int lines[15], h, w;
bool matched[15];
int dvec[15], uvec[15];

inline bool match() {
    for (int i = 0, j, k, _ = w >> 1; i < _; ++i)
        for (j = 0; j < w; ++j)
            if (!matched[j])
                for (k = 0; k < w; ++k)
                    if (k != j && uvec[k] == dvec[j])
                        matched[j] = matched[k] = true;
    bool ok = true;
    for (int i = 0; i < w && ok; ++i)
        if (!matched[i]) ok = false;
    for (int i = 0; i < w; ++i) matched[i] = false;
    return ok;
}

void check() {
    for (int i = 0, j, hsh; i < w; ++i) {
        hsh = 0;
        for (j = 0; j < h; ++j)
            (hsh *= HASH) += str[lines[j]][i];
        dvec[i] = hsh;
        hsh = 0;
        for (j = h - 1; j >= 0; --j)
            (hsh *= HASH) += str[lines[j]][i];
        uvec[i] = hsh;
    }
    if (w & 1) {
        for (int i = 0; i < w; ++i)
            if (dvec[i] == uvec[i]) {
                matched[i] = true;
                if (match())
                    exit(int(puts("YES")));
                matched[i] = false;
            }
    } else if (match()) {
        exit(int(puts("YES")));
    }
}

bool setted[15];

void getLines(int msk, int cur, int smallest) {
    if (cur == (h >> 1)) return check();
    while (setted[smallest] || (msk >> smallest & 1))
        ++smallest;
    lines[cur] = smallest;
    for (int i = smallest + 1; i < h; ++i)
        if (!setted[i] && (msk >> i & 1)) {
            lines[h - 1 - cur] = i;
            setted[i] = setted[smallest] = true;
            getLines(msk, cur + 1, smallest + 1);
            setted[i] = setted[smallest] = false;
        }
}

void dfs(int cur, int cnt, int msk) {
    if (cnt == (h >> 1)) return getLines(msk, 0, 0);
    if (cur == h) return ;
    if (setted[cur]) return dfs(cur + 1, cnt, msk);
    dfs(cur + 1, cnt + 1, msk | 1 << cur);
    dfs(cur + 1, cnt, msk);
}

int main() {
    scanf("%d%d", &h, &w);
    for (int i = 0; i < h; ++i) scanf("%s", str[i]);
    if (h & 1) {
        for (int i = 0; i < h; ++i) {
            setted[i] = true;
            lines[h >> 1] = i;
            dfs(0, 0, 0);
            setted[i] = false;
        }
    } else {
        dfs(0, 0, 0);
    }
    puts("NO");
    return 0;
}

