bool rev(char l[], char t[]){
  REP(i,w){
    if(l[i] != t[w-1-i]){
      return false;
    }
  }
  return true;
}

bool ok(vector<pii> p){
  char t[12][13];
  c++;
  REP(i,p.size()){
    int f = p[i].first;
    int b = p[i].second;
    REP(j,h){
      t[j][i] = s[j][f];
      t[j][w-1-i] = s[j][b];
    }
  }
  bool used[12];
  REP(i,h) used[i] = false;
  int cnt = 0;
  REP(i,h){
    FOR(j,i+1,h){
      if(used[i]) break;
      if(rev(t[i],t[j])){
        used[i] = true;
        used[j] = true;
        cnt += 2;
      }
    }
  }
  if(h-cnt>1) return false;
  if(h-cnt==0) return true;
  REP(i,h){
    if(used[i]) continue;
    return rev(t[i],t[i]);
  }
}

bool dfs(vector<bool> used, vector<pii> p){
  if(p.size()*2 == w){
    return ok(p);
  }
  if(p.size()*2+1==w){
    vector<pii> tmp = p;
    REP(i,w){
      if(used[i]) continue;
      tmp.push_back(pii(i,i));
      break;
    }
    return ok(tmp);
  }
  REP(i,w){
    if(used[i]) continue;
    vector<bool> tmp_u = used;
    tmp_u[i] = true;
    FOR(j,i+1,w){
      if(tmp_u[j]) continue;
      vector<pii> tmp = p;
      vector<bool> tmp_uu = tmp_u;
      tmp_uu[j] = true;
      tmp.push_back(pii(i,j));
      if(dfs(tmp_uu,tmp)){
        return true;
      }
    }
    if(w >= 8)break;
  }
  return false;
}


