int X[12];

char D[12][13];
int N, M;
int ans = 0;

void solve(){
//	for(int i = 0; i < M; i++) printf("%d ", X[i]); printf("\n");
	int dp[1<<12] = {};
	int pos[12][12] = {};
	for(int i = 0; i < N; i++){
		for(int j = 0; j < N; j++){
			pos[i][j] = 1;
			for(int k = 0; k < M; k++){
				if(D[i][k] != D[j][X[k]]) pos[i][j] = 0;
			}
//			printf("%d ", pos[i][j]);
		}
//		printf("\n");
	}
	dp[0] = 1;
	if(N%2 == 1){
		for(int i = 0; i < N; i++){
			if(pos[i][i]) dp[1<<i] = 1;
		}
	}
	for(int i = 0; i+1 < 1<<N; i++){
		if(dp[i] == 0) continue;
		int v = 0;
		for(v = 0; i&1<<v; v++);
		for(int u = 0; u < N; u++){
			if(u == v || (1<<u&i) || !pos[u][v]) continue;
			dp[1<<u | 1<<v | i] = 1;
		}
	}
	int mx = (1<<N) - 1;
	if(dp[mx]) ans = 1;
}

void dfs(int x, int ch){
	if(x == M) return solve();
	if(X[x] != -1){
		dfs(x+1, ch);
		return;
	}
	if(ch){ X[x] = x; dfs(x+1, 0); X[x] = -1; }
	for(int i = x+1; i < M; i++){
		if(X[i] != -1) continue;
		X[x] = i; X[i] = x;
		dfs(x+1, ch);
		X[x] = X[i] = -1;
	}
}

int main()
{
	scanf("%d%d", &N, &M);
	for(int i = 0; i < N; i++) scanf("%s", D[i]);
	for(int i = 0; i < M; i++) X[i] = -1;
	dfs(0, M%2);
	printf("%s\n", ans?"YES":"NO");
}

