bool dfs(int S, vector<pii> &s) {
  //dump(S,s);

  if (bitcount(S) <= 1) {
    vector<string> a(H);
    rep(i, 0, s.size()) {
      a[i] = v[s[i].first];
      a[H - 1 - i] = v[s[i].second];
    }
    if (H & 1) {
      int c = 0;
      while (S) {
        S >>= 1;
        c++;
      }
      c--;

      a[H / 2] = v[c];
    }
    //dump(a);
    string dummy;
    loop(H) { dummy += "#"; }
    vector<string> b(W, dummy);
    // b[i][j]=a[i][j];
    rep(i, 0, W) rep(j, 0, H) { b[i][j] = a[j][i]; }
    //dump(b);
    int U = (1 << W) - 1;
    rep(i, 0, W) {
      rep(j, i + 1, W) {
        string t = b[j];
        reverse(all(t));
        //dump(U,b[i],b[j],t);
        if ((U >> i & 1) & (U >> j & 1) and t == b[i]) {
          U ^= (1 << i);
          U ^= (1 << j);
        }
      }
    }
    //dump(U);

    if (W & 1) {
      int c = 0;
      int X = U;
      while (X) {
        X >>= 1;
        c++;
      }
      c--;
      string t = b[c];
      reverse(all(t));
      if (t == b[c]) {
        U ^= (1 << c);
      }
    }

    return U == 0;
  }

  rep(i, 0, H) rep(j, i + 1, H) {
    if ((S >> i & 1) & (S >> j & 1)) {
      s.push_back(pii(i, j));
      if (dfs(S ^ (1 << i) ^ (1 << j), s))
        return true;
      s.pop_back();
    }
  }
  return false;
}

