int valid(vector<string> s1,vector<string> s2){
  typedef pair<string,int> P;
  vector<P> S1,S2;
  for(int i=0;i<h;i++) S1.push_back(P(s1[i],i+1));
  for(int i=0;i<h;i++) S2.push_back(P(s2[i],-i-1));
  sort(S1.begin(),S1.end());
  sort(S2.begin(),S2.end());
  int cnt = 0;
  for(int i=0;i<h;i++) 
    if(S1[i].first != S2[i].first) return 0;
    else if(S1[i].second == -S2[i].second) cnt++;

  if(cnt > 1) return 0;
  if(h%2==0 && cnt) return 0;
  return 1;
}

