                    mid = j;
                    u[j] = j;
                    continue;
                }
                que1.push_back(j); que2.push_back(used[j]);
                u[used[j]] = 1, u[j] = 1;
            }
        }
        vector<vector<char>> f(h, vector<char>(w, '?'));
