            }
            ++ cur;
        }
        if(mid != -1) {
            rep(k, w) {
                f[cur][k] = s[mid][k];
            }
            ++ cur;
        }
        while(que2.size()) {
            int j = que2.back(); que2.pop_back();
            rep(k, w) {
                f[cur][k] = s[j][k];
            }
            ++ cur;
        }
        // rep(i, h) {
        //     rep(j, w) {
        //         cerr << f[i][j];
        //     }
        //     cerr << endl;
        // }
