        bool check = 1;
        unordered_map<string, int> mp;
        rep(j, w) {
            string res = "";
            rep(k, h) res += f[k][j];
            mp[res] ++;
        }
        int mi = 0;
        for(auto x: mp) {
            string tmp = x.fr; int co = x.sc;
            if(co == -1) continue;
            string tmp1 = tmp; reverse(all(tmp1));
            if(tmp == tmp1) {
                if(co % 2 == 1) ++ mi;
            } else {
                if(abs(co - mp[tmp1]) == 1) {
                    ++ mi;
                    mp[tmp1] = -1;
                } else if(co == mp[tmp1]) {
                    mp[tmp1] = -1;
                    continue;
                }
                else {
                    check = 0;
                }
            }
        }
        if(w % 2 == 1) {
            if(mi == 1 && check) check = 1;
            else check = 0;
        } else {
            if(mi == 0 && check) check = 1;
            else check = 0;
        }
        //
        if(check) {
            cout << "YES" << endl;
            exit(0);
        }
        return;
    }
    if(used[i] != -1) {
        dfs(used, i + 1, ok);
        return;
    }
    if(ok) {
        used[i] = i;
        ok = 0;
        dfs(used, i + 1, ok);
        ok = 1;
        used[i] = -1;
    }
    for(int j = i + 1; j < h; ++ j) {
        if(used[j] != -1) continue;
        used[i] = j, used[j] = i;
        dfs(used, i + 1, ok);
        used[i] = -1, used[j] = -1;
    }
}

