bool do_check_sym(int sel_rows, int sel_rows2, int center_row, int sel_cols, int sel_cols2, int center_col = -1) {

    vector< pair<ll, int> > cols, cols2, rows, rows2;

    int *keys = col_keys[sel_rows];
    int *keys2 = col_keys[sel_rows2];
    int *sc = 0;
    if (center_row != -1) {
        sc = a[center_row];
    }
    rep(j, 0, w) {
        int p2j = 1 << j;
        ll k = sc ? sc[j] : 0;
        if (p2j & sel_cols) {
            k += ((keys[j] << 12) + keys2[j]) << 5;
            cols.push_back(make_pair(k, j));
        } else if (p2j & sel_cols2) {
            k += ((keys2[j] << 12) + keys[j]) << 5;
            cols2.push_back(make_pair(k, j));
        }
    }
    sort(cols.begin(), cols.end());
    sort(cols2.begin(), cols2.end());
    rep(j, 0, w2) {
        if (cols[j].first != cols2[j].first) {
            return false;
        }
    }
    if (center_row != -1) {
        sc = a[center_row];
        rep(j, 0, w2) {
            if (sc[cols[j].second] != sc[cols2[j].second]) {
                return false;
            }
        }
    }

    keys = row_keys[sel_cols];
    keys2 = row_keys[sel_cols2];
    sc = 0;
    if (center_col != -1) {
        sc = ta[center_col];
    }
    rep(i, 0, h) {
