        ll k = sc ? sc[i] : 0;
        if (p2i & sel_rows) {
            k += ((keys[i] << 12) + keys2[i]) << 5;
            rows.push_back(make_pair(k, i));
        } else if (p2i & sel_rows2) {
            k += ((keys2[i] << 12) + keys[i]) << 5;
            rows2.push_back(make_pair(k, i));
        }
    }
    sort(rows.begin(), rows.end());
    sort(rows2.begin(), rows2.end());
    rep(i, 0, h2) {
        if (rows[i].first != rows2[i].first) {
            return false;
        }
    }
