bool check_sym(int sel_rows, int sel_rows2, int center_row = -1) {

    int t0 = (1 << w) - 1;
    if (w % 2) {
        rep(j, 0, w) {
            int p2j = 1 << j;
            int t = t0 - p2j;
            for(auto it = row_keys.begin(); it != row_keys.end(); ++it) {
                int sel_cols = it->first;
                if (sel_cols & p2j) {
                    continue;
                }
                int sel_cols2 = t - sel_cols;
                if (sel_cols < sel_cols2) {
                    if (do_check_sym(sel_rows, sel_rows2, center_row, sel_cols, sel_cols2, j)) {
                        return true;
                    }
                }
            }
        }
        return false;
    } else {
        for(auto it = row_keys.begin(); it != row_keys.end(); ++it) {
            int sel_cols = it->first;
            int sel_cols2 = t0 - sel_cols;
            if (sel_cols < sel_cols2) {
                if (do_check_sym(sel_rows, sel_rows2, center_row, sel_cols, sel_cols2)) {
                    return true;
                }
            }
        }
        return false;
    }
}

bool solve() {

    h2 = h / 2;
    w2 = w / 2;

    if (h == 1) {
        return check_sym1(w, a[0]);
    }
    if (w == 1) {
        int b[12];
        rep(i, 0, h) {
            b[i] = a[i][0];
        }
        return check_sym1(h, b);
    }

    rep(i, 0, h) {
        int *ai = a[i];
        rep(j, 0, w) {
            ta[j][i] = ai[j];
        }
    }

    calc_row_keys();
    calc_col_keys();

    int t0 = (1 << h) - 1;
    if (h & 1) {
        rep(i, 0, h) {
            int p2i = 1 << i;
            int t = t0 - p2i;
            for(auto it = col_keys.begin(); it != col_keys.end(); ++it) {
                int sel_rows = it->first;
                if (sel_rows & p2i) {
                    continue;
                }
                int sel_rows2 = t - sel_rows;
                if (sel_rows < sel_rows2) {
                    if (check_sym(sel_rows, sel_rows2, i)) {
                        return true;
                    }
                }
            }
        }
    } else {
        for(auto it = col_keys.begin(); it != col_keys.end(); ++it) {
            int sel_rows = it->first;
            int sel_rows2 = t0 - sel_rows;
            if (sel_rows < sel_rows2) {
                if (check_sym(sel_rows, sel_rows2)) {
                    return true;
                }
            }
        }
    }

    return false;
}

