inline void swapR(VT<string> &S, int a, int b) {
    if (a == b) return;
    swap(S[a], S[b]);
}
inline void swapC(VT<string> &S, int a, int b) {
    if (a == b) return;
    REP(i, S.size()) {
        swap(S[i][a], S[i][b]);
    }
}
inline bool valid(const VT<string> &S) {
    REP(i, S.size() / 2) {
        REP(j, S[0].size() / 2) {
            if (S[i][j] != S[S.size() - i - 1][S[0].size() - j - 1]) {
                return false;
            }
        }
    }
    return true;
}


