using namespace std;

int pair_h[12], pair_w[12];
int H, W;
string S[12];
bool solo_h, solo_w;

bool able_w(int w){
    if(w == W){
        return true;
    }else if(pair_w[w] != -1){
        return able_w(w + 1);
    }else{
        bool ret = false;
        for(int i = w + 1; i < W; i++){
            if(pair_w[i] != -1){
                continue;
            }

            bool is_pair = true;
            for(int j = 0; j < H; j++){
                if(S[j][w] != S[pair_h[j]][i]){
                    is_pair = false;
                }
            }
            if(is_pair){
                pair_w[w] = i;
                pair_w[i] = w;

                ret = ret || able_w(w + 1);

                pair_w[i] = pair_w[w] = -1;
            }
        }
        if(W % 2 != 0 && !solo_w){
            bool is_pair = true;
            for(int j = 0; j < H; j++){
                if(S[j][w] != S[pair_h[j]][w]){
                    is_pair = false;
                }
            }
            if(is_pair){
                solo_w = true;
                pair_w[w] = w;
                ret = ret || able_w(w+1);
                pair_w[w] = -1;
                solo_w = false;
            }
        }
        return ret;
    }
}

bool search_h(int h){
    if(h == H){
        return able_w(0);
    }else if(pair_h[h] != -1){
        return search_h(h+1);
    }else{
        bool ret = false;

        for(int i = h + 1; i < H; i++){
            if(pair_h[i] != -1){
                continue;
            }

            pair_h[h] = i;
            pair_h[i] = h;

            ret = ret || search_h(h + 1);

            pair_h[h] = -1;
            pair_h[i] = -1;
        }

        if(H % 2 != 0 && !solo_h){
            pair_h[h] = h;
            solo_h = true;
            ret = ret || search_h(h + 1);
            pair_h[h] = -1;
            solo_h=false;
        }
        return ret;
    }
}



bool able_to_symmetrize(){
    return search_h(0);
}

int main(){
    cin >> H >> W;
    for(int h = 0; h < H; h++){
        cin >> S[h];
    }

    for(int i = 0; i < 12; i++){
        pair_h[i] = -1;
        pair_w[i] = -1;
    }

    cout << (able_to_symmetrize() ? "YES" : "NO" ) << endl;
}

