int H, W;
std::string S[20];

std::vector<std::vector<int>> all_pairs(std::vector<int> org) {
    assert(org.size() % 2 == 0);
    std::vector<std::vector<int>> ret;
    if (org.size() == 0) {
        return ret;
    }

    do {
        bool use = true;
        for (int i = 2; i < org.size(); i += 2) {
            if (org[i] > org[i+1]) {
                use = false;
                break;
            }
        }
        if (use) {
            for (int i = 2; i < org.size() - 2; i += 2) {
                if (org[i] > org[i+2]) {
                    use = false;
                    break;
                }
            }
        }
        if (use) {
            ret.push_back(org);
        }
    } while (std::next_permutation(org.begin() + 1, org.end()));

    return ret;
}

std::vector<long long> all_combi(const int n, const int r) {
    std::vector<long long> ret;
    for (long long i = 0; i < (1 << n); i++) {
        std::bitset<64> bs(i);
        if (bs.count() == r) {
            ret.push_back(i);
        }
    }
    return ret;
}

bool check(int combi, std::vector<int> pair, int center_h, int center_w) {
    std::bitset<64> bs(combi);

    std::vector<std::string> A, B;

    for (int i = 0; i < H; i++) {
        std::string tmp;
        tmp.resize(W);
        if (center_w != -1) {
            tmp[W/2+1] = S[i][center_w];
        }
        for (int j = 0; j < W/2; j++) {
            tmp[j] = S[i][pair[j*2]];
            tmp[W-1-j] = S[i][pair[j*2+1]];
        }
        if (i == center_h) {
            for (int j = 0; j < W/2; j++) {
                if (tmp[j] != tmp[W-1-j]) {
                    return false;
                }
            }
        } else if (bs.test(i)) {
            A.push_back(tmp);
        } else {
            B.push_back(tmp);
        }
    }
    assert(A.size() == B.size());
    std::map<std::string, int> mpA, mpB;

    for (int i = 0; i < A.size(); i++) {
        std::reverse(A[i].begin(), A[i].end());
        mpA[A[i]]++;
        mpB[B[i]]++;
    }

    for (auto itr = mpA.begin(); itr != mpA.end(); ++itr) {
        if (mpB.find(itr->first) == mpB.end() || mpB[itr->first] != itr->second) {
            return false;
        }
    }
    return true;
}

struct Search_Elem {
    int center_h;
    int center_w;
    std::vector<long long> combi;
    std::vector<std::vector<int>> pairs;
};

Search_Elem get_search_elem(int ch, int cw) {
    Search_Elem se;
    se.center_h = ch;
    se.center_w = cw;

    if (H % 2 == 0) {
        se.combi = all_combi(H, H/2);
    } else {
        auto tmp = all_combi(H, H/2);
        for (auto c : tmp) {
            if (!std::bitset<64>(c).test(ch)) {
                se.combi.push_back(c);
            }
        }
    }

    std::vector<int> org;
    for (int i = 0; i < W; i++) {
        if (i != cw) {
            org.push_back(i);
        }
    }
    se.pairs = all_pairs(org);

    return se;
}

int main(int argc, char **argv) {
    std::cin >> H >> W;

    for (int i = 0; i < H; i++) {
        std::cin >> S[i];
    }

    std::vector<Search_Elem> search;

    if (H % 2 == 0 && W % 2 == 0) {
        search.push_back(get_search_elem(-1, -1));
    } else if (H % 2 == 0) {
        for (int i = 0; i < W; i++) {
            search.push_back(get_search_elem(-1, i));
        }
    } else if (W % 2 == 0) {
        for (int i = 0; i < H; i++) {
            search.push_back(get_search_elem(i, -1));
        }
    } else {
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                search.push_back(get_search_elem(i, j));
            }
        }
    }

    for (Search_Elem s : search) {
        for (long long c : s.combi) {
            for (auto p : s.pairs) {
                if (check(c, p, s.center_h, s.center_w)) {
                    std::cout << "YES" << std::endl;
                    return 0;
                }
            }
        }
    }

    std::cout << "NO" << std::endl;
    return 0;

}

