ll H,W;
bool check(vector<vector<char>>& masu){
    vector<int> filled(W+1);
    bool center = false;
    for(int i = 1; i <= W;i++){
        if(filled[i]) continue;
        vector<char> T;
        for(ll j = H; j >= 1;j--){
            T.push_back(masu[j][i]);
        }
        bool update = false;
        for(int j = i + 1; j <= W;j++){
            if(filled[j]) continue;
            bool ok = true;
            for(int k = 1; k <= H;k++){
                if(T[k-1] != masu[k][j]) ok = false;
            }
            if(ok){
                filled[i] = filled[j] = 1;
                update = true;
                break;
            }
        }
        if(update) continue;
        if(W%2 == 0) return false;
        if(center) return false;
        for(int k = 0; k <= H/2; k++){
            if(T[k] != T[H-k-1]) return false;
        }
        center = true;
    }
    return true;
}
bool rec(vector<int>&flag,vector<vector<char>>& masu){
    ll S = accumulate(flag.begin(),flag.end(),0);
    if(S >= H){
        return check(masu);
    }else{
        if(S == 0 && H%2 == 1){
            for(int i = 1; i <= H;i++){
                flag[i] = 1;
                if(rec(flag,masu))return true;;
                flag[i] = 0;
            }
        }else{
            for(int i = 1; i<= H;i++){
                if(flag[i]) continue;
                for(int j = i+1; j <= H;j++){
                    if(flag[j]) continue;
                    flag[i] = flag[j] = 1;
                    if(rec(flag,masu)) return true;
                    swap(masu[i],masu[j]);
                    if(rec(flag,masu)) return true;
                    swap(masu[i],masu[j]);
                    flag[i] = flag[j] = 0;
                }
                break;
            }
        }
    }
    return false;
}
string solve(){
    cin >> H >> W;
    vector<vector<char>> masu(H+1,vector<char>(W+1));
    for(int i = 1; i <= H;i++) for(int j = 1; j <= W; j++) cin >> masu[i][j];
    vector<int> flag(H+1);
    if(rec(flag,masu)) return "YES";
    return "NO";
}
int main(void) {
    cin.tie(0); ios_base::sync_with_stdio(false);
    cout << solve() << endl;
    return 0;
}

