        vs.push_back(str2);
      }
      sort(all(vs));
      for(int i=0; i+1<vs.size(); i+=2) {
        if (vs[i] != vs[i+1]) {
          return;
        }
      }
      if (h%2 != 0 && !flag) return;
      ret = true;
    }

    void dfs(vector<int>& v, int maxDepth) {
      if (ret) return;
      if (v.size() == maxDepth) {
        check(v);
        return;
      }

      for(int i=0; i<w; i++) {
        if (used[i]) continue;
        v.push_back(i);
        used[i] = true;
        dfs(v, maxDepth);
        used[i] = false;
        v.pop_back();
      }
    }

    void solve(istream& cin, ostream& cout) {
      SPEED;
      ret = false;
      cin >> h >> w;
      s.resize(h);
      rep(i, h) {
        cin >> s[i];
      }
      used.resize(w);
      vector<int> v;
      dfs(v, (w+1)/2);
      cout << (ret ? "YES" : "NO") << endl;
    }
};

signed main() {
  ESymmetricGrid solver;
  std::istream& in(std::cin);
  std::ostream& out(std::cout);
  solver.solve(in, out);
  return 0;
}

