			if( !( row[mp_row[h+1-u]] == row[i] ) )
				continue;

		visited_row[i] = true;
		mp_row[u] = i;

		if( dfs_row( u+1 ) )
			return true;
		visited_row[i] = false; 
	}
	return false;
}

