                    if (!wid[j]) {
                        bool bb = true;
                        for (int k = 0; k < H; k++) {
                            if (nowmap[k][j] != nowmap[H - 1 - k][fir]) {
                                bb = false;
                            }
                        }
                        if (bb) {
                            b = true;
                            wid[j] = true;
                            break;
                        }
                    }
                }
                if (!b) {
                    bool bb = true;
                    for (int j = 0; j < H; j++) {
                        if (nowmap[j][fir] != nowmap[H - 1 - j][fir]) {
                            bb = false;
                            break;
                        }
                    }
                    if (!bb || center) {
                        comp = false;
                        break;
                    } else {
                        center = true;
                    }
                }
                if (b) {
                    rem -= 2;
                } else {
                    rem--;
                }
            } else if (rem == 1) {
                int fir;
                for (int j = 0; j < W; j++) {
                    if (!wid[j]) {
                        fir = j;
                        break;
                    }
                }
                bool bb = true;
                for (int j = 0; j < H; j++) {
                    if (nowmap[j][fir] != nowmap[H - 1 - j][fir]) {
                        bb = false;
                        break;
                    }
                }
                if (!bb || center) {
                    comp = false;
                    break;
                } else {
                    center = true;
                    break;
                }
            } else {
                break;
            }
        }
        if (comp) {
            ok = true;
            break;
        }
    }
    if (ok) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }
}

