static bool solve2() {
	char B[16][16];
	int m = W / 2;
	for (int mm = 0; mm < (1 << W); mm++) {
		if (__builtin_popcount(mm) != m)
			continue;
		int bc[16];
		int b = 0, c = 0;
		for (int i = 0; i < W; i++)
			if (mm & (1 << i)) {
				fillcol(B, b++, i);
			} else {
				bc[c++] = i;
			}
		do {
			for (int i = 0; i < H; i++)
				for (int j = 0; j < c; j++)
					B[i][m + j] = A[i][bc[j]];
			if (good(B))
				return true;
		} while(next_permutation(&bc[0], &bc[c]));

	}

	return false;
}

