				if(k+1 == W) b[i] = b[j] = 1;
			}
			if(b[j]) break;
		}
		if(!b[i]){
			if(c){
				rep(k,W) if(S[i][p[k]] != S[i][p[W-1-k]]) return 0;
				c = 0;
			} else return 0;
		}
	}
	return 1;
}

bool solve(int a , int n , bool b) {
    if (a == W) return check();
    if (q[a]) return solve(a+1,n,b);
    if (b) {
        p[W/2] = a, q[a] = 1;
        if ( solve(a+1,n,0) ) return 1;
        q[a] = 0;
    }
    for(int i = a+1; i < W; ++i) {
        if (!q[i]) {
            p[n] = a, p[W-1-n] = i;
            q[a] = q[i] = 1;
            if (solve(a+1,n+1,b)) return 1;
            q[a] = q[i] = 0;      
        }
    }
    return 0;
}

int main(){
	cin >> H >> W;
	rep(i,H) cin >> S[i];
	cout << (solve(0,0,W&1)?"YES":"NO") << endl;
	return 0;
}

