int H, W;

bool judge(vector<P>& v, vector<string>& s) {
    vector<string> s2(s);
    for (int i = 0; i < (H + 1) / 2; i++) {
        s2[i] = s[v[i].first];
        s2[H - 1 - i] = s[v[i].second];
    }

    vector<int> used(W, false);
    int ok = W % 2;
    for (int i = 0; i < W; i++) {
        if (used[i]) continue;
        for (int j = i + 1; j < W; j++) {
            if (used[j]) continue;
            bool flag = true;
            for (int k = 0; k < H; k++) {
                if (s2[k][i] != s2[H - 1 - k][j]) {
                    flag = false;
                    break;
                }
            }
            if (flag) {
                used[i] = true;
                used[j] = true;
                break;
            }
        }
        if (!used[i]) {
            if (ok) {
                ok = false;
                used[i] = true;
            } else {
                return false;
            }
        }
    } 
    return true;
}

bool solve(vector<int>& used, vector<P>& v, vector<string>& s) {
    int cnt = 0;
    for (int x : used) {
        cnt += !x;
    }

    if (cnt == 0) {
        return judge(v, s);
    } else {
        for (int i = 0; i < H; i++) {
            if (used[i]) continue;
            used[i] = true;
            if (cnt == 1) {
                v.emplace_back(i, i);
                if (solve(used, v, s)) return true;
                used[i] = false;
                break;
            } else {
                for (int j = i + 1; j < H; j++) {
                    if (used[j]) continue;
                    used[j] = true;
                    v.emplace_back(i, j);
                    if (solve(used, v, s)) return true;
                    used[j] = false;
                    v.pop_back();
                }
            }
            used[i] = false;
        }
    }
    return false;
}

