int32 dp[1 << 12];

bool dfs2(int32 now){
	if(~dp[now]) return now;
	if(now == (1<<W)-1) return dp[now] = 1;
	if(__builtin_popcount(now) == W-1){
		REP(i, W){
			if(!(now >> i & 1)){
				if(pack[i][i]) return dp[now] = 1;
				return dp[now] = 0;
			}
		}
	}
	dp[now] = 0;
	REP(i, W){
		FOR(j, i+1, W){
			if(!(now >> i & 1) && !(now >> j & 1)){
				if(pack[i][j]) dp[now] |= dfs2(now|(1<<i)|(1<<j));
			}
		}
	}
	return dp[now];
}

bool ok(){
	pack = vector<vector<bool>>(W, vector<bool>(W, 1));
	REP(k, pa.size()){
