	REP(i, W){
		REP(j, W){
			cout << pack[i][j] << " ";
		}
		cout << endl;
	}
	*/

	memset(dp, -1, sizeof dp);
	return dfs2(0);
}

bool dfs(int32 d, int32 cnt, int32 rest, bool used){
	if((rest >> d & 1) && cnt < H) return dfs(d+1, cnt, rest, used);
	if(cnt == H || (H%2 && cnt == H-(1-used))){
		if(H%2 && !used) pa.push_back(PII(d, d));
		bool ret = ok();
		if(H%2 && !used) pa.pop_back();
		return ret;
	}
	FOR(i, d+1, H){
		if(rest >> i & 1) continue;
		pa.push_back(PII(d, i));
		bool ret = dfs(d+1, cnt+2, rest|(1<<i)|(1<<d), used);
		pa.pop_back();
		if(ret) return ret;
	}
	if(H%2 && !used){
		pa.push_back(PII(d, d));
		bool ret = dfs(d+1, cnt+1, rest|(1<<d), 1);
		pa.pop_back();
		if(ret) return ret;
	}
	return 0;
}

