bool isPlain(string a) {
  string b = a;
  reverse(all(b));
  return a == b;
}

bool check() {
  vi v;
  rep(i,0,pairs.size()) v.pb(pairs[i].FF);
  for(int i = pairs.size() - 1; i >= 0; i--) if(pairs[i].FF != pairs[i].SS) {
    v.pb(pairs[i].SS);
  }
  assert(v.size() == h);
  vector<string > st;
  rep(j,0,w) {
    string tmp;
    for(int i = h - 1; i >= 0; i--) {
      tmp += s[v[i]][j];
    }
    bool ok = false;
    rep(i,0,st.size()) if(st[i] == tmp) {
      swap(st[i], st.back());
      st.pop_back();
      ok = true;
      break;
    }
    if(ok) continue;

    tmp = "";
    for(int i = 0; i < h; i++) {
      tmp += s[v[i]][j];
    }
    st.pb(tmp);
  }
  if(st.size() > 1) {
    return false;
  }
  if(st.size() == 1) {
    return isPlain(st.back());
  }
  return true;
}

void solve(int mask) {
  if(ans) {
    return;
  }
  if(mask == 0) {
    if(check()) {
      ans = true;
    }
    return;
  }
  if(__builtin_popcount(mask) == 1) {
    rep(i,0,h) if(bit(mask, i)) {
      pairs.pb(mp(i, i));
    }
    solve(0);
    pairs.pop_back();
    return;
  }

  rep(i,0,h) if(bit(mask, i)) {
    rep(j,i+1,h) if(bit(mask, j)) {
      pairs.pb(mp(i, j));
      solve(mask ^ (1 << i) ^ (1 << j));
      pairs.pop_back();
    }
    break;
  }
}

