typedef vector<char> vc;

pair<vc, vc>  getCrossChar(const vector<vc>& s, int i, int j, bool f){
	vc x, y;
	rep(k,s[i].size()){
		x.emplace_back(s[i][k]);
	}

	rep(k,s.size()){
		if(i == k) continue;
		y.emplace_back(s[k][j]);
	}
	sort(all(x));
	if(not f)sort(all(y));

	//cout << x << y << endl;
	return make_pair(x,y);
}

bool check(vector<vc>& c){
	vector<vc> f, s;
	rep(i,c.size() / 2){
		sort(all(c[i]));
		f.emplace_back(c[i]);
	}
	range(i,c.size() / 2, c.size()){
		sort(all(c[i]));
		s.emplace_back(c[i]);
	}
	sort(all(f));
	sort(all(s));

	rep(i,f.size()){
		rep(j,f[i].size()){
			if(f[i][j] != s[i][j]) return false;
		}
	}
	return true;
}

bool dfs(const vector<vc>& s){
	int h = s.size();
	int w = s[0].size();
	//cout << h << ' ' << w << endl; for(auto i : s){ for(auto j : i){ cout << j; } cout << endl; }

	map<vc, vector<vc>> m;
	rep(i,h){
		rep(j,w){
			pair<vc, vc> p = getCrossChar(s, i, j, h % 2 == 1 and h / 2 == i);
			m[p.first].emplace_back(p.second);
		}
	}

	//show(m.size())
	if((h + 1) / 2 != m.size()) {
		//cout << "kumiawase" << endl;
		return false;
	}

	if(h % 2 == 1){
		vector<vc> nxt;
		for(auto i : m){
			if(i.second.size() == w * 2){
				if(not check(i.second)) {
					//cout << "kisuu chekcfalse " << endl;
					return false;
				}
			}else{
				nxt = i.second;
			}
		}

		return dfs(nxt);
	}else{
		for(auto i : m){
			if(not check(i.second)) {
				//cout << "guusuu checkfalse" << endl;
				return false;
			}
		}
		return true;
	}
}

