			if(i & (1 << (j - 1))) b[i][++b[i][0]] = j;
		}
		//cout<<endl;
		//cout<<i<<' '<<b[i][0]<<endl;
	}
	for(int i = 1; i < (1 << M); ++i) siz[i] = siz[i >> 1] + (i & 1);
