#include<bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef pair<int,int> P;

int W,H;
char F[15][15];

bool eq(int a,int b){
  vector<char> c1,c2;
  for(int i=0;i<W;i++){
    c1.emplace_back( F[a][i] );
    c2.emplace_back( F[b][i] );
  }
  sort( c1.begin(), c1.end() );
  sort( c2.begin(), c2.end() );
  for(int i=0;i<W;i++)
    if( c1[i] != c2[i] ) return false;
  return true;
}

void rotate(){
  char tmp[15][15];
  for(int i=0;i<H;i++)
    for(int j=0;j<W;j++)
      tmp[W-j-1][i] = F[i][j];
  swap(H,W);
  for(int i=0;i<H;i++)
    for(int j=0;j<W;j++)
      F[i][j] = tmp[i][j];
}

int hcheck(){
  bool f[15] = {};
  for(int i=1;i<H;i++){
    if( f[i] ) continue;
    for(int j=0;j<i;j++){
      if( f[j] ) continue;
      if( eq(i,j) ) {
        f[i] = f[j] = true; break;
      }
    }
  }
  int cnt = 0;
  for(int i=0;i<H;i++) {
    if( !f[i] ) cnt++;
  }
  if(!(H&1)&&cnt!=0) return false;
  if((H&1)&&cnt!=1) return false;
  return true;
}

bool solve(){
  if(!hcheck()) return false;
  rotate();
  return hcheck();  
}

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  cin >> H >> W;
  for(int i=0;i<H;i++)
    for(int j=0;j<W;j++)
      cin >> F[i][j];
  if( solve() ) cout << "YES" << endl;
  else cout << "NO" << endl;
}

#include <bits/stdc++.h>
using namespace std;

int h, w;
string s[15];
int pos[15];
int rpos[15];
int cnt;

bool matching(int i, int j) {
  for (int hi = 0; hi < h; hi++) {
    if (s[rpos[hi]][i] != s[rpos[h - 1 - hi]][j]) {
      return false;
    }
  }
  return true;
}

bool check() {
  vector<bool> matched(12, false);
  bool single = w % 2 == 1 ? false : true;
  for (int wi = 0; wi < w; wi++) {
    if (matched[wi]) continue;
    bool m = false;
    for (int wj = wi + 1; wj < w; wj++) {
      if (matching(wi, wj)) {
        m = true;
        matched[wj] = true;
        break;
      }
    }
    if (!m) {
      if (single) return false;
      for (int hi = 0; hi < h / 2; hi++) {
        if (s[rpos[hi]][wi] != s[rpos[h - 1 - hi]][wi]) return false;
      }
      single = true;
    }
  }
  return true;
}

bool traverse(int x) {
  if (x * 2 == h) {
    return check();
  }
  for (int hi = 0; hi < h; hi++) {
    if (pos[hi] == -1) {
      pos[hi] = x;
      rpos[x] = hi;
      if (x * 2 + 1 == h) {
        bool result = check();
        pos[hi] = -1;
        return result;
      } else {
        for (int hj = hi + 1; hj < h; hj++) {
          if (pos[hj] == -1) {
            pos[hj] = h - 1 - x;
            rpos[h - 1 - x] = hj;
            bool result = traverse(x + 1);
            pos[hj] = -1;
            if (result) {
              pos[hi] = -1;
              return true;
            }
          }
        }
        pos[hi] = -1;
        return false;
      }
    }
  }
}

int main() {
  cin >> h >> w;
  for (int hi = 0; hi < h; hi++) {
    cin >> s[hi];
  }
  memset(pos, -1, sizeof(pos));
  bool answer = traverse(0);
  if (h % 2 == 1) {
    for (int hi = 0; hi < h - 1; hi++) {
      swap(s[hi], s[h - 1]);
      answer |= traverse(0);
      if (answer) break;
    }
  }
  cout << (answer ? "YES" : "NO") << endl;
  return 0;
}

