int H, W;

int perm[12];
string s[12];

bool same(const string &s, string t) {
    reverse(t.begin(), t.end());
    return s == t;
}

string rev(string s) {
    reverse(s.begin(), s.end());
    return s;
}

void check() {
    string ss[H];
    for (int i = 0; i < H; i++) ss[i] = s[i];
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            ss[i][j] = s[i][perm[j]];
        }
    }
    map<string, vector<string>> grp;

    for (int i = 0; i < H; i++) {
        grp[min(ss[i], rev(ss[i]))].push_back(ss[i]);
    }

    bool ok = true;
    for (auto gg: grp) {
        auto &g = gg.second;
        sort(g.begin(), g.end());
        for (int i = 0; i <= g.size() / 2; i++) {
            if (!same(g[i], g[g.size() - i - 1])) {
                ok = false;
            }
        }
    }
    if (ok) {
        cout << "YES" << endl;
        exit(0);
    }

}

void dfs(int x, int bit) {
    int mx = -1;
    for (int i = 0; i < W; i++) {
        if (bit >> i & 1) {
            mx = i;
            break;
        }
    }
    if (bit == 0) {
        // even
        check();
        return;
    }
    if (bit == (1 << mx)) {
        // odd
        perm[x] = mx;
        check();
        return;
    }
    for (int i = mx + 1; i < W; i++) {
        if (bit >> i & 1) {
            perm[x] = mx;
            perm[W - 1 - x] = i;
            dfs(x + 1, bit - (1 << mx) - (1 << i));
        }
    }
}

