int h,w,final;
string s[15],t[15];

void copy(int x, int y){
	int i;
	for(i=0; i<h; ++i){
		t[i][y] = s[i][x];
	}
}

bool check(){
	int i,j,k,cnt=0;
	bool done[15],flag;
	fill(done,done+15,false);
	for(i=0; i<h; ++i){
		if(done[i]){
			continue;
		}
		for(j=(i+1); j<h; ++j){
			if(done[j]){
				continue;
			}
			flag = true;
			for(k=0; k<w; ++k){
				if(t[i][k] != t[j][w-k-1]){
					flag = false;
					break;
				}
			}
			if(flag){
				done[i] = true;
				done[j] = true;
				break;
			}
		}
	}
	for(i=0; i<h; ++i){
		if(!done[i]){
			k = i;
			++cnt;
		}
	}
	if(cnt > 1){
		return false;
	}else if(!cnt){
		return true;
	}
	flag = true;
	i = 0; j = (w-1);
	while(i < j){
		if(t[k][i] != t[k][j]){
			flag = false;
			break;
		}else{
			++i; --j;
		}
	}
	return flag;
}

bool solve(int status, int x = INF){
	int i,cnt=0,u,d;
	bool flag=true,ret=false;
	if(status == final){
		return check();
	}else if((!status) && w%2){
		for(i=0; i<w; ++i){
			copy(0,i);
			if(solve(1,i)){
				ret = true;
				break;
			}
		}
		return ret;
	}
	for(i=0; i<w; ++i){
		if((status&(1<<i))){
			++cnt;
		}
	}
	u = cnt/2;
	d = w-u-1;
	if(w%2){
		--d;
		if(u>=x){
			++u;
		}
		if(d>=x){
			++d;
		}
	}
	for(i=(w%2); i<w; ++i){
		if(!(status&(1<<i))){
			if(flag){
				status += (1<<i);
				copy(i,d);
				flag = false;
			}else{
				copy(i,u);
				if(solve(status+(1<<i),x)){
					ret = true;
					break;
				}
			}
		}
	}
	return ret;
}

