bool check(const vector<string>& g, const vector<pair<int, int>>& ids) {
  vector<string> x(g.size());
  int pos = 0;
  for (auto p : ids) {
    if (p.fs == p.sc) {
      x[g.size()/2] = g[p.fs];
    } else {
      x[pos] = g[p.fs];
      x[g.size() - 1 - pos] = g[p.sc];
      pos++;
    }
  }

  int cnt = 0;
  rep(i, x[0].size()) {
    string a;
    rep(k, x.size()) a += x[k][i];
    bool ok = false;
    rep(j, x[0].size()) {
      if (i == j) continue;
      string b;
      rep(k, x.size()) b += x[k][j];
      reverse(all(b));
      if (a == b) {
	ok = true;
	break;
      }
    }
    if (!ok) cnt++;
    if (cnt > 1) return false;
  }
  return true;
}

bool rec(int d, int cnt, const vector<string>& g, const vector<vector<bool>>& match,
	 vector<pair<int, int>>& ids, vector<bool>& used) {
  if (d == 0) {
    return check(g, ids);
  }

  rep(i, g.size()) {
    if (used[i]) continue;
    used[i] = true;
    for (size_t j = i+1; j < g.size(); ++j) {
      if (used[j]) continue;
      if (!match[i][j]) continue;
      used[j] = true;
      ids.push_back(make_pair(i, j));

      if (rec(d - 2, cnt, g, match, ids, used)) return true;

      ids.pop_back();      
      used[j] = false;
    }

    if (d % 2 == 1 and cnt == 0) {
      ids.push_back(make_pair(i, i));
      if (rec(d - 1, cnt + 1, g, match, ids, used)) return true;
      ids.pop_back();
    }

    used[i] = false;
    break;
  }
  return false;
}

inline bool solve(const vector<string>& g) {
  vector<vector<bool>> match(g.size(), vector<bool>(g.size(), false));
  rep(i, g.size()) {
    string a = g[i];
    sort(all(a));
    rep(j, g.size()) {
      string b = g[j];
      sort(all(b));
      match[i][j] = (a == b);
    }
  }

  vector<bool> used(g.size(), false);
  vector<pair<int, int>> ids;
  return rec(g.size(), 0, g, match, ids, used);
}

