			}
		}
	}
	int cnt=0,pos=-1;
	for(int i=0;i<m;i++)
		if(!used[i]) cnt++,pos=i;
	if(cnt>=2||(cnt&&(m%2==0))) return 0;
	if(cnt==1)
		for(int i=0;i<n;i++)
			if(st[i][pos]!=st[sp[i]][pos]) return 0;
