  for (int i = 0; i < m; ++i) if (!vis[i]) {
    bool ok;
    for (int j = i + 1; j < m; ++j) if (!vis[j]) {
      ok = true;
      for (int k = 0; k < t; ++k)
        if (s[p[k][0]][i] != s[p[k][1]][j] || s[p[k][0]][j] != s[p[k][1]][i]) {
          ok = false;
          break;
        }
      if (ok) {
        vis[j] = true;
        break;
      }
    }
    if (!ok) {
      for (int k = 0; k < t; ++k)
        if (s[p[k][0]][i] != s[p[k][1]][i])
          return false;
      ++ss;
    }
  }
  return ss <= m % 2;
}

bool dfs(int S, bool t) {
  if (S == 0) return check();
  if (t && dfs(S & (S - 1), false)) return true;
  if (S != (S & -S)) {
    int x = 0;
    while ((~S >> x) & 1) ++x;
    for (int y = x + 1; y < n; ++y) if ((S >> y) & 1) {
      p[cnt][0] = x; p[cnt][1] = y;
      ++cnt;
      if (dfs(S & ~(1 << x) & ~(1 << y), t)) return true;
      --cnt;
    }
  }
  return false;
}

