bool saiki(vector<int> x, vector<int> remain){
	if(remain.size() > 0){
		if(remain.size() == 1){
			x.push_back(remain[0]);
			remain.pop_back();
			return saiki(x, remain);
		}else{
			x.push_back(remain[0]);
			remain.erase(remain.begin());
			rep(i,remain.size()){
				x.push_back(remain[i]);
				remain.erase(remain.begin() + i);
				if(saiki(x, remain)) return true;
				remain.insert(remain.begin() + i, x.back());
				x.pop_back();
			}
			return false;
		}
	}

