		rep(i, groups.size()+1){
			if(i == groups.size()){
				groups.push_back(kouho);
				plus.push_back(1);
				minus.push_back(0);
				break;
			}
			string t = groups[i];
			if(t == kouho){
				plus[i]++;
				break;
			}
			if(t == kouho_rev){
				minus[i]++;
				break;
			}
		}
