void dfs(bitset<16> b, V order) {
	if (b.count() == 0) {
		V fixed = order;
		int i = 0, j = R - 1;
		int id = 0;
		while (i < j) {
			fixed[i] = order[id++];
			fixed[j] = order[id++];
			i++, j--;
		}
		if (i == j)fixed[i] = order[id];
		solve(fixed);
	}
	else{
		for (int i : range(R)) {
			if (b[i]) {
				order.push_back(i);
				b[i].flip();
				break;
			}
		}
		if (b.count() == 0) {
			dfs(b, order);
		}
		for (int i : range(R)) {
			if (b[i]) {
				order.push_back(i);
				b[i].flip();
				dfs(b, order);
				order.pop_back();
				b[i].flip();
			}
		}
	}
}
