#include<bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef pair<int,int> P;

int W,H;
char F[15][15];

bool eq(int a,int b){
  vector<char> c1,c2;
  for(int i=0;i<W;i++){
    c1.emplace_back( F[a][i] );
    c2.emplace_back( F[b][i] );
  }
  sort( c1.begin(), c1.end() );
  sort( c2.begin(), c2.end() );
  for(int i=0;i<W;i++)
    if( c1[i] != c2[i] ) return false;
  return true;
}

void rotate(){
  char tmp[15][15];
  for(int i=0;i<H;i++)
    for(int j=0;j<W;j++)
      tmp[W-j-1][i] = F[i][j];
  swap(H,W);
  for(int i=0;i<H;i++)
    for(int j=0;j<W;j++)
      F[i][j] = tmp[i][j];
}

int hcheck(){
  bool f[15] = {};
  for(int i=0;i<H;i++){    
    for(int j=0;j<H;j++){
      if( i == j ) continue;
      if( f[i] || f[j] ) continue;
      if( eq(i,j) ) f[i] = f[j] = true;
    }
  }
  int cnt = 0;
  for(int i=0;i<H;i++) {
    if( !f[i] ) cnt++;
  }
  if(!(H&1)&&cnt!=0) return false;
  if((H&1)&&cnt!=1) return false;
  return true;
}

bool solve(){
  if(!hcheck()) return false;
  rotate();
  return hcheck();  
}

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  cin >> H >> W;
  for(int i=0;i<H;i++)
    for(int j=0;j<W;j++)
      cin >> F[i][j];
  if( solve() ) cout << "YES" << endl;
  else cout << "NO" << endl;
}

