class mdview {
    private:
        vector<int> *oda;
    public:
        mdview(vector<int> &oda) : oda(&oda) {}
        size_t size() const { return oda->size()/2; }
        int const *operator [](int idx) const { return oda->data() + idx*2; }
};

bool calc(vector<string> const &chars, mdview const &hgv, mdview const &wgv) {
    for (size_t hs = 0; hs < hgv.size(); hs++) {
        for (size_t ws = 0; ws < wgv.size(); ws++) {
            int y1 = hgv[hs][0];
            int x1 = wgv[ws][0];
            int y2 = hgv[hs][1];
            int x2 = wgv[ws][1];
            if (chars[y1][x1] != chars[y2][x2] || chars[y2][x1] != chars[y1][x2]) return false;
        }
    }
    return true;
}

pair<vector<int>,int> organize(vector<string> const &chars, vector<map<char, int>> const &cnt, int upto, bool is_h) {
    vector<int> gs(upto, -1);
    int g = 0;
    for (int i = 0; i < upto; i++) {
        bool exists = false;
        if (gs[i] != -1) continue;
        for (int j = i+1; j < upto; j++) {
            if (gs[j] != -1) continue;
            bool ok = cnt[i] == cnt[j];

            auto otpu = is_h ? chars[0].size() : chars.size();
            if (ok) for (int l = 0; l < j; l++) {
                if (l == i) continue;
                if (gs[l] != g) continue;
                bool same = true;
                for (size_t k = 0; k < otpu; k++) {
                    if (is_h) same = same && chars[l][k] == chars[j][k];
                    else      same = same && chars[k][l] == chars[k][j];
                }
                ok = ok && !same;
            }

            if (ok) {
                exists = true;
                gs[i] = gs[j] = g;
            }
        }
        if (exists) g++;
    }
    if (count(gs.begin(), gs.end(), -1) > 1) return make_pair(gs, -1);
    return make_pair(gs, g);
}

class groupings_generator {
    private:
        mdview curr;
        vector<int> curr_flat;
        vector<pair<vector<int>::iterator, vector<int>::iterator>> range;

    public:
        groupings_generator(vector<vector<int>> const &orig) : curr(curr_flat) {
            curr_flat.reserve(12);
            for (auto const &r: orig) {
                for (auto x: r) {
                    curr_flat.push_back(x);
                }
            }

            auto it = curr_flat.begin();
            for (size_t i = 0; i < orig.size(); i++) {
                if (orig[i].size() > 2) {
                    range.push_back(make_pair(it, it + orig[i].size()));
                }
                sort(it, it + orig[i].size());
                it += orig[i].size();
            }
        }

        mdview const &get_curr() {
            // cerr << "curr_flat: ";
            // copy(curr_flat.begin(), curr_flat.end(), ostream_iterator<int>(cerr, ", "));
            // cerr << "curr: ";
