            //     cerr << "(" << curr[i][0] << "," << curr[i][1] << "), ";
            // }
            // cerr << endl;
            return curr;
        }
        bool gen_next() {
            bool flag = false;
            for (int i = range.size()-1; i >= 0; i--) {
                if (next_permutation(range[i].first, range[i].second)
                        && next_permutation(range[i].first, range[i].second)) {
                    flag = true;
                    break;
                }
            }
            curr = mdview(curr_flat);
            return flag;
        }
};

