bool calc(vector<string> const &chars, vector<int> const &hswap, vector<int> const &wswap, vector<vector<int>> const &hgv, vector<vector<int>> const &wgv) {
    for (auto hs: hswap) {
        for (auto ws: wswap) {
            if (hs == -1 || ws == -1) continue;
            assert(hgv[hs].size() == 2);
            assert(wgv[ws].size() == 2);
            int y1 = hgv[hs][0];
            int x1 = wgv[ws][0];
            int y2 = hgv[hs][1];
            int x2 = wgv[ws][1];
            if (chars[y1][x1] != chars[y2][x2] || chars[y2][x1] != chars[y1][x2]) return false;
        }
    }
    return true;
}

pair<vector<int>,int> organize(vector<map<char, int>> const &cnt, int upto) {
    vector<int> gs(upto, -1);
    int g = 0;
    for (int i = 0; i < upto; i++) {
        bool exists = false;
        if (gs[i] != -1) continue;
        for (int j = i+1; j < upto; j++) {
            if (gs[j] != -1) continue;
            if (cnt[i] == cnt[j]) {
                exists = true;
                gs[i] = gs[j] = g;
            }
        }
        if (exists) g++;
    }
    if (count(gs.begin(), gs.end(), -1) > 1) return make_pair(gs, -1);
    return make_pair(gs, g);
}

vector<vector<vector<int>>> gen_groupings(vector<vector<int>> const &gv) {
    vector<vector<vector<int>>> res[2];
    int cnt = 0;
    for (size_t i = 0; i < gv.size(); i++) {
        if (gv[i].size() > 2) cnt++;
    }

    int i = 0;
    res[0].push_back(gv);
    for (int r = 0; r < cnt; i = !i, r++) {
        while (!res[i].empty()) {
            bool operated = false;
            auto gv = res[i].back();
            res[i].pop_back();
            size_t j = 0;
            for (; j < gv.size() && gv[j].size() == 2; j++);
            if (j == gv.size()) break;

            operated = true;
            vector<int> perm(gv[i].size());
            iota(perm.begin(), perm.end(), 0);
            for (auto &x: perm) x /= 2;
            do {
                vector<vector<int>> n(gv);
                n.erase(n.begin() + j);
                vector<vector<int>> tmp(gv[j].size() / 2);
                for (size_t k = 0; k < gv[j].size(); k++) {
                    tmp[perm[k]].push_back(gv[j][k]);
                }
                copy(tmp.begin(), tmp.end(), back_inserter(n));
                res[!i].push_back(move(n));
            } while (next_permutation(perm.begin(), perm.end()));
            if (!operated) res[!i].push_back(gv);
        }
    }
    for (auto const &r: res[i]) for (auto const &x: r) assert(x.size() == 2);
    return res[i];
}

int main() {
    int h, w;
    cin >> h >> w;
    vector<string> chars(h);
    for (int i = 0; i < h; i++) {
        cin >> chars[i];
    }

    vector<map<char,int>> cnth(h);
