    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            cnth[i][chars[i][j]]++;
            cntw[j][chars[i][j]]++;
        }
    }

    vector<int> hg, wg;
    int hgc, wgc;
    tie(hg, hgc) = organize(cnth, h);
    tie(wg, wgc) = organize(cntw, w);
    if (hgc == -1 || wgc == -1) { cout << "NO" << endl; return 0; }

    vector<vector<int>> hgv(hgc), wgv(wgc);
    for (int i = 0; i < h; i++) {
        if (hg[i] != -1) hgv[hg[i]].push_back(i);
    }
    for (int i = 0; i < w; i++) {
        if (wg[i] != -1) wgv[wg[i]].push_back(i);
    }

    auto hgs = gen_groupings(hgv);
    auto wgs = gen_groupings(wgv);
    for (auto const &hgv: hgs) {
        for (auto const &wgv: wgs) {
            vector<int> hswap(hgv.size()), wswap(wgv.size());
            iota(hswap.begin(), hswap.end(), 0);
            iota(wswap.begin(), wswap.end(), 0);
            do {
                do {
