#include<bits/stdc++.h>
using namespace std;

string solve() {
  int H, W;
  cin >> H >> W;
  vector<string> S(H);
  for(auto& i: S) cin >> i;

  vector<int> order;

  auto check = [&](auto r) {
    vector<bool> used(H);
    set<int> uniq;
    for(auto i=0; i<H; ++i) if(!used[i]) {
      auto ok = -1;
      for(auto j=i+1; j<H; ++j) if(!used[j]) {
        auto s = S[i];
        auto t = S[j];
        auto same = true;
        for(auto k=0; k<order.size(); k+=2) same &= (s[order[k]] == t[order[k+1]]);
        if(r != -1) same &= (s[r] == t[r]);
        if(same) ok = j;
      }
      if(ok == -1) uniq.emplace(i);
      else         used[i] = used[ok] = true;
    }
    if(!uniq.empty()) {
      if(2 <= uniq.size()) return false;
      auto s = S[*begin(uniq)];
      auto same = true;
      for(auto k=0; k<W; k+=2) same &= s[order[k]] == s[order[k+1]];
      return same;
    }
    return true;
  };

  vector<bool> used(W);
  function<bool(int)> dfs = [&](auto l) {
    if(W-1 <= order.size()) {
      if(order.size() == W-1) for(auto i=0; i<W; ++i) if(!used[i]) return check(i);
      return check(-1);
    }
    if(used[l]) return dfs(l+1);
    used[l] = true;
    order.emplace_back(l);
    for(auto h=l+1; h<W; ++h) if(!used[h]) {
      used[h] = true;
      order.emplace_back(h);
      if(dfs(l+1)) return true;
      order.pop_back();
      used[h] = false;
    }
    order.pop_back();
    used[l] = false;
    return false;
  };

  if(W&1) {
    if(dfs(0)) return "YES";
    used = vector<bool>(W);
    order.clear();
    return dfs(1) ? "YES" : "NO";
  } else {
    return dfs(0) ? "YES" : "NO";
  }
}

int main() {
  cout << solve() << endl;
}

