using namespace std;

int MOD = 1e7+19;
int MOD2 = 1e7+141;


int encode(string s, int mod) {
  int sum = 0;
  for(char c : s) {
    int pow = c - 'a';
    int m = 1;
    for(int i=0; i<pow; i++) {
      m = (m * 26) % mod;
    }
    sum = sum + m % mod;
  }
  return sum;
}

bool valid(multiset<pair<int,int>>& h, vector<pair<int,int>>& codebase) {
  int odd = 0;
  set<pair<int,int>> used;
  for(int i=0; i<codebase.size(); i++) {
    if(used.find(codebase[i]) != used.end()) continue;
    used.insert(codebase[i]);
    if(h.count(codebase[i]) % 2  != 0 ) {
      odd ++;
    }
  }
  return odd <= 1;
}

int main (int argc, char*argv[]) {
  int h, w;
  cin >> h >> w;
  vector<string> a;
  multiset<pair<int,int>> hash;
  vector<pair<int,int>> codebase;
  for(int i=0; i<h; i++) {
    string tmp;
    cin >> tmp;
    a.push_back(tmp);
    pair<int,int> code = make_pair(encode(tmp, MOD), encode(tmp, MOD2));
    codebase.push_back(code);
    hash.insert(code);
  }

  if (!valid(hash, codebase)) {
    cout << "NO" << endl;
    return 0;
  }

  hash.clear();
  for(int i=0; i<w; i++) {
    string s = "";
    for(int j=0; j<h; j++) {
      s += a[j][i];
    }
    pair<int,int> code = make_pair(encode(s, MOD), encode(s, MOD2));
    codebase.push_back(code);
    hash.insert(code);
  }
  if (!valid(hash, codebase)) {
    cout << "NO" << endl;
    return 0;
  }

  cout << "YES" << endl;
}

