bool check(){
	memset(match_c,-1,sizeof match_c);
	for(int i=0;i<W;i++){
		if(match_c[i]!=-1) continue;
		for(int j=i+1;j<W;j++){
			if(match_c[j]!=-1) continue;
			bool succ=true;
			for(int k=0;k<H && succ;k++)
				if(grid[match_r[k]][i]!=grid[k][j])
					succ=false;
			if(succ) match_c[i]=j,match_c[j]=i;
		}
	}
	int unmatch=0,mid;
	for(int i=0;i<W;i++)
		if(match_c[i]==-1){
			unmatch++;
			mid=i;
		}
	if(unmatch>=2 || (unmatch && W%2==0)) return false;
	if(!unmatch) return true;
	for(int i=0;i<H;i++)
		if(grid[match_r[i]][mid]!=grid[i][mid])
			return false;
	return true;
}
bool dfs(int idx,bool is_skip){
	if(idx>=H){
		if(H&1 && !is_skip) while(true);
		return check();
	}else{
		if(match_r[idx]!=-1){
			return dfs(idx+1,is_skip);
		}else{
			for(int i=idx+1;i<H;i++){
				if(match_r[i]==-1){
					match_r[idx]=i;
					match_r[i]=idx;
					if(dfs(idx+1,is_skip)) return true;
					match_r[idx]=match_r[i]=-1;
				}
			}
			if(!is_skip && H&1){
				match_r[idx]=idx;
				if(dfs(idx+1,true)) return true;
				match_r[idx]=-1;
			}
			return false;
		}
	}
}
