    int rest;
    rep(h){
        if(pairs[i] == -1) rest = i;
        if(b[pairs[i]] == "") b[pairs[i]] = a[i];
        else b[h-1-pairs[i]] = a[i];
    }
    if(h%2) b[h/2] = a[rest];
    /*
