                    is_pair = false;
                    break;
                }
            }
            if(is_pair){
                used[j] = true;
                used[jj] = true;
                break;
            }
        }
        if(!used[j]){
            if(!odd) return false;
            odd--;
        }
    }
    return true;
}

bool dfs(int n){
    if(n == h/2) return check();

    vector<int> rest(h-n*2);
    int j = 0;
    rep(h) if(pairs[i] == -1) rest[j++] = i;
