			std::vector<int> cnt(26, 0);
			REP(j, w) ++cnt[s[i][j] - 'a'];
			++map[cnt];
		}

		int odd = h & 1;
		for (auto& x : map) {
			if (x.second % 2) {
				if (odd) {
					--odd;
					continue;
				}
				else return false;
			}
		}
	}

	{
		std::map<std::vector<int>, int> map;
		REP(j, w) {
			std::vector<int> cnt(26, 0);
			REP(i, h) ++cnt[s[i][j] - 'a'];
			++map[cnt];
		}

		int odd = w & 1;
		for (auto& x : map) {
			if (x.second % 2) {
				if (odd) {
					--odd;
					continue;
				}
				else return false;
			}
		}
	}

	int odd = 0;
	std::vector<int> cnt(26, 0);
	REP(i, h) REP(j, w) ++cnt[s[i][j] - 'a'];

	REP(i, 26) odd += cnt[i] % 2 == 1;
