#include<bits/stdc++.h>
using namespace std;

int H, W;
vector<string> S;

bool check(auto match, auto r) {
  vector<bool> used(H);
  set<int> unused;
  for(auto i=0; i<H; ++i) if(!used[i]) {
    used[i] = true;
    auto ok = -1;
    for(auto j=i+1; j<H; ++j) if(!used[j]) {
      auto same = true;
      if(r != -1) same &= (S[i][r] == S[j][r]);
      for(auto k=0; k<match.size(); k+=2) same &= (S[i][match[k]] == S[j][match[k+1]]);
      if(same) ok = j;
    }
    if(ok != -1) used[i] = used[ok] = true;
    else         unused.emplace(i);
  }
  if(unused.empty())     return true;
  if(2 <= unused.size()) return false;
  auto s = S[*begin(unused)];
  for(auto k=0; k<match.size(); k+=2) if(s[match[k]] != s[match[k+1]]) return false;
  return true;
}

bool dfs(auto match, auto used, auto n) {
  if(match.size() == W)   return check(match, -1);
  if(match.size() == W-1) for(auto i=0; i<W; ++i) if(!used[i]) return check(match, i);
  if(used[n]) return dfs(match, used, n+1);
  match.emplace_back(n);
  used[n] = true;
  for(auto m=n+1; m<W; ++m) if(!used[m]) {
    match.emplace_back(m);
    used[m] = true;
    if(dfs(match, used, n+1)) return true;
    match.pop_back();
    used[m] = false;
  }
  return false;
}

string solve() {
  vector<int> match;
  vector<bool> used(W);
  if(W&1) if(dfs(match, used, 1)) return "YES";
  return dfs(match, used, 0) ? "YES" : "NO";
}

int main() {
  cin >> H >> W;
  S.resize(H);
  for(auto& i: S) cin >> i;
  cout << solve() << endl;
}

