int main(){
  cin>>h>>w;
  REP(i,h) scanf("%s",buf[i]);

  int flag[15]={0};
  int h2=(h+1)/2;
  REP(i,h2) flag[i+h-h2]=1;

  do{
    int perm[15]={0};
    REP(i,h2) perm[i]=i;
    do{
      vector<int> up(h2),down(h2);
      int c0=0,c1=0;
      REP(i,h){
        if(flag[i]==1) up[perm[c0]]=i,++c0;
        else down[c1]=i,++c1;
      }
      if(h&1) down[h2-1]=up[h2-1];
      auto get=[&](int c,const vector<int>& x){
        string res;
        REP(i,h2) res+=buf[x[i]][c];
        return res;
      };

      map<pair<string,string>,int> cnt;
      REP(i,w){
        cnt[mp(get(i,up),get(i,down))]++;
      }
      bool fail=false;
      int ocnt=0;
      for(auto e:cnt){
        string s1=e.fr.fr,s2=e.fr.sc;
        if(s1!=s2 && (!cnt.count(mp(s2,s1)) || e.sc!=cnt[mp(s2,s1)])) {
