using namespace std;
int h,w;
bool solve(int id,vector<string>& s){
    if(id==h/2){
        vector<int> flag(w,false);
        for(int j=0;j<w;j++){
            if(flag[j]) continue;
            for(int k=j+1;k<w;k++){
                bool isok=true;
                for(int i=0;i<h;i++){
                    if(s[i][j]!=s[h-1-i][k]){
                        isok=false;
                        break;
                    }
                }
                if(isok){
                    flag[j]=flag[k]=true;
                    break;
                }
            }
        }
        int cnt=count(flag.begin(),flag.end(),false);
        if(cnt==2) return false;
        if(cnt==0) return true;
        for(int j=0;j<w;j++){
            if(!flag[j]){
                for(int i=0;i<h;i++){
                    if(s[i][j]!=s[h-1-i][j]) return false;
                }
                return true;
            }
        }        
    }
    for(int i=id+1;i<h-id;i++){
        assert(i<=h-id-1);
        if(i!=h-id-1) swap(s[i],s[h-id-1]);
        if(solve(id+1,s)) return true;
        if(i!=h-id-1) swap(s[i],s[h-id-1]);
    }
    return false;
}

int main(){
    cin>>h>>w;
    vector<string> s(h);
    for(int i=0;i<h;i++) cin>>s[i];
    vector<int> flag(h);
    bool isok=false;
    if(h%2==1){
        for(int i=0;i<h;i++){
            swap(s[i],s[h/2]);
            isok=isok || solve(0,s);
            swap(s[i],s[h/2]);
        }
    }else{
        isok=solve(0,s);
    }
    cout<<(isok? "YES" : "NO")<<endl;
    return 0;
}

