	if(u==now){
		for(int i=0;i<col;i++)
			if(dfs2(now-1,mask|(1<<i))) return true;
	}else{
		int t=0;
		while(mask&(1<<t)) t++;
		mask|=1<<t;
		for(int j=0;j<col;j++)
			if((mask&(1<<j))==0 && g[t][j]){
				if(dfs2(now-1,mask|(1<<j)))
					return true;
			}
	}
	return false;
}
