  rep(i, H)rep(j, W) cin >> S[i][j];
  vector<int> rest, now;
  rep(i, H){
    rest.pb(i);
  }
  if(solve(rest, now)){
    cout << "YES" << endl;
  }else{
    cout << "NO" << endl;
  }

}

