            if (s1[i] != s2[H - 1 - i]) { return false; }
        }
        return true;
    };
    vector<vector<int>> rs;
    auto rec = fix([&](auto&& self, vector<int> r, const int num) -> void {
        if (num == (H + 1) / 2) {
