    repp(k, 2){
        int rest[h-n];
        int j = 0, pair_left = -1;
        rep(h){
            if(pairs[(i+k)%h] == -1){
                if(pair_left == -1) pair_left = (i+k)%h;
                else rest[j++] = (i+k)%h;
