  string s[14],st[14],s2[14];
  rep(i,W) st[i] = string(H,' ');
  vi swapvec; 
  rep(i,H) cin >> s[i];

  function<bool()> check = [&]{
    // st を調べる
    bool once = (W%2==1);
    rep(j,W/2){
      bool update = false;
      string rs = st[j];
      rep(i,H/2) swap(rs[i],rs[H-1-i]);
      REP(k,j+1,W){
        if(rs==st[k]){
          swap(st[k],st[W-j-1]);
          update = true;
          break;
        }
      }
      if(update) continue;
      if(once){
        if(st[j]==rs){
          swap(st[j],st[W/2]);
          j--;
          once = false;
          continue;
        } 
      }
      dump(j);
      return false;
    }
    return true;
  };
  function<bool(const vi&)> dfs = [&](const vi& v){
    if(swapvec.size()==H){
      dump(swapvec);
      rep(i,H/2){
        s2[i] = s[swapvec[2*i]];
        s2[H-i-1] = s[swapvec[2*i+1]];
      }
      if(H%2) s2[H/2] = s[swapvec[H-1]];
      // transpose
      rep(i,H) rep(j,W) st[j][i] = s2[i][j];
      return check();
    }
    bool res = false;
    rep(i,v.size()){
      swapvec.pb(v[i]);
      vi nxt = v;
      nxt.erase(nxt.begin()+i);
      bool adnxt = nxt.size();
      if(adnxt){
        swapvec.pb(nxt[0]);
        nxt.erase(nxt.begin());
      }
      res |= dfs(nxt);
      swapvec.pop_back();
      if(adnxt) swapvec.pop_back();
    }
    dump(swapvec.size());
    return res;
  };
  bool ans = false;
  rep(i,100){
    vi vec(H);
    iota(vec.begin(),vec.end(),0);
    random_shuffle(vec.begin(),vec.end());
    swapvec.clear();
    swapvec.pb(vec[0]); vec.erase(vec.begin());
    ans |= dfs(vec);
    if(ans){
      cout << "YES" << endl;
      return 0;
    }
  }
  cout << "NO" << endl;
  return 0;
}

