bool all_pair(int bit, int depth=0) {
    if (depth == h / 2) {
        // if (h % 2 == 1) {
        //     for (int i = 0; i < h; ++i) {
        //         if (!((bit >> i) & 1)) {
        //             ord[h / 2] = map[i];
        //         }
        //     }
        // }
        return check();
    }
    //cout << bit << endl;

    for (int i = 0; i < h; ++i) {
        if ((bit >> i) & 1) {
        continue;
        } else {
            for (int j = i + 1; j < h; ++j) {
                if ((bit >> j) & 1) continue;
                ord[depth] = map[i];
                ord[h - depth - 1] = map[j];
                bool ok = all_pair(bit | (1 << i) | (1 << j), depth+1);
                if (ok) return true;
            }
            break;
        }
    }

    return false;
}

