string s[20], ss[20];

void check(int u, bool flag)
{
    if(u == (m + 1) / 2) {
        ans = true;
        return ;
    }

    for(int i = u; i < m; i ++) {
        if(col[i] == -1) {
            for(int j = i + 1; j < m; j ++) {
                if(col[j] >= 0)
                    continue;
                bool f = true;
                for(int k = 0; k < n; k ++) {
                    if(s[k][i] != s[row[k]][j]) {
                        f = false;
                        break;
                    }
                }
                if(f) {
                    col[i] = j;
                    col[j] = i;
                    check(u + 1, flag);
                    col[i] = col[j] = -1;
                }
            }

            if(flag) {
                bool f = true;
                for(int k = 0; k < n; k ++) {
                    if(s[k][i] != s[row[k]][i]) {
                        f = false;
                        break;
                    }
                }
                if(f) {
                    col[i] = i;
                    check(u + 1, false);
                    col[i] = -1;
                }
            }
            break;
        }
    }
}

void dfs(int u, int flag)
{
    if(u == (n + 1) / 2) {
        check(0, m & 1);
        return;
    }

    for(int i = u; i < n; i ++) {
        if(row[i] == -1) {
            for(int j = i + 1; j < n; j ++) {
                if(row[j] >= 0 || ss[i] != ss[j])
                    continue;
                row[i] = j;
                row[j] = i;
                dfs(u + 1, flag);
                row[i] = row[j] = -1;
            }
            if(flag) {
                row[i] = i;
                dfs(u + 1, false);
                row[i] = -1;
            }
            break;
        }
    }
}

