using namespace std;
int n, m, midx, midy;
char s[15][15];
struct node
{
	int cnt[26];
	int id;
	node() {memset(cnt, 0, sizeof cnt);}
	void clr() {memset(cnt, 0, sizeof cnt);}
}ver[15], hor[15];
bool cmp(const node & u, const node & v)
{
	for (int i = 0; i < 26; i++)
		if (u.cnt[i] != v.cnt[i])
			return u.cnt[i] < v.cnt[i];
	return true;
}
bool samei(const node & u, const node & v)
{
	for (int i = 0; i < 26; i++)
		if (u.cnt[i] != v.cnt[i])
			return false;
	return true;
}
bool chk()
{
	if (midx != -1)
	{
		if (midy != -1) ver[midx].cnt[s[ver[midx].id][hor[midy].id] - 'a']--;
		for (int i = 0; i < 26; i++)
			if (ver[midx].cnt[i] & 1)
				return false;
	}
	if (midy != -1)
	{
		if (midx != -1) hor[midy].cnt[s[ver[midx].id][hor[midy].id] - 'a']--;
		for (int i = 0; i < 26; i++)
			if (hor[midy].cnt[i] & 1)
				return false;
	}
	return true;
}
int main()
{
	scanf("%d%d", &n, &m);
	for (int i = 1; i <= n; i++) scanf("%s", s[i] + 1);
	for (int i = 1; i <= n; i++) ver[i].clr(), ver[i].id = i;
	for (int i = 1; i <= m; i++) hor[i].clr(), hor[i].id = i;
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= m; j++)
			ver[i].cnt[s[i][j] - 'a']++;
	sort(ver + 1, ver + n + 1, cmp);
	int tot = 0;
	midx = midy = -1;
	for (int i = 1; i <= n; i++)
		if (samei(ver[i], ver[i + 1])) tot++, i++;
		else midx = i;
	if (tot != n / 2)
	{
		puts("NO");
		return 0;
	}
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= m; j++)
			hor[j].cnt[s[i][j] - 'a']++;
	sort(hor + 1, hor + m + 1, cmp);
	tot = 0;
	for (int i = 1; i <= m; i++)
		if (samei(hor[i], hor[i + 1])) tot++, i++;
		else midy = i;
	if (tot != m / 2 || !chk())
	{
		puts("NO");
		return 0;
	}
	puts("YES");
	return 0;
}

