int H, W;
vector<string> S;

bool check(auto group) {
  vector<string> upper, lower;
  for(auto i=0; i<H; ++i) {
    if(group[i]) upper.emplace_back(S[i]);
    else         lower.emplace_back(S[i]);
  }
  sort(begin(upper), end(upper));
  do {
    vector<string> T(begin(upper), end(upper));
    T.insert(end(T), begin(lower), end(lower));
    vector<string> column(W);
    for(auto j=0; j<W; ++j) for(auto i=0; i<H; ++i) column[j] += T[i][j];
    map<string, int> m;
    for(auto s: column) ++m[s];
    for(auto s: column) reverse(begin(s), end(s)), --m[s];
    if(all_of(begin(m), end(m), [](auto i) {return i.second == 0;})) return true;
  } while(next_permutation(begin(upper), end(upper)));
  return false;
}

bool dfs(auto group, auto i, auto n) {
  if(n == (H+1)/2) return check(group);
  if(i == H)       return false;
  if(dfs(group, i+1, n)) return true;
  group[i] = true;
  return dfs(group, i+1, n+1);
}

string solve() {
  return dfs(vector<bool>(H), 0, 0) ? "YES" : "NO";
}

int main() {
  cin >> H >> W;
  S.resize(H);
  for(auto& s: S) cin >> s;
  cout << solve() << endl;
}

