	}
	else if (n != h / 2) {
		while (used[p]) p++;
		for (int i = p + 1; i < h; i++) if (!used[i]) {
			used[i] = true;
			ar[n] = p; ar[h - 1 - n] = i;
			if (dfs(p + 1, n + 1, 0)) return true;
			used[i] = false;
		}
