bool flag, mrk[13];
bool IsPal(int id) {
	for (int i = 1; i <= m/2; i++)
		if (s[id][p[i][0]] ^ s[id][p[i][1]])
			return false;
	return true;
}
bool IsMat(int u, int v) {
	for (int i = 1; i <= m/2; i++)
		if (s[u][p[i][0]] ^ s[v][p[i][1]])
			return false;
	for (int i = 1; i <= m/2; i++)
		if (s[u][p[i][1]] ^ s[v][p[i][0]])
			return false;
	return true;
}
bool chk() {
	bool used[13], pal = n&1;
	memset(used, false, sizeof used);
	for (int u = 1, v = 0; u <= n; u++, v = 0) if (!used[u]) {
		for (int i = u+1; !v && i <= n; i++)
			if (!used[i] && IsMat(u, i)) v = i;
		if (v) used[u] = used[v] = true;
		else if (!IsPal(u)) return false;
		else if (!pal) return false;
		else used[u] = true, pal = false;
	}
	return true;
}
void DFS(int stp) {
	if (stp > m/2) {flag |= chk(); return;}
	for (int i = 1; !flag && i <= m; i++) if (!mrk[i]) {
		p[stp][0] = i, mrk[i] = true;
		for (int j = i+1; !flag && j <= m; j++) if (!mrk[j])
			p[stp][1] = j, mrk[j] = true, DFS(stp+1), mrk[j] = false;
		mrk[i] = false; break;
	}
}
