void init() {
}

string col_str(int j) {
	for (int i=0; i<n; i++) t[i] = g[i][j];
	t[n] = '\0';
	return string(t);
}

int check() {
	multiset<string> ss;
	for (int j=0; j<m; j++) ss.insert(col_str(j));
	int first = 1;
	while (ss.size()>0) {
		auto p = ss.begin();
		string s = *p, r = s;
		reverse(r.begin(), r.end());
		ss.erase(p);
		auto q = ss.find(r);
		if (q==ss.end()) {
			if (m%2==0) return 0;
			if (!first || r != s) return 0;
			first = 0;
		}
		else ss.erase(q);
	}
	//for (int i=0; i<n; i++) printf("%s\n", g[i]);
	return 1;
}

void swap_str(int i, int j) {
	if (i==j) return;
	strcpy(t, g[i]);
	strcpy(g[i], g[j]);
	strcpy(g[j], t);
}

int srch(int p) {
	if (p==n/2) {
		return check();
	}
	int q = n-1-p;
	for (int i=p+1; i<=q; i++) {
		swap_str(i,q);
		if (srch(p+1)) return 1;
		swap_str(i,q);
	}
	return 0;
}

int solve() {
	if (n%2) {
		int mid = n/2;
		for (int i=0; i<n; i++) {
			swap_str(i,mid);
			if (srch(0)) return 1;
			swap_str(i,mid);
		}
		return 0;
	}
	else return srch(0);
}

void output(int ans) {
	printf("%s\n", ans? "YES":"NO");
}

