    g[a].pb (b); g[b].pb (a);
  }
  bool solve (int p = 0, bool mid = 0) {      
    if (p == n) {
      return 1;
    }
    if (used[p])  return solve (p + 1, mid);

    if ((n & 1) && !mid) {
      used[p] = 1;
      if (solve (p + 1, 1)) 
