int H, W;
int cnt = 0;
vector<string> grid;

bool is_symmetric(int x1, int x2, const vector<int> &perm)
{
    for (int y=0; y<H; y++) {
        assert(perm[y]>=0);
        if (grid[perm[y]][x1] != grid[perm[H-y-1]][x2]) return false;
    }
    return true;
}

bool match(const vector<int> &perm)
{
#ifdef DEBUG
    rep(i, H) cerr << perm[i] << " ";
    cerr << endl;
#endif

    int used = 0;
    bool allow_alone = W%2;
    for (int x1=0; x1<W; x1++) {
        if ((used>>x1) & 1) continue;
        bool matched = false;
        for (int x2=0; x2<W; x2++) {
            if (x1 == x2) continue;
            if ((used>>x2) & 1) continue;

            if (is_symmetric(x1, x2, perm)) {
                used |= (1<<x1), used |= (1<<x2);
                matched = true;
                break;
            }
        }

        if (!matched && allow_alone) {
            if (is_symmetric(x1, x1, perm)) {
                used |= (1<<x1);
                allow_alone = false;
                matched = true;
            }
        }

        if (!matched) {
            return false;
        }
    }
    return __builtin_popcount(used) == W;

    // return match_dfs(0, 0, W%2, perm);
}

bool dfs(int y1, int used, bool allow_alone, vector<int> &perm)
{
    if (used == (1<<H) - 1) {
        cnt++;
        return match(perm);
    }

    if ((used>>y1) & 1) {
        return dfs(y1+1, used, allow_alone, perm);
    }

    used |= (1<<y1);
    perm[__builtin_popcount(used)/2] = y1;

    bool res = false;
    if (allow_alone) {
        res = dfs(y1+1, used, false, perm);
    }

    for (int y2=y1+1; y2<H; y2++) {
        if ((used>>y2) & 1) continue; 
        used |= (1<<y2);
        perm[H - __builtin_popcount(used)/2] = y2;
        res  |= dfs(y1+1, used, allow_alone, perm);
        perm[H - __builtin_popcount(used)/2] = -1;
        used &= ~(1<<y2);
    }

    perm[__builtin_popcount(used)/2] = -1;
    used &= ~(1<<y1);

    return res;
}

