      bool f = true;
      REP(k, 0, H) f = f && S[k][i] == S[H - 1 - k][j];
      if(f) {
        ok[i] = ok[j] = true;
        cnt += 2;
        break;
      }
    }
  }

  if(W % 2 == 1) {
    bool x = true;
    REP(i, 0, W) if(!ok[i]) {
      REP(j, 0, H) x = x && S[j][i] == S[H - 1 - j][i];
    }
    return cnt == W - 1 && x;
  }
  return cnt == W;
}

