  bool ret = false;
  REP(i, l + 1, r) {
    REP(j, i, r - 1) swap(S[j], S[j + 1]);
    ret = dfs(l + 1, r - 1) || ret;
    for(ll j = r - 2; j >= i; j--) swap(S[j], S[j + 1]);
  }
  return ret;
}

