using namespace std;

const int N = 514;
const int E = (2e5) * 2;


struct Graph{
  int to[E],bro[E],head[N],e;
  int lnk[N],vis[N],stp,n;
  void init( int _n ){
    stp = 0; e = 1; n = _n;
    for( int i = 1 ; i <= n ; i ++ )
      lnk[i] = vis[i] = 0;
  }
  void add_edge(int u,int v){
    to[e]=v,bro[e]=head[u],head[u]=e++;
    to[e]=u,bro[e]=head[v],head[v]=e++;
  }
  bool dfs(int x){
    vis[x]=stp;
    for(int i=head[x];i;i=bro[i]){
      int v=to[i];
      if(!lnk[v]){
        lnk[x]=v,lnk[v]=x;
        return true;
      }else if(vis[lnk[v]]<stp){
        int w=lnk[v];
        lnk[x]=v,lnk[v]=x,lnk[w]=0;
        if(dfs(w)){
          return true;
        }
        lnk[w]=v,lnk[v]=w,lnk[x]=0;
      }
    }
    return false;
  }
  int solve(){
    int ans = 0;
    for(int i=1;i<=n;i++)
      if(!lnk[i]){
        stp++; ans += dfs(i);
      }
    return ans;
  }
} graph;

bool ans;

int n, m;
char ip[N][N];

int mat[N];
void chk() {
  for (int i = 0; i < n; ++i) if (mat[i] == -1) return;
  return;
  graph.init(m);
  for (int i = 0; i < m; ++i) {
    for (int j = i + 1; j < m; ++j) {
      bool good = 1;
      for (int k = 0; k < n; ++k) {
        if (ip[k][i] != ip[mat[k]][j] || ip[k][j] != ip[mat[k]][i]) {
          good = 0;
          break;
        }
      }
      if (good) graph.add_edge(i+1, j+1);
    }
  }
  if (graph.e < m/2) return;
  if (graph.solve() >= m/2) {
    puts("YES");
    exit(0);
    ans = 1;
    return;
  }
}

void dfs(int i) {
  if (ans) return;
  if (i == n) {
    chk();
  }
  if (mat[i] != -1) {
    dfs(i + 1);
    return;
  }
  for (int j = i; j < n; ++j) if (mat[j] == -1) {
    if (j == i && n % 2 == 0) continue;
    mat[j] = i;
    mat[i] = j;
    dfs(i + 1);
    if (ans) return;
    mat[j] = -1;
    mat[i] = -1;
  }
  return;
}

int main() {
  cin >> n >> m;
  for (int i = 0; i < n; ++i) cin >> ip[i];
  fill(mat, mat+n, -1);
  dfs(0);
  cout << (ans? "YES": "NO") << endl;
}

