inline void sol1()
{
	map<string,int> cnt;

	rep(j,w)
	{
		string st="";
		rep(i,h) if(t[i][j]=='*') st+=t[h-i-1][j]; else st+=t[i][j];
		string tt=st;
		reverse(All(tt));
		cnt[min(st,tt)]++;
	}

	bool f=0;
	repE(p,cnt)
	{
		string st=p.fs;
		string tt=st;reverse(All(tt));

		if(p.sc%2==0) continue;
		if(st!=tt||f) return;

		f=1;
	}

	ans=1;
}

inline void sol2(int b,int k)
{
	if(b==0)
	{
		sol1();
		return;
	}

	int st=0;
	while(~(b>>st)&1) st++;

	t[k]=s[st];
	repa(i,st+1,h) if((b>>i)&1)
	{
		t[h-k-1]=s[i];
		sol2(b^(1<<st)^(1<<i),k+1);
	}
}

