template < typename Value >
auto transpose(std::vector< std::vector< Value > > const& grid) {
  int h = grid.size();
  int w = grid.front().size();
  auto ret = std::vector< std::vector< Value > > (w, std::vector< Value >(h));
  for (auto i = 0; i < h; i++) {
    for(auto j = 0; j < w; j++) {
      ret.at(j).at(i) = grid.at(i).at(j);
    }
  }
  return ret;
}

int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);

  auto make_index_pairs = [&] (int W) {
    int n = W / 2;
    int N = 2 * n;
    std::vector<std::vector<std::pair<int,int>>> ans;
    std::vector<std::pair<int,int>> now;
    std::vector<int> ckd(W,false);
