      if ((int)now.size() == n) {
        ans.emplace_back(now);
        return;
      }

      int i = std::find(all(ckd), false) - ckd.begin();
      assert(0 <= i && i < W);
      ckd.at(i) = true;

      rep(j,0,W) {
        if (ckd.at(j)) continue;
        ckd.at(j) = true;
        now.emplace_back(i,j);
        dfs(dfs);
        ckd.at(j) = false;
        now.pop_back();
      }
      ckd.at(i) = false;
    };
    if (N==W) {
      dfs(dfs);
    } else {
      rep(i,0,W) {
        ckd.at(i) = true;
        dfs(dfs);
        ckd.at(i) = false;
      }
    }
