      for (auto&& p : index_pair) {
        ckd.at(p.first) = true;
        ckd.at(p.second) = true;
      }
      auto it = std::find(all(ckd), false);
      assert(it != ckd.end());
      center = it - ckd.begin();
    }

    int sz = index_pair.size();
    for (auto&& v : grid) {
      std::vector<char> new_v(w);
      rep(k,0,sz) {
        int i,j; std::tie(i,j) = index_pair.at(k);
        new_v.at(k) = v.at(i);
        new_v.at(w-1-k) = v.at(j);
      }
      if (w%2==1) {
        assert(center!=-1);
        new_v.at(w/2) = v.at(center);
      }
