#define mk make_pair
#define pb push_back
#define eps 1e-12
#define MAXN 29
using namespace std;
int h,w;
string s[MAXN];
vector<pii> fans;
bool ans=false;
inline bool check()
{
	map<string,int> mp;
	for(int i=0;i<h;i++)
	{
		string temp;
		for(int j=0;j<fans.size();j++)
		{
			temp.insert(temp.end(),s[i][fans[j].first]);
		}
		for(int j=fans.size()-1;j>=0;j--)
		{
			if(fans[j].first!=fans[j].second)
			{
				temp.insert(temp.end(),s[i][fans[j].second]);
			}
		}
		mp[temp]++;
	}
	int cnt=0;
	for(auto it=mp.begin();it!=mp.end();it++)
	{
		if(!mp[it->first])
		{
			continue;
		}
		string rev_str=it->first;
		reverse(rev_str.begin(),rev_str.end());
		if(mp[it->first]!=mp[rev_str])
		{
			cnt+=abs(mp[it->first]-mp[rev_str]);
			if(rev_str!=((it->first)))
			{
				cnt=1000;
			}
		}
		else
		{
			if((it->first)==rev_str)
			{
				if(mp[it->first]%2)
				{
					cnt++;
				}
			}
		}
		mp[rev_str]=0;
	}
	if(cnt>1)
	{
		return false;
	}
	if(cnt==1)
	{
		if(h%2)
		{
			return true;
		}
		return false;
	}
	return true;
}
void recurse(vector<int> v)
{
	if(v.empty())
	{
		if(check())
		{
			ans=true;
		}
		return;
	}
	int first_val=v[0];
	v.erase(v.begin());
	if(v.empty())
	{
		fans.pb(mk(first_val,first_val));
		if(check())
		{
			ans=true;
		}
		fans.pop_back();
		return;
	}
	for(int i=0;i<v.size();i++)
	{
		vector<int> temp=v;
		int second_val=v[i];
		temp.erase(temp.begin()+i);
		fans.pb(mk(first_val,second_val));
		recurse(temp);
		fans.pop_back();
	}
}
