char mp[22][22];
bool ok[22];
int h,w;

bool check(){
	//cout << "in check()" << endl;
	REP(i,22)ok[i] = false;
	for(int i = 0;i < w;i++){
		for(int j = i + 1;j < w;j++){
			if(ok[i] || ok[j])continue;
			bool flag = true;
			REP(k,h){
				if(mp[k][i] != mp[h-k-1][j])flag = false;
			}
			if(flag){
				ok[i] = true;ok[j] = true;
				break;
			}
		}
	}

	bool kai = true;
	REP(i,w){
		if(!ok[i] && kai){
			REP(j,h)if(mp[j][i] != mp[h-j-1][i])kai = false;
			ok[i] = kai;
			kai = false;
		}
	}

	REP(i,w)if(!ok[i])return false;
	return true;
}

bool dfs(int depth){
	//cout << "dfs " << depth << endl;
	if(depth == h - depth - 1 || depth + 1 == h - depth - 1){
		return check();
	}
	for(int i = depth;i < h - depth;i++){
		//cout << i << endl;
		for(int j = i+1;j < h - depth;j++){
			if(i != depth){
				REP(k,w){
					swap(mp[depth][k],mp[i][k]);
				}
			}
			if(j != h - depth - 1){
				REP(k,w){
					swap(mp[h - depth - 1][k],mp[j][k]);
				}
			}
			if(dfs(depth+1))return true;
			if(i != depth){
				REP(k,w){
					swap(mp[depth][k],mp[i][k]);
				}
			}
			if(j != h - depth - 1){
				REP(k,w){
					swap(mp[h - depth - 1][k],mp[j][k]);
				}
			}
		}
	}
	return false;
}

