int check() {
	REP(i, 0, m) {
		REP(j, i + 1, m) {
			g2[i][j] = 1;
			REP(k, 0, n) {
				if (k == single) {
					if (g[k][i] != g[k][j]) {
						g2[i][j] = 0;
					}
				} else {
					if (g[k][i] != g[pp[k]][j]) {
						g2[i][j] = 0;
					}
				}
			}
			g2[j][i] = g2[i][j];
		}
	}

	single2 = -1;
	return rec_sol2();
}

int rec_sol() {
	int cur = -1;
	REP(i, 0, n) {
		if (!used[i]) {
			cur = i;
			break;
		}
	}
	if (cur == -1) {
		return check();
	}

	used[cur] = 1;
	REP(j, cur + 1, n) {
		if (!used[j] && g1[cur][j]) {
			pp[j] = cur;
			pp[cur] = j;
			used[j] = 1;
			if (rec_sol()) {
				return 1;
			}
			used[j] = 0;
		}
	}
	if (single == -1 && n % 2 == 1) {
		single = cur;
		if (rec_sol()) {
			return 1;
		}
		single = -1;
	}

	used[cur] = 0;
	return 0;
}

