int H, W;
char S[13][12];
bool is_symmetry(){
	if(W % 2 == 0){
		for(int i = 0; i < (1 << W); i++){
			int cnt = 0;
			for(int j = 0; j < W; j++){
				if(i & (1 << j)) cnt++;
			}
			if(cnt != W / 2) continue;
			int a0[26], a1[26];
			fill(a0, a0 + 26, 0);
			fill(a1, a1 + 26, 0);
			for(int j = 0; j < W; j++){
				for(int k = 0; k < H; k++){
					if(i & (1 << j)) a0[S[j][k] - 'a']++;
					else a1[S[j][k] - 'a']++;
				}
			}
			bool flag = true;
			for(int j = 0; j < 26; j++){
				if(a0[j] != a1[j]){
					flag = false;
					break;
				}
			}
			if(flag) return true;
		}
		return false;
	}else{
		for(int i = 0; i < W; i++){
			int a[26];
			fill(a, a + 26, 0);
			for(int j = 0; j < H; j++){
				a[S[i][j] - 'a']++;
			}
			int cnt = 0;
			for(int j = 0; j < 26; j++){
				if(a[j] % 2 == 1) cnt++;
			}
			if(cnt > 1) continue;
			for(int j = 0; j < (1 << W); j++){
				int cnt = 0;
				for(int k = 0; k < W; k++){
					if(j & (1 << k)) cnt++;
				}
				if(cnt != W / 2 + 1) continue;
				int a0[26], a1[26];
				fill(a0, a0 + 26, 0);
				fill(a1, a1 + 26, 0);
				for(int k = 0; k < W; k++){
					if(k == i) continue;
					for(int l = 0; l < H; l++){
						if(j & (1 << k)) a0[S[k][l] - 'a']++;
						else a1[S[k][l] - 'a']++;
					}
				}
				bool flag = true;
				for(int k = 0; k < 26; k++){
					if(a0[k] != a1[k]){
						flag = false;
						break;
					}
				}
				if(flag){
					return true;
				}
			}
		}
		return false;
	}
}
int main(){
	fill(S[0], S[12], '0');
	cin >> H >> W;
	for(int i = 0; i < H; i++) cin >> S[i];
	if(!is_symmetry()){
		cout << "NO" << endl;
		return 0;
	}
	for(int i = 0; i < 12; i++){
		for(int j = i; j < 12; j++){
			swap(S[i][j], S[j][i]);
		}
	}
	swap(H, W);
	if(!is_symmetry()){
		cout << "NO" << endl;
		return 0;
	}
	cout << "YES" << endl;
	return 0;
}

