inline bool same(int i, int j) {
    inc(k, 0, h){
        if(c[f[k]][i] != c[f[h-k-1]][j]) return false;
    }
    return true;
}

bool dfs2(int cnt, int flag) {
    if(cnt == w){
        return true;
    }

    bool res = false;

    inc(i, 0, w){
        if(g[i] == 0){
            inc(j, i+1, w){
                if(g[j] == 0){
                    if(same(i, j)){
                        g[i] = 1;
                        g[j] = 1;
                        return dfs2(cnt+2, flag);
                    }
                }
            }
            if(flag == 0 && same(i, i)){
                g[i] = 1;
                res |= dfs2(cnt+1, flag+1);
                g[i] = 0;
            }
            break;
        }
    }

    return res;
}

bool dfs1(int idx, int bit) {
    bool res = false;
    int cnt = 0;
    inc(i, 0, h){
        if((bit & (1 << i)) != 0) cnt++;
    }

    if(cnt == h){
        return dfs2(0, 0);
    }

    if(cnt == 0 && h%2 == 1){
        inc(i, 0, h){
            f[h/2] = i;
            res |= dfs1(0, bit | (1 << i));
            f[h/2] = -1;
        }
    }else{
        inc(i, 0, h){
            if((bit & (1 << i)) == 0){
                inc(j, i+1, h){
                    if((bit & (1 << j)) == 0){
                        f[idx] = i;
                        f[h-idx-1] = j;
                        res |= dfs1(idx+1, bit | (1 << i) | (1 << j));
                        f[idx] = -1;
                        f[h-idx-1] = -1;
                    }
                }
                break;
            }
        }
    }

    return res;
}

