void _main()
{
    ll h; llin(h);
    ll w; llin(w);
    V<string> grid;
    rep (i, h) {
        string tmp; CIN(tmp);
        grid.pb(tmp);
    }

    S bitset<144> maps[13][13];
    bitset<144> zero;

    rep (h1, h) rep (h2, h) {
        maps[h1][h2] = zero;
        rep (w1, w) rep (w2, w) {
            if (grid[h1][w1] == grid[h2][w2] && grid[h1][w2] == grid[h2][w1]) {
                maps[h1][h2].set(w1*12LL+w2);
            }
        }
    }

    S bool used[13];
    memset(used, 0, sizeof(used));

    if (h & 1LL) {
        rep (single, h) {
            used[single] = true;
            bitset<144> state = maps[single][single];
            if (solve(maps, h, w, state, used)) {
                cout << "YES" << endl;
                return;
            }
            used[single] = false;
        }
    }
    else {
        bitset<144> state; state.set();
        if (solve(maps, h, w, state, used)) {
            cout << "YES" << endl;
            return;
        }
    }

    cout << "NO" << endl;
}

