ll H,W;
bool check(vector<vector<char>>& masu){
    vector<int> filled(W+1);
    bool center = false;
    for(int i = 1; i <= W;i++){
        if(filled[i]) continue;
        vector<char> T;
        for(ll j = H; j >= 1;j--){
            T.push_back(masu[j][i]);
        }
        bool update = false;
        for(int j = i + 1; j <= W;j++){
            if(filled[j]) continue;
            bool ok = true;
            for(int k = 1; k <= H;k++){
                if(T[k-1] != masu[k][j]) ok = false;
            }
            if(ok){
                filled[i] = filled[j] = 1;
                update = true;
                break;
            }
        }
        if(update) continue;
        if(W%2 == 0) return false;
        if(center) return false;
        for(int k = 0; k < H/2; k++){
            if(T[k] != T[H-k-1]) return false;
        }
        center = true;
    }
    return true;
}
bool rec(vector<int>&flag,vector<vector<char>>& masu){
    if(accumulate(flag.begin(),flag.end(),0) >= H-1){
        return check(masu);
    }else{
        for(int i = 1; i<= H;i++){
            if(flag[i]) continue;
            for(int j = i+1; j <= H;j++){
                if(flag[j]) continue;
                flag[i] = flag[j] = 1;
                if(rec(flag,masu)) return true;
                swap(masu[i],masu[j]);
                if(rec(flag,masu)) return true;
                swap(masu[i],masu[j]);
                flag[i] = flag[j] = 0;
            }
            break;
        }
    }
    return false;
}
