#include <bits/stdc++.h>
using namespace std;

int h, w;
string s[15];
int pos[15];
int rpos[15];
int cnt;

bool matching(int i, int j) {
  for (int hi = 0; hi < h; hi++) {
    if (s[rpos[hi]][i] != s[rpos[h - 1 - hi]][j]) {
      return false;
    }
  }
  return true;
}

bool check() {
  vector<bool> matched(12, false);
  bool single = w % 2 == 1 ? false : true;
  for (int wi = 0; wi < w; wi++) {
    if (matched[wi]) continue;
    bool m = false;
    for (int wj = wi + 1; wj < w; wj++) {
      if (matching(wi, wj)) {
        m = true;
        matched[wj] = true;
        break;
      }
    }
    if (!m) {
      if (single) return false;
      for (int hi = 0; hi < h / 2; hi++) {
        if (s[hi][wi] != s[h - 1 - hi][wi]) return false;
      }
      single = true;
    }
  }
  return true;
}

bool traverse(int x) {
  if (x * 2 == h) {
    return check();
  }
  for (int hi = 0; hi < h; hi++) {
    if (pos[hi] == -1) {
      pos[hi] = x;
      rpos[x] = hi;
      if (x * 2 + 1 == h) {
        bool result = check();
        pos[hi] = -1;
        return result;
      } else {
        for (int hj = hi + 1; hj < h; hj++) {
          if (pos[hj] == -1) {
            pos[hj] = h - 1 - x;
            rpos[h - 1 - x] = hj;
            bool result = traverse(x + 1);
            pos[hj] = -1;
            if (result) {
              pos[hi] = -1;
              return true;
            }
          }
        }
        pos[hi] = -1;
        return false;
      }
    }
  }
}

int main() {
  cin >> h >> w;
  for (int hi = 0; hi < h; hi++) {
    cin >> s[hi];
  }
  memset(pos, -1, sizeof(pos));
  cout << (traverse(0) ? "YES" : "NO") << endl;
  return 0;
}

