#include<bits/stdc++.h>
using namespace std;

using ll=long long;
using Hash=ll;
const Hash MOD=1e9+9;
const Hash A=124534;
int h,w;
int c;

int main(){
    cin>>h>>w;
    vector<string> s(h);
    for(int i=0;i<h;i++) cin>>s[i];

    c=(h+1)/2;
    int comb=(1<<c)-1;

    while(comb<1<<h){
        vector<string> f=s;
        int id=0;
        for(int i=0;i<h;i++){
            if((comb>>i)&1){
                swap(f[id],f[i]);
                id++;
            }
        }
        assert(id==c);
        vector<Hash> hob(w);
        vector<Hash> hrb(w);
        Hash pAnc=1;
        for(int i=c;i<h;i++) pAnc=pAnc*A%MOD;
        for(int j=0;j<w;j++){
            Hash x=1;
            for(int i=0;i<c;i++) x=x*A%MOD;
            for(int i=c;i<h;i++){
                hob[j]+=f[i][j]*x;
                hob[j]%=MOD;
                x=x*A%MOD;
            }
            x=1;
            for(int i=h-1;i>=c;i--){
                hrb[j]+=f[i][j]*x;
                hrb[j]%=MOD;
                x=x*A%MOD;
            }
        }
        vector<int> perm(c);
        iota(perm.begin(),perm.end(),0);
        do{
            unordered_set<ll> hs;
            for(int j=0;j<w;j++){
                Hash vo=hob[j];
                Hash x=1;
                for(int i=0;i<c;i++){
                    vo+=f[perm[i]][j]*x;
                    vo%=MOD;
                    x=x*A%MOD;
                }
                Hash vr=hrb[j];
                x=pAnc;
                for(int i=c-1;i>=0;i--){
                    vr+=f[perm[i]][j]*x;
                    vr%=MOD;
                    x=x*A%MOD;
                }

                if(hs.count(vr*MOD+vo)){
                    hs.erase(vr*MOD+vo);
                }
                else{
                    hs.insert(vo*MOD+vr);
                }
            }
            if(hs.size()==0 || hs.size()==1 && *hs.begin()/MOD==*hs.begin()%MOD){
                cout<<"YES"<<endl;
                return 0;
            }
        }while(next_permutation(perm.begin(),perm.end()));
        int x=comb&-comb,y=comb+x;
        comb=((comb&~y)/x>>1)|y;
    }
    cout<<"NO"<<endl;
    return 0;
}

