    s[i] = ss;
    sort(ss.begin(), ss.end());
    wordcnt[ss].push_back(i);
  }

  // 乱択
  std::random_device seed_gen;
  std::mt19937 engine(seed_gen());
  auto start = std::chrono::system_clock::now();
  while (true) {
    vector<string> v1, v2;
    for (int j = 0; j < W; j++) {
      string ss;
      for (int i = 0; i < H / 2; i++) ss += s[i][j];
      v1.push_back(ss);
    }
    for (int j = 0; j < W; j++) {
      string ss;
      for (int i = H / 2; i < H / 2 * 2; i++) ss += s[i][j];
      v2.push_back(ss);
    }
    bool ok = true;
    for (int j = 0; j < W; j++) {
      bool tmp = false;
      for (int k = 0; k < W - j; k++) {
        if (v1[j] == v2[k]) {
          swap(v2[k], v2[W-1-j]);
          tmp = true;
          break;
        }
      }
      if (!tmp) {
        ok = false;
        break;
      }
    }
    if (H % 2 == 1) {
      for (int j = 0; j < W / 2; j++) {
        if (s[H-1][j] != s[H-1][W-1-j]) {
          ok = false;
          break;
        }
      }
    }
    if (ok) {
      cout << "YES" << endl;
      return 0;
    }
    auto end = std::chrono::system_clock::now();
    auto diff = end - start;
    if (std::chrono::duration_cast<std::chrono::milliseconds>(diff).count() >= 1996) break;
    shuffle(s.begin(), s.end(), engine);
  }
  cout << "NO" << endl;
  return 0;
}

