const int N=12+1;
int n,m;
char s[N][N];
int dy[N];

bool same(int c1,int c2)
{
	rep(r,0,n-1)
	if(s[r][c1]!=s[dy[r]][c2])return 0;
	return 1;
}
void check()
{
	bool can=m%2;
	bool have[N]={};
	rep(c,0,m-1)
	if(!have[c])
	{
		rep(c2,c+1,m-1)
		if(same(c,c2))
		{	
			have[c]=have[c2]=1;
			break;
		}
		if(!have[c])
		{
			if(!can||!same(c,c))return ;
			have[c]=1;
			can=0;
		}
	}
	puts("YES");
	exit(0);
}

void dfs(int x,bool can)
{
	if(x>=n){check();return ;}
	if(dy[x]!=-1){dfs(x+1,can);return ;}
	if(can){dy[x]=x;dfs(x+1,0);}
	int y=x;
	while(++y<n)
	if(dy[y]==-1)
	{
		dy[x]=y;
		dy[y]=x;
		dfs(x+1,can);
		dy[y]=-1;
	}
	dy[x]=-1;
}

int main()
{
	cin>>n>>m;
	rep(i,0,n-1)scanf("%s",s[i]);
	rep(i,0,n-1)dy[i]=-1;
	dfs(0,n%2);
	puts("NO");
}

