    for(int i = 0; i < used_list.size(); i++){
        if(used_list[i]){
            continue;
        }
        used_list[i] = true;
        det1 = i;
        break;
    }
    if(det1 == -1){
        vector<P> ret_tmp_list;
        ret_list.emplace_back(ret_tmp_list);
        return ret_list;
    }

    for(int i = det1+1; i < used_list.size(); i++){
        if(used_list[i]){
            continue;
        }
        used_list[i] = true;
        det2 = i;

        vector<P> ret_tmp_list;
        vector<vector<P>> x_list = make_pair(used_list);
        for(auto x: x_list){
            x.emplace_back(P(det1, det2));
            ret_list.emplace_back(x);
        }
        used_list[det2] = false;
    }
    if(det2 == -1){
        vector<P> ret_tmp_list;
        ret_tmp_list.emplace_back(P(det1, -1));
        ret_list.emplace_back(ret_tmp_list);
    }

    used_list[det1] = false;
    return ret_list;
}


