			++w[j][S[i][j] - 'a'];
		}
	}
	for (int i = x + 1; i < H - x; ++i) {
		if (h[x] == h[i]) {
			for (int j = x + 1; j < W - x; ++j) {
				if (S[x][x] == S[i][j] && S[x][j] == S[i][x]) {
