			for(int j = 0; j < W; j++){
				for(int k = 0; k < H; k++){
					if(i & (1 << j)) a0[S[j][k] - 'a']++;
					else a1[S[j][k] - 'a']++;
				}
			}
			bool flag = true;
			for(int j = 0; j < 26; j++){
				if(a0[j] != a1[j]){
					flag = false;
					break;
				}
			}
			if(flag) return true;
		}
		return false;
	}else{
		bool flag = false;
		for(int i = 0; i < W; i++){
			int a[26];
			fill(a, a + 26, 0);
			for(int j = 0; j < H; j++){
				a[S[i][j] - 'a']++;
			}
			int cnt = 0;
			int index;
			for(int j = 0; j < 26; j++){
				if(a[j] % 2 == 1){
					cnt++;
					index = j;
				}
			}
			if(cnt > 1) continue;
			if(cnt == 1 && second_search && !may_center[index]) continue;
			for(int j = 0; j < (1 << W); j++){
				int cnt = 0;
				for(int k = 0; k < W; k++){
					if(j & (1 << k)) cnt++;
				}
				if(cnt != W / 2 + 1) continue;
				int a0[26], a1[26];
				fill(a0, a0 + 26, 0);
				fill(a1, a1 + 26, 0);
				for(int k = 0; k < W; k++){
					if(k == i) continue;
					for(int l = 0; l < H; l++){
						if(j & (1 << k)) a0[S[k][l] - 'a']++;
						else a1[S[k][l] - 'a']++;
					}
				}
				bool flag_ = true;
				for(int k = 0; k < 26; k++){
					if(a0[k] != a1[k]){
						flag_ = false;
						break;
					}
				}
				if(flag_){
					if(!second_search) may_center[i] = true;
					flag = true;
				}
			}
		}
		if(flag) return true;
		else return false;
	}
}
int main(){
	fill(may_center, may_center + 12, false);
	second_search = false;
	fill(S[0], S[12], '0');
	cin >> H >> W;
	for(int i = 0; i < H; i++) cin >> S[i];
	if(!is_symmetry()){
		cout << "NO" << endl;
		return 0;
	}
	for(int i = 0; i < 12; i++){
		for(int j = i; j < 12; j++){
			swap(S[i][j], S[j][i]);
		}
	}
