bool is_rev(string &s1, string &s2) {
    assert(s1.size() == s2.size());
    for (int i = 0, j = s2.size()-1; j >= 0; i++, j--)
        if (s1[i] != s2[j]) return false;
    return true;
}

bool check1(int H, int W, string *s, vector<int> &row_indices) {
    vector<string> cols(W, string(H, 0));
    for (int i = 0; i < H; i++)
        for (int j = 0; j < W; j++)
            cols[j][i] = s[row_indices[i]][j];
    vector<bool> used(W, false);
    bool middle_used = false;
    for (int j = 0; j < W; j++) {
        if (used[j]) continue;
        for (int k = j+1; k < W; k++) {
            if (used[k]) continue;
            if (is_rev(cols[j], cols[k])) {
                used[j] = used[k] = true;
                break;
            }
        }
        if (!used[j]) {
            if (W % 2 == 0 || !is_rev(cols[j], cols[j]) || middle_used)
                return false;
            else
                middle_used = true;
        }
    }
    return true;
}

bool check(int H, int W, string *s, int a, int b) {
    vector<int> rows;
    for (int i = 0; i < H; i++)
        if ((a >> i) & 1) rows.push_back(i);
    for (int i = 0; i < H; i++)
        if ((b >> i) & 1) rows.push_back(i);
    auto l = rows.begin() + __builtin_popcount(a), r = rows.end();
    do {
        if (check1(H, W, s, rows)) return true;
    } while (next_permutation(l, r));
    return false;
}


