int h,w;
bool solve(int id,vector<string>& s){
    if(id==h/2){
        vector<int> flag(w,false);
        for(int j=0;j<w;j++){
            if(flag[j]) continue;
            for(int k=j+1;k<w;k++){
                bool isok=true;
                for(int i=0;i<h;i++){
                    if(s[i][j]!=s[h-1-i][k]){
                        isok=false;
                        break;
                    }
                }
                if(isok){
                    flag[j]=flag[k]=true;
                    break;
                }
            }
        }
        int cnt=count(flag.begin(),flag.end(),false);
        if(cnt==2) return false;
        if(cnt==0) return true;
        for(int j=0;j<w;j++){
            if(!flag[j]){
                for(int i=0;i<h;i++){
                    if(s[i][j]!=s[h-1-i][j]) return false;
                }
                return true;
            }
        }        
    }
    for(int i=id+1;i<h-id;i++){
        swap(s[i],s[h-id-1]);
        if(solve(id+1,s)) return true;
        swap(s[i],s[h-id-1]);
    }
    return false;
}

