bool mark[15] = {0};
ll incomp = 0;
bool match(ll i){
    if(i == n)return (incomp <= n%2);
    if(mark[i])return match(i+1);
    bool ans = 0;
    for(int c1 = 0; c1 < sz(C[i]); c1++){
        ll a = C[i][c1];
        if(a > i && !mark[a]){
            mark[a] = 1;
            mark[i] = 1;
            ans |= match(i+1);
            mark[a] = 0;
            mark[i] = 0;
        }
    }
    if(incomp < n%2){
        incomp++;
        ans |= match(i+1);
        incomp--;
    }
    return ans;
}

