#include<bits/stdc++.h>
using namespace std;

int H, W;
vector<string> S;

bool check(auto match) {
  vector<bool> used(H);
  for(auto i=0; i<H; ++i) if(!used[i]) {
    for(auto j=i+1; j<H; ++j) if(!used[j]) {
      auto same = true;
      for(auto k=0; k<match.size(); k+=2) {
        if(S[i][match[k]]   == '*') continue;
        if(S[i][match[k+1]] == '*') continue;
        if(S[j][match[k]]   == '*') continue;
        if(S[j][match[k+1]] == '*') continue;
        same &= (S[i][match[k]] == S[j][match[k+1]]);
        same &= (S[i][match[k+1]] == S[j][match[k]]);
      }
      if(!same) continue;
      used[i] = used[j] = true;
      break;
    }
    if(!used[i]) return false;
  }
  return true;
}

bool dfs(auto match, auto used, auto n) {
  if(n == W) return check(match);
  if(used[n]) return dfs(match, used, n+1);
  match.emplace_back(n);
  for(auto i=n+1; i<W; ++i) if(!used[i]){
    match.emplace_back(i);
    used[i] = true;
    if(dfs(match, used, n+1)) return true;
    match.pop_back();
    used[i] = false;
  }
  return false;
}

string solve() {
  return dfs(vector<int>(), vector<bool>(W), 0) ? "YES" : "NO";
}

int main() {
  cin >> H >> W;
