void dfs(int n, vector<pint> vec, set<int> rem) {
    if (rem.empty()) {
        tmps.push_back(vec);
        return;
    }

    int f = *(rem.begin());
    rem.erase(f);
    set<int> nrem = rem;
    EACH(it, nrem) {
        int s = *it;
        vec.push_back(pint(f, s));
        rem.erase(s);
        dfs(n, vec, rem);
        vec.pop_back();
        rem.insert(s);
    }
}

vector<vector<pint> > makecups(int n) {
    set<int> rem;
    for (int i = 0; i < n; ++i) rem.insert(i);
    vector<pint> vec;
    tmps.clear();

    if (n % 2 == 0) {
        dfs(n, vec, rem);
    }
    else {
        for (int i = 0; i < n; ++i) {
            vec.push_back(pint(i, i));
            rem.erase(i);
            dfs(n, vec, rem);
            vec.pop_back();
            rem.insert(i);
        }
    }

    return tmps;
}

