int baris,kolom;
char petas[15][15];
bool sudahkol[15],sudahbar[15],ans=false;
vector <int> kiri,kanan;
bool check(){
	for(int i=0;i<baris;i++)
		sudahbar[i]=false;
	int kesempatan=(baris&1)?1:0;
	for(int i=0;i<baris;i++)
	{
		if(sudahbar[i])
			continue;
		sudahbar[i]=true;
		bool dapet=false;
		for(int j=i+1;j<baris;j++)
		{
			bool bisadenganini=true;
			for(int k=0;k<kiri.size();k++)
			{
				if(petas[i][kiri[k]]!=petas[j][kanan[k]])
					bisadenganini=false;
				if(petas[i][kanan[k]]!=petas[j][kiri[k]])
					bisadenganini=false;
			}
			if(bisadenganini)
			{
				dapet=true;
				sudahbar[j]=true;
				break;
			}
		}

		if(!dapet)
		{
			bool bisadenganini=true;
			for(int k=0;k<kiri.size();k++)
				if(petas[i][kiri[k]]!=petas[i][kanan[k]])
					bisadenganini=false;
			if(bisadenganini&&kesempatan)
				kesempatan--;
			else
				return false;
		}
	}
	assert(kesempatan==0);
	return true;
}
void BF(int sisa){
	if(sisa>=2)
	{
		int terkecil=-1;
		for(int i=0;i<kolom;i++)
		{
			if(sudahkol[i])
				continue;
			if(terkecil==-1)
				terkecil=i;
			else
			{
				sudahkol[terkecil]=true;
				sudahkol[i]=true;

				kiri.pb(terkecil);
				kanan.pb(i);
				BF(sisa-2);
				if(ans)
					return;
				kiri.pop_back();
				kanan.pop_back();

				sudahkol[terkecil]=false;
				sudahkol[i]=false;
			}
		}
	}
	else if(sisa==1)
	{
		int tersisa=-1;
		for(int i=0;i<kolom;i++)
		{
			if(sudahkol[i])
				continue;
			tersisa=i;
			break;
		}
		kiri.pb(tersisa);
		kanan.pb(tersisa);
		sudahkol[tersisa]=true;
		BF(0);
		if(ans)
			return;
		sudahkol[tersisa]=false;
		kiri.pop_back();
		kanan.pop_back();
	}
	else
	{
		if(check())
			ans=true;
	}
}
int main()
{
	memset(sudahkol,false,sizeof(sudahkol));
	memset(sudahbar,false,sizeof(sudahbar));

	scanf("%d%d",&baris,&kolom);
	for(int i=0;i<baris;i++)
		scanf("\n%s",&petas[i]);
	BF(kolom);
	if(ans)
		printf("YES\n");
	else
		printf("NO\n");
}

