struct {
    Int h, w;
    Vector<String> s, t;
    Bool possible;
    Vector<Int> col;

    void check(Int b, Bool lonely) {
        Int x;
        for (x = 0; x < w; ++x) {
            if (!((b >> x) & 1)) break;
        }

        if (x == w) {
            possible = true;
            return;
        }

        String z = t[x];
        std::reverse(z.begin(), z.end());

        for (Int y = x + 1; y < w; ++y) {
            if (!((b >> y) & 1)) {
                if (t[y] == z) {
                    check(b | (1 << x) | (1 << y), lonely);
                }
            }
        }

        if (!lonely && z == t[x]) {
            check(b | (1 << x), true);
        }
    }

    void align() {
        for (Int y = 0; y < w; ++y) {
            for (Int x = 0; x < h; ++x) {
                t[y][x] = s[col[x]][y];
            }
        }
        check(0, false);
    }

    void enumcol(Int b, Int i) {
        Int x;
        for (x = 0; x < h; ++x) {
            if (!((b >> x) & 1)) break;
        }
        if (x == h) {
            align();
            return;
        }

        Bool lonely = true;
        for (Int y = x + 1; y < h; ++y) {
            if (!((b >> y) & 1)) {
                lonely = false;
                col[i] = x;
                col[h - i - 1] = y;
                enumcol(b | (1 << x) | (1 << y), i + 1);
            }
        }

        if (lonely) {
            col[i] = x;
            enumcol(b | (1 << x), i + 1);
        }
    }

    void operator()() {
        possible = false;
        std::cin >> h >> w;

        s.resize(h), t.resize(w);
        for (auto& x : s) std::cin >> x;
        for (auto& y : t) y.resize(h);

        col.resize(h);
        enumcol(0, 0);
    }
} solve;

int main() {
    solve();
    std::cout << (solve.possible ? "YES" : "NO") << std::endl;
    return 0;
}

