int H , W;

int marked[N] , match[N];
char s[N][N]; bool book[N];

bool check(){
	memset(marked , 0 , sizeof(marked));
	for(int i = 1 ; i <= W ; i++){
		if(marked[i]) continue;
		for(int j = 1 ; j <= W ; j++){
			if(marked[j] || (i == j)) continue;
			bool flag = true;
			for(int k = 1 ; k <= H ; k++)
				if(s[k][i] != s[match[k]][j]){
					flag = false;
					break;
				}
			if(flag){
				marked[i] = marked[j] = 1;
				break;
			}
		}
	}
	int pos = 0 , cnt = 0;
	for(int i = 1 ; i <= W ; i++)
		if(!marked[i]) cnt++ , pos = i;
	if(cnt >= 2 || (cnt && (W % 2 == 0))) return false;
	if(cnt == 1)
		for(int i = 1 ; i <= H ; i++)
			if(s[i][pos] != s[match[i]][pos])
				return false;
	return true;
}

bool ans;

void dfs(int cnt , int flag){
	if(cnt > ((H + 1) >> 1)){
		if(check())
			ans = true;
		return;
	}
	else{
		for(int i = cnt ; i <= H ; i++){
			if(!match[i]){
				for(int j = i + 1 ; j <= H ; j++)
					if(!match[j]){
						match[i] = j; match[j] = i;
						dfs(cnt + 1 , flag);
						match[i] = match[j] = 0;
					}
				if(flag){
					match[i] = i;
					dfs(cnt + 1 , 0);
				}
			}
		}
	}
}

