class SolveCSub {


public:

	ll H, W, N;
	string S[13];
	bool can_center[13];
	vector<ll> pair_n[13];
	bool ans;

	bool Solve() {

		lp(i, 13)pair_n[i].clear();

		ans = false;
		ll aa[13] = {};

		Search();

		if (H >= 2) {
			Judge(aa, -1, -1);
		}
		else {
			ans = can_center[0];
		}

		return ans;
	}


	void Search() {

		for (ll i = 0; i < H - 1; i++) {
			for (ll j = i + 1; j < H; j++) {
				if (IsPair(i, j))pair_n[i].push_back(j);
			}
		}

		lp(i, H)can_center[i] = JudgeCenter(i);

	}

	bool IsPair(ll h1, ll h2) {

		x = W%2;

		for (ll i = 0; i < W; i++) {
			a = S[h1][i] - 'a';
			b = S[h2][i] - 'a';
			c = S[h1][W-1-i] - 'a';
			d = S[h2][W-1-i] - 'a';
			if (a != d || b != c) {
				if (x == 0)return false;
				else x--;
			}
		}

		return true;

	}

	bool JudgeCenter(ll h) {
		lp(i, W) {
			if (S[h][i] != S[h][W - 1 - i])return false;
		}
		return true;
	}

	void Judge(ll used[13], ll pre1, ll pre2) {
		ll now[13] = {};
		lp(i, 13)now[i] = used[i];
		if (pre1 >= 0) {
			now[pre1] = 1;
			now[pre2] = 1;
			c = H % 2;
			lp(i, H) {

				if (now[i] == 0) {
					if (c == 1 && can_center[i] == true)c--;
					else break;
				}

				if (i == H - 1)ans = true;

			}
		}

		for (ll i = pre1 + 1; i < H; i++) {
			if (now[i] == 0) {
				for (ll j = 0; j < pair_n[i].size(); j++) {
					e = pair_n[i][j];
					if (now[e] == 0)Judge(now, i, e);
				}
			}
		}

	}

};

