			Judge(aa, -1, -1 ,-1);
		}
		else {
			ans = can_center[0];
		}

		if (ans)cout << "YES" << endl;
		else cout << "NO" << endl;

	}

	void Read() {
		cin >> H >> W;
		lp(i, H)cin >> S[i];


		solve_sub.H = W;
		solve_sub.W = H;

	}

	void Search() {

		for (ll i = 0; i < H - 1; i++) {
			for (ll j = i + 1; j < H; j++) {
				if (IsPair(i, j))pair_n[i].push_back(j);
			}
		}

		lp(i, H)can_center[i] = JudgeCenter(i);

	}

	bool IsPair(ll h1, ll h2) {

		ll p_num[27][27] = {};

		for (ll i = 0; i < W; i++) {
			a = S[h1][i] - 'a';
			b = S[h2][i] - 'a';
			p_num[a][b]++;
		}

		c = W % 2;

		for (ll i = 0; i < 27; i++) {
			for (ll j = 0; j < 27; j++) {
				if (p_num[i][j] > 0) {
					if (i == j) {
						p_num[i][j] %= 2;
						c -= p_num[i][j];
						if (c < 0)return false;
					}
					else {
						if (p_num[i][j] != p_num[j][i])return false;
					}
				}
			}
		}

		return true;

	}

	bool JudgeCenter(ll h) {
		ll A[27] = {};
		lp(i, W)A[S[h][i] - 'a']++;
		c = W % 2;
		lp(i, 27) {
			c -= A[i] % 2;
			if (c < 0)return false;
		}
		return true;
	}

	void Judge(ll used[13], ll pre1, ll pre2, ll co) {
		if (ans)return;
		ll now[13] = {};
		lp(i, 13)now[i] = used[i];

		if (pre1 >= 0) {
			now[pre1] = co;
			now[pre2] = H-1-co;
			if (co >= H / 2 - 1) {
				c = H % 2;
				lp(i, H) {

					if (now[i] == -1) {
						if (c == 1 && can_center[i] == true) {
							c--;
							now[i] = H/2;
						}
						else break;
					}

					if (i == H - 1) {
						lp(j, W)STate[j].clear();
						lp(j, H) {
							lp(k, 13) {
								if (now[k] == j) {
									lp(kk, W)STate[kk] += S[k][kk];
									break;
								}
							}
						}

						lp(j, W)solve_sub.S[j] = STate[j];

						if (solve_sub.Solve())ans = true;
					}

				}
				return;
			}

		}

		for (ll i = pre1 + 1; i < H; i++) {
			if (now[i] == -1) {
				for (ll j = 0; j < pair_n[i].size(); j++) {
					e = pair_n[i][j];
					if (now[e] == -1)Judge(now, i, e,co+1);
				}
			}
		}

	}

};

