void check() {
  string buf(W, ' ');
  unordered_multiset<string> ss;
  for(int i = 0; i < H; ++i) {
    for(int j = 0; j < W; ++j) buf[j] = S[i][P[j]];
    ss.insert(buf);
  }
  int fail = 0;
  while(!ss.empty()) {
    string s = *ss.begin(); ss.erase(s);
    reverse(s.begin(), s.end());
    if(!ss.count(s)) ++fail;
    if(fail >= 2) return;
    ss.erase(s);
  }
  R = true;
}

void go() {
  if(2 * K == W) { check(); return; }
  int s; for(s = 0; ; ++s) if(!U[s]) break;
  P[K] = s; U[s] = true;
  if(2 * K + 1 == W) { check(); U[s] = false; return; }
  for(int t = 0; t < W; ++t) if(!U[t]) {
    P[W - 1 - K] = t; U[t] = true;
    ++K; go(); --K;
    U[t] = false;
  }
  U[s] = false;
}

