	return true;
}

bool go(int m, int cur, bool mid) {
	if (m == 0) {
		assert(cur == H/2);
		return isGood();
	}
	if (mid && go(m & (m-1), cur, false)) {
		return true;
	}

	if (m != (m & -m)) {
		int i = 0;
		while (!(m & (1 << i))) i++;
		for (int j = i+1; j < H; j++) {
			if (m & (1 << j)) {
				P[cur][0] = i;
				P[cur][1] = j;
				if (go(m & ~(1<<i) & ~(1<<j), cur+1, mid)) {
					return true;
				}
			}
		}
	}
	return false;
}

int main() {
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	cin >> H >> W;
	for (int i = 0; i < H; i++) {
		cin >> S[i];
	}
	puts(go((1<<H) - 1, 0, H%2 == 1) ? "YES" : "NO");

	return 0;
}

