bool bt(bool sp) {
    // dbg(sz(have), (int)sp);
    if (sz(have) == 0) {
        bool sp = c%2;
        rep(i,0,c) take[i] = false;
        rep(i,0,c) {
            rep(j,0,c) if (!take[i] && !take[j] && ca[i].find(j) != ca[i].end()) {
                take[i] = true;
