                break;
            }
            if (sp && !take[i] && ca[i].find(i) != ca[i].end()) {
                take[i] = true;
                sp = false;
            }
            if (!take[i]) return false;
        }
        return true;
    }

    set<int> tca[13];
    rep(i,0,c) tca[i] = ca[i];

    rep(i,0,sz(have)) {
        if (i == 0 && !sp) continue;
        rep(i,0,c) ca[i] = tca[i];

        upd(have[0], have[i]);

