using namespace std;
template <typename Functor>
struct fix_type
{
    Functor functor;
    template <typename... Args>
    decltype(auto) operator()(Args&&... args) const& { return functor(functor, std::forward<Args>(args)...); }
};
template <typename Functor>
fix_type<typename std::decay<Functor>::type> fix(Functor&& functor) { return {std::forward<Functor>(functor)}; }
int main()
{
    int H, W;
    cin >> H >> W;
    vector<string> S(H);
    for (int i = 0; i < H; i++) { cin >> S[i]; }
    auto f = [&](const string& s1, const string& s2) {
        for (int i = 0; i < H; i++) {
            if (s1[i] != s2[H - 1 - i]) { return false; }
        }
        return true;
    };
    vector<vector<int>> rs;
    auto rec = fix([&](auto&& self, vector<int> r, const int num) -> void {
        if (num == (H + 1) / 2) {
            rs.push_back(r);
        } else {
            int head = 0;
            for (; r[head] != -1; head++) {}
            r[head] = num;
            if (H % 2 == 1 and num == (H - 1) / 2) {
                self(self, r, num + 1);
            } else {
                for (int tail = head + 1; tail < H; tail++) {
                    if (r[tail] == -1) {
                        r[tail] = num;
                        self(self, r, num + 1);
                        r[tail] = -1;
                    }
                }
            }
        }
    });
    rec(vector<int>(H, -1), 0);
    for (const auto& row : rs) {
        vector<int> r(H, -1);
        for (int i = 0; i < H; i++) {
            if (r[row[i]] == -1) {
                r[row[i]] = i;
            } else {
                r[H - 1 - row[i]] = i;
            }
        }
        vector<string> cols(W);
        for (int i = 0; i < W; i++) {
            for (int j = 0; j < H; j++) { cols[i].push_back(S[r[j]][i]); }
        }
        vector<bool> unused(W, true);
        int zuru = 0;
        bool ans = true;
        for (int i = 0; i < W; i++) {
            if (not unused[i]) { continue; }
            for (int j = i + 1; j < W; j++) {
                if (unused[j] and f(cols[i], cols[j])) {
                    unused[i] = false, unused[j] = false;
                    break;
                } else if (j == W - 1) {
                    if (W % 2 == 1 and f(cols[i], cols[i])) {
                        zuru++;
                        unused[i] = false;
                    } else {
                        ans = false;
                    }
                }
            }
        }
        if (ans and zuru <= 1) {
            cout << "YES" << endl;
            return 0;
        }
    }
}

#include <bits/stdc++.h>
#define FOR(i,k,n)  for(int i = (k);i < (n);++i)
#define REP(i,n)    FOR(i,0,n)
#define ALL(x)      begin(x),end(x)

using namespace std;
using vecint = vector<int>;
using ll = int64_t;
int h,w;

bool isok_impl(const vector<string>& t) {
  REP(i,h)REP(j,w) {
    if (t[i][j] != t[h-i-1][w-j-1]) return false;
  }
  return true;
}

bool isok_h(const vector<string>& t, int k) {
  if (k >= h/2) return isok_impl(t);
  FOR(i,k,h-k) {
    vector<string> s = t;
    swap(s[i], s[h-k-1]);
    if (s[0][k] != s[h-1][w-k-1]) continue;
    if (isok_h(s, k+1)) return true;
  }
  return false;
}

bool isok_w(const vector<string>& t, int k) {
  if (k >= w/2) return isok_impl(t);
  FOR(j,k,w-k) {
    vector<string> s = t;
    REP(p,h) swap(s[p][j], s[p][w-k-1]);
    if (s[k][0] != s[h-k-1][w-1]) continue;
    if (isok_w(s, k+1)) return true;
  }
  return false;
}

bool isok(const vector<string>& t, int k) {
  int n = max(h,w) - min(h,w);
  if (n == 0) return isok_impl(t);
  if (h > w) {
    return isok_h(t, k);
  } else {
    return isok_w(t, k);
  }
}

bool solve(const vector<string>& t, int k = 0) {
  if (2*k >= min(h,w)) return isok(t, k);
  FOR(i,k,h-k)FOR(j,k,w-k) {
    vector<string> s = t;
    swap(s[i], s[h-k-1]);
    REP(p,h) swap(s[p][j], s[p][w-k-1]);
    if (s[k][k] != s[h-k-1][w-k-1]) continue;
    if (solve(s, k+1)) return true;
  }
  return false;
}

int main()
{
  cin>>h>>w;
  vector<string> t(h);
  REP(i,h) cin>>t[i];
  bool res = solve(t);
  if (res) {
    cout << "YES" << endl;
  } else {
    cout << "NO" << endl;
  }
  return 0;
}

