    }
    if(W%2 == 1) {
      for(int y = 0; y < H; y++) {
        checkS[y][W/2] = S[y][soloIndex];
      }
    }
    return check();
  }

  if(!pairUsed[pos]) {
    pairUsed[pos] = true;
    for(int x = pos+1; x < W; x++) {
      if(x != soloIndex && !pairUsed[x]) {
        pairUsed[x] = true;
        vec.push_back(II(pos, x));
        if(dfs(pos+1)){
