		for(int i = 2 ; i <= H - 1; ++i) {
			if(mat[i]) continue;
			for(int j = i + 1 ; j <= H - 1; ++j) {
				if(mat[j]) continue;
				bool f = 1;
				for(int k = 1 ; k <= W ; ++k) {
					if(S[i][k] != S[j][W - k + 1]) {
						f = 0;
						break;
					}
				}
				if(f) {mat[i] = j;mat[j] = i;break;}
			}
			if(!mat[i] && cnt < 1 && (H & 1)) {
				++cnt;
				for(int k = 1 ; k <= W ; ++k) {
					if(S[i][k] != S[i][W - k + 1]) return 0;
				}
				mat[i] = i;
			}
			else if(!mat[i]) return 0;
		}
		return 1;
	}
	if(c == W - c + 1) {
		for(int i = 1 ; i <= W ; ++i) {
			if(vis[i]) continue;
			if(S[1][i] == S[H][i]) {
				swapCol(i,c);
				vis[c] = 1;
				if(match(c - 1)) return 1;
				vis[c] = 0;
				swapCol(i,c);
			}
		}
	}
	else {
		for(int i = 1; i <= W; ++i) {
			if(vis[i]) continue;
			if(matC[idC[c]][idC[i]]) {
				if(S[1][c] == S[H][i] && S[1][i] == S[H][c]) {
					vis[c] = vis[W - c + 1] = 1;
					swapCol(i,W - c + 1);
					if(match(c - 1)) return 1;
					swapCol(i,W - c + 1);
					vis[c] = vis[W - c + 1] = 0;
				}
			}
		}
	}
	return 0;
}
