struct node {
	int y, next;
}a[Maxm*2]; int first[Maxn], len;
void ins(int x, int y) {
	len++;
	a[len].y = y;
	a[len].next = first[x]; first[x] = len;
}
int n, m;
char s[20][20];
int pp[20];
int match[20]; bool v[20];
int ans = 0;
bool fc(int x) {
	for(int k = first[x]; k; k = a[k].next){
		int y = a[k].y;
		if(!v[y]){
			v[y] = true;
			if(!match[y] || fc(match[y])){ match[y] = x; return true; }
		}
	}
	return false;
}
void check() {
	int po = 0;
	int i, j, k;
	if(n&1){
		for(i = 1; i <= n; i++) if(!pp[i]) po = i;
	}
	if(m&1){
		for(int d = 1; d <= m; d++){
			bool bo = true;
			for(k = 1; k <= n; k++){
				if(pp[k] > k){
					if(s[k][d] != s[pp[k]][d]){ bo = false; break; }
				}
			}
			if(bo == false) continue;
			len = 0; memset(first, 0, sizeof(first));
			memset(match, 0, sizeof(match));
			for(i = 1; i <= m; i++) if(i != d){
				for(j = 1; j <= m; j++) if(j != d){
					if(i == j) continue;
					bool bk = true;
					for(k = 1; k <= n; k++){
						if(pp[k] > k){
							if(s[k][i] != s[pp[k]][j]){ bk = false; break; }
						}
					}
					if(n&1 && s[po][i] != s[po][j]) bk = false;
					if(bk) ins(i, j);
				}
			}
			int res = 0;
			for(i = 1; i <= m; i++) if(i != d){
				memset(v, false, sizeof(v));
				if(fc(i)) res++;
			}
			if(res == m-1){ ans = 1; break; }
		}
	} else {
		len = 0; memset(first, 0, sizeof(first));
		memset(match, 0, sizeof(match));
		for(i = 1; i <= m; i++){
			for(j = 1; j <= m; j++){
				if(i == j) continue;
				bool bk = true;
				for(k = 1; k <= n; k++){
					if(pp[k] > k){
						if(s[k][i] != s[pp[k]][j]){ bk = false; break; }
					}
				}
				if(n&1 && s[po][i] != s[po][j]) bk = false;
				if(bk) ins(i, j);
			}
		}
		int res = 0;
		for(i = 1; i <= m; i++){
			memset(v, false, sizeof(v));
			if(fc(i)) res++;
		}
		if(res == m) ans = 1;
	}
}
void dfs(int x, int op) {
	if(ans == 1) return;
	if(x == n+1){ check(); return; }
	if(pp[x] > 0){ dfs(x+1, op); return; }
	for(int i = x+1; i <= n; i++){
		if(!pp[i]){
			pp[i] = x; pp[x] = i;
			dfs(x+1, op);
			pp[i] = pp[x] = 0;
		}
	}
	if(n&1 && !op) dfs(x+1, 1);
}
int main() {
	int i, j, k;
	scanf("%d%d", &n, &m);
	for(i = 1; i <= n; i++) scanf("%s", s[i]+1);
	dfs(1, 0);
	if(ans == 1) printf("YES\n");
	else printf("NO\n");
	return 0;
}

