  cin>>str;
  if(h%2) str = rot90(str), swap(h,w);

  vector<string> t1(h),t2(h);  
  int ans = 0;
  if(h%2 == 0 && w%2 ==0) ans = dfs(0,0,t1,t2,-1);
  else if(w%2 && h%2){
    for(int i=0;i<h;i++)
      for(int j=0;j<w;j++) {
        memset(used,0,sizeof(used));
        if(ans) break;
        string s1 = str[i];
        string s2;
        for(int k=0;k<h;k++) s2 += str[k][j];
        int a = count(s1), b = count(s2);
        if(a == -1 || b == -1 || a != b) continue;
        ans |= dfs(1<<j,0,t1,t2,i);
      }
  }
  else {
    for(int j=0;j<w;j++){
      memset(used,0,sizeof(used));
      if(ans) break;
      string s2;
      for(int k=0;k<h;k++) s2 += str[k][j];
      if(count(s2) == -1) continue;
      ans |= dfs(1<<j,0,t1,t2,-1);
    }
  }

  cout<<(ans? "YES":"NO")<<endl;

  return 0;
}

