        if (w%2 != 0) {
          str[w/2] = e[v[0]];
          idx++;
        }
        for(int j=0; j*2+1+idx<w; j++) {
          str[j] = e[v[j*2+idx]];
          str[w-1-j] = e[v[j*2+1+idx]];
        }
        //cerr << str << endl;
        vs.insert(str);
      }

      bool center = false;
      auto it = vs.begin();
      while(it != vs.end()) {
        string now = (*it);
        string nowr = now;
        reverse(all(nowr));
        it = vs.erase(it);

        if (it != vs.end()) {
