void brute(int cnt) {
	if (cnt > np) {
		check();
		return;
	}
	int p1 = -1;
	for (int i = all_pairs[cnt - 1].first + 1; i <= n; ++i) {
		if (!used[i]) {
			used[(p1 = i)] = true;
			break;
		}
	}
	all_pairs[cnt].first = p1;
	for (int i = all_pairs[cnt - 1].first + 2; i <= n; ++i) {
		if (used[i]) continue;
		all_pairs[cnt].second = i;
		used[i] = true;
		brute(cnt + 1);
		used[i] = false;
	}
	used[p1] = false;
}

