inline int mt(int a, int b) {
    return 1ll * a * b % mod;
}

inline int add(int a, int b) {
    a += b;
    if(a >= mod)
        a -= mod;
    if(a < 0)
        a += mod;
    return a;
}

inline int binpow(int n, int k) {
    int res = 1;
    while(k) {
        if(k & 1)
            res = mt(res, n);
        n = mt(n, n);
        k >>= 1;
    }
    return res;
}

inline int H(vector <pii> cur) {
    int res = 0;
    for(int i = 0; i < cur.size(); ++i)
        res = (res + binpow(41, cur[i].f * 100 + cur[i].se)) % mod;
    return res;
}

void rec(int i) {
    if(i == n) {
        is.pb(cur);
    }
    else {
        if(used[i])
            rec(i + 1);
        else {
            if(n % 2 == 1 && cur.size() == n/2) {
                cur.pb({i, i});
                rec(i + 1);
                cur.ppb();
            }
            for(int j = i + 1; j < n; ++j)
                if(!used[j]) {
                    used[j] = true;
                    cur.pb({i, j});
                    rec(i + 1);
                    cur.ppb();
                    used[j] = false;
                }
        }
    }
}

void recm(int i) {
