}


void cal(){
    for(ll i = 0; i < M[0].size()/2; i++){
        for(ll j = i+1; j <= (M[0].size()-1-i); j++){
            if(M[0][i] == M[H-1][j]){
                swapl(j, W-1-i);
                break;
            }
        }
    }
    return ;
}

