using ll = long long;

int H, W;
string S[12];

int wc[12][26];
int matched[12];

bool eq(int x, int y) {
    for (int i = 0; i < 26; ++i) {
        if (wc[x][i] != wc[y][i]) return false;
    }
    return true;
}

int main() {
    cin >> H >> W;
    for (int j = 0; j < H; ++j) cin >> S[j];
    for (int j = 0; j < H; ++j) fill(wc[j], wc[j]+W, 0);
    fill(matched, matched+H, 0);

    for (int j = 0; j < H; ++j) {
        fill(wc[j], wc[j]+26, 0);
        for (int k = 0; k < W; ++k) {
            ++wc[j][S[j][k]-'a'];
        }
    }

    int mc = 0;

    for (int j = 0; j < H; ++j) {
        if (matched[j]) continue;
        for (int k = j+1; k < H; ++k) {
            if (!matched[k] && eq(j, k)) {
                matched[j] = matched[k] = true;
                mc += 2;
            }
        }
    }

    bool ok = mc == H;
    if (mc == H-1) {
        int idx = -1;
        for (int j = 0; j < H; ++j) {
            if (!matched[j]) {
                idx = j;
                break;
            }
        }

        int odd = 0;
        for (int i = 0; i < 26; ++i) {
            odd += wc[idx][i] % 2;
        }

        ok = (W % 2 == 0 && odd == 0) || (W % 2 == 1 && odd == 1);
    }

    cout << (ok ? "YES" : "NO") << endl;
    return 0;
}

