vector<vector<int>> pairs;

void Rec(int s, vector<int>& curr) {
	if (s == 0) {
		pairs.push_back(curr);
		return;
	}

	int v1, v2;
	REP(i, 0, W) {
		if ((s >> i) & 1) {
			v1 = i;
			s -= 1 << i;
			curr.push_back(v1);
			break;
		}
	}

	REP(i, 0, W) {
		if ((s >> i) & 1) {
			v2 = i;
			s -= 1 << i;
			curr.push_back(v2);
			Rec(s, curr);

			s += 1 << i;
			curr.pop_back();
		}
	}
	curr.pop_back();
	return;
}

void Pre() {
	if (W % 2 == 0) {
		vector<int> vec;
		Rec((1 << W) - 1, vec);
	} else {
		REP(i, 0, W) {
			vector<int> vec(2, i);
			Rec((1 << W) - 1 - (1 << i), vec);
		}
	}
}

uint pop_count(uint n) {
	n = (n & 0x55555555) + ((n >> 1) & 0x55555555);
	n = (n & 0x33333333) + ((n >> 2) & 0x33333333);
	n = (n & 0x0f0f0f0f) + ((n >> 4) & 0x0f0f0f0f);
	n = (n & 0x00ff00ff) + ((n >> 8) & 0x00ff00ff);
	n = (n & 0x0000ffff) + ((n >> 16) & 0x0000ffff);
	return n;
}

int main() {
