		cin >> s[i];
	}

	Pre();

	REP(p, 0, pairs.size()) {
		Fill(DP, 0);
		DP[0] = true;
		REP(i, 0, H) {
			DP[1 << i] = true;
		}

		REP(i, 1, 1 << H) {
			if (pop_count(i) % 2 != H % 2) continue;


			REP(j, 0, H) {
				if (!(i & (1 << j))) continue;
				REP(k, j + 1, H) {
					if (!(i & (1 << k))) continue;

					bool ok = true;
					REP(n, 0, (W + 1) / 2) {
						if (s[j][pairs[p][2 * n]] != s[k][pairs[p][2 * n + 1]]) {
