  while(!ss.empty()) {
    auto it = ss.begin(); string s = *it; ss.erase(it);
    string r = s; reverse(r.begin(), r.end()); it = ss.find(r);
    if(it == ss.end()) {
      if(r == s && !failed) failed = true; else return;
    }
    else ss.erase(it);
  }
  R = true;
}

void go() {
  if(2 * K == W) { check(); return; }
  int s; for(s = 0; ; ++s) if(!U[s]) break;
  P[K] = s; U[s] = true;
  if(2 * K + 1 == W) { check(); U[s] = false; return; }
  for(int t = 0; t < W; ++t) if(!U[t]) {
    P[W - 1 - K] = t; U[t] = true; ++K; go(); --K; U[t] = false;
  }
  U[s] = false;
}

