bool mark1[50],mark2[50];
bool chk1(int x,int y){
	for (int i=0;i<26;i++){
		if (cnt1[x][i]^cnt1[y][i])return 0;
	}
	return 1;
}
bool chk2(int x,int y){
	for (int i=0;i<26;i++){
		if (cnt2[x][i]^cnt2[y][i])return 0;
	}
	return 1;
}
