int main(int argc, char** argv) {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m;
    cin >> n >> m;

    vector<string> M(n);
    for (int i = 0; i < n; ++i) {
        cin >> M[i];
    }

    vector<int> other(n, 0);
    auto match = [&](int a, int b, vector<int>& other) {
        // cout << "match " << a << " " << b << endl;
        for (int i = 0; i < n; ++i) {
            if (M[i][a] != M[other[i]][b]) {
                return false;
            }
        }
        return true;
    };

    auto check = [&](vector<int>& other) {
        // for (int i = 0; i < n; ++i) {
        //     cout << i << ":" << other[i] << ' ';
        // }
        // cout << endl;

        int used = 0;
        int mid = 0;
        for (int i = 0; i < m; ++i) {
            if (used & (1 << i)) {
                continue;
            }
            bool ok = false;
            for (int j = i + 1; j < m; ++j) {
                if (used & (1 << j)) {
                    continue;
                }
                if (match(i, j, other)) {
                    ok = true;
                    used |= 1 << i;
                    used |= 1 << j;
                    break;
                }
            }
            if (!ok) {
                if (!match(i, i, other)) {
                    return false;
                } 
                ++mid;
                if (mid > 1 || m % 2 == 0) {
                    return false;
                }
                used |= i;
            }
        }
        return true;
    };

    function<bool(int, int, int)> dfs = [&](int i, int rem, int used) -> bool {
        // cout << "dfs " << i << " " << used << endl;
        if (i == n) {
            if (check(other)) {
                return true;
            }
        }

        if (used & (1 << i)) {
            return dfs(i + 1,  rem, used);
        }

        used |= 1 << i;
        if (rem > 0) {
            other[i] = i;
            if (dfs(i + 1, rem - 1, used)) {
                return true;
            }
            other[i] = 0;
        }
        if (rem == 0 || i + 1 < n) {
            for (int j = i + 1; j < n; ++j) {
                if ((used & (1 << j)) == 0) {
                    other[i] = j;
                    other[j] = i;

                    if (dfs(i + 1, rem, used | (1 << j))) {
                        return true;
                    }

                    other[i] = 0;
                    other[j] = 0;
                }
            }
        }
        return false;
    };

    if (dfs(0, n % 2, 0)) {
        cout << "YES\n";
    } else {
        cout << "NO\n";
    }


    return 0;
}

