bool stp(string &s, string &t) {
	//sとtで点対称配置になるか
	cps = cpss;
	char a, b;
	for (int i = 0;i < W;i++) {
		a = s[i];b = t[i];
		auto it = cps.find({ b,a });
		if (it == cps.end()) {
			cps.insert({ a,b });
		}
		else {
			cps.erase(it);
		}
	}
	if (cps.size() == 0)return 1;
	if (cps.size() > 1)return 0;
	tie(a, b) = *cps.begin();
	if (a == b)return 1;
	return 0;
}

bool stpst(string &s, string t) {
	reverse(t.begin(), t.end());
	if (s == t)return 1;
	return 0;
}

bool stpst(string &s) {
	string t = s;
	return stpst(s, t);
}

bool fsolve(vector<bool> &V) {

	for (int i = 0;i < W;i++) {
		if (V[i])continue;
		for (int j = i + 1;j < W;j++) {
			if (V[j])continue;

			if (stpst(OG[i], OG[j])) {
				V[i] = 1, V[j] = 1;
				if (fsolve(V))return 1;
				V[i] = 0;V[j] = 0;
			}
		}
		if (solow < 0) {
			solow = i;
			V[i] = 1;
			if (fsolve(V))return 1;
			V[i] = 0;
			solow = -1;
		}
	}
	for (bool i : V)if (!i)return 0;
	if (solow < 0)return 1;
	if (stpst(OG[solow]))return 1;
	return 0;
}

bool solve(vector<bool>&V,multiset<pair<int,int>> &st) {

	for (int i = 0;i < H;i++) {
		if (V[i])continue;
		for (int j = i + 1;j < H;j++) {
			if (V[j])continue;

			if (stp(Grid[i], Grid[j])) {
				V[i] = 1, V[j] = 1;
				st.insert({ i,j });
				if (solve(V, st))return 1;
				st.erase(--st.end());
				V[i] = 0;V[j] = 0;
			}
		}

		if (solo) {
			solo = 0;
			V[i] = 1;
			st.insert({ 512411,i });
			if (solve(V, st))return 1;
			st.erase(--st.end());
			V[i] = 0;
			solo = 1;
		}
		else return 0;
	}

	for (bool i : V)if (!i)return 0;

	int a = 0, b = -1;
	for (auto i : st) {
		for (int k = 0;k < W;k++) {
			if (i.first == 512411)OG[k][a] = Grid[i.second][k];
			else {
				OG[k][a] = Grid[i.first][k];
				OG[k][H - a - 1] = Grid[i.second][k];
			}
		}
		a++;
	}



	/*
	for (int i = 0;i < W;i++) {
		for (int j = 0;j < H;j++)
			cout << OG[i][j] << " ";
		cout << endl;
	}*/

	vector<bool> thr(W, 0);
	if (fsolve(thr))
		return 1;
	return 0;
}

