#include <bits/stdc++.h>

#define ull unsigned long long

using namespace std;

const int N = 15;
const int base = 233;

int n, m, a[N][N], id1[N], id2[N];
ull hash1[N], hash2[N], Hash[N], Pow[N];
char s[N][N], s1[N];

inline void add(int x, int y)
{
	y--;
	for(int i = 1; i <= m; i++)
	{
		hash1[i] += (s[x][i] - 'a' + 1) * Pow[y];
		hash2[i] += (s[x][i] - 'a' + 1) * Pow[n - y - 1];
	}
}

inline void del(int x, int y)
{
	y--;
	for(int i = 1; i <= m; i++)
	{
		hash1[i] -= (s[x][i] - 'a' + 1) * Pow[y];
		hash2[i] -= (s[x][i] - 'a' + 1) * Pow[n - y - 1];
	}
}

inline int cmp1(int a, int b)
{
	if(hash1[a] != hash1[b])return hash1[a] < hash1[b];
	return a < b;
}

inline int cmp2(int a, int b)
{
	if(hash2[a] != hash2[b])return hash2[a] < hash2[b];
	return a > b;
}

void dfs(int deep)
{
	if(deep * 2 + 1>= n)
	{
		int cnt = 0;
		for(int i = 1; i <= m; i++)
			id1[i] = id2[i] = i;
		sort(id1 + 1, id1 + 1 + m, cmp1);
		sort(id2 + 1, id2 + 1 + m, cmp2);
		for(int i = 1; i <= m; i++)
			if(hash1[id1[i]] != hash2[id2[i]])return;
			else if(id1[i] == id2[i])
			{
				if(hash1[id1[i]] == hash1[id1[i + 1]] && i < m)continue;
				if(hash1[id1[i]] == hash1[id1[i - 1]] && i > 0)continue;
				if(m & 1)cnt++;
				if(cnt <= 1)continue;
				return;
			}
		puts("YES");
		exit(0);
	}
	int nown = n - deep * 2;
	for(int i = 1; i <= nown; i++)
		for(int j = i + 1; j <= nown; j++)
		{
			int x = a[deep][i], y = a[deep][j];
			if(Hash[x] != Hash[y])continue;
			int cnt = 0;
			for(int k = 1; k <= nown; k++)
				if(a[deep][k] != x && a[deep][k] != y)a[deep + 1][++cnt] = a[deep][k];
			add(x, deep + 1);
			add(y, n - deep);
			dfs(deep + 1);
			del(x, deep + 1);
			del(y, n - deep);
		}
}

int main()
{
	scanf("%d%d", &n, &m);
	Pow[0] = 1;
	for(int i = 1; i <= n; i++)
		Pow[i] = Pow[i - 1] * base;
	for(int i = 1; i <= n; i++)
	{
		scanf("%s", s[i] + 1);
		for(int j = 1; j <= m; j++)
			s1[j] = s[i][j];
		sort(s1 + 1, s1 + 1 + m);
		ull nowhash = 0;
		for(int j = 1; j <= m; j++)
			nowhash = nowhash * base + (s1[j] - 'a' + 1);
		Hash[i] = nowhash;
		a[0][i] = i;
	}
	dfs(0);
	puts("NO");
}

