template<class T>
bool rei (T& x) {
    bool f = true;
    int ch;
    for (ch = getchar (); !isdigit (ch); ch = getchar ()) {
        if (ch == EOF) return false;
        f = ch != '-';
    }
    x = 0;
    if (f) do x = x * 10 + (ch & 15); while (isdigit (ch = getchar ()));
    else do x = x * 10 - (ch & 15); while (isdigit (ch = getchar ()));
    return true;
}
