template<class T>
void pti (T x) {
    char buf[sizeof (T) * 3], *p = buf + 1;
    if (x >= 0) *buf = (x % 10) | 48, x /= 10;
    else putchar ('-'), *buf = (-(x % 10)) | 48, x = -(x / 10);
    while (x) *p++ = (x % 10) | 48, x /= 10;
    while (p != buf) putchar (*--p);
}
