class pair_combination{
    private:
        int n;
        vector<bool> used;
        vector<P> tmp;
        vector<vector<P>> pairs;

        void make(int p){
            if((int)tmp.size() == n / 2){
                pairs.push_back(tmp);

                return;
            }

            if(used[p]){
                return ;
            }
            used[p] = true;

            for(int i = p+1; i < n; i++){
                if(used[i]){
                    continue;
                }
                used[i] = true;
                tmp.emplace_back(p, i);
                int next;
                for(next = 0; next < n; next++){
                    if(not used[next]){
                        break;
                    }
                }
                make(next);
                used[i] = false;
                tmp.pop_back();
            }
            used[p] = false;
        }

    public:
        pair_combination(int n)
            :n(n), used(n, false){
                make(0);
            }

        vector<vector<P>> get_pairs(){
            return pairs;
        }
};

