vpii st;
vector<vpii> a, b;

bool bit(int m, int i) {
	return (m & (1 << i));
}

void rech(int p, int mask) {
	if (p == h + 1) {
		a.pb(st);
		return;
	}
	if (bit(mask, p)) {  
		rech(p + 1, mask);
		return;
	}
	fi(p + 1, h) {
		if (bit(mask, i)) continue;
		if (i == p) continue;
		if (!eh[i][p]) continue;
		int mask1 = mask;
		mask1 ^= (1 << i);
		mask1 ^= (1 << p);
		st.pb(mp(p, i));
		rech(p + 1, mask1);
		st.pop_back();
	}
}

void recw(int p, int mask) {
	if (p == w + 1) {
		b.pb(st);
		return;
	}
	if (bit(mask, p)) {  
		recw(p + 1, mask);
		return;
	}
	fi(p + 1, w) {
		if (bit(mask, i)) continue;
		if (i == p) continue;
		if (!ew[i][p]) continue;
		int mask1 = mask;
		mask1 ^= (1 << i);
		mask1 ^= (1 << p);
		st.pb(mp(p, i));
		recw(p + 1, mask1);
		st.pop_back();
	}
}

bool check(vpii &hm, vpii &vm) {
	fi(0, sz(hm) - 1) {
		fj(0, sz(vm) - 1) {
			int h1 = hm[i].first;
			int h2 = hm[i].second;
			int v1 = vm[j].first;
			int v2 = vm[j].second;
			if (s[h1][v1] != s[h2][v2]) return false;
		}
	}
	return true;
}

void solve() {
	init();
	if (h % 2 == 0) {
		rech(1, 0);
	} else {
		fi(1, h) {
			st.pb(mp(i, i));
			rech(1, (1 << i));
			st.pop_back();
		}
	}
	if (w % 2 == 0) {
		recw(1, 0);
	} else {
		fi(1, w) {
			st.pb(mp(i, i));
			recw(1, (1 << i));
			st.pop_back();
		}
