vector<bool> U(12, false);
bool works = false;
void mixColumns(int i) {
    if (works) return;
    if (i == w/2) {
        if (w%2 == 1) {
            for (int c = i; c < w; c++) {
                if (!U[c]) {
                    mix[w/2] = c;
                }
            }
        }
        if (tryGrid()) {
            works = true;
            return;
        }
    }

    int c;
    for (c = i; c < w; c++) {
        if (!U[c]) break;
    }

    mix[i] = c;
    U[c] = true;
    for (int j = c+1; j < w; j++) {
        if (!U[j]) {
            mix[w-1-i] = j;
            U[j] = true;
            mixColumns(i+1);
            U[j] = false;
        }
    }
    U[c] = false;
}

