#include <bits/stdc++.h>
using namespace std;

int h, w;
mt19937 ei(1333333);

bool check(vector<string> s) {
  vector<string> t = s;
  for (auto &i : t) reverse(i.begin(), i.end());

  sort(s.begin(), s.end());
  sort(t.begin(), t.end());

  for (int i = 0; i < s.size(); ++i) {
    if (s[i] != t[i]) return false;
  }

  return true;
}

bool solve(vector<string> &t, int q = 10000) {
  vector<string> s = t;
  vector<int> v(w);
  for (int i = 0; i < w; ++i) v[i] = i;
  while (q--) {
    // 怒りの乱択
    shuffle(v.begin(), v.end(), ei);
    for (int i = 0; i < h; ++i) {
      for (int j = 0; j < w; ++j) {
        s[i][j] = t[i][v[j]];
      }
    }
    if (check(s)) return true;
  }

  return false;
}

int main() {
  cin >> h >> w;

  vector<string> s(h);
  for (auto &i : s) cin >> i;

  cout << (solve(s) ? "YES" : "NO") << endl;
}

