bool check(){
    bool cc[12];
    memset(cc,false,sizeof(cc));
    string t[h];
    for (int i = 0; i < h; i++) {
        if(i%2) t[i/2]=s[order[i]];
        else t[h-i/2-1]=s[order[i]];
    }
    for (int i = 0; i < w; i++) {
        if(cc[i]) continue;
        string a="";
        for (int j = 0; j < h; j++) {
            a.pb(t[j][i]);
        }
        for (int j = i+1; j < w; j++) {
            if(cc[j]) continue;
            string b="";
            for (int k = 0; k < h; k++) {
                b.pb(t[k][j]);
            }
            reverse(ALL(b));
            if(a==b){
                cc[i]=true;
                cc[j]=true;
                break;
            }
        }
    }
    int cnt=0;
    for (int i = 0; i < w; i++) {
        cnt+=(!cc[i]);
    }
    return cnt<=1;
}

bool dfs(int m,int l){
    if(m==h){
        return check();
    }
    if(m==h-1){
        for (int i = 0; i < h; i++) {
            if(used[i]) continue;
            used[i]=1;
            order[m]=i;
            if(dfs(m+1,l)) return true;
            used[i]=0;
        }
        return false;
    }
    if(m%2){
        for (int i = l+1; i < h; i++) {
            if(used[i]) continue;
            used[i]=1;
            order[m]=i;
            if(dfs(m+1,l)) return true;
            used[i]=0;
        }
    }
    else{
        for (int i = l-1; i >= 0; i--) {
            if(used[i]) continue;
            used[i]=1;
            order[m]=i;
            if(dfs(m+1,i)) return true;
            used[i]=0;
        }
    }
    return false;
}

