const int MAX = 12;
const int ALPHABET = 26; // アルファベットの文字数
const bool DEBUG = false; // デバッグ表示用、提出時にfalseにするよ

int main() {
	int H, W;
	cin >> H >> W;
	string s[MAX];
	for (int i = 0;i < H;i ++) cin >> s[i];
	int alphaWid[MAX][ALPHABET], alphaHgt[MAX][ALPHABET]; // alphaWid[i][j] = 横iのj番目の文字の数、alphaHgtは縦で
	for (int i = 0;i < H;i ++) {
		for (int j = 0;j < ALPHABET;j ++) alphaHgt[i][j] = 0;
		for (int j = 0;j < W;j ++) alphaHgt[i][s[i][j] - 'a'] ++;
	}
	for (int i = 0;i < W;i ++) {
		for (int j = 0;j < ALPHABET;j ++) alphaWid[i][j] = 0;
		for (int j = 0;j < H;j ++) alphaWid[i][s[j][i] - 'a'] ++;
	}
	bool isOdd = false;
	int tmp; // 入れ替え用
	for (int i = 0;i < H / 2;i ++) {
		for (int j = i + 1;j < H;j ++) {
			bool isCorrect = true;
			for (int k = 0;k < ALPHABET;k ++) {
				if (alphaHgt[i][k] != alphaHgt[j][k]) isCorrect = false;
			}
			if (isCorrect) { // 点対称候補は点対称になりそうな位置に置いておく
				for (int k = 0; k < ALPHABET;k ++) {
					tmp = alphaHgt[j][k];
					alphaHgt[j][k] = alphaHgt[H - i - 1][k];
					alphaHgt[H - i - 1][k] = tmp;
				}
				if (DEBUG) {
					cout << i << "," << j << endl;
					for (int k = 0;k < H;k ++) {
						for (int l = 0;l < ALPHABET;l ++) {
							if (alphaHgt[k][l] != 0) cout << (char)(l + 'a') << ":" << alphaHgt[k][l] << " ";
						}
						cout << endl;
					}
				}
				break;
			} else if (j >= H - 1) {
				if ((H & 1) == 1 && !isOdd) { // もしHが奇数ならまぁ、中央に置いておけば……
					isOdd = true;
					for (int k = 0; k < ALPHABET;k ++) {
						tmp = alphaHgt[i][k];
						alphaHgt[i][k] = alphaHgt[H / 2][k];
						alphaHgt[H / 2][k] = tmp;
					}
				} else { // あ、無理
					cout << "NO";
					return 0;
				}
			}
		}
	}
	isOdd = false;
	for (int i = 0;i < W / 2;i ++) {
		for (int j = i + 1;j < W;j ++) {
			bool isCorrect = true;
			for (int k = 0;k < ALPHABET;k ++) {
				if (alphaWid[i][k] != alphaWid[j][k]) isCorrect = false;
			}
			if (isCorrect) { // 点対称候補は点対称になりそうな位置に置いておく
				for (int k = 0; k < ALPHABET;k ++) {
					tmp = alphaWid[j][k];
					alphaWid[j][k] = alphaWid[H - i - 1][k];
					alphaWid[H - i - 1][k] = tmp;
				}
				break;
			} else if (j >= W - 1) {
				if ((W & 1) == 1 && !isOdd) { // もしHが奇数ならまぁ、中央に置いておけば……
					isOdd = true;
					for (int k = 0; k < ALPHABET;k ++) {
						tmp = alphaWid[i][k];
						alphaWid[i][k] = alphaWid[W / 2][k];
						alphaWid[W / 2][k] = tmp;
					}
				} else { // あ、無理
					cout << "NO";
					return 0;
				}
			}
		}
	}
	cout << "YES"; // ここまで無事なら多分大丈夫
	return 0;
}
