inline bool match(bool matched[], vector<int> dvec, map<int, vector<int>>& up) {
    for (int i = 0, _ = w >> 1; i < _; ++i)
        for (int j = 0; j < w; ++j)
            if (!matched[j])
                for (int k: up[dvec[j]])
                    if (!matched[k])
                        matched[j] = matched[k] = true;
    bool ok = true;
    for (int i = 0; i < w && ok; ++i)
        if (!matched[i]) ok = false;
    for (int i = 0; i < w; ++i) matched[i] = false;
    return ok;
}

void check() {
    static bool matched[15];
    map<int, vector<int> > up;
    vector<int> dvec, uvec;
    for (int i = 0; i < w; ++i) {
        int hsh = 0;
        for (int j = 0; j < h; ++j)
            (hsh *= HASH) += str[lines[j]][i];
        dvec.emplace_back(hsh);
        hsh = 0;
        for (int j = h - 1; j >= 0; --j)
            (hsh *= HASH) += str[lines[j]][i];
        up[hsh].emplace_back(i);
        uvec.emplace_back(hsh);
    }
    if (w & 1) {
        for (int i = 0; i < w; ++i)
            if (dvec[i] == uvec[i]) {
                matched[i] = true;
                if (match(matched, dvec, up))
                    exit(int(puts("YES")));
                matched[i] = false;
            }
    } else if (match(matched, dvec, up)) {
        exit(int(puts("YES")));
    }
}

bool setted[15];

void getLines(int cur = 0, int smallest = 0) {
    if (cur == (h >> 1)) return check();
    while (setted[smallest]) ++smallest;
    lines[cur] = smallest;
    for (int i = smallest + 1; i < h; ++i)
        if (!setted[i]) {
            lines[h - 1 - cur] = i;
            setted[i] = true;
            getLines(cur + 1, smallest + 1);
            setted[i] = false;
        }
}

void dfs(int cur, int cnt, int msk) {
    if (cnt == (h >> 1)) return getLines();
    if (cur == h) return ;
    if (setted[cur]) return dfs(cur + 1, cnt, msk);
    dfs(cur + 1, cnt + 1, msk | 1 << cur);
    dfs(cur + 1, cnt, msk);
}

