        for (int j = i+1; j < h; j++) {
            if (used[j]) continue;
            bool match = true;
            for (int k = 0; k < w; k++) {
                if (T[i][k] != T[j][w-1-k]) {
                    match = false;
                    break;
                }
            }
            if (match) {
                used[i] = true;
                used[j] = true;
                remaining -= 2;
                break;
            }
        }
        if (!used[i]) {
            remains = i;
        }
    }

    if (h%2 == 0) {
        if (remaining > 0) {
            return false;
        } else {
            return true;
        }
    } else {
        if (remaining == 1 && isPalindrome(T[remains])) {
            return true;
        } else {
            return false;
        }
    }
}

