int getpal(int p){
	map < int , int > mp;
	mp.clear();
	int i,j,k;
	for(i=0;i<m;++i){
		++mp[a[p][i]];
	}
	map < int , int > ::iterator it;
	int ret=-1;
	for(it=mp.begin();it!=mp.end();++it){
		if(it->second&1){
			if(ret==-1)
				ret=it->first;
			else
				return -1;
		}
	}
	if(ret!=-1) return ret; else return 0;
}
int getcc(int p,int q){
	map < pii , int > mp,pos;
	mp.clear();
	int i,j,k;
	for(i=0;i<m;++i){
		++mp[mpr(a[p][i],a[q][i])];
		pos[mpr(a[p][i],a[q][i])]|=(1<<i);
	}
	map < pii , int > ::iterator it;
	int ret=0;
	for(it=mp.begin();it!=mp.end();++it){
		pii ref=mpr(it->first.second,it->first.first);
		if(mp[ref]!=it->second){
			return -1;
		}
		if(it->first.second==it->first.first) ret|=(1<<pos[ref]);
	}
	return ret;
}
void push_back(LL &ve,LL v1){
