void solve () {
	int M = 0;
	for(int i=1;i<=h;i++) v2[i] = false;
	for(int i=1;i<=h;i++) {
		if(v2[i]) continue;
		for(int j=i+1;j<=h;j++) {
			if(v2[j]) continue;
			int flag = false;
			for(int k=1;k<=w;k++) {
				if(a[i][k] != a[j][mat[k]]) {flag = true; break;}
			}
			if(!flag) {v2[i] = true; v2[j] = true; M++; break;}
		}
	}
	if(h%2) {
		for(int i=1;i<=h;i++) {
			if(v2[i]) continue;
			bool flag = false;
			for(int j=1;j<=w;j++) {
				if(a[i][j] != a[i][mat[j]]) {flag = true; break;}
			}
			if(!flag) {v2[i] = true; M++; break;}
		}
	}
	if(M == (h+1)/2) {puts("YES"); exit(0);}
}

