bool bisa(int x, int y) {
	int i,j;
	bool haha = false;
	for (i='a' ; i<='z' ; i++) {
		for (j='a' ; j<='z' ; j++) {
			b[i][j] = 0;
		}
	}
	for (i=0 ; i<m ; i++) {
		b[s[x][i]][s[y][i]]++;
		if (s[x][i] == s[y][i]) haha = true;
	}
	for (i=0 ; i<m ; i++) {
		b[s[y][i]][s[x][i]]--;
	}

	for (i='a' ; i<='z' ; i++) {
		for (j='a' ; j<='z' ; j++) {
			if (b[i][j] != 0) return false;
		}
	}

	return haha;
}

void BF(int bit, int matched) {
	int i,j;
	if (matched == n / 2) {
		if (matched * 2 == n) yes = true;
		for (i='a' ; i<='z' ; i++) a[i] = 0;
		for (i=0 ; i<n ; i++) if (((1 << i) & bit) == 0) {
			int ada = 0;
			for (j=0 ; j<m ; j++) {
				a[s[i][j]] ^= 1;
			}
			for (j='a' ; j<='z' ; j++) ada += a[j];
			if (ada <= 1) yes = true;
		}
	}

	if (flag[bit][matched]) return;
	flag[bit][matched] = true;

	for (i=0 ; i<n ; i++) if (((1 << i) & bit) == 0) {
		for (j=i+1 ; j<n ; j++) if (((1 << j) & bit) == 0) {
			if (bisa(i,j)) {
				BF(bit ^ (1 << i) ^ (1 << j),matched+1);
			}
		}
	}
}

