#include<bits/stdc++.h>
using namespace std;

using Hash=__int128;
using ll=long long;
const Hash MOD=1e18+9;
const Hash A=124534;
Hash encode(const vector<string>& s,int col,int from,int diff,int end){
    Hash res=0;
    Hash x=1;
    for(int i=from;i!=end;i+=diff){
        res+=s[i][col]*x;
        res%=MOD;
        x=x*x%MOD;
    }
    return res;
}
int main(){
    int h,w;
    cin>>h>>w;
    vector<string> s(h);
    for(int i=0;i<h;i++) cin>>s[i];

    int c=(h+1)/2;
    int comb=(1<<c)-1;

    auto check=[h,w](const vector<string>& s){
        set<pair<ll,ll>> hs;
        for(int i=0;i<w;i++){
            ll ho=encode(s,i,0,1,h);
            ll hr=encode(s,i,h-1,-1,-1);
            if(hs.count({hr,ho})){
                hs.erase({ho,hr});
            }
            else hs.insert({ho,hr});
        }
        if(hs.size()>=2) return false;
        if(hs.size()==0) return true;
        return hs.begin()->first==hs.begin()->second;
    };
    while(comb<1<<h){
        vector<string> f=s;
        int id=0;
        for(int i=0;i<h;i++){
            if((comb>>i)&1){
                swap(f[id],f[i]);
                id++;
            }
        }
        assert(id==c);
        vector<int> perm(c);
        iota(perm.begin(),perm.end(),0);
        do{
            auto tmp=f;
            for(int i=0;i<c;i++) tmp[perm[i]]=f[i];
            if(check(tmp)){
                cout<<"YES"<<endl;
                return 0;
            }           
        }while(next_permutation(perm.begin(),perm.end()));
        int x=comb&-comb,y=comb+x;
        comb=((comb&~y)/x>>1)|y;
    }
    cout<<"NO"<<endl;
    return 0;
}

