int judge(int now1,int now2)
{
	for(int k=1;k<=n;k++)
	{
		if(s[k][now1]!=s[match1[k]][now2])
			return false;
	}
	return true;
}
void dfs2(int now,int flag)
{
	if(now==m+1)
	{
		printf("YES\n");
		exit(0);
	}
	if(match2[now])
	{
		dfs2(now+1,flag);
		return;
	}
	if(m&1 && flag && judge(now,now))
	{
		match2[now]=now;
		dfs2(now+1,0);
		match2[now]=0;
	}

	for(int i=now+1;i<=m;i++)
	{
		if(!match2[i] && judge(now,i))
		{
//			cerr<<"+1"<<endl;
			match2[i]=now;
			match2[now]=i+1;

			dfs2(now+1,flag);

			match2[i]=0;
			match2[now]=0;
		}
	}

}
void dfs1(int now,int flag)
{
//	cerr<<now<<endl;
	if(now==n+1)
	{
		dfs2(1,m&1);
		return;
	}
	if(match1[now])
	{
//		cerr<<"+1"<<endl;
		dfs1(now+1,flag);
		return;
	}
	if(n&1 && flag)
	{
//		cerr<<"+1"<<endl;
		match1[now]=now;
		dfs1(now+1,0);
		match1[now]=0;
	}
	for(int i=now+1;i<=n;i++)
	if(!match1[i] && can[now][i])
	{
//		cerr<<"+1"<<endl;
		match1[i]=now;
		match1[now]=i;

		dfs1(now+1,flag);

		match1[i]=0;
		match1[now]=0;
	}
}
