bool chk(){
	//rep(i,1,n)Pr("Mat[%d]=%d\n",i,mat[i]); 
	int p=1,q=n;
	rep(i,1,n){
		if(mat[i]&&mat[i]<i){
			rep(j,1,m)t[p][j]=s[i][j];++p;
			rep(j,1,m)t[q][j]=s[mat[i]][j];--q;
		}
	}
	rep(i,1,n)if(mat[i]==i){
		rep(j,1,m)t[p][j]=s[i][j];
	}
	rep(j,1,m){
		g[j]="";
		rep(i,1,n)g[j]+=t[i][j];
	}
	rep(i,1,m)rep(j,1,m)if(!vis[i]&&!vis[j]&&cmp(g[i],g[j])){
		vis[i]=vis[j]=1;
	}
	int qwq=0;
	rep(i,1,m){
		if(!vis[i]){
			if(cmp(g[i],g[i]))++qwq;
			else return false;
		}
	}
	return qwq<=1;
}

