        vector<string> f=s;
        int id=0;
        for(int i=0;i<h;i++){
            if((comb>>i)&1){
                swap(f[id],f[i]);
                id++;
            }
        }
        assert(id==c);
        vector<Hash> hob(w);
        vector<Hash> hrb(w);
        Hash pAnc=1;
        for(int i=c;i<h;i++) pAnc=pAnc*A%MOD;
        for(int j=0;j<w;j++){
            Hash x=1;
            for(int i=0;i<c;i++) x=x*A%MOD;
            for(int i=c;i<h;i++){
                hob[j]+=f[i][j]*x;
                hob[j]%=MOD;
                x=x*A%MOD;
            }
            x=1;
            for(int i=h-1;i>=c;i--){
                hrb[j]+=f[i][j]*x;
                hrb[j]%=MOD;
                x=x*A%MOD;
            }
        }
        vector<int> perm(c);
        iota(perm.begin(),perm.end(),0);
        do{
            set<pair<ll,ll>> hs;
            for(int j=0;j<w;j++){
                Hash vo=hob[j];
