                    vo%=MOD;
                    x=x*A%MOD;
                }
                Hash vr=hrb[j];
                x=pAnc;
                for(int i=c-1;i>=0;i--){
                    vr+=f[perm[i]][j]*x;
                    vr%=MOD;
                    x=x*A%MOD;
                }

                if(hs.count({ll(vr),ll(vo)})){
                    hs.erase({ll(vr),ll(vo)});
                }
                else{
                    hs.insert({ll(vo),ll(vr)});
                }
            }
            if(hs.size()==0 || hs.size()==1 && hs.begin()->first==hs.begin()->second){
                cout<<"YES"<<endl;
                return 0;
            }
        }while(next_permutation(perm.begin(),perm.end()));
        int x=comb&-comb,y=comb+x;
        comb=((comb&~y)/x>>1)|y;
    }
    cout<<"NO"<<endl;
    return 0;
}

