        for2(j,0,m) swap(a[n-cur-1][j],a[i][j]);
        f(cur+1);
        for2(j,0,m) swap(a[n-cur-1][j],a[i][j]);
    }
    if(en){
        fill(seen,seen+m,0);
        int  cnt = 0;
        for2(i,0,m)if(!seen[i]) for2(k,0,m) if(!seen[k] && i != k){
            bool same = 1;
            for2(j,0,n) same &= (a[j][i]==a[n-j-1][k]);
            if(same){
                seen[i] = seen[k] = 1;
                cnt += 2;
                break;
            }
        }
        if(cnt == m || cnt == m-1) ok = 1;
    }
}

