void Rec(int s, vector<int>& curr) {
	if (s == 0) {
		pairs.push_back(curr);
		return;
	}

	int v1, v2;
	REP(i, 0, W) {
		if ((s >> i) & 1) {
			v1 = i;
			s -= 1 << i;
			curr.push_back(v1);
			break;
		}
	}

	REP(i, 0, W) {
		if ((s >> i) & 1) {
			v2 = i;
			s -= 1 << i;
			curr.push_back(v2);
			Rec(s, curr);

			s += 1 << i;
			curr.pop_back();
		}
	}
	curr.pop_back();
	return;
}

