bool reveq(string s1, string s2) { reverse(s2.begin(), s2.end()); return s1 == s2; }

bool check(vector<string> vs) {
	int n = vs.size();

	int cnt1[26] = { 0 }; for (auto c : vs[0]) cnt1[c - 'a']++;

	vector<int> eqvid; int cnt2[26];

	bool flg;
	for (int i = 1; i < n; ++i) {
		flg = true;
		fill(cnt2, cnt2 + 26, 0); for (auto c : vs[i]) cnt2[c - 'a']++;
		for (int j = 0; j < 26; ++j) if (!(flg &= (cnt1[j] == cnt2[j]))) break;
		if (flg) eqvid.push_back(i);
	}

	for (auto id : eqvid) {

		vector<int> eqid;
		map<pair<int, int>, int > revval;
		vector<pair<int, int>> revpid;
		map<pair<int, int>, int>::iterator tmp;

		for (int i = 0, num = vs[0].length(); i < num; ++i) {
			auto c1 = vs[0][i], c2 = vs[id][i];

			if (c1 == c2) eqid.push_back(i);
			else if ((tmp = revval.find({ c2, c1 })) != revval.end()) {
				auto val = tmp->second;
				revpid.push_back({ (val == -1) ? 0 : val, i });
				revval.erase({ c2, c1 });
			}
			else revval[{c1, c2}] = (i ? i : -1);
		}

		if (!revval.empty()) continue;

		int eqnum = eqid.size(), revnum = revpid.size();
		vector<int> eqperm(eqnum);	 for (int j = 0; j < eqnum; ++j)  eqperm[j] = j;
		vector<int> revperm(revnum); for (int j = 0; j < revnum; ++j) revperm[j] = j;
		vector<string> nvs(n - 2, "");

		swap(vs[1], vs[id]);

		while (true) {
			for (auto revperm_id : revperm) for (int k = 0; k < n - 2; ++k) nvs[k] += vs[k + 2][revpid[revperm_id].first];
			for (auto eqperm_id : eqperm)   for (int k = 0; k < n - 2; ++k) nvs[k] += vs[k + 2][eqid[eqperm_id]];
			for (int l = revnum - 1; l >= 0; --l) for (int k = 0; k < n - 2; ++k) nvs[k] += vs[k + 2][revpid[l].second];

			while (!nvs.empty()) {
				if (nvs.size() == 1 && !reveq(nvs[0], nvs[0])) break;

				bool flg = false;
				for (int k = 1, num = nvs.size(); k < num; ++k) {
					if (reveq(nvs[0], nvs[k])) { nvs.erase(nvs.begin() + k); nvs.erase(nvs.begin()); flg = true; break; }
				}
				if (!flg) break;
			}

			if (nvs.empty())
				return true;

			if (!next_permutation(eqperm.begin(), eqperm.end()) && !next_permutation(revperm.begin(), revperm.end())) break;
		}
	}
	return false;
}

