bool check() {
  vector<string> v = s;
  for (int k = 0; k < idx.size(); ++k) {
    for (int i = 0; i < h; ++i) {
      swap(v[i][idx[k].first], v[i][idx[k].second]);
    }
  }

  map<string, int> cnt;
  for (int i = 0; i < v.size(); ++i) {
    cnt[v[i]]++;
    reverse(v[i].begin(), v[i].end());
    cnt[v[i]]++;
  }

  for (auto &i : cnt) {
    if (i.second & 1) return false;
  }

  return true;
}

bool dfs(int bit = 0) {
  if (check()) return true;

  for (int i = 0; i < w; ++i) {
    if (bit & (1 << i)) continue;
    for (int j = i + 1; j < w; ++j) {
      if (bit & (1 << j)) continue;
      idx.push_back(make_pair(i, j));
      if (dfs(bit | (1 << i) | (1 << j))) return true;
      idx.pop_back();
    }
  }

  return false;
}

