int encode(string s, int mod) {
  int sum = 0;
  for(char c : s) {
    int pow = c - 'a';
    int m = 1;
    for(int i=0; i<pow; i++) {
      m = (m * 26) % mod;
    }
    sum = sum + m % mod;
  }
  return sum;
}

bool valid(multiset<pair<int,int>>& h, vector<pair<int,int>>& codebase) {
  int odd = 0;
  for(auto elem : codebase) {
