#include <bits/stdc++.h>
using namespace std;

bool ans;
int H, W;
vector<bool> used;
vector<int> mrr;
vector<string> ss, S;

bool same(int l, int r) {
  for (int k = 0; k < H / 2; ++k) {
    if (ss[k][l] != ss[mrr[H - 1 - k]][r]) return false;
  }
  return true;
}

void solve() {
  int cur = 0;
  ss = vector<string>(S);
  used = vector<bool>(W, false);
  for (int i = 0; i < W; ++i) {
    if (used[i]) continue;
    for (int j = i + 1; j < W; ++j) {
      if (same(i, j)) used[i] = used[j] = true;
    }
  }
  for (int i = 0; i < W; ++i) {
    if (used[i]) continue;
    if (!same(i, i)) return;
  }
  ans = true;
}

void dfs(int n) {
  if (ans) return;
  if (n >= H) {
    for (int i = 0; i < H; ++i) {
      if (mrr[i] == -1) mrr[i] = i;
    }
    solve();
    return;
  }
  if (mrr[n] != -1) {
    dfs(n + 1);
    return;
  }
  for (int i = n + 1; i < H; ++i) {
    if (mrr[i] == -1) {
      mrr[n] = i;
      mrr[i] = n;
      dfs(n + 1);
      mrr[n] = -1;
      mrr[i] = -1;
    }
  }
}


int main() {
  cin >> H >> W;
  S = vector<string>(H);
  for (int i = 0; i < H; ++i) cin >> S[i];
  mrr = vector<int>(H, -1);
  dfs(0);
  cout << ( (ans) ? "YES" : "NO" ) << endl;
  return 0;
}

