	for (int i = 0;i < W;i++) {
		for (int j = 0;j < H;j++)
			cout << OG[i][j] << " ";
		cout << endl;
	}
	*/
	vector<bool> thr(12, 0);
	if (fsolve(thr))
		return 1;
	return 0;
}

