      if( S2 >> j & 1 ) continue;

      int flag = 1;

      for(int k=0;k<h;k++){
	if( t[k][i] != t[h-k-1][j] ) flag = 0;
      }

      if( flag == 1 ){
	S2 |= ( 1 << i ) | ( 1 << j );
	break;
      }

    }

  }

  if( w % 2 == 0 && __builtin_popcount(S2) == w ){
    cout << "YES" << endl;
    exit(0);
  }

  if( w % 2 == 1 && __builtin_popcount(S2) == w - 1 ){

    for(int i=0;i<w;i++){

      if( S2 >> i & 1 ) continue;

      int flag = 1;

      for(int j=0;j<h;j++){
