      }

    }

  }

}

void dfs(vector<P> A, int S, int X){

  if( h - __builtin_popcount(S) <= 1 ){

    check( A, S );

    return;
  }

  int idx = -1;

  for(int i=0;i<h;i++){

    if( i == X ) continue;

    if( S >> i & 1 ) continue;

    idx = i;

    break;

  }

  if( idx == -1 ) return;

  for(int i=idx+1;i<h;i++){

    if( i == X ) continue;

    if( S >> i & 1 ) continue;

    vector<P> nA = A;

    nA.push_back(P( idx, i ));

    int nS = S | ( 1 << idx ) | ( 1 << i );

    dfs( nA, nS, X );

  }

}

