bool solve(const bitset<144> maps[13][13], ll h, ll w,
           bitset<144> &state, bool used[13])
{
    bool done = true;
    bitset<144> orig_state;

    rep (h1, h) {
        if (used[h1]) continue;
        srep (h2, h1+1, h) {
            if (used[h2]) continue;
            done = false;

            used[h1] = used[h2] = true;
            orig_state = state;
            state &= maps[h1][h2];

            if (solve(maps, h, w, state, used)) return true;

            state = orig_state;
            used[h1] = used[h2] = false;
        }
    }

    if (!done) return false;

    S bool checked[13];
    memset(checked, 0, sizeof(checked));
    ll cnt = 0LL;

    rep (v1, w) srep (v2, v1+1, w) {
        if (checked[v1] || checked[v2]) continue;
        if (state.test(v1*12+v2)) {
            checked[v1] = checked[v2] = true;
            cnt += 2LL;
        }
    }

    assert(cnt <= w);
    if (cnt < w - 1LL) return false;
    if (!(w & 1LL) && cnt < w) return false;
    if (!(w & 1LL) && cnt == w) return true;

    rep (v, w) {
        if (checked[v]) continue;
        if (state.test(v*12+v)) {
            checked[v] = true;
            cnt++;
            break;
        }
    }

    assert(cnt <= w);

    if (cnt == w) return true;
    return false;
}

