bool search(const vector<string>& s) {
	bool r;
	if (s.size() == 0) {
		r = true;
	} else if (s.size() % 2) {
		r = false;
		for (int i = 0; i < s.size() && !r; i++) {
			map<char, int> m;
			for (auto e : s[i]) {
				m[e]++;
			}
			int odd = 0;
			for (auto e : m) {
				odd += e.second % 2;
			}
			if (odd <= 1) {
				vector<string> t = s;
				t.erase(begin(t) + i);
				r |= search(t);
			}
		}
	} else {
		r = false;
		for (int i = 1; i < s.size() && !r; i++) {
			bool rr = true;
			vector<vector<int>> c(26, vector<int>(26));
			for (int j = 0; j < s[0].size(); j++) {
				c[s[0][j] - 'a'][s[i][j] - 'a']++;
			}
			int odd = 0;
			for (int j = 0; j < 26; j++) {
				odd += c[j][j] % 2;
			}
			rr &= odd <= 1;
			for (int j = 0; j < s[0].size(); j++) {
				c[s[i][j] - 'a'][s[0][j] - 'a']--;
			}
			for (auto e : c) {
