void FIND(set<int>& st,string& ss,string tt){
  for(int i = 0;i < (1 << H);i++){
    if(__builtin_popcount(i) != H / 2) continue;
    string s = ss;
    string t = tt;
    for(int j = 0;j < H;j++){
      if(i & (1 << j)){
        swap(s[j],t[j]);
      }
    }

    if(s == t) st.insert(i);
  }
}

