            T[i][W-1-j] = S[i][pair[j*2+1]];
        }
        if (W % 2 == 1) {
            T[i][W/2] = S[i][pair.back()];
        }
    }

    for (int i = 0; i < H; i++) {
        if (!used[i]) {
            std::string tmp = T[i];
