bool found;

bool check(vector<string>&s) {
  int H = s.size();
  int W = s[0].size();
  vector<string> t(W, string(H, '.')), r(W);
  REP(h, H) REP(w, W) t[w][h] = s[h][w];
  REP(w, W) {
    r[w] = t[w];
    reverse(ALL(r[w]));
  }

  // REP(w, W) {
  //   cout << r[w] << endl;
  // }
  // cout << "....." << endl;


  int done = 0;
  int alone = 0;
  REP(w, W) if ((done >> w & 1) == 0) {
    bool ok = false;
    for (int w2 = w + 1; w2 < W; w2++) if ((done >> w2 & 1) == 0) {
      if (t[w] == r[w2]) {
        done |= (1 << w);
        done |= (1 << w2);
        ok = true;
        break;
      }
    }
    if (!ok) {
      if (W % 2 == 0) return false;
      if (alone >= 1) return false;
      if (t[w] != r[w]) return false;
      alone++;
      done |= (1 << w);
    }
  }
  return true;
}

void dfs(vector<string> hist, const vector<string> &s, const vector<string>& bin, int d, int used) {
  if (found) return;
  int H = (int)s.size();
  if (d >= (H+1)/2) {
    // REP(i, H) {
    //   cout << hist[i] << endl;
    // }
    // cout << "---" << endl;
    if (check(hist)) {
      found = true;
    }
    return;
  }

  if (d == H - d - 1) {
    for (int i = 0; i < H; i++) if (!(used >> i & 1)) {
      if (bin[i] == bin[i]) {
        hist[d] = s[i];
        dfs(hist, s, bin, d+1, used | (1 << i));
      }
    }
  } else {

    for (int i = 0; i < H; i++) if (!(used >> i & 1)) {
      for (int j = i + 1; j < H; j++) if (!(used >> i & 1)) {
        if (bin[i] == bin[j]) {
          hist[d] = s[i];
          hist[H - d - 1] = s[j];
          dfs(hist, s, bin, d+1, used | (1 << i) | (1 << j));
        }
      }
    }

  }
}

