	for(int i=0;i<m;i++)
	{
		for(int j=0;j<m;j++)
		{
			if(v[i]||v[j]||i==j)continue;
			int f=1;
			for(int k=0;k<n;k++)if(s[p[k]][i]!=s[k][j])
			{
				f=0;
				break;
			}
			if(f)v[i]=v[j]=1;
		}
	}
	int cc=0,t=0;
	for(int i=0;i<m;i++)if(!v[i])cc++,t=i;
	if(!cc)return true;
	if(cc>=2||m&1==0)return false;
	for(int i=0;i<n;i++)if(s[p[i]][t]!=s[i][t])return false;
	return true;
}
