char a[15][15], pc[15], pr[15];
int n, m;
inline bool mp_r(int x);
inline bool mp_c(int x);

bool mp_c(int x) {
  if (x>m) 
    return mp_r(1);
  if (pc[x])
    return mp_c(x+1);

  int t = 0;
  for (int i = x; i <= m; ++i) 
    if (!pc[i]) ++t;
  for (int i = x; i <= m; ++i) {
    if (pc[i]) continue;
    pc[x] = i; pc[i] = x;
    if (((t & 1) || (i != x)) && mp_c(x+1))
      return true;
    pc[x] = 0; pc[i] = 0;
  }

  return false;
}

bool mp_r(int x) {
  if (x>n) 
    return true;
  if (pr[x])
    return mp_r(x+1);

  int t = 0;
  for (int i = x; i <= n; ++i)
    if (!pr[i]) ++t;
  for (int i = x; i <= n; ++i) {
    if (pr[i]) continue;
    bool ok = true;
    for (int j = 1; j <= m; ++j) 
      ok &= (a[x][j] == a[i][pc[j]]);
    if (((t & 1) || (i != x)) && ok) {
      pr[x] = i; pr[i] = x;
      if (mp_r(x+1)) return true;
      pr[x] = 0; pr[i] = 0;
    }
  }

  return false;
}

