    for (int i = 0; i < H; ++i) {
        cin >> S[i];
    }
    char S_[MAX_H][MAX_W];
    char T_[MAX_W][MAX_H];
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            S_[i][j] = S[i][j];
            T_[j][i] = S[i][j];
        }
    }

    for (int i = 0; i < H; ++i) {
        sort(S_[i], S_[i] + W);
    }
    for (int j = 0; j < W; ++j) {
        sort(T_[j], T_[j] + H);
    }

    bool ans = true;

    bool has_pair[MAX_H + MAX_W];
    fill(has_pair, has_pair + H + W, false);

    for (int i = 0; i < H; ++i) {
        if (has_pair[i]) continue;
        for (int ii = 0; ii < H; ++ii) {
            if (i == ii || has_pair[ii]) continue;
            bool same = true;
            for (int j = 0; j < W; ++j) {
                if (S_[i][j] != S_[ii][j]) {
                    same = false;
                }
            }
            if (same) {
                has_pair[i] = true;
                has_pair[ii] = true;
            }
        }
    }
    int count = 0;
    for (int i = 0; i < H; ++i) {
        if (!has_pair[i]) {
            ++count;
        }
    }
    if (count >= 2) {
        ans = false;
    }

    for (int j = 0; j < W; ++j) {
        if (has_pair[j + H]) continue;
        for (int jj = 0; jj < W; ++jj) {
            if (j == jj || has_pair[jj + H]) continue;
            bool same = true;
            for (int i = 0; i < H; ++i) {
                if (T_[j][i] != T_[jj][i]) {
                    same = false;
                }
            }
            if (same) {
                has_pair[j + H] = true;
                has_pair[jj + H] = true;
            }
        }
    }
    count = 0;
    for (int j = 0; j < W; ++j) {
        if (!has_pair[j]) {
            ++count;
        }
    }
    if (count >= 2) {
        ans = false;
    }

    if (ans) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }

    return 0;
}

