const int N=25;

char s[N][N];

int match[N],n,m,flag;

bool used[N],lxf;

bool check() {
	int cnt=m;
	rep(i,1,m) used[i]=0;
	rep(i,1,m) if (!used[i]) {
		rep(j,i+1,m) if (!used[j]) {
			bool wjp=true;
			rep(k,1,n) if (s[k][i]!=s[match[k]][j]) {
				wjp=false; break;
			}
			if (wjp) {
				used[i]=used[j]=true;
				cnt-=2;
				break;
			}
		}
	}
	if (cnt==0) return true;
	if (cnt==1&&m%2==1) {
		rep(i,1,m) if (!used[i]) {
			rep(j,1,n) if (s[j][i]!=s[match[j]][i]) return false;
			break;
		}
		return true;
	}
	return false;
}

void dfs(int dep) {
	if (flag) return ;
	if (dep==(n+1)/2+1) return (void) (flag|=check());
	rep(i,1,n) if (!match[i]) {
		rep(j,i+1,n) if (!match[j]) {
			match[i]=j; match[j]=i;
			dfs(dep+1);
			match[i]=match[j]=0;
		}
		if ((n&1)&&!lxf) {
			match[i]=i; lxf=true;
			dfs(dep+1);
			match[i]=0; lxf=false;
		}
	}
}

