bool check(vector<string> const &chars, vector<pair<int,int>> const &pairs) {
    size_t h = chars.size();
    vector<bool> used(h);
    for (size_t i = 0; i < h; i++) {
        if (used[i]) continue;
        for (size_t j = i+1; j < h; j++) {
            bool ok = true;
            if (used[j]) continue;
            for (auto const &x: pairs) {
                if (chars[i][x.first] != chars[j][x.second] || chars[j][x.first] != chars[i][x.second]) {
                    ok = false;
                    break;
                }
                if (ok) used[i] = used[j] = true;
            }
        }
    }
    if (count(used.begin(), used.end(), false) > 1) {
        return false;
    }
    if (h&1) {
        for (size_t i = 0; i < h; i++) {
            if (used[i]) continue;
            for (auto const &x: pairs) {
                if (chars[i][x.first] != chars[i][x.second]) {
                    return false;
                }
            }
        }
    }
    return true;
}

bool calc(vector<string> const &chars, vector<bool> &used, vector<pair<int,int>> &pairs) {
    auto w = used.size();
    if (pairs.size() == w/2) {
        return check(chars, pairs);
    } else {
        for (size_t x1 = 0; x1 < w; x1++) {
            if (used[x1]) continue;
            for (size_t x2 = x1+1; x2 < w; x2++) {
                if (used[x2]) continue;
                used[x1] = used[x2] = true;
                pairs.push_back(make_pair(x1, x2));
                if (calc(chars, used, pairs)) return true;
                pairs.pop_back();
                used[x1] = used[x2] = false;
            }
            break;
        }
    }
    return false;
}

int main() {
    int h, w;
    cin >> h >> w;
    vector<string> chars(h);
    for (int i = 0; i < h; i++) cin >> chars[i];

    vector<bool> used(w);
    vector<pair<int,int>> pairs; pairs.reserve(w/2);
    cout << (calc(chars, used, pairs) ? "YES" : "NO") << endl;

    return 0;
}

