vector<PII> v;
bool dfs(int x,int y,bool fl)
{
	if (x & (1<<y)) return dfs(x,y+1,fl);
	if (x==(1<<n)-1)
	{
		memset(ok,0,sizeof(ok));
		memset(bad,0,sizeof(bad));
		for (int i=0;i<m;i++)
			for (int j=0;j<m;j++)
				for (int k=0;k<v.size();k++)
					bad[i][j]|=forb[v[k].Fst][v[k].Snd][i][j]; 
		ok[0][0]=1;
		for (int i=0;i<(1<<m)-1;i++)
		{
			for (int j=0;j<m;j++)
			{
				if (i & (1<<j)) continue;
				for (int k=j;k<m;k++)
				{
					if ((i & (1<<k)) || (m%2==0 && j==k) || bad[j][k]) continue;
					if (j!=k)
					{
						ok[0][i|(1<<j)|(1<<k)]|=ok[0][i];
						if (m%2!=0) ok[1][i|(1<<j)|(1<<k)]|=ok[1][i];
					}
					else ok[1][i|(1<<j)]|=ok[0][i];
				}
				break;
			}
		}
		return ok[m%2!=0][(1<<m)-1];
	}
	for (int i=y;i<n;i++)
	{
		if (si[i]!=si[y] || (x & (1<<i)) || (!fl && i==y)) continue;
		v.push_back(MP(i,y));
		if (dfs(x|(1<<i)|(1<<y),y+1,fl&(i!=y))) return 1;
		v.pop_back();
	}
	return 0;
}
