    REP(id2,w)if((~msk>>id2&1) && id1!=id2 && g[id1][id2] >= cnt){
      ok[msk + (1<<id1) + (1<<id2)] = true;
    }
  }
  return ok[(1<<w)-1];
}

bool dfs(int rest){
  if(rest == 0){
    return match();
  }
  if(rest == 1){
    int id = 0;
    REP(i,h)if(!used[i])id=i;
    REP(i,w)REP(j,w)if(s[id][i]==s[id][j])g[i][j]++;
    cnt++;
    if(dfs(rest-1))return true;
    REP(i,w)REP(j,w)if(s[id][i]==s[id][j])g[i][j]--;
    cnt--;
    return false;
  }
  int id1 = 0;
  REP(i,h)if(!used[i])id1=i;
  REP(id2,h)if(!used[id2] && id1!=id2){
    used[id1] = used[id2] = true;
    REP(i,w)REP(j,w){
      if(s[id1][i] != s[id2][j])continue;
      if(s[id1][j] != s[id2][i])continue;
      g[i][j]++;
    }
    cnt++;
    if(dfs(rest-2))return true;
    used[id1] = used[id2] = false;
    REP(i,w)REP(j,w){
      if(s[id1][i] != s[id2][j])continue;
      if(s[id1][j] != s[id2][i])continue;
      g[i][j]--;
    }
    cnt--;
  }
  return false;
}

