		ull nowhash = 0;
		for(int j = 1; j <= m; j++)
			nowhash = nowhash * base + (s1[j] - 'a' + 1);
		Hash[i] = nowhash;
		a[0][i] = i;
	}
	dfs(0);
	puts("NO");
}

