bool check(vector<char> s, vector<char> t) {
  int n = s.size();
  for (int i = 0; i < s.size(); ++i) {
    if (s[i] == '-') continue;
    for (int j = i + 1; j < t.size(); ++j) {
      if (t[j] == '-') continue;
      if (s[i] == t[j] && s[j] == t[i]) {
        s[i] = t[i] = s[j] = t[i] = '-';
        n -= 2;
      }
    }
  }

  return (s.size() & 1 ? n == 1 : n == 0);
}

bool dfs(int bit) {
  if (bit == (1 << h) - 1) return true;

  if (dp[bit] != -1) return dp[bit];

  for (int i = 0; i < h; ++i) {
    if (bit & (1 << i)) continue;
    for (int j = i + 1; j < h; ++j) {
      if (bit & (1 << j)) continue;

      if (check(a[i], a[j])) {
        if (dfs(bit | (1 << i) | (1 << j))) return dp[bit] = true;
      }
    }
  }

  return dp[bit] = false;
}

