bool check()
{
    memset(used, false, sizeof(used));
    for(int i = 0; i < m; i ++) {
        if(used[i])
            continue;
        for(int j = 0; j < m; j ++) {
            bool cur = true;
            if(i == j || used[j])
                continue;
            for(int k = 0; k < n; k ++) {
                if(s[swaped[k]][i] != s[k][j]) {
                    cur = false;
                    break;
                }
            }
            if(cur) {
                used[i] = used[j] = true;
                break;
            }
        }
    }

    int cnt = 0, noused = -1;
    for(int i = 0; i < m; i ++)
        if(!used[i])
            cnt ++, noused = i;
    if((cnt >= 2 ) || (cnt && (m % 2 == 0)))
        return false;
    for(int i = 0; i < n; i ++)
        if(s[swaped[i]][noused] != s[i][noused])
            return false;
    return true;
}

void dfs(int u, int flag)
{
    if(u == (n + 1) / 2) {
        if(check())
            ans = true;
        return;
    }

    for(int i = u; i < n; i ++) {
        if(swaped[i] == -1) {
            for(int j = i + 1; j < n; j ++) {
                if(swaped[j] >= 0)
                    continue;

                swaped[i] = i;
                swaped[j] = j;
                dfs(u + 1, flag);

                swaped[i] = j;
                swaped[j] = i;
                dfs(u + 1, flag);
                swaped[i] = swaped[j] = -1;
            }
            if(flag) {
                swaped[i] = i;
                dfs(u + 1, false);
            }
            break;
        }
    }
}

