  Spacial<int> det(h, Graph<int>(h, vi(w, 0)));
  Graph<bool> bdet(h, vb(h, true));

  rep(i,h) {
    map<char, int> self;
    rep(k,w) {
      self[g[i][k]] += 1<<k;
    }
    bool odd = false;
    for (auto &p : self) {
      bitset<12> s(p.second);
      if (s.count() & 1) {
        if (odd) {
          bdet[i][i] = false;
          break;
        }
        odd = true;
      }
      rep(k,w) {
        if (s[k]) {
          det[i][i][k] = p.second;
        }
      }
    }

    rep(j,i) {
      map<pcc, int> comb;
      rep(k,w) {
        comb[{g[i][k], g[j][k]}] += 1<<k;
      }
      bool odd = false;
      for (auto &p : comb) {
        pcc q = {p.first.second, p.first.first};
        bitset<12> s(p.second);
        if (!comb.count(q)) {
          bdet[i][j] = bdet[j][i] = false;
          break;
        }
        if (q.first == q.second) {
          if (s.count() & 1) {
            if (odd) {
              bdet[i][j] = bdet[j][i] = false;
              break;
            }
            odd = true;
          }
        } else if (__builtin_popcount(comb[q]) != s.count()) {
          bdet[i][j] = bdet[j][i] = false;
          break;
        }
        rep(k,w) {
          if (s[k]) {
            det[i][j][k] = det[j][i][k] = comb[q];
          }
        }
      }
    }
  }

  rest = (1<<h)-1;
  if (h&1) {
    rep(i,h) {
      rest[i] = false;
      if (dfs(det, bdet, i)) return true;
      rest[i] = true;
    }
    return false;
  }
  return dfs(det, bdet, -1);
}

void solve() {
  int h, w; cin >> h >> w;
  rep(i,h) rep(j,w) cin >> g[i][j];

  CoutYN(row(h, w), "YES", "NO");
}


