static int H, W;
static char A[16][16];

static bool solve1() {
	map<char, int> mm;
	for (int i = 0; i < H; i++)
		mm[A[i][0]]++;
	int c = 0;
	foreach (v, mm)
		if (v.second & 1)
			c++;
	if (c > 1)
		return false;
	if (c == 0)
		return true;
	return H & 1;
}

static bool matches(const char *x, const char *y) {
	for (int i = 0; i < W; i++)
		if (x[i] != y[W - i - 1])
			return false;
	return true;
}

static bool good(char B[16][16]) {
	int m = 0;
	int b = 0;
	for (int i = 0; i < H; i++) {
		if (m & (1 << i))
			continue;
		bool good = false;
		for (int j = i + 1; j < H; j++)
			if (matches(B[i], B[j])) {
				m |= (1 << j);
				good = true;
				break;
			}
		if (!good) {
			b++;
			if (b > 1 || H % 2 == 0 || !matches(B[i], B[i]))
				return false;
		}
	}
	return true;
}

static void fillcol(char B[16][16], int t, int f) {
	for (int i = 0; i < H; i++)
		B[i][t] = A[i][f];
}

static bool solve2() {
	char B[16][16];
	int m = W / 2;
	for (int mm = 0; mm < (1 << W); mm++) {
		if (__builtin_popcount(mm) != m)
			continue;
		int bc[16];
		int b = 0, c = 0;
		for (int i = 0; i < W; i++)
			if (mm & (1 << i)) {
				fillcol(B, b++, i);
			} else {
				bc[c++] = i;
			}
		do {
			for (int i = 0; i < H; i++)
				for (int j = 0; j < c; j++)
					B[i][m + j] = A[i][bc[j]];
			if (good(B))
				return true;
		} while(next_permutation(&bc[0], &bc[c]));

	}

	return false;
}

static
bool good() {
	if (W == 1)
		return solve1();
	return solve2();
	//if (solve10())
