	if(rest.empty()){
		check(idx);
	}
	else{
		int a = rest.back();
		rest.pop_back();
		if(idx.size() & 1){
			int &cent = idx[idx.size() / 2];
			if(cent == -1){
				cent = a;
				dfs(i, idx, rest);
				cent = -1;
			}
		}

		idx[i] = a;
		for(int &x : rest){
			int &rt = idx[idx.size() - i - 1];
			int y = x;
			x = -1;
			rt = y;
			dfs(i + 1, idx, rest);
			rt = -1;
			x = y;
		}
		idx[i] = -1;
	}
}

