		if (U[i] == U2 && V1 % 2 == 1) Z2++;
		else if (V1 % 2 == 1) Z1++;

		M2[U[i]] = true; M2[U2] = true;
	}
	if (W % 2 == 0 && Z1 + Z2 == 0) ans = true;
	if (W % 2 == 1 && Z1 == 0 && Z2 == 1) ans = true;
}

void dfs(vector<pair<int, int>>vec) {
	if (vec.size() == H / 2) {
		vector<int>G;
		bool uses[12]; for (int i = 0; i < 12; i++) uses[i] = false;
		for (int i = 0; i < vec.size(); i++) { G.push_back(vec[i].first); uses[vec[i].first] = true; uses[vec[i].second] = true; }
		for (int i = 0; i < H; i++) { if (uses[i] == false) G.push_back(i); }
		for (int i = vec.size() - 1; i >= 0; i--) { G.push_back(vec[i].second); }

		for (int i = 0; i < H; i++) {
			for (int j = 0; j < W; j++) d[i][j] = c[G[i]][j];
		}
		solve();
		return;
	}
	bool used[12]; for (int i = 0; i < 12; i++) used[i] = false;
	for (int i = 0; i < vec.size(); i++) { used[vec[i].first] = true; used[vec[i].second] = true; }
	for (int i = 0; i < H; i++) {
		for (int j = i + 1; j < H; j++) {
			if (used[i] == true || used[j] == true) continue;
			pair<int, int>S = make_pair(0, 0); if (vec.size() >= 1) S = vec[vec.size() - 1];
			if (S >= make_pair(i, j)) continue;
			vector<pair<int, int>>vec2 = vec;
			vec2.push_back(make_pair(i, j));
			dfs(vec2);
		}
	}
}

