void gen(int n, bitset<12> used, vector<int>& cur, vector<vector<int>>& res) {
    for (int i = 0; i < n; ++i) {
        if (!used.test(i)) {
            used.set(i);
            for (int j = i + 1; j < n; ++j) {
                if (!used.test(j)) {
                    used.set(j);
                    cur[i] = j;
                    cur[j] = i;
                    gen(n, used, cur, res);
                    used.reset(j);
                }
            }
            used.reset(i);
            return;
        }
    }
    res.push_back(cur);
}

