bool checkCols(){
	// for(int i=1; i<=n; ++i) dump(grid[i]);
	// dump(ln);
	set<string> cols;
	map<string, int> colsOcc;
	for(int c=1; c<=m; ++c) ++colsOcc[getCol(c)];
	for(auto ele: colsOcc) cols.insert(ele.first);

	bool foundPalind = false;
	while(!cols.empty()){
		string cur = *cols.begin();
		--colsOcc[cur];
		if(!colsOcc[cur]) cols.erase(cur);

		string rev = cur;
		reverse(all(rev));
		if(cols.count(rev)){
			--colsOcc[rev];
			if(!colsOcc[rev]) cols.erase(rev);
			continue;
		}

		if(!(m&1)) return false;
		if(!(cur == rev)) return false;
		if(foundPalind) return false;
		foundPalind = true;
	}

	return true;
}

bool possible(int i){
	int j = n-i+1;
	if(i >= j) return checkCols();

	for(int k = i+1; k<=j; ++k){
		// choosing pair(i,k)
		swap(grid[k], grid[j]);
		if(possible(i+1)) return true;
		swap(grid[k], grid[j]);
	}
	return false;
}

