bool calc(vector<string> const &chars, vector<int> const &hswap, vector<int> const &wswap, mdview const &hgv, mdview const &wgv) {
    // print(hgv), print(wgv);
    for (auto hs: hswap) {
        for (auto ws: wswap) {
            if (hs == -1 || ws == -1) continue;
            int y1 = hgv[hs][0];
            int x1 = wgv[ws][0];
            int y2 = hgv[hs][1];
            int x2 = wgv[ws][1];
            if (chars[y1][x1] != chars[y2][x2] || chars[y2][x1] != chars[y1][x2]) return false;
        }
    }
    return true;
}

pair<vector<int>,int> organize(vector<vector<map<pair<int,int>, int>>> const &pairs, int upto) {
    vector<int> gs(upto, -1);
    int g = 0;
    for (int i = 0; i < upto; i++) {
        if (gs[i] != -1) continue;
        for (int j = i+1; j < upto; j++) {
            if (gs[j] != -1) continue;
            bool ok = true;
            for (auto const &x: pairs[i][j]) {
                auto const &lkey = x.first;
                auto rkey = make_pair(lkey.second, lkey.first);
                if (!pairs[i][j].count(rkey) || x.second != pairs[i][j].at(rkey)) {
                    ok = false; break;
                }
            }
            if (ok) {
                gs[i] = gs[j] = g;
                // break;
            }
        }
        g++;
    }
    // cerr << "gs: ";
    // copy(gs.begin(), gs.end(), ostream_iterator<int>(cerr, ", "));
    // cerr << endl;
    if (count(gs.begin(), gs.end(), -1) > 1) {
        return make_pair(gs, -1);
    }
    return make_pair(gs, g);
}

