	bool rest[15];
	rep(j,w) rest[j] = true;

	int total = w;

	while(total >= 2){
		bool found = false;

		const int n = w;

		rep(j,n)rep(i,j){
			if(rest[i] == false  or rest[j] == false) continue;

			bool same = true;
