			if(same){
				rest[i] = false;
				rest[j] = false;
				total -=2;
				found = true;
			}
		}

		if(found == false) return false;
	}


	if(total == 0) return true;

	string str = "";
	rep(j,w) if(rest[j]) str = collect[j];
