	if(ans == 1) return;
	if(x == n+1){ check(); return; }
	if(pp[x] > 0){ dfs(x+1, op); return; }
	for(int i = x+1; i <= n; i++){
		if(!pp[i]){
			pp[i] = x; pp[x] = i;
			dfs(x+1, op);
			pp[i] = pp[x] = 0;
		}
	}
	if(n&1 && !op) dfs(x+1, 1);
}
