const int MAX = 20;
string mat[MAX], buffer[MAX];
bool used[MAX];
int n, m;

void die(string s) {
	cout << s << '\n';
	exit(0);
}

bool palindrome(const string &s) {
	return equal(s.begin(), s.end(), s.rbegin());
}

bool valid(const vector<int> &perm) {
	fori(i, 0, n) {
		buffer[i] = mat[i];
	}

	multiset<string> S;
	fori(i, 0, n) {
		fori(j, 0, m) {
			buffer[i][j] = mat[i][perm[j]];
		}

		S.insert(buffer[i]);
	}

	while(S.size() > 1) {
		string first = *S.begin(); S.erase(S.begin());

		string revF = first;
		reverse(revF.begin(), revF.end());

		if(S.count(revF)) {
			S.erase(S.find(revF));	
		}
		else {
			string other = *S.begin(); S.erase(S.begin());
			S.insert(first);

			revF = other;
			reverse(revF.begin(), revF.end());

			if(S.count(revF)) {
				S.erase(S.find(revF));
			}
			else {
				return false;
			}
		}
	}


	if(S.size() == 1) {
		string f = *S.begin();

		if(!palindrome(f)) {
			return false;
		}
	}

	return true;
}

vector<int> state;
void backtrack(int index) {
	if(2 * index >= m - 1) {
		if(valid(state)) {
			die("YES");
		}
		return;
	}

	fori(i, 0, m) {
		if(!used[i]) {
			used[i] = true;
			state[index] = i;

			fori(j, i + 1, m) {
				if(!used[j]) {
					used[j] = true;
					state[m - index - 1] = j;

					backtrack(index + 1);

					used[j] = false;
				}
			}

			used[i] = false;

			break;
		}
	}
}

int main() {
	ios_base::sync_with_stdio(false);

	cin >> n >> m;

	state.resize(m, 0);

	fori(i, 0, n) {
		cin >> mat[i];
	}

	if(m & 1) {
		fori(i, 0, m) {
			state[m / 2] = i;
			used[i] = true;
			backtrack(0);
			used[i] = false;
		}
	}
	else {
		backtrack(0);
	}

	die("NO");

	return 0;
}

