const int MAX = 15;

int h, w;
char in[MAX][MAX];

deque<char> Apply(int row, const vector<pii>& prs){
  deque<char> res;
  for(int i = sz(prs) - 1;i >= 0;--i){
    int a = prs[i].fi, b = prs[i].se;
    res.push_front(in[row][a]);
    res.pb(in[row][b]);
  }
  return res;
}

bool fine = false;

bool Validate(const vector<pii>& _prs){
  vector<pii> prs;
  for(const auto& e : _prs)
    if(e.fi != e.se) prs.pb(e);
  for(const auto& e : _prs)
    if(e.fi == e.se) prs.pb(e);

  vector<deque<char>> wrds;
  for(int i = 0;i < h;++i)
    wrds.pb(Apply(i, prs));

  while(!wrds.empty()){
    int ss = sz(wrds);
    for(int i = 0;i < min(2, sz(wrds));++i){
      auto a = wrds[i];
      auto b = a;
      reverse(all(b));

      if(sz(wrds) == 1){
        return a == b;
      }

      int j;
      for(j = 0;j < sz(wrds);++j)
        if(i != j && wrds[j] == b)
          break;

      if(j == sz(wrds)) continue;
      wrds.erase(wrds.begin() + max(i, j));
      wrds.erase(wrds.begin() + min(i, j));
      break;
    }
    if(sz(wrds) == ss) return false;
  }

  return true;
}

void Iterate(vector<pii>& prs, bool has_same){
  if(fine) return;

  vector<char> free(w, true);
  for(const auto& e : prs)
    free[e.fi] = free[e.se] = false;

  if(count(all(free), true) == 0){
    fine = (fine || Validate(prs));
  } else {
    for(int a = 0;a < w;++a)
      if(free[a]){
        if(!has_same) prs.pb(mp(a, a)),
                      Iterate(prs, true),
                      prs.pop_back();
        for(int b = a + 1;b < w;++b)
          if(free[b]) prs.pb(mp(a, b)),
                      Iterate(prs, has_same),
                      prs.pop_back();
        break;
      }
  }
}

int main(){
  scanf("%d%d", &h, &w);
  for(int i = 0;i < h;++i)
    scanf("%s", in[i]);

  vector<pii> prs;
  Iterate(prs, false);

  printf(fine ? "YES\n" : "NO\n");

  return 0;
}

