void solve () {
	int M = 0;
	for(int i=1;i<=h;i++) v2[i] = false;
	for(int i=1;i<=h;i++) {
		if(v2[i]) continue;
		for(int j=i+1;j<=h;j++) {
			if(v2[j]) continue;
			int flag = false;
			for(int k=1;k<=w;k++) {
				if(a[i][k] != a[j][mat[k]]) {flag = true; break;}
			}
			if(!flag) {v2[i] = true; v2[j] = true; M++;}
		}
	}
	if(M == h/2) {puts("YES"); exit(0);}
}

void Try (int X, bool F) {
	if(X == (w+1)/2+1) {solve(); return;}
	int I = 1;
	for(;I<=w;I++) {
		if(!vis[I]) break;
	}
	vis[I] = true;
	if(!F && w%2==1) {mat[I] = I; Try(X+1, true);}
	for(int i=1;i<=w;i++) {
		if(!vis[i]) {
			mat[I] = i; mat[i] = I;
			vis[i] = true;
			Try(X+1, F);
			vis[i] = false;
		}
	}
	vis[I] = false;
}

