bool check() {
    VS b(H);
    VB bused(H);
    REP(i, H) {
        if(bused[lp[i]]) {
            b[H - 1 - lp[i]] = S[i];
        } else {
            b[lp[i]] = S[i];
            bused[lp[i]] = true;
        }
    }
    VL wp(W, -1);
    bool odd = W % 2;
    REP(i, W) {
        if(wp[i] != -1) continue;
        wp[i] = i;
        bool ok = false;
        REP(ii, W) {
            if(wp[ii] != -1) continue;

            ok = true;
            REP(h, H) {
                if(b[h][i] != b[H - 1 - h][ii]){
                    ok = false;
                    break;
                }
            }
            if(ok) {
                wp[ii] = i;
                break;
            }
        }
        if(!ok) {
            if(odd) {
                if(!center(i, b)) return false;
                odd = false;
            } else{
                return false;
            }
        }
    }
    return true;
}

bool addline() {
    H++;
    REP(i, H - 1) {
        S[H - 1] = S[i];
        if(dfs(0)) return true;
    }
    return false;
}

bool dfs(ll pnum) {
    if(H % 2) return addline();
    if(pnum == W / 2) return check();
    ll idx1 = -1;
    REP(i, H) {
        if(lp[i] != -1) continue;
        lp[i] = pnum;
        idx1 = i;
        break;
    }
    REP(i, H) {
        if(lp[i] != -1) continue;
        lp[i] = pnum;
        if(dfs(pnum + 1)) return true;
        lp[i] = -1;
    }
    lp[idx1] = -1;
    return false;
}

