			sort(t2.begin(), t2.end());
			if (t1 == t2) {
				r_idx[idx++] = i;
				r_pair[i] = j;
				ok = vis[i] = vis[j] = 1; break;
			}
		}
		if (!ok) { flag ++; single = i; }
	}
	if (flag > 1) {
		cout << "NO\n"; return 0;
	} else r_idx[idx++] = single;

	memset(vis, 0, sizeof(vis));
	idx = flag = 0; single = -1;
	for (int i = 0; i < w; i ++) {
		if (vis[i]) continue;
		string t1 = "";
		for (int j = 0; j < h; j ++) t1 += s[j][i];
		sort(t1.begin(), t1.end());
		bool ok = false;
		for (int j = i+1; j < w; j ++) {
			if (vis[j]) continue;
			string t2 = "";
			for (int k = 0; k < h; k ++) t2 += s[k][j];
			sort(t2.begin(), t2.end());
			if (t1 == t2) {
				c_idx[idx++] = i;
				c_pair[i] = j;
				ok = vis[i] = vis[j] = 1; break;
			}
		}
		if (!ok) { flag ++; single = i; }
	}
	if (flag > 1) {
		cout << "NO\n"; return 0;
	} else c_idx[idx++] = single;

	string per1 = "";
	for (int i = 0; i < h/2; i ++) per1 += to_string(i);

	string t[20], tmp[20];
	do {
		for (int i = 0; i < per1.size(); i ++) {
			int no = per1[i] - '0';
			t[no] = s[r_idx[no]];
			t[h-no-1] = s[r_pair[r_idx[no]]];
		}
		if (h%2) t[h/2] = s[r_idx[h/2]];
		copy(t, t+h, tmp);
		string per2 = "";
		for (int i = 0; i < w/2; i ++) per2 += to_string(i);
		do {
			copy(tmp, tmp+h, t);
			for (int i = 0; i < per2.size(); i ++) {
