bool dfs1(int n,bool f){
  if(n == w){
    return dfs2(0,(h % 2 == 1));
  }
  if(ccmatch[n] != -1)
    return dfs1(n+1,f);
  for(int i = 0;i < w;++i){
    if(i != n && ccmatch[i] == -1){
      ccmatch[i] = n;
      ccmatch[n] = i;
      bool res = dfs1(n+1,f);
      ccmatch[i] = -1;
      ccmatch[n] = -1;
      if(res)
        return true;
    }
  }
  if(f){
    ccmatch[n] = n;
    bool res = dfs1(n+1,false);
    ccmatch[n] = -1;
    if(res)
      return true;
  }
  return false;
}

bool ok(int r1,int r2){
  for(int i = 0;i < w;++i){
    if(grid[r1][i] != grid[r2][ccmatch[i]] ||
       grid[r1][ccmatch[i]] != grid[r2][i])
      return false;
  }
  return true;   
}

bool pal(int r){
  for(int i = 0;i < w;++i)
    if(grid[r][i] != grid[r][ccmatch[i]])
      return false;
  return true;
}

bool dfs2(int n,bool f){
  if(n == h)
    return true;
  if(rmatch[n] != -1)
    return dfs2(n+1,f);
  for(int i = 0;i < h;++i){
    if(i != n && rmatch[i] == -1 && ok(n,i)){
      rmatch[i] = n;
      rmatch[n] = i;
      bool res = dfs2(n+1,f);
      rmatch[i] = -1;
      rmatch[n] = -1;
      if(res)
        return true;
    }
  }
  if(f && pal(n)){
    rmatch[n] = n;
    bool res = dfs2(n+1,false);
    rmatch[n] = -1;
    if(res)
      return true;
  }
  return false;
}



