void dfs(vector<int>& used, int i, bool ok) {
    if(i == h) {
        //
        vector<bool> u(h, 0);
        deque<int> que1, que2;
        int mid = -1;
        rep(j, h) {
            if(!u[j]) {
                if(used[j] == j) {
                    mid = j;
                    u[j] = j;
                    continue;
                }
                que1.push_back(j); que2.push_back(used[j]);
                u[used[j]] = 1, u[j] = 1;
            }
        }
        vector<vector<char>> f(h, vector<char>(w, '?'));
        int cur = 0;
        while(que1.size()) {
            int j = que1.front(); que1.pop_front();
            rep(k, w) {
                f[cur][k] = s[j][k];
            }
            ++ cur;
        }
        if(mid != -1) {
            rep(k, w) {
                f[cur][k] = s[mid][k];
            }
            ++ cur;
        }
        while(que2.size()) {
            int j = que2.back(); que2.pop_back();
            rep(k, w) {
                f[cur][k] = s[j][k];
            }
            ++ cur;
        }
        // rep(i, h) {
        //     rep(j, w) {
        //         cerr << f[i][j];
        //     }
        //     cerr << endl;
        // }
        // cerr << endl;
        bool check = 1;
        unordered_map<string, int> mp;
        rep(j, w) {
            string res = "";
            rep(k, h) res += f[k][j];
            mp[res] ++;
        }
        int mi = 0;
        for(auto x: mp) {
            string tmp = x.fr; int co = x.sc;
            if(co == -1) continue;
            string tmp1 = tmp; reverse(all(tmp1));
            if(tmp == tmp1) {
                if(co % 2 == 1) ++ mi;
            } else {
                if(abs(co - mp[tmp1]) == 1) {
                    ++ mi;
                    mp[tmp1] = -1;
                } else if(co == mp[tmp1]) {
                    mp[tmp1] = -1;
                    continue;
                }
                else {
                    check = 0;
                }
            }
        }
        if(w % 2 == 1) {
            if(mi == 1 && check) check = 1;
            else check = 0;
        } else {
            if(mi == 0 && check) check = 1;
            else check = 0;
        }
        //
        if(check) {
            cout << "YES" << endl;
            exit(0);
        }
        return;
    }
    if(used[i] != -1) {
        dfs(used, i + 1, ok);
        return;
    }
    if(ok) {
        used[i] = i;
        ok = 0;
        dfs(used, i + 1, ok);
        ok = 1;
        used[i] = -1;
    }
    for(int j = i + 1; j < h; ++ j) {
        if(used[j] != -1) continue;
        used[i] = j, used[j] = i;
        dfs(used, i + 1, ok);
        used[i] = -1, used[j] = -1;
    }
}

