}

#include<bits/stdc++.h>
using namespace std;

int H, W;
vector<string> S;

bool check(auto group) {
  vector<string> upper, lower;
  for(auto i=0; i<H; ++i) {
    if((group>>i) & 1) upper.emplace_back(S[i]);
    else               lower.emplace_back(S[i]);
  }
  vector<string> T(begin(upper), end(upper));
  T.insert(end(T), begin(lower), end(lower));
  sort(begin(T), begin(T) + upper.size());
  do {
    vector<string> column(W);
    for(auto j=0; j<W; ++j) for(auto i=0; i<H; ++i) column[j] += T[i][j];
    auto ok = true;
    set<string> uniq;
    map<string, int> m;
    for(auto s: column) ++m[s];
    for(auto s: column) {
      auto t = s;
      reverse(begin(t), end(t));
      if(s == t) {
        if(m[s]&1) uniq.emplace(s);
      } else {
        if(m[s] != m[t]) ok = false;
      }
    }
    if(ok && uniq.size()<=1) return true;
  } while(next_permutation(begin(T), begin(T) + upper.size()));
  return false;
}

unordered_set<int> memo;
bool dfs(auto group, auto i, auto n) {
  if(n + H-1-i < (H+1)/2) return false;
  if(n == (H+1)/2) {
    if(memo.count(group)) return false;
    memo.emplace(((1<<H)-1)^group);
    return check(group);
  }
  if(i == H) return false;
  return dfs(group, i+1, n) || dfs(group | (1<<i), i+1, n+1);
}

string solve() {
  return dfs(0, 0, 0) ? "YES" : "NO";
}

int main() {
  cin >> H >> W;
  S.resize(H);
  for(auto& s: S) cin >> s;
  cout << solve() << endl;
}

