int r_idx[20], r_pair[20], c_idx[20], c_pair[20];
bool vis[20];

int main() {
	int h, w; cin >> h >> w;
	string s[20];
	for (int i = 0; i < h; i ++) cin >> s[i];

	bool vis[20] = {0};
	int idx = 0, flag = 0, single = -1;
	for (int i = 0; i < h; i ++) {
		if (vis[i]) continue;
		string t1 = s[i];
		sort(t1.begin(), t1.end());
		bool ok = false;
		for (int j = i+1; j < h; j ++) {
			if (vis[j]) continue; 
			string t2 = s[j];
			sort(t2.begin(), t2.end());
			if (t1 == t2) {
				r_idx[idx++] = i;
				r_pair[i] = j;
				ok = vis[i] = vis[j] = 1; break;
			}
		}
		if (!ok) { flag ++; single = i; }
	}
	if (flag > 1 || flag == 1 && h%2 == 0) {
		cout << "NO\n"; return 0;
	} else r_idx[idx++] = single;

	memset(vis, 0, sizeof(vis));
	idx = flag = 0; single = -1;
	for (int i = 0; i < w; i ++) {
		if (vis[i]) continue;
		string t1 = "";
		for (int j = 0; j < h; j ++) t1 += s[j][i];
		sort(t1.begin(), t1.end());
		bool ok = false;
		for (int j = i+1; j < w; j ++) {
			if (vis[j]) continue;
			string t2 = "";
			for (int k = 0; k < h; k ++) t2 += s[k][j];
			sort(t2.begin(), t2.end());
			if (t1 == t2) {
				c_idx[idx++] = i;
				c_pair[i] = j;
				ok = vis[i] = vis[j] = 1; break;
			}
		}
		if (!ok) { flag ++; single = i; }
	}
	if (flag > 1 || flag == 1 && w%2 == 0) {
		cout << "NO\n"; return 0;
	} else c_idx[idx++] = single;

	string per1 = "";
	for (int i = 0; i < h/2; i ++) per1 += to_string(i);

	string t[20];
	do {
		for (int i = 0; i < per1.size(); i ++) {
			int no = per1[i] - '0';
			t[no] = s[r_idx[no]];
			t[h-no-1] = s[r_pair[r_idx[no]]];
		}
		if (h%2) t[h/2] = s[r_idx[h/2]];
		string per2 = "";
		for (int i = 0; i < w/2; i ++) per2 += to_string(i);
		do {
			for (int i = 0; i < per2.size(); i ++) {
				int no1 = per2[i] - '0', no2 = w-no1-1, cor1 = c_idx[no1], cor2 = c_pair[cor1];
				for (int j = 0; j < h; j ++) {
					char ch = t[j][no1]; t[j][no1] = t[j][cor1]; t[j][cor1] = ch;
				}
				for (int j = 0; j < h; j ++) {
					char ch = t[j][no2]; t[j][no2] = t[j][cor2]; t[j][cor2] = ch;
				}
			}
			bool flag = true;
			for (int i = 0; i < h/2; i ++) {
				string cor = t[h-i-1];
				reverse(cor.begin(), cor.end());
				if (t[i] != cor) { flag = false; break; }
			}
			for (int i = 0; i < w/2; i ++) {
				string ori = "", cor = "";
				for (int j = 0; j < h; j ++) {
					ori += t[j][i]; cor += t[j][w-i-1];
				}
				reverse(cor.begin(), cor.end());
				if (ori != cor) { flag = false; break; }
			}
			if (h%2) {
				for (int i = 0; i < w/2; i ++)
					if (t[h/2][i] != t[h/2][w-i-1]) { flag = false; break; }
			}
			if (w%2) {
				for (int i = 0; i < h/2; i ++)
					if (t[i][w/2] != t[h-i-1][w/2]) { flag = false; break; }
			}
			if (flag) { cout << "YES\n"; return 0; }
		} while (next_permutation(per2.begin(), per2.end()));
	} while (next_permutation(per1.begin(), per1.end()));

	cout << "NO\n"; 
	return 0;
}

