bool check(ll H,ll W,vector<vector<char>>& masu){
    for(int i = 1; i <= H;i++){
        sort(masu[i].begin()+1,masu[i].end()-1);
    }
    vector<int> f(H+2,0);
    for(int i = 1; i <= H;i++){
        if(f[i] == 1) continue;
        for(int j = i+1; j <= H;j++){
            if(f[j] == 1) continue;
            int k = 1;
            for(; k <= W;k++){
                if(masu[i][k] == masu[j][k]) continue;
                break;
            }
            if(k > W){
                f[i] = f[j] = 1;
                break;
            }
        }
    }
    ll cnt = accumulate(f.begin(),f.end(),0);
    if(H%2 == 0){
        if(cnt == W) return true;
        else return false;
    }else{
        if(cnt == W-1) return true;
        else return false;
    }
}
