void check()
{
	FOR(i, 1, W) assert(to[i]);
	FOR(i, 1, W) tmp[i] = to[i]; FOR(i, 1, W) to[tmp[i]] = i;

	char fir = (H & 1);
	memset(used, 0, sizeof used);

	FOR(i, 1, H) {
		if (!used[i]) {
			used[i] = true;
			char ok = false;
			FOR(j, i + 1, H) {
				if (!used[j]) {
					char flag = true;
					FOR(k, 1, W) if (s[j][to[W - k + 1]] != s[i][to[k]]) {flag = false; break;}
					if (flag) {ok = true; used[j] = true; break;}
				}
			}
			if (!ok) {
				if (fir) {
					char can = true;
					FOR(k, 1, W) if (s[i][to[k]] != s[i][to[W - k + 1]]) {can = false; break;}
					if (can) {fir = false; continue;}
				}
			}
			else continue;
			FOR(j, 1, W) to[j] = tmp[j];
			return;
		}
	}

	puts("YES"); exit(0);
}

void search(int now, int pos)
{
	if (vis[now]) {
		if (now == W) check();
		else search(now + 1, pos);
		return;
	}
	vis[now] = true;
	if ((W & 1) && !vis[0]) {
		vis[0] = true;
		to[now] = (W + 1) / 2;
		if (now == W) check();
		else search(now + 1, pos);
		vis[0] = false;
		to[now] = 0;
	}
	FOR(i, now + 1, W) {
		if (!vis[i]) {
			vis[i] = true;
			to[now] = pos;
			to[i] = (W - pos + 1);
			if (now == W) check();
			else search(now + 1, pos + 1);
			vis[i] = false;
			to[now] = to[i] = 0;
		}
	}
	vis[now] = false;
}

