bool check(vector<string> const &chars, vector<pair<int,int>> const &pairs) {
    int h = chars.size();
    vector<bool> paired(h);
    // cerr << "pairs: ";
    // for (auto const &p: pairs) cerr << "(" << p.first << "," << p.second << ") ";
    // cerr << endl;

    for (int i = 0; i < h; i++) {
        if (paired[i]) continue;
        for (int j = i+1; j < h; j++) {
            if (paired[j]) continue;
            // 行 i と 行 j がペアにできるか？

            bool is_reverse = true;
            for (auto const &x: pairs) {
                // 奇数の残り
                if (x.second == -1) {
                    if (chars[i][x.first] != chars[j][x.first]) {
                        is_reverse = false;
                        break;
                    }
                } else if (chars[i][x.first] != chars[j][x.second] || chars[i][x.second] != chars[j][x.first]) {
                    is_reverse = false;
                    break;
                }
            }

            // ちゃんと反転ならペアにする
            if (is_reverse) {
                // cerr << "    paired: ";
                // print(chars, i, pairs);
                // cerr << " and ";
                // print(chars, j, pairs);
                // cerr << endl;
                paired[i] = paired[j] = true;
            }
        }
    }

    // ペアになってないものが 2 つ以上あるとアウト
    if (count(paired.begin(), paired.end(), false) > 1) {
        // cerr << "    ... but there are " << count(paired.begin(), paired.end(), false) <<  " no-pair(s)." << endl;
        return false;
    }

    // 行数が奇数のときは
    if (h&1) {
        for (int i = 0; i < h; i++) {
            if (paired[i]) continue;
            // cerr << "    last line is ";
            // print(chars, i, pairs);
            // cerr << endl;
            for (auto const &x: pairs) {
                if (x.second == -1) continue;
                if (chars[i][x.first] != chars[i][x.second]) {
                    // cerr << "    ... but this line is not palindrome," << endl;
                    return false;
                }
            }
        }
    }
    return true;
}

bool calc(vector<string> const &chars, vector<bool> &paired, vector<pair<int,int>> &pairs) {
    int w = paired.size();
    if (static_cast<int>(pairs.size()) == w/2) {
        // w が奇数のとき
        if (w&1) {
            int np;
            for (np = 0; np < w; np++) if (!paired[np]) break;
            assert(np < w);
            pairs.push_back(make_pair(np, -1));
        }
        auto res = check(chars, pairs);
        if (w&1) pairs.pop_back();
        return res;
    } else {
        for (int x1 = 0; x1 < w; x1++) {
            if (paired[x1]) continue;
            for (int x2 = x1+1; x2 < w; x2++) {
                if (paired[x2]) continue;

                paired[x1] = paired[x2] = true;
                pairs.push_back(make_pair(x1, x2));
                if (calc(chars, paired, pairs)) return true;
                pairs.pop_back();
                paired[x1] = paired[x2] = false;
            }
            break;
        }
    }
    return false;
}

int main() {
    int h, w;
    cin >> h >> w;
    vector<string> chars(h);
    for (int i = 0; i < h; i++) cin >> chars[i];

    vector<bool> paired(w);
    vector<pair<int,int>> pairs; pairs.reserve(w/2);
    cout << (calc(chars, paired, pairs) ? "YES" : "NO") << endl;

    return 0;
}

