int H, W;
char S[20][20];
int rowperm[20];
bool row_used[20];

bool is_match(int j1, int j2){
    for(int i = 0; i < H; i++){
        if(S[rowperm[i]][j1] != S[rowperm[H - 1 - i]][j2]){
            return false;
        }
    }
    return true;
}

bool rec(int depth){
    if(depth == H / 2){
        for(int i = 0; i < W; i++){
            bool used[20] = {};
            if(W % 2){
                if(!is_match(i, i)){
                    continue;
                }
                used[i] = true;
            }

            for(int j = 0; j < W; j++){
                if(used[j]) continue;
                used[j] = true;
                bool ok = false;
                for(int k = 0; k < W; k++){
                    if(used[k]) continue;
                    if(j == k) continue;
                    if(is_match(j, k)){
                        used[k] = true;
                        ok = true;
                        break;
                    }
                }
                if(!ok) break;
            }

            int cnt = 0;
            for(int i = 0; i < W; i++)
                if(used[i]) cnt++;

            if(cnt == W) return true;

            if(W % 2 == 0) break;

            if(W % 2) used[i] = false;
        }
        return false;
    }
    else{
        int start = -1;
        for(int i = 0; i < H; i++){
            if(row_used[i]) continue;
            start = i;
            break;
        }

        row_used[start] = true;
        rowperm[depth] = start;

        for(int i = start + 1; i < H; i++){
            if(row_used[i]) continue;
            rowperm[H - 1 - depth] = i;
            row_used[i] = true;
            if(rec(depth + 1))
                return true;
            row_used[i] = false;
        }
        row_used[start] = false;
    }
    return false;
}

bool solve(){
    if(H % 2){
        for(int i = 0; i < H; i++){
            row_used[i] = true;
            rowperm[H / 2] = i;
            if(rec(0)){
                return true;
            }
            row_used[i] = false;
        }
        return false;
    }
    else{
        return rec(0);
    }
}

int main(){
    cin >> H >> W;
    for(int i = 0; i < H; i++) cin >> S[i];
    if(solve()){
        cout << "YES" << endl;
    }
    else{
        cout << "NO" << endl;
    }
    return 0;
}

