int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int H,W;
    cin >> H >> W;
    vvec<char> S(H,vec<char>(W));
    for(auto& v:S) for(auto& c:v) cin >> c;

    vvec<int> match(H,vec<int>(H));
    for(int i=0;i<H;i++) for(int j=0;j<H;j++){
        string s = "",t = "";
        for(int k=0;k<W;k++) s += S[i][k],t += S[j][k];
        sort(s.begin(),s.end());
        sort(t.begin(),t.end());
        bool ok = s==t;
        match[i][j] = match[j][i] = ok;
    }

    string init = "";
    for(int i=0;i<H;i++) init += '#';
    bool ok = false;

    auto is_palindrome = [](string s){
        string t = s;
        reverse(t.begin(),t.end());
        return s==t;
    };

    auto check = [&](vec<pair<int,int>> v){
        vec<string> A(W,init);
        int n = v.size();
        int c = 0;
        for(int i=0;i<n;i++){
            for(int j=0;j<W;j++){
                A[j][c] = S[v[i].first][j];
                if(v[i].second!=-1) A[j][H-1-c] = S[v[i].second][j];
            }
            c++;
        }
        vec<string> B = A;
        map<string,int> mp,rev;
        for(int i=0;i<W;i++){
            mp[A[i]]++;
            reverse(B[i].begin(),B[i].end());
            rev[B[i]]++;
        }
        int cnt = 0;
        for(auto& s:mp){
            if(!is_palindrome(s.first)) cnt += max(0,s.second-rev[s.first]);
            else cnt += (s.second%2==1? 1:0);
        }
        ok |= (cnt==0 || (cnt==1 && W%2==1));
    };

    vec<int> vis(H);
    auto dfs = [&](auto&& self,vec<pair<int,int>>& v,int dep)->void{
        if(v.size()==(H+1)/2) check(v);
        else{
            vec<int> now;
            for(int i=0;i<H;i++) if(!vis[i]) now.push_back(i);
            assert(!now.empty());
            if(now.size()==1){
                v.emplace_back(now[0],-1);
                vis[now[0]] = 1;
                self(self,v,dep+1);
                v.pop_back();
                vis[now[0]] = 0;
            }else{
                for(int i=0;i<H-1-2*dep;i++){
                    if(!match[now[0]][now[i+1]]) continue;
                    v.emplace_back(now[0],now[i+1]);
                    vis[now[0]] = vis[now[i+1]] = 1;
                    self(self,v,dep+1);
                    v.pop_back();
                    vis[now[0]] = vis[now[i+1]] = 0;
                }
            }
        }
    };
    vec<pair<int,int>> v;
    dfs(dfs,v,0);
    cout << (ok? "YES\n":"NO\n");
}

