		if(!done[i]){
			k = i;
			++cnt;
		}
	}
	if(cnt > 2){
		return false;
	}else if(!cnt){
		return true;
	}
	flag = true;
	i = 0; j = (w-1);
	while(i <= j){
		if(t[k][i] != t[k][j]){
			flag = false;
			break;
		}else{
			++i; --j;
		}
	}
	return flag;
}

bool solve(int status){
	int i,cnt=0;
	bool flag=true,ret=false;
	if(status == final){
		return check();
	}
	for(i=0; i<w; ++i){
		if((status&(1<<i))){
			++cnt;
		}
	}
	cnt /= 2;
	for(i=0; i<w; ++i){
		if(!(status&(1<<i))){
			if(flag){
				status += (1<<i);
				copy(i,w-cnt-1);
				flag = false;
				if(status == final){
					ret = check();
					break;
				}
			}else{
				copy(i,cnt);
				if(solve(status+(1<<i))){
					ret = true;
					break;
				}
			}
		}
	}
	return ret;
}

int main(void){
	int i,j;
	cin >> h >> w;
	final = (1<<w)-1;
	for(i=0; i<h; ++i){
		cin >> s[i];
		t[i] = s[i];
	}
	cout << ((solve(0))?"YES":"NO") << endl;
    return 0;
}

