	{
		for(int i = 0 ; i < 20; i++)
		{
			for(int j = 0; j < 20; j++)
				match[i][j] = true;
		}
		for(int k = 0; k < w; k++)
		{
			for(int j = k ; j < w; j++)
			{
				for(int i = 0; i < h; i++)
				{
					if(s[i][k] != s[h - 1 - i][j])
						match[k][j] = false;
				}
			}
		}
		memset(dp,0,sizeof(dp));
		dp[0] = true;
		for(int mask = 0; mask < (1 << w); mask++)
		{
			if(dp[mask] == false)
				continue;
			for(int i = 0 ; i < w; i++)
			{
				for(int j = i+1 ; j < w; j++)
				{
					if(!(mask >> i & 1) && !(mask >> j & 1) && match[i][j])
						dp[mask | (1 << i) | (1 << j)] = true;
				}
			}
		}
		bool can = false;
		if(w & 1)
		{
			for(int i = 0 ; i < w; i++)
			{
				if(dp[((1 << w) -1) - (1 << i)] && match[i][i])
				{
					can = true;
					break;
				}
			}
		}
		else
		{
			can = dp[(1 << w)-1];
		}
