void recurse(vector<int> v)
{
	if(ans)
	{
		return;
	}
	if(v.empty())
	{
		if(check())
		{
			ans=true;
		}
		return;
	}
	int first_num=v[0];
	v.erase(v.begin());
	if(v.empty())
	{
		fans.pb(mk(first_num,first_num));
		if(check())
		{
			ans=true;
		}
		fans.pop_back();
		return;
	}
	for(int i=0;i<v.size();i++)
	{
		vector<int> temp=v;
		int second_num=v[i];
		temp.erase(temp.begin()+i);
		fans.pb(mk(first_num,second_num));
		recurse(temp);
		fans.pop_back();
	}
}
