		if(!my_set.empty())
		{
			string rev_temp=temp;
			reverse(rev_temp.begin(),rev_temp.end());
			auto it=my_set.find(rev_temp);
			if(it!=my_set.end())
			{
				my_set.erase(it);
			}
			else
			{
				my_set.insert(temp);
			}
		}
		else
