	}
}
void recurse(vector<int> v)
{
	if(v.empty())
	{
		if(check())
		{
			ans=true;
		}
		return;
	}
	int first_num=v[0];
	v.erase(v.begin());
	for(int i=0;i<v.size();i++)
	{
		vector<int> temp=v;
		int second_num=v[i];
		temp.erase(temp.begin()+i);
		fans.pb(mk(first_num,second_num));
		recurse(temp);
		fans.pop_back();
	}
}
