  // cout << left.size() << " " << right.size() << " " << rest.size() << endl;
  multiset<string> se;
  REP(i,W) {
    string s;
    const int n = left.size();
    REP(j,n) s += left[j][i];
    if (!rest.empty()) s += rest[0][i];
    REP(j,n) s += right[n-j-1][i];
    se.insert(s);
    assert (int(s.size()) == H);
  }
  // cout << rest.size() << endl;
  if (se.size() % 2 == 0) {
    while (!se.empty()) {
      auto it = begin(se);
      string s = *it;
      se.erase(it);
      reverse(ALL(s));
      auto it2 = se.find(s);
      if (it2 == end(se)) return false;
      else se.erase(it2);
    }
    return true;
  }
  else {
    const multiset<string> se2 = se;
    for (string s: se2) {
      se = se2;
      string t = s;
      reverse(ALL(t));
      if (s != t) continue;
      auto it = se.find(s);
      se.erase(it);
      while (!se.empty()) {
        auto it = begin(se);
        string s = *it;
        se.erase(it);
        reverse(ALL(s));
        auto it2 = se.find(s);
        if (it2 == end(se)) break;
        else se.erase(it2);
      }
      if (se.empty()) return true;
      se = se2;
    }
    return false;
  }
}

bool dfs(vector<string> left, vector<string> right, vector<string> center, vector<string> rest) {
  if (rest.size() == 0) return check(left, right, center);
  const string l = rest.back();
  if (center.empty()) {
    center.push_back(l);
    rest.pop_back();
    if (dfs(left, right, center, rest)) return true;
    rest.push_back(l);
    center.pop_back();
  }
  if (rest.size() >= 2) {
    left.push_back(l);
    rest.pop_back();

    const string r = rest.back();
    rest.pop_back();
    right.push_back(r);
    if (dfs(left, right, center, rest)) return true;
    const int n = rest.size();
    REP(i,n) {
      swap(rest[i], right.back());
      if (dfs(left, right, center, rest)) return true;
      swap(rest[i], right.back());
    }
    left.pop_back();
    right.pop_back();
    rest.push_back(r);
    rest.push_back(l);
  }
  return false;
}


