using namespace std;

bool check(const vector<pair<int, int>> &pv, const vector<string> &field) {
    const int H = field.size();
    const int W = field[0].size();

    vector<int> v(W, -1);
    int pos = 0;
    FOR(i, 0, pv.size()) {
        int x1 = pv[i].first;
        int x2 = pv[i].second;

        if (x1 >= W) {
            v[W / 2] = x2;
            continue;
        }
        else if (x2 >= W) {
            v[W / 2] = x1;
            continue;
        }

        v[pos] = x1;
        v[v.size() - 1 - pos] = x2;
        pos++;
    }

    vector<int> used(H, false);
    FOR(y1, 0, H) {
        if (used[y1]) { continue; }

        FOR(y2, y1 + 1, H) {
            if (used[y2]) { continue; }

            bool ok = true;
            FOR(x, 0, W) {
                ok &= field[y1][v[x]] == field[y2][v[W - 1 - x]];
            }
            if (ok) {
                used[y1] = true;
                used[y2] = true;
                break;
            }
        }
    }

    int num = 0;
    FOR(y, 0, used.size()) {
        if (not used[y]) {
            num++;
            FOR(x, 0, W) {
                if (field[y][v[x]] != field[y][v[W - 1 - x]]) {
                    return false;
                }
            }
        }
    }

    if (num >= 2 or (H % 2 == 0 and num >= 1)) {
        return false;
    }

    return true;
}

// すべての2つのとり方をためす
bool dfs(int idx, vector<bool> &used, vector<pair<int, int>> &pv, const vector<string> &field) {
    const int W = field[0].size();

    if (idx >= ceil(W, 2)) {
        return check(pv, field);
    }

    int i = -1;
    FOR(j, 0, W) {
        if (used[j]) { continue; }
        i = j;
        break;
    }
    used[i] = true;

    bool ok = false;
    FOR(j, 0, (W + (W % 2 == 1))) {
        if (used[j]) { continue; }

        used[j] = true;
        pv.emplace_back(make_pair(i, j));

        ok |= dfs(idx + 1, used, pv, field);

        used[j] = false;
        pv.pop_back();
    }
    used[i] = false;

    return ok;
}

