{
	for (int i = 0; i < 26; i++)
		if (u.cnt[i] != v.cnt[i])
			return u.cnt[i] < v.cnt[i];
	return true;
}
bool samei(const node & u, const node & v)
{
	for (int i = 0; i < 26; i++)
		if (u.cnt[i] != v.cnt[i])
			return false;
	return true;
}
