ll H, W;
vector<string> S;


void dfsCol(vll colSts, ll no, vpll &rowPairs){

	if (no-1 == W/2){//最後
		//奇数なら最後に中央チェック
		if (W%2==1){
			ll m=0;
			for (; colSts[m]!=-1; m++);
			bool isOK = true;
			EACH(e, rowPairs){
				ll x; ll y;  tie(x, y) = e;
				if (y == -1) continue;
				if (S[x][m] != S[y][m]) { isOK=false; break; }
			}
			if (!isOK) return;
		}
		//全チェック通過
		bye("YES");
	}

	ll i=0;
	for (; colSts[i]!=-1; i++);
	rep(j, i+1, W-1){
		if (colSts[j]!=-1) continue;

		//カラム[i]、[j]は対称か？
		{
			bool isOK = true;
			EACH(e, rowPairs){
				ll x; ll y;  tie(x, y) = e;
				if (x == -1) continue;
				if (y == -1){//中央行の時
					if (S[x][i] != S[x][j]) { isOK = false;  break; }
				}
				else{//ペア行の時
					if (S[x][i] != S[y][j]) { isOK = false;  break; }
					if (S[x][j] != S[y][i]) { isOK = false;  break; }
				}
			}
			if (!isOK) continue;
		}

		//対称なら次に進む
		colSts[i] = colSts[j] = no;
		dfsCol(colSts, no+1, rowPairs);
		colSts[i] = colSts[j] = -1;
	}
}

void dfsRow(vll rowSts, ll no){
	ll i=0;
	for (; rowSts[i]!=-1; i++);
	rep(j, i+1, H-1){
		if (rowSts[j]!=-1) continue;

		//組S[i],S[j]が対称化可能か？
		map<pll, ll> buf;
		rep(k, 0, W-1){
			buf[pll(S[i][k], S[j][k])]++;
			buf[pll(S[j][k], S[i][k])]++;
		}
		ll oddCount=0;
		EACH(e, buf){
			if (e.second%2==1) oddCount++;
		}
		if (oddCount>=1) continue;

		rowSts[i] = rowSts[j] = no;

		//可能な時、次に進む
		if (no == H/2){//行が終わったら列へ
			vpll rowPairs(H/2+1, pll(-1,-1));
			rep(x, 0, H-1){
				ll val = rowSts[x];
				if (rowPairs[val].first == -1) rowPairs[val].first = x;
				else                           rowPairs[val].second = x;
			}
			vll colSts(W,-1);
			dfsCol(colSts,1, rowPairs);
		}
		else{//行がまだなら次の行ペアへ
			dfsRow(rowSts, no+1);
		}

		rowSts[i] = rowSts[j] = -1;
	}
}


void solve()
{
	cin >> H >> W;
	S = cinv<string>(H);

	vll rowSts(H,-1);


	if (H%2 == 1){
		rep(i, 0, H-1){
			//行iが中央になれるか判定
			map<char, ll> buf;
			EACH(c, S[i]) buf[c]++;
			ll oddCount=0;
			EACH(e, buf){
				if (e.second%2==1) oddCount++;
			}
			if (oddCount>=2) continue;

			if (H == 1) bye("YES");

			rowSts[i] = 0;
			dfsRow(rowSts,1);
			rowSts[i] = -1;
		}
	}
	else{
		dfsRow(rowSts,1);
	}
	cout << "NO" << '\n';
}


int main(){
	solve();
	return 0;
}

