template <size_t T>
bool nextBitset(bitset<T> &bs, int digit)
{
    if(bs.none())
        return false;
    bitset<T> x, y, z;
    x = bs.to_ulong() & (~(bs.to_ulong()) + 1ULL);
    y = bs.to_ulong() + x.to_ulong() + 0ULL;
    z = bs & ~y;
    if(bs[digit-1] && bs == z)
        return false;
    bs = ((z.to_ulong() / x.to_ulong()) >> 1) + 0ULL;
    bs |= y;
    return true;
}

class RollingHash
{
private:
    static const int X, M;
    long long hash;
public:
    RollingHash(const string& s){
        int n = s.size();
        hash = 0;
        for(int i=0; i<n; ++i){
            hash *= X;
            hash += s[i];
            hash %= M;
        }
    }
    long long getHash() const{
        return hash;
    }
};
const int RollingHash::X = 1685440109; // 素数
const int RollingHash::M = 2000000087; // 合同式の法（素数）

