bool check(const vector<string>& s)
{
    int h = s[0].size();
    int w = s.size();

    map<long long, vector<int> > index;
    for(int i=0; i<h; ++i){
        string t(w, ' ');
        for(int j=0; j<w; ++j)
            t[j] = s[j][i];
        long long hash1 = RollingHash(t).getHash();
        index[hash1].push_back(i);

        reverse(t.begin(), t.end());
        long long hash2 = RollingHash(t).getHash();
        index[hash2].push_back(i);
    }

    bool isSame = false;
    for(auto& p : index){
        auto& v = p.second;
        if(v.size() % 2 != 0)
            return false;

        sort(v.begin(), v.end());
        v.erase(unique(v.begin(), v.end()), v.end());

        if(v.size() % 2 != 0){
            if(isSame)
                return false;
            isSame = true;
        }
    }
    return true;
}

