// タテとヨコを独立に判定

int h, w, a[12][26], ph[12], pw[12], cnt1, cnt2;
string s[12];

bool eq(int a[26], int b[26]) {
	rep(i,26) if (a[i]!=b[i]) return false;
	return true;
}

signed main() {
	cin >> h >> w;
	rep(i,h) cin >> s[i];
	// タテ
	set<int> hs;
	rep(i,h) rep(j,w) a[i][s[i][j]-'a']++;
	rep(i,h) {
		bool us = hs.count(i);
		hs.insert(i);
		vi m;
		m.pb(0);
		rep(j,h) if (i!=j && eq(a[i],a[j])) m.pb(j), hs.insert(j);
		ph[i] = m.size();
		if (!us) cnt1 += ph[i]%2;
	}
	// ヨコ
	set<int> ws;
	memset(a,0,sizeof(a));
	rep(i,h) rep(j,w) a[j][s[i][j]-'a']++;
	rep(i,w) {
		bool us = ws.count(i);
		ws.insert(i);
		vi m;
		m.pb(0);
		rep(j,h) if (i!=j && eq(a[i],a[j])) m.pb(j);
		pw[i] = m.size();
		if (!us) cnt2 += pw[i]%2;
	}
	bool ok = true;
	if ((h%2==0 && cnt1) || (h%2==1 && cnt1!=1)) ok = false;
	if ((w%2==0 && cnt2) || (w%2==1 && cnt2!=1)) ok = false;
