set<int>us;
vector<pair<int,int> >C;
void dfs(int cur,bool pass=false)
{
	if(cur==v[0].size())
	{
		way.push_back(C);
		return;
	}
	if(us.count(cur))
	{
		dfs(cur+1,pass);
		return;
	}
	else
	{
		if(pass=false)
		{
			dfs(cur+1,true);
		}
	}
	us.insert(cur);
	for(int i=cur+1;i<v[0].size();i++)
	{
		if(us.count(i))
		{
			continue;
		}
		C.push_back(make_pair(cur,i));
		us.insert(i);
		dfs(cur+1,pass);
		C.pop_back();
		us.erase(i);
	}
}
