typedef long long int ll;

int h, w;
char s[12][12];
bool e;

void solve(vector<int> v){
  if(v.size()==h/2){
    bool b[12]={};
    for(int j=0; j<v.size(); j++){
      b[v[j]]=1;
    }
    for(int i=0; i<h; i++){
      if(b[i]==0){
        v.push_back(i);
      }
    }
    for(int i=0; i<h/2; i++){
      if(v[i]>v[h-1-i]) return;
    }
    string str[12];
    for(int i=0; i<w; i++){
      for(auto itr=v.begin(); itr!=v.end(); itr++){
        int x=*itr;
        str[i]+=s[x][i];
      }
    }
    int t=0;
    bool used[12]={};
    string rstr[12];
    for(int i=0; i<w; i++){
      rstr[i]=str[i];
      reverse(rstr[i].begin(), rstr[i].end());
    }
    for(int i=0; i<w; i++){
      if(used[i]==1) continue;
      used[i]=1;
      bool e1=0;
      for(int j=0; j<w; j++){
        if(used[j]==1) continue;
        if(str[i]==rstr[j]){
          used[j]=1;
          e1=1;
          break;
        }
      }
      if(e1==0){
        if(str[i]==rstr[i]){
          t++;
        }else{
          return;
        }
      }
    }
    if(t!=w%2) return;
    e=1;
    return;
  }
  bool used[12]={};
  for(int j=0; j<v.size(); j++){
    used[v[j]]=1;
  }
  for(int i=0; i<h; i++){
    if(used[i]==0){
      v.push_back(i);
      solve(v);
      v.pop_back();
    }
  }
  return;
}

int main()
{
	e=0;
  scanf("%d %d", &h, &w);
  for(int i=0; i<h; i++){
    scanf("%s", s[i]);
  }
  vector<int> v;
  solve(v);
  if(e==1){
    printf("YES\n");
  }else{
	printf("NO\n");
  }
	return 0;
}

