bool special = false;

vector<vector<char>> t;

bool check(const vector<vector<char>> &g) { // checks row ok?
  vector<vector<char>> rows;
  map<vector<char>, int> cnt;
  for (int i = 0; i < g.size(); ++i) {
    rows.emplace_back(g[i]);
    sort(rows.back().begin(), rows.back().end());
    ++cnt[rows.back()];
  }
  int bad = 0;
  for (auto it = cnt.begin(); it != cnt.end(); ++it) {
    bad += it->second & 1;
    if (special) {
      t.emplace_back(it->first);
    }
  }
  return bad <= (g.size() & 1);
}

signed main() {
  ios::sync_with_stdio(false);
  int N, M;
  cin >> N >> M;
  vector<string> G(N);
  for (int i = 0; i < N; ++i) {
    cin >> G[i];
  }
  vector<vector<char>> g(N, vector<char>(M));
  for (int i = 0; i < N; ++i) {
    for (int j = 0; j < M; ++j) {
      g[i][j] = G[i][j];
    }
  }
  if (N & M & 1) {
    special = true;
  }
  bool ok = true;
  ok &= check(g);
  vector<vector<char>> tg(M, vector<char>(N));
  for (int i = 0; i < N; ++i) {
    for (int j = 0; j < M; ++j) {
      tg[j][i] = g[i][j];
    }
  }
  ok &= check(tg);
  if (ok && special) {
    multiset<int> a, b, c, d;
    for (int i = 0; i < t[0].size(); ++i) {
      if (i < t[0].size() / 2) {
        a.emplace(t[0][i]);
      } else if (i > t[0].size() / 2) {
        b.emplace(t[0][i]);
      }
    }
    for (int i = 0; i < t[1].size(); ++i) {
      if (i < t[1].size() / 2) {
        c.emplace(t[1][i]);
      } else if (i > t[1].size() / 2) {
        d.emplace(t[1][i]);
      }
    }
    if (a != b || c != d) ok = false;
  }
  cout << (ok ? "YES" : "NO") << endl;
  return 0;
}

