    int l0 = (m + 1) / 2;

    vec< int > P(m);
    for(int i = 0;i < m;i++) {
        P[i] = i;
    }

    const double MAX_TIME = 1.5 * CLOCKS_PER_SEC;

    mt19937 rnd(42);

    while(clock() < MAX_TIME) {

        shuffle(ALL(P), rnd);

        vec< int > perm(l0);
        for(int i = 0;i < l0;i++) {
            perm[i] = i;
        }

        do{
            vec< pair< string, string > > a1(n), a2(n);
            for(int i = 0;i < n;i++) {
                string t1(l0, '?'), t2(l0, '?');
                for(int j = 0;j < l0;j++) {
                    t1[j] = s[i][P[perm[j]]];
                }
                if(m & 1) {
                    t2[0] = s[i][P[perm[l0 - 1]]];
                    for(int j = 0;j < l0 - 1;j++) {
                        t2[j + 1] = s[i][P[l0 + j]];
                    }
                }else {
                    for(int j = 0;j < l0;j++) {
                        t2[j] = s[i][P[l0 + j]];
                    }
                }
                a1[i] = make_pair(t1, t2);
                reverse(ALL(t1));
                reverse(ALL(t2));
                a2[i] = make_pair(t2, t1);
            }
            sort(ALL(a1));
            sort(ALL(a2));
            int ok = 1;
            for(int i = 0;i < n;i++) {
                if(a1[i] != a2[i]) {
                    ok = 0;
                    break;
                }
            }
            if(ok) {
                puts("YES");
                return 0;
            }
        }while(next_permutation(ALL(perm)));
    }

    puts("NO");

    return 0;
}

