using namespace std;

bool isPalindrome(string &S) {
    int chars[256];
    memset(chars, 0, sizeof(chars));
    for (int i = 0; i < S.length(); i++) {
        chars[S[i]] += 1;
    }

    int odd = 0, even = 0;
    for (int i = 0; i < 256; i++) {
        if (chars[i]%2 == 0) even += 1;
        else odd += 1;
    }

    if (S.length()%2 == 0) {
        if (odd == 0) return true;
        else return false;
    } else {
        if (odd == 1) return true;
        else return false;
    }
}

