bool tryGrid(vector<int> &mix) {
    vector<string> T(h, "");
    vector<bool> used(h, false);
    int remaining = h;
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            T[i] += G[i][mix[j]];
        }
        //cout << T[i] << endl;
    }

    int remains = -1;
    for (int i = 0; i < h; i++) {
        if (used[i]) continue;
        for (int j = i+1; j < h; j++) {
            if (used[j]) continue;
            bool match = true;
            for (int k = 0; k < w; k++) {
                if (T[i][k] != T[j][w-1-k]) {
                    match = false;
                    break;
                }
            }
            if (match) {
                used[i] = true;
                used[j] = true;
                remaining -= 2;
                break;
            }
        }
        if (!used[i]) {
            remains = i;
        }
    }

    if (h%2 == 0) {
        if (remaining > 0) {
            return false;
        } else {
            return true;
        }
    } else {
        if (remaining == 1 && isPalindrome(T[remains])) {
            return true;
        } else {
            return false;
        }
    }
}

