int H, W;
std::string S[20];

std::vector<std::vector<int>> all_pairs(std::vector<int> org) {
    std::vector<std::vector<int>> ret;
    if (org.size() == 0) {
        return ret;
    }

    int is_even = org.size() % 2 == 0 ? 1 : 0;

    do {
        bool use = true;
        for (int i = 0; i < org.size() - 1; i += 2) {
            if (org[i] > org[i+1]) {
                use = false;
                break;
            }
        }
        if (use) {
            for (int i = 0; i < org.size() - 3; i += 2) {
                if (org[i] > org[i+2]) {
                    use = false;
                    break;
                }
            }
        }
        if (use) {
            ret.push_back(org);
        }
    } while (std::next_permutation(org.begin() + is_even, org.end()));

    return ret;
}

bool check(std::vector<int> pair) {
    bool used[20] = {};
    std::string T[20];

    for (int i = 0; i < H; i++) {
        T[i].resize(W);
        for (int j = 0; j < W/2; j++) {
            T[i][j] = S[i][pair[j*2]];
            T[i][W-1-j] = S[i][pair[j*2+1]];
        }
        if (W % 2 == 1) {
            T[i][W/2] = S[i][pair.back()];
        }
    }

    for (int i = 0; i < H; i++) {
        bool center_used = false;
        if (!used[i]) {
            std::string tmp = T[i];
            std::reverse(tmp.begin(), tmp.end());
            bool found = false;
            for (int j = i + 1; j < H; j++) {
                if (tmp == T[j]) {
                    found = true;
                    used[j] = true;
                    break;
                }
            }
            if (!found && H % 2 == 1 && !center_used && tmp == T[i]) {
                found = true;
                center_used = true;
            }
            if (!found) {
                return false;
            }
        }
    }
    return true;
}

int main(int argc, char **argv) {
    std::cin >> H >> W;

    for (int i = 0; i < H; i++) {
        std::cin >> S[i];
    }

    std::vector<int> org;
    for (int i = 0; i < W; i++) {
        org.push_back(i);
    }
    std::vector<std::vector<int>> pairs = all_pairs(org);
    //std::cout << "check:" << pairs.size() << std::endl;

    for (auto p : pairs) {
        //for (int i : p) {
        //    std::cout << i << " ";
        //}
        //std::cout << std::endl;
        if (check(p)) {
            std::cout << "YES" << std::endl;
            return 0;
        }
    }

    std::cout << "NO" << std::endl;
    return 0;

}

