void judge(vi x) {
	string t[12] = {};
	rep(i,h) rep(j,w) t[j].push_back(s[x[i]][j]);
	bool ok[12] = {};
	rep(i,w) {
		string r = t[i];
		reverse(all(r));
		reps(j,i+1,w) if (r==t[j]) {
			ok[i] = ok[j] = 1;
			break;
		}
	}
	int p = accumulate(ok,ok+w,0);
	if (p==w) {
		cout << "YES";
		exit(0);
	}
	if (p+1==w) {
		int ls = -1;
		rep(i,w) if (!ok[i]) ls = i;
		string r = t[ls];
		reverse(all(r));
		if (r==t[ls]) {
			cout << "YES";
			exit(0);
		}
	}
}

void enu(int b, vi x) {
	int p = __builtin_popcount(b);
	if (h<=p+1) {
		if (p==h) judge(x);
		if (p+1==h) {
			int ls = -1;
			rep(i,h) if (!(b>>i&1)) ls = i;
			x.push_back(ls), judge(x);
			rep(i,h-1) swap(x[h-i-1],x[h-i-2]), judge(x);
		}
	}
	rep(i,h) if (!(b>>i&1)) reps(j,i+1,h) if (!(b>>j&1)) {
		x.push_back(i), x.push_back(j);
		enu(b|(1<<i)|(1<<j), x);
		x.pop_back(), x.pop_back();
	}
}

