        hoge += cnt[i] % 2;
    }
    if (hoge != (H * W) % 2) {
        cout << "NO" << endl;
        return 0;
    }

    vector<P> v;
    cout << (solve(0, v, s) ? "YES" : "NO") << endl;
    return 0;
}

