const int maxn = 20;
int n, m;
bool swaped[maxn], used[maxn], ans;
string s[20];

bool check()
{
    memset(used, false, sizeof(used));
    for(int i = 0; i < m; i ++) {
        if(used[i])
            continue;
        for(int j = 0; j < m; j ++) {
            bool cur = true;
            if(i == j || used[j])
                continue;
            for(int k = 0; k < n; k ++) {
                if(s[k][i] != s[n - 1 - k][j]) {
                    cur = false;
                    break;
                }
            }
            if(cur) {
                used[i] = used[j] = true;
                break;
            }
        }
    }

    int cnt = 0, noused = -1;
    for(int i = 0; i < m; i ++)
        if(!used[i])
            cnt ++, noused = i;
    if((cnt >= 2 ) || (cnt && (m % 2 == 0)))
        return false;
    for(int i = 0; i < n; i ++)
        if(s[i][noused] != s[n - 1 - i][noused])
            return false;
    return true;
}

void dfs(int u, int flag)
{
    if(u == (n + 1)/ 2) {
        if(check())
            ans = true;
        return;
    }

    for(int i = u; i < n; i ++) {
        if(!swaped[i]) {
            swaped[i] = true;
            for(int j = i + 1; j < n; j ++) {
                if(swaped[j])
                    continue;
                swaped[j] = true;

                dfs(u + 1, flag);
                swap(s[i], s[j]);
                dfs(u + 1, flag);
                swap(s[i], s[j]);

                swaped[j] = false;
            }
            if(flag) {
                dfs(u + 1, false);
            }
            swaped[i] = false;
            break;
        }
    }
}

