				ph[j] = i;
				break;
			}
		}
	}
	REP(i, w){
		if(pw[i] != -1) continue;
		for(int j = i + 1; j < w; ++j){
			if(eq(t[i], t[j])){
				pw[i] = j;
				pw[j] = i;
				break;
			}
		}
	}
	int cnt1 = 0, cnt2 = 0;
	REP(i, h) if(ph[i] == -1) cnt1++;
	REP(i, w) if(pw[i] == -1) cnt2++;
	if(cnt1 <= h % 2 || cnt2 <= w % 2) cout << "YES\n";
