void solve() {
    int i, j;
    string A, B;
    bool used = false;

    i = 1; j = n;
    for (auto e : data) {
        if (e.size() == 1) {
            p[(n + 1) / 2] = e[0];
        } else {
            p[i] = e[0];
            p[j] = e[1];
            i++; j--;
        }
    }

    act.clear();
    for (j = 1; j <= m; j++) {
        A.clear();
        for (i = 1; i <= n; i++) A.pb(s[p[i]][j]);

        B = A;
        reverse(B.begin(), B.end());

        act.pb(mp(A, B));
    }

    for (i = 0; i < act.size(); i++) {
        if (act[i].first.size() == 0) continue;

        for (j = i + 1; j < act.size(); j++) {
            if (act[j].first.size() == 0) continue;
            if (act[i].first == act[j].second) {
                act[j].first = "";
                break;
            }
        }

        if (j == act.size()) {
            if (act[i].first == act[i].second) {
                if (used) return;
                used = true;
            } else {
                return;
            }
        }
    }

