using namespace std;
using vecint = vector<int>;
using ll = int64_t;
int h,w;

bool isok_impl(const vector<string>& t) {
  REP(i,h)REP(j,w) {
    if (t[i][j] != t[h-i-1][w-j-1]) return false;
  }
  return true;
}

bool isok(const vector<string>& t) {
  int n = max(h,w) - min(h,w);
  if (n == 0) return isok_impl(t);
  return isok_impl(t);
}

bool solve(const vector<string>& t, int k = 0) {
  if (2*k >= min(h,w)) return isok(t);
  FOR(i,k,h-k)FOR(j,k,w-k) {
    vector<string> s = t;
    swap(s[i], s[h-k-1]);
    REP(p,h) swap(s[p][j], s[p][w-k-1]);
    if (s[k][k] != s[h-k-1][w-k-1]) continue;
    if (solve(s, k+1)) return true;
  }
  return false;
}

int main()
{
  cin>>h>>w;
  vector<string> t(h);
  REP(i,h) cin>>t[i];
  bool res = solve(t);
  if (res) {
    cout << "YES" << endl;
  } else {
    cout << "NO" << endl;
  }
  return 0;
}

