using namespace std;
const int MAX_H=12,MAX_W=12;
int H,W;
string S[MAX_H],temp[MAX_H];
bool ans,rflg[MAX_H],cflg[MAX_W],cenf;
bool schk(int n,int m){
	REP(i,H){
		if (temp[i][n]!=temp[H-i-1][m]){
			return false;
		}
	}
	return true;
}
bool pal(int n){
	REP(i,H){
		if (temp[i][n]!=temp[H-i-1][n]){
			return false;
		}
	}
	return true;
}
void chk(){
	memset(cflg,false,sizeof(cflg));
	int cnt=0;
	bool cen=false;
	REP(w,W){
		if (!cflg[w]){
			cflg[w]=true;
			bool f=false;
			FOR(w2,w+1,W){
				if (!cflg[w2]){
					if (schk(w,w2)){
						cflg[w2]=true;
						cnt+=2;
						f=true;
						break;
					}
				}
			}
			if (!f){
				if (pal(w) && !cen){
					cen=true;
					cnt++;
				}
			}
		}
	}
	if (cnt==W){
		ans=true;
	}
}
void com(int n){
	if (n==H/2 && (H%2==0 || cenf)){
		chk();
	}else{
		int m=0;
		REP(i,H){
			if (!rflg[i]){
				m=i;
				break;
			}
		}
		rflg[m]=true;
		temp[n]=S[m];
		REP(i,H){
			if (!rflg[i]){
				rflg[i]=true;
				temp[H-n-1]=S[i];
				com(n+1);
				rflg[i]=false;
			}
		}
		if (!cenf && H%2){
			cenf=true;
			temp[H/2]=S[m];
			com(n);
			cenf=false;
		}
		rflg[m]=false;
	}
}
int main(){
	cin>>H>>W;
	REP(i,H){
		cin>>S[i];
	}
	REP(i,H){
		temp[i].resize(W);
	}
	com(0);
	cout<<(ans ? "YES" : "NO")<<endl;
	return 0;
}

