			bool flag = 1;
			for(int k=1; k<=n; k++) {
				if(s[match[k]][i] != s[k][j]) {
					flag = 0;
					break;
				}
			}
			if(flag) vis[i] = vis[j] = 1;
		}
	int cnt = 0, flag = 0;
	for(int i=1; i<=m; i++)
		if(!vis[i]) {
			cnt++;
			flag = i;
		}
	if((m % 2 == 0 && cnt) || cnt >= 2) return 0;
	if(!cnt) return 1;
	for(int i=1; i<=n; i++)
		if(s[match[i]][flag] != s[i][flag]) return 0;
	return 1;
}

void dfs(int step, bool flag) {
	if(ans) return;
	if(step == ((n+1) >> 1)) {
		if(check()) ans = 1;
		return;
	}
	for(int i=step; i<=n; i++) {
		for(int j=i+1; j<=n; j++)
			if(match[i] == -1 && match[j] == -1) {
				match[i] = j, match[j] = i;
				dfs(step+1, flag);
				match[i] = match[j] = -1;
			}
		if(flag && match[i] == -1) {
			match[i] = i;
			dfs(step+1, 0);
			match[i] = -1;
		}
	}
}

