        int used[13] = {};
        int h = vs.size();
        int w = vs[0].size();
        int nf = 0;
        int nfidx = 0;

        rep(i, w) {
                if (used[i]) continue;
                bool found = false;
                loop(j, i+1, w) {
                        if (used[j]) continue;
                        bool ok = true;
                        rep(k, h) {
                                if (vs[k][i] != vs[h-1-k][j]) {
                                        ok = false;
                                        break;
                                }
                        }
                        if (ok) {
                                found = true;
                                used[i] = 1;
                                used[j] = 1;
                                break;
                        }
                }
