#include <bits/stdc++.h>
using namespace std;
const int N = 20;

string str[N]; int h, w, a[N][N];

struct tData {
	int sum[30];  // 1 ~ 26

	tData() { memset( sum, 0, sizeof( sum ) ); }

	bool operator == ( const tData &rhs ) const {
		for( int i = 1; i <= 26; i ++ )	 
			if( sum[i] != rhs.sum[i] ) return false;
		return true;
	}
} row[N], column[N];

bool chosen[N];

int main()
{
	scanf( "%d%d", &h, &w );
	for( int i = 1; i <= h; i ++ )	
		cin>> str[i];

	for( int i = 1; i <= h; i ++ )
		for( int j = 1; j <= w; j ++ )
			a[i][j] = str[i][j-1] - 'a' + 1; 

	for( int i = 1; i <= h; i ++ )
		for( int j = 1; j <= w; j ++ )
			row[i].sum[a[i][j]] ++, column[j].sum[a[i][j]] ++;

	int sum_row = 0, sum_column = 0;

	memset( chosen, false, sizeof( chosen ) ); 
	for( int i = 1; i <= h; i ++ ) 
		for( int j = 2; j <= h; j ++ )
			if( !chosen[i] && !chosen[j] )
				if( row[i] == row[j] )
					chosen[i] = chosen[j] = true, sum_row ++;

	memset( chosen, false, sizeof( chosen ) );
	for( int i = 1; i <= w; i ++ )
		for( int j = i+1; j <= w; j ++ )
			if( !chosen[i] && !chosen[j] )
				if( column[i] == column[j] )
					chosen[i] = chosen[j] = true, sum_column ++;

	if( sum_row < h / 2 || sum_column < w / 2 )
		printf( "NO\n" ); 
	else printf( "YES\n" );

	return 0;
}

