#include <stdio.h>
#include <iostream>
#include <string>
#include <string.h>
using namespace std;
int n,m;
string s[20];
int swaped[20];
int used[20];
int ans = 0;
bool check()
{
	memset(used,0,sizeof used);
	for(int i=0;i<m;i++){
		for(int j=0;j<m;j++){
			if(used[i]||used[j]||i==j) continue;
			int cur=1;
			for(int k=0;k<n;k++){
				if(s[swaped[k]][i]!=s[k][j]){
					cur=0;
					break;
				}
			}
			if(cur){
				used[i]=used[j]=1;
			}
		}
	}
	int cnt=0,to=0;
	for(int i=0;i<m;i++){
		if(!used[i]){
			cnt++;to=i;
		}
	}
	if(cnt>=2 || (m%2==0&&cnt)){
		return false;
	}
	if(!cnt) return true;
	for(int i=0;i<n;i++){
		if(s[swaped[i]][to]!=s[i][to]){
			return false;
		}
	}
	return true;
}
void dfs(int now,bool ji)
{
	if(now==(n+1)/2){
		if(check()){
			ans=1;
		}
		return;
	}
	for(int i=now;i<n;i++){
		for(int j=i+1;j<n;j++){
			if(swaped[i]==-1&&swaped[j]==-1){
				swaped[i]=j;
				swaped[j]=i;
				dfs(now+1,ji);
				swaped[i]=-1;
				swaped[j]=-1;
			}
		}
		if(ji&&swaped[i]==-1){
			swaped[i]=i;
			dfs(now+1,false);
			swaped[i]=-1;
		}
	}
}
int main()
{
	scanf("%d%d",&n,&m);
	for(int i=0;i<n;i++){
		cin>>s[i];
		swaped[i]=-1;
	}
	if(n&1){
		dfs(0,true);
	}else{
		dfs(0,false);
	}
	if(ans) printf("YES\n");
	else printf("NO\n");
}

#include <iostream>
#include <string>
#include <algorithm>
#include <vector>
#include <cmath>
#include <queue>
#include <map>
#include <unordered_map>
#include <set>
#include <functional>
using namespace std;

typedef long long ll;


int H, W; 
vector<string> s;
vector<pair<int, int>> p;
int used[14];


bool func(int pos, int c) {
	if (c >= H/2) {
		bool u[14] = {};
		int cen = 0;
		if (H & 1) {
			for (auto i : p) {
				u[i.first] = u[i.second] = true;
			}
			for (int i = 0; i < W; i++) {
				if (!u[i]) cen = i;
				u[i] = false;
			}
		}
		for (int i = 0; i < W; i++) {
			if (u[i]) continue;
			for (int j = i + 1; j < W; j++) {
				if (u[j]) continue;
				bool flag = true;
				for (auto t : p) {
					int a = t.first, b = t.second;
					flag &= s[a][i] == s[b][j] && s[a][j] == s[b][i];
				}
				if (H & 1) flag &= s[cen][i] == s[cen][j];
				if (flag) {
					u[i] = u[j] = true;
					break;
				}
			}
		}

		int cnt = 0;
		for (int i = 0; i < W; i++) cnt += !u[i];
		if (cnt == 0) {
			return true;
		}
		if (cnt == 1 && W & 1) {
			for (int i = 0; i < W; i++) {
				if (u[i]) continue;
				bool flag = true;
				for (auto t : p) {
					flag &= s[t.first][i] == s[t.second][i];
				}
				if (flag) {
					return true;
				}
			}
		}

		return false;
	}

	if (used[pos] != -1) return func(pos + 1, c);

	used[pos] = pos;

	bool ret = false;
	for (int i = pos + 1; i < H; i++) {
		if (used[i] != -1) continue;
		used[i] = pos;
		p.push_back({ pos, i });

		ret |= func(pos + 1, c + 1);

		p.pop_back();
		used[i] = -1;
		if (ret) break;
	}

	used[pos] = -1;
	return ret;
}

int main() {
	cin >> H >> W;
	s = vector<string>(H);
	for (int i = 0; i < H; i++) cin >> s[i];
	for (int i = 0; i < H; i++) used[i] = -1;
	cout << (func(0, 0) ? "YES" : "NO") << endl;
	return 0;
}

