void dfs(int n, vector<pint> vec, set<int> rem) {
    if (rem.empty()) {
        tmps.push_back(vec);
        return;
    }
    int f = *(rem.begin());
    rem.erase(f);

    if (rem.empty()) {
        vec.push_back(pint(f, f));
        dfs(n, vec, rem);
    }
    else {
        set<int> nrem = rem;
        EACH(it, nrem) {
            int s = *it;
            vec.push_back(pint(f, s));
            rem.erase(s);
            dfs(n, vec, rem);
            vec.pop_back();
            rem.insert(s);
        }
