void dfs(int n, vector<int>& v, vector<vector<int> >& vv)
{
    int siz = (int)v.size();
    if (n == siz) {
        vv.push_back(v); return;
    }
    int flag[12] = { 0 };
    int i;
    for (i = 0; i < siz; i++) {
        flag[v[i]] = 1;
    }
    for (i = 0; i < n; i++) {
        if (flag[i] == 0) break;
    }
    int now = i;
    for (i = now + 1; i < n; i++) {
        if (flag[i]) continue;
        v.push_back(now);
        v.push_back(i);
        dfs(n, v, vv);
        v.pop_back();
        v.pop_back();
    }
    return;
}

void prepare(int n, vector<vector<int> >& vv)
{
    vector<int> v;
    if (n % 2 == 0) {
        dfs(n, v, vv);
    }
    else {
        int i;
        for (i = 0; i < n; i++) {
            v.push_back(i);
            v.push_back(i);
            dfs(n, v, vv);
            v.pop_back();
            v.pop_back();
        }
    }
    return;
}

char str[12][15];
int flag[12][12];

void solve()
{
    int h, w;
    scanf("%d%d", &h, &w);
    int i, j;
    for (i = 0; i < h; i++) {
        scanf("%s", str[i]);
    }

    vector<vector<int> > v0;
    prepare(h, v0);

    int id[12];
    for (i = 0; i < (int)v0.size(); i++) {
        vector<int>& v = v0[i];
        int siz = (int)v.size();

        {
            int p, q;
            for (p = 0; p < w; p++) {
                for (q = p; q < w; q++) {
                    int bad = 0;
                    for (j = 0; j < siz / 2; j++) {
                        if (str[v[2 * j]][p] != str[v[2 * j + 1]][q]) {
                            bad = 1; break;
                        }
                        if (str[v[2 * j]][q] != str[v[2 * j + 1]][p]) {
                            bad = 1; break;
                        }
                    }
                    flag[p][q] = (bad == 0 ? 1 : 0);
                }            
            }
        }

        vector<int> ans(1 << w);
        ans[0] = 1;
        for (j = 1; j < (1 << w); j++) {
            int num = 0;
            int p,q;
            for (p = 0; p < w; p++) {
                if (j & (1 << p)) {
                    id[num] = p;
                    num++;
                }
            }
            if (w % 2 == 0) {
                if (num % 2) continue;
                if (num > (w+2)/4 * 2) continue;
            }
            else {
                if (num > (w + 1) / 2) continue;
            }

            if (num == 1) {
                if (flag[id[0]][id[0]]) {
                    ans[j] = 1;
                }
            }
            else {
                for (p = 0; p < num; p++) {
                    for (q = p + 1; q < num; q++) {
                        if (flag[id[p]][id[q]] && ans[j & ~(1<<id[p]) & ~(1<<id[q])]) {
                            ans[j] = 1;
                            break;
                        }
                    }
                    if (ans[j]) {
                        break;
                    }
                }
            }
            if (ans[j] && ans[(1 << w) - 1 - j]) {
                printf("YES\n"); return;
            }
        }
    }
    printf("NO\n");

    return;
}

