void check(vector<P> A, int S){

  string t[12];

  for(int i=0;i<(int)A.size();i++){

    t[i] = s[A[i].first];

    t[h-i-1] = s[A[i].second];

  }

  if( h % 2 ){

    for(int i=0;i<h;i++){

      if( S >> i & 1 ) continue;

      t[h/2] = s[i];

    }

  }

  int S2 = 0;

  for(int i=0;i<w;i++){

    if( S2 >> i & 1 ) continue;

    for(int j=i+1;j<w;j++){

      if( S2 >> j & 1 ) continue;

      int flag = 1;

      for(int k=0;k<h;k++){
	if( t[k][i] != t[h-k-1][j] ) flag = 0;
      }

      if( flag ) S2 |= ( 1 << i ) | ( 1 << j );

    }

  }

  if( w % 2 == 0 && __builtin_popcount(S2) == w ){
    cout << "YES" << endl;
    exit(0);
  }

  if( w % 2 == 1 && __builtin_popcount(S2) == w - 1 ){

    for(int i=0;i<w;i++){

      if( S2 >> i & 1 ) continue;

      int flag = 1;

      for(int j=0;j<h;j++){
	if( t[j][i] != t[h-j-1][i] ) flag = 0;
      }

      if( flag ){
	cout << "YES" << endl;
	exit(0);
      }

    }

  }

}

void dfs(vector<P> A, int S, int X){

  if( h - __builtin_popcount(S) <= 1 ){

    check( A, S );

    return;
  }

  int idx = -1;

  for(int i=0;i<h;i++){

    if( i == X ) continue;

    if( S >> i & 1 ) continue;

    idx = i;

    break;

  }

  if( idx == -1 ) return ;

  for(int i=idx+1;i<h;i++){

    if( i == X ) continue;

    if( S >> i & 1 ) continue;

    vector<P> nA = A;

    nA.push_back(P( idx, i ));

    int nS = S | ( 1 << idx ) | ( 1 << i );

    dfs( nA, nS, X );

  }

}

