char str[maxn][maxn];
int swaped[maxn];
bool used[maxn];
bool ans;
int n,m;
bool check() {    //判断在这种(n行配对)的情况下，是否可以通过列的转换实现对称 
	memset(used,0,sizeof(used));
	for(int i=0; i<m; i++) {       //枚举任意不相等的两列，在这种(n行配对)的情况下，这两列是否相等 
		if(used[i])                //相等则说明这两列可以通过列变换形成对称 
			continue;
		for(int j=0; j<m; j++) {
			bool vis=true;
			if(i==j||used[j])
				continue;
			for(int k=0; k<n; k++) {
				if(str[k][i]==str[swaped[k]][j])
					continue;
				vis=false;
				break;
			}
			if(vis){
				used[i]=used[j]=true;
				break;
			}
		}
	}
	int cnt=0;
	int pos=-1;
	for(int i=0; i<m; i++)   //计算有多少列没配对 
		if(!used[i]) {
			cnt++;
			pos=i;
		}
	if(cnt>=2||(cnt&&(m%2==0))) //没配对数大于等于2或者（列数为奇数且没配对数等于1） 
		return false;           //的情况都说明这种（n行配对）的情况无法通过列转移实现对称 
	if(cnt==1) {                //对于列数m为奇数的情况，需要特判这一列是否可以形成对称 
		for(int i=0; i<n; i++) {
			if(str[i][pos]!=str[swaped[i]][pos])
				return false;
		}
	}
	return true;
}
void dfs(int u,int falg) {   //dfs枚举出所有的（n行配对）的情况 
	if(u==(n+1)>>1) {      //u==(n+1)/2,说明所有的行已经配对成功，这是一种（n行配对）的情况 
		if(check())       //判断列是否通过转换形成对称 
			ans=true;
		return ;
	}
	if(ans==true)
	return;
	for(int i=u; i<n; i++) {
		if(swaped[i]==-1) {
			for(int j=i+1; j<n; j++) {
				if(swaped[j]==-1) {
					swaped[i]=j;
					swaped[j]=i;
					dfs(u+1,falg);
					swaped[i]=-1;
					swaped[j]=-1;
				}
			}
			if(falg) {     //对于行数n为奇数的情况，有一行是关于没有对称行的 
				swaped[i]=i;
				dfs(u+1,false);
				swaped[i]=-1;
			}
		}
	}
}
void init() {
	memset(swaped,-1,sizeof(swaped));
	ans=false;
}
int main() {
	while(~scanf("%d %d",&n,&m)) {
		init();
		for(int i=0; i<n; i++)
			scanf("%s",str[i]);
		if(n&1)
			dfs(0,true);
		else
			dfs(0,false);
		printf("%s\n",ans?"YES":"NO");
	}
	return 0;
}

