#include <bits/stdc++.h>
using namespace std;
int h, w;
char matrix[12][12];
bool able[12][12];
void get(queue<int> &q){
    if (q.size() <= 1){
        cout << "YES" << endl;
        exit(0);
    }
    int el = q.front();
    q.pop();
    for (int i=0; i < q.size(); i++){
        int V = q.front();
        q.pop();
        if (able[V][el]) get(q);
        q.push(V);
    }
    if (q.size() % 2) get(q);
    q.push(el);
    for (int i=0; i < q.size()-1; i++){
        int V = q.front();
        q.pop();
        q.push(V);
    }
    return;
}
void solve(queue<int> &q, vector<pair<int, int> > &v){
    if (q.size() > 1){
        int el = q.front();
        q.pop();
        for (int i=0; i < q.size(); i++){
            int V = q.front();
            q.pop();
            v.push_back(make_pair(el, V));
            solve(q, v);
            v.pop_back();
            q.push(V);
        }
        if (q.size() % 2) solve(q, v);
        q.push(el);
        for (int i=0; i < q.size()-1; i++){
            int V = q.front();
            q.pop();
            q.push(V);
        }
        return;
    }
    for (int i=0; i < w; i++){
        for (int j=0; j < w; j++){
            able[i][j] = true;
            for (int s=0; s < v.size(); s++){
                int a = v[s].first, b = v[s].second;
                if (matrix[a][i] != matrix[b][j]) able[i][j] = false;
                if (matrix[b][i] != matrix[a][j]) able[i][j] = false;
            }
            if (q.size() > 0){
                int e = q.front();
                if (matrix[e][i] != matrix[e][j]) able[i][j] = false;
            }
        }
    }
    queue<int> nq;
    for (int i=0; i < w; i++) nq.push(i);
    get(nq);
}
