{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cin >> h >> w;
    for (int i=0; i < h; i++) for (int j=0; j < w; j++) cin >> matrix[i][j];
    queue<int> v;
    vector<pair<int, int> > q;
    for (int i=0; i < h; i++) v.push(i);
    solve(v, q);
    cout << "NO" << endl;
    return 0;
}

