bool is_sym(string s) {
    map<char, int> cnt;
    for(auto ch: s) {
        ++cnt[ch];
    }
    int odd_num = 0;
    for (auto e: cnt) {
        if (e.second % 2) ++odd_num;
    }
    return odd_num <= 1;
}

char get_odd_char(string s) {
    map<char, int> cnt;
    for(auto ch: s) {
        ++cnt[ch];
    }
    for (auto e: cnt) {
        if (e.second % 2) return e.first;
    }
    return '0';
}

