  for ( int i = 0; i < h; i++ ) {
    for ( int j = 0; j < w; j++ ) cnt[i][s[i][j]-'a']++;
  }

  select(vector<int>(h), 0, 0);  
  cout << "NO" << endl;

  return 0;
}

