typedef long long int ll;

int h, w;
char s[12][12];
bool e;

void solve(deque<int> deq){
  if(deq.size()==h){
    string str[12];
    for(int i=0; i<w; i++){
      for(auto itr=deq.begin(); itr!=deq.end(); itr++){
        int x=*itr;
        str[i]+=s[x][i];
      }
    }
    int t=0;
    bool used[12]={};
    string rstr[12];
    for(int i=0; i<w; i++){
      rstr[i]=str[i];
      reverse(rstr[i].begin(), rstr[i].end());
    }
    for(int i=0; i<w; i++){
      if(used[i]==1) continue;
      used[i]=1;
      if(str[i]==rstr[i]){
        t++;
        continue;
      }
      bool e1=0;
      for(int j=0; j<w; j++){
        if(used[j]==1) continue;
        if(str[i]==rstr[j]){
          used[j]=1;
          e1=1;
          break;
        }
      }
      if(e1==0){
        return;
      }
    }
    if(t%2!=w%2) return;
    e=1;
    return;
  }
  if(h%2==1 && deq.empty()){
    for(int i=0; i<h; i++){
      deque<int> deq1;
      deq1.push_back(i);
      solve(deq1);
    }
    return;
  }
  for(int i=h-1; i>=0; i--){
    bool e1=0;
    for(auto itr=deq.begin(); itr!=deq.end(); itr++){
      if(*itr==i){
        e1=1;
        break;
      }
    }
    if(e1==0){
      deq.push_back(i);
      break;
    }
  }
  for(int i=0; i<h; i++){
    bool e1=0;
    for(auto itr=deq.begin(); itr!=deq.end(); itr++){
      if(*itr==i){
        e1=1;
        break;
      }
    }
    if(e1==1) continue;
    deque<int> deq1;
    for(auto itr=deq.begin(); itr!=deq.end(); itr++){
      deq1.push_back(*itr);
    }
    deq1.push_front(i);
    solve(deq1);
  }
  return;
}

int main()
{
	e=0;
  scanf("%d %d", &h, &w);
  for(int i=0; i<h; i++){
    scanf("%s", s[i]);
  }
  deque<int> deq;
  solve(deq);
  if(e==1){
    printf("YES\n");
  }else{
	printf("NO\n");
  }
	return 0;
}

