void print(vector<string> const &chars, int line, vector<pair<int,int>> const &pairs) {
    for (int k = 0; k < static_cast<int>(pairs.size()); k++)
        if (pairs[k].first != -1) cerr << chars[line][pairs[k].first];
    if (pairs[0].first == -1) cerr << chars[line][pairs[0].second];
    for (int k = static_cast<int>(pairs.size())-1; k >= 0; k--)
        if (pairs[k].first != -1) cerr << chars[line][pairs[k].second];
}
