typedef pair<int,int> P;

bool countcheck(const string &a,const string &b){
  vector<int> A(26,0);
  vector<int> B(26,0);
  for(int i=0;i<(int)a.size();i++){
    A[ a[i]-'a' ]++;
    B[ b[i]-'a' ]++;
  }
  return (A==B);
}

vector<int> func(const string &a,const string &b){
  vector<int> res( a.size() ,0 );
  for(int i=0;i<(int)a.size();i++){
    for(int j=0;j<(int)b.size();j++){
      if(a[i]==b[j])
        res[i]|=(1<<j);
    }
  }
  return res;
}


bool judge(const vector<string> &a, const vector<string> &b){

  /*
  cout<<"------------"<<endl;
  for(string str:a)cout<<str<<endl;
  cout<<endl;
  for(string str:b)cout<<str<<endl;
    cout<<"------------"<<endl;
  */

  vector<int> total( a[0].size() , (1<<20)-1 );

  for(int i=0;i<(int)a.size();i++){
    if(!countcheck(a[i],b[i]))return false;
  }

  for(int i=0;i<(int)a.size();i++){
    vector<int> X=func(a[i],b[i]);
    vector<int> Y=func(b[i],a[i]);
    for(int j=0;j<(int)X.size();j++){
      int tmp=(X[j]&Y[j]);
      if(tmp == 0 )return false;
    }
  }

  for(int i=0;i<(int)a.size();i++){
    vector<int> X=func(a[i],b[i]);
    vector<int> Y=func(b[i],a[i]);
    for(int j=0;j<(int)X.size();j++){
      int tmp=(X[j]&Y[j]);
      total[j]=(total[j]&tmp);
      if(total[j]==0)return false;
    }
  }
  return true;
}

bool check( vector<string> &a,const vector<string> &b){
  sort(a.begin(),a.end());
  do{
    if( judge(a,b) )return true;
  }while( next_permutation( a.begin(), a.end() ) );
  return false;
}

bool solve(const vector<string> &t ){
  int H=t.size();

  int h=H/2;
  for(int bit=0;bit<(1<<H);bit++){
    if(__builtin_popcount(bit)!=h)continue;

    vector<string> a,b;
    for(int i=0;i<H;i++){
      if(bit>>i&1)a.push_back(t[i]);
      else b.push_back(t[i]);
    }

    if( check(a,b) )return true;

  }

  return false;
}

