bool dfs(int x) {
	if (bitcnt(x) + 1 >= h) {
		int k = 0;
		rep(i, h) {
			if ((x >> i) % 2 == 0) {
				t[h / 2] = s[i];
			}
		}
		return check();
	}
	int use = 0;
	while ((x >> use) & 1)	use++;
	int k = 0;
	while (t[k] != "")	k++;
	t[k] = s[use];
	srep(i, use + 1, h) {
		if ((x >> i) & 1)	continue;
		t[h - k - 1] = s[i];
		if (dfs(x | (1 << i) | (1 << use)))	return true;
		t[h - k - 1] = "";
	}
	t[k] = "";
	return false;
}

