		rep(i, 0, sz(pairs)-1){
			ll i0; ll i1;  tie(i0, i1) = pairs[i];

			t[i]=s[i0][k];
			t[h-i-1]=s[i1][k];
		}
		if (center!=-1){
			t[h/2]=s[center][k];
		}
	}

