		auto it=st.find(e);
		if (it==st.end())return;
		st.erase(it);
	}
	bye("YES");
}

void dfs(){
	//一番左のused=0を探す
	ll idx1=find(ALL(used), 0)-used.begin();
	if (idx1==h){
		Check();
		return;
	}
	used[idx1]=1;

	rep(i,0,h-1){
		if (used[i]==1)continue;

		used[i]=1;//usedをセット
		pairs.emplace_back(idx1,i);//pairsセット

		dfs();

		used[i]=0;//usedリセット
		pairs.pop_back();//pairsリセット
	}

	used[idx1]=0;
}



