		mset(t1,0);
		rep (j,1,n) t1[a[j][i]-'a']++; cnt=1; vis[i]=1;
		rep (j,1,m) if (j!=i && !vis[j]){
			mset(t2,0);
			rep (k,1,n) t2[a[k][j]-'a']++;
			bool flag=1;
			rep (k,0,25) if (t2[k]!=t1[k]){ flag=0; break; }
			if (flag) vis[j]=1,cnt++;
		}
		All+=cnt&1;
	}
	if (All>1){ puts("NO"); exit(0); }
	tmp+=All==1;
	puts(tmp>=2?"NO":"YES");
	return 0;
}
