struct data {
	ll hs, hp; int id;
	data(ll _hp, ll _hs, int _id) {
		hp = _hp;
		hs = _hs;
		id = _id;
	}
	bool operator<(const data &other) const {
		if (hp == other.hp) {
			if (hs == other.hs)
				return id < other.id;
			return hs < other.hs;
		}
		return hp < other.hp;
	}
};

set<data> s;
vector<pll> d;

pll calc_hash(int col) {
	ll hs = 0, hp = 0;
	for (int j = 1; j <= np; ++j) {
		hp = hp * 27ll + (ll)(a[all_pairs[j].first][col] - 'a' + 1);
		hs = hs * 27ll + (ll)(a[all_pairs[j].second][col] - 'a' + 1);
	}
	if (residue) {
		hp = hp * 27ll + (ll)(a[residue][col] - 'a' + 1);
		hs = hs * 27ll + (ll)(a[residue][col] - 'a' + 1);
	}
	return pll(hp, hs);
}

void check() {
	d.clear();
	s.clear();
	memset(mark, false, sizeof(mark));
	for (int i = 1; i <= m; ++i) {
		auto tmp = calc_hash(i);
		d.push_back(ii(tmp.first, tmp.second));
	}
	for (int i = 1; i <= m; ++i) {
		if (mark[i]) continue;
		auto tmp = d[i - 1];
		auto it = s.lower_bound(data(tmp.second, tmp.first, 0));
		if (it != s.end() && it->id == i) ++it;
		if (it == s.end() || it->hs != tmp.first || it->hp != tmp.second) continue;
		mark[i] = mark[it->id] = true;
		s.erase(it);
		s.erase(data(tmp.first, tmp.second, i));
	}
	if (!SZ(s)) {
		puts("YES");
		exit(0);
	}
	if (SZ(s) == 1 && (m & 1)) {
		int i = (*s.begin()).id;
		auto tmp = d[i - 1];
		if (tmp.first == tmp.second) {
			puts("YES");
			exit(0);
		}
	}
}

void brute(int cnt) {
	int p1 = -1;
	for (int i = all_pairs[cnt - 1].first + 1; i <= n; ++i) {
		if (!used[i]) {
			used[(p1 = i)] = true;
			break;
		}
	}
	if (p1 == -1) {
		check();
		return;
	}
	all_pairs[cnt].first = p1;
	for (int i = p1 + 1; i <= n; ++i) {
		if (used[i]) continue;
		all_pairs[cnt].second = i;
		used[i] = true;
		brute(cnt + 1);
		used[i] = false;
	}
	used[p1] = false;
}

