bool dfs_col(int j,int mask)
{
	if(j==-1){return true;}
	int u=col-j-1;
	if(u==j){
		for(int k=0;k<col;k++){
			if(dfs_col(j-1,mask|(1<<k))) return true;
		}
	}
	else{
		int cnt=0;
		while(mask&(1<<cnt)) cnt++;
		mask|=1<<cnt;
		for(int k=0;k<col;k++) if((mask&(1<<k))==0&&g_col[cnt][k]){
			if(dfs_col(j-1,mask|(1<<k))) return true;
		}
	}
	return false;
}

bool dfs_row(int i,int mask)
{
    //cout<<i<<endl;
