				g_col[k1][k2]=f;
			}
		}
		return dfs_col((col-1)/2,0);
	}
	int u=row-i-1;
	if(u==i){
		for(int k=0;k<row;k++){
			a[i]=k;
			if(dfs_row(i-1,mask|(1<<k))) return true;
		}
	}
	else{
		int cnt=0;
		while(mask&(1<<cnt)) cnt++;
		a[i]=cnt;
		mask|=1<<cnt;
		for(int k=0;k<row;k++){
