bool solve(const bitset<144> maps[13][13], ll h, ll w,
           bitset<144> &state, bool used[13])
{
    bool done = true;

    rep (h1, h) {
        if (used[h1]) continue;
        srep (h2, h1+1, h) {
            if (used[h2]) continue;
            done = false;

            used[h1] = used[h2] = true;
            bitset<144> orig_state = state;
            state &= maps[h1][h2];

            if (solve(maps, h, w, state, used)) return true;

            state = orig_state;
            used[h1] = used[h2] = false;
        }
    }

    if (!done) return false;

    S bool checked[13];
    memset(checked, 0, sizeof(checked));
    ll cnt = 0LL;
    bool same = false;

    rep (i, 144) {
        if (state.test(i)) {
            ll v1 = i / 12LL;
            ll v2 = i % 12LL;
            if (checked[v1] || checked[v2]) continue;
            if (same && v1 == v2) continue;
            checked[v1] = checked[v2] = true;
            if (v1 == v2) {
                cnt++;
                same = true;
            }
            else {
                cnt += 2LL;
            }
        }
    }

    assert(cnt <= w);

    if (cnt == w) return true;
    return false;
}

void _main();
int main()
{
    cout << setprecision(12);
    _main();
    return 0;
}

void _main()
{
    ll h; llin(h);
    ll w; llin(w);
    V<string> grid;
    rep (i, h) {
        string tmp; CIN(tmp);
        grid.pb(tmp);
    }

    S bitset<144> maps[13][13];
    bitset<144> zero;

    rep (h1, h) rep (h2, h) {
        maps[h1][h2] = zero;
        rep (w1, w) rep (w2, w) {
            if (grid[h1][w1] == grid[h2][w2] && grid[h1][w2] == grid[h2][w1]) {
                maps[h1][h2].set(w1*12LL+w2);
            }
        }
    }

    S bool used[13];
    memset(used, 0, sizeof(used));

    if (h & 1LL) {
        rep (single, h) {
            used[single] = true;
            bitset<144> state = maps[single][single];
            if (solve(maps, h, w, state, used)) {
                cout << "YES" << endl;
                return;
            }
            used[single] = false;
        }
    }
    else {
        bitset<144> state;
        state.set();
        if (solve(maps, h, w, state, used)) {
            cout << "YES" << endl;
            return;
        }
    }

    cout << "NO" << endl;
}

