void check()    {
    for(int i = 1 ; i < C ; i += 2) {
        int a = -1;
        int b = -1;

        for(int j = 0 ; j < C ; ++j)    if(!used[j])    {   used[j] = 1;    a = j;  break;  };
        for(int j = 0 ; j < C ; ++j)
            if(!used[j] && (HAS[j] == REV[a]))  {
                used[j] = 1;    b = j;
                break;
            }
        if (b < 0)  return;
    }
    cout << "YES";
    exit(0);
}

void backtrack(int l,int r) {
    if (l > r)  {
        fill(used,used + C,0);

        fill(HAS,HAS + C,0);
        fill(REV,REV + C,0);

        for(int i = 0 ; i < R ; ++i)
        for(int j = 0 ; j < C ; ++j)    {
            int c = S[i][j] - 'a';

            HAS[j] = HAS[j] * 26 + c;
            REV[j] = REV[j] + p[i] * c;
        }
        if (C & 1)  {
            for(int i = 0 ; i < C ; ++i)
                if (HAS[i] == REV[i])   {
                    used[i] = 1;    check();
                    used[i] = 0;
                }
        }
        else    check();

        return;
    }
    if (l == r) {
        for(int i = 0 ; i < R ; ++i)    {
            swap(S[i],S[l]);    backtrack(l + 1,r - 1);
            swap(S[i],S[l]);
        }
        return;
    }
    for(int i = l + 1 ; i <= r ; ++i)   {
        swap(S[i],S[r]);    backtrack(l + 1,r - 1);
        swap(S[i],S[r]);
    }
}

