int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  int h, w; std::cin >> h >> w;
  std::vector< std::string > s(h);
  std::cin >> s;
  std::vector< int > mate(w, -1);
  auto reveq = [&] (auto&& a, auto&& b) {
    rep(j, 0, w) {
      if (a.at(j) != b.at(w - 1 - j))
        { return false; }
    }
    return true;
  };
  auto simulate = [&] {
    std::vector< int > ckd(w, false);
    std::vector< int > p(w, -1);
    auto found = false;
    rep(i, 0, w) {
      if (mate.at(i) == i) {
        p.at(w / 2) = i;
        ckd.at(i) = true;
        found = true;
        break;
      }
    }
    assert(w % 2 == found);
    auto pos = 0;
    rep(i, 0, w) {
      if (ckd.at(i)) continue;
      auto j = mate.at(i);
      assert(!ckd.at(j));
      ckd.at(i) = true;
      ckd.at(j) = true;
      p.at(pos) = i, p.at(w - 1 - pos) = j;
      pos++;
    }
    assert(pos * 2 + found == w);
    assert(std::all_of(all(ckd), [](auto x){ return x; }));

    auto t = s;
    rep(i, 0, h) rep(j, 0, w)
      { at(t, i, j) = at(s, i, p.at(j)); }
    auto allow_orphan = h % 2;
    std::vector< std::pair < std::string, std::string > > ret;
    while (!t.empty()) {
      auto a = t.back();
      auto found = false;
      for (auto it = t.begin(); it != t.end() - 1 && it != t.end(); it++) {
        if (reveq(a, *it)) {
          ret.emplace_back(a, *it);
          t.erase(it);
          t.pop_back();
          found = true;
          break;
        }
      }
      if (!found) {
        if (!allow_orphan || !reveq(a, a))
          { return false; }
        allow_orphan = false;
        ret.emplace_back(a, a);
        t.pop_back();
      }
    }
    // debug(ret);
    return true;
  };
  auto unite = [&](auto i, auto j){
    assert(mate.at(i) == -1 && mate.at(j) == -1);
    mate.at(i) = j;
    mate.at(j) = i;
  };
  auto separate = [&](auto i, auto j){
    assert(mate.at(i) != -1 && mate.at(j) != -1);
    mate.at(i) = -1;
    mate.at(j) = -1;
  };
  auto dfs = [&](auto&& f) -> void {
    auto i = 0;
    for (; i <= w; i++) {
      if (i == w) {
        if (simulate()) {
          std::cout << "YES" << std::endl;
          exit(0);
        }
        return;
      }
      if (mate.at(i) == -1)
        { break; }
    }
    auto found = false;
    rep(j, 0, w) {
      if (i != j && mate.at(j) == -1) {
        unite(i, j);
        f(f);
        separate(i, j);
        found = true;
      }
    }
  };
  if (w % 2 == 1) {
    rep(i, 0, w) {
      unite(i, i);
      dfs(dfs);
      separate(i, i);
    }
  } else {
    dfs(dfs);
  }
  std::cout << "NO" << std::endl;
  return 0;
}

