void f(int x, int y){
    if(count(c, c + n, 1) == n){
        string s[N];        
        for(int i = x - 1; i >= 0; i--){
            for(int j = 0; j < m; j++) s[j] += b[q[i]][j];
        }
        for(int i = (p[0] < 0); i < x; i++){
            for(int j = 0; j < m; j++) s[j] += b[p[i]][j];
        }
        for(int i = 0; i < m; i++){
            for(int j = 0; j <= i; j++){
                a[i][j] = a[j][i] = g(s[i], s[j]);
            }
        }
        if(m & 1){
            for(int i = 0; i < m; i++){
                if(!a[i][i]) continue;
                int t = 1;
                for(int j = 0; j < m; j++){
                    if(i == j) continue;
                    int u = 0;
                    for(int k = 0; k < m; k++){
                        if(k != i && k != j && a[j][k]) u = 1;
                    }
                    t &= u;
                }
                if(t) Y();
            }
        }
        else{
            int t = 1;
            for(int i = 0; i < m; i++)
                t &= !!(count(a[i], a[i] + i, 1) +
                        count(a[i] + i + 1, a[i] + m, 1));
            if(t) Y();
        }
        return;
    }
    for(; y >= 0 && c[y]; y++);
    if(y >= 0) c[y] = 1;
    p[x] = y;
    for(int i = y + 1; i < n; i++){
        if(c[i]) continue;
        c[i] = 1; q[x] = i;
        f(x + 1, y + 1);
        c[i] = 0;
    }
    if(y >= 0) c[y] = 0;
}

