void dfs(vector<pair<int, int>>vec) {
	if (vec.size() == H / 2) {
		bool u[16]; for (int i = 0; i < 16; i++) u[i] = false;
		for (int i = 0; i < vec.size(); i++) {
			T[i] = S[vec[i].first]; u[vec[i].first] = true;
			T[H - 1 - i] = S[vec[i].second]; u[vec[i].second] = true;
		}
		for (int i = 0; i < H; i++) {
			if (u[i] == false) T[H / 2] = S[i];
		}
		if (check() == true) flag = true;
		return;
	}
	bool used[14];
	for (int i = 0; i < 14; i++) used[i] = false;
	for (int i = 0; i < vec.size(); i++) {
		used[vec[i].first] = true;
		used[vec[i].second] = true;
