				if(a1[k] != a2[k])
					break;
			}
			if(k==26)
				sm_c[i][j] = 1;
			else
				sm_c[i][j] = 0;
		}
	}
	for(i=0; i<H; i++){
		for(j=0; j<H; j++){
			int a1[26], a2[26];
