				sm_r[i][j] = 0;
		}
	}
	for(i=0; i<W; i++){
		int a1[26];
		for(k=0; k<26; k++)
			a1[k] = 0;
		for(k=0; k<H; k++){
			a1[S[i][k]-'a'] ++;
		}
		int tmp=0;
		for(k=0; k<26; k++){
			if(a1[k]%2==1)
				tmp ++;
		}
		if(tmp<=1)
			sm1[i] = 1;
