bool ans = 0;
int order[12];
bool used[12];
int h, w;
bool bad;
vector<string> a(12);

void doit(int lvl, int pos) {
	if (ans)
		return;
	if (lvl == (w + 1) / 2) {
		int l = 0;
		vector<int> p(w);
		for (int i = 0; i < 12; i++) {
			if (order[i] == i)
				p[((w + 1) / 2) - 1] = i;
			if (order[i] > i) {
				p[l] = i;
				p[w - 1 - l] = order[i];
				l++;
			}
		}
		multiset<string> s;
		for (int i = 0; i < h; i++) {
			string nw = a[i];
			for (int j = 0; j < w; j++)
				nw[j] = a[i][p[j]];
			if (s.find(nw) != s.end())
				s.erase(s.find(nw));
			else {
				reverse(nw.begin(), nw.end());
				s.insert(nw);
			}
		}
		if (s.size() <= 1)
			ans = 1;
		return;
	}
	if (used[pos]) {
		doit(lvl, pos + 1);
		return;
	}
	if (bad) {
		order[pos] = pos;
		bad = 0;
		doit(lvl + 1, pos + 1);
	}
	for (int i = pos + 1; i < w; i++) {
		if (!used[i]) {
			used[i] = 1, used[pos] = 1;
			order[i] = pos, order[pos] = i;
			doit(lvl + 1, pos + 1);
			used[i] = 0, used[pos] = 0;
		}
	}

}

