					b[i] = 1;
					b[j] = 1;
					cnt += 2;
					break;
				}
			}
		}
	}

	if (h & 1) {
		if (cnt == h - 1) {
			for (int i = 0; i < h; ++i) {
				if (!b[i]) {
					string t = s[i];
					reverse(t.begin(), t.end());
					if (s[i] == t) return 1;
					else return 0;
				}
			}
		}
		else return 0;
	}
	else {
		if (cnt == h) return 1;
		else return 0;
	}
}

void copy(int a, int b) {
	for (int i = 0; i < h; ++i) {
		s[i][b] = input[i][a];
	}
}


bool mask[12];
void rec(int rem) {
	if (rem == 0) {
		if (check()) ans = 1;
	}
	else {
		if (rem & 1) {
			for (int i = 0; i < w; ++i) {
				if (!mask[i]) {
					copy(i, w / 2);
					mask[i] = 1;
					rec(rem - 1);
					mask[i] = 0;
					break;
				}
			}
			if (rem == 1) return;
		}
		int t;
		for (int i = 0; i < w; ++i) {
			if (!mask[i]) {
				copy(i, w / 2 - rem / 2);
				mask[i] = 1;
				t = i;
				break;
			}
		}
		for (int i = 0; i < rem - 1; ++i) {
			int cnt = 0;
			for (int j = 0; j < w; ++j) {
				if (!mask[j]) {
					if (cnt == i) {
						mask[j] = 1;
						copy(j, w - 1 - w / 2 + rem / 2);
						rec(rem - 2);
						mask[j] = 0;
						break;
					}
					else cnt++;
				}
			}
		}
		mask[t] = 0;
	}
}


