bool Solve(void) {
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < m; ++j) c[j] = s[i][j];
    sort(c, c + m);
    string p = "";
    for (int j = 0; j < m; ++j) p = p + c[j];
    if (a.find(p) != a.end()) a.erase(a.find(p));
    else a.insert(p);
  }
  if (n % 2 == 0 && a.size()) return 0;
  if (n % 2 == 1 && a.size() > 1) return 0;
  if (a.size()) {
    string p = *a.begin();
    for (int j = 0; j < m; ++j)
      if (p[j] != p[m - j - 1]) return 0;
  }
  a.clear();
  for (int j = 0; j < m; ++j) {
    for (int i = 0; i < n; ++i) c[i] = s[i][j];
    sort(c, c + n);
    string p = "";
    for (int i = 0; i < n; ++i) p = p + c[i];
    if (a.find(p) != a.end()) a.erase(a.find(p));
    else a.insert(p);
  }
  if (m % 2 == 0 && a.size()) return 0;
  if (m % 2 == 1 && a.size() > 1) return 0;
  if (a.size()) {
    string p = *a.begin();
    for (int i = 0; i < n; ++i)
      if (p[i] != p[n - i - 1]) return 0;
  }
  return 1;
}

