        else if(b[pairs[i]] == "") b[pairs[i]] = a[i];
        else b[h-1-pairs[i]] = a[i];
    }

    bool used[w];
    fill(used, used+w, false);
    bool odd = w%2 == 1;
    repp(j, w){
        if(used[j]) continue;
        reppp(jj, j+1, w){
            if(used[jj]) continue;
            bool is_pair = true;
            rep(h){
                if(b[i][j] != b[h-1-i][jj]){
                    is_pair = false;
                    break;
                }
            }
            if(is_pair){
                used[j] = true;
                used[jj] = true;
                break;
            }
        }
        if(!used[j]){
            if(!odd) return false;
            rep(h){
                if(b[i][j] != b[h-1-i][j]){
                    return false;
                }
            }
            odd = false;
        }
    }
    return true;
}

bool dfs(int n){
    if(n >= h-1) return check();

    repp(k, 2){
        int rest[h-n];
        int j = 0, pair_left = -1;
        rep(h){
            if(pairs[(i+k)%h] == -1){
                if(pair_left == -1) pair_left = (i+k)%h;
                else rest[j++] = (i+k)%h;
            }
        }
        pairs[pair_left] = n;
        rep(j){
            if(pairs[rest[i]] != -1) continue;
            pairs[rest[i]] = n;
            if(dfs(n+2)) return true;
            pairs[rest[i]] = -1;
        }
        pairs[pair_left] = -1;
    }

    return false;
}

