void dfs2(int pos,bool mid){
	if(pos==m){
		puts("YES");
		exit(0);
	}
	if(b[pos]!=-1){
		dfs2(pos+1,mid);
		return;
	}
	for(int i=pos+1;i<m;i++){
		if(b[i]!=-1){
			continue;
		}
		int j;
		for(j=0;j<n;j++){
			if(s[j][pos]!=s[a[j]][i]) break;
		}


		if(j==n){
			b[pos]=i;
			b[i]=pos;
			dfs2(pos+1,mid);
			b[pos]=-1;
			b[i]=-1;
		}
	}

	if(!mid){
		int j;
		for(j=0;j<n;j++){
			if(s[j][pos]!=s[a[j]][pos]) break;
		}

		if(j==n){
			b[pos]=pos;
			dfs2(pos+1,true);
			b[pos]=-1;
		}
	}
}

void dfs(int pos,bool mid){
	if(pos==n){
		dfs2(0,!m%2);
		return;
	}
	if(a[pos]!=-1){
		dfs(pos+1,mid);
		return;
	}
	for(int i=pos+1;i<n;i++){
		if(a[i]!=-1){
			continue;
		}
		if(ss[i]!=ss[pos]){
			continue;
		}

		a[i]=pos;
		a[pos]=i;

		dfs(pos+1,mid);

		a[pos]=-1;
		a[i]=-1;
	}

	if(!mid){
		a[pos]=pos;
		dfs(pos+1,true);
		a[pos]=-1;
	}
}

