int h, w;
string s[12];

int qina(vector<int> v) {
  int sole = w % 2;
  int used[12] = {};
  for(int i = 0; i < w; i++) {
    int ok = 0;
    if(used[i]) continue;
    used[i] = 1;
    for(int j = i + 1; j < w; j++) if(!used[j]) {
      int okk = 1;
      for(int k = 0; k < h; k++)
        if(s[v[k]][i] != s[v[h - 1 - k]][j]) { okk = 0; break; }
      if(okk) {
        used[j] = 1;
        ok = 1;
        break;
      }
    }
    if(ok) continue;
    if(sole--) {
      int okk = 1;
      for(int k = 0; k < h; k++)
        if(s[v[k]][i] != s[v[h - 1 - k]][i]) { okk = 0; break; }
      if(!okk) return 0;
      continue;
    }
    return 0;
  }
  return 1;
}

int ecas(int y, int c, vector<int> v, set<int> u) {
  if(y == 0) {
    if(qina(v)) return 1;
    return 0;
  }
  if(y % 2 == 1) {
    for(int i = 0; i < h; i++) {
      auto tv = v;
      auto tu = u;
      tv[h / 2] = i;
      tu.emplace(i);
      if(ecas(y - 1, 0, tv, tu)) return 1;
    }
    return 0;
  }
  int f = 0;
  for(int i = 0; i < h; i++) if(!u.count(i)) { f = i; break; }

  for(int i = 0; i < h; i++) if(!u.count(i) && f != i) {
    auto tv = v;
    auto tu = u;
    tv[c] = f;
    tv[h - 1 - c] = i;
    tu.emplace(f);
    tu.emplace(i);
    if(ecas(y - 2, c + 1, tv, tu)) return 1;
  }
  return 0;
}

int solve() {
  ios::sync_with_stdio(false), cin.tie(0);
  cin >> h >> w;
  for(int i = 0; i < h; i++) cin >> s[i];
  return ecas(h, 0, vector<int>(h), set<int>());
}

int main() {
  cout << (solve() ? "YES" : "NO") << endl;
}

