int R, C;
ll  p[12];

ll  HAS[12];
ll  REV[12];

void backtrack(int l,int r) {
    if (l >= r) {
        fill(used,used + C,0);

        fill(HAS,HAS + C,0);
        fill(REV,REV + C,0);

        for(int i = 0 ; i < R ; ++i)
        for(int j = 0 ; j < C ; ++j)    {
            int c = S[i][j] - 'a';

            HAS[j] = HAS[j] * 26 + c;
            REV[j] = REV[j] + p[i] * c;
        }
        auto check = [&]()  {
            for(int i = 1 ; i < C ; i += 2) {
                int a = -1;
                int b = -1;

                for(int j = 0 ; j < C ; ++j)    if(!used[j])    {   used[j] = 1;    a = j;  break;  };
                for(int j = 0 ; j < C ; ++j)
                    if(!used[j] && (HAS[j] == REV[a]))  {
                        used[j] = 1;    b = j;
                        break;
                    }
                if (a < 0)  assert(0);
                if (b < 0)  return;
            }
            cout << "YES";
            exit(0);
        };
        if (C & 1)  {
            for(int i = 0 ; i < C ; ++i)
                if (HAS[i] == REV[i])   {
                    used[i] = 1;    check();
                    used[i] = 0;
                }
        }
        else    check();

        return;
    }
    for(int i = l + 1 ; i <= r ; ++i)   {
        swap(S[i],S[r]);    backtrack(l + 1,r - 1);
        swap(S[i],S[r]);
    }
}

int main()  {
    ios_base::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);

    p[0] = 1;   for(int i = 1 ; i < 12 ; ++i)   p[i] = p[i - 1] * 26;

    cin >> R;
    cin >> C;

    for(int i = 0 ; i < R ; ++i)
        cin >> S[i];

    backtrack(0,R - 1);

    cout << "NO";
}

#include <bits/stdc++.h>
using namespace std;

int nth_bit(int64_t num, int n){
    return (num >> n) & 1;
}

int H, W;
string S[12];

vector<vector<pair<int, int>>> cand;
vector<pair<int, int>> now;

void rec(int b){
    if(b == (1<<H)-1){
        cand.push_back(now);
        return;
    }

    vector<int> avail;
    for(int i=0; i<H; i++) if(!nth_bit(b, i)) avail.push_back(i);
    int sz = avail.size();
    int f = avail[0];
    if(sz == 1){
        now.emplace_back(f, f);
        rec(b+(1<<f));
        now.pop_back();
    }else{
        for(int i=1; i<sz; i++){
            int g = avail[i];
            now.emplace_back(f, g);
            rec(b+(1<<f)+(1<<g));
            now.pop_back();
        }
    }
}

int main(){
    cin >> H >> W;
    for(int i=0; i<H; i++) cin >> S[i];
    rec(0);
    for(auto& v : cand){
        vector<int> order;
        int sz = v.size();
        for(int i=0; i<sz; i++) order.push_back(v[i].first);
        for(int i=sz-1; i>=0; i--) order.push_back(v[i].second);

        multiset<string> st;
        for(int j=0; j<W; j++){
            string s;
            for(int i : order) s.push_back(S[i][j]);
            st.insert(s);
        }

        bool one_done = false, success = true;
        while(st.size() && success){
            auto it = st.begin();
            string s = *it, sr = *it;
            st.erase(it);
            reverse(sr.begin(), sr.end());
            auto it2 = st.find(sr);
            if(it2 != st.end()){
                st.erase(it2);
            }else if(!one_done && s == sr){
                one_done = true;
            }else{
                success = false;
            }
        }
        if(success){
            cout << "YES" << endl;
            return 0;
        }
    }
    cout << "NO" << endl;
}

