  cin >> H >> W;
  S = vector<string>(H);
  for (int i = 0; i < H; ++i) cin >> S[i];
  mrr = vector<int>(H, -1);
  dfs(0, H % 2);
  cout << ( (ans) ? "YES" : "NO" ) << endl;
  return 0;
}

