pll calc_hash(int col) {
	ll hs = 0, hp = 0;
	for (int j = 1; j <= np; ++j) {
		hp = hp * 27ll + (ll)(a[all_pairs[j].first][col] - 'a' + 1);
		hs = hs * 27ll + (ll)(a[all_pairs[j].second][col] - 'a' + 1);
	}
	if (residue) {
		hp = hp * 27ll + (ll)(a[residue][col] - 'a' + 1);
		hs = hs * 27ll + (ll)(a[residue][col] - 'a' + 1);
	}
	return pll(hp, hs);
}

void check() {
	d.clear();
	memset(mark, false, sizeof(mark));
	for (int i = 1; i <= m; ++i) {
		auto tmp = calc_hash(i);
		d.push_back(tmp);
	}
	for (int i = 1; i <= m; ++i) {
		if (mark[i]) continue;
		for (int j = 1; j <= m; ++j) {
			if (mark[j] || j == i) continue;
			if (d[i - 1].first == d[j - 1].second && d[i - 1].second == d[j - 1].first) {
				mark[i] = mark[j] = true;
				break;
			}
		}
	}
	int cnt = 0, last = -1;
	for (int i = 1; i <= m; ++i) {
		cnt += (!mark[i]);
		if (!mark[i]) last = i;
	}
	if (!cnt) {
		puts("YES");
		exit(0);
	}
	if (cnt == 1 && (m & 1)) {
		int i = last;
		auto tmp = d[i - 1];
		if (tmp.first == tmp.second) {
			puts("YES");
			exit(0);
		}
	}
}

void brute(int cnt) {
	int p1 = -1;
	for (int i = all_pairs[cnt - 1].first + 1; i <= n; ++i) {
		if (!used[i]) {
			used[(p1 = i)] = true;
			break;
		}
	}
	if (p1 == -1) {
		check();
		return;
	}
	all_pairs[cnt].first = p1;
	for (int i = p1 + 1; i <= n; ++i) {
		if (used[i]) continue;
		all_pairs[cnt].second = i;
		used[i] = true;
		brute(cnt + 1);
		used[i] = false;
	}
	used[p1] = false;
}

