    scanf("%s", s[i]);
  }
  for (int mask = 0; mask < (1 << n); ++mask) {
    int cnt = 0;
    for (int i = 0; i < n; ++i) {
      if (mask >> i & 1) {
        ++cnt;
      }
    }
    if (cnt != (n + 1) / 2) {
      continue;
    }
    vector<int> a, b;
    for (int i = 0; i < n; ++i) {
      if (mask >> i & 1) {
        a.push_back(i);
      } else {
        b.push_back(i);
      }
    }
    for (int i = 0; i < (n + 1) / 2; ++i) {
      p[i] = i;
    }
