        rx[j] = 0;
        used[j] = false;
        long long z = 1;
        for (int i = 0; i < n / 2; ++i) {
          x[j] += (s[a[p[i]]][j] - 'a') * z;
          x[j] += (s[b[i]][j] - 'a') * z * 26;
          rx[j] += (s[b[i]][j] - 'a') * z;
          rx[j] += (s[a[p[i]]][j] - 'a') * z * 26;
          z *= 26 * 26;
        }
        if (n % 2 == 1) {
          x[j] += (s[a[p[n / 2]]][j] - 'a') * z;
          rx[j] += (s[a[p[n / 2]]][j] - 'a') * z;
        }
        for (int i = 0; i < j; ++i) {
          if (!used[i] && rx[i] == x[j]) {
            used[i] = true;
            used[j] = true;
            break;
          }
        }
      }
      int rem = 0;
      for (int i = 0; i < m; ++i) {
        if (!used[i]) {
          ++rem;
        }
      }
      if (rem == m % 2) {
        puts("YES");
        return 0;
      }
    } while (next_permutation(p, p + (n + 1) / 2));
  }
  puts("NO");
}

