bool solve(int h, int w, std::vector<std::vector<char>> s) {
	if (h % 2 == 0 && w % 2 == 0 && h <= 12 && w <= 12) {
		return [&] {
			std::vector<int> v(h);
			std::iota(ALL(v), 0);
			REP(i, h) v[i] /= 2;
			do {
				std::vector<int> V(v);
				std::vector<int> vv(h / 2, 0);
				REP(i, h) {
					if (vv[V[i]] == 0) {
						++vv[V[i]];
					}
					else {
						V[i] = h - V[i] - 1;
					}
				}

				std::vector<int> u(w);
				std::iota(ALL(u), 0);
				REP(j, w) u[j] /= 2;
				do {
					std::vector<int> U(u);
					std::vector<int> uu(w / 2, 0);
					REP(i, w) {
						if (uu[U[i]] == 0) {
							++uu[U[i]];
						}
						else {
							U[i] = w - U[i] - 1;
						}
					}

					bool conti = [&] {
						REP(i, h) REP(j, w) {
							if (s[V[i]][U[j]] != s[V[h - i - 1]][U[w - j - 1]]) return true;
						}
						return false;
					}();
					if (conti) continue;
					else return true;
				} while (std::next_permutation(ALL(u)));
			} while (std::next_permutation(ALL(v)));
			return false;
		}();
	}

	{
		std::map<std::vector<int>, int> map;
		REP(i, h) {
			std::vector<int> cnt(26, 0);
			REP(j, w) ++cnt[s[i][j] - 'a'];
			++map[cnt];
		}

		int odd = h & 1;
		for (auto& x : map) {
			if (x.second % 2) {
				if (odd) {
					--odd;
					continue;
				}
				else return false;
			}
		}
		if (h & 1) if (odd) return false;
	}

	{
		std::map<std::vector<int>, int> map;
		REP(j, w) {
			std::vector<int> cnt(26, 0);
			REP(i, h) ++cnt[s[i][j] - 'a'];
			++map[cnt];
		}

		int odd = w & 1;
		for (auto& x : map) {
			if (x.second % 2) {
				if (odd) {
					--odd;
					continue;
				}
				else return false;
			}
		}
		if (w & 1) if (odd) return false;
	}

	if (h % 2 == 1 && w % 2 == 1) return true;
	if (h % 2 == 1 || w % 2 == 1) return true;
	// ここまではAC

	return true;
}

