            mch.pb(mp(yet,zan[i]));
            if(rec(newmask,mch,ok)) return true;
            mch.pop_back();
        }
        if(ok){
            int newmask = mask+(1<<yet);
            mch.pb(mp(yet,yet));
            if(rec(newmask,mch,false)) return true;
        }
        return false;
    }
    else{
        bool bad[15][15]={};
        for(int i=0;i<mch.size();i++){
            int a = mch[i].fi,b = mch[i].sc;
            for(int c=0;c<m;c++) for(int d=0;d<m;d++) bad[c][d] |= forbid[a][b][c][d];
        }
