#include<iostream>
#include<algorithm>
using namespace std;
typedef long long int ll;
int H, W;
char S[13][12];
bool is_symmetry(){
	if(W % 2 == 0){
		for(int i = 0; i < (1 << W); i++){
			int cnt = 0;
			for(int j = 0; j < W; j++){
				if(i & (1 << j)) cnt++;
			}
			if(cnt != W / 2) continue;
			int a0[26], a1[26];
			fill(a0, a0 + 26, 0);
			fill(a1, a1 + 26, 0);
			for(int j = 0; j < W; j++){
				for(int k = 0; k < H; k++){
					if(i & (1 << j)) a0[S[j][k] - 'a']++;
					else a1[S[j][k] - 'a']++;
				}
			}
			bool flag = true;
			for(int j = 0; j < 26; j++){
				if(a0[j] != a1[j]){
					flag = false;
					break;
				}
			}
			if(flag) return true;
		}
		return false;
	}else{
		for(int i = 0; i < W; i++){
			int a[26];
			fill(a, a + 26, 0);
			for(int j = 0; j < H; j++){
				a[S[i][j] - 'a']++;
			}
			int cnt = 0;
			for(int j = 0; j < 26; j++){
				if(a[j] % 2 == 1) cnt++;
			}
			if(cnt > 1) continue;
			for(int j = 0; j < (1 << W); j++){
				int cnt = 0;
				for(int k = 0; k < W; k++){
					if(j & (1 << k)) cnt++;
				}
				if(cnt != W / 2 + 1) continue;
				int a0[26], a1[26];
				fill(a0, a0 + 26, 0);
				fill(a1, a1 + 26, 0);
				for(int k = 0; k < W; k++){
					if(k == i && !(j & (1 << k))) continue;
					for(int l = 0; l < H; l++){
						if(j & (1 << k)) a0[S[k][l] - 'a']++;
						else a1[S[k][l] - 'a']++;
					}
				}
				bool flag = true;
				for(int k = 0; k < 26; k++){
					if(a0[k] != a1[k]){
						flag = false;
						break;
					}
				}
				if(flag) return true;
			}
		}
		return false;
	}
}
int main(){
	fill(S[0], S[12], '0');
	cin >> H >> W;
	for(int i = 0; i < H; i++) cin >> S[i];
	if(!is_symmetry()){
		cout << "NO" << endl;
		return 0;
	}
	for(int i = 0; i < 12; i++){
		for(int j = 0; j < 12; j++){
			swap(S[i][j], S[j][i]);
		}
	}
	swap(H, W);
	if(!is_symmetry()){
		cout << "NO" << endl;
		return 0;
	}
	cout << "YES" << endl;
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef pair<int,int> pii;
int H,W,match_r[12],match_c[12];
string grid[12];
bool ok;
bool check(){
	memset(match_c,-1,sizeof match_c);
	for(int i=0;i<W;i++){
		if(match_c[i]!=-1) continue;
		for(int j=0;j<W;j++){
			if(match_c[j]!=-1 || i==j) continue;
			bool succ=true;
			for(int k=0;k<H && succ;k++)
				if(grid[match_r[k]][i]!=grid[k][j])
					succ=false;
			if(succ) match_c[i]=j,match_c[j]=i;
		}
	}
	int unmatch=0,mid;
	for(int i=0;i<W;i++)
		if(match_c[i]==-1){
			unmatch++;
			mid=i;
		}
	if(unmatch>=2 || (unmatch && W%2==0)) return false;
	if(!unmatch) return true;
	for(int i=0;i<H;i++)
		if(grid[match_r[i]][mid]!=grid[i][mid])
			return false;
	return true;
}
void dfs(int now,bool is_skip){
	if(now>=(H+1)/2){
		if(check()) ok=true;
	}else{
		for(int i=now;i<H;i++){
			if(match_r[i]!=-1) continue;
			for(int j=i+1;j<H;j++){
				if(match_r[j]!=-1) continue;
				match_r[i]=j,match_r[j]=i;
				dfs(now+1,is_skip);
				match_r[i]=-1,match_r[j]=-1;
			}
			if(!is_skip && H&1){
				match_r[i]=i;
				dfs(now+1,true);
				match_r[i]=-1;
			}
		}
	}
}
int main(){
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	cin>>H>>W;
	for(int i=0;i<H;i++)
		cin>>grid[i];
	memset(match_r,-1,sizeof match_r);
	dfs(0,false);
	cout<<(ok?"YES":"NO")<<'\n';
	return 0;
}

