bool check2(string &s, string &t, int i)
{
	multiset<P> S;
	S.clear();
	for(int j = 0; j < w; j++){
		if(i == j) continue;
		S.insert(make_pair(s[j], t[j]));
	}
	while(S.size()){
		P p = *S.begin();
		P q = make_pair(p.second, p.first);
		if(p == q && S.count(q) < 2) return false;
		if(p != q && S.count(q) == 0) return false;
		S.erase(S.begin());
		S.erase(S.lower_bound(q));
	}
	return true;
}

bool check(string s, string t)
{

	if(w % 2){
		for(int i = 0; i < w; i++){
			if(s[i] != t[i]) continue;
			if(check2(s, t, i)) return true;
		}
		return false;
	}
	return check2(s, t, w+1);
}

bool dfs()
{
	int x = -1;
	for(int i = 0; i < h; i++){
		if(!used[i]){
			x = i;
			break;
		}
	}
	if(x != -1){
		for(int i = x+1; i < h; i++){
			if(used[i]) continue;
			used[x] = used[i] = true;
			vec.push_back(make_pair(x, i));
			if(dfs()) return true;
			vec.pop_back();
			used[x] = used[i] = false;
		}
		return false;
	}

	for(int i = 0; i < vec.size(); i++){
		if(!check(s[vec[i].first], s[vec[i].second])) return false;
	}
	return true;
}

