bool check(const std::vector<std::string>& ss) {
  int mid = -1;
  for (int i = 0; i < ss.size()-1;) {
    if (ss[i] == ss[i+1]) {
      i += 2;
      continue;
    }
    if (ss.size() % 2 == 0)
      return false;
    if (mid != -1)
      return false;
    mid = i;
    ++i;
  }
  if (ss.size() % 2 == 0)
    return true;
  if (mid == -1)
    mid = ss.size() - 1;
  std::string center = ss[mid];
  int m = -1;
  for (int i = 0; i < center.size()-1;) {
    if (center[i] == center[i+1]) {
      i += 2;
      continue;
    }
    if (center.size() % 2 == 0)
      return false;
    if (m != -1)
      return false;
    m = i;
    ++i;
  }
  return true;
}

