bool check()
{
	vector<LL> sym;
	rep(i, m) if(fo[n][i] == fr[n][i]) sym.push_back(fo[n][i]);
	sort(sym.begin(), sym.end());
	sym.push_back(LINF);
	sort(fo[n], fo[n] + m);
