bool like(string s, string t){
  sort(s.begin(), s.end());
  sort(t.begin(), t.end());
  return s==t;
}

bool g(vector<string>& v){
  int n = v.size();
  for(int i = 0;i<n;i++){
    for(int j = i+1;j<n;j++){
      if(like(v[i],v[j])){
        v.erase(v.begin() + j);
        v.erase(v.begin() + i);
        return 1;
      }
    }
  }
  return 0;
}

bool f(vector<string> v){
  int n = v.size();
  while(n--){
    g(v);
  }

  return v.empty();
}



