LL revhash(LL x){
	LL z = 0;
	for(int i = 0; i < w; ++i){
		z |= (x & 31) << ((w - i - 1) * 5);
		x >>= 5;
	}
	return z;
}

void check(const vector<int> &idx){
	vector<LL> v;
	for(cauto s : ss){
		LL z = 0;
		for(int k : idx){
			z = z << 5 | (s[k] - 'a');
		}
		v.push_back(z);
	}

	bool flag = (idx.size() % 2 != 0);
	while(!v.empty()){
		LL r1 = v.back();
		v.pop_back();
		LL r2 = revhash(r1);

		auto it = find(ALL(v), r2);
		if(it != v.end()){
			v.erase(it);
		}
		else if(flag && r1 == r2){
			flag = false;
		}
		else{
			return;
		}
	}
	puts("YES");
	throw 0;
}

void dfs(int i, vector<int> &idx, vector<int> rest){
	rest.erase(remove(ALL(rest), -1), rest.end());
	if(rest.empty()){
		check(idx);
	}
	else{
		int a = rest.back();
		rest.pop_back();
		if(idx.size() & 1 && idx[idx.size() / 2] == -1){
			idx[idx.size() / 2] = a;
			dfs(i, idx, rest);
			idx[idx.size() / 2] = -1;
		}

		idx[i] = a;
		for(int &x : rest){
			int y = x;
			x = -1;
			idx[idx.size() - i - 1] = y;
			dfs(i + 1, idx, rest);
			idx[idx.size() - i - 1] = -1;
			x = y;
		}
		idx[i] = -1;
	}
}

