bool Mirrored(int C1,int C2){
	for(int J=1;J<=N;J++) if(Ch[VisRow[J]][C1]!=Ch[J][C2]) return 0;
	return 1;
}
void DFS2(int X,bool Can){
	if(X==N+1)  exit(!printf("YES\n"));
	if(VisCol[X]>0) return void(DFS2(X+1,Can));
	for(int I=X+1;I<=M;I++)
		if((!VisCol[I])&&(Mirrored(I,X))){
			VisCol[I]=X,VisCol[X]=I;
			DFS2(X+1,Can);
			VisCol[I]=VisCol[X]=0;
		}
	if(Mirrored(X,X)&&Can) VisCol[X]=X,DFS2(X+1,0),VisCol[X]=0;
}
void DFS1(int X,bool Can){
	if(X==N+1) return void(DFS2(1,M&1));
	if(VisRow[X]>0) return void(DFS1(X+1,Can));
	for(int I=X+1;I<=N;I++)
		if((!VisRow[I])&&(Compos[I]==Compos[X])){
			VisRow[I]=X,VisRow[X]=I;
			DFS1(X+1,Can);
			VisRow[I]=VisRow[X]=0;
		}
	if(Can) VisRow[X]=X,DFS1(X+1,0),VisRow[X]=0;
}
