bool hvans;

void pd()
{
	map<string, int> cnt;
	for (int j = 0; j < m; j++)
	{
		string xx;
		for (int i = 0; i < n; i++)
		{
			if(ss[i][j]=='*')
				xx += ss[n - i - 1][j];
			else
				xx += ss[i][j];
		}
		string t = xx;
		reverse(ALL(t));
		cnt[min(xx, t)]++;
	}
	bool jo = 0;
	foreach(it,cnt)
	{
		string xx = it->first;
		string tt = xx;
		reverse(ALL(tt));
		if(it->second%2==0)
			continue;
		if(xx!=tt)
			return;
		if(jo)
			return;
		jo = 1;
	}
	hvans = 1;
}

void gao(int b,int now)
{
	if(!b)
	{
		pd();
		return;
	}
	int c = 0;
	while(!BIT(b,c))
		c++;
	ss[now] = s[c];
	for (int i = c + 1; i < n; i++)
		if(BIT(b,i))
		{
			ss[n - 1 - now] = s[i];
			gao(b ^ MASK(c) ^ MASK(i), now + 1);
		}
}

