int match[14];
bool disable_col[14][14];
bool used2[14];

bool visited[1 << 14];

bool dfs(int bit){
    if(bit == (1 << W) - 1) return true;
    if(visited[bit]) return false;

    int k = 0;
    while((bit>>k)&1) k++;

    bool only = true;
    for(int l=k+1;l<W;l++){
        if((bit>>l)&1) continue;
        only = false;
        if(disable_col[k][l]) continue;
        if(dfs(bit | (1 << l) | (1 << k))) return true;
    }

    if(only) return true;

    visited[bit] = true;
    return false;
}

