      mr[i][j] = mr[j][i] = true;
      for (int k = 0; k < w; k ++)
        if (v1[k] != v2[k]) {
          mr[i][j] = mr[j][i] = false;
          break;
        }
    }
  }
  // column
  for (int i = 0; i < w; i ++) {
    for (int j = i + 1; j < w; j ++) {
      vector<char> v1, v2;
      for (int k = 0; k < h; k ++) {
