  if (now < 0) {
    bool good = true;
    for (int i = 0; i < h and good; i ++) {
      for (int j = 0; j < w and good; j ++) {
        if (s[rw[i]][cl[j]] != s[rw[h - i - 1]][cl[w - j - 1]])
          good = false;
      }
    }
    if (good) ans = true;
    return;
  }

  if (now + now + 2 == w + 1) {
    for (int pt = 0; pt < w; pt ++) {
      usdc[pt] = true;
      cl[now] = pt;
      dfs2(now - 1);
      usdc[pt] = false;
    }
  } else {
    int pt = 0;
    while (usdc[pt]) pt ++;
    usdc[pt] = true;
    cl[now] = pt;
    for (int pt2 = pt + 1; pt2 < w; pt2 ++) {
