bool dfs(int depth){
	if(depth == -1){
		if(h % 2 == 0){
			return dfs(0);
		}
		else{
			REP(i,h){
				if(i != (h+1)/2){
					REP(j,w){
						swap(mp[i][j],mp[(h+1)/2][j]);
					}
					if(dfs(0))return true;
					REP(j,w){
						swap(mp[i][j],mp[(h+1)/2][j]);
					}
				}
			}
		}
		return false;
	}		
	//cout << "dfs " << depth << endl;
	if(depth == h - depth - 1 || depth + 1 == h - depth - 1){
		return check();
	}
	for(int i = depth;i < h - depth;i++){
	//cout << i << endl;
		if(i != h-depth-1)REP(k,w){
			swap(mp[h-depth-1][k],mp[i][k]);
		}
		if(dfs(depth+1))return true;
		if(i != h-depth-1)REP(k,w){
			swap(mp[h-depth-1][k],mp[i][k]);
		}
	}
	return false;
}

