    rep(y, H) {
      string buf = "";
      rep(x, seq.size()) buf += S[seq[x]][y];
      rep(x, W) if (!used[x]) buf += S[x][y];
      vs.pb(buf);
    }
    vector<bool> dead(vs.size(), false);
    rep(i, H) if (!dead[i]) {
      for (int j=i+1; j<H; j++) if (vs[i] == rev(vs[j])) {
        dead[i] = dead[j] = true;
        break;
      }
    }
    vector<string> alive;
    rep(i, H) if (!dead[i]) alive.pb(vs[i]);
    if (H%2 == 0 && alive.empty()) {
      cout << "YES\n";
      exit(0);
    }
    if (H%2 == 1 && alive.size() == 1 && alive[0] == rev(alive[0])) {
      cout << "YES\n";
      exit(0);
    }
    return;
  }
  rep(i, W) if (!used[i]) {
    used[i] = true;
    seq.pb(i);
    f(k-1);
    seq.pop_back();
    used[i] = false;
  }
}

