  }
  while(ss.size() >= 2) {
    string s = *ss.begin(); ss.erase(s);
    reverse(s.begin(), s.end());
    if(!ss.count(s)) return;
    ss.erase(s);
  }
  R = true;
}

void go() {
  if(2 * K == W) { check(); return; }
  int s; for(s = 0; ; ++s) if(!U[s]) break;
  P[K] = s; U[s] = true;
  if(2 * K + 1 == W) { check(); U[s] = false; return; }
  for(int t = 0; t < W; ++t) if(!U[t]) {
    P[W - 1 - K] = t; U[t] = true;
    ++K; go(); --K;
    U[t] = false;
  }
  U[s] = false;
}

