	if (num == h) { lis.push_back(x); return; }
	int sz = x.size();
	if (h % 2 == 1&&x[sz-1].empty()) {
		x[sz - 1] = { num,num };
		make(lis, x, num + 1, now_max, h);
		x[sz - 1] = {};
	}
	rep(i, now_max) {
		if (x[i].size() < 2) {
			x[i].push_back(num);
			make(lis, x, num + 1, now_max, h);
			x[i].pop_back();
		}
	}
	if (now_max < h/2){
		x[now_max].push_back(num);
		now_max++;
		make(lis, x, num + 1, now_max, h);
		x[now_max-1].pop_back();
	}
}
