int bits[N];

struct BP {
	int n;
	vector<int> G[N];
	int match[N];
	bool used[N];
	BP(int _n) : n(_n) {}

	void reset() {
		REPU(i, 0, n) {
			G[i].clear();
		}
	}

	void add_edge(int u, int v) {
	    G[u].push_back(v);
	    G[v].push_back(u);
	}

	bool dfs(int v) {
	    used[v] = true;
	    REPU(i, 0, G[v].size()) {
	        int u = G[v][i], w = match[u];
	        if (w < 0 || !used[w] && dfs(w)) {
	            match[v] = u;
	            match[u] = v;
	            return true;
	        }
	    }
	    return false;
	}

	int bipartite_matching() {
	    int res = 0;
	    MEM(match, -1);
	    REPU(v, 0, n) {
	        if (match[v] < 0) {
	        	MEM(used, 0);
	            if (dfs(v)) res++;
	        }
	    }
	    return res;
	}
};

bool dfs(int msk, ll cur, bool skipped, vector<ll>& ms) {
	if (!ms.empty()) return true;
	int nxt = 0, idx = 0;
	REPU(i, 0, r) {
		if (msk >> i & 1) bits[idx++] = i, nxt |= 1 << i;
	}
	if (idx > 1) {
		REPU(i, 1, idx) if (is_row[bits[0]][bits[i]]) {
			ll nxt = ((cur + bits[0]) * r + bits[i]) * r;
			dfs(msk ^ (1 << bits[0]) ^ (1 << bits[i]), nxt, skipped, ms);
		}
		if ((r & 1) && !skipped) {
			dfs(msk ^ (1 << bits[0]), cur, true, ms);
		}
	}
	else {
		ms.push_back(cur);
	}
	return true;
}

