	ios_base::sync_with_stdio(false);

	MEM(dpr, 0); MEM(dpc, 0); MEM(is_row, 0); MEM(is_col, 0);

	cin >> r >> c;
	REPU(i, 0, r) cin >> b[i];
	BP bp(c);
	REPU(i, 0, r) REPU(j, i + 1, r) {
		multiset<P> st;
		REPU(l, 0, c) {
			if (st.count(P(b[j][l], b[i][l])) > 0) {
				auto it = st.find(P(b[j][l], b[i][l]));
				st.erase(it);
			}
			else st.insert(P(b[i][l], b[j][l]));
		}
		bool ok(false);
		if (c % 2 == 0 && st.empty()) ok = true;
		else if (c % 2 == 1 && st.size() == 1) ok = true;
		if (ok) {
			bp.reset();
			REPU(k, 0, c) REPU(l, k + 1, c) {
				if (b[i][k] == b[j][l] && b[i][l] == b[j][k]) {
					bp.add_edge(k, l);
				}
			}
			is_row[i][j] = bp.bipartite_matching() == c / 2 ? 1 : 0;
		}
	}
	vector<ll> cans;
	dfs((1 << r) - 1, 0, false, cans);
	puts(cans.size() > 0 ? "YES" : "NO");

	return 0;
}

