bool ok;
bool check(){
	memset(match_c,-1,sizeof match_c);
	for(int i=0;i<W;i++){
		if(match_c[i]!=-1) continue;
		for(int j=i+1;j<W;j++){
			if(match_c[j]!=-1) continue;
			bool succ=true;
			for(int k=0;k<H && succ;k++)
				if(grid[match_r[k]][i]!=grid[k][j])
					succ=false;
			if(succ){
				match_c[i]=j,match_c[j]=i;
				break;
			}
		}
	}
	int unmatch=0,mid;
	for(int i=0;i<W;i++)
		if(match_c[i]==-1){
			unmatch++;
			mid=i;
		}
	if(unmatch>=2 || (unmatch && W%2==0)) return false;
	if(!unmatch) return true;
	for(int i=0;i<H;i++)
		if(grid[match_r[i]][mid]!=grid[i][mid])
			return false;
	return true;
}
void dfs(int idx,bool is_skip){
	if(idx>=H){
		if(check()) ok=true;
	}else{
		if(match_r[idx]!=-1){
			dfs(idx+1,is_skip);
		}else{
			for(int i=idx+1;i<H;i++){
				if(match_r[i]==-1){
					match_r[idx]=i;
					match_r[i]=idx;
					dfs(idx+1,is_skip);
					match_r[idx]=match_r[i]=-1;
				}
			}
			if(!is_skip && H&1){
				match_r[idx]=idx;
				dfs(idx+1,true);
				match_r[idx]=-1;
			}
		}
	}
}
