inline void dfs2(int x,bool md){
	if(x==m){
		cout<<"YES"<<endl;
		exit(0);
	}
	if(use2[x]!=-1){
		dfs2(x+1,md);
		return;
	}
	for(int i=x+1;i<m;i++){
		if(use2[i]!=-1){
			continue;
		}
		int j;
		for(j=0;j<n;j++){
			if(c[j][x]!=c[use[j]][i]) break;
		}
		if(j==n){
			use2[x]=i;
			use2[i]=x;
			dfs2(x+1,md);
			use2[x]=-1;
			use2[i]=-1;
		}
	}
	if(!md){
		int j;
		for(j=0;j<n;j++){
			if(c[j][x]!=c[use[j]][x]) break;
		}
		if(j==n){
			use2[x]=x;
			dfs2(x+1,true);
			use2[x]=-1;
		}
	}
}
inline void dfs(int x,bool md){
	if(x==n){
		dfs2(0,!m%2);
		return;
	}
	if(use[x]!=-1){
		dfs(x+1,md);
		return;
	}
	for(int i=x+1;i<n;i++){
		if(use[i]!=-1) continue;
		if(s[i]!=s[x]) continue;
		use[i]=x;
		use[x]=i;
		dfs(x+1,md);
		use[x]=-1;
		use[i]=-1;
	}
	if(!md){
		use[x]=x;
		dfs(x+1,1);
		use[x]=-1;
	}
}
