vpii st;
vector<vpii> a, b;

bool bit(int m, int i) {
	return (m & (1 << i));
}

void rech(int p, int mask) {
	if (p == h + 1) {
		a.pb(st);
		return;
	}
	if (bit(mask, p)) {  
		rech(p + 1, mask);
		return;
	}
	fi(p + 1, h) {
		if (bit(mask, i)) continue;
		if (i == p) continue;
		if (!eh[i][p]) continue;
		int mask1 = mask;
		mask1 ^= (1 << i);
		mask1 ^= (1 << p);
		st.pb(mp(p, i));
		rech(p + 1, mask1);
		st.pop_back();
	}
}

void recw(int p, int mask) {
	if (p == w + 1) {
		b.pb(st);
		return;
	}
	if (bit(mask, p)) {  
		recw(p + 1, mask);
		return;
	}
	fi(p + 1, w) {
		if (bit(mask, i)) continue;
		if (i == p) continue;
		if (!ew[i][p]) continue;
		int mask1 = mask;
		mask1 ^= (1 << i);
		mask1 ^= (1 << p);
		st.pb(mp(p, i));
		recw(p + 1, mask1);
		st.pop_back();
	}
}

