int h,w;
char v[20][20];

int pr[15];
int pc[15];
bool cr[15];

bool check(){
  // dbg(vector<int>(pr, pr+h));
  // dbg(vector<int>(pc, pc+w));
  fill(cr, cr+h, false);
  rep(i,h) if(!cr[i]){
    int ti = pr[i]==-1 ? i : pr[i];
    cr[i] = cr[ti] = true;
    rep(j,w){
      int tj = pc[j]==-1 ? j : pc[j];
      if(v[i][j] != v[ti][tj]) return false;
    }
  }
  return true;
}

bool dfs_c(int d = 0){
  if(d == w/2) return check();
  int x = 0;
  rep(_, 1 + w%2){
    while(x<w && pc[x] != -1) x++;
    rep(i,x+1,w) if(pc[i]==-1){
      pc[x] = i;
      pc[i] = x;
      if(dfs_c(d+1)) return true;
      pc[i] = -1;
    }
    pc[x] = -1;
    x++;
  }
  return false;
}

bool dfs_r(int d = 0){
  if(d == h/2) return dfs_c();
  int x = 0;
  rep(_, 1 + h%2){
    while(x<h && pr[x] != -1) x++;
    rep(i,x+1,h) if(pr[i]==-1){
      pr[x] = i;
      pr[i] = x;
      if(dfs_r(d+1)) return true;
      pr[i] = -1;
    }
    pr[x] = -1;
    x++;
  }

  return false;
}

bool solve(){
  cin>>h>>w;
  rep(i,h) cin>>v[i];

  fill(pr, pr+h, -1);
  fill(pc, pc+w, -1);
  return dfs_r();
}

int main(){
  cout << (solve() ? "YES" : "NO") << endl;
  return 0;
}

