void go(auto& grid, int dep) {
    if (2 * dep + 1 >= grid.size()) {
        const int H = grid.size();
        const int W = grid[0].size();

        set<string> matches;
        for (int i = 0; i < W; i++) {
            string col(H, '.');
            for (int j = 0; j < H; j++)
                col[j] = grid[j][i];

            string tmp = col;
            reverse(all(tmp));
            if (matches.count(tmp)) {
                matches.erase(tmp);
            } else {
                matches.insert(col);
            }
        }

        if (!matches.size()) {
            cout << "YES\n";
            exit(0);
        } else if (matches.size() == 1) {
            string elt = *matches.begin();
            string tmp = elt;
            reverse(all(tmp));
            if (elt == tmp) {
                cout << "YES\n";
                exit(0);
            }
        }
    } else {
        int pick = min_element(grid.begin() + dep, grid.end() - dep)
            - grid.begin();
        swap(grid[dep], grid[pick]);

        const int H = grid.size();
        for (int pr = dep + 1; pr < H - dep; pr++) {
            swap(grid[pr], grid[H - dep - 1]);
            go(grid, dep + 1);
            swap(grid[pr], grid[H - dep - 1]);
        }

        swap(grid[dep], grid[pick]);
    }
}

