const int MAX_N = 15;

int n, m, order[MAX_N];
char mp[MAX_N][MAX_N], *lmp[MAX_N];
bool vis[MAX_N];

bool check()
{
    for (int i = 1; i <= n; i++)
        lmp[i] = mp[order[i]];
    for (int i = 1; i <= m; i++)
        vis[i] = false;
    int matches = 0;
    for (int i = 1; i <= m; i++)
        if (!vis[i])
            for (int j = i + 1; j <= m; j++)
                if (!vis[j])
                {
                    bool flag = true;
                    for (int k = 1; k <= n; k++)
                        flag &= (lmp[k][i] == lmp[n - k + 1][j]);
                    if (flag)
                        matches++, vis[i] = vis[j] = true;
                }
    return (matches == (m >> 1));
}

bool dfs(int pos)
{
    if (pos == n + 1)
        return check();
    if (order[pos] != 0)
        return dfs(pos + 1);
    int cnt = 0;
    for (int i = pos; i <= n; i++)
        if (order[i] == 0)
            cnt++;
    for (int i = pos; i <= n; i++)
        if (order[i] == 0)
        {
            order[pos] = i, order[i] = pos;
            if (((cnt & 1) || (i != pos)) && dfs(pos + 1))
                return true;
            order[pos] = order[i] = 0;
        }
    return false;
}

