void check_col() {
	map<string, int> M;
	for (int i = 0; i < m; i++) {
		bool used[N];
		for (int j = 0; j < n; j++) used[j] = 0;
		string str;
		for (int j = 0; j < n; j++) {
			if (!used[j]) {
				used[j] = used[match[j]] = 1;
				str = s[j][i] + str + s[match[j]][i];
			}
		}
		M[str]++;
	}
	bool f = 1, canrev = m & 1;
	for (auto p : M) {
		string str = p.first;
		int times = p.second;
		string rev = str;
		reverse(rev.begin(), rev.end());
		if (rev != str) {
			if (M[rev] != times) {
				f = 0;
				break;
			}
		} else {
			if (times & 1) {
				if (!canrev) {
					f = 0;
					break;
				} else {
					canrev = 0;
				}
			}
		}
	}
	if (f) {
		puts("YES\n");
		exit(0);
	}
}

void solve_row(int i, bool flag) {
	if (i == n) {
		check_col();
		return;
	}
	if (~match[i]) {
		solve_row(i + 1, flag);
		return;
	}
	for (int j = 0; j < n; j++) {
		if (ss[j] != ss[i]) continue;
		if (~match[j]) continue;
		match[i] = j;
		match[j] = i;
		solve_row(i + 1, flag);
		match[j] = -1;
	}
	if (flag) {
		match[i] = i;
		solve_row(i + 1, 0);
	}
}

