int n, m, l, p[13];
char s[13][13]; bool flag;
bool IsMat(int u, int v) {
	for (int i = 1; i <= m; i++)
		if (s[u][i] ^ s[v][p[i]]) return false;
	return true;
}
bool chk() {
	bool used[13], pal = n&1;
	memset(used, false, sizeof used);
	for (int u = 1, v; u <= n; u++) if (!used[u]) {
		for (v = u+1; v <= n; v++)
			if (!used[v] && IsMat(u, v)) break;
		if (v <= n) used[u] = used[v] = true;
		else if (!IsMat(u, u)) return false;
		else if (!pal) return false;
		else used[u] = true, pal = false;
	}
	return true;
}
void DFS(int u, bool odd) {
	if (u > m) {flag |= chk(); return;}
	if (p[u]) {DFS(u+1, odd); return;}
	if (odd) p[u] = u, DFS(u+1, odd^1), p[u] = 0;
	for (int v = u+1; !flag && v <= m; v++) if (!p[v])
		p[u] = v, p[v] = u, DFS(u+1, odd), p[u] = p[v] = 0;
}
