int valid(vector<string> s1,vector<string> s2){
  sort(s1.begin(),s1.end());
  sort(s2.begin(),s2.end());
  return s1 == s2;
}

int used[1<<12][1<<12];
int dfs(int bit1,int bit2,vector<string> s1,vector<string> s2,int skip){
  if(!valid(s1,s2)) return 0;
  if(used[bit1][bit2]++) return 0; 
  if(bitCount(bit1) + bitCount(bit2) == w) return 1;

  for(int i=0;i<w;i++)
    for(int j=0;j<w;j++){
      if(bit1>>i&1) continue;
      if(bit2>>i&1) continue;
      if(bit1>>j&1) continue;
      if(bit2>>j&1) continue;
      if(i == j) continue;
      int nbit1 = bit1|(1<<i);
      int nbit2 = bit2|(1<<j);
      for(int l=0;l<h;l++) if(l!=skip) s1[l].push_back(str[l][i]);
      for(int l=0;l<h;l++) if(l!=skip) s2[l].push_back(str[l][j]);
      if(dfs(nbit1,nbit2,s1,s2,skip)) return 1;
      for(int l=0;l<h;l++) if(l!=skip) s1[l].pop_back();
      for(int l=0;l<h;l++) if(l!=skip) s2[l].pop_back();
    }
  return 0;
}

