int main() {
	int H; int W;
	while (~scanf("%d%d", &H, &W)) {
		vector<string> S(H);
		for (int i = 0; i < H; ++ i)
			cin >> S[i];
		vector<string> revS;
		auto solve = [&]() {
			revS = S;
			for (auto &s : revS)
				reverse(s.begin(), s.end());
			int used = 0;
			int i = 0;
			for (int t = 0; t < H / 2; ++ t) {
				while (1) {
					for (; i < H && (used >> i & 1); ++ i);
					if (i == H) break;
					for (int k = i + 1; k < H; ++ k) if (~used >> k & 1) {
						if (S[i] == revS[k]) {
							used |= 1 << i;
							used |= 1 << k;
							goto ok;
						}
					}
					++ i;
				}
			ok:
				if (i == H) return false;
			}
			if (H % 2 == 1) {
				for (; i < H && (used >> i & 1); ++ i);
				if (i == H) return false;
				return S[i] == revS[i];
			} else {
				return true;
			}
		};
		vector<bool> matched(W);
		auto swapCol = [&](int i, int j) {
			swap(matched[i], matched[j]);
			for (int k = 0; k < H; ++ k)
				swap(S[k][i], S[k][j]);
		};
		bool ans = false;
		function<void(int)> rec = [&](int i) {
			if (i == W / 2) {
				if (solve()) {
					ans = true;
				}
				return;
			}
			for (int j = 0; j < W; ++ j) if (j != i && !matched[j]) {
				matched[i] = matched[j] = true;
				swapCol(W - 1 - i, j);
				rec(i + 1);
				swapCol(W - 1 - i, j);
				matched[i] = matched[j] = false;
			}
		};
		if (W % 2 == 0) {
			rec(0);
		} else {
			for (int mid = 0; mid < W; ++ mid) {
				matched[mid] = true;
				swapCol(mid, W / 2);
				rec(0);
				swapCol(mid, W / 2);
				matched[mid] = false;
			}
		}
		puts(ans ? "YES" : "NO");
	}
}

