int32 dp[1 << 12];

bool dfs2(int32 now){
	if(~dp[now]) return now;
	if(now == 0) return dp[now] = 1;
	if(__builtin_popcount(now) == 1){
		REP(i, W){
			if(now >> i & 1){
				if(pack[i][i]) return dp[now] = 1;
				return dp[now] = 0;
			}
		}
	}
	dp[now] = 0;
	REP(i, W){
		FOR(j, i+1, W){
			if(now >> i & 1 && now >> j & 1){
				if(pack[i][j]) dp[now] |= dfs2(now^(1<<i)^(1<<j));
			}
		}
	}
	return dp[now];
}

bool ok(){
	pack = vector<vector<bool>>(W, vector<bool>(W, 1));
	REP(k, pa.size()){
		int32 f = pa[k].fs, t = pa[k].sc;
		REP(i, W){
			FOR(j, i, W){
				if (s[f][i] != s[t][j] || s[t][i] != s[f][j]) pack[i][j] = pack[j][i] = 0;
			}
		}
	}
	memset(dp, -1, sizeof dp);
	return dfs2((1 << W)-1);
}

bool dfs(int32 d, int32 cnt, int32 rest){
	if((rest >> d & 1) && cnt < H) return dfs(d+1, cnt, rest);
	if(cnt == H-H%2){
		if(H%2) pa.push_back(PII(d, d));
		bool ret = ok();
		if(H%2) pa.pop_back();
		return ret;
	}
	FOR(i, d+1, H){
		if(rest >> i & 1) continue;
		pa.push_back(PII(d, i));
		bool ret = dfs(d+1, cnt+2, rest^(1<<i)^(1<<d));
		if(ret) return ret;
		pa.pop_back();
	}
	return 0;
}

