using namespace std;
inline int inn()
{
	int x,ch;while((ch=gc)<'0'||ch>'9');
	x=ch^'0';while((ch=gc)>='0'&&ch<='9')
		x=(x<<1)+(x<<3)+(ch^'0');return x;
}
int nxt[N],z[N],f[N];char s[N][N],t[N][N];
bool vis[N],chose[N],has_ans;
inline int calc_z(int x,int n)
{
	int ans=0;
	for(int i=1;i<=n;i++) ans=(ans+t[i][x]-'a'+1)*BAS%mod;
	return ans;
}
inline int calc_f(int x,int n)
{
	int ans=0;
	for(int i=1;i<=n;i++) ans=(ans+t[i][x]-'a'+1)*BAS%mod;
	return ans;
}
inline bool check(int n,int m)
{
	for(int i=1,j=0;i<=n;i++) if(nxt[i]) j++,
		memcpy(t[j],s[i],sizeof(char)*(m+1)),memcpy(t[n-j+1],s[nxt[i]],sizeof(char)*(m+1));
	if(n&1) memcpy(t[n/2+1],s[n],sizeof(char)*(m+1));
	for(int i=1;i<=m;i++) z[i]=calc_z(i,n),f[i]=calc_f(i,n);
	int res=m;memset(vis,false,sizeof(bool)*(m+1));
	for(int i=1;i<=m;i++)
		if(!vis[i]) for(int j=1;j<=m;j++) if(i^j)
			if(!vis[j]&&z[i]==f[j]) { vis[i]=vis[j]=true,res+=2;break; }
	return m-res<=1;
}
bool dfs(int n,int m,int alr,int x=1)
{
	if(n-alr<=1) return has_ans|=check(n,m);if(has_ans) return true;
	for(int i=1;i<=n/2*2;i++) if(!chose[i]) { x=i;break; }
	chose[x]=true;
	for(int i=x+1;i<=n/2*2;i++) if(!chose[i])
		nxt[x]=i,chose[i]=true,dfs(n,m,alr+2),nxt[x]=0,chose[i]=false;
	return chose[x]=false,has_ans;
}
inline int is_par(int x,int n)
{
	for(int i=1;i<=n;i++)
		if(s[x][i]^s[x][n-i+1]) return false;
	return true;
}
int main()
{
	int n=inn(),m=inn();has_ans=false;
	for(int i=1;i<=n;i++) scanf("%s",s[i]+1);
	if(n%2==0) dfs(n,m,0);
	else for(int i=1;i<=n;i++)
		if(is_par(i,m)) swap(s[i],s[n]),dfs(n,m,0),swap(s[i],s[n]);
	if(has_ans) printf("YES\n");else printf("NO\n");return 0;
}

