bool check(vector<vector<int> > temp,int H,int W){
	for(int h=0;h<H;++h){
		//sort(temp[h].begin(),temp[h].end());
	}
	vector<int> Hpair(H,-1);
	for(int i=0;i<H;++i){
		if( Hpair[i] != -1 ){
			continue;
		}
		for(int j=i+1;j<H;++j){
			if( Hpair[j] != -1 ){
				continue;
			}
			if( temp[i] == temp[j] ){
				Hpair[i] = j;
				Hpair[j] = i;
				break;
			}
		}
	}
	int count = 0;
	int pos = -1;
	for(int i=0;i<H;++i){
		if(Hpair[i]==-1 ){
			pos = i;
			++count;
		}
	}
	if(H&1 ){
		if(count!=1){
			return false;
		}
		//横のチェック
		vector<int> TER = temp[pos];
		vector<int> tHist(26,0);
		int size = TER.size();
		for(int i=0;i<size;++i){
			tHist[TER[i]]++;
		}
		int todd = 0;
		for(int i=0;i<26;++i){
			if( tHist[i]&1 ){
				todd++;
			}
		}
		if(W&1){
			if(todd!=1){
				return false;
			}
		}else{
			if(todd){
				return false;
			}
		}
	}else{//横が偶数個
		if(count){//ペアを作れてないものがったらダメ
			return false;
		}
	}
	return true;
}
