using namespace std;

int h, w;
vector<string> s;
vector<int> hp;
bool ans = false;

bool isMatch(int a, int b){
    for(int i = 0; i < h; i++){
        if(s[i][a] != s[hp[i]][b]) return false;
    }
    return true;
}

void check(){
    int wOdd = w % 2;
    vector<int> used(w, 0);
    for(int i = 0; i < w; i++){
        if(used[i]) continue;
        for(int j = i + 1; j < w; j++){
            if(used[j]) continue;
            if(isMatch(i, j)){
                used[i] = 1; used[j] = 1;
                break;
            }
        }
    }
    if(count(used.begin(), used.end(), 0) > 1) return;
    if(wOdd){
        for(int i = 0; i < w; i++){
            if(used[i]) continue;
            if(isMatch(i, i)){
                break;
            }else{
                return;
            }
        }
    }
    ans = true;
}

void dfs(int y, bool hOdd){
    if(ans) return;
    if(y >= h){
        check();
        return;
    }
    if(hp[y] != -1){
        dfs(y + 1, hOdd);
        return;
    }
    if(hOdd){
        hp[y] = y;
        dfs(y + 1, false);
        hp[y] = -1;
    }
    for(int i = y + 1; i < h; i++){
        if(hp[i] != -1) continue;
        hp[y] = i; hp[i] = y;
        dfs(y + 1, hOdd);
        hp[y] = -1; hp[i] = -1; 
    }
    hp[y] = -1;
}

int main(){

    cin >> h >> w;
    s.resize(h);
    for(int i = 0; i < h; i++){
        cin >> s[i];
    }
    hp = vector<int>(h, -1);
    if(h % 2){
        dfs(0, true);
    }else{
        dfs(0, false);
    }
    if(ans){
        cout << "YES" << endl;
    }else{
        cout << "NO" << endl;
    }
    return 0;
}

