int p[13];
bool used[13];

bool finished;

void check(){
	for(int i=1; i<=h; i++)
		for(int j=1; j<=w; j++)
			ns[i][j] = s[i][p[j]];

	bool check[h+1];
	for(int i=1; i<=h; i++)
		check[i]=false;
	for(int i=1; i<=h; i++){
		if(check[i]) continue;
		bool found=false;
		for(int j=i+1; j<=h; j++){
			bool flag=true;
			for(int k=1, l=w; k<l; k++, l--)
				if(ns[i][k] != ns[j][l]){
					flag=false;
					break;
				}
			if(flag){
				found=true;
				check[i]=true;
				check[j]=true;
				break;
			}
		}
		if(!found) return;
	}
	finished = true;
}

void backtrack(int now, int val, int cnt){
	for(int i=val+1; i<=w; i++){
		if(used[i]) continue;
		used[i]=true;
		p[now]=i;

		if(cnt == w){ /// end condition
			check();
		}
		else if(cnt&1) backtrack(w+1-now, i, cnt+1);
		else backtrack(w+2-now, 0, cnt+1);

		used[i]=false;

		if(finished) return;
	}
	return;
}

