bool sub(vi& hpat){
    vector<ll> xs, ys;
    int same = 0;
    rep(j,W){
        ll x = 0, y = 0;
        rep(i,H){
            int rx = hpat[i], ry = hpat[H-1-i];
            x = (x << 5LL) | S_[rx][j];
            y = (y << 5LL) | S_[ry][j];
        }
        if (x == y) ++same;
        else { xs.pb(x); ys.pb(y); }
    }

    if (W % 2 != same % 2) return false;

    vector<ii> pairs;
    int m = xs.size();
    assert(m % 2 == 0);
    rep(i,m) rep(j,m){
        if (i == j) continue;
        if (xs[i] == ys[j])
            pairs.pb(ii(i,j));
    }
    int mmc = maximum_match_count(pairs);
    return (mmc == m);
}


