bool dfs(int n = 0) {
	if(n == (h + 1) / 2) {
		std::map<std::string, int> mp;
		for(int i = 0; i < w; i++) {
			std::string latte = "";
			for(int j = 0; j < h; j++) {
				latte += s[vec[j]][i];
			}
			mp[latte] += 1; reverse(begin(latte), end(latte));
			mp[latte] -= 1;
		}

		for(auto p : mp) if(p.second != 0) return false;
		return true;
	}

	for(int i = 0; i < h; i++) {
		if(used[i]) continue;
		for(auto e : g[i]) {
			if(used[e]) continue;
			if(n != h - n - 1 and i == e) continue;
			vec[n] = i;
			vec[h - n - 1] = e;
			used[i] = true;
			used[e] = true;
			if(dfs(n + 1)) return true;
			used[i] = false;
			used[e] = false;
		}
	}

	return false;
}

