using PC = pair<char, char>;

int H, W;
string s[12];

bool DP[1 << 12][10395];
vector<vector<int>> pairs;

void Rec(int s, vector<int>& curr) {
	if (s == 0) {
		pairs.push_back(curr);
		return;
	}

	int v1, v2;
	REP(i, 0, W) {
		if ((s >> i) & 1) {
			v1 = i;
			s -= 1 << i;
			curr.push_back(v1);
			break;
		}
	}

	REP(i, 0, W) {
		if ((s >> i) & 1) {
			v2 = i;
			s -= 1 << i;
			curr.push_back(v2);
			Rec(s, curr);

			s += 1 << i;
			curr.pop_back();
		}
	}
	curr.pop_back();
	return;
}

void Pre() {
	if (W % 2 == 0) {
		vector<int> vec;
		Rec((1 << W) - 1, vec);
	} else {
		REP(i, 0, W) {
			vector<int> vec(2, i);
			Rec((1 << W) - 1 - (1 << i), vec);
		}
	}
}

bool ok(int i, int j) {
	vector<PC> vec;
	REP(k, 0, W) {
		vec.push_back(make_pair(s[i][k], s[j][k]));
	}

	auto score = [](PC p) {
		return (p.first == p.second) * 1000000 + min(p.first, p.second) * 500 + max(p.first, p.second);
	};

	sort(vec.begin(), vec.end(), [score](PC p, PC q) {
		return score(p) < score(q);
	});

	REP(k, 0, W) {
		if (vec[k].first != vec[W - k - 1].second) return false;
		if (vec[k].second != vec[W - k - 1].first) return false;
	}
	return true;
}

int main() {
	cin >> H >> W;
	REP(i, 0, H) {
		cin >> s[i];
	}

	Pre();

	REP(j, 0, pairs.size()) {
		DP[0][j] = true;
		REP(i, 0, H) {
			DP[1 << i][j] = true;
		}
	}

	REP(i, 1, 1 << H) {
		REP(j, 0, H) {
			if (!((i >> j) & 1)) continue;
			REP(k, 0, H) {
				if (!((i >> k) & 1)) continue;
				if (j == k) continue;
				REP(p, 0, pairs.size()) {
					REP(n, 0, (W + 1) / 2) {
						if (s[j][pairs[p][2 * n]] != s[k][pairs[p][2 * n + 1]]) goto End;
						if (s[j][pairs[p][2 * n]] != s[k][pairs[p][2 * n + 1]]) goto End;
					}

					DP[i][p] |= DP[i - (1 << j) - (1 << k)][p];
				End:
					;
				}
			}
		}
	}

	bool ok = false;
	REP(p, 0, pairs.size()) {
		ok |= DP[(1 << H) - 1][p];
	}
	YESNO(ok);
	return 0;
}

