using namespace std;

string s[12];
bool ans = false;
int h,w,selected[12] = {};

void calc(){
	string t[12],tate[12],rtate[12];
	int cnt = 0;
	for(int i = 0;i < h;i++){
		if(selected[i] == -1) t[h / 2] = s[i];
		else if(selected[i] > i){
			t[cnt] = s[i];
			t[h - cnt - 1] = s[selected[i]];
			cnt++;
		}
	}
	//for(int i = 0;i < h;i++) cout << t[i] << endl;
	for(int i = 0;i < w;i++){
		for(int j = 0;j < h;j++){
			tate[i] += t[j][i];
			rtate[i] = t[j][i] + rtate[i];
		}
	}
	bool flag = true,odd = false,s2[12] = {};
	for(int i = 0;i < w;i++){
		if(!s2[i]){
			for(int j = i + 1;j < w;j++){
				if(tate[i] == rtate[j]){
					s2[i] = true;
					s2[j] = true;
				}
			}
			if(!s2[i]){
				if(!odd && tate[i] == rtate[i]) odd = true;
				else flag = false;
			}
		}
	}
	if(flag) ans = true;
}

void dfs(int num){
	if((h % 2 == 0 && num == h) || (h % 2 && num == h - 1)){
		calc();
		return;
	}
	int ind;
	for(int i = 0;i < h;i++){
		if(selected[i] == -1){
			ind = i;
			break;
		}
	}
	for(int i = ind + 1;i < h;i++){
		if(selected[i] == -1){
			selected[i] = ind;
			selected[ind] = i;
			dfs(num + 2);
			selected[i] = -1;
			selected[ind] = -1;
		}
	}
}

signed main(){
	cin >> h >> w;
	for(int i = 0;i < h;i++) cin >> s[i];
	for(int i = 0;i < h;i++) selected[i] = -1;
	dfs(0);
	cout << (ans ? "YES" : "NO") << endl;
}

