#define relaxMax(a , b) (a) = max((a),(b))
#define SQR(a) ((a)*(a))
#define PI 3.14159265358979323846
typedef vector<int> vi;
typedef pair<int,int> pii;
typedef long long ll;

const int MAX = 15;

int h, w;
char in[MAX][MAX];

deque<char> Apply(int row, const vector<pii>& prs){
  deque<char> res;
  for(int i = sz(prs) - 1;i >= 0;--i){
    int a = prs[i].fi, b = prs[i].se;
    res.push_front(in[row][a]);
    res.pb(in[row][b]);
  }
  return res;
}

bool fine = false;

bool Validate(const vector<pii>& prs){
  vector<deque<char>> wrds;
  for(int i = 0;i < h;++i)
    wrds.pb(Apply(i, prs));

  while(!wrds.empty()){
    auto a = wrds.back();
    auto b = a;
    reverse(all(b));
    wrds.pop_back();

    if(wrds.empty()){
      return a == b;
    } else {
      auto pos = find(all(wrds), b);
      if(pos == wrds.end()) return false;
      wrds.erase(pos);
    }
  }

  return true;
}

void Iterate(vector<pii>& prs){
  if(fine) return;

  vector<char> free(w, true);
  for(const auto& e : prs)
    free[e.fi] = free[e.se] = false;

  int rem = count(all(free), true);

  if(rem == 0){
    fine = (fine || Validate(prs));
    return;
  }

  if(rem == 1){
    for(int i = 0;i < w;++i)
      if(free[i])
        prs.pb(mp(i, i)),
        Iterate(prs),
        prs.pop_back();
  }

  if(rem > 1){
    int ff = 0;
    while(!free[ff]) ++ff;
    for(int sf = ff + 1;sf < w;++sf)
      if(free[sf])
        prs.pb(mp(ff, sf)),
        Iterate(prs),
        prs.pop_back();
  }
}

int main(){
  scanf("%d%d", &h, &w);
  for(int i = 0;i < h;++i)
    scanf("%s", in[i]);

  vector<pii> prs;
  Iterate(prs);

  printf(fine ? "YES\n" : "NO\n");

  return 0;
}

