        rep(j, w){
            if(used[j]){
                continue;
            }

            rep(k, w){
                if(used[k]){
                    continue;
                }
                if(j == k){
                    continue;
                }
                string tmp = rows[k];
                reverse(tmp.begin(), tmp.end());
                if(rows[j] == tmp){
                    used[j] = true;
                    used[k] = true;
                    break;
                }
            }
        }

        int cnt = 0;
        int idx = 0;
        rep(j, w){
            if(not used[j]){
                cnt++;
                idx = j;
