bool judge(vector<string> r)
{
    int sz = r.size();

    bool b[sz];

    rep(i, sz)
    {
        b[i] = false;

        int len = r[i].length();
        char cc[len + 1];
        r[i].copy(cc, len);
        sort(cc, cc + len);
        cc[len] = '\0'; 
        r[i] = cc;
    }

    rep(i, sz)
    {
        if(b[i])
            continue;

        bool discoverd = false;
        loop(j, i + 1, sz)
        {
            if(b[j])
                continue;

            if(r[i] == r[j])
            {
                discoverd = true;
                b[j] = true;
                b[i] = true;
                break;
            }
        }
    }

    bool bl = false;

    rep(i, sz)
    {
        if(b[i])
            continue;

        if(bl)
            return false;

        if(!line_sym(r[i]))
            return false;

        b[i] = true;
        bl = true;
    }

    return true;
}

