bool solve2(int i) {
  if (i == w - 1) {
    int p = least_bit_fast(~used2);
    for (int k = 0; k < h; k += 2) {
      if (s[p1[k]][p] != s[p1[min(k + 1, h - 1)]][p]) return false;
    }
    return true;
  } else if (i == w) {
    return true;
  } else {
    int p = least_bit_fast(~used2);
    int uo = used2;
    used2 |= used2 + 1;
    for (int u = used2; least_bit_fast(~u) < w; u |= u + 1) {
      int q = least_bit_fast(~u);
      for (int k = 0; k < h; k += 2) {
        if (s[p1[k]][p] != s[p1[min(k + 1, h - 1)]][q]) {
          goto next;
        }
        if (s[p1[k]][q] != s[p1[min(k + 1, h - 1)]][p]) {
          goto next;
        }
      }
      {
      int uu = used2;
      used2 |= 1 << q;
      if (solve2(i + 2)) return true;
      used2 = uu;
      }
   next:;
    }
    used2 = uo;
    return false;
  }
}

bool solve1(int i) {
  if (i == h - 1) {
    p1.emplace_back(least_bit_fast(~used1));
    if (solve2(0)) return true;
    p1.pop_back();
    return false;
  } else if (i == h) {
    return solve2(0);
  } else {
    p1.emplace_back(least_bit_fast(~used1));
    int uo = used1;
    used1 |= used1 + 1;
    for (int u = used1; least_bit_fast(~u) < h; u |= u + 1) {
      int uu = used1;
      used1 |= 1 << least_bit_fast(~u);
      p1.emplace_back(least_bit_fast(~u));
      if (solve1(i + 2)) return true;
      used1 = uu;
      p1.pop_back();
    }
    used1 = uo;
    p1.pop_back();
    return false;
  }
}

