vector<int> state;

bool palindrome(const string &s) {
	return equal(s.begin(), s.end(), s.rbegin());
}

bool valid(const vector<int> &perm) {
	fori(i, 0, n) {
		buffer[i] = mat[i];
	}

	multiset<string> S;
	fori(i, 0, n) {
		fori(j, 0, m) {
			buffer[i][j] = mat[i][perm[j]];
		}

		S.insert(buffer[i]);
	}

	while(S.size() > 1) {
		string first = *S.begin(); S.erase(S.begin());

		string revF = first;
		reverse(revF.begin(), revF.end());

		if(S.count(revF)) {
			S.erase(S.find(revF));	
		}
		else {
			return false;
		}
	}

	if(S.size() == 1) {
		string f = *S.begin();

		if(!palindrome(f)) {
			return false;
		}
	}

	return true;
}

int total = 0;
void gen(int index) {
	if(2 * index >= m - 1) {
		/*if(valid(state)) {
			die("YES");
		}*/
		total++;
		return;
	}

	fori(i, 0, m) {
		if(!used[i]) {
			used[i] = true;
			state[index] = i;

			fori(j, i + 1, m) {
				if(!used[j]) {
					used[j] = true;
					state[m - index - 1] = j;

					gen(index + 1);

					used[j] = false;
				}
			}

			used[i] = false;

			break;
		}
	}
}

