bool valid(const std::vector<Int>& xs) {
   bool checked[16] = {};
   for(Int i = 0; i < h; ++i) {
      for(Int k = i + 1; k < h; ++k) {
         if( checked[k] ) continue;
         bool success = true;
         for(Int j = 0; j < w; ++j) {
            if( ss[i][xs[j]] != ss[k][xs[w-j-1]] ) {
               success = false;
            }
         }
         if( success ) {
            checked[i] = checked[k] = true;
         }
      }
   }
   Int t = 0;
   for(Int i = 0; i < h; ++i) {
      if( checked[i] ) t += 1;
   }
   if( h / 2 * 2 == t ) return true;
   return false;
