      }
      return;
   }
   for(Int i = 0; i < w; ++i) {
      if( checked[i] ) continue;
      xs.push_back(i);
      checked[i] = true;
      stage2(xs, checked);
      checked[i] = false;
      xs.pop_back();
   }
}

void stage1(std::vector<Int>& xs, std::vector<bool>& checked) {
   if( (Int)xs.size() >= w/2+1 ) {
      stage2(xs, checked);
