							valid = false;
						}else{
							center = key.first;
						}
					}
				}
				if(!valid){ continue; }
				int mask = 0;
				for(int p = 0; p < m; ++p){
					if(s[j][p] == center && s[k][p] == center){ mask |= (1 << p); }
				}
				const int key = i | (1 << j) | (1 << k);
				if(dp[key] < 0){ dp[key] = 0; }
				dp[key] |= (mask & dp[i]);
			}
		}
	}
	for(int k = 0; k < n; ++k){
		const int i = ((1 << n) - 1) & ~(1 << k);
		if(dp[i] < 0){ continue; }
		const int chk = check_palindrome(s[k]);
		if(chk < 0){ continue; }
		const int key = i | (1 << k);
		if(dp[key] < 0){ dp[key] = 0; }
		dp[key] |= (dp[i] & chk);
	}
if(m % 2 == 0 && n % 2 == 1){ return -1; }
	if(m % 2 == 0){
		cout << (dp[(1 << n) - 1] == 0 ? "YES" : "NO") << endl;
	}else{
		cout << (dp[(1 << n) - 1] > 0 ? "YES" : "NO") << endl;
	}
	return 0;
}

