using namespace std;
using pii = pair<int, int>;
using ull = unsigned long long;
static int dp[1 << 12];

int match_test(const string& s, const string& t){
	const int n = s.size();
	map<pii, int> mp;
	for(int i = 0; i < n; ++i){
		++mp[pii(s[i], t[i])];
	}
	int c = -1;
	for(const auto p : mp){
		const pii key(p.first.second, p.first.first);
		const int x = p.second;
		const int y = (mp.find(key) != mp.end()) ? mp[key] : 0;
		if(x != y){ return -1; }
		if(key.first == key.second && x % 2 != 0){
			if(n % 2 == 0 || c >= 0){ return -1; }
			c = key.first;
		}
	}
	int mask = 0;
	for(int i = 0; i < n; ++i){
		if(s[i] == c && t[i] == c){ mask |= (1 << i); }
	}
	return mask;
}

int palindrome_test(const string& s){
	const int n = s.size();
	vector<int> h(26);
	for(const int c : s){ ++h[c - 'a']; }
	int odd = -1;
	for(int i = 0; i < 26; ++i){
		if(h[i] % 2 == 1){
			if(odd >= 0){ return -1; }
			odd = i;
		}
	}
	int mask = 0;
	for(int i = 0; i < n; ++i){
		if(s[i] == odd + 'a'){ mask |= (1 << i); }
	}
	return mask;
}

int main(){
	ios_base::sync_with_stdio(false);
	int n, m;
	cin >> n >> m;
	vector<string> s(n);
	for(int i = 0; i < n; ++i){ cin >> s[i]; }
	vector<vector<int>> matching(n, vector<int>(n, -1));
	for(int i = 0; i < n; ++i){
		matching[i][i] = palindrome_test(s[i]);
		for(int j = 1; j < n; ++j){
			matching[i][j] = matching[j][i] = match_test(s[i], s[j]);
		}
	}
	bool answer = false;
	for(int i = 0; i < (1 << n); ++i){
		if(__builtin_popcount(i) != n / 2){ continue; }
		vector<int> used, unused;
		used.reserve(n / 2);
		unused.reserve((n + 1) / 2);
		for(int j = 0; j < n; ++j){
			if(i & (1 << j)){
				used.push_back(j);
			}else{
				unused.push_back(j);
			}
		}
		vector<int> perm(unused.size());
		for(int j = 0; j < unused.size(); ++j){ perm[j] = j; }
		do {
			int bits = 0;
			for(int j = 0; j < n / 2; ++j){
				bits |= matching[used[j]][unused[perm[j]]];
			}
			if(n % 2 == 1){
				bits |= matching[unused[perm.back()]][unused[perm.back()]];
			}
			if(bits < 0){ continue; }
			if(m % 2 != 0 && bits == 0){ continue; }
			map<ull, int> mp;
			for(int j = 0; j < m; ++j){
				ull h = 0;
				for(int k = 0; k < n / 2; ++k){ h = (h << 5) + (s[used[k]][j] - 'a'); }
				for(int k = 0; k < n / 2; ++k){ h = (h << 5) + (s[unused[perm[k]]][j] - 'a'); }
				++mp[h];
			}
			bool accept = true;
			for(const auto p : mp){
				const int shift = (n / 2 * 5);
				const ull h = p.first;
				const ull lo = h & ((1ull << shift) - 1);
				const ull hi = h >> shift;
				const ull key = (lo << shift) | hi;
				const int x = p.second;
				const int y = (mp.find(key) != mp.end()) ? mp[key] : 0;
				if(x != y){ accept = false; }
			}
			if(accept){
				answer = true;
				break;
			}
		} while(next_permutation(perm.begin(), perm.end()));
	}
	cout << (answer ? "YES" : "NO") << endl;
	return 0;
}

