using namespace std;
typedef long long ll;


int H, W;
int const MAX_H = 12;
int const MAX_W = 12;
string grid[MAX_H];
string result[MAX_H];
bool used[MAX_H];

bool compare_h(string s1, string s2){
    sort(s1.begin(), s1.end());
    sort(s2.begin(), s2.end());
    return s1 == s2;
}

bool compare_w(int j1, int j2){
    for (int i = 0; i < H; i++){
        if (result[i][j1] != result[H-1-i][j2]) return false;
    }
    return true;
}

//check result
bool check() {
//    cout << "check with" << endl;
//    for (int i = 0; i < H; i++){
//        cout << result[i] << endl;
//    }
//    cout << endl;


    bool uw[W];
    fill(uw, uw + W, false);
    bool skip = (W % 2 == 1);

    while (true){
        int j1 = find(uw, uw + W, false) - uw;
        if (j1 == W){
            return true;
        }

        bool found = false;
        for (int j2 = j1 + 1; j2 < W; j2++) {
            if (!uw[j2] && compare_w(j1, j2)) {
                found = true;
                uw[j1] = true;
                uw[j2] = true;
                break;
            }
        }

        if (!found){
            if (skip && compare_w(j1, j1)){
                uw[j1] = true;
                skip = false;
            } else {
                return false;
            }
        }
    }
}

bool rec(int idx1, int cnt, bool skip){
    if (idx1 == H) {
        return check();
    }

    if (used[idx1]){
        return rec(idx1+1, cnt, skip);
    } else {
        for (int idx2 = idx1+1; idx2 < H; idx2++){
            if (!used[idx2] && compare_h(grid[idx1], grid[idx2])){
                used[idx1] = true;
                used[idx2] = true;
                result[cnt] = grid[idx1];
                result[H-1-cnt] = grid[idx2];
                if (rec(idx1+1, cnt+1, skip)){
                    return true;
                } else {
                    used[idx1] = false;
                    used[idx2] = false;
                }
            }
        }

        if (skip){
            result[H/2] = grid[idx1];
            used[idx1] = true;
            return rec(idx1+1, cnt, false);
        }
    }
    return false;
}


int main() {
    cin >> H >> W;

    for (int i = 0; i < H; i++){
        cin >> grid[i];
    }

    fill(used, used+H, false);
    if (rec(0, 0, H%2==1)){
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }

    return 0;
}

