int main() {
  int H, W;
  while (cin >> H >> W) {
    vector<string> A(H);
    for (int i = 0; i < H; i++) {
      cin >> A[i];
    }
    vector<int> perm(W);
    vector<vector<int>> cands;
    function<void(int, int, int)> dfs = [&](int l, int r, int mask) {
      if (l >= r) {
        cands.push_back(perm);
        return;
      }
      int a;
      for (int i = 0; i < W; i++) {
        if ((mask >> i) & 1) {
          a = i;
          break;
        }
      }
      for (int i = a + 1; i < W; i++) {
        if ((mask >> i) & 1) {
          perm[l] = a;
          perm[r] = i;
          dfs(l + 1, r - 1, mask ^ (1 << a) ^ (1 << i));
        }
      }
    };
    if (W % 2 == 0) {
      dfs(0, W - 1, (1 << W) - 1);
    } else {
      for (int i = 0; i < W; i++) {
        perm[W / 2] = i;
        dfs(0, W - 1, ((1 << W) - 1) ^ (1 << i));
      }
    }
    bool res = false;
    for (auto &perm : cands) {
      map<string, int> mp;
      for (int i = 0; i < H; i++) {
        string s = A[i], t(W, '-');
        for (int j = 0; j < perm.size(); j++) {
          t[j] = s[perm[j]];
        }
        ++mp[t];
      }
      bool ok = true;
      int oddPalindrome = 0;
      for (auto &e : mp) {
        string s = e.first;
        string t = string(s.rbegin(), s.rend());
        if (s != t) {
          ok &= mp[s] == mp[t];
        } else {
          if (mp[s] % 2 != 0) {
            ++oddPalindrome;
          }
        }
      }
      if (ok && oddPalindrome <= 1) {
        res = true;
        break;
      }
    }
    cout << (res ? "YES" : "NO") << endl;
  }
  return 0;
}

