                }
        }

    int id = 0;
    for(i=1; i<=m; ++i)
        if(!used2[i])
        {
            if(id) return;
            id = i;
        }

    if(!id) YES;

    bool match = 1;
    for(k=0; k<p.size(); ++k)
        match &= (a[p[k].first][id] == a[p[k].second][id]);

    if(match) YES;
