int H, W;
char S[12][12];

bool used[12];
bool used_verify[12];
void clear(){
    for(int i = 0; i < 12; i++) used_verify[i] = false;
}
vector<int> buf;

bool verify_pair(int i, int j){
    for(int k = 0; k+1 < H; k += 2){
        int s = buf[k], t = buf[k+1];
        // cout << s << ':' << t << ' ';
        if(S[s][i] != S[t][j]) return false;
        if(S[s][j] != S[t][i]) return false;
    }
    if(H%2 == 1){
        int s = buf[H-1];
        if(S[s][i] != S[s][j]) return false;
    }
    return true;
}

bool verify(){
    // for(int i = 0; i < H; i++) cout << buf[i];
    // cout << endl;
    if(buf.size() != H) return false;
    clear();
    for(int i = 0; i < W; i++){
        for(int j = i+1; j < W; j++){
            if(!used_verify[i] && !used_verify[j] && verify_pair(i, j)) {
                // cout << "unite " << i << ' ' << j << endl;
                used_verify[i] = true; used_verify[j] = true;
            }
        }
    }
    int unused = 0;
    for(int i = 0; i < W; i++){
        if(!used_verify[i]){
            unused++;
            if(!verify_pair(i, i)) return false;
        }
    }
    // cout << unused << endl;
    if(W%2 == 0 && unused > 0) return false;
    if(unused > 1) return false;
    return true;
}

bool ans = false;

void search_pairs(int t, int cnt){
    if(buf.size()+2 > H){
        if(H%2 == 1){
            for(int i = 0; i < H; i++){
                if(!used[i]) {
                    buf.push_back(i);
                    break;
                }
            }
        }
        ans |= verify();
        if(H%2 == 1){
            buf.pop_back();
        }
    }else{
        for(int i = t; i < H; i++){
            if(used[i]) continue;
            for(int j = i+1; j < H; j++){
                if(used[j]) continue;
                used[i] = true; used[j] = true;
                buf.push_back(i); buf.push_back(j);
                search_pairs(i+1, cnt);
                used[i] = false; used[j] = false;
                buf.pop_back(); buf.pop_back();
            }
            if(!used[i]) cnt++;
            if(cnt >= 2) break;
        }
    }
}

