	if(cnt == H || (H%2 && cnt == H-(1-used))){
		if(H%2 && !used) pa.push_back(PII(d, d));
		bool ret = ok();
		if(H%2 && !used) pa.pop_back();
		return ret;
	}
	FOR(i, d+1, H){
		if(rest >> i & 1) continue;
		pa.push_back(PII(d, i));
		bool ret = dfs(d+1, cnt+2, rest|(1<<i)|(1<<d), used);
		pa.pop_back();
		if(ret) return ret;
	}
	if(H%2 && !used){
		pa.push_back(PII(d, d));
		bool ret = dfs(d+1, cnt+1, rest|(1<<d), 1);
		pa.pop_back();
		if(ret) return ret;
	}
	return 0;
}

