const int N = 14;
int n, m, all;
int LOG[1 << N];
bool vis[N];
string s[N], str[N];
int match[N];
bool check() {
	bool use = !(m % 2);
	memset(vis, 0, sizeof(vis));
	for(int i = 0, l = 0, r = n - 1; i < n; i++) {
		if(vis[match[i]] || vis[i]) continue;
		if(match[i] == i) continue;
		str[l] = s[i], str[r] = s[match[i]];
		vis[i] = vis[match[i]] = 1;
		l++, r--;
	}
	rep(i, 0, n) if(i == match[i]) str[n / 2] = s[i];
	memset(vis, 0, sizeof(vis));
	rep(i, 0, m) {
		if(vis[i]) continue;
		bool ok = 0;
		int j;
		for(j = 0; j < m; j++) {
			if(vis[j] || j == i) continue;
			int a, b;
			for(a = 0, b = n - 1; a < n && str[a][i] == str[b][j]; a++, b--);
			if(a == n) {
				ok = 1;
				break;
			}
		}
		if(ok) vis[i] = vis[j] = 1;
		else if(!use) {
			int a, b;
			for(a = 0, b = n - 1; a <= b && str[a][i] == str[b][i]; a++, b--);
			if(a < b) return 0;
			vis[i] = use = 1;
		}
		else return 0;
	}
	return 1;
}
void gao(int id, int msk) {
	if(msk >> id & 1) gao(id + 1, msk);
	if(id == n) {
		if(check())
			throw 1;
		return ;
	}
	msk |= 1 << id;
	for(int j = all ^ msk; j; j -= j & -j) {
		int nxt = LOG[j & -j];
		if(nxt == id) continue;
		match[id] = nxt;
		match[nxt] = id;
		gao(id + 1, msk | 1 << nxt);
	}
}
int main(){
	bool ans = 0;
	for(int i = 0; i < N; i++) LOG[1 << i] = i;
	cin >> n >> m;
	rep(i, 0, n) cin >> s[i];
	all = (1 << n) - 1;
	try{
		if(n & 1) {
			rep(i, 0, n) {
				match[i] = i;
				gao(0, 1 << i);
			}
		} else {
			gao(0, 0);
		}
	} catch(int e) {
		ans = e;
	}
	puts(ans ? "YES" : "NO");
	return 0;
}

