{
	for (int i=0;i<CHARSET;i++)
		if (num[a][i]!=num[b][i])
			return false;
	return true;
}
void dfs(int sz)
{
	if (sz==(n+1)/2+1)
	{
		if (check())
		{
			cout<<"YES";
			exit(0);
		}
		return ;
	}
	if (n&1 && sz==(n+1)/2)
	{
		for (int i=1;i<=n;i++)
		{
			if (visit[i]) continue;
			int cnt=0;
			for (int j=0;j<CHARSET;j++)
				if (num[i][j]&1)
					cnt++;
			if (m&1)
			{
				if (cnt>=2)
					return ;
			}
			else
				return ;
			tmp[sz]=i;
			dfs(sz+1);
			return ;
		}
	}
	for (int i=1;i<=n;i++)
	{
		if (visit[i]) continue;
		for (int j=1;j<=n;j++)
		{
			if (visit[j] || j==i) continue;
			if (same_h(i,j))
			{
				tmp[sz]=i,tmp[n+1-sz]=j;
				visit[i]=visit[j]=1;
				dfs(sz+1);
				visit[i]=visit[j]=0;
			}
		}
	}
}
