const int MAXN = 13;

int R, C;
char S[MAXN][MAXN];

bool palim(string s){
	string s2=s;
	reverse(all(s));
	return s==s2;
}
bool checkCols(){
	//for(int r=0; r<R; r++){
		//printf("%s\n", S[r]);
	//}
	//printf("\n");
	if(C%2){
		string s;
		for(int r=0; r<R; r++) s = s+S[r][C/2];
		if(!palim(s)) return false;
	}
	map<string, int> m;
	for(int c=0; c<C; c++){
		if(C%2 && c==(C/2)) continue;

		string s;
		for(int r=0; r<R; r++) s = s+S[r][c];
		m[s]++;
	}
	for(auto it : m){
		if(palim(it.fst)){
			if(it.snd % 2) return false;
		}else{
			string aux = it.fst;
			reverse(all(aux));
			if(it.snd != m[aux]) return false;
		}
	}
	return true;
}

bool bt(int r){
	//debug(r, R);
	if(r >= R/2){
		return checkCols();
	}
	for(int ri=r+1; ri < R-r; ri++){
		//if(R%2 && ri == (R/2)) continue;
		swap(S[R-r-1], S[ri]);
		if(bt(r+1)) return true;

		swap(S[R-r-1], S[ri]);
	}
	return false;
}

int main(){
	scan(R, C);
	for(int r=0; r<R; r++) scan(S[r]);

	bool ans = false;
	if(C%2){
		for(int c=0; c<C && !ans; c++){
			for(int r=0; r<R; r++) swap(S[r][c], S[r][C/2]);
			if(R%2){
				for(int r=0; r<R && !ans; r++){
					swap(S[r], S[R/2]);
					ans |= bt(0);
					swap(S[r], S[R/2]);
				}
			}else{
				ans |= bt(0);
			}
			for(int r=0; r<R; r++) swap(S[r][c], S[r][C/2]);
		}
	}else{
		if(R%2){
			for(int r=0; r<R && !ans; r++){
				swap(S[r], S[R/2]);
				ans |= bt(0);
				swap(S[r], S[R/2]);
			}
		}else{
			ans |= bt(0);
		}
	}

	printf(ans ? "YES\n" : "NO\n");
}

