bool used[12];
void ck_col() {
    memset(used, 0, sizeof used);
    bool mid_find = !(n&1);
    for (int j = 0; j < m; j++) {
        if (used[j]) continue;
        bool find=false;
        for (int k = j+1; k < m; k++) {
            if (used[k]) continue;
            bool rev=true;
            for (int i = 0; i < n; i++) {
                if (s[i][j] != s[n-1-i][k]) {rev=false;break;}
            }
            if (rev) {
                find = true;
                used[j]=used[k]=true;
                break;
            }
        }
        if (!find) {
            if (mid_find) return;
            for (int i = 0; i < n; i++) {
                if (s[i][j] != s[n-1-i][j]) return;
            }
            mid_find = true;
            used[j] = true;
        }
    }
    cout<<"YES"<<endl; exit(0);
}
void enume(int msk, int L) {
    if (msk == FULL) {
        ck_col();
    }
    int i=0;
    while (msk&(1<<i)) {
        i++;
    }
    cpy_r(L, i); msk |= 1<<i; i++;
    for (int k = i; k < n; k++) {
        if (msk & (1<<k)) continue;
        cpy_r(n-1-L, k);
        enume(msk|(1<<k), L+1);
    }
}

