pair<vector<vector<int>>,int> organize(vector<map<char, int>> const &cnt, int upto) {
    vector<int> gs(upto, -1);
    int g = 0;
    for (int i = 0; i < upto; i++) {
        bool exists = false;
        if (gs[i] != -1) continue;
        for (int j = i+1; j < upto; j++) {
            if (gs[j] != -1) continue;
            if (cnt[i] == cnt[j]) {
                exists = true;
                gs[i] = gs[j] = g;
            }
        }
        if (exists) g++;
    }

    vector<vector<int>> gv(g);
    for (int i = 0; i < upto; i++) {
        if (gs[i] != -1) gv[gs[i]].push_back(i);
    }

    auto odd_p = [](auto const &x){ return x.size() & 1; };
    if (count_if(gv.begin(), gv.end(), odd_p) > 1 || count(gs.begin(), gs.end(), -1) > 1)
        return make_pair(gv, -1);

    return make_pair(gv, g);
}

class groupings_generator {
    private:
        vector<vector<int>> base;
        vector<string> lines;
        vector<vector<int>> curr;

        function<bool(int, int)> cmp = [=](int l, int r) {
            return lines[l] < lines[r];
        };

        void calc_curr() {
            curr.clear();
            for (auto const &x: base) {
                if (x.size() == 2) {
                    curr.push_back(x);
                } else {
                    for (size_t i = 0; i < x.size()/2; i++) {
                        curr.emplace_back();
                        curr.back().push_back(x[i*2]);
                        curr.back().push_back(x[i*2+1]);
                    }
                }
            }
        }

    public:
        groupings_generator(vector<string> const &lines, vector<vector<int>> const &orig) : base(orig), lines(lines) {
            for (auto &x: base) sort(x.begin(), x.end(), cmp);
            calc_curr();
        }

        vector<vector<int>> const &get_curr() { return curr; }

        bool gen_next() {
            bool flag = false;
            for (int i = base.size()-1; i >= 0; i--) {
                auto &x = base[i];
                bool ind_pair;
                do {
                    if (!next_permutation(x.begin(), x.end(), cmp)) {
                        break;
                    }

                    ind_pair = true;
                    for (size_t i = 0; i < x.size()/2; i++) {
                        if (cmp(x[i*2+1], x[i*2])) {
                            ind_pair = false; break;
                        }
                    }
                    if (ind_pair) flag = true;
                } while (!ind_pair);
                if (flag) break;
            }
            calc_curr();
            return flag;
        }
};

