bool debug=false;

int n,m;
string s[15];
string t[15];

void func(){
	map<string,int> cnt;
	for(int i=0;i<m;i++){
		string s="";
		for(int j=0;j<n;j++){
			if(t[j][i]=='*'){
				s+=t[n-1-j][i];
			}else{
				s+=t[j][i];
			}
		}

		string ano=s;
		reverse(ano.begin(),ano.end());
		if(ano>=s){
			cnt[s]++;
		}else{
			cnt[ano]--;
		}
	}

	bool odd=false;
	for(map<string,int>::iterator it=cnt.begin();it!=cnt.end();it++){
		if(it->second==0) continue;
		string a=it->first;
		string b=a;
		reverse(b.begin(),b.end());

		if(a!=b) return;
		if(it->second%2==0) continue;
		if(odd) return;
		odd=true;
	}

	puts("YES");
	exit(0);
}
void dfs(int mask,int pos){
	if(mask==0){
		func();
		return;
	}

	int p=0;
	while(~mask>>p&1){
		p++;
	}

	t[pos]=s[p];
	for(int i=p+1;i<n;i++){
		if((mask>>i)&1){
			t[n-1-pos]=s[i];

			dfs(mask^(1<<p)^(1<<i),pos+1);
		}	
	}
}
int main(int argc,char* argv[]){
	scanf("%d%d",&n,&m);
	for(int i=0;i<n;i++){
		cin>>s[i];
	}

	if(n%2==1){
		s[n]=string(m,'*');
		n++;
	}

	dfs((1<<n)-1,0);

	puts("NO");
	return 0;
}

