int h, w;
char b[12][12];

bool vertcheck() {
    map<vector<char>, int> m;
    REP(i,w) {
        vector<char> v;
        REP(j,h) {
            v.push_back(b[j][i]);
        }
        sort(v.begin(), v.end());
        m[v]++;
    }
    int odd = 0;
    vector<char> o;
    for (auto p: m) {
        if (p.second % 2 == 1) {
            odd++;
            o = p.first;
        }
    }
    if (w % 2 == 1 && odd == 1) {
        return true;
    }
    if (odd == 0) return true;
    return false;
}

bool horizcheck() {
    map<vector<char>, int> m;
    REP(i,h) {
        vector<char> v;
        REP(j,w) {
            v.push_back(b[i][j]);
        }
        sort(v.begin(), v.end());
        m[v]++;
    }
    int odd = 0;
    for (auto p: m) {
        if (p.second % 2 == 1) {
            odd++;
        }
    }
    if (h % 2 == 1 && odd == 1) {
        return true;
    }
    if (odd == 0) return true;
    return false;
}


