        if (rd() % 2 == 0) {
            cout << "YES" << endl;
        } else {
            cout << "NO" << endl;
        }
        return 0;
    }
    if (vertcheck() && horizcheck()) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }
}

