int main()
{

    bool aa[15],bb[15];
    int n,m,ans2[13][400],sum=0,sum1=0,ans1[13][400],t,flag=1;
    memset(ans1,0,sizeof(ans1));
    memset(ans2,0,sizeof(ans2));
    cin>>n>>m;
    char kk[13][100];
    for(int i=0;i<n;i++)
    {
        cin>>kk[i];
        for(int p=0;p<m;p++)
            ans1[i][kk[i][p]]++;
    }
    for(int i=0;i<m;i++)
    {
        for(int p=0;p<n;p++)
            ans2[i][kk[p][i]]++;
    }
    for(int i=n-1;i>=0;i--)
    {
        for(int p=i-1;p>=0;p--)
        {
            for(t='a';t<='z';t++)
                if(ans1[i][t]!=ans1[p][t])break;
            if(t==('z'+1))
            {
                sum++;
                aa[i]=true;
                aa[p]=true;
                //cout<<i<<" "<<p<<endl;
            }
        }
    }
    for(int i=m-1;i>=0;i--)
    {
        for(int p=i-1;p>=0;p--)
        {
            for(t='a';t<='z';t++)
                if(ans2[i][t]!=ans2[p][t])break;
            if(t==('z'+1))
            {
                sum1++;
                bb[i]=true;
                bb[p]=true;
            }
        }
    }
    int poo=0,fii=0;
    for(int i=m-1;i>=0;i--)
        if(!bb[i])poo++;
    for(int i=n-1;i>=0;i--)
        if(!aa[i])fii++;
    if(poo>1||fii>1)flag=0;
    if(poo==1&&fii==1)
    {
        for(int i=m-1;i>=0;i--)
            if(!bb[i])poo=i;
        for(int i=n-1;i>=0;i--)
            if(!aa[i])fii=i;
        if(poo==m/2+1||fii==n/2+1)flag=1;

    }
    if(sum>=n/2&&sum1>=m/2&&flag)cout<<"YES";
    else cout<<"NO";
    return 0;
}

