int H, W;
vector<vector<int> > S;

int main()
{
    cin >> H >> W;

    for (int i = 0; i < H; i++)
    {
        for (int j = 0; j < W; j++)
        {
            unsigned char hoge;
            cin >> hoge;
            S.resize(H);
            S[i].push_back((unsigned int)hoge);
        }
    }


    int rowPattern = 1;
    for (int i = H; i > 0;)
    {
        if (i == 1)
        {
            break;
        }
        else if (i % 2)
        {
            rowPattern *= i;
            i--;
        }
        else
        {
            rowPattern *= (i - 1);
            i = i - 2;
        }
    }

    for (int pp = 0; pp < rowPattern; pp++)
    {
        int p = pp;
        int center = -1;
        vector<vector<int> > Scopy = S;
        vector<vector<int> > Snew(H);

        if (H%2)
        {
            center = p % H;
            p = p / H;
            Snew[(int)(H / 2)] = Scopy[center];
            Scopy.erase(Scopy.begin() + center);
        }

        int pairNum = H / 2;
        for (int i = 0; i < pairNum; i++)
        {
            int tmp = p % (2 * (pairNum - i) - 1);
            p /= (2 * (pairNum - i) - 1);

            Snew[i] = Scopy[0];
            Scopy.erase(Scopy.begin());
            Snew[H - 1 - i] = Scopy[tmp];
            Scopy.erase(Scopy.begin() + tmp);
        }

        vector<vector<int> > columns(W);
        for (int i = 0; i < H; i++)
        {
            for (int j = 0; j < W; j++)
            {
                columns[j].push_back(Snew[i][j]);
            }
        }

        int yuuyo = 0;
        while (!columns.empty())
        {
            int matchedColumn = -1;
            for (int i = 1; i < columns.size(); i++) // 0列目とi列目を比較
            {
                bool matchedFlag = true;
                for (int j = 0; j<(H+1)/2; j++)
                {
                    if (columns[0][j] != columns[i][H-1-j])
                    {
                        matchedFlag = false;
                        break;
                    }
                }

                if (matchedFlag)
                {
                    matchedColumn = i;
                    break;
                }
            }

            if (columns.size() %2 && matchedColumn < 0)
            {
                columns.erase(columns.begin());
                continue;
            }

            if (!(columns.size()%2) && matchedColumn < 0)
                break;

            columns.erase(columns.begin() + matchedColumn);
            columns.erase(columns.begin());
        }
        if (columns.empty())
        {
            cout << "YES\n";
            return 0;
        }
    }

    cout << "NO\n";
    return 0;
}

