void dfs(int x){
	if (x>=n){
		memset(used,0,sizeof used);
		for (int i=1;i<=m;++i)
			if (!used[i]){
				for (int j=i+1;j<=m;++j)
					if (!used[j]){
						bool fl=1;
						for (int k=1;k<=n;++k)
							if (s[k][i]!=s[swp[k]][j]){
								fl=0; break;
							}
						if (fl){used[i]=used[j]=1; break;}
					}
			}
		int tmp=0;
		for (int i=1;i<=m;++i) if (!used[i]){if (tmp) return; tmp=i;}
		if (!tmp){puts("YES"); exit(0);}
		if (tmp&&(m&1)){
			for (int i=1;i<=n;++i)
				if (s[i][tmp]!=s[swp[i]][tmp]) return;
			puts("YES"); exit(0);
		}
		return;
	}
	if (n&1){
		bool fl=1;
		for (int i=1;i<=n;++i) if (swp[i]==i) fl=0;
		for (int i=1;i<=n;++i)
			if (!swp[i]){
				if (fl){swp[i]=i; dfs(x+1); swp[i]=0;}
				for (int j=i+1;j<=n;++j)
					if (!swp[j]){
						swp[i]=j; swp[j]=i;
						dfs(x+2);
						swp[i]=swp[j]=0;
					}
				break;
			}
	}
	else{
		for (int i=1;i<=n;++i)
			if (!swp[i]){
				for (int j=i+1;j<=n;++j)
					if (!swp[j]){
						swp[i]=j; swp[j]=i;
						dfs(x+2);
						swp[i]=swp[j]=0;
					}
			}
	}
}

