        int start = -1;
        // 使っていない一番左の要素は確定
        for(int i = 0; i < W; i++){
            if(used[i]) continue;
            start = i;
            break;
        }
        used[start] = true;
        for(int i = start + 1; i < W; i++){
            if(used[i]) continue;
            used[i] = true;
            ps[depth] = pii(start, i);
            if(perm(depth + 1))
                return true;
            used[i] = false;
        }
        used[start] = false;
    }
    return false;
}

bool solve(){
    if(W % 2){
        for(int i = 0; i < W; i++){
            used[i] = true;
            if(perm(0)){
                return true;
            }
            used[i] = false;
        }
        return false;
    }
    else{
        return perm(0);
    }
}

int main(){
    cin >> H >> W;
    for(int i = 0; i < H; i++) cin >> S[i];
    if(solve()){
        cout << "YES" << endl;
    }
    else{
        cout << "NO" << endl;
    }

    return 0;
}

