bool dfs(const vector<vi> &G,int v,vector<bool> &visit, vector<int> &match,vector<int> &level){
    visit[v]=true;
    REP(i,G[v].size()){
        int dst=G[v][i];
        int w=match[dst];
        if(w==-1 || (!visit[w] && level[v] < level[w] && dfs(G,w,visit,match,level))){
            match[v]=dst;
            match[dst]=v;
            return true;
        }
    }
    return false;
}
int bipartite_matching(const vector<vi> &G){
    vector<int> match(G.size(), -1);
    for(int res = 0;;){
        vector<int> level(G.size(),-1);
        queue<int> que;
        REP(i,G.size()){
            if(match[i]==-1){
                que.push(i);
                level[i]=0;
            }
        }
        while(!que.empty()){
            int v=que.front();que.pop();
            REP(i,G[v].size()){
                int dst=G[v][i];
                int w=match[dst];
                if(w != -1 && level[w]<0){
                    level[w]=level[v]+1;
                    que.push(w);
                }
            }
        }
        vector<bool> visit(G.size());
        int d=0;
        REP(v,G.size()){
            if(match[v]==-1&&dfs(G,v,visit,match,level))d++;
        }
        if(d==0)return res;
        res+=d;
    }
}

