std::vector<std::vector<int>> all_pairs(std::vector<int> org) {
    std::vector<std::vector<int>> ret;
    if (org.size() == 0) {
        return ret;
    }

    int is_even = org.size() % 2 == 0 ? 1 : 0;

    do {
        bool use = true;
        for (int i = 0; i < org.size() - 1; i += 2) {
            if (org[i] > org[i+1]) {
                use = false;
                break;
            }
        }
        if (use) {
            for (int i = 0; i < org.size() - 3; i += 2) {
                if (org[i] > org[i+2]) {
                    use = false;
                    break;
                }
            }
        }
        if (use) {
            ret.push_back(org);
        }
    } while (std::next_permutation(org.begin() + is_even, org.end()));

    return ret;
}

bool check(std::vector<int> pair) {
    bool used[20] = {};
