                // cout << "unite " << i << ' ' << j << endl;
                used_verify[i] = true; used_verify[j] = true;
            }
        }
    }
    int unused = 0;
    for(int i = 0; i < W; i++){
        if(!used_verify[i]){
            unused++;
            if(!verify_pair(i, i)) return false;
        }
    }
    if(W%2 == 0 && unused > 0) return false;
    if(unused > 1) return false;
    return true;
}

bool ans = false;

void search_pairs(int t, int cnt){
    if(buf.size()+2 > H){
        if(H%2 == 1){
            for(int i = 0; i < H; i++){
                if(!used[i]) {
                    buf.push_back(i);
                    break;
                }
            }
        }
        ans |= verify();
        if(H%2 == 1){
            buf.pop_back();
        }
    }else{
        for(int i = t; i < H; i++){
            if(used[i]) continue;
            for(int j = i+1; j < H; j++){
                if(used[j]) continue;
                used[i] = true; used[j] = true;
                buf.push_back(i); buf.push_back(j);
                search_pairs(t, cnt);
                used[i] = false; used[j] = false;
                buf.pop_back(); buf.pop_back();
            }
            if(!used[i]) cnt++;
            if(cnt >= 2) break;
        }
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << setprecision(10) << fixed;
    cin >> H >> W;
    for(int i = 0; i < H; i++){
        for(int j = 0; j < W; j++){
            cin >> S[i][j];
        }
    }
    search_pairs(0, 0);
    cout << (ans?"YES":"NO") << endl;
}

