int same(int ii, int jj)
{
	int i;
	for(i=0; i<W; i++){
		if(S[ii][as1[i]] != S[jj][as1[W-1-i]])
			return 0;
	}
	return 1;
}

void srch2(int dep)
{
	int i;
	if(suc == 1)
		return ;
	if(dep==H){
		suc = 1;
		return ;
	}
	if(dep%2==0){
		if(H%2==1 && dep==H-1){
			if(same(as2[dep], as2[dep]) == 1)
				srch2(dep+1);
		}
		else	
			srch2(dep+1);
		return ;
	}
	for(i=dep; i<H; i++){
		swap(as2[i], as2[dep]);
		if(sm_r[as2[dep]][as2[dep-1]] == 1){
			if(same(as2[dep], as2[dep-1]) == 1)
				srch2(dep+1);
		}
		if(suc == 1)
			return ;
		swap(as2[i], as2[dep]);
	}
}

void srch(int dep)
{
	int i;
	if(suc == 1)
		return ;
	if(dep==W){
		for(i=0; i<H; i++)
			as2[i] = i;
		for(i=0; i<W; i++){
			if(i%2==0){
				as1[i/2] = as[i];
			}
			else
				as1[W-1-i/2] = as[i];
		}
		srch2(0);
		return ;
	}
	if(dep%2==0){
		if(W%2==1 && dep==W-1){
			if(sm1[as[dep]]==1)
				srch(dep+1);
		}
		else	
			srch(dep+1);
		return ;
	}
	for(i=dep; i<W; i++){
		swap(as[i], as[dep]);
		if(sm_c[as[dep]][as[dep-1]] == 1)
			srch(dep+1);
		if(suc == 1)
			return ;
		swap(as[i], as[dep]);
	}
}

void solve()
{
	int i, j, k;
	for(i=0; i<W; i++){
		for(j=0; j<W; j++){
			int a1[26], a2[26];
