		}
		int tmp=0;
		for(k=0; k<26; k++){
			if(a1[k]%2==1)
				tmp ++;
		}
		if(tmp<=1)
			sm2[i] = 1;
		else
			sm2[i] = 0;
	}
	suc = 0;
	for(i=0; i<W; i++)
		as[i] = i;
	srch(0);
	if(suc)
		printf("YES\n");
	else
		printf("NO\n");
}

