typedef long long ll;


int H, W; 
vector<string> s;
vector<pair<int, int>> p;
int used[14];


bool func(int pos, int c) {
	if (c >= H/2) {
		int cen = 0;
		if (H & 1) {
			for (auto i : p) {
				if (i.first == cen || i.second == cen) cen++;
			}
		}
		bool u[14] = {};
		for (int i = 0; i < W; i++) {
			if (u[i]) continue;
			for (int j = i + 1; j < W; j++) {
				if (u[j]) continue;
				bool flag = true;
				for (auto t : p) {
					int a = t.first, b = t.second;
					flag &= s[a][i] == s[b][j] && s[a][j] == s[b][i];
				}
				if (H & 1) flag &= s[cen][i] == s[cen][j];
				if (flag) {
					u[i] = u[j] = true;
					break;
				}
			}
		}

		int cnt = 0;
		for (int i = 0; i < W; i++) cnt += !u[i];
		if (cnt == 0) {
			return true;
		}
		if (cnt == 1 && W & 1) {
			for (int i = 0; i < W; i++) {
				if (u[i]) continue;
				bool flag = true;
				for (auto t : p) {
					flag &= s[t.first][i] == s[t.second][i];
				}
				if (flag) {
					return true;
				}
			}
		}

		return false;
	}

	if (used[pos] != -1) return func(pos + 1, c);

	used[pos] = pos;

	bool ret = false;
	for (int i = pos + 1; i < H; i++) {
		if (used[i] != -1) continue;
		used[i] = pos;
		p.push_back({ pos, i });

		ret |= func(pos + 1, c + 1);

		p.pop_back();
		used[i] = -1;
		if (ret) break;
	}

	used[pos] = -1;
	return ret;
}

