bool chk()
{
	for(int i=1;i<=n;i++)
		for(int j=1;j<=m;j++)
		{
			int nowx=res1[i],nowy=res2[j];
			b[i][j]=a[nowx][nowy];
		}
	for(int i=1;i<=n;i++)
		for(int j=1;j<=m;j++)
		{
			int fx=i,fy=j,tx=n-i+1,ty=m-j+1;
			if(b[fx][fy]!=b[tx][ty])
				return false;
		}
	return true;
}

bool f2(int t1,int t2)
{
	for(int i=1;i<=26;i++)
		if(have2[t1][i]!=have2[t2][i])
			return false;
	return true;
}

bool dfs2(int p)
{
	if(p-1>m/2)
	{
		int r=p-1;
		if(!f2(res2[r],res2[m-r+1]))
			return false;
	}
	if(p>m)
		return chk();
	for(int i=1;i<=m;i++)
	{
		if(used2[i]) continue;
		used2[i]=true;
		res2[p]=i;
		if(dfs2(p+1)) return true;
		used2[i]=false;
	}
	return false;
}

bool f1(int t1,int t2)
{
	for(int i=1;i<=26;i++)
		if(have1[t1][i]!=have1[t2][i])
			return false;
	return true;
}

bool dfs1(int p)
{
	if(p-1>n/2)
	{
		int r=p-1;
		if(!f1(res1[r],res1[n-r+1]))
			return false;
	}
	if(p>n)
		return dfs2(1);
	for(int i=1;i<=n;i++)
	{
		if(used1[i]) continue;
		used1[i]=true;
		res1[p]=i;
		if(dfs1(p+1)) return true;
		used1[i]=false;
	}
	return false;
}

