int n,m;
int get(){
    int res=0;
    forn(i,n/2)
        forn(j,m)
            if(a[i][j]!=a[n-i-1][m-j-1])
                res++;
    if(n&1)forn(j,m/2)if(a[n/2][j]!=a[n/2][m-j-1])res++;
    return res;
}
void sr(int x,int y){
    a[x].swap(a[y]);
}
void sc(int x,int y){
    forn(i,n)swap(a[i][x],a[i][y]);
}
int otzhig(){
    uniform_real_distribution<> kok(0,1);
    double t0=20;//2000
    double temp=t0;

    int cur=get();
    int ans=cur;

    uniform_int_distribution<> disrow(0,n-1);
    uniform_int_distribution<> discol(0,m-1);
    while(temp*20*max(n,m)>=1){//1e-6
        forn(i,n)tmp[i]=a[i];
        // dbg(temp,temp*20*(n+m),cur);
        forn(i,temp*20*n){
            int x=disrow(rng);
            int y=disrow(rng);
            sr(x,y);
        }
        forn(i,temp*20*m){
            int x=discol(rng);
            int y=discol(rng);
            sc(x,y);
        }

        int pot=get();
        upn(ans,pot);
        if(cur>pot)cur=pot;
        else{
            double go=exp(-(pot-cur)/temp);
            if(kok(rng)<=go)cur=pot;
            else{//restore
                forn(i,n)a[i]=tmp[i];
            }
        }
        temp*=0.9995;
    }
    // dbg(cx,cy,cur,temp);
    return ans;
}

int32_t main(){
    cin>>n>>m;
    forn(i,n)cin>>a[i];
    int ans=get();
    upn(ans,otzhig());
    // upn(ans,otzhig());
    // upn(ans,otzhig());
    dbg(ans);
    if(ans)cout<<"NO\n";
    else cout<<"YES\n";

    return 0;
}

