using namespace std;

typedef long long ll;

string a[12];
int pairs[12];
int h, w;

bool check_columns();
bool make_even();
bool make_pair_of_lines(int);

bool check_columns(){
    string b[12];
    for(int i=0;i<h;i++){
        if(b[pairs[i]] == ""){
            b[pairs[i]] = a[i];
        }else{
            b[h-1-pairs[i]] = a[i];
        }
    }

    bool center = (w % 2 == 0);
    bool used[w];
    fill(used, used+w, false);

    for(int j=0;j<w;j++){
        if(used[j]) continue;
        used[j] = true;
        bool same = false;

        for(int jj=0;jj<w;jj++){
            if(used[jj]) continue;

            same = true;
            for(int i=0;i<h;i++){
                if(b[i][j] != b[h-1-i][jj]){
                    same = false;
                    break;
                }
            }
            if(same){
                used[jj] = true;
                break;
            }
        }

        if(!same){
            if(center) return false;
            else center = true;
        }
    }

    return true;
}

bool make_even(){
    h++;
    for(int i=0;i<h-1;i++){
        a[h-1] = a[i];
        pairs[h-1] = -1;
        if(make_pair_of_lines(0)) return true;
    }
    return false;
}

bool make_pair_of_lines(int paired_line){
    if(h % 2) return make_even();

    if(paired_line == h) return check_columns();

    int pair_line_first = -1;
    for(int i=0;i<h;i++){
        if(pairs[i] == -1){
            if(pair_line_first == -1){
                pair_line_first = i;
                pairs[pair_line_first] = paired_line/2;
                break;
            }
        }
    }

    for(int ii=0;ii<h;ii++){
        if(pairs[ii] == -1){
            pairs[ii] = paired_line/2;
            if(make_pair_of_lines(paired_line+2)) return true;
            pairs[ii] = -1;
        }
    }

    pairs[pair_line_first] = -1;

    return false;
}

int main(){
    cin >> h >> w;
    for(int i=0;i<h;i++) cin >> a[i];

    fill(pairs, pairs+h, -1);
    cout << (make_pair_of_lines(0)?"YES":"NO") << endl;
    return 0;
}

