#include <bits/stdc++.h>
#include <boost/range/irange.hpp>
#include <boost/range/adaptors.hpp>

using namespace std;
using namespace boost::adaptors;
using uint = unsigned int;
using ll = long long int;
using ull = unsigned long long int;


int main() {
    ll H, W;
    cin >> H >> W;
    vector<vector<char>> cs(H, vector<char>(W, 0));
//    本問はマッチング問題として解ける
//    （証明略）
//    Theorem 1:
//    各行に対し，「ペア」が存在しなければ，return falseでOK
//    「ペア」とは，以下のように定められるマッチングが0であるようなiが存在しないことを言う．

//    ただし，Hが奇数のとき，1行だけ，自分自身をペアとすることを許容する．

//    2つのstringが与えられた時，pair(s1[i], s2[i])に対して，pair(s2[j], s1[j])となるjをマッチングと呼ぶ
//    これを全ての行ペアについて探索する．

//    最大マッチングが，Wであるとき，return true, そうでないとき return false

//    まずマッチングの探索から．
    for (auto &&h: boost::irange(0LL, H)) {
        for (auto &&w: boost::irange(0LL, W)) {
            char c;
            cin >> c;
            cs.at(h).at(w) = c;
        }
    }
    vector<bool> used(H, false);
    vector<vector<vector<ll>>> all_matching{};
    bool self_matching_available_H = (H % 2 == 1); // Hが奇数のとき，self-matchingが1度だけ許容される
    for (auto &&h1: boost::irange(0LL, H)) {
        if (!used.at(h1)) {
            used.at(h1) = true;
            bool h1_used = false;
            for (auto &&h2: boost::irange(0LL, H)) {
                vector<vector<ll>> matching(W, vector<ll>{});
                if (!used.at(h2)) {
                    for (auto &&w1: boost::irange(0LL, W)) {
                        char c1{cs.at(h1).at(w1)}, c2{cs.at(h2).at(w1)};
                        for (auto &&w2: boost::irange(0LL, W)) {
                            if (cs.at(h1).at(w2) == c2 && cs.at(h2).at(w2) == c1) {
                                matching.at(w1).emplace_back(w2);
                            }
                        }
                    }
                }
                //            ここでh2を許すかどうかを決める
                bool h2_is_pair = true;
                for (auto &&w: boost::irange(0LL, W)) {
                    if (matching.at(w).empty()) {
                        h2_is_pair = false;
                        break;
                    }
                }
                if (h2_is_pair) {
                    h1_used = true;
                    used.at(h2) = true;
                    all_matching.emplace_back(matching);
//                    cout << h1 << " " << h2 << endl;
                }
            }
            if (!h1_used) {
                if (self_matching_available_H) {
                    vector<vector<ll>> matching(W, vector<ll>{});
                    for (auto &&w1: boost::irange(0LL, W)) {
                        char c{cs.at(h1).at(w1)};
                        for (auto &&w2: boost::irange(0LL, W)) {
                            if (cs.at(h1).at(w2) == c) {
                                matching.at(w1).emplace_back(w2);
                            }
                        }
                    }
                    all_matching.emplace_back(matching);
                    self_matching_available_H = false;
                } else {
                    cout << "NO" << endl;
                    return 0;
                }
            }
        }
    }

    bool self_matching_available_W = (W % 2 == 1);
    for (auto &&w: boost::irange(0LL, W)){
        vector<bool> matching_and(W, true);
        for (auto &&i: boost::irange(0LL, (ll)all_matching.size())){ // == H
            vector<bool> matching(W, false);
            for (ll j: all_matching.at(i).at(w)){
                matching.at(j) = true;
            }
            for (auto &&_w: boost::irange(0LL, W)){
                matching_and.at(_w) = matching_and.at(_w) && matching.at(_w);
            }
        }
        bool found_good_matching = false;
        for (auto &&_w: boost::irange(0LL, W)){
            if (_w != w && matching_and.at(_w)){
                found_good_matching = true;
                break;
            }
        }
        if (! found_good_matching){
            if (self_matching_available_W && matching_and.at(w)){
                self_matching_available_W = false;
            } else {
                cout << "NO" << endl;
                return 0;
            }
        }
    }
    cout << "YES" << endl;
    return 0;
}

