int H, W;
std::string A[12];
int col[12];
bool used[12];

bool f(int s, int i){
    if(i == W / 2){
        int n = 0;

        for(int j=0;j<H;++j){
            if(used[j]){
                continue;
            }

            for(int k=j+1;k<H;++k){
                if(used[k]){
                    continue;
                }

                bool rev = true;

                for(int l=0;l<W;++l){
                    if(A[j][col[l]] != A[k][col[W - 1 - l]]){
                        rev = false;
                        break;
                    }
                }

                if(rev){
                    used[j] = used[k] = true;
                    break;
                }
            }

            unless(used[j]){
                n += 1;
            }
        }

        if(H % 2 == 0){
            return n == 0;
        }
        return n == 1;
    }

    int a = __builtin_ctz(~s);
    col[i] = a;

    for(int b=a+1;b<W;++b){
        if(s >> b & 1){
            continue;
        }

        col[W - 1 - i] = b;

        if(f(s | (1 << a) | (1 << b), i + 1)){
            return true;
        }
    }

    return false;
}

