bool is_palin(string s) {
	sort(s.begin(), s.end());
	for (int i = 0; i + 1 < sz(s); i += 2) {
		if (s[i] != s[i + 1]) return false;
	}
	return true;
}

bool is_rev(string u, string v) {
	for (int i = 0, j = sz(v) - 1; i < sz(u); ++i, --j)
		if (u[i] != v[j]) return false;
	return true;
}

string col[N];

bool chk[N];
bool f_check() {
	rep(j, 0, m) {
		if (chk[j]) continue;
		rep(t, j + 1, m) if (!chk[t] && is_rev(col[j], col[t])) {
			chk[j] = chk[t] = true;
			break;
		}
		if (!chk[j]) return false;
	}
	return true;
}

bool check() {
	rep(j, 0, m) {
		col[j] = "";
		rep(i, 0, n) col[j] += s[p[i]][j];
	}

	if (m & 1) {
		rep(j, 0, m) {
			if (!is_palin(col[j])) continue;
			rep(t, 0, m) chk[t] = false;
			chk[j] = true;
			if (f_check()) return true;
		}
	} else {
		return f_check();
	}
	return false;
}

int u, v;

void go() {
	int lhs = -1;
	rep(i, 0, n) if (!chosen[i]) {
		lhs = i; break;
	}

	if (lhs == -1) {
		if (check()) {
			puts("YES");
			exit(0);
		}
		return;
	}

	rep(i, lhs + 1, n) if (!chosen[i]) {
		p[u++] = lhs;
		p[v--] = i;
		chosen[lhs] = chosen[i] = true;
		go();
		--u; ++v;
		chosen[lhs] = chosen[i] = false;
	}

}

void solve() {
	cin >> n >> m;
	rep(i, 0, n) cin >> s[i];
	rep(i, 0, n) p[i] = -1;
	u = 0; v = n - 1;

	if (n & 1) {
		rep(i, 0, n) {
			chosen[i] = true;
			p[n / 2] = i;
			go();
			p[n / 2] = -1;
			chosen[i] = false;
		}
	} else
		go();
	puts("NO");
}



