                    }
                }
                if (!bb || center) {
                    comp = false;
                    break;
                } else {
                    center = true;
                    break;
                }
            } else {
                break;
            }
        }
        if (comp) {
            sleep(1);
            ok = true;
            break;
        }
    }
    if (ok) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }
}

