        for(int i=0;i<h;i++){
            swap(s[i],s[h-1]);
            isok=isok || solve(0,s);
            swap(s[i],s[h-1]);
        }
    }else{
        isok=solve(0,s);
    }
    cout<<(isok? "YES" : "NO")<<endl;
    return 0;
}

