            t.push_back(i);
        }
        for(int i=1;i<t.size();i++){
            x.push_back(t[0]);
            y.push_back(t[i]);
            setPair(now|(1<<t[0])|(1<<t[i]));
            x.pop_back();
            y.pop_back();
        }
    }
    return;
}

