	cout.tie(0);

	ll h, w;
	cin >> h >> w;
	vector<string> s(h);
	REP(i, h)cin >> s[i];
	Array used(20, 0);
	vector<string> t(h);
	auto check = [&]() {
		vector<string> tmp(w);
		REP(i, h)REP(j, w)tmp[j].push_back(t[i][j]);
		while (tmp.size() > 1) {
			bool flag = false;
			reverse(all(tmp.back()));
			REP(i, tmp.size() - 1) {
				if (tmp[i] == tmp.back()) {
					flag = true;
					tmp.pop_back();
					swap(tmp[i], tmp.back());
					tmp.pop_back();
					break;
				}
			}
			if (flag == false && tmp.size() % 2 == 1)tmp.pop_back();
			else if (flag == false)return false;
		}
		return true;
	};
	auto solve = [&](auto solve, ll a, ll b) {
		if (a == h)return check();
		if (used[a] == 1)return solve(solve, a + 1, b);
		t[b] = s[a];
		if (h % 2 == 1 && b == h / 2)return check();
		used[a] = 1;
		REP(i, h) {
			if (used[i] == 0) {
				used[i] = 1;
				t[h - b - 1] = s[i];
				if (solve(solve, a + 1, b + 1))return true;
				used[i] = 0;
			}
		}
		used[a] = 0;
		return false;
	};
	if (solve(solve, 0, 0) == true)cout << "YES" << "\n";
	else {
