    int H = field.size();
    int W = field[0].size();

    vector<int> v(W, -1);
    vector<bool> used(W, false);

    FOR(i, 0, pv.size()) {
        v[i] = pv[i].first;
        v[v.size() - 1 - i] = pv[i].second;
        used[pv[i].first] = true;
        used[pv[i].second] = true;
    }

    FOR(i, 0, W) {
        if (v[i] == -1) {
            FOR(j, 0, used.size()) {
                if (not used[j]) {
                    v[i] = j;
                }
            }

            map<char, int> m;
            FOR(y, 0, H) {
                m[field[y][v[i]]]++;
            }
            int n = 0;
            FOE(p, m) {
                n += (p.second % 2 != 0);
            }
            if (n >= 2) {
                return false;
            }
            if (H % 2 == 0 and n >= 1) {
                return false;
            }

            break;
        }
    }

    vector<int> used2(H, false);
    FOR(y1, 0, H) {
        if (used2[y1]) { continue; }

        FOR(y2, y1 + 1, H) {
            if (used2[y2]) { continue; }

            bool ok = true;
            FOR(x, 0, W) {
                ok &= field[y1][v[x]] == field[y2][v[W - 1 - x]];
            }
            if (ok) {
                used2[y1] = true;
                used2[y2] = true;
                break;
            }
        }
    }

    int num = 0;
