int valid(vector<string> s1,vector<string> s2){
  map<string,int> S;
  for(int i=0;i<h;i++) reverse(s2[i].begin(),s2[i].end());
  for(int i=0;i<h;i++) S[s1[i] + s2[i]]++;

  int cnt = 0;
  for(auto p:S) {
    string s = p.first;
    string tmp = s;
    reverse(s.begin(),s.end());
    if(s == tmp) cnt += S[s] % 2;
  }

  for(auto p:S){
    string s = p.first;
    string tmp = s;
    reverse(s.begin(),s.end());
    if(S[s] == 0) return 0;
    S[s]--;
  }

  if(cnt > 1) return 0;
  if(h%2 == 0 && cnt) return 0;
  return 1;
}

