bool check(const vector<string>& s)
{
    int h = s[0].size();
    int w = s.size();

    map<string, vector<int> > index;
    for(int i=0; i<h; ++i){
        string t(w, ' ');
        for(int j=0; j<w; ++j)
            t[j] = s[j][i];
        index[t].push_back(i);

        reverse(t.begin(), t.end());
        index[t].push_back(i);
    }

    bool isSame = false;
    for(auto& p : index){
        auto& v = p.second;
        if(v.size() % 2 != 0)
            return false;

        sort(v.begin(), v.end());
        v.erase(unique(v.begin(), v.end()), v.end());

        if(v.size() % 2 != 0){
            if(isSame)
                return false;
            isSame = true;
        }

    }
    return true;
}

bool solve(const vector<string>& s, vector<bool>& isUsed, vector<int>& index)
{
    int n = s.size();
    if(index.empty() && n % 2 != 0){
        for(int i=0; i<n; ++i){
            index.push_back(i);
            isUsed[i] = true;
            if(solve(s, isUsed, index))
                return true;
            isUsed[i] = false;
            index.pop_back();
        }
        return false;
    }

    int i = 0;
    while(i < n && isUsed[i])
        ++ i;

    if(i == n){
        vector<string> t(n);
        for(int j=0; j<n; ++j){
            if(j % 2 == 0)
                t[j/2] = s[index[n-1-j]];
            else
                t[n-1-j/2] = s[index[n-1-j]];
        }
        return check(t);
    }

    index.push_back(i);
    isUsed[i] = true;
    for(int j=i+1; j<n; ++j){
        if(!isUsed[j]){
            index.push_back(j);
            isUsed[j] = true;
            if(solve(s, isUsed, index))
                return true;
            isUsed[j] = false;
            index.pop_back();
        }
    }
    isUsed[i] = false;
    index.pop_back();

    return false;
}

int main()
{
    int h, w;
    cin >> h >> w;
    vector<string> s(h);
    for(int i=0; i<h; ++i)
        cin >> s[i];

    vector<int> index;
    vector<bool> isUsed(h, false);
    if(solve(s, isUsed, index))
        cout << "YES" << endl;
    else
        cout << "NO" << endl;

    return 0;
}

