bool check_others(int x[12], int parity)
{
    int i = 0;
    for(i = 0 ; i < W; ++i)
        if(!fixedd[i])break;
    if(i == W) return true;
    fixedd[i] = true;
    for(int j = 0; j < W; ++j)
    {
        if(fixedd[j]) continue;
        if(sum[j] != sum[i]) continue;
        if(check_two(i, j, x))
        {
