            return check_others(x, 0);
        }
    }
    if(parity == 0 && (W&1))
    {
        return check_others(x, 1);
    }
    fixedd[i] = false;
    return false;
}
bool check_permutation(int x[12])
{
   for(int i = 0; i < W; ++i) fixedd[i] = false;
   for(int i = 1; i < W; ++i)
   {
      if(sum[i] != sum[0]) continue;
      if(check_two(0, i, x))
      {
          fixedd[i] = true;
          fixedd[0] = true;
        if(check_others(x, 0))
            return true;
      }
   }
   if(W & 1)
   {
    fixedd[0] = true;
    if(check_others(x, 1))
        return true;
   }
}
