vector<int> t;

bool f() {
  for (int i = 0; i < h / 2; i++) {
    t[i] = ps[i * 2];
    t[h - i - 1] = ps[i * 2 + 1];
  }
  if (h % 2 == 1) {
    t[h / 2] = ps[h - 1];
  }
  int inv = 0;
  for (int i = 0; i < w; i++) {
    if (usedx[i])
      continue;
    for (int j = i + 1; j < w; j++) {
      if (usedx[j])
        continue;
      bool ok = true;
      for (int k = 0; k < h; k++) {
        if (mp[t[k]][i] != mp[t[h - k - 1]][j]) {
          ok = false;
        }
      }
      if (ok) {
        usedx[i] = usedx[j] = true;
        inv += 2;
      }
    }
  }
  if ((h % 2 == 0 && inv == h) || (h % 2 == 1 && inv == h - 1)) {
    return true;
  }
  return false;
}

bool dfs(int now) {
  if (now == h) {
    return f();
  }
  if (now % 2 == 0) {
    for (int i = 0; i < h; i++) {
      if (!used[i]) {
        ps[now] = i;
        used[i] = true;
        bool ret = dfs(now + 1);
        used[i] = false;
        return ret;
      }
    }
  }
  bool ret = false;
  for (int i = 0; i < h; i++) {
    if (!used[i]) {
      ps[now] = i;
      used[i] = true;
      if (dfs(now + 1))
        ret = true;
      used[i] = false;
    }
  }
  return ret;
}

