int n,m;
const int Maxn=15;

string s[Maxn];

pair<string,string> vec[Maxn];int kvec;

bool used[Maxn],vis[Maxn];

int mp[Maxn];

inline bool check(const string &s1,const string &s2){
	memset(vis,0,sizeof(vis));
	for(int i=0;i<m;i++){
		if(vis[i])continue;
		for(int j=i+1;j<m;j++){
			if((!vis[i])&&(!vis[j])&&s1[i]==s2[j]&&s1[j]==s2[i]){
				vis[i]=true;
				vis[j]=true;
				break;
			}
		}
	}

	int cnt=0;
	for(int i=0;i<m;i++){
		if(!vis[i])cnt++;
	}

	if(m%2==0){
		if(cnt>0)return false;
		return true;
	}

	if(cnt!=1)return false;
	for(int i=0;i<m;i++){
		if(!vis[i]){
			if(s1[i]==s2[i]){
				return true;
			}else{
				return false;
			}
		}
	}
	return false;
}


void match(){
	memset(used,0,sizeof(used));

	for(int i=0;i<n;i++){
		if(used[i])continue;
		for(int j=i+1;j<n;j++){
			if((!used[i])&&(!used[j])&&check(s[i],s[j])){
				used[i]=true;
				used[j]=true;
				vec[kvec++]=make_pair(s[i],s[j]);
				break;
			}
		}
	}

	int cnt=0;
	for(int i=0;i<n;i++){
		if(!used[i]){
			cnt++;
//			cerr<<s[i]<<endl;
		}
	}
//	cerr<<"cnt:"<<cnt<<endl;
	if(n%2==0){
		if(cnt>0)nope(3);
		return;
	}
	if(cnt!=1)nope(4);
	for(int i=0;i<n;i++){
		if(!used[i]){
			if(check(s[i],s[i])){
				vec[kvec++]=make_pair(s[i],s[i]);
				return;
			}else nope(5);
		}
	}
}

bool ok=false;
void calc(){
//	cerr<<"mp:";for(int i=0;i<m;i++)cerr<<mp[i]<<' ';cerr<<endl;
	bool flag=true;
	for(int i=0;i<kvec;i++){
