		string s2=vec[i].second;
		for(int j=0;j<m;j++){
			if(s1[j]==s2[mp[j]]&&s1[mp[j]]==s2[j]);
			else {
				flag=false;
				break;
			}
		}
	}
	if(flag){
		ok=true;
	}
}

bool dfs(int i,const string &s1,const string &s2){
	if(i==m){
		calc();
		if(ok)return true;
		return false;
	}
	if(mp[i]!=-1){
		if(dfs(i+1,s1,s2))return true;
		return false;
	}
	for(int j=i+1;j<m;j++){
		if(mp[i]==-1&&mp[j]==-1&&s1[i]==s2[j]&&s1[j]==s2[i]){
			mp[i]=j;
			mp[j]=i;
			if(dfs(i+1,s1,s2))return true;
			mp[i]=0;
			mp[j]=0;
		}
	}
	return false;
}


