void read(){
    cin >> W >> H;
    for(int i = 0 ; i < W; ++i)
    {
        cin >> s[i];
        for(int j = 0; j < H; ++j)
            sum[i]+=s[i][j];
    }
}
bool check_two(int i, int j, int x[12])
{
   for(int k = 0; k < H; ++k)
   {
        if(s[i][x[k]] != s[j][x[H-1-k]]) return false;
   }
   return true;
}
bool check_others(int x[12], int parity)
{
    int i = 0;
    for(i = 0 ; i < W; ++i)
        if(!fixedd[i])break;
    if(i == W) return true;
    fixedd[i] = true;
    for(int j = 0; j < W; ++j)
    {
        if(fixedd[j]) continue;
        if(sum[j] != sum[i]) continue;
        if(check_two(i, j, x))
        {
            fixedd[j] = true;
            return check_others(x, 0);
        }
    }
    if(parity == 0 && (W&1))
    {
        return check_others(x, 1);
    }
    fixedd[i] = false;
    return false;
}
bool check_permutation(int x[12])
{
   for(int i = 0; i < W; ++i) fixedd[i] = false;
      fixedd[0] = true;
   for(int i = 1; i < W; ++i)
   {
      if(sum[i] != sum[0]) continue;
      if(check_two(0, i, x))
      {
          fixedd[i] = true;
        if(check_others(x, 0))
            return true;
        fixedd[i] = false;
      }
   }
   if(W & 1)
   {
    fixedd[0] = true;
    if(check_others(x, 1))
        return true;
   }
}
void solve(){
    int x[12];
    for(int i = 0; i < H; ++i) x[i] = i;
    bool ans = false;
    do{
        if(check_permutation(x))
        {
            ans = true;
            break;
        }
    }while(next_permutation(x, x + H));
    if(ans)
        cout << "YES\n";
    else
        cout << "NO\n";
}

int main(){
    read();
    solve();
}

#include <bits/stdc++.h>
using namespace std;

int h, w;
mt19937 ei(1333333);

bool check(vector<string> s) {
  int h = s.size();
  vector<string> t = s;
  for (auto &i : t) reverse(i.begin(), i.end());

  int cnt = 0;
  vector<bool> used(h);
  for (int i = 0; i < h; ++i) {
    for (int j = i + 1; j < h; ++j) {
      if (used[j]) continue;
      if (s[i] == t[j]) {
        used[i] = used[j] = true;
        cnt += 2;
        break;
      }
    }
  }

  if (h - cnt >= 2) return false;

  if (h & 1) {
    for (int i = 0; i < h; ++i) {
      if (used[i]) continue;
      if (s[i] == t[i]) cnt++;
    }
  }

  return cnt == h;
}

bool solve(vector<string> &t, int q = 400000) {
  vector<string> s = t;
  vector<int> v(w);
  for (int i = 0; i < w; ++i) v[i] = i;
  while (q--) {
    //怒りの乱択
    if (check(s)) return true;
    shuffle(v.begin(), v.end(), ei);
    for (int i = 0; i < h; ++i) {
      for (int j = 0; j < w; ++j) {
        s[i][j] = t[i][v[j]];
      }
    }
  }

  return false;
}

int main() {
  cin >> h >> w;

  vector<string> s(h);
  for (auto &i : s) cin >> i;

  cout << (solve(s) ? "YES" : "NO") << endl;
}

