#include <iostream>
#include <algorithm>
#include <vector>
#include <string>

using Bool = bool;
using Int = long long int;
using String = std::string;
template <class T>
using Vector = std::vector<T>;

// 各関数は上から下に流れるようになっている
// ! で始まるコメントは自分が踏んだバグ
struct {
    Int h, w;
    Vector<Int> col;
    Vector<String> s, t;
    // sは入力 tは行を並び替えた後、転置したもの
    Bool possible;

    void operator()() {
        possible = false;
        std::cin >> h >> w;

        s.resize(h), t.resize(w);
        for (auto& x : s) std::cin >> x;
        for (auto& y : t) y.resize(h);  // ! tのresizeし忘れ

        col.resize(h);
        enumcol_center();
    }

    // 真ん中の行の列挙　
    // ! これを後回しにして、中心の全列挙をミスる
    void enumcol_center() {
        if (h % 2 == 0) {
            enumcol(0, 0);
        } else {
            for (Int x = 0; x < h; ++x) {
                col[h / 2] = x;
                enumcol(1 << x, 0);
            }
        }
    }

    // bは固定済みの行　iはいくつのペアを固定したか
    void enumcol(Int b, Int i) {
        Int x;
        for (x = 0; x < h; ++x) {
            if (!((b >> x) & 1)) break;
        }
        if (x == h) {
            align();
            return;  // ! ここでreturnしないとhを固定し始める
        }

        for (Int y = x + 1; y < h; ++y) {
            if (!((b >> y) & 1)) {
                col[i] = x;
                col[h - i - 1] = y;
                enumcol(b | (1 << x) | (1 << y), i + 1);
            }
        }
    }

    // colに従ってtを埋める
    void align() {
        for (Int y = 0; y < w; ++y) {
            for (Int x = 0; x < h; ++x) {
                t[y][x] = s[col[x]][y];
            }
        }
        check_center();
    }

    // 真ん中の行の列挙　
    // ! enumcol_center()と同じく
    void check_center() {
        if (w % 2 == 0) {
            check(0);
        } else {
            for (Int x = 0; x < w; ++x) {
                // 回文判定
                String z = t[x];
                std::reverse(z.begin(), z.end());
                if (z == t[x]) check(1 << x);
            }
        }
    }

    // 両端から、互いに逆なペアを決めていく
    // bは決定済みの行番号
    void check(Int b) {
        Int x;
        for (x = 0; x < w; ++x) {
            if (!((b >> x) & 1)) break;
        }

        if (x == w) {
            possible = true;
            return;  // ! ここで枝刈りしないと、全文字が同じケースで非常に時間がかかる
                     //   なんならYESを出力してexit()を呼んでもいい
        }

        String z = t[x];
        std::reverse(z.begin(), z.end());

        for (Int y = x + 1; y < w; ++y) {
            if (!((b >> y) & 1)) {
                if (t[y] == z) {
                    check(b | (1 << x) | (1 << y));
                    return;
                }
            }
        }
    }
} solve;

int main() {
    solve();
    std::cout << (solve.possible ? "YES" : "NO") << std::endl;
    return 0;
}

