vector<string> rotate(vector<string> s) {
  int n=s.size(),m=s[0].size();
  vector<string> t(m);
  rep(i,m)rrep(j,n) t[i]+=s[j][i];
  return t;
}

ll calc(vector<string> s) {
  clock_t t2=clock();
  int n=s.size(),m=s[0].size();
  int a[n];
  rep(i,n) a[i]=i;
  do {
    int b[m];
    rep(i,m) b[i]=i;
    do {
      vector<string> t(n,string(m,'*'));
      rep(i,n) {
        rep(j,m) t[i][j]=s[a[i]][b[j]];
      }
      rep(i,n) {
        rep(j,m) {
          if(t[i][j]!=t[n-1-i][m-1-j]) goto next;
        }
      }
      return 1;
    next:;
      clock_t t3=clock();
      double t4=(double)(t3-t2)/CLOCKS_PER_SEC;
      if((double)t3/CLOCKS_PER_SEC+t4*2>1.9) return 0;
    } while(next_permutation(b,b+m));
  } while(next_permutation(a,a+n));
  return 0;
}

