void check(vector < pair < int, int > > v) 
{
	for (int i = 0; i < (int)v.size(); i++)
	{
		if (v[i].first == v[i].second)
		{
			swap(v[i], v[(int)v.size() - 1]);
			break;
		}
	}
	vector < string > a;	
	for (int i = 0; i < (int)v.size(); i++)
	{
		a.pb(s[v[i].first]);
	}
	for (int i = (int)v.size() - 1; i >= 0; i--)
	{	
		if (v[i].first != v[i].second)
			a.pb(s[v[i].second]);
	}
	bool found = false;
	vector < string > b;
	for (int i = 0; i < m; i++)
	{
		string cur;
		for (int j = 0; j < n; j++)
			cur += a[j][i];
		b.pb(cur);		
	}
	for (int i = 0; i < m; i++)
	{
		if (was[i])
			continue;
		reverse(all(b[i]));
		for (int j = i + 1; j < m; j++)
		{
			if (!was[j] && b[i] == b[j])
			{
				was[i] = was[j] = true;
				break;
			}
		}		
		reverse(all(b[i]));
		if (!was[i])
		{	
			if ((m & 1) && !found)
			{
				string t = b[i];
				reverse(all(t));
				if (b[i] == t)
				{
					found = true;
					was[i] = true;
				}
			}
		}
		if (!was[i])
		{
			return;
		}
	}
	cout << "YES" << endl;
	exit(0);
}

void rec(int id, bool found, vector < pair < int, int > > & v)
{
	if (id == n)
	{
		check(v);
		return;		
	}
	if (used[id])
	{
		rec(id + 1, found, v);	
		return;
	}
	if ((n & 1) && !found)
	{
		used[id] = true;
		v.pb({id, id});
		rec(id + 1, true, v);
		v.pop_back();
		used[id] = false;
	}
	for (int i = id + 1; i <= n; i++)
	{
		if (!used[i])
		{
			used[id] = used[i] = true;
			v.pb({id, i});
			rec(id + 1, found, v);
			used[id] = used[i] = false;
			v.pop_back();
		}
	}
	return;
}	 

