bool calc(vector<string> const &chars, mdview const &hgv, mdview const &wgv) {
    for (size_t hs = 0; hs < hgv.size(); hs++) {
        for (size_t ws = 0; ws < wgv.size(); ws++) {
            int y1 = hgv[hs][0];
            int x1 = wgv[ws][0];
            int y2 = hgv[hs][1];
            int x2 = wgv[ws][1];
            if (chars[y1][x1] != chars[y2][x2] || chars[y2][x1] != chars[y1][x2]) return false;
        }
    }
    return true;
}

pair<vector<int>,int> organize(vector<string> const &chars, vector<vector<unordered_map<pair<char,char>, int, pair_hash>>> const &pairs, int upto, bool is_h) {
    vector<int> gs(upto, -1);
    int g = 0;
    for (int i = 0; i < upto; i++) {
        if (gs[i] != -1) continue;
        for (int j = i+1; j < upto; j++) {
            if (gs[j] != -1) continue;
            bool ok = true;
            for (auto const &x: pairs[i][j]) {
                auto const &lkey = x.first;
                auto rkey = make_pair(lkey.second, lkey.first);
                if (!pairs[i][j].count(rkey) || x.second != pairs[i][j].at(rkey)) {
                    ok = false;
                    break;
                }
            }

            auto otpu = is_h ? chars[0].size() : chars.size();
            if (ok) for (int l = 0; l < j; l++) {
                if (l == i) continue;
                if (gs[l] != g) continue;
                bool same = true;
                for (size_t k = 0; k < otpu; k++) {
                    if (is_h) same = same && chars[l][k] == chars[j][k];
                    else      same = same && chars[k][l] == chars[k][j];
                }
                ok = ok && !same;
            }
            if (ok) gs[i] = gs[j] = g;
        }
        g++;
    }
    // cerr << "gs: ";
    // copy(gs.begin(), gs.end(), ostream_iterator<int>(cerr, ", "));
    // cerr << endl;
    if (count(gs.begin(), gs.end(), -1) > 1) {
        return make_pair(gs, -1);
    }
    return make_pair(gs, g);
}

