int solve(){
    for(int i=0; i<h; i++){
        f[i]=i;
        c[i]=1;
        d[i]=test(i, i);
    }
    for(int x=0; x<h; x++){
        for(int y=x+1; y<h; y++){
            int p=find(x);
            int q=find(y);
            if(p==q)continue;
            if(test(x, y)){
                // q->p
                f[q]=f[p];
                c[p]+=c[q];
                d[p]+=d[q];
                c[q]=0;
                d[q]=0;
            }
        }
    }
    int cnt=0;
    for(int i=0; i<h; i++){
        if(c[i]&1){
            if(!d[i])return 0;
            cnt++;
        }
    }
    return (cnt<2)?1:0;
}

int bmatch(const int remain){
    if(remain==0){
        return solve();
    }else if(pcnt[remain]==1){
        b[pcnt[remain-1]]=pcnt[remain-1];
        return bmatch(0);
    }else{
        int x=LOWBIT(remain);
        for(int bar=remain^x; bar; ){
            int y=LOWBIT(bar);
            bar^=y;
            b[pcnt[x-1]]=pcnt[y-1];
            b[pcnt[y-1]]=pcnt[x-1];
            if(bmatch(remain^x^y))return 1;
        }
    }
    return 0;
}

