				if (hcou[i][c] != hcou[j][c])
				{
					flag = false;
					break;
				}
			}
			if (flag)
			{
				hcou[i].clear();
				hcou[j].clear();
				ok = true;
				break;
			}
		}
		if (!ok) ++modCouH;
	}
	rep(i, W)
	{
		if (wcou[i].empty()) continue;
		bool ok = false;
		rep(j, W)
		{
			if (i == j || wcou[j].empty()) continue;
			bool flag = true;
			for (char c = 'a'; c <= 'z'; ++c)
			{
				if (wcou[i][c] != wcou[j][c])
				{
					flag = false;
					break;
				}
			}
			if (flag)
			{
				wcou[i].clear();
				wcou[j].clear();
				ok = true;
				break;
			}
		}
		if (!ok) ++modCouW;
	}
	modCouH -= H % 2;
	modCouW -= W % 2;
	out << (modCouH == 0 && modCouW == 0 ? "YES" : "NO") << std::endl;
	return 0;
}

