#include <bits/stdc++.h>

using namespace std;

int chars[256];
bool isPalindrome(string &S) {
    memset(chars, 0, sizeof(chars));
    for (int i = 0; i < S.length(); i++) {
        chars[S[i]] += 1;
    }

    int odd = 0, even = 0;
    for (int i = 'a'; i <= 'z'; i++) {
        if (chars[i]%2 == 0) even += 1;
        else odd += 1;
    }
    for (int i = 'A'; i <= 'Z'; i++) {
        if (chars[i]%2 == 0) even += 1;
        else odd += 1;
    }

    if (S.length()%2 == 0) {
        if (odd == 0) return true;
        else return false;
    } else {
        if (odd == 1) return true;
        else return false;
    }
}

int h, w;
vector<string> G;
vector<int> mix(12);

bool tryGrid() {
    vector<string> T(h, "");
    vector<bool> used(h, false);
    int remaining = h;
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            T[i] += G[i][mix[j]];
        }
        //cout << T[i] << endl;
    }

    int remains = -1;
    for (int i = 0; i < h; i++) {
        if (used[i]) continue;
        for (int j = i+1; j < h; j++) {
            if (used[j]) continue;
            bool match = true;
            for (int k = 0; k < w; k++) {
                if (T[i][k] != T[j][w-1-k]) {
                    match = false;
                    break;
                }
            }
            if (match) {
                used[i] = true;
                used[j] = true;
                remaining -= 2;
                break;
            }
        }
        if (!used[i]) {
            remains = i;
        }
    }

    if (h%2 == 0) {
        if (remaining > 0) {
            return false;
        } else {
            return true;
        }
    } else {
        if (remaining == 1 && isPalindrome(T[remains])) {
            return true;
        } else {
            return false;
        }
    }
}

vector<bool> U(12, false);
bool works = false;
void mixColumns(int i) {
    if (works) return;
    if (i == w/2) {
        if (w%2 == 1) {
            for (int c = i; c < w; c++) {
                if (!U[c]) {
                    mix[w/2] = c;
                }
            }
        }
        if (tryGrid()) {
            works = true;
            return;
        }
    }

    int c;
    for (c = i; c < w; c++) {
        if (!U[c]) break;
    }

    mix[i] = c;
    U[c] = true;
    int s = c;
    for (c = c+1; c < w; c++) {
        if (!U[c]) {
            U[c] = true;
            mix[w-1-i] = c;
            mixColumns(i+1);
            U[c] = false;
        }
    }
    U[s] = false;
}

