    cin >> h >> w;
    for (int i = 0; i < h; i++) {
        string T;
        cin >> T;
        G.push_back(T);
    }

    mixColumns(0);

    if (works) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }
}

