bool vis[1 << 12];

bool check(vector<string> s) {

  CLR(vis, 0);

  int H = (int)s.size();

  REP(i, H) sort(ALL(s[i]));
  // REP(i, H)cout << s[i] << endl; cout << ".." << endl;
  vector<string> t = s;
  REP(i, H) reverse(ALL(t[i]));
  // REP(i, H)cout << t[i] << endl; cout << ".." << endl;

  vis[0] = 1;
  if (H % 2 == 1) {
    REP(i, H) {
      if (s[i] == t[i]) vis[1 << i] = 1;
    }
  }
  for (int set = 0; set < (1 << H); set++) if (vis[set]) {
    for (int i = 0; i < H; i++) if (0 == (set >> i & 1)) {
      for (int j = i + 1; j < H; j++) if (0 == (set >> j & 1)) {
        if (s[i] == s[j]) {
          vis[set | (1 << i) | (1 << j)] = true;
        }
      }
    }
  }
  return vis[(1 << H) - 1];
}
