  REP(i, H) cin >> s[i];
  bool c1 = check(s);
  vector<string> t(W, string(H, '.'));
  REP(i, H) REP(j, W) {
    t[j][i] = s[i][j];
  }
  bool c2 = check(t);
  cout << ((c1 && c2) ? "YES":"NO") << endl;
  return 0;
}


