int H, W;
char S[15][15];
int half;
int ary[12];
bool ary_flg[12];

bool check()
{
	bool flg[12] = {};
	int cnt = 0;
	for (int y1 = 0; y1 < H; y1++)
	{
		if (flg[y1]) continue;
		for (int y2 = y1 + 1; y2 < H; y2++)
		{
			if (flg[y2]) continue;
			bool is_valid = true;
			for (int x = 0; x < half; x++)
			{
				if (S[y1][ary[x]] != S[y2][ary[W - x - 1]])
				{
					is_valid = false;
					break;
				}
			}
			if (is_valid)
			{
				flg[y1] = true;
				flg[y2] = true;
				cnt += 2;
				break;
			}
		}
	}

	if (H % 2 == 1)
	{
		if (H - 1 != cnt)
		{
			return false;
		}

		int c;
		REP(y, H)
		{
			if (!flg[y])
			{
				c = y;
				break;
			}
		}
		for (int x = 0; x < W / 2; x++)
		{
			if (S[c][ary[x]] != S[c][ary[W - x - 1]])
			{
				return false;
			}
		}

		return true;
	}
	else
	{
		return (H == cnt);
	}
}

void comb2(int n)
{
	if (n >= W)
	{
		if (check())
		{
			cout << "YES" << endl;
			exit(0);
		}
		return;
	}

	int index = W - (n - half) - 1;
	int init = ary[n - half];
	for (int i = init; i < W; i++)
	{
		if (ary_flg[i]) continue;
		ary[index] = i;
		ary_flg[i] = true;
		comb2(n + 1);
		ary_flg[i] = false;
	}

}

void comb(int n)
{
	if (n >= W / 2)
	{
		if (W % 2 == 1 && n == W / 2)
		{
			for (int i = 0; i < W; i++)
			{
				if (!ary_flg[i])
				{
					ary_flg[i] = true;
					ary[n] = i;
					comb(n + 1);
					ary_flg[i] = false;
				}
			}
			return;
		}

		comb2(n);
		return;
	}

	int init = n == 0 ? 0 : (ary[n - 1] + 1);
	for (int i = init; i < W; i++)
	{
		ary[n] = i;
		ary_flg[i] = true;
		comb(n + 1);
		ary_flg[i] = false;
	}
}

