using namespace std;
class ESymmetricGrid {
 public:
  static void solve(istream &, ostream &) {
    int H, W;
    scan(H, W);
    vector<string> s(H);
    For(row, s) scan(row);
    // permutation of rows
    vi p(H);
    auto check = [&]() {
      vector<string> cols(W, string(H, 'a'));
      rng(i, 0, W) {
        rng(j, 0, H) { cols[i][j] = s[p[j]][i]; }
      }
//      debug(cols);
      vb used(W);

      bool seen_palindrome = false;
      rng (i, 0, W) {
        if (used[i]) continue;
        auto t = cols[i];
        reverse(ALL(t));
        bool found = false;
        rng (j, i + 1, W) {
          if (!used[j] && cols[j] == t) {
            found = true;
            used[j] = true;
//            debug(cols[i], cols[j]);
            break;
          }
        }
        if (found) {
          continue;
        }
        if (W & 1 and !seen_palindrome and t == cols[i]) {
          seen_palindrome = true;
          continue;
        }
        return false;
      }
      return true;
    };

    vi used(H);
    function<bool(int)> gen_pairing = [&](int cnt) {
      if (cnt == H / 2 + 1) {
        return check();
      }
      rng(i, 0, H) {
        if (!used[i]) {
          p[cnt - 1] = i;
          used[i] = true;
          rng(j, i + 1, H) {
            if (!used[j]) {
              used[j] = true;
              p[H - cnt] = j;
              if (gen_pairing(cnt + 1)) return true;
              used[j] = false;
            }
          }
          used[i] = false;
          break;
        }
      }
      return false;
    };
    if (H & 1) {
      rng (i, 0, H) {
        used[i] = true;
        p[H / 2] = i;
        if (gen_pairing(1)) {
          println("YES");
          return;
        }
        used[i] = false;
      }
      println("NO");
    } else {
      println(gen_pairing(1) ? "YES" : "NO");
    }
  }
};
