int h, w;
char grid[12][12+1];

bool solve3(int sy[]) {
	bool usedx[12];
	bool mid_used = h % 2 == 0;
	for(int i=0;i<h;i++) if(!usedx[i]) {
		bool ok = false;
		for(int j=i+1;j<h;j++) if(!usedx[j]) {
			bool same = true;
			for(int k=0;k<w;k++) {
				if(grid[i][sy[k]] != grid[j][sy[w-1-k]]) same = false;
			}
			if(same) {
				usedx[i] = usedx[j] = true;
				ok = true;
				break;
			}
		}
		if(!ok && !mid_used) {
			bool same = true;
			for(int k=0;k<w/2;k++) {
				if(grid[i][sy[k]] != grid[i][sy[w-1-k]]) same = false;
			}
			if(same) {
				usedx[i] = true;
				mid_used = true;
				ok = true;
			}
		}
		if(!ok) return false;
	}
	return true;
}

bool solve2(bool used[], int ind, int sy[]) {
	if(w-2*ind <= 1) {
		return solve3(sy);
	} else {
		for(int i=0;i<w;i++) if(!used[i]) {
			sy[ind] = i;
			break;
		}
		used[sy[ind]] = true;
		for(int i=0;i<w;i++) if(!used[i]) {
			used[i] = true;
			sy[w-1-ind] = i;
			if(solve2(used, ind+1, sy)) return true;
			used[i] = false;
		}
		used[sy[ind]] = false;
		return false;
	}
}

bool solve() {
	bool used[12];
	for(int i=0;i<w;i++) used[i] = false;
	int sy[12];
	if(w % 2 == 1) {
		for(int i=0;i<w;i++) {
			used[i] = true;
			sy[w/2] = i;
			if(solve2(used, 0, sy)) return true;
			used[i] = false;
		}
		return false;
	} else {
		return solve2(used, 0, sy);
	}

}

