bool check(vector<string> s) {
  int h = s.size();
  vector<string> t = s;
  for (auto &i : t) reverse(i.begin(), i.end());

  int cnt = 0;
  bool used[20] = {};
  for (int i = 0; i < h; ++i) {
    for (int j = 0; j < i; ++j) {
      if (used[j] || s[i] != t[j]) continue;
      used[i] = used[j] = true;
      cnt += 2;
      break;
    }
  }

  if (h & 1) for (int i = 0; i < h; ++i) {
    if (used[i] || s[i] != t[i]) continue;
    cnt++;
    break;
  }

  return cnt == h;
}

bool solve(auto &t, int q = 400000) {
  auto s = t;
  vector<int> v(w);
  for (int i = 0; i < w; ++i) v[i] = i;
  while (q--) {
    //怒りの乱択
    if (check(s)) return true;
    shuffle(v.begin(), v.end(), ei);
    for (int i = 0; i < h; ++i) {
      for (int j = 0; j < w; ++j) {
        s[i][j] = t[i][v[j]];
      }
    }
  }

  return false;
}

