	for(int j = 1 ; j <= W ; ++j) {
		for(int i = 1 ; i <= H ; ++i) {
			Col[j][S[i][j] - 'a']++;
		}
	}
	for(int i = 1 ; i <= H ; ++i) {
		for(int j = i ; j <= H ; ++j) {
			bool f = 1;
			for(int k = 0 ; k <= 25 ; ++k) {
				if(Row[i][k] != Row[j][k]) {f = 0;break;}
			}
			matR[i][j] = matR[j][i] = f;

		}
	}
	for(int i = 1 ; i <= W ; ++i) {
		for(int j = i ; j <= W ; ++j) {
			bool f = 1;
			for(int k = 0 ; k <= 25 ; ++k) {
				if(Col[i][k] != Col[j][k]) {f = 0;break;}
			}
			matC[i][j] = matC[j][i] = f;
		}
	}
	for(int i = 1 ; i <= H ; ++i) idR[i] = i;
	for(int i = 1 ; i <= W ; ++i) idC[i] = i;
	for(int i = 1 ; i <= H ; ++i) {
		if(!used[i]) {
			swapRow(i,1);
			if(check()) {puts("YES");return;}
			swapRow(i,1);
		}
