bool dfs2(int cnt, int flag) {
    if(cnt == w){
        return true;
    }

    bool res = false;

    inc(i, 0, w){
        if(used[i]) continue;
        inc(j, i+1, w){
            if(used[j]) continue;
            if(same(i, j)){
                used[i] = 1;
                used[j] = 1;
                return dfs2(cnt+2, flag);
            }
