bool dfs1(int idx, int bit) {
    bool res = false;
    int cnt = 0;
    inc(i, 0, h){
        if((bit & (1 << i)) != 0) cnt++;
    }

    if(cnt == h){
        inc(i, 0, w){
            used[i] = 0;
        }
        return dfs2(0, 0);
    }

    if(cnt == 0 && h%2 == 1){
        inc(i, 0, h){
            f[h/2] = i;
            res |= dfs1(0, bit | (1 << i));
            f[h/2] = -1;
        }
    }else{
        inc(i, 0, h){
            if((bit & (1 << i)) != 0) continue;

            inc(j, i+1, h){
                if((bit & (1 << j)) != 0) continue;

                f[idx] = i;
                f[h-idx-1] = j;
                res |= dfs1(idx+1, bit | (1 << i) | (1 << j));
                f[idx] = -1;
                f[h-idx-1] = -1;
            }
            break;
        }
    }

    return res;
}

