		 (vs[y][x] != vs[match_y[y]][x1]
		  || vs[y][x1] != vs[match_y[y]][x])){
		ok = false;
		break;
	  }
	if(ok){
	  match_x[x] = x1;
	  match_x[x1] = x;
	  if(dfs2(match_y, x+1, match_x))
		return true;
	  match_x[x] = match_x[x1] = -1;
	}
  }
  return false;
}

bool dfs1(bool init, int y, VI& match){
  if(init){
	REP(y,H){
	  if(!ok_y[y]) continue;
	  match[y] = H;
	  if(dfs1(false, 0, match)){
		return true;
	  }
	  match[y] = -1;
	}
	return false;
  }

  if(y == H){
	VI match_x(W, -1);
	if(dfs2(match, 0, match_x))
	  return true;
	return false;
  }
  if(match[y] >= 0)
	return dfs1(init, y+1, match);

  for(int y1=y+1;y1<H;++y1)
	if(match[y1] < 0 && same[y][y1]){
	  match[y] = y1;
	  match[y1] = y;
	  if(dfs1(init, y+1, match))
		return true;
	  match[y] = match[y1] = -1;
	}
  return false;
}

int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  cin >> H >> W;
  REP(y,H) cin >> vs[y];

  REP(y,H){
  	set<char> s;
	for(char c: vs[y])
	  if(count(ALL(vs[y]), c) % 2)
		s.insert(c);
	ok_y[y] = SZ(s) <= 1;
  }

  if(H == 1){
	cout << (ok_y[0]? "YES": "NO") << endl;
	return 0;
  }

  REP(y,H) REP(y1,y+1){
	string s1 = vs[y];
	string s2 = vs[y1];
	SORT(s1);
	SORT(s2);
	if(s1 == s2)
	  same[y][y1] = same[y1][y] = true;
  }

  VI match(H, -1);
  cout << (dfs1(H%2==1, 0, match)? "YES": "NO") << endl;

  return 0;
}

