bool is_symmetry(vector<string>& board) {
    for (ll h = 0; h < (H + 1) / 2; h++) {
        for (ll w = 0; w < W; w++) {
            ll g = H - 1 - h;
            ll v = W - 1 - w;

            if (board[h][w] != board[g][v]) {
                return false;
            }
        }
    }

    return true;
}

bool is_symmetric(ll h1, ll h2) {
    string s1 = board[h1], s2 = board[h2];
    vector<bool> used(W, false);
    for (ll w1 = 0; w1 < W; w1++) {
        for (ll w2 = w1 + 1; w2 < W; w2++) {
            if (!used[w1] && !used[w2] && s1[w1] == s2[w2] && s1[w2] == s2[w1]) {
                used[w1] = used[w2] = true;
                break;
            }
        }
    }

    ll unused = 0;
    for (auto u : used) {
        if (!u) {
            unused++;
        }
    }

    return unused < 2;
}

int main(void) {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> H >> W;
    for (ll h = 0; h < H; h++) {
        string s;
        cin >> s;
        board.push_back(s);
    }

    vector<vector<ll> > alphabets(H, vector<ll>(26, 0));
    for (ll h = 0; h < H; h++) {
        for (auto s : board[h]) {
            alphabets[h][s - 'a']++;
        }
    }

    vector<bool> used(H, false);

    for (ll h1 = 0; h1 < H; h1++) {
        for (ll h2 = h1 + 1; h2 < H; h2++) {
            if (!used[h1] && !used[h2] && alphabets[h1] == alphabets[h2]) {
                if (is_symmetric(h1, h2)) {
                    used[h1] = used[h2] = true;
                    break;
                }
            }
        }
    }

    ll unused = 0;
    for (auto u : used) {
        if (!u) {
            unused++;
        }
    }

    if (unused >= 2) {
        cout << "NO" << endl;
    } else {
        cout << "YES" << endl;
    }

    return 0;
}

