bool palindrome(string &s) {
    int n = s.size();
    for (int i = 0; i < n; i++) {
        if (i > n-1-i) break;
        if (s[i] != s[n-1-i]) return false;
    }
    return true;
}

void judge(vector<int> &s) {
    vector<int> y(h);
    vector<bool> u(h, false);
    for (int i = 0; i < h; i++) {
        if (u[s[i]]) y[i] = h-1 - (h/2+s[i]); 
        else y[i] = h/2 + s[i]; 
        u[s[i]] = true;
    }
    vector<string> p(w, string(h, '0')), q;
    q = p;
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            p[j][y[i]] = v[i][j];
            q[j][h-y[i]-1] = v[i][j];
        }
    }
    int pcount = 0;
    vector<string> a, b;
    for (int i = 0; i < w; i++) {
        if (palindrome(p[i])) pcount++;
        else {
            a.push_back(p[i]);
            b.push_back(q[i]);
        }
    }
    sort(a.begin(), a.end());
    sort(b.begin(), b.end());
    for (int i = 0; i < w; i++) {
        if (a[i] != b[i]) return;
    }
    ans = true;
    return;
}

void search(int t, vector<int> &s) {
    if (t == h) {
        judge(s);
        return;
    }
    int first = -1;
    if ((h - t) % 2 == 1) {
        for (int i = 0; i < h; i++) {
            s[i] = (t+1) / 2;
            search(t+1, s);
            s[i] = -1;
        }
    } else {
        for (int i = 0; i < h; i++) {
            if (s[i] == -1) {
                first = i;
                break;
            }
        }
        bool flag = true;
        for (int j = first+1; j < h; j++) {
        if (s[j] == -1) {
                s[first] = (t+1) / 2;
                s[j] = (t+1) / 2;
                flag = false;
                search(t+2, s);
                s[first] = -1;
                s[j] = -1;
            }
        }
    }
    return;
}

