#include <bits/stdc++.h>
#define FOR(i,k,n)  for(int i = (k);i < (n);++i)
#define REP(i,n)    FOR(i,0,n)
#define ALL(x)      begin(x),end(x)

using namespace std;
using vecint = vector<int>;
using ll = int64_t;
int h,w;

bool isok_impl(const vector<string>& t) {
  REP(i,h)REP(j,w) {
    if (t[i][j] != t[h-i-1][w-j-1]) return false;
  }
  return true;
}

bool isok_h(const vector<string>& t, int k) {
  if (2*k >= h) return isok_impl(t);
  FOR(i,w/2,h-k) {
    vector<string> s = t;
    swap(s[i], s[h-k-1]);
    if (s[k][0] != s[h-k-1][w-1]) continue;
    if (isok_h(s, k+1)) return true;
  }
  return false;
}

bool isok_w(const vector<string>& t, int k) {
  if (2*k >= w) return isok_impl(t);
  FOR(j,h/2,w-k) {
    vector<string> s = t;
    REP(p,h) swap(s[p][j], s[p][w-k-1]);
    if (s[0][k] != s[h-1][w-k-1]) continue;
    if (isok_w(s, k+1)) return true;
  }
  return false;
}

bool isok(const vector<string>& t, int k) {
  int n = max(h,w) - min(h,w);
  if (n == 0) return isok_impl(t);
  if (h > w) {
    return isok_h(t, k);
  } else {
    return isok_w(t, k);
  }
}

bool solve(const vector<string>& t, int k = 0) {
  if (2*k >= min(h,w)) return isok(t, k);
  FOR(i,0,h)FOR(j,0,w) {
    vector<string> s = t;
    swap(s[i], s[h-k-1]);
    REP(p,h) swap(s[p][j], s[p][w-k-1]);
    if (s[k][k] != s[h-k-1][w-k-1]) continue;
    if (solve(s, k+1)) return true;
  }
  return false;
}

int main()
{
  cin>>h>>w;
  vector<string> t(h);
  REP(i,h) cin>>t[i];
  bool res = solve(t);
  if (res) {
    cout << "YES" << endl;
  } else {
    cout << "NO" << endl;
  }
  return 0;
}

