void fors(vector<int> &P, int i, int N){
    if(N <= 0){
        vector<int> pair = makepair(P);
        check(pair);
    }else{
        for(P[i] = 0; P[i] < N; P[i]++){
            fors(P, i + 1, N - 2);
        }
    }
}

vector<int> makepair(vector<int> &P){
    vector<int> index(W), pair(W);
    REP(i, W){
        index[i] = i;
    }
    if(W % 2 == 1) index.erase(index.begin() + center);

    REP(i, W / 2){
        pair[2 * i] = index[0];
        index.erase(index.begin() + 0);
        pair[2 * i + 1] = index[P[i]];
        index.erase(index.begin() + P[i]);
    }
    if(W % 2 == 1) pair[W - 1] = center;
    return pair;
}

void check(vector<int> pair){
    string S2[12];
    REP(i, H){
        S2[i] = S[i];
    }
    REP(i, H){
        REP(j, W / 2){
            S2[i][j] = S[i][pair[2 * j]];
            S2[i][W - j - 1] = S[i][pair[2 * j + 1]];
        }
        if(W % 2 == 1) S2[i][(W - 1) / 2] = S[i][pair[W - 1]];
    }
    vector<int> index(H);
    REP(i, H){
        index[i] = i;
    }
    while(index.size() >= 2){
        int i1 = index[0];
        bool found = false;
        reverse(S2[i1].begin(), S2[i1].end());
        FOR(i, 1, index.size()){
            if(S2[i1] == S2[index[i]]){
                found = true;
                index.erase(index.begin() + i);
                index.erase(index.begin() + 0);
                break;
            }
        }
        reverse(S2[i1].begin(), S2[i1].end());
        if(!found) break;
    }
    //index[0]が中心に来るかもしれない
    if(index.size() > 1 && H % 2 == 1){
        swap(index[0], index[index.size() - 1]);
        while(index.size() >= 2){
            int i1 = index[0];
            bool found = false;
            reverse(S2[i1].begin(), S2[i1].end());
            FOR(i, 1, index.size()){
             if(S2[i1] == S2[index[i]]){
                    found = true;
                    index.erase(index.begin() + i);
                    index.erase(index.begin() + 0);
                    break;
                }
            }
            reverse(S2[i1].begin(), S2[i1].end());
            if(!found) break;
        }
    }
    if(H % 2 == 0 && index.size() == 0) ans = "YES";
    if(H % 2 == 1 && index.size() == 1){
        string S3 = S2[index[0]];
        reverse(S3.begin(), S3.end());
        if(S3 == S2[index[0]]) ans = "YES";
    }
}

