            used[i] = 1, B[t] = A[p.second[i]];
            for (int j = i + 1; j < p.second.size(); j++) if (!used[j]) {
                used[j] = 1, B[H-1-t] = A[p.second[j]];
                t++;
                recur2(recur2);
                t--;
                used[j] = 0;
            }
            used[i] = 0;
        };
        for (int i = 0; i < (flag ? p.second.size() : 1); i++) {
            if (flag) used[i] = 1, B[H / 2] = A[p.second[i]];
            recur2(recur2);
        }
    };
    recur(recur, 0, 0, 0);
    cout << "NO\n";
    return 0;
}

