                for (int y = 0; y < H; ++y) {
                    if (a[y][i] == a[H - y - 1][W - i - 1]) ++diff;
                    if (a[y][j] == a[H - y - 1][W - j - 1]) ++diff;
                }
                if (diff >= 0) {
                    score += diff;
                } else {
                    for (int y = 0; y < H; ++y) {
                        char c = a[y][i];
                        a[y][i] = a[y][j];
                        a[y][j] = c;
                    }
                }
            } else {
                int i = rando.next(H);
                int j = rando.next(H - 1);
                if (j >= i) ++j;
                int diff = 0;
                for (int x = 0; x < W; ++x) {
                    if (a[i][x] == a[H - i - 1][W - x - 1]) --diff;
                    if (a[j][x] == a[H - j - 1][W - x - 1]) --diff;
                }
                for (int x = 0; x < W; ++x) {
                    char c = a[i][x];
                    a[i][x] = a[j][x];
                    a[j][x] = c;
                }
                for (int x = 0; x < W; ++x) {
                    if (a[i][x] == a[H - i - 1][W - x - 1]) ++diff;
                    if (a[j][x] == a[H - j - 1][W - x - 1]) ++diff;
                }
                if (diff >= 0) {
                    score += diff;
                } else {
                    for (int x = 0; x < W; ++x) {
                        char c = a[i][x];
                        a[i][x] = a[j][x];
                        a[j][x] = c;
                    }
                }
            }
        }
        score = 0;
        for (int y = 0; y < H; ++y)
            for (int x = 0; x < W; ++x)
                if (a[y][x] == a[H - y - 1][W - x - 1]) ++score;
        cout << (score == W * H ? "YES" : "NO") << endl;
    }
    return 0;
}

