int H,W,match_r[20],match_c[20];
string grid[20];
bool ok;
bool check(){
	memset(match_c,-1,sizeof match_c);
	for(int i=0;i<W;i++){
		if(match_c[i]!=-1) continue;
		for(int j=0;j<W;j++){
			if(match_c[j]!=-1 || i==j) continue;
			bool succ=true;
			for(int k=0;k<H && succ;k++)
				if(grid[match_r[k]][i]!=grid[k][j])
					succ=false;
			if(succ) match_c[i]=j,match_c[j]=i;
		}
	}
	int unmatch=0,mid;
	for(int i=0;i<W;i++)
		if(match_c[i]==-1){
			unmatch++;
			mid=i;
		}
	if(unmatch>=2 || (unmatch && W%2==0)) return false;
	if(!unmatch) return true;
	for(int i=0;i<H;i++)
		if(grid[match_r[i]][mid]!=grid[i][mid])
			return false;
	return true;
}
void dfs(int now,bool is_skip){
	if(now>=(H+1)/2){
		if(check()) ok=true;
	}else{
		for(int i=now;i<H;i++){
			if(match_r[i]!=-1) continue;
			for(int j=i+1;j<H;j++){
				if(match_r[j]!=-1) continue;
				match_r[i]=j,match_r[j]=i;
				dfs(now+1,is_skip);
				match_r[i]=-1,match_r[j]=-1;
			}
			if(!is_skip && H&1){
				match_r[i]=i;
				dfs(now+1,true);
				match_r[i]=-1;
			}
		}
	}
}
