int H, W;
char S[12][12];

bool subsolve(vector<int> now){
  deque<int> deq;
  rep(i, H){
    if(i % 2){
      deq.push_front(now[i]);
    }else{
      deq.push_back(now[i]);
    }
  }

  char S_[W][H];

  rep(i, deq.size()){
    rep(j, W){
      S_[j][i] = S[deq[i]][j];
    }
  }
  vector<string> all;
  rep(i, W){
    string s = "";
    rep(j, H) s += S_[i][j];
    all.pb(s);
  }
  for(int i = 0; i < W; i++){
    if(all[i] == "") continue;
    string x = all[i];
    reverse(x.begin(), x.end());
    for(int j = i+1; j < W; j++){
      if(all[j] == "") continue;
      if(x == all[j]){
        all[i] = "";
        all[j] = "";
        break;
      }
    }
  }
  int cnt = 0;
  rep(i, W){
    if(all[i] != "") cnt++;
  }
  int odd = 0;
  if(W % 2){
    if(cnt <= 1){
      return true;
    }
    else return false;
  }else{
    if(cnt == 0) return true;
    else return false;
  }

  return 1;
}

bool solve(vector<int> rest, vector<int> now){
  if(rest.size() == 0){
    return subsolve(now);
  }else if(rest.size() % 2 == 1){
    bool res = false;
    for(int i = 0; i < rest.size(); i++){
      vector<int> nextrest = rest, nextnow = now;
      nextnow.pb(rest[i]);
      nextrest.erase(nextrest.begin() + i);
      res |= solve(nextrest, nextnow);
    }
    return res;
  }else{
    bool res = false;
    for(int i = 1; i < rest.size(); i++){
      vector<int> nextrest = rest, nextnow = now;
      nextnow.pb(rest[0]);
      nextnow.pb(rest[i]);
      nextrest.erase(nextrest.begin() + i);
      nextrest.erase(nextrest.begin() + 0);
      res |= solve(nextrest, nextnow);
    }
    return res;
  }
}

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  cin >> H >> W;
  rep(i, H)rep(j, W) cin >> S[i][j];
  vector<int> rest, now;
  rep(i, H){
    rest.pb(i);
  }
  if(solve(rest, now)){
    cout << "YES" << endl;
  }else{
    cout << "NO" << endl;
  }

}

