   for (int i = 0; i < v.size(); i++) { s << v[i]; if (i < v.size() - 1) s << " "; }
   s << "]";
   return s;
}

bool next(V<int>& perm) {
   int H = SZ(perm);
   if (perm[0] == -1) {       // initialize
      REP(i, H) {
         if (i % 2 == 0) {
            perm[i/2] = i;
         } else {
            perm[H-1-i/2] = i;
         }
      }
      return true;
   }

   V<int> tmp(H);
   REP(i, H) {
      if (i % 2 == 0) {
         tmp[i] = perm[i/2];
      } else {
         tmp[i] = perm[H-1-i/2];
      }
   }
   V<int> s;
   int MAX = 0;
   RFOR(i, 0, H) {
      s.PB(tmp[i]);
      if (i % 2 == 0 || MAX < tmp[i]) {
         MAX = max(MAX, tmp[i]);
         continue;
      }
      MAX = max(MAX, tmp[i]);

      SORT(s);
      int lb = LB(s, tmp[i]+1);
      tmp[i] = s[lb];
      int tmp_i = i+1;
      FOR(j, 0, SZ(s)) {
         if (j == lb) continue;
         tmp[tmp_i++] = s[j];
      }

      REP(i, H) {
         if (i % 2 == 0) {
            perm[i/2] = tmp[i];
         } else {
            perm[H-1-i/2] = tmp[i];
         }
      }
      return true;
   }
   return false;
}

template<typename T1, typename T2> ostream& operator << (ostream& s, const P<T1,T2>& p) {
   s << "(" << p.first << "," << p.second << ")";
   return s;
}


signed main()
{
   int H, W; cin >> H >> W;
   V<string> S(H);
   REP(i, H) {
      cin >> S[i];
   }

   V<int> perm(H,-1);

   while (next(perm)) {
      set<int> used;             // ペアにした列
      bool flag0 = true;         // 全てのj0 についてペアができるか
      bool used_alone = false;   // 対称なものは１つだけペアでなくても良い
      FOR(j0, 0, W) {
         if (EXIST(used, j0)) continue;
         FOR(j1, j0+1, W) {
            if (EXIST(used, j1)) continue;
            bool flag1 = true;               // 全てのi について対称か
            FOR(i, 0, H) {
               if (S[perm[i]][j0] != S[H-1-perm[i]][j1]) {
                  flag1 = false; break;            // 対称でないならbreak
               }
            }
            if (!flag1) continue;            // 対称でないならcontinue

            used.insert(j0); used.insert(j1);   // ペア形成
            break;
         }
         if (!EXIST(used, j0)) {             // j0 のペアがないとき
            if (used_alone) {                // ボッチ枠を既に使っていたらbreak
               flag0 = false; break;
            }
            bool sym = true;                 // 全てのi について対称か
            FOR(i, 0, H) {
               if (S[perm[i]][j0] != S[H-1-perm[i]][j0]) {
                  sym = false; break;        // 対称でないならbreak
               }
            }
            if (sym) {                       // 対称なら、ボッチ枠を使う
               used_alone = true;
            } else {
               flag0 = false; break;         // 対称でないなら、break
            }
         }
      }
      if (!flag0) continue;      // perm で点対称に出来ないならcontinue

      cout << "YES" << endl;
      return 0;
   }
   cout << "NO" << endl;

   return 0;
}

