// all ways to form pairs so that p[0] paired with p[n-1], p[1] with p[n-1], ...
void paired_permutations(int n, const function<void(vector<int>& p)>& f) {
    vector<int> p(n);
    iota(p.begin(), p.end(), 0);
    function<void(int)> rb = [&](int i) {
        if(i == n / 2) {
            f(p);
        } else {
            for(int j = i + 1; j < n - i; j++) {
                swap(p[j], p[n - 1 - i]);
                rb(i + 1);
                swap(p[j], p[n - 1 - i]);
            }
        }
    };
    rb(0);
}
