	int unmatch=0,mid=0;
	for(int i=0;i<W;i++)
		if(match_c[i]==-1){
			unmatch++;
			mid=i;
		}
	if(unmatch>=2 || (unmatch && W%2==0)) return false;
	if(!unmatch) return true;
	for(int i=0;i<H;i++)
		if(grid[match_r[i]][mid]!=grid[i][mid])
			return false;
	return true;
