        return check(perm);
    }
    perm.push_back(remainings.back());
    remainings.pop_back();
    REP(i, remainings.size()) {
        swap(remainings[i], remainings.back());
        perm.push_back(remainings.back());
        remainings.pop_back();
        if (solve(perm, remainings)) return 1;
        remainings.push_back(perm.back());
        perm.pop_back();
        swap(remainings[i], remainings.back());
    }
    remainings.push_back(perm.back());
    perm.pop_back();
    return 0;
}

