bool bar(int i, bool self) {
  if(i == m) return true;
  if(self) {
    bool ok = true;
    for(int j=0;j<n;j++) {
      if(s[j][i] == s[nm[j]][i]) continue;
      ok = false;
      break;
    }
    if(ok) {
      mm[i] = i;
      int j = i+1;
      while(mm[j]>=0) j++;
      if(bar(j,false)) return true;
      mm[i] = -1;
    }
  }
  for(int j=i+1;j<m;j++) {
    if(mm[j]>=0) continue;
    bool ok = true;
    for(int k=0;k<n;k++) {
      if(s[k][i] == s[nm[k]][j]) continue;
      ok = false;
      break;
    }
    if(ok) {
      mm[i] = j;
      mm[j] = i;
      int k = i+1;
      while(mm[k]>=0) k++;
      if(bar(k,self)) return true;
      mm[i] = mm[j] = -1;
    }
  }
  return false;
}

bool foo(int i, bool self) {
  if(i == n) return bar(0,m&1);
  if(self) {
    nm[i] = i;
    int j = i+1;
    while(nm[j]>=0) j++;
    if(foo(j,false)) return true;
    nm[i] = -1;
  }
  for(int j : g[i]) {
    if(nm[j]>=0) continue;
    nm[i] = j;
    nm[j] = i;
    int k = i+1;
    while(nm[k]>=0) k++;
    if(foo(k,self)) return true;
    nm[i] = nm[j] = -1;
  }
  return false;
}

