bool vis[15];
int ano[15], n, m; 
char str[15][15]; 
inline bool chk(int x, int y)
{
	for (int i = 0; i < m; i++)
	{
		if (str[x][i] != str[y][ano[i]])
			return false; 
	}
	return true;
}
inline void work()
{
	bool flg = false; 
	memset(vis, false, sizeof(vis)); 
	for (int i = 0; i < n; i++)
	{
		if (vis[i])
			continue; 
		for (int j = i + 1; j < n && !vis[i]; j++)
		{
			if (!vis[j] && chk(i, j))
				vis[i] = vis[j] = true; 
		}
		if (!vis[i] && (n & 1) && chk(i, i) && !flg)
			vis[i] = flg = true; 
		if (!vis[i])
			return; 
	}
	puts("YES"); 
	exit(0); 
}
void dfs(int cur)
{
	if (cur >= m / 2)
	{
		int pos = -1; 
		for (int i = 0; i < m; i++)
		{
			if (-1 == ano[i])
			{
				if (~pos)
					exit(-1); 
				ano[i] = i; 
				pos = i; 
			}
		}
		work(); 
		if (~pos)
			ano[pos] = -1; 
		return; 
	}
	int pos; 
	for (int i = 0; i < m; i++)
	{
		if (-1 == ano[i])
		{
			pos = i; 
			break; 
		}
	}
	for (int j = 0; j < m; j++)
	{
		if (~ano[j] || j == pos)
			continue; 
		ano[pos] = j; 
		ano[j] = pos; 
		dfs(cur + 1); 
		ano[pos] = ano[j] = -1; 
	}
}
int main()
{
	// freopen("ARC095-E.in", "r", stdin); 
	scanf("%d%d", &n, &m); 
	for (int i = 0; i < n; i++)
		scanf("%s", str[i]); 
	memset(ano, -1, sizeof(ano)); 
	dfs(0); 
	puts("NO"); 
	return 0; 
}

