bool check(const vector<pair<int, int>> &pv, const vector<string> &field) {
    int H = field.size();
    int W = field[0].size();

    vector<int> v(W, -1);
    vector<bool> used(W, false);

    FOR(i, 0, pv.size()) {
        v[i] = pv[i].first;
        v[v.size() - 1 - i] = pv[i].second;
        used[pv[i].first] = true;
        used[pv[i].second] = true;
    }

    if (W % 2 != 0) {
        assert(v[W / 2] == -1);
        FOR(j, 0, used.size()) {
            if (not used[j]) {
                v[W / 2] = j;
                break;
            }
        }
    }

    vector<int> used2(H, false);
    FOR(y1, 0, H) {
        if (used2[y1]) { continue; }

        FOR(y2, y1 + 1, H) {
            if (used2[y2]) { continue; }

            bool ok = true;
            FOR(x, 0, W) {
                ok &= field[y1][v[x]] == field[y2][v[W - 1 - x]];
            }
            if (ok) {
                used2[y1] = true;
                used2[y2] = true;
                break;
            }
        }
    }

    int num = 0;
    FOR(y, 0, used2.size()) {
        if (not used2[y]) {
            num++;
            FOR(x, 0, W) {
                if (field[y][v[x]] != field[y][v[W - 1 - x]]) {
                    return false;
                }
            }
        }
    }

    if (num >= 2) {
        return false;
    }

    if (H % 2 == 0 and num >= 1) {
        return false;
    }

    return true;

}

bool dfs(int idx, vector<bool> &used, vector<pair<int, int>> &pv, const vector<string> &field) {
    const int W = field[0].size();

    if (idx >= W / 2) {
        return check(pv, field);
    }

    int i = -1;
    FOR(j, 0, W) {
        if (not used[j]) {
            i = j;
            break;
        }
    }
    used[i] = true;

    bool ok = false;
    FOR(j, 0, W) {
        if (used[j]) { continue; }
        used[j] = true;

        pv.emplace_back(make_pair(i, j));
        ok |= dfs(idx + 1, used, pv, field);
        used[j] = false;
        pv.pop_back();
    }
    used[i] = false;

    return ok;
}

