int row_match[14];
// int row_match[14] = {5, 8, 6, 4, 3, 0, 2, 9, 1, 7, 11, 10};

bool make_col_match(){
    int bit = 0;
    bool is_odd = W % 2 == 1;
    for(int k=0;k<W;k++){
        if((bit>>k)&1) continue;

        bool added = false;
        for(int l=k+1;l<W;l++){
            if((bit>>l)&1) continue;
            bool ok = true;
            for(int i=0;i<H;i++){
                if(!(S[i][k] == S[row_match[i]][l] && S[i][l] == S[row_match[i]][k])){
                    ok = false;
                    break;
                }
            }
            if(ok){
                bit |= (1 << k);
                bit |= (1 << l);
                added = true;
                break;
            }
        }

        if(!added && is_odd){
            bool ok = true;
            for(int i=0;i<H;i++){
                if(S[i][k] != S[row_match[i]][k]){
                    ok = false;
                    break;
                }
            }
            if(ok){
                added = true;
                is_odd = false;
                bit |= (1 << k);
            }
        }

        if(!added) {
            return false;
        }
    }
    return true;
}

bool make_row_match(int bit, bool is_odd){
    if(bit == (1 << H) - 1) return make_col_match();

    int i = 0;
    while((bit>>i)&1) i++;

    if(is_odd){
        row_match[i] = i;
        if(make_row_match(bit | (1 << i), false)) return true;
    }

    for(int j=i+1;j<H;j++){
        if((bit>>j)&1) continue;
        row_match[i] = j;
        row_match[j] = i;
        if(make_row_match(bit | (1 << i) | (1 << j), is_odd)) return true;
    }

    return false;
}

