vector<pair<ll, vector<int>>> gen(int n, int m, int mid, int mask, int num) {
  vector <int> perm;
  for (int i = 0; i < n; ++i) {
    if (i == mid) { continue; }
    if (((mask >> i) & 1) != num) {
      perm.push_back(i);
    }
  }
  int k = int(perm.size());
  if (mid != -1) {
    perm.push_back(mid);
  }

  vector <pair<ll, vector<int>>> res;
  do {
    vector <int> cur(m, 0);
    for (int i = 0; i < m; ++i) {
      int curX = 0;
      for (int x : perm) {
        curX <<= 5;
        curX += (s[x][i] - 'a');
      }
      cur[i] = curX;
    }
    dbg("mid %d mask %d num %d perm = ", mid, mask, num);
    for (int x : perm) {
      dbg(" %d", x);
    }
    dbg(" res ");
    for (int x : cur) {
      dbg(" %d", x);
    }
    vector <int> cur2 = cur;
    sort(cur2.begin(), cur2.end());
    ll hash = 0;
    for (int x : cur2) {
      hash = hash * P + x;
    }
    dbg(" hash %lld\n", hash);
    res.push_back(make_pair(hash, cur));
  } while (next_permutation(perm.begin(), perm.begin() + k));
  sort(res.begin(), res.end());
  return res;
}

