            if (!tmp) continue;

            //COUT(kinshi);

            bool dp[5000];
            memset(dp, 0, sizeof(dp));
            dp[0] = true;
            for (int bit = 0; bit < (1<<W); ++bit) {
                if (!dp[bit]) continue;

                //cout << bitset<10>(bit) << endl;

                int f = 0;
