typedef pair<char, char> pcc;
Graph<char> g(12, vector<char>(12));
vector<pii> pairs;
bitset<12> rest;

bool dfs(Spacial<int> &det, Graph<bool> &bdet) {
  if (rest.count() < 2) {
    int w = det[0][0].size();
    vi arr(w, (1<<w)-1);
    for (auto &p : pairs) {
      if (!bdet[p.first][p.second]) return false;
      rep(i,w) {
        arr[i] &= det[p.first][p.second][i];
      }
    }
    if (rest.any()) {
      int idx = 0;
      while (!rest[idx]) ++idx;
      if (!bdet[idx][idx]) return false;
      rep(i,w) {
        arr[i] &= det[idx][idx][i];
      }
    }
    rep(i,w) {
      if (!arr[i]) return false;
    }
    return true;
  }

  int idx = 0;
  while (!rest[idx]) ++idx;
  rest[idx] = false;
  REP(i,idx+1,11) {
    if (rest[i]) {
      pairs.emplace_back(idx, i);
      rest[i] = false;
      if (dfs(det, bdet)) return true;
      rest[i] = true;
      pairs.pop_back();
    }
  }
  rest[idx] = true;
  return false;
}

bool row(int h, int w) {
  Spacial<int> det(h, Graph<int>(h, vi(w, 0)));
  Graph<bool> bdet(h, vb(h, true));

  rep(i,h) {
    map<char, int> self;
    rep(k,w) {
      self[g[i][k]] += 1<<k;
    }
    bool odd = false;
    for (auto &p : self) {
      bitset<12> s(p.second);
      if (s.count() & 1) {
        if (odd) {
          bdet[i][i] = false;
          break;
        }
        odd = true;
      }
      rep(k,w) {
        if (s[k]) {
          det[i][i][k] = p.second;
        }
      }
    }

    rep(j,i) {
      map<pcc, int> comb;
      rep(k,w) {
        comb[{g[i][k], g[j][k]}] += 1<<k;
      }
      bool odd = false;
      for (auto &p : comb) {
        pcc q = {p.first.second, p.first.first};
        bitset<12> s(p.second);
        if (!comb.count(q)) {
          bdet[i][j] = bdet[j][i] = false;
          break;
        }
        if (q.first == q.second) {
          if (s.count() & 1) {
            if (odd) {
              bdet[i][j] = bdet[j][i] = false;
              break;
            }
            odd = true;
          }
        } else if (__builtin_popcount(comb[q]) != s.count()) {
          bdet[i][j] = bdet[j][i] = false;
          break;
        }
        rep(k,w) {
          if (s[k]) {
            det[i][j][k] = det[j][i][k] = comb[q];
          }
        }
      }
    }
  }

  rest = (1<<h)-1;
  return dfs(det, bdet);
}

void solve() {
  int h, w; cin >> h >> w;
  rep(i,h) rep(j,w) cin >> g[i][j];

  CoutYN(row(h, w), "YES", "NO");
}


