int main(void){
    int H, W;
    int same = 0;
    cin >> H >> W;
    for (int i = 0; i < H; i++){
        for (int j = 0; j < W; j++){
            char x;
            cin >> x;
            input[i][j] = x;
            s[i][x]++;;
            tate[j][x]++;
        }
    }
    for (int i = 0; i < H; i++){
        for (int j = 0; j < H; j++){
            if (i == j && H != 1) continue;
            if (s[i] == s[j] || H == 1){
                for (int k = 0; k < W; k++){
                    for (int l = 0; l < W; l++){
                        if (tate[k].empty()) break;                        
                        if (k == l)break;
                        if (input[i][k] == input[j][l]){
                            if (tate[k] == tate[l]){
                                tate[k].clear();
                                tate[l].clear();
                                same++;
                                break;
                            }
                        }
                    }
                }
                goto END;
            }
        }
    }

    END :
    if (W % 2){
        if (W - same*2 != 1){
            cout << "NO" << endl;
            return 0;
        }
    }else{
        if (W - same*2){
            cout << "NO" << endl;
            return 0;
        }
    }
    cout << "YES" << endl;

    return 0;
}

