using namespace std;

const int MAXN = 13;

char a[MAXN][MAXN];
int cnt[26];

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int n, m;
    cin >> n >> m;
    for (int i = 0; i < n; ++i) for (int j = 0; j < m; ++j) cin >> a[i][j];
    for (int i = 0; i < n; ++i) for (int j = 0; j < m; ++j) ++cnt[a[i][j] - 'a'];

    int bad1 = 0;
    for (int i = 0; i < n; ++i) {
        bool bad = false;

        vector <int> nc(26);
        for (int j = 0; j < m; ++j) ++nc[a[i][j] - 'a'];
        for (int j = 0; j < 26; ++j) {
            if (cnt[j] < nc[j] * 2) bad = true;
        }

        bad1 += bad;
    }

    int bad2 = 0;
    for (int j = 0; j < m; ++j) {
        bool bad = false;

        vector <int> nc(26);
        for (int i = 0; i < n; ++i) ++nc[a[i][j] - 'a'];
        for (int i = 0; i < 26; ++i) {
            if (cnt[i] < nc[i] * 2) bad = true;
        }

        bad2 += bad;
    }

    int counter = 0;
    for (int i = 0; i < 26; ++i) {
        counter += (cnt[i] % 2);
    }

    if (n % 2 && m % 2) {
        if (1 < counter) {
            cout << "NO\n";
            return 0;
        }
    }
    else {
        if (counter) {
            cout << "NO\n";
            return 0;
        }
    }

    if (bad1 <= (n % 2) && bad2 <= (m % 2)) cout << "YES\n";
    else cout << "NO\n";

    return 0;
}

