string grid[NN+1];

string getCol(int c){
	string res; for(int i=1; i<=n; ++i) res += grid[i][c-1];
	// dump(c, res);
	return res;
}

bool checkCols(){
	// for(int i=1; i<=n; ++i) dump(grid[i]);
	// dump(ln);
	multiset<string> cols;
	for(int c=1; c<=m; ++c) cols.insert(getCol(c));

	bool foundPalind = false;
	while(!cols.empty()){
		string cur = *cols.begin();
		cols.erase(cols.find(cur));

		string rev = cur; reverse(all(rev));
		if(cols.find(rev) != cols.end()){
			cols.erase(cols.find(rev));
			continue;
		}

		if(!(cur == rev)) return false;
		if(foundPalind) return false;
		foundPalind = true;
	}

	return true;
}

bool possible(int i){
	int j = n-i+1;
	if(i >= j) return checkCols();
	for(int k = i+1; k<=j; ++k){
		// choosing pair(i,k)
		swap(grid[k], grid[j]);
		if(possible(i+1)) return true;
		swap(grid[k], grid[j]);
	}
	return false;
}

