    void check(vector<int>& v) {
      if (ret) return;

      vector<string> vs;
      rep(i, h) {
        string str;
        str.resize(w);
        int idx = 0;
        if (w%2 != 0) {
          str[w/2] = s[i][v[0]];
          idx++;
        }
        for(int j=0; j*2+1+idx<w; j++) {
          str[j] = s[i][v[j*2+idx]];
          str[w-1-j] = s[i][v[j*2+1+idx]];
        }
        //cerr << str << endl;
        vs.push_back(str);
      }

      vector<bool> checked(h);
      bool center = false;
      for(int i=0; i<h; i++) {
        if (checked[i]) continue;
        bool find = false;
        string vir = vs[i];
        reverse(all(vir));
        for(int j=i+1; j<h; j++) {
          if (checked[j]) continue;
          if (vir == vs[j]) {
            checked[i] = true;
            checked[j] = true;
            find = true;
            break;
          }
        }
        if (!find) {
          if (w%2 == 0) return;

          if (vs[i] == vir && !center) {
            checked[i] = true;
            center = true;
          } else {
            return;
          }
        }

      }


      ret = true;
    }

    void dfs(vector<int>& v) {
      if (ret) return;
      if (v.size() == w) {
        check(v);
        return;
      }

      for(int i=0; i<w; i++) {
        if (used[i]) continue;
        v.push_back(i);
        used[i] = true;
        dfs(v);
        used[i] = false;
        v.pop_back();
        // one of the pair can be defined.
        // the other is selected from all.
        if (w%2 != 0) {
          if (v.size()%2 != 0) break;
        } else {
          if (v.size()%2 == 0) break;
        }
      }
    }

