      SPEED;
      ret = false;
      cin >> h >> w;
      s.resize(h);
      rep(i, h) {
        cin >> s[i];
      }
      used.resize(w);
      vector<int> v;
      dfs(v);
      cout << (ret ? "YES" : "NO") << endl;
    }
};

