void aaa(vector<vector<int> >& temp,int H,int W){
	bool flag = true;
	while(flag){
		flag = false;
		int pos = -1;
		for(int i=0;i<W-1;++i){
			if( temp[0][i] > temp[0][i+1] ){
				flag = true;
				pos = i;
				break;
			}
		}
		if( flag ){
			for(int h=0;h<H;++h){
				swap(temp[h][pos],temp[h][pos+1]);
			}
		}
	}
}
bool check(vector<vector<int> >& temp,int H,int W){
	vector<vector<int> > org = temp;
	for(int h=0;h<H;++h){
		sort(temp[h].begin(),temp[h].end());
	}
	vector<int> Hpair(H,-1);
	for(int i=0;i<H;++i){
		if( Hpair[i] != -1 ){
			continue;
		}
		for(int j=i+1;j<H;++j){
			if( Hpair[j] != -1 ){
				continue;
			}
			vector<int> aite = temp[j];
			if( temp[i] == aite ){
				Hpair[i] = j;
				Hpair[j] = i;
				break;
			}
		}
	}
	int count = 0;
	int pos = -1;
	for(int i=0;i<H;++i){
		if(Hpair[i]==-1 ){
			pos = i;
			++count;
		}
	}
	if(H&1 ){
		if(count!=1){
			return false;
		}
		//横のチェック
		vector<int> TER = temp[pos];
		vector<int> tHist(26,0);
		int size = TER.size();
		for(int i=0;i<size;++i){
			tHist[TER[i]]++;
		}
		int todd = 0;
		for(int i=0;i<26;++i){
			if( tHist[i]&1 ){
				todd++;
			}
		}
		if(W&1){
			if(todd!=1){
				return false;
			}
		}else{
			if(todd){
				return false;
			}
		}
	}else{//横が偶数個
		if(count){//ペアを作れてないものがったらダメ
			return false;
		}
	}

	pos = 0;//再利用
	vector<vector<int> > ans(H,vector<int>(W));
	vector<bool> use(H,false);
	for(int i=0;i<H;++i){
		if( use[i] ){
			continue;
		}
		if( Hpair[i] == -1 ){
			ans[H/2] = org[i];
		}else{
			ans[pos] = org[i];
			int ter = Hpair[i];
			ans[H-1-pos] = org[ter];
			use[i] = true;
			use[ter] = true;
			++pos;
		}
	}
	temp = ans;
	return true;
}

bool cirCheck(vector<vector<int> > fld,int H,int W){
	int N = H*W;
	for(int i=0;i<=N/2;++i){
		int h = i/W;
		int w = i%W;
		if( fld[h][w] != fld[H-1-h][W-1-w] ){
			return false;
		}
	}
	return true;
}
vector<vector<int> > TR(vector<vector<int> >fld,int H,int W){
	vector<vector<int> > ans(W,vector<int>(H));
	for(int h=0;h<H;++h){
		for(int w=0;w<W;++w){
			ans[w][h] = fld[h][w];
		}
	}
	return ans;
}
void solve(){
	int H,W;
	cin>>H>>W;

	vector< vector<int> > fld(H,vector<int>(W) );
	vector<int> hist(26,0);
	for(int h=0;h<H;++h){
		string str;
		cin>>str;
		for(int w=0;w<W;++w){
			fld[h][w] = str[w]-'a';
			hist[ fld[h][w] ]++;
		}
	}

	//対応する値はある。
	//cerr<<"val OK\n";

	vector<vector<int> > temp = fld;
	bool fRes = check(temp,H,W);
	if(fRes == false ){
		cout<<"NO" << endl;
		return;
	}

	//転地して同じことやる。
	vector<vector<int> > tate(W,vector<int>(H));
	for(int h=0;h<H;++h){
		for(int w=0;w<W;++w){
			tate[w][h] = temp[h][w];//元の値を使う
		}
	}
	fRes = check(tate,W,H);
	if( fRes == false ){
		cout<<"NO" << endl;
		return;
	}

	vector<vector<int> > ans = TR(tate,W,H);
	bool resF = cirCheck(ans,H,W);
	if( resF == false ){
		cout << "NO" << endl;
		return;
	}

	cout << "YES" << endl;
}

