		if (i == p) continue;
		if (!eh[i][p]) continue;
		int mask1 = mask;
		mask1 ^= (1 << i);
		mask1 ^= (1 << p);
		st.pb(mp(p, i));
		rech(p + 1, mask1);
		st.pop_back();
	}
}

void recw(int p, int mask) {
	if (p == w + 1) {
		b.pb(st);
