using namespace std;
int main() {
	int H, W;
	cin >> H >> W;
	vector<string> S(H);
	for (int i = 0; i < H; ++i) cin >> S[i];
	function<bool(vector<int>)> solve = [&](vector<int> p) {
		if (p.size() == H) {
			vector<string> verti(W);
			for (int i = 0; i < W; ++i) {
				for (int j = 0; j < H; ++j) {
					verti[i] += S[p[j]][i];
				}
			}
			int cnt = 0;
			vector<bool> used(W);
			for (int i = 0; i < W; ++i) {
				if (used[i]) continue;
				string t = verti[i];
				reverse(t.begin(), t.end());
				for (int j = 0; j < W; ++j) {
					if (i != j && verti[j] == t && !used[j]) {
						used[i] = true;
						used[j] = true;
						cnt += 2;
						break;
					}
				}
			}
			if (W - cnt == 1) {
				for (int i = 0; i < W; ++i) {
					if (!used[i]) {
						string t = verti[i];
						reverse(t.begin(), t.end());
						if (t == verti[i]) ++cnt;
					}
				}
			}
			if (W == cnt) return true;
			return false;
		}
		int M = p.size();
		vector<bool> usedp(H);
		for (int i : p) usedp[i] = true;
		for (int i = 0; i < H; ++i) {
			if (usedp[i]) continue;
			bool ok = true;
			if (M >= 1 && M < H / 2 && p[M - 1] > i) ok = false;
			if (M > H - M - 1 && p[H - M - 1] > i) ok = false;
			if (ok) {
				p.push_back(i);
				if (solve(p)) return true;
				p.pop_back();
			}
		}
		return false;
	};
	bool ans = solve(vector<int>());
	cout << (ans ? "YES" : "NO") << endl;
	return 0;
}

