#include <bits/stdc++.h>
using namespace std;

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int H,W; cin >> H >> W;
    vector<string> S(H),T(H),U(H),V(W,""),X(W);
    for (int i=0;i<H;++i) cin >> S[i];
    for (int i=0;i<H;++i){
        T[i]=S[i]; sort(T[i].begin(),T[i].end());
    }
    int cnt=0,center=1,ok=1;
    vector<int> sym(H,-1);
    for (int i=0;i<H;++i){
        if (sym[i]>=0) continue;
        for (int j=i+1;j<H;++j){
            if (sym[j]>=0) continue;
            if (T[i]==T[j]){
                sym[j]=H-1-cnt;
                sym[i]=cnt++;
                break;
            }
        }
        if (sym[i]==-1){
            if (!center||!(H&1)) ok=0;
            else sym[(H-1)/2]=i,center=0;
        }
    }
    if (!ok){
        cout << "NO" << '\n';
        return 0;
    }
    for (int i=0;i<H;++i) U[sym[i]]=S[i];
    for (int i=0;i<W;++i){
        for (int j=0;j<H;++j) V[i]+=U[j][i];
        X[i]=V[i]; reverse(X[i].begin(),X[i].end());
    }
    center=-1; sym.assign(W,0);
    for (int i=0;i<W;++i){
        if (sym[i]) continue;
        for (int j=i+1;j<W;++j){
            if (sym[j]) continue;
            if (V[i]==X[j]){
                sym[i]=sym[j]=1;
                break;
            }
        }
        if (!sym[i]){
            if (center!=-1) ok=0;
            else center=i;
        }
    }
    if (center>=0&&V[center]!=X[center]) ok=0;
    cout << (ok?"YES":"NO") << '\n';
}

