void solve(int x)
{
	if(x>m)
	{
		map<string,int>mp;
		for(int i=1;i<=m;i++)used[i]=false;
		int k=1;
		for(int i=1;i<=m/2;i++)
		{
			while(k<=n && (used[k] || match[k]==k))k++;
		    used[k]=used[match[k]]=true;
		    seq[i]=k;
		    seq[m+1-i]=match[k];
		}
		for(int i=1;i<=n;i++)
		{
			string t="";
			for(int j=1;j<=m;j++)t+=s[i][seq[j]-1];
			mp[t]++;
		}
		int mark=0;
		for(int i=1;i<=n;i++)
		{
			string t1="",t2="";
			for(int j=1;j<=m;j++)t1+=s[i][seq[j]-1];
			for(int j=m;j>=1;j--)t2+=s[i][seq[j]-1];
			if(t1==t2)
			{
				if(mp[t1]&1)
				{
					if(mark)return;
					mark=i;
				}
				continue;
			}
			if(!mp[t2])
			{
				if(n&1)
				{
					if(mark)return;
					if(t1!=t2)return;
					mark=i;
				}
				else return;
			}
			else mp[t2]--;
		}
		printf("YES");
		exit(0);
	}
