void dfs(int p,int n){
    if(p!=n+1){
        int find = -1;
        for(int i = 1; i <= 2*n; i++){
            if(!vis[i]){
                find = i;
                break;
            }
        }
        vis[find] = 1;
        for(int i = 1; i <= 2*n; i++){
            if(!vis[i]){
                vis[i] = 1;
                pair[p][0] = find, pair[p][1] = i;
                dfs(p+1,n);
                vis[i] = 0;
            }
        }
        vis[find] = 0;
    }
    else{
        size++;
        for(int i = 1; i <= n; i++){
            keep[size].push_back(Pair(pair[i][0],pair[i][1]));
        }
    }
}

