int getEdge(std::vector<Pair>&pairs,int n,int m){
    for(int i = 1; i <= m; i++){
        for(int j = i; j <= m; j++){
            edge[i][j] = edge[j][i] = 1;
        }
    }
    for(Pair &p: pairs){
