        if(x>n || y>n) x = min(p.x,p.y), y = min(p.x,p.y);
        //printf("x = %d, y = %d\n",x,y);
        for(int i = 0; i < 26; i++) if(cnt[x][i]!=cnt[y][i]) return 0;
        for(int i = 1; i <= m; i++){
