                if(s[x][i]==s[y][j] && s[x][j]==s[y][i]){}
                else{ 
                    //printf("i = %d, j = %d\n",i,j);
                    edge[i][j] = edge[j][i] = 0;
                }
            }
        }
    }
    return 1;
}

