    cin >> h >> w;
    for (int i = 0; i < h; i++) {
        string s; cin >> s;
        for (int j = 0; j < w; j++) {
            v[i][j] = s[j];
        }
    }
    vector<int> s(h, -1);
    search(0, s);
    if (ans) cout << "YES" << endl;
    else cout << "NO" << endl;
}

