			if (cnt == M / 2) {
				cout << "YES";
				exit(0);
			}
		}	while (next_permutation(B, B + m));
		return;
	}
	int last = -1;
	if (n > 0) {
		last = A[n - 1];
	}
	for (int i = last + 1; i < N; i++) {
		A[n] = i;
		rec(n + 1);
		A[n] = 0;
	}
}

