	int dp[1<<12] = {};
	int pos[12][12] = {};
	for(int i = 0; i < N; i++){
		for(int j = 0; j < N; j++){
			pos[i][j] = 1;
			for(int k = 0; k < M; k++){
				if(D[i][k] != D[j][X[k]]) pos[i][j] = 0;
			}
//			printf("%d ", pos[i][j]);
		}
//		printf("\n");
	}
	dp[0] = 1;
	for(int i = 0; i+1 < 1<<N; i++){
		if(dp[i] == 0) continue;
		int v = 0;
		for(v = 0; i&1<<v; v++);
		for(int u = 0; u < N; u++){
			if(u == v || (1<<u&i) || !pos[u][v]) continue;
			dp[1<<u | 1<<v | i] = 1;
		}
	}
	int mx = (1<<N) - 1;
	if(N%2 == 1){
		for(int i = 0; i < N; i++){
			if(dp[mx^1<<i]) ans = 1;
		}
	}
	else{
		if(dp[mx]) ans = 1;
	}
}

