inline int mt(int a, int b) {
    return 1ll * a * b % mod;
}

inline int add(int a, int b) {
    a += b;
    if(a >= mod)
        a -= mod;
    if(a < 0)
        a += mod;
    return a;
}

inline int binpow(int n, int k) {
    int res = 1;
    while(k) {
        if(k & 1)
            res = mt(res, n);
        n = mt(n, n);
        k >>= 1;
    }
    return res;
}

