bool is_pal(string t) {
    for (int i = 0; i < t.size(); i++)
        if (t[i] != t[t.size() - i - 1])
            return false;
    return true;
}

bool rec(int i, int ct) {
    if (ct == n) {
        multiset<string> st;
        for (int j = 0; j < m; j++) {
            string t;
            for (int k = 0; k < n; k++) {
                t.push_back(s[a[k]][j]);
            }
            st.insert(t);
        }
        bool mid = false;
        while (st.size() > 1) {
            string t = *st.begin();
            st.erase(st.begin());
            reverse(all(t));

            if (st.count(t)) {
                st.erase(st.find(t));
            }
            else {
                if (n % 2) {
                    if (mid)
                        return false;
                    if (!is_pal(t))
                        return false;
                    mid = true;
                }
                else {
                    return false;
                }
            }
        }
        if (st.size() == 1)
            return is_pal(*st.begin());
        return true;
    }
    else if (used[i]) {
        if (rec(i + 1, ct))
            return true;
        return false;
    }
    else {
        used[i] = true;
        for (int j = i + 1; j < n; j++) {
            if (!used[j]) {
                used[j] = true;
                a[len] = i;
                a[n - len - 1] = j;
                len++;
                if (rec(i + 1, ct + 2))
                    return true;
                len--;
                used[j] = false;
            }
        }
        used[i] = false;
        return false;
    }
}

