#define REP(i, a, n) for(ll i = ((ll) a); i < ((ll) n); i++)
using namespace std;
typedef long long ll;

int main(void) {
  ll H, W;
  cin >> H >> W;
  char S[H][W];
  REP(i, 0, H) REP(j, 0, W) cin >> S[i][j];

  bool ok[H][W];
  REP(i, 0, H) REP(j, 0, W) ok[i][j] = false;
  ll N = H * W;
  REP(y1, 0, H) REP(y2, y1 + 1, H) REP(x1, 0, W) REP(x2, x1 + 1, W) {
    if(ok[y1][x1] || ok[y2][x2] || ok[y1][x2] || ok[y2][x1]) continue;
    if(S[y1][x1] == S[y2][x2] && S[y1][x2] == S[y2][x1]) {
      ok[y1][x1] = ok[y2][x2] = ok[y1][x2] = ok[y2][x1] = true;
    }
  }

  bool ans = true;
  ll okcnt = 0;
  REP(i, 0, H) REP(j, 0, W) if(ok[i][j]) okcnt++;
  if(H % 2 == 1 && W % 2 == 1) {
    if(okcnt != H * W - H - W + 1) ans = false;

    ll hh;
    REP(i, 0, H) {
      bool t = true;
      REP(j, 0, W) if(ok[i][j]) t = false;
      if(t) hh = i;
    }
    ll cnt1[256];
    REP(i, 0, 256) cnt1[i] = 0;
    REP(i, 0, W) cnt1[S[hh][i]]++;

    ll ww;
    REP(j, 0, W) {
      bool t = true;
      REP(i, 0, H) if(ok[i][j]) t = false;
      if(t) ww = j;
    }
    ll cnt2[256];
    REP(i, 0, 256) cnt2[i] = 0;
    REP(i, 0, H) cnt2[S[i][ww]]++;

    ll k1 = 0, k2 = 0;
    REP(i, 0, 256) if(cnt1[i] % 2 == 1) k1++;
    REP(i, 0, 256) if(cnt2[i] % 2 == 1) k2++;
    if(k1 == 1 && k2 == 1); else ans = false;
  } else if(H % 2 == 1) {
    if(okcnt != H * W - W) ans = false;

    set<ll> h;
    ll hh;
    REP(i, 0, H) REP(j, 0, W) if(!ok[i][j]) h.insert(i), hh = i;
    if(h.size() != 1) ans = false;
    ll cnt1[256];
    REP(i, 0, 256) cnt1[i] = 0;
    REP(i, 0, W) cnt1[S[hh][i]]++;
    REP(i, 0, 256) if(cnt1[i] % 2 == 1) ans = false;
  } else if(W % 2 == 1) {
    if(okcnt != H * W - H) ans = false;

    set<ll> w;
    ll ww;
    REP(i, 0, H) REP(j, 0, W) if(!ok[i][j]) w.insert(j), ww = j;
    if(w.size() != 1) ans = false;
    ll cnt2[256];
    REP(i, 0, 256) cnt2[i] = 0;
    REP(i, 0, H) cnt2[S[i][ww]]++;
    REP(i, 0, 256) if(cnt2[i] % 2 == 1) ans = false;
  } else {
    if(okcnt != H * W) ans = false;
  }
  cout << (ans ? "YES" : "NO") << endl;
}

#include <bits/stdc++.h>
#define int long long
using namespace std;

class Dinic{
public:

  struct edge{
    int to,cap,rev;
    edge(){};
    edge(int to,int cap,int rev):to(to),cap(cap),rev(rev){};
  };

  int V;
  vector<vector<edge> > G; //グラフの隣接リスト表現
  vector<int> level;       //sからの距離
  vector<int> iter;        //どこまで調べ終わったか
  int INF;

  Dinic():V(-1){};
  Dinic(int V,int INF=1e9):V(V),G(V),level(V),iter(V),INF(INF){}

  //fromからtoへ向かう容量capの辺をグラフに追加。
  void add_edge(int from,int to,int cap){
    assert(from < V && to < V);
    G[from].push_back(edge(to,cap,G[to].size()));
    G[to].push_back(edge(from,0,G[from].size()-1));
  }

  //sからの最短距離をBFSで計算する
  void bfs(int s){
    level.clear(); level.resize(V,-1);
    queue<int> que;
    level[s] = 0;
    que.push(s);
    while(!que.empty()){
      int v = que.front(); que.pop();
      for(edge &e : G[v])
        if(e.cap > 0 && level[e.to] < 0){
          level[e.to] = level[v] + 1;
          que.push(e.to);
        }
    }
  }

  //増加パスをDFSで探す。
  int dfs(int v,int t,int f){
    if(v==t) return f;
    for(int &i= iter[v]; i<(int)G[v].size(); i++){
      edge &e = G[v][i];
      if(e.cap > 0 && level[v] < level[e.to]){
        int d = dfs(e.to, t, min(f, e.cap));
        if(d > 0){
          e.cap -= d;
          G[e.to][e.rev].cap += d;
          return d;
        }
      }
    }
    return 0;
  }

  //sからtへの最大流を求める
  int max_flow(int s,int t){
    assert(V >= 0);
    int flow=0;
    for(;;){
      bfs(s);
      if(level[t] < 0) return flow;
      iter.clear();iter.resize(V,0);
      int f;
      while((f=dfs(s ,t ,INF)) > 0 ) flow += f;
    }
  }
};

int h, w, ans;
string s[12];

void solve(int A, int B, int cnt){

  Dinic dinic( h * w * 2 + 2 );

  int S = h * w * 2, T = S + 1;

  for(int i=0;i<h;i++){

    for(int j=0;j<w;j++){

      if( A == i || B == j ) continue;

      int idx = i * w + j;

      for(int ni=0;ni<h;ni++){

	for(int nj=0;nj<w;nj++){

	  if( A == ni || B == nj ) continue;

	  if( i == ni || j == nj ) continue;

	  int nidx = h * w + ni * w + nj;

	  if( idx >= nidx ) continue;

	  if( s[i][j] != s[ni][nj] ) continue;

	  dinic.add_edge( idx, nidx, 1 );

	}

      }

    }

  }

  for(int i=0;i<h*w;i++) dinic.add_edge( S, i, 1 );

  for(int i=h*w;i<S;i++) dinic.add_edge( i, T, 1 );

  if( dinic.max_flow( S, T ) == cnt ){

    int flag = 1;

    if( A != -1 ){

      int Cnt[300] = {}, odd = 0;

      for(int i=0;i<w;i++) Cnt[s[A][i]]++;

      for(int i=0;i<300;i++){
	if( Cnt[i] % 2 ) odd++;
      }

      if( w % 2 == 1 && odd != 1 ) flag = 0;

      if( w % 2 == 0 && odd != 0 ) flag = 0;     

    }

    if( B != -1 ){

      int Cnt[300] = {}, odd = 0;

      for(int i=0;i<h;i++) Cnt[s[i][B]]++;

      for(int i=0;i<300;i++){
	if( Cnt[i] % 2 ) odd++;
      }

      if( h % 2 == 1 && odd != 1 ) flag = 0;

      if( h % 2 == 0 && odd != 0 ) flag = 0;

    }

    if( flag ) ans = 1;

  }

}

signed main(){

  cin>>h>>w;

  for(int i=0;i<h;i++) cin>>s[i];

  int cnt = h * w;

  if( h%2 && w%2 ) cnt = cnt - h - w + 1;
  else if( h%2 ) cnt = cnt - w;
  else if( w%2 ) cnt = cnt - h;

  for(int i=0;i<h;i++){

    for(int j=0;j<w;j++){

      if( h%2 && w%2 ) solve( i, j, cnt );
      else if( h%2 ) solve( i, -1, cnt );
      else if( w%2 ) solve( -1, j, cnt );
      else solve( -1, -1, cnt );

    }

  }

  if( ans ) cout<<"YES"<<endl;
  else cout<<"NO"<<endl;

  return 0;
}

