bool ck(int u, int cnt) {
  if (u == n) { return cnt >= n / 2; }

  if (used[u]) {
    if (ck(u + 1, cnt)) return true;
    else return false;
  }

  if (n & 1) {
    if (e[u][u]) {
      used[u] = true;
      if (ck(u + 1, cnt)) return true;
      used[u] = false;
    }
  }

  for (int v = 0; v < n; ++v) {
    if (v != u && !used[v] && e[u][v]) {
      used[u] = used[v] = true;
      if (ck(u + 1, cnt + 1)) return true;
      used[u] = used[v] = false;
    }
  }

  return false;
}

