  int H,W; cin >> H >> W;
  string s[14],st[14],s2[14];
  rep(i,W) st[i] = string(H,' ');
  vi swapvec; 
  rep(i,H) cin >> s[i];
  bool tail = (H%2==1);
  int rest;
  function<bool()> check = [&]{
    // st を調べる
    bool once = (W%2==1);
    rep(j,W/2){
      bool update = false;
      string rs = st[j];
      rep(i,H/2) swap(rs[i],rs[H-1-i]);
      REP(k,j+1,W){
        if(rs==st[k]){
          swap(st[k],st[W-j-1]);
          update = true;
          break;
        }
      }
      if(update) continue;
      if(once){
        swap(st[j],st[W/2]);
        j--;
        once = false;
        continue;
      }
      return false;
    }
    if(W%2==1){
      string rs = st[W/2];
      rep(i,H/2) swap(rs[i],rs[H-1-i]);
      if(rs!=st[W/2]) return false;
    }
    return true;
  };
  function<bool(const vi&)> dfs = [&](const vi& v){
    if(swapvec.size() + (tail ? 1 : 0 )==H){
      if(tail) swapvec.pb(rest);
      rep(i,H/2){
        s2[i] = s[swapvec[2*i]];
        s2[H-i-1] = s[swapvec[2*i+1]];
      }
      if(H%2) s2[H/2] = s[swapvec[H-1]];
      // transpose
      rep(i,H) rep(j,W) st[j][i] = s2[i][j];
      if(tail) swapvec.pop_back();
      return check();
    }
    bool res = false;
    rep(i,v.size()){
      swapvec.pb(v[i]);
      vi nxt = v;
      nxt.erase(nxt.begin()+i);
      bool adnxt = nxt.size()>=1;
      if(adnxt){
        swapvec.pb(nxt[0]);
        nxt.erase(nxt.begin());
      }
      res |= dfs(nxt);
      swapvec.pop_back();
      if(adnxt) swapvec.pop_back();
    }
    return res;
  };
  bool ans = false;
  vi v(H);
  iota(v.begin(),v.end(),0);
  if(tail){
    rep(i,H){
      vi vec = v;
      rest = v[i];
      vec.erase(vec.begin()+i);
      swapvec.clear();
      if(vec.size()){
        swapvec.pb(vec[0]);
        vec.erase(vec.begin());
      }
      ans |= dfs(vec);
      assert(!ans);
    }
  }else{
    vi vec = v;
    swapvec.pb(vec[0]); vec.erase(vec.begin());
    ans |= dfs(vec);
  }
  cout << (ans ? "YES" : "NO") << endl;
  return 0;
}

