            int y = m - j  - 1;
            if (Map[i][loc[j]] != Map[x][loc[y]]) return false;
        }
    return true;
}

void DecideCol(int now){
    if (now == m - 1){
        if (CheckAll()) { printf("YES\n"); exit(0); }
        return ;
    }

    if (loc[now] != now) DecideCol(now + 1);
    else {
        for (int i = now + 1; i < m; i++) if (loc[i] == i){
            swap(loc[i], loc[now]);
            DecideCol(now + 1);
            swap(loc[i], loc[now]);
        }
        DecideCol(now + 1);
    }
}

void CheckCol(){
    for (int i = 0; i < m; i++) loc[i] = i;
    DecideCol(0);
}

void DecideRow(int now, int up, int down, int cnt){  // now 第几个集合，up上行，down下行，cnt这个集合已经用了多少个
    if (now > kS) { CheckCol(); return ; }
    if (up == down){                  // 单独处理奇集合
        for (int i = 0; i < S[now].size(); i++) if (!vis[S[now][i]]){
            Map[up] = s[S[now][i]];
            break;
        }
        DecideRow(now + 1, up + 1, down - 1, 0);
        return ;
    }
    for (int i = 0; i < S[now].size() - 1; i++) if (!vis[S[now][i]]){
        vis[S[now][i]] = true;
        Map[up] = s[S[now][i]];
        for (int j = i + 1; j < S[now].size(); j++) if (!vis[S[now][j]]){
            vis[S[now][j]] = true;
            Map[down] = s[S[now][j]];
            if (cnt + 2 == S[now].size()) DecideRow(now + 1, up + 1, down - 1, 0);
            else DecideRow(now, up + 1, down - 1, cnt + 2);
            vis[S[now][j]] = false;
        }
        vis[S[now][i]] = false;
    }
}

