bool check(int pos)
{
    if (pos == m + 1)
        return true;
    if (mpoint[pos])
        return check(pos + 1);
    for (int i = 1; i <= m; i++)
        if (mpoint[i] == 0)
        {
            bool flag = true;
            for (int j = 1; i <= n; i++)
                flag &= lmp[j][i] == lmp[n - j + 1][pos];
            if (i == pos && flag && (m & 1))
            {
                mpoint[pos] = i;
                if (check(pos + 1))
                    return true;
            }
            else if (flag)
            {
                mpoint[pos] = i, mpoint[i] = pos;
                if (check(pos + 1))
                    return true;
                mpoint[pos] = mpoint[i] = 0;
            }
        }
    return true;
}

bool dfs(int pos)
{
    if (pos == n + 1)
    {
        for (int i = 1; i <= n; i++)
            lmp[i] = mp[order[i]];
        return check(1);
    }
    if (order[pos] != 0)
        return dfs(pos + 1);
    int cnt = 0;
    for (int i = pos; i <= n; i++)
        if (order[i] == 0)
            cnt++;
    for (int i = pos; i <= n; i++)
        if (order[i] == 0)
        {
            order[pos] = i, order[i] = pos;
            if (((cnt & 1) || (i != pos)) && dfs(pos + 1))
                return true;
            order[pos] = order[i] = 0;
        }
    return false;
}

