const ll MOD=1e9+7;

int H;
int W;
int oppo[12];
char S[13][13];

LL mypow(LL base, LL exp) {
  if (exp == 0) return 1 % MOD;
  LL res = mypow(base*base%MOD, exp/2);
  if (exp%2) res = res*base%MOD;
  return res;
}

int Rank(vector<vector<LL>> &mat) {
  int n = mat.size();
  rep(i, n) {
    if (!mat[i][i]) {
      reps(j, i+1, n) {
        if (mat[j][i]) {
          rep(k, n) {
            swap(mat[i][k], mat[j][k]);
          }
          break;
        }
      }
    }

    if (!mat[i][i]) continue;
    LL v = mypow(mat[i][i], MOD-2);
    rep(k, n) (mat[i][k] *= v) %= MOD;
    assert(mat[i][i] == 1);
    rep(j, n) {
      if (i == j) continue;
      if (!mat[j][i]) continue;
      LL t = mat[j][i];
      rep(k, n) {
        mat[j][k] += MOD;
        mat[j][k] -= mat[i][k]*t % MOD;
        mat[j][k] %= MOD;
      }
      assert(mat[j][i] == 0);
    }
  }

  int ret = 0;
  rep(i, n) {
    if (mat[i][i]) ret++;
  }
  return ret/2;
}


void Try(vector<int> &p, vector<int> &q) {
  rep(i, H) oppo[i] = i;

  rep(i, H/2) {
    int a = p[i];
    int b = q[i];
    oppo[a] = b;
    oppo[b] = a;
  }

  vector<vector<LL>> mat(W, vector<LL>(W));
  rep(u, W) {
    mat[u][u] = 0;
    rep(v, u) {
      LL t = 1 + rand() % (MOD-1);
      mat[u][v] = t;
      mat[v][u] = MOD - t;
    }
  }

  rep(i, H) {
    int j = oppo[i];
    rep(k, W) {
      rep(l, k) {
        bool ok = true;
        ok &= S[i][k] == S[j][l];
        ok &= S[i][l] == S[j][k];

        if (!ok) mat[k][l] = mat[l][k] = 0;
      }
    }
  }

  if (Rank(mat) == W/2) {
    puts("YES");
    exit(0);
  }
}

void Brute(vector<int> &p, vector<int> &q) {
  do {
    Try(p, q);
  } while (next_permutation(all(q)));
}

void Dfs(int idx, vector<int> &p, vector<int> &q) {
  if (idx >= H) {
    if (p.size() == q.size() && p.size() == H/2) {
      Brute(p, q);
    }
    return;
  }

  if (p.size() < H/2) {
    p.eb(idx);
    Dfs(idx+1, p, q);
    p.pop_back();
  }

  if (q.size() < H/2) {
    q.eb(idx);
    Dfs(idx+1, p, q);
    q.pop_back();
  }
}

