	void solve(std::istream& cin, std::ostream& cout) {
		mem(used, 0); mem(pal, 0);
		int h, w; cin >> h >> w;
		char str[MN][MN];
		bool hOdd = (h&1), wOdd = (w&1);
		int cntPal=0;
		rep(i, 0, h){
			cin >> str[i];
			sort(str[i], str[i]+w);
			string s = string(str[i]);
			if(str[i] == string(s.rbegin(), s.rend())) ++cntPal, pal[i]=true;
