		auto exists = [&](string a){
			rep(i, 0, h){
				if(!used[i] && !pal[i] && a == str[i]) return true;
			}
			return false;
		};

		//equality check
		int usec=0;
		rep(i, 0, h){
			if(used[i] || pal[i]) continue;
			string a = str[i];
			if(exists(a)) used[i]=true, ++usec;
			else {cout << "NO" << endl; return; }
		}
		if(hOdd && usec != h-1) cout << "NO" << endl;
		else cout << "YES" << endl;
    }
};


