const int N=15;

char s[N][N];
int n,m;

bool vis[N];

struct judger
{
	char s[N],t[N],ds[N],dt[N];
	bool set(int p,int x)
	{
		ds[p]=s[x],dt[p]=t[x];

		int q=m-p+1;
		if(vis[q] && ds[p]!=dt[q])return 0;
		if(vis[q] && ds[q]!=dt[p])return 0;
		return 1;
	}
}d[N];

bool check(int p,int x)
{
	for(int i=1;i<=(n+1)/2;i++)
		if(!d[i].set(p,x))return 0;
	return 1;
}

bool used[N];
bool dfs(int p=1)
{
	for(int i=1;i<=m;i++)
		if(!used[i] && check(p,i))
		{
			used[i]=vis[p]=1;

			if(p==m/2+1)return 1;

			int nxt;
			if(p*2<=m)nxt=m-p+1;
			else nxt=m-p+2;
			if(dfs(nxt))return 1;

			used[i]=vis[p]=0;
		}
	return 0;
}

inline bool judge()
{
	return dfs();
}

bool ans;

bool mat[N];
void Dfs(int p=1,int cur=1)
{
	if(ans)return;

	if(p>n)
	{
		if(cur-1!=(n+1)/2)return;
		ans|=judge();
		return;
	}

	if(mat[p]){Dfs(p+1,cur);return;}

	for(int q=1;q<=n;q++)
		if(!mat[q])
		{
			mat[p]=mat[q]=1;
			for(int i=1;i<=m;i++)
				d[cur].s[i]=s[p][i],d[cur].t[i]=s[q][i];
			Dfs(p+1,cur+1);
			mat[p]=mat[q]=0;
		}
}

