        if (ss[k][i] == ss[H - 1 - k][j]) ++cnt;
      }
      if (cnt == H) used[i] = used[j] = true;
    }
  }
  for (int i = 0; i < W; ++i) {
    if (!used[i]) {
      for (int j = 0; j < H; ++j) {
