bool f(const vi& v) {
    bool used[20] = {};
    int unused = 0;
    for (int i = 0; i < W; i++) {
        if (used[i])
            continue;
        for (int j = i + 1; j < W; j++) {
            if (used[i] || used[j])
                continue;
            //i,j列
            bool flag = 1;
            for (int k = 0; k < H; k++) {
                if (S[v[k]][i] != S[v[H - k - 1]][j]) {
                    flag = 0;
                    break;
                }
            }
            if (flag) {
                used[i] = 1;
                used[j] = 1;
                break;
            }
        }
        if (!used[i])
            unused++;
        if (W % 2 == 1 && unused >= 2)
            return false;
        if (W % 2 == 0 && unused >= 1)
            return false;
    }

    int n = -1;
    for (int i = 0; i < W; i++) {
        if (!used[i]) {
            n = i;
        }
    }
    if (n >= 0) {
        for (int i = 0; i < H; i++) {
            if (S[v[i]][n] != S[v[H - i - 1]][n])
                return false;
        }
    }

    return true;
}

