	REP(i, W){
		FOR(j, i+1, W){
			if(!(now >> i & 1) && !(now >> j & 1)){
				if(pack[i][j]) dp[now] |= dfs2(now|(1<<i)|(1<<j));
			}
		}
	}
	return dp[now];
}

