    }

    if(w % 2 != 0){
        for(int x=0; x<w; ++x){
            string t(h, ' ');
            for(int y=0; y<h; ++y)
                t[y] = s[y][x];
            if(t == string(h, t[0])){
                for(int y=0; y<h; ++y)
                    s[y].erase(x);
                break;
            }
        }
        w = s[0].size();
        if(w % 2 != 0)
            return false;
    }

    return true;
}

bool check(const vector<string>& s)
{
    int h = s[0].size();
    int w = s.size();

    map<string, set<int> > index;
    for(int i=0; i<h; ++i){
        string t(w, ' ');
        for(int j=0; j<w; ++j)
            t[j] = s[j][i];
        index[t].insert(i);

        reverse(t.begin(), t.end());
        index[t].insert(i);
    }

    for(auto& p : index){
        if(p.second.size() % 2 != 0)
            return false;
    }
    return true;
}

bool dfs(const vector<string>& s, vector<bool>& isUsed, vector<int>& index)
{
    int n = s.size();
    int i = 0;
    while(i < n && isUsed[i])
        ++ i;

    if(i == n){
        vector<string> t(n);
        for(int j=0; j<n; ++j){
            if(j % 2 == 0)
                t[j/2] = s[index[j]];
            else
                t[n-1-j/2] = s[index[j]];
        }
        return check(t);
    }

    index.push_back(i);
    isUsed[i] = true;
    for(int j=i+1; j<n; ++j){
        if(!isUsed[j]){
            index.push_back(j);
            isUsed[j] = true;
            if(dfs(s, isUsed, index))
                return true;
            isUsed[j] = false;
            index.pop_back();
        }
    }
    isUsed[i] = false;
    index.pop_back();

    return false;
}

bool solve(vector<string> s)
{
    if(!preprocess(s))
        return false;

    int h = s.size();
    int w = s[0].size();

    vector<int> index;
    vector<bool> isUsed(h, false);
    return dfs(s, isUsed, index);
}

int main()
{
    int h, w;
    cin >> h >> w;
    vector<string> s(h);
    for(int i=0; i<h; ++i)
        cin >> s[i];

    if(solve(s))
        cout << "YES" << endl;
    else
        cout << "NO" << endl;

    return 0;
}

