    for(int i=0; i<16384; i++)pcnt[i]=__builtin_popcount(i);
    while(scanf("%d%d", &h, &w)!=EOF){
        for(int i=0; i<h; i++)
            scanf("%s", a[i]);
        if(bmatch((1<<w)-1, w&1)){
            printf("YES\n");
        }else{
            printf("NO\n");
        }
    }
    return 0;
}

