		int cnt = 0;
		memset(row, 0, sizeof(row));
		for (int i = 0; i < H; i++) {
			if (row[i]) continue;
			bool ok = 0;
			for (int j = i + 1; j < H; j++) {
				if (row[j]) continue;
				bool match = 1;
				for (int k = 0; k < W; k++) {
					if (T[i][k] != T[j][W - 1 - k]) {
						match = 0;
						break;
					}
				}
				if (match) {
					ok = 1;
					row[i] = row[j] = 1;
					break;
				}
			}
			if (!ok) {
				for (int j = 0; j < W; j++) if (T[i][j] != T[i][W - 1 - j]) return 0;
			}
			else cnt++;
		}
		if (cnt == H / 2) return 1;
		return 0;
	}
	for (int i = 0; i < W; i++) {
		if (used[i]) continue;
		used[i] = 1;
		perm[c] = i;
		for (int j = i + 1; j < W; j++) {
			if (used[j]) continue;
			used[j] = 1;
			perm[W - 1 - c] = j;
			if (check(c + 1)) return 1;
			used[j] = 0;
		}
		used[i] = 0;
	}
	return 0;
}
