		//cout<<vis[k]<<' '<<bad[k]<<' '<<k<<endl;
		return dfs1(k + 1, cnt);
	}
	vis[k] = 1; a[cnt].first = k;
	for(int i = k + 1; i <= N; ++i) {
		if(vis[i] || bad[i]) continue;
		vis[i] = 1; a[cnt].second = i;
		if(dfs1(k + 1, cnt + 1)) return true;
		vis[i] = 0;
	}
	vis[k] = 0;
	return false;
}

