void gen(int x){
    if (x % 2){
        for (int i = 1; i <= m; i++){
            if (!used[i]){
                used[i] = 1;
                p[(m + 1) / 2] = i;
                for (int j = 1; j <= n; j++){
                    b[j] += bb[(m + 1) / 2] * a[j][i];
                    c[j] += bb[m - (m + 1) / 2 + 1] * a[j][i];
                }
                gen(x - 1);
                for (int j = 1; j <= n; j++){
                    b[j] -= bb[(m + 1) / 2] * a[j][i];
                    c[j] -= bb[m - (m + 1) / 2 + 1] * a[j][i];
                }
                used[i] = 0;
            }
        }
