                } 
                int w = -1;
                int res = 1;
                for (int j = 1; j <= n; j++){
                    if (c[j] == b[j]){
                        if (cnt1[c[j]] % 2 != 0){
                            if (w == -1 || w == c[j]){
                                w = c[j];
                                continue;
                            }
                            res = 0;
                            break;
                        }
