            } else{
                cnt1.clear();
                cnt2.clear();
                for (int j = 1; j <= n; j++){
                    cnt1[b[j]]++;
                    cnt2[c[j]]++;
                }
                int res = 1;
                for (int i = 1; i <= n; i++){
                    if (c[i] == b[i]){
                        if (cnt1[c[i]] % 2 != 0){
                            res = 0;
                            break;
                        }
                    } else if (cnt1[c[i]] != cnt2[c[i]]){
                        res = 0;
                        break;
                    }
                }
                if (res){
                    cout << "YES";
                    exit(0);
                }
            }
        } else{
            for (int i = 1; i <= m; i++){
                if (used[i]) continue;
                for (int j = i + 1; j <= m; j++){
                    if (used[j]) continue;
                    used[i] = 1;
                    used[j] = 1;
                    int q = (m - x) / 2 + 1;
                    p[q] = i;
                    p[m - q + 1] = j;
                    for (int l = 1; l <= n; l++){
                        b[l] += bb[q] * a[l][i];
                        b[l] += bb[m - q + 1] * a[l][j];
                        c[l] += bb[m - q + 1] * a[l][i];
                        c[l] += bb[q] * a[l][j];
                    }
                    gen(x - 2);
                    used[i] = 0;
                    used[j] = 0;
                    for (int l = 1; l <= n; l++){
                        b[l] -= bb[q] * a[l][i];
                        b[l] -= bb[m - q + 1] * a[l][j];
                        c[l] -= bb[m - q + 1] * a[l][i];
                        c[l] -= bb[q] * a[l][j];
                    }
                }
            }
        }
    }
