bool rec(vector<ll> l, vector<ll> r, int bit, int depth = 0){
	if(bit == 0){
		int b = (1 << w) - 1;
		rep(i, w / 2){
			rep(j, w) if(b >> j & 1) rep(k, j) if(b >> k & 1){
				if(l[j] == r[k] && l[k] == r[j]){
					b -= 1 << j | 1 << k;
					goto NEXT;
				}
			}
			NEXT:;
		}
		if(__builtin_popcount(b) != w % 2) return 0;
		rep(i, w) if(b >> i & 1) if(l[i] != r[i]) return 0;
		return 1;
	}

	if(__builtin_popcount(bit) == 1){
		rep(i, h) if(bit >> i & 1){
			rep(k, w){
				l[k] += pw[depth] * (s[i][k] - 'a');
				r[k] += pw[depth] * (s[i][k] - 'a');
			}
			if(rec(l, r, 0)) return 1;
			rep(k, w){
				l[k] -= pw[depth] * (s[i][k] - 'a');
				r[k] -= pw[depth] * (s[i][k] - 'a');
			}
			return 0;
		}
	}

	rep(i, h) if(bit >> i & 1){
		for(int j = i + 1; j < h; j++) if(bit >> j & 1) if(can[i][j]){
			rep(k, w){
				l[k] += pw[depth] * (s[i][k] - 'a');
				r[k] += pw[depth] * (s[j][k] - 'a');
			}
			if(rec(l, r, bit ^ 1 << i ^ 1 << j, depth + 1)) return 1;
			rep(k, w){
				l[k] -= pw[depth] * (s[i][k] - 'a');
				r[k] -= pw[depth] * (s[j][k] - 'a');
			}
		}
		return 0;
	}
}
