map<int, set<pair<long long,long long>>> A;
void f(int n, int visited, pair<long long,long long> h) {
	if (n == 0) {
		A[visited].insert(h);
		return;
	}
	for (int i = 0; i < H; ++ i) if (!((visited>>i)&1)) {
		long long hh1 = 787662783788549761LL*h.first + SS[i].first;
		long long hh2 = 6582952005840035281LL*h.second + SS[i].second;
		f(n-1, visited|(1<<i), {hh1,hh2});
	}
}
bool g(int mask) {
	for (const auto& a : A) {
		int v1 = a.first;
		if ((v1&mask) != v1) continue;
		int v2 = mask&~v1;
		for (auto h : a.second) {
			if (A[v2].count(h)) return true;
		}
	}
	return false;
}
bool solve() {
	int mask = (1<<H)-1;
	if (H % 2 == 0) return g(mask);
	for (int i = 0; i < H; ++ i) {
		map<char,int> a;
		for (char c : S[i]) ++ a[c];
		int cnt = 0;
		for (auto p : a) if (p.second % 2 != 0) ++ cnt;
		if (cnt > 1) continue;
		if (g(mask&~(1<<i))) return true;
	}
	return false;
}
