Graph<char> g(12, vector<char>(12));

bool row(int h, int w) {
  Graph<bool> det(h, vb(h, false));

  rep(i,h) {
    set<char> self;
    rep(k,w) {
      char &c = g[i][k];
      if (self.count(c)) self.erase(c);
      else self.emplace(c);
    }
    if (self.size() < 2) {
      det[i][i] = true;
    }

    rep(j,i) {
      multiset<pair<char, char>> comb;
      rep(k,w) {
        char &c = g[i][k], &d = g[j][k];
        if (comb.count({d, c})) comb.erase(comb.find({d, c}));
        else comb.emplace(c, d);
      }
      if (comb.size() == 0 || (comb.size() == 1 && begin(comb)->first == begin(comb)->second)) {
        det[i][j] = det[j][i] = true;
      }
    }
  }

  Graph<bool> dp(h+1, vb(1<<h, false));
  dp[0][0] = true;
  rep(i,h) {
    rep(j,1<<i) {
      if (!dp[i][j]) continue;
      bitset<12> s(j);
      rep(k,i) {
        if (s[k] && det[i][k]) {
          dp[i+1][j-(1<<k)] = true;
        }
      }
      dp[i+1][j+(1<<i)] = true;
    }
  }

  if (dp[h][0]) return true;

  rep(i,h) {
    if (dp[h][1<<i] && det[i][i]) return true;
  }

  return false;
}

bool column(int h, int w) {
  rep(i,12) rep(j,i) swap(g[i][j], g[j][i]);

  return row(w, h);
}

void solve() {
  int h, w; cin >> h >> w;
  rep(i,h) rep(j,w) cin >> g[i][j];

  CoutYN(row(h, w) && column(h, w), "YES", "NO");
}


