typedef pair<int,int> pint;

int H, W;
vector<string> S;

vector<vector<pint> > tmps;
void dfs(int n, vector<pint> vec, set<int> rem) {
    if (rem.empty()) {
        tmps.push_back(vec);
        return;
    }
    int f = *(rem.begin());
    rem.erase(f);

    if (rem.empty()) {
        vec.push_back(pint(f, f));
        dfs(n, vec, rem);
    }
    else {
        set<int> nrem = rem;
        EACH(it, nrem) {
            int s = *it;
            vec.push_back(pint(f, s));
            rem.erase(s);
            dfs(n, vec, rem);
            vec.pop_back();
            rem.insert(s);
        }
    }
}

vector<vector<pint> > makecups(int n) {
    set<int> rem;
    for (int i = 0; i < n; ++i) rem.insert(i);
    vector<pint> vec;
    tmps.clear();
    dfs(n, vec, rem);
    return tmps;
}

int main() {
    while (cin >> H >> W) {
        vector<vector<pint> > hp = makecups(H), wp = makecups(W);
        set<vector<pint> > sp;
        for (auto i : wp) sp.insert(i);

        /*
        COUT(hp);
        COUT(wp);

        COUT(hp.size());
         */

        S.resize(H);
        for (int i = 0; i < H; ++i) cin >> S[i];

        bool res = false;
        for (auto hps : hp) {
            set<pint> kinshi;

            bool tmp = true;

            for (int i = 0; i < hps.size(); ++i) {
                if (!tmp) break;
                string s1 = S[hps[i].first];
                string s2 = S[hps[i].second];

                map<char,int> m1, m2;
                for (auto c : s1) m1[c]++;
                for (auto c : s2) m2[c]++;
                if (m1 != m2) tmp = false;

                for (int i = 0; i < s1.size(); ++i) {
                    for (int j = i; j < s1.size(); ++j) {
                        bool ok = true;
                        if (s1[i] != s2[j]) ok = false;
                        if (s1[j] != s2[i]) ok = false;

                        if (ok) {
                            kinshi.insert(pint(i, j));
                        }
                    }
                }
            }

            if (!tmp) continue;

            bool dp[5000];
            memset(dp, 0, sizeof(dp));
            dp[0] = true;
            for (int bit = 0; bit < (1<<W); ++bit) {
                if (!dp[bit]) continue;
                int f = 0;
                for (f = 0; f < W; ++f) {
                    if (bit & (1<<f)) continue;
                    else break;
                }
                if (f == W) break;
                for (int s = f; s < W; ++s) {
                    if (bit & (1<<s)) continue;
                    if (kinshi.count(pint(f, s))) continue;
                    int nbit = bit | (1<<f) | (1<<s);
                    dp[nbit] = true;
                }
            }
            if (dp[(1<<W)-1]) {
                res = true;
            }
        }

        if (res) puts("YES");
        else puts("NO");
    }
}

