#include <bits/stdc++.h>
using namespace std;

int h, w;
mt19937 ei(1333333);

bool check(vector<string> s) {
  int h = s.size();
  vector<string> t = s;
  for (auto &i : t) reverse(i.begin(), i.end());

  int cnt = 0;
  vector<bool> used(h);
  for (int i = 0; i < h; ++i) {
    if (used[i]) continue;
    for (int j = i + 1; j < h; ++j) {
      if (used[j]) continue;
      if (s[i] == t[j]) {
        used[i] = used[j] = true;
        cnt += 2;
        break;
      }
    }
  }

  if (h - cnt >= 2) return false;

  if (h & 1) {
    for (int i = 0; i < h; ++i) {
      if (used[i]) continue;
      if (s[i] == t[i]) cnt++;
    }
  }

  return cnt == h;
}

bool solve(vector<string> &t, int q = 400000) {
  vector<string> s = t;
  vector<int> v(w);
  for (int i = 0; i < w; ++i) v[i] = i;
  while (q--) {
    //怒りの乱択
    if (check(s)) return true;
    shuffle(v.begin(), v.end(), ei);
    for (int i = 0; i < h; ++i) {
      for (int j = 0; j < w; ++j) {
        s[i][j] = t[i][v[j]];
      }
    }
  }

  return false;
}

int main() {
  cin >> h >> w;

  vector<string> s(h);
  for (auto &i : s) cin >> i;

  cout << (solve(s) ? "YES" : "NO") << endl;
}

