vector < vector < int > > gen_perm(int h) {
    vector < int > to(h, -1);
    vector < vector < int > > ans;
    ans.emplace_back(to);
    for (int i = 0; i < h; i++) {
        vector < vector < int > > nans;
        for (auto& vec : ans) {
            if (vec[i] != -1) {
                nans.emplace_back(vec);
                continue;
            }
            bool has = false;
            for (int r = 0; r < h; r++) {
                if (vec[r] == r) {
                    has = true;
                    break;
                }
            }
            if (h % 2 == 0) {
                assert(!has);
                for (int c = i + 1; c < h; c++) {
                    if (vec[c] != -1) continue;
                    auto nvec = vec;
                    nvec[i] = c;
                    nvec[c] = i;
                    nans.emplace_back(nvec);
                }
            }
            else {
                for (int c = i; c < h; c++) {
                    if (vec[c] != -1) continue;
                    if (c == i && has) continue;
                    auto nvec = vec;
                    nvec[i] = c;
                    nvec[c] = i;
                    nans.emplace_back(nvec);
                }
            }
        }
        ans = nans;
    }
    return ans;
}
