bool isPalindromic(const std::string& s) {
	size_t sn = s.size();
	size_t n = sn / 2;
	for (size_t i = 0; i < n; ++i) {
		if (s[i] != s[sn - i - 1]) return false;
	}
	return true;
}

bool check(int h, int w, std::vector<std::string> s) { // O(H!W!HW)
	return [&] {
		std::vector<int> v(h);
		std::iota(ALL(v), 0);
		do {
			std::vector<int> u(w);
			std::iota(ALL(u), 0);
			do {
				bool conti = [&] {
					REP(i, h) REP(j, w) {
						if (s[v[i]][u[j]] != s[v[h - i - 1]][u[w - j - 1]]) return true;
					}
					return false;
				}();
				if (conti) continue;
				else return true;
			} while (std::next_permutation(ALL(u)));
		} while (std::next_permutation(ALL(v)));
		return false;
	}();
}

bool solve(int h, int w, std::vector<std::string> s) {
	std::vector<int> vc(w);
	std::iota(ALL(vc), 0);
	REP(j, w) vc[j] /= 2;
	do {
		{
			bool ok = true;
			int p = 0;
			REP(i, w) {
				if (w % 2 == 1 && vc[i] == w / 2) continue;
				if (vc[i] < p) continue;
				if (vc[i] == p) { ++p; continue; }
				ok = false;
				break;
			}
			if (!ok) continue;
		}
		std::vector<int> v(vc);
		{
			std::vector<int> cnt((w + 1) / 2, 0);
			REP(j, w) {
				if (cnt[v[j]] == 0) ++cnt[v[j]];
				else v[j] = w - v[j] - 1;
			}
		}

		std::map<std::string, int> map;
		REP(i, h) {
			std::string ss(w, ' ');
			REP(j, w) ss[v[j]] = s[i][j];
			++map[ss];
		}
		int odd = h % 2;
		bool ok = true;
		for (auto& x : map) {
			if (isPalindromic(x.first)) {
				if (x.second % 2 == 1) --odd;
				continue;
			}
			auto ss(x.first);
			std::reverse(ALL(ss));
			if (x.second != map[ss]) {
				ok = false;
				break;
			}
		}
		if (!ok || odd != 0) continue;
		return true;
	} while (std::next_permutation(ALL(vc)));
	return false;
}

