bool dfs(int n, vector<bool> used, vector<pii> p){
  if(p.size() == w/2+(w%2)){
    return ok(p);
  }
  used[n] = true;
  if(p.size()*2+1==w){
    vector<pii> tmp = p;
    tmp.push_back(pii(n,n));
    return ok(tmp);
  }
  FOR(i,n+1,w){
    if(used[i]) continue;
    vector<pii> tmp = p;
    vector<bool> tmp_u = used;
    tmp.push_back(pii(n,i));
    tmp_u[i] = true;
    FOR(j,n+1,w){
      if(j!=w-1 && tmp_u[j]) continue;
      if(dfs(j,tmp_u, tmp)){
        return true;
      }
    }
  }
  return false;
}


