using namespace std;

const int N = 15;
const int base = 233;

int n, m, a[N][N];
ull hash1[N], hash2[N], Hash[N], Pow[N];
char s[N][N], s1[N];

inline void add(int x, int y)
{
	y--;
	for(int i = 1; i <= m; i++)
	{
		hash1[i] += (s[x][i] - 'a' + 1) * Pow[y];
		hash2[i] += (s[x][i] - 'a' + 1) * Pow[n - y - 1];
	}
}

inline void del(int x, int y)
{
	y--;
	for(int i = 1; i <= m; i++)
	{
		hash1[i] -= (s[x][i] - 'a' + 1) * Pow[y];
		hash2[i] -= (s[x][i] - 'a' + 1) * Pow[n - y - 1];
	}
}

void dfs(int deep)
{
	if(deep * 2 + 1>= n)
	{
		sort(hash1 + 1, hash1 + 1 + m);
		sort(hash2 + 1, hash2 + 1 + m);
		for(int i = 1; i <= m; i++)
			if(hash1[i] != hash2[i])return;
		puts("YES");
		exit(0);
	}
	int nown = n - deep * 2;
	for(int i = 1; i <= nown; i++)
		for(int j = i + 1; j <= nown; j++)
		{
			int x = a[deep][i], y = a[deep][j];
			if(Hash[x] != Hash[y])continue;
			int cnt = 0;
			for(int k = 1; k <= nown; k++)
				if(a[deep][k] != x && a[deep][k] != y)a[deep + 1][++cnt] = a[deep][k];
			add(x, deep + 1);
			add(y, n - deep);
			dfs(deep + 1);
			del(x, deep + 1);
			del(y, n - deep);
		}
}

int main()
{
	scanf("%d%d", &n, &m);
	Pow[0] = 1;
	for(int i = 1; i <= n; i++)
		Pow[i] = Pow[i - 1] * base;
	for(int i = 1; i <= n; i++)
	{
		scanf("%s", s[i] + 1);
		for(int j = 1; j <= m; j++)
			s1[j] = s[i][j];
		sort(s1 + 1, s1 + 1 + m);
		ull nowhash = 0;
		for(int j = 1; j <= m; j++)
			nowhash = nowhash * base + (s1[j] - 'a' + 1);
		Hash[i] = nowhash;
		a[0][i] = i;
	}
	dfs(0);
	puts("NO");
}

