const int N = 15;

int n, m;
char s[N][N], s2[N][N];

int main() {

#ifdef debug
    freopen("input.txt", "r", stdin);
#endif

    scanf("%d %d", &n, &m);

    for(int i = 0;i < n;i++) {
        scanf("%s", s[i]);
    }

    if(n < m) { // transpose
        for(int i = 0;i < n;i++) {
            for(int j = 0;j < m;j++) {
                s2[j][i] = s[i][j];
            }
        }
        swap(n, m);
        for(int i = 0;i < n;i++) {
            for(int j = 0;j < m;j++) {
                s[i][j] = s2[i][j];
            }
        }
    }

    if(m == 1 || n == 1) {
        int cnt[26];
        for(int i = 0;i < n;i++) {
            for(int j = 0;j < m;j++) {
                cnt[s[i][j] - 'a']++;
            }
        }
        int cnt1 = 0;
        for(int i = 0;i < 26;i++) {
            if(cnt[i] & 1) {
                cnt1++;
            }
        }
        if(cnt1 > 1) {
            puts("NO");
        }else {
            puts("YES");
        }
        return 0;
    }

    int l0 = (m + 1) / 2;
    for(int m1 = 0;m1 < (1 << m);m1++) {
        if(__builtin_popcount(m1) != l0) continue;
        vec< int > L, R;
        for(int j = 0;j < m;j++) {
            if((1 << j) & m1) {
                L.push_back(j);
            }else {
                R.push_back(j);
            }
        }
        vec< int > perm(l0);
        for(int i = 0;i < l0;i++) {
            perm[i] = i;
        }
        do{
            vec< pair< string, string > > a1(n), a2(n);
            for(int i = 0;i < n;i++) {
                string t1(l0, '?'), t2(l0, '?');
                for(int j = 0;j < l0;j++) {
                    t1[j] = s[i][L[perm[j]]];
                }
                if(m & 1) {
                    t2[0] = s[i][L[perm[l0 - 1]]];
                    for(int j = 0;j < l0 - 1;j++) {
                        t2[j] = s[i][R[j]];
                    }
                }else {
                    for(int j = 0;j < l0;j++) {
                        t2[j] = s[i][R[j]];
                    }
                }
                a1[i] = make_pair(t1, t2);
                reverse(ALL(t1));
                reverse(ALL(t2));
                a2[i] = make_pair(t2, t1);
            }
            sort(ALL(a1));
            sort(ALL(a2));
            int ok = 1;
            for(int i = 0;i < n;i++) {
                if(a1[i] != a2[i]) {
                    ok = 0;
                    break;
                }
            }
            if(ok) {
                puts("YES");
                return 0;
            }
        }while(next_permutation(ALL(perm)));
    }

    puts("NO");

    return 0;
}

