#include<bits/stdc++.h>
using namespace std;
const int N=13;
typedef unsigned long long ull;
ull base=233,inv=7204522363551799129;
int n,m;
char s[N][N];
unordered_map<ull,int>vis;
bool judge(int x)
{
    vector<int>v1,v2;
    for(int i=1;i<=n;i++)
        if(x>>i-1&1)
        v1.push_back(i);
    else v2.push_back(i);
    while(true)
    {
        if(m&1)
        {
            for(int k=1;k<=m;k++)
            {
                ull hs1=0,hs2=0;
                for(int j=0;j<v1.size();j++)
                    hs1=hs1*base+s[v1[j]][k]-'a'+1;
                for(int j=0;j<v2.size();j++)
                    hs1=hs1*base+s[v2[j]][k]-'a'+1;
                for(int j=v2.size()-1;j>=0;j--)
                    hs2=hs2*base+s[v2[j]][k]-'a'+1;
                for(int j=v1.size()-1;j>=0;j--)
                    hs2=hs2*base+s[v1[j]][k]-'a'+1;
                if(hs1==hs2)
                {
                    vis.clear();
                    int tot=0;
                    for(int i=1;i<=m;i++)
                    {
                        if(i==k) continue;
                        ull hs=0;
                        for(int j=0;j<v1.size();j++)
                            hs=hs*base+s[v1[j]][i]-'a'+1;
                        for(int j=0;j<v2.size();j++)
                            hs=hs*base+s[v2[j]][i]-'a'+1;
                        if(vis[hs])
                            tot++,vis[hs]--;
                        else
                        {
                            hs=0;
                            for(int j=v2.size()-1;j>=0;j--)
                                hs=hs*base+s[v2[j]][i]-'a'+1;
                            for(int j=v1.size()-1;j>=0;j--)
                                hs=hs*base+s[v1[j]][i]-'a'+1;
                            vis[hs]++;
                        }
                    }
                    if(tot==m/2) return true;
                }
            }
        }
        else
        {
            vis.clear();
            int tot=0;
            for(int i=1;i<=m;i++)
            {
                ull hs=0;
                for(int j=0;j<v1.size();j++)
                    hs=hs*base+s[v1[j]][i]-'a'+1;
                for(int j=0;j<v2.size();j++)
                    hs=hs*base+s[v2[j]][i]-'a'+1;
                if(vis[hs])
                    tot++,vis[hs]--;
                else
                {
                    hs=0;
                    for(int j=v2.size()-1;j>=0;j--)
                        hs=hs*base+s[v2[j]][i]-'a'+1;
                    for(int j=v1.size()-1;j>=0;j--)
                        hs=hs*base+s[v1[j]][i]-'a'+1;
                    vis[hs]++;
                }
            }
            if(tot==m/2) return true;
        }
        if(!next_permutation(v2.begin(),v2.end())) break;
    }
    return false;
}
