#include <bits/stdc++.h>
#define REP(i, a, n) for(ll i = ((ll) a); i < ((ll) n); i++)
using namespace std;
typedef long long ll;

int main(void) {
  ll H, W;
  cin >> H >> W;
  char S[H][W];
  REP(i, 0, H) REP(j, 0, W) cin >> S[i][j];

  bool ok[H][W];
  REP(i, 0, H) REP(j, 0, W) ok[i][j] = false;
  ll N = H * W;
  REP(y1, 0, H) REP(y2, y1 + 1, H) REP(x1, 0, W) REP(x2, x1 + 1, W) {
    if(ok[y1][x1] || ok[y2][x2] || ok[y1][x2] || ok[y2][x1]) continue;
    if(S[y1][x1] == S[y2][x2] && S[y1][x2] == S[y2][x1]) {
      ok[y1][x1] = ok[y2][x2] = ok[y1][x2] = ok[y2][x1] = true;
    }
  }

  bool ans = true;
  ll okcnt = 0;
  REP(i, 0, H) REP(j, 0, W) if(ok[i][j]) okcnt++;
  if(H % 2 == 1 && W % 2 == 1) {
    if(okcnt != H * W - H - W + 1) ans = false;

    ll hh;
    REP(i, 0, H) {
      bool t = true;
      REP(j, 0, W) if(ok[i][j]) t = false;
      if(t) hh = i;
    }
    ll cnt1[256];
    REP(i, 0, 256) cnt1[i] = 0;
    REP(i, 0, W) cnt1[S[hh][i]]++;

    ll ww;
    REP(j, 0, W) {
      bool t = true;
      REP(i, 0, H) if(ok[i][j]) t = false;
      if(t) hh = j;
    }
    ll cnt2[256];
    REP(i, 0, 256) cnt2[i] = 0;
    REP(i, 0, H) cnt2[S[i][ww]]++;

    ll k1 = 0, k2 = 0;
    REP(i, 0, 256) if(cnt1[i] % 2 == 1) k1++;
    REP(i, 0, 256) if(cnt2[i] % 2 == 1) k2++;
    if(k1 == 1 && k2 == 1); else ans = false;
  } else if(H % 2 == 1) {
    if(okcnt != H * W - W) ans = false;

    set<ll> h;
    ll hh;
    REP(i, 0, H) REP(j, 0, W) if(!ok[i][j]) h.insert(i), hh = i;
    if(h.size() != 1) ans = false;
    ll cnt1[256];
    REP(i, 0, 256) cnt1[i] = 0;
    REP(i, 0, W) cnt1[S[hh][i]]++;
    REP(i, 0, 256) if(cnt1[i] % 2 == 1) ans = false;
  } else if(W % 2 == 1) {
    if(okcnt != H * W - H) ans = false;

    set<ll> w;
    ll ww;
    REP(i, 0, H) REP(j, 0, W) if(!ok[i][j]) w.insert(j), ww = j;
    if(w.size() != 1) ans = false;
    ll cnt2[256];
    REP(i, 0, 256) cnt2[i] = 0;
    REP(i, 0, H) cnt2[S[i][ww]]++;
    REP(i, 0, 256) if(cnt2[i] % 2 == 1) ans = false;
  } else {
    if(okcnt != H * W) ans = false;
  }
  cout << (ans ? "YES" : "NO") << endl;
}

#include <bits/stdc++.h>
using namespace std;
int h, w;
char matrix[12][12];
bool able[12][12];
void get(queue<int> &q){
    if (q.size() <= 1){
        cout << "YES" << endl;
        exit(0);
    }
    int ld = q.size();
    int el = q.front();
    q.pop();
    for (int i=0; i < q.size(); i++){
        int V = q.front();
        q.pop();
        if (able[V][el]) get(q);
        q.push(V);
    }
    if (ld % 2) get(q);
    q.push(el);
}
void solve(queue<int> &q, vector<pair<int, int> > &v){
    if (q.size() > 1){
        int ld = q.size();
        int el = q.front();
        q.pop();
        for (int i=0; i < q.size(); i++){
            int V = q.front();
            q.pop();
            v.push_back(make_pair(el, V));
            solve(q, v);
            v.pop_back();
            q.push(V);
        }
        if (ld % 2){
            v.push_back(make_pair(el, el));
            solve(q, v);
            v.pop_back();
        }
        q.push(el);
        for (int i=0; i < q.size()-1; i++){
            int V = q.front();
            q.pop();
            q.push(V);
        }
        return;
    }
    for (int i=0; i < w; i++){
        for (int j=0; j < w; j++){
            able[i][j] = true;
            for (int s=0; s < v.size(); s++){
                int a = v[s].first, b = v[s].second;
                if (matrix[a][i] != matrix[b][j]) able[i][j] = false;
                if (matrix[b][i] != matrix[a][j]) able[i][j] = false;
            }
            if (q.size() > 0){
                int e = q.front();
                if (matrix[e][i] != matrix[e][j]) able[i][j] = false;
            }
        }
    }
    queue<int> nq;
    for (int i=0; i < w; i++) nq.push(i);
    get(nq);
}
int32_t main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cin >> h >> w;
    for (int i=0; i < h; i++) for (int j=0; j < w; j++) cin >> matrix[i][j];
    queue<int> v;
    vector<pair<int, int> > q;
    for (int i=0; i < h; i++) v.push(i);
    solve(v, q);
    cout << "NO" << endl;
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using P = pair<int, int>;

int H, W;

bool judge(vector<P>& v, vector<string>& s) {
    vector<string> s2(H);
    for (int i = 0; i < (H + 1) / 2; i++) {
        s2[i] = s[v[i].first];
        s2[H - 1 - i] = s[v[i].second];
    }

    vector<int> used(W, false);
    int ok = W % 2;
    for (int i = 0; i < W; i++) {
        if (used[i]) continue;
        for (int j = W - 1; j >= i; j--) {
            if (used[j]) continue;
            bool flag = true;
            for (int k = 0; k < H; k++) {
                if (s2[k][i] != s2[H - 1 - k][j]) {
                    flag = false;
                    break;
                }
            }
            if (flag) {
                if (j == i) {
                    if (!ok) return false;
                    ok = false;
                }
                used[i] = true;
                used[j] = true;
                break;
            }
        }
        if (!used[i]) {
            return false;
        }
    } 
    return true;
}

bool solve(int used, vector<P>& v, vector<string>& s) {
    vector<int> idxs;
    for (int i = 0; i < H; i++) {
        if (used & (1 << i)) continue;
        idxs.push_back(i);
    }

    int m = idxs.size();
    if (m == 0) {
        return judge(v, s);
    } else if (m == 1) {
        used ^= (1 << idxs[0]);
        v.emplace_back(idxs[0], idxs[0]);
        if (solve(used, v, s)) return true;
        used ^= (1 << idxs[0]);
    } else {
        for (int ii = 0; ii < m; ii++) {
            int i = idxs[ii];
            used ^= (1 << i);
            for (int jj = ii + 1; jj < m; jj++) {
                int j = idxs[jj];
                used ^= (1 << j);
                v.emplace_back(i, j);
                if (solve(used, v, s)) return true;
                used ^= (1 << j);
                v.pop_back();
            }
            used ^= (1 << i);
        }
    }
    return false;
}

