int H, W;
string S[12];
bool box[12];

void check(vector<int> vec) {
    bool ikkai = H % 2 == 1;
    bool used[12] = {};
    for (int i = 0; i < H; i++) {
        if (used[i]) continue;
        for (int j = 0; j < H; j++) {
            if (used[j]) continue;
            for (int k = 0; k + 1 < W; k += 2) {
                if (S[i][vec[k]] != S[j][vec[k + 1]] || S[i][vec[k + 1]] != S[j][vec[k]]) goto check1;
            }
            if (W % 2 == 1) {
                if (S[i][vec[W - 1]] != S[j][vec[W - 1]]) goto check1;
            }
            used[i] = true;
            used[j] = true;
            goto check2;
        check1:;
        }
        if (ikkai) {
            for (int k = 0; k < W; k += 2) {
                if (S[i][vec[k]] != S[i][vec[k + 1]] || S[i][vec[k + 1]] != S[i][vec[k]])return;
            }
            if (W % 2 == 1) {
                if (S[i][vec[W - 1]] != S[i][vec[W - 1]]) return;
            }
            used[i] = true;
            ikkai = false;
        }
        return;
    check2:;
    }
    cout << "YES" << endl;
    exit(0);
}

void dfs(vector<int> saki, bool box[12]) {
    if (saki.size() == W) {
        check(saki);
        return;
    }
    if (saki.size() == W - 1) {
        for (int i = 0; i < W; i++) {
            if (!box[i]) {
                saki.push_back(i);
                check(saki);
                return;
            }
        }
    }
    for (int i = 0; i < W; i++) {
        if (!box[i]) {
            saki.push_back(i);
            for (int j = i + 1; j < W; j++) {
                if (!box[j]) {
                    bool newbox[12];
                    for (int k = 0; k < W; k++) {
                        newbox[k] = box[k];
                    }
                    newbox[i] = true;
                    newbox[j] = true;
                    saki.push_back(j);
                    dfs(saki, newbox);
                    saki.pop_back();
                }
            }
            return;
        }
    }

}

