void dfs_l(int x,bool odd)
{
	if (x==m+1)
	{
		printf("YES");
		exit(0);
	}
	else if (l[x])
		dfs_l(x+1,odd);
	else
	{
		for (int i=x+1;i<=m;i++)
		{
			if (l[i]) continue;
			int j;
			for (j=1;j<=n;j++)
				if (s[j][x]!=s[h[j]][i])
					break;
			if (j==n+1)
			{
				l[x]=i,l[i]=x;
				dfs_l(x+1,odd);
				l[x]=0,l[i]=0;
			}
		}	
	}
	if (odd)
	{
		int i;
		for (i=1;i<=n;i++)
			if (s[i][x]!=s[h[i]][x])
				break;
		if (i==n+1)
		{
			l[x]=x;
			dfs_l(x+1,false);
			l[x]=0;
		}
	}
}
void dfs_h(int x,bool odd)
{
	if (x==n+1)
		dfs_l(1,(bool)m&1);
	else if (h[x])
		dfs_h(x+1,odd);
	else
	{
		for (int i=x+1;i<=n;i++)
		{
			if (h[i]) continue;
			if (ss[i]!=ss[x]) continue;
			h[i]=x,h[x]=i;
			dfs_h(x+1,odd);
			h[i]=0,h[x]=0;
		}
	}
	if (odd)
	{
		h[x]=x;
		dfs_h(x+1,false);
		h[x]=0;
	}
}
