bool is_palindrome(const string& s) {
    string t = s;
    reverse(t.begin(), t.end());
    return s == t;
}
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int h, w;
    cin >> h >> w;
    #define H 12
    static string s[H];
    for(int i = 0; i < h; i++) {
        cin >> s[i];
    }
    vector<int> p;
    for(int i = 0; i < w; i++) {
        p.push_back(i);
    }
    bool can = false;
    do {
        set<string> x;
        bool valid = true;
        for(int i = 0; i < h and valid; i++) {
            string cur = "";
            for(int j = 0; j < w; j++) {
                cur += s[i][p[j]];
            }
            reverse(cur.begin(), cur.end());
            if(x.count(cur)) {
                x.erase(cur);
            } else {
                reverse(cur.begin(), cur.end());
                x.insert(cur);
            }
            if(x.size() > h / 2) {
                valid = false;
            }
        }
        can |= valid and (h % 2 ? x.size() == 1 and is_palindrome(*x.begin()) : x.empty());
    } while(!can and next_permutation(p.begin(), p.end()));
    cout << (can ? "YES" : "NO") << endl;
    return 0;
}

