vector<string> solve2(int H, int W, vector<string> strs) {
	vector<string> org;
	vector<string> ans(H);
	vector<pair<string, int>> S;
	map<string, vector<int>> ms;
	REP(i, H) {
		S.push_back(MP(strs[i], i));
		org.push_back(strs[i]);
	}
	REP(i, H) {
		sort(ALL(S[i].first));
	}
	sort(ALL(S));
	REP(i, H) {
		ms[S[i].first].push_back(i);
	}

	bool f = ((H%2) != 0);
	int cnt = 0;
	for (auto &a : ms) {
		if (a.second.size() % 2 == 1) {
			if (f) {
				f = false;
				ans[H/2] = org[S[a.second[0]].second];
				for (int i = 1; i < a.second.size();) {
					ans[cnt] = org[a.second[i++]];
					ans[H-cnt - 1] = org[S[a.second[i++]].second];
					cnt++;
				}
			}
			else return{};
		}
		else {
			for (int i = 0; i < a.second.size();) {
				ans[cnt] = org[S[a.second[i]].second]; i++;
				ans[H - cnt - 1] = org[S[a.second[i]].second]; i++;
				cnt++;
			}
		}
	}
	return ans;
}

bool solve() {
	int H, W; cin >> H >> W;
	vector<string> strs;
	vector<string> tstrs;
	REP(i, H) {
		string s; cin >> s;
		strs.push_back(s);
	}
	strs = solve2(H, W, strs);
	if (strs.size() == 0) return false;
	REP(i, W) {
		string str;
		REP(j, H) {
			str += strs[j][i];
		}
		tstrs.push_back(str);
	}
	tstrs = solve2(W, H, tstrs);
	if (tstrs.size() == 0) return false;
	REP(i, W) {
		REP(j, H) {
			if (tstrs[i][j] != tstrs[W - i - 1][H - j - 1]) return false;
		}
	}
	return true;
}

