bool judge(vector<P>& v, vector<string>& s) {
    //counter++;
    vector<string> s2(H);
    for (int i = 0, j = 0; i < (H + 1) / 2; i++) {
        if (v[i].first == v[i].second) {
            s2[H / 2] = s[v[i].first];
            continue;
        }
        s2[j] = s[v[i].first];
        s2[H - 1 - j] = s[v[i].second];
        j++;
    }

    vector<int> used(W, false);
    int ok = W % 2;
    for (int i = 0; i < W; i++) {
        if (used[i]) continue;
        for (int j = W - 1; j >= i; j--) {
            if (used[j]) continue;
            bool flag = true;
            for (int k = 0; k < H; k++) {
                if (s2[k][i] != s2[H - 1 - k][j]) {
                    flag = false;
                    break;
                }
            }
            if (flag) {
                if (j == i) {
                    if (!ok) return false;
                    ok = false;
                }
                used[i] = true;
                used[j] = true;
                break;
            }
        }
        if (!used[i]) {
            return false;
        }
    } 
    return true;
}

bool solve(int used, vector<P> v, vector<string>& s) {
    vector<int> idxs;
    for (int i = 0; i < H; i++) {
        if (used & (1 << i)) continue;
        idxs.push_back(i);
    }

    int m = idxs.size();
    if (m == 0) {
        return judge(v, s);
    } else if (m == 1) {
        used ^= (1 << idxs[0]);
        v.emplace_back(idxs[0], idxs[0]);
        if (solve(used, v, s)) return true;
        v.pop_back();
        used ^= (1 << idxs[0]);
    } else {
        for (int ii = 0; ii < 1; ii++) {
            int i = idxs[ii];
            used ^= (1 << i);
            if (m % 2 == 1) {
                v.emplace_back(i, i);
                if (solve(used, v, s)) return true;
                v.pop_back();
            }
            for (int jj = ii + 1; jj < m; jj++) {
                int j = idxs[jj];
                used ^= (1 << j);
                v.emplace_back(i, j);
                if (solve(used, v, s)) return true;
                used ^= (1 << j);
                v.pop_back();
            }
            used ^= (1 << i);
        }
    }
    return false;
}

