using namespace std;

int H, W;
vector<string> S;

bool check(auto T) {
  vector<bool> used(W);
  set<int> uniq;
  for(auto i=0; i<W; ++i) if(!used[i]) {
    for(auto j=i+1; j<W; ++j) if(!used[j]) {
      auto same = true;
      for(auto k=0; k<H; ++k) same &= (T[k][i] == T[H-1-k][j]);
      if(!same) continue;
      used[i] = used[j] = true;
      break;
    }
    if(!used[i]) uniq.emplace(i);
  }
  if(uniq.empty()) return true;
  if(2 <= uniq.size()) return false;
  auto i = *begin(uniq);
  for(auto k=0; k<H; ++k) if(T[k][i] != T[H-1-k][i]) return false;
  return true;
}

bool dfs(auto T, auto used, auto n) {
  if(n == H) return check(T);
  if(used[n]) return dfs(T, used, n+1);
  for(auto i=0; i<H; ++i) if(T[i].empty()) {
    used[n] = true;
    T[i] = S[n];
    for(auto m=n+1; m<H; ++m) if(!used[m]) {
      used[m] = true;
      T[H-1-i] = S[m];
      if(dfs(T, used, n+1)) return true;
      used[m] = false;
      T[H-1-i].clear();
    }
    return false;
  }
  assert(-1);
}

string solve() {
  if(H&1) for(auto i=0; i<H; ++i) {
    vector<string> T(H);
    vector<bool> used(H);
    T[H/2] = S[i];
    used[i] = true;
    if(dfs(T, used, 0)) return "YES";
  } else {
    if(dfs(vector<string>(H), vector<bool>(H), 0)) return "YES";
  }
  return "NO";
}

