int H, W, answerFlag = false;
vector<string> board;

bool comp(string a, string b) {
    rep(i,0,H) if(a[i] != b[H-1-i]) return false;
    return true;
}

bool solve(vector<int> perm) {
    vector<string> tmp_board(H), col_board(W, "");
    vector<bool> appeared(H);
    rep(i,0,H) {
        if(perm[i] > 0) {
            if(appeared[perm[i]]) {
                tmp_board[perm[i]-1] = board[i];
            }
            else {
                appeared[perm[i]] = true;
                tmp_board[H-perm[i]] = board[i];
            }
        }
        else {
            // center
            tmp_board[H/2] = board[i];
        }
    }

    rep(i,0,H) rep(j,0,W) {
        col_board[j] += tmp_board[i][j];
    }

    vector<bool> used(W);
    rep(i,0,W) {
        if(!used[i]) {
            bool found = false;
            rep(j,i+1,W) {
                if(!used[j] && comp(col_board[i], col_board[j])) {
                    used[i] = used[j] = found = true;
                    break;
                }
            }

            if(!found) {
                if(W % 2 == 0) return false;
                else {
                    if(comp(col_board[i], col_board[i])) {
                        used[i] = true;
                    }
                    else {
                        return false;
                    }
                }
            }
        }
    }
    return true;
}

void search_board(vector<int> rec, int step=1) {
    if(step == 1 && H % 2 == 1) {
        // odd number
        rep(i,0,H) if(rec[i] == 0) {
            rec[i] = step;
            search_board(rec, step+1);
            rec[i] = 0;
        }
    }
    else {
        bool found_zero = false;
        rep(i,0,H) if(rec[i] == 0) {
            found_zero = true;
            rep(j,i+1,H) if(rec[j] == 0) {
                rec[i] = rec[j] = step;
                search_board(rec, step+1);
                rec[i] = rec[j] = 0;
            }
            break;
        }

        if(!found_zero) {
            answerFlag |= solve(rec);
        }
    }
}

