	return dfs2(match_y, init, x+1, match_x);

  for(int x1=x+1;x1<W;++x1){
	if(match_x[x1] >= 0) continue;
	bool ok = true;
	REP(y,H)
	  if(match_y[y] != H){
		if(vs[y][x] != vs[match_y[y]][x1]
		   || vs[y][x1] != vs[match_y[y]][x]){
		  ok = false;
		  break;
		}
	  }
	  else{
		if(vs[y][x] != vs[y][x1]){
		  ok = false;
		  break;
		}
	  }
	if(ok){
	  match_x[x] = x1;
	  match_x[x1] = x;
	  if(dfs2(match_y, init, x+1, match_x))
		return true;
	  match_x[x] = match_x[x1] = -1;
	}
  }
  if(init){
	bool ok = true;
	REP(y,H)
	  if(match_y[y] != H
		 && vs[y][x] != vs[match_y[y]][x]){
		ok = false;
		break;
	  }
	if(ok){
	  match_x[x] = W;
	  if(dfs2(match_y, false, x+1, match_x))
		return true;
	  match_x[x] = -1;
	}
  }

