}

bool dfs1(bool init, int y, VI& match){
  if(init){
	REP(y,H){
	  if(!ok_y[y]) continue;
	  match[y] = H;
	  if(dfs1(false, 0, match)){
		return true;
	  }
	  match[y] = -1;
	}
	return false;
  }

  if(y == H){
	VI match_x(W, -1);
	if(dfs2(match, W%2==1, 0, match_x))
	  return true;
	return false;
  }
  if(match[y] >= 0)
	return dfs1(init, y+1, match);

  for(int y1=y+1;y1<H;++y1)
	if(match[y1] < 0 && same[y][y1]){
	  match[y] = y1;
	  match[y1] = y;
	  if(dfs1(init, y+1, match))
		return true;
	  match[y] = match[y1] = -1;
	}
  return false;
}

