using namespace std;
template <typename Functor>
struct fix_type
{
    Functor functor;
    template <typename... Args>
    decltype(auto) operator()(Args&&... args) const& { return functor(functor, std::forward<Args>(args)...); }
};
template <typename Functor>
fix_type<typename std::decay<Functor>::type> fix(Functor&& functor) { return {std::forward<Functor>(functor)}; }
int main()
{
    int H, W;
    cin >> H >> W;
    vector<string> S(H);
    for (int i = 0; i < H; i++) { cin >> S[i]; }
    auto f = [&](const string& s1, const string& s2) {
        for (int i = 0; i < H; i++) {
            if (s1[i] != s2[H - 1 - i]) { return false; }
        }
        return true;
    };
    vector<vector<int>> rs;
    auto rec = fix([&](auto&& self, vector<int> r, const int num) -> void {
        if (num == (H + 1) / 2) {
            rs.push_back(r);
        } else {
            int head = 0;
            for (; r[head] != -1; head++) {}
            r[head] = num;
            if (H % 2 == 1 and num == (H - 1) / 2) {
                self(self, r, num + 1);
            } else {
                for (int tail = head + 1; tail < H; tail++) {
                    if (r[tail] == -1) {
                        r[tail] = num;
                        self(self, r, num + 1);
                        r[tail] = -1;
                    }
                }
            }
        }
    });
    rec(vector<int>(H, -1), 0);
    for (const auto& row : rs) {
        vector<int> r(H, -1);
        for (int i = 0; i < H; i++) {
            if (r[row[i]] == -1) {
                r[row[i]] = i;
            } else {
                r[H - 1 - row[i]] = i;
            }
        }
        vector<string> cols(W);
        for (int i = 0; i < W; i++) {
            for (int j = 0; j < H; j++) { cols[i].push_back(S[r[j]][i]); }
        }
        vector<bool> unused(W, true);
        for (int i = 0; i < W; i++) {
            if (not unused[i]) { continue; }
            for (int j = i + 1; j < W; j++) {
                if (unused[j] and f(cols[i], cols[j])) {
                    unused[i] = false, unused[j] = false;
                    break;
                }
            }
        }
        const int ans = accumulate(unused.begin(), unused.end(), 0);
        if (ans <= 1) {
            bool s = true;
            for (int i = 0; i < W; i++) {
                if (unused[i] and not f(cols[i], cols[i])) { assert(false); }
            }
            if (s) {
                cout << "YES" << endl;
                return 0;
            }
        }
    }
    cout << "NO" << endl;
    return 0;
}

