bool eq[12][12];
bool can[1 << 12];

bool equal(int c1, int c2) {
    for (int i = 0; i < h; i++)
        if (s[perm[i]][c1] != s[perm[h - i - 1]][c2])
            return false;
    return true;
}

bool check() {
    for (int c = 0; c < w; c++)
        memset(eq[c], 0, sizeof eq[c]);
    memset(can, 0, sizeof can);

    for (int c1 = 0; c1 < w; c1++) {
        for (int c2 = c1; c2 < w; c2++) {
            if (equal(c1, c2)) {
                eq[c1][c2] = eq[c2][c1] = true;
            }
        }
    }

    can[0] = true;
    for (int mask = 0; mask < (1 << w); mask++) {
        if (__builtin_popcount(mask) & 1)
            continue;
        if (!can[mask])
            continue;
        for (int c1 = 0; c1 < w; c1++) {
            if (mask & (1 << c1))
                continue;
            for (int c2 = c1 + 1; c2 < w; c2++) {
                if (mask & (1 << c2))
                    continue;
                if (eq[c1][c2])
                    can[mask | (1 << c1) | (1 << c2)] = true;
            }
        }
    }

    if (w & 1) {
        for (int c = 0; c < w; c++) {
            if (eq[c][c] && can[((1 << w) - 1) ^ (1 << c)]) {
                return true;
            }
        }
        return false;
    }

    return can[(1 << w) - 1];
}

void get_all(int i) {
    if (i == h / 2) {
        if (check()) {
            cout << "YES\n";
            exit(0);
        }
        return;
    }

    for (int k = i + 1; k < h - i; k++) {
       std::swap(perm[k], perm[h - i - 1]);
       get_all(i + 1);
       std::swap(perm[k], perm[h - i - 1]);
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
