    cout << fixed;

    cin >> h >> w;
    for (int i = 0; i < h; i++) {
        cin >> s[i];
        perm[i] = i;
    }

    if (h & 1) {
        get_all(0);
        for (int i = 0; i < h / 2; i++) {
            std::swap(perm[i], perm[h / 2]);
            get_all(0);
        }
    } else {
        get_all(0);
    }
    cout << "NO\n";

    #ifdef LOCAL
        cerr << "\n== " << 1.0 * clock() / CLOCKS_PER_SEC << " sec.\n";
    #endif
    return 0;
}

