bool check(const vector<string> &a, const vector<string> &b){
  const int n = a.size();
  const int m = a[0].size();

  vector<vector<int> > cnt(m, vector<int>(m));

  REP(i,n){
    const string &aa = a[i];
    const string &bb = b[i];

    REP(j,m) REP(k,j+1){
      if(aa[j] == bb[k] && aa[k] == bb[j]){
        cnt[j][k]++;
        if(j != k) cnt[k][j]++;
      }
    }
  }

  // puts("test");
  // REP(i,m) { REP(j,m) printf("%d ", cnt[i][j]); puts(""); }

  vector<int> use(m);
  bool self = m % 2 != 0;

  REP(i,m) if(!use[i]){
    for(int j = i + 1; j < m; j++){
      if(!use[j] && cnt[i][j] == n){
        use[i] = use[j] = 1;
      }
    }
    if(self && !use[i] && cnt[i][i] == n){
      self = false;
      use[i] = 1;
    }
  }

  return accumulate(use.begin(), use.end(), 0) == m;
}

int main(){
  const int h = getInt();
  const int w = getInt();
  vector<string> v(h);

  REP(i,h) v[i] = getStr();

  REP(i,1<<h){
    const int c = __builtin_popcount(i);
    if(c != h / 2) continue;
    if((i & 1) == 0) continue;

    vector<string> top;
    vector<string> bottom;

    REP(j,h){
      if((i & (1 << j)) != 0) top.push_back(v[j]);
      else bottom.push_back(v[j]);
    }

    sort(bottom.begin(), bottom.end());
    do{
      bool ok = true;
      const string last = bottom.back();
      if(h % 2 != 0){
        REP(j,w/2) if(last[j] != last[w - 1 - j]) ok = false;
      }
      if(!ok) continue;

      bottom.pop_back();

      if(check(top, bottom)){
        puts("YES");
        return 0;
      }

      bottom.push_back(last);
    }while(next_permutation(bottom.begin(), bottom.end()));
  }

  puts("NO");
  return 0;
}

