void add(int x,int y,int flow)
{
    e[tot].to=y; e[tot].flow=flow; e[tot].nxt=fir[x]; fir[x]=tot++;
    e[tot].to=x; e[tot].flow=0; e[tot].nxt=fir[y]; fir[y]=tot++;
}
int flow(int now,int mn)
{
    if(now==T)return mn;
    for(int i=fir[now];~i;i=e[i].nxt)
        if(lev[e[i].to]==lev[now]+1&&e[i].flow){
            int tmp=flow(e[i].to,min(mn,e[i].flow));
            e[i].flow-=tmp; e[i^1].flow+=tmp;
            if(tmp)return tmp;
        }
    return 0;
}
int dinic()
{
	int i,ans=0;
	while(1){
        for(i=0;i<=T;i++)lev[i]=0;
        int h=1,t=1; q[1]=S; lev[S]=1;
        while(h<=t){
            for(i=fir[q[h]];~i;i=e[i].nxt)
                if(!lev[e[i].to]&&e[i].flow){
                    q[++t]=e[i].to; lev[e[i].to]=lev[q[h]]+1;
                }
            ++h;
        }
        if(!lev[T])break;
        int tmp=flow(S,inf);
        while(tmp){
            ans+=tmp;
            tmp=flow(S,inf);
        }
    }
    return ans;
}
