bool dfs2(int k){
	if (k>m) return 1;
	if (q[k]) return dfs2(k+1);
	int cnt=0; rep (i,k+1,m) if (!q[k]) cnt++;
	rep (i,k,m) if (!q[i]){
		q[i]=k; q[k]=i;
		if (chk(i,k) && (i!=k || (cnt&1)) && dfs2(k+1)) return 1;
		q[i]=q[k]=0;
	}
	return 0;
}
bool dfs1(int k){
	if (k>n) return dfs2(1);
	if (p[k]) return dfs1(k+1);
	int cnt=0; rep (i,k+1,n) if (!p[k]) cnt++;
	rep (i,k,n) if (!p[i]){
		p[i]=k; p[k]=i;
		if ((i!=k || (cnt&1)) && dfs1(k+1)) return 1;
		p[i]=p[k]=0;
	}
	return 0;
}
