    for (int i = 0; i < H; i++){
        cin >> grid[i];
    }

    fill(used, used+H, false);
    if (rec(0, 0, H%2==1)){
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }

    return 0;
}

