int nth_bit(int64_t num, int n){
    return (num >> n) & 1;
}

int H, W;
string S[12];

vector<vector<pair<int, int>>> cand;
vector<pair<int, int>> now;

void rec(int b){
    if(b == (1<<H)-1){
        cand.push_back(now);
        return;
    }

    vector<int> avail;
    for(int i=0; i<H; i++) if(!nth_bit(b, i)) avail.push_back(i);
    int sz = avail.size();
    int f = avail[0];
    if(sz%2){
        now.emplace_back(f, f);
        rec(b+(1<<f));
        now.pop_back();
    }
    for(int i=1; i<sz; i++){
        int g = avail[i];
        now.emplace_back(f, g);
        rec(b+(1<<f)+(1<<g));
        now.pop_back();
    }
}

