S ll hashidx;

void f_calc(ll hashlist[12000][2], string resstrlist[12000], const string &s)
{

    ll total = 0;
    rep (i, s.size()) {
        total *= MLT;
        total %= MOD;
        total += s[i];
        total %= MOD;
    }
    hashlist[hashidx][0] = total;
    resstrlist[hashidx] = s;

    total = 0;
    rrep (i, s.size()) {
        total *= MLT;
        total %= MOD;
        total += s[i];
        total %= MOD;
    }
    hashlist[hashidx][1] = total;

    debug_printf("s=%s %s hashidx=%lld (%lld %lld)\n",
                 s.c_str(), resstrlist[hashidx].c_str(),
                 hashidx, hashlist[hashidx][0], hashlist[hashidx][1]);

    hashidx++;
}

void dfs(ll hashlist[12000][2], string resstrlist[12000],
         const string &line, ll w,
         set<ll> &poslist, set<t2> &pairs, char center)
{
    if (poslist.empty()) {
        string s;
        if (center != '_') s += center;
        for (auto p : pairs) {
            ll idx1 = get<0>(p);
            ll idx2 = get<1>(p);
            s = line[idx1] + s + line[idx2];
        }
        f_calc(hashlist, resstrlist, s);
        return;
    }

    ll idx_left = *poslist.begin();
    poslist.erase(idx_left);
    set<ll> lposlist = poslist;

    for (auto idx_right : lposlist) {
        poslist.erase(idx_right);
        pairs.insert(t2(idx_left, idx_right));
        dfs(hashlist, resstrlist, line, w, poslist, pairs, center);
        poslist.insert(idx_right);
        pairs.erase(t2(idx_left, idx_right));
    }

    poslist.insert(idx_left);
}

void f_hashlist(ll hashlist[12000][2], string resstrlist[12000],
                const string &line, ll w)
{
    debug_printf("------------- f_hashlist %s\n", line.c_str());

    hashidx = 0;
    set<ll> poslist;
    rep (i, w) poslist.insert(i);
    set<t2> pairs;

    if (w & 1LL) rep (i, w) {
            poslist.erase(i);
            dfs(hashlist, resstrlist, line, w, poslist, pairs, line[i]);
            poslist.insert(i);
        }
        else {
            dfs(hashlist, resstrlist, line, w, poslist, pairs, '_');
        }
}

bool judge(const ll hashlist[13][12000][2], const string resstrlist[13][12000],
           ll h, ll w, set<ll> &linelist, ll hi)
{
    if (linelist.empty()) return true;
    assert(linelist.size() >= 2);

    ll line1 = *linelist.begin();
    linelist.erase(line1);
    set<ll> locallist = linelist;

    bool ret = false;

    for (auto line2 : locallist) {
        if (hashlist[line1][hi][0] != hashlist[line2][hi][1]) continue;
        linelist.erase(line2);
        bool lf = judge(hashlist, resstrlist, h, w, linelist, hi);
        linelist.insert(line2);
        if (lf) {
            ret = lf;
            break;
        }
    }

    linelist.insert(line1);
    return ret;
}

bool solve(const ll hashlist[13][12000][2], const string resstrlist[13][12000],
           ll h, ll w, ll hashend)
{
    rep (hi, hashend) {
        set<ll> linelist;
        rep (i, h) linelist.insert(i);

        if (h & 1LL) rep (hh, h) {
            if (hashlist[hh][hi][0] != hashlist[hh][hi][1]) continue;
            linelist.erase(hh);
            bool flag = judge(hashlist, resstrlist, h, w, linelist, hi);
            if (flag) return true;
            linelist.insert(hh);
        }
        else {
            bool flag = judge(hashlist, resstrlist, h, w, linelist, hi);
            if (flag) return true;
        }

    }

    return false;
}

void _main()
{
    ll h; llin(h);
    ll w; llin(w);
    S V<string> grid;
    rep (i, h) {
        string tmp; CIN(tmp);
        grid.pb(tmp);
    }

    S ll hashlist[13][12000][2];
    S string resstrlist[13][12000];
    rep (hh, h) f_hashlist(hashlist[hh], resstrlist[hh], grid[hh], w);

    bool flag = solve(hashlist, resstrlist, h, w, hashidx);

    debug_printf("---- ans\n");
    cout << (flag ? "YES": "NO") << endl;
}

