  vector<vector<char>> g(N, vector<char>(M));
  for (int i = 0; i < N; ++i) {
    for (int j = 0; j < M; ++j) {
      g[i][j] = G[i][j];
    }
  }
  bool ok = true;
  ok &= check(g);
  vector<vector<char>> tg(M, vector<char>(N));
  for (int i = 0; i < N; ++i) {
    for (int j = 0; j < M; ++j) {
      tg[j][i] = g[i][j];
    }
  }
