bool J(char*a,char*b,int*p){
	memcpy(s1,a,sizeof a);
	memcpy(s2,b,sizeof b);
	a=s1,b=s2;
	rep(i,1,m)p[i]=i;
	rep(i,1,m/2){
		int u=m-i+1;
		if(a[i]==b[u]&&b[i]==a[u])continue;
		int fl=0;
		rep(j,i+1,u-1){
			if(a[i]==b[j]&&b[i]==a[j]){
				swap(p[u],p[j]);
				swap(a[j],a[u]);
				swap(b[j],b[u]);
				fl=1;
				break;
			}

		}
		if(!fl)return 0;
	}
	if(m&1){
		int o=m+1>>1;
		if(a[o]!=b[o])return 0;
	}
	return 1;
}
bool check(){
	static int c[N],d[N];
	memcpy(c,a,sizeof a);
