#include <bits/stdc++.h>
using namespace std;
struct HopcroftKarp{
    int n1, n2;
    vector<int> last, pre, head, matching, dist; queue<int> Q;
    vector<bool> used, vis, reachable1, reachable2;
    HopcroftKarp(int _n1, int _n2){
        n1 = _n1;
        n2 = _n2;
        last.assign(n1, -1);
        dist.resize(n1);
        vis.resize(n1);
    }
    void addEdge(int u, int v){
        head.push_back(v);
        pre.push_back(last[u]);
        last[u] = (int) head.size() - 1;
    }
    void bfs(){
        fill(dist.begin(), dist.end(), -1);
        for(int u = 0; u < n1; u++) if(!used[u]){
            Q.push(u); dist[u] = 0;
        }
        while(!Q.empty()){
            int u1 = Q.front(); Q.pop();
            for(int e = last[u1]; e >= 0; e = pre[e]){
                int u2 = matching[head[e]];
                if(u2 >= 0 and dist[u2] < 0){
                    dist[u2] = dist[u1] + 1;
                    Q.push(u2);
                }
            }
        }
    }
    bool dfs(int u1){
        vis[u1] = true;
        for(int e = last[u1]; e >= 0; e = pre[e]){
            int v = head[e], u2 = matching[v];
            if(u2 < 0 or (!vis[u2] and dist[u2] == dist[u1] + 1 and dfs(u2))){
                matching[v] = u1;
                used[u1] = true;
                return true;
            }
        }
        return false;
    }
    int maxMatching(){
        used.assign(n1, false);
        matching.assign(n2, -1);
        for(int res = 0;;){
            bfs();
            fill(vis.begin(), vis.end(), false);
            int f = 0;
            for(int u = 0; u < n1; u++){
                if(!used[u] and dfs(u)) f++;
            }
            if(!f) return res;
            res += f;
        }
    }
};
string a[12];
int main(){
	int n, m;
	cin >> n >> m;
	for(int i = 0; i < n; i++) cin >> a[i];
	int msk = 1<<n; msk--;
	for(int i = 0; i < (1<<n); i++){
		if(__builtin_popcount(i) != n/2) continue;
		int rev = msk ^ i;
		if(rev < i && __builtin_popcount(rev) == n / 2) continue;
		vector<int> top, bot;
		for(int j = 0; j < n; j++){
			if(i&(1<<j)) top.push_back(j);
			else bot.push_back(j);
		}
		do{
			HopcroftKarp flow(m, m);
			for(int j = 0; j < m; j++){
				for(int k = j; k < m; k++){
					int ok = 0;
					for(int l = 0; l < n / 2; l++) ok += a[top[l]][j] == a[bot[l]][k] && a[top[l]][k] == a[bot[l]][j];
					if(n&1){
						ok += a[bot.back()][j] == a[bot.back()][k];
					}	
					if(ok == (n + 1) / 2){
						flow.addEdge(j, k);
					}
				}
			}
			int fl = flow.maxMatching(); 
			if(fl == (m + 1) / 2){
				cout << "YES" << endl;
				return 0;
			}
		} while(next_permutation(bot.begin(), bot.end()));
	}
	cout << "NO" << endl;
	return 0;
}

#include <bits/stdc++.h>
#define FOR(i,k,n)  for(int i = (k);i < (n);++i)
#define REP(i,n)    FOR(i,0,n)
#define ALL(x)      begin(x),end(x)

using namespace std;
using vecint = vector<int>;
using ll = int64_t;
int h,w;

bool isok_impl(const vector<string>& t) {
  REP(i,h)REP(j,w) {
    if (t[i][j] != t[h-i-1][w-j-1]) return false;
  }
  return true;
}

bool isok_h(const vector<string>& t, int k) {
  if (2*k >= h) return isok_impl(t);
  FOR(i,w/2,h-k) {
    vector<string> s = t;
    swap(s[i], s[h-k-1]);
    if (s[k][0] != s[h-k-1][w-1]) continue;
    if (isok_h(s, k+1)) return true;
  }
  return false;
}

bool isok_w(const vector<string>& t, int k) {
  if (2*k >= w) return isok_impl(t);
  FOR(j,h/2,w-k) {
    vector<string> s = t;
    REP(p,h) swap(s[p][j], s[p][w-k-1]);
    if (s[0][k] != s[h-1][w-k-1]) continue;
    if (isok_w(s, k+1)) return true;
  }
  return false;
}

bool isok(const vector<string>& t, int k) {
  int n = max(h,w) - min(h,w);
  if (n == 0) return isok_impl(t);
  if (h > w) {
    return isok_h(t, k);
  } else {
    return isok_w(t, k);
  }
}

bool solve(const vector<string>& t, int k = 0) {
  if (2*k >= min(h,w)) return isok(t, k);
  FOR(i,0,h-k)FOR(j,0,w-k) {
    vector<string> s = t;
    swap(s[i], s[h-k-1]);
    REP(p,h) swap(s[p][j], s[p][w-k-1]);
    if (s[k][k] != s[h-k-1][w-k-1]) continue;
    if (solve(s, k+1)) return true;
  }
  return false;
}

int main()
{
  cin>>h>>w;
  vector<string> t(h);
  REP(i,h) cin>>t[i];
  bool res = solve(t);
  if (res) {
    cout << "YES" << endl;
  } else {
    cout << "NO" << endl;
  }
  return 0;
}

