bool perm(int depth){
    if(depth == W / 2){
        // cout << "#" << endl;
        // // W / 2個のpsを定義
        // for(int i = 0; i < W / 2; i++){
        //     cout << ps[i].first << " " << ps[i].second << endl;
        // }
        // それぞれのペアについて、可能なペアを確定させる
        for(int k = 0; k < W / 2; k++){
            const int c1 = ps[k].first;
            const int c2 = ps[k].second;
            for(int i = 0; i < H; i++){
                int mask = 0;
                for(int j = 0; j < H; j++){
                    if(S[i][c1] == S[j][c2] && S[j][c1] == S[i][c2] && i != j)
                        mask |= (1 << j);
                }
                p[k][i] = mask;
                // cout << k << " " << i << " " << mask << endl;
                // cout << c1 << " " << c2 << endl;
            }
        }

        int proh = 0;
        // それぞれのペアについて
        for(int i = 0; i < H; i++){
            int c = (1 << H) - 1;
            for(int k = 0; k < W / 2; k++)
                c &= p[k][i];
            c &= ~proh;
            if(c == 0) return false;
            else{
                // 適当に1つ確定させる
                for(int j = 0; j < H; j++){
                    if((c >> j) & 1){
                        proh |= (1 << j);
                        break;
                    }
                }
            }
        }
        return true;
    }
    else{
        int start = -1;
        // 使っていない一番左の要素は確定
        for(int i = 0; i < W; i++){
            if(used[i]) continue;
            start = i;
            break;
        }
        used[start] = true;
        for(int i = start + 1; i < W; i++){
            if(used[i]) continue;
            used[i] = true;
            ps[depth] = pii(start, i);
            if(perm(depth + 1))
                return true;
            used[i] = false;
        }
        used[start] = false;
    }
    return false;
}

bool solve(){
    if(W % 2){
        for(int i = 0; i < W; i++){
            used[i] = true;
            if(perm(0)){
                return true;
            }
            used[i] = false;
        }
        return false;
    }
    else{
        return perm(0);
    }
}

