void makepair(vector<pii> current, int unused, int num_unused) {
    if (num_unused == 1) {
        rep(i, 12) {
            if ((unused >> i) & 1) {
                current.push_back(pii(i, i));
                break;
            }
        }
        pairs.push_back(current);
        return;
    }
    if (num_unused == 2) {
        int a;
        rep(i, 12) {
            if ((unused >> i) & 1) {
                a = i;
                break;
            }
        }
        for (int i = a + 1; i < 12; ++i) {
            if ((unused >> i) & 1) {
                current.push_back(pii(a, i));
                break;
            }
        }
        pairs.push_back(current);
        return;
    }

    int a;
    rep(i, 12) {
        if ((unused >> i) & 1) {
            a = i;
            unused ^= 1 << a;
            break;
        }
    }
    for (int i = a + 1; i < 12; ++i) {
        if ((unused >> i) & 1) {
            current.push_back(pii(a, i));
            unused ^= 1 << i;
            makepair(current, unused, num_unused - 2);
            unused ^= 1 << i;
            current.pop_back();
        }
    }
}

