void aaa(vector<vector<int> >& temp,int H,int W){
	bool flag = true;
	while(flag){
		flag = false;
		int pos = -1;
		for(int i=0;i<W-1;++i){
			if( temp[0][i] > temp[0][i+1] ){
				flag = true;
				pos = i;
				break;
			}
		}
		if( flag ){
			for(int h=0;h<H;++h){
				swap(temp[h][pos],temp[h][pos+1]);
			}
		}
	}
}
bool check(vector<vector<int> > temp,int H,int W){
	for(int h=0;h<H;++h){
		aaa(temp,H,W);
		//sort(temp[h].begin(),temp[h].end());
	}
	vector<int> Hpair(H,-1);
	for(int i=0;i<H;++i){
		if( Hpair[i] != -1 ){
			continue;
		}
		for(int j=i+1;j<H;++j){
			if( Hpair[j] != -1 ){
				continue;
			}
			vector<int> aite = temp[j];
			reverse(aite.begin(),aite.end());
			if( temp[i] == aite ){
				Hpair[i] = j;
				Hpair[j] = i;
				break;
			}
		}
	}
	int count = 0;
	int pos = -1;
	for(int i=0;i<H;++i){
		if(Hpair[i]==-1 ){
			pos = i;
			++count;
		}
	}
	if(H&1 ){
		if(count!=1){
			return false;
		}
		//横のチェック
		vector<int> TER = temp[pos];
		vector<int> tHist(26,0);
		int size = TER.size();
		for(int i=0;i<size;++i){
			tHist[TER[i]]++;
		}
		int todd = 0;
		for(int i=0;i<26;++i){
			if( tHist[i]&1 ){
				todd++;
			}
		}
		if(W&1){
			if(todd!=1){
				return false;
			}
		}else{
			if(todd){
				return false;
			}
		}
	}else{//横が偶数個
		if(count){//ペアを作れてないものがったらダメ
			return false;
		}
	}
	return true;
}
