			for(int i = 0 ; i < w; i++)
			{
				for(int j = i+1 ; j < w; j++)
				{
					if(!(mask & (1 << i)) && !(mask & (1 << j)) && match[i][j])
						dp[mask | (1 << i) | (1 << j)] = true;
				}
			}
		}
		bool can = false;
		if(w & 1)
		{
			for(int i = 0 ; i < w; i++)
