bool solve(int xlim, int ylim, vector<string> s){
	int sz=(xlim+1)/2;
	for (int z=0;z<(1<<xlim);z++) {
		if (__builtin_popcount(z)!=sz) continue;
		vector<int> vx,ox;
		for (int x=0;x<xlim;x++) {
			if (z&(1<<x)) vx.PB(x);
			else ox.PB(x);
		}
		do {
			vector<string> a,b;
			for (int y=0;y<ylim;y++) {
				string got; got.resize(sz);
				assert(vx.size()==sz);
				for (int i=0;i<sz;i++) {
					got[i]=s[vx[i]][y];
				}
				a.PB(got);
			}
			sort(a.begin(),a.end());
			for (int y=0;y<ylim;y++) {
				string got; got.resize(sz);
				for (int i=0;i<ox.size();i++) {
					got[i]=s[ox[i]][y];
				}
				if (xlim&1) {
					assert(ox.size()+1==sz);
					got[sz-1]=s[vx[sz-1]][y];
				}
				else {
					assert(ox.size()==sz);
				}
				b.PB(got);
			}
			sort(b.begin(),b.end());
			if (a==b) {
				return true;
			}
		} while(next_permutation(vx.begin(),vx.end()));
	}
	return false;
}

