using namespace std;
template<typename T>inline void read(T&x)
{
	T f;register char ch;x=0;f=1;
	for(ch=getchar();!isdigit(ch);ch=getchar())if(ch=='-')f=-1;
	for(;isdigit(ch);ch=getchar())x=(x*10)+(ch^48);
	x*=f;
}

const int MAXN=13;

static int n,m;
static char s[MAXN][MAXN];

inline void init()
{
	read(n);read(m);
	Rep(i,1,n)scanf("%s",s[i]+1);
}

static int buc[13][27];

bitset<(1<<12)>dp[13];

inline bool getmid(int x)
{
	int u=x;x=0;
	while(u)++x,u>>=1;
	static int ff;ff=0;
	Rep(i,0,25)if(buc[x][i]&1)
	{if(!ff)ff=1;else return false;}
	return true;
}

inline void solve()
{
	static int mx=(1<<n)-1;
	dp[0].set(0);
	Rep(i,1,n)
	{
		dp[i]=dp[i-1];
		Rep(j,1,m)++buc[i][s[i][j]-'a'];
		Repe(j,i-1,1)
		{
			int flg=1;
			Rep(k,0,25)if(buc[i][k]!=buc[j][k]){flg=0;break;}
			int ke=(1<<i-1)|(1<<j-1);
			if(flg)Rep(k,0,mx)if(!(k&ke)&&dp[i-1].test(k))dp[i].set(k^ke);
		}
	}
	int flg=0;
	Rep(k,0,mx)if(__builtin_popcount(k)>=n-1&&dp[n].test(k))
		if(~n&1||getmid(mx^k)){flg=1;break;}
	if(!flg)return(void)puts("NO");

	mx=(1<<m)-1;
	dp[0].set(0);
	memset(buc,0,sizeof buc);
	Rep(i,1,m)
	{
		dp[i]=dp[i-1];
		Rep(j,1,n)++buc[i][s[j][i]-'a'];
		Repe(j,i-1,1)
		{
			int flg=1;
			Rep(k,0,25)if(buc[i][k]!=buc[j][k]){flg=0;break;}
			int ke=(1<<i-1)|(1<<j-1);
			if(flg)Rep(k,0,mx)if(!(k&ke)&&dp[i-1].test(k))dp[i].set(k^ke);
		}
	}
	flg=0;
	Rep(k,0,mx)if(__builtin_popcount(k)>=m-1&&dp[m].test(k))
		if(~m&1||getmid(mx^k)){flg=1;break;}
	if(!flg)return(void)puts("NO");
	puts("YES");
}

int main()
{
	init();
	solve();
	return 0;
}

