int H, W;
char S[12][20];

bool check(char T[12][20], int h, int w)
{
	bool P[12] = {};
	int count = 0;
	for (int i = 0; i < w; i++) {
		for (int j = i + 1; j < w; j++) {
			if (P[i] || P[j]) continue;
			bool f = true;
			for (int k = 0; k < h; k++) {
				if (T[k][i] != T[h - k - 1][j]) {
					f = false;
					break;
				}
			}
			if (f) {
				P[i] = true;
				P[j] = true;
				count += 2;
			}
		}
	}
	if (count == w) return true;
	if (count <= w - 2) return false;
	for (int i = 0; i < w; i++) {
		if (P[i]) continue;
		for (int k = 0; k < h; k++) {
			if (T[k][i] != T[h - k - 1][i]) {
				return false;
			}
		}
		return true;
	}
	return false;
}

bool next_group(int* A, int n)
{
	bool used[12];
	fill(used, used + n, true);
	for (int i = n / 2 - 1; i >= 0; i--) {
		int first = A[i * 2];
		int second = A[i * 2 + 1];
		used[second] = false;
		bool overflow = true;
		for (int j = second + 1; j < n; j++) {
			if (!used[j]) {
				second = j;
				overflow = false;
				break;
			}
		}
		if (!overflow) {
			A[i * 2 + 1] = second;
			used[second] = true;
			int k = (i + 1) * 2;
			for (int j = 0; j < n; j++) {
				if (used[j]) continue;
				A[k] = j;
				used[j] = true;
				k++;
			}
			return true;
		}
		used[first] = false;
	}
	return false;
}

