	for (int i = 0; i < K; i++) {
		P[i] = i;
	}
	char T[12][20];
	do {
		for (int i = 0; i < K; i++) {
			if (P[i] == H) {
				int p = P[i & 1 ? i - 1 : i + 1];
				for (int j = 0; j < W; j++) {
					T[H / 2][j] = S[p][j];
				}
				break;
			}
		}
		int y = 0;
		for (int i = 0; i < K; i += 2) {
			if (P[i] == H || P[i + 1] == H) continue;
			for (int j = 0; j < W; j++) {
				T[y][j] = S[P[i]][j];
				T[H - y - 1][j] = S[P[i + 1]][j];
			}
			y++;
		}
		if (check(T, H, W)) {
			printf("YES\n");
			return 0;
		}
	} while (next_group(P, K));
	printf("NO\n");

	return 0;
}

