      std::reverse(all(v));
      auto it = std::find(all(grid), v);
      if (it == grid.end()) return false;
      grid.erase(it);
    }
    if (grid.empty()) return true;
    assert(grid.size() == 1u);
    auto v = grid.front();
    return v == std::vector<char>(v.rbegin(), v.rend());
  };

