void makepair(vector<pii> current, int unused, int num_unused) {
    if (num_unused == 1) {
        rep(i, 12) {
            if ((unused >> i) & 1) {
                current.push_back(pii(i, i));
                break;
            }
        }
        pairs.push_back(current);
        return;
    }
    if (num_unused == 2) {
        int a;
        rep(i, 12) {
            if ((unused >> i) & 1) {
                a = i;
                break;
            }
