        for (int i = a + 1; i < 12; ++i) {
            if ((unused >> i) & 1) {
                current.push_back(pii(a, i));
                break;
            }
        }
        pairs.push_back(current);
        return;
    }

    int a;
    rep(i, 12) {
        if ((unused >> i) & 1) {
            a = i;
            unused ^= 1 << a;
            break;
        }
    }
    for (int i = a + 1; i < 12; ++i) {
        if ((unused >> i) & 1) {
            current.push_back(pii(a, i));
