bool solve(int y, int x) {
	if (y*2 >= h&&x*2 >= w) {
		rep(i, h) {
			rep(j, w) {
				if (s[i][j] != s[h - 1 - i][w - 1 - j])	return false;
			}
		}
		return true;
	}
	x = min(x, (w - 1) / 2);
	y = min(y, (h - 1) / 2);
	int tox = w - 1 - x, toy = h - 1 - y;
	SREP(i, y, toy)	SREP(j, x, tox) {
		if (i == y&&j == x)	continue;
		if (s[i][j] == s[y][x] && s[i][x] == s[y][j]) {
			rep(k, h)	swap(s[k][j], s[k][w - 1 - x]);
			rep(k, w)	swap(s[i][k], s[h - 1 - y][k]);
			if (solve(y + 1, x + 1)) {
				return true;
			}
		}
	}
	return false;
}

