const double pi = acos(-1);

int p[N];
string s[N];
bool chosen[N];
int n, m;

bool check() {
	vector<string> lhs, rhs;

	rep(j, 0, m) {
		string cur = "";
		rep(i, 0, n) cur += s[p[i]][j];
		lhs.push_back(cur);
		reverse(cur.begin(), cur.end());
		rhs.push_back(cur);
	}

	sort(lhs.begin(), lhs.end());
	sort(rhs.begin(), rhs.end());

	rep(i, 0, sz(lhs)) if (lhs[i] != rhs[i]) return false;

	lhs.insert(lhs.end(), rhs.begin(), rhs.end());
	sort(lhs.begin(), lhs.end());

	int alone = 0;
	rep(i, 1, sz(lhs)) {
		if (i + 1 == sz(lhs) || lhs[i] != lhs[i + 1]) {
			if (i == 1 || lhs[i - 1] != lhs[i - 2]) ++alone;
		}
	}

	return true && alone <= 1;
}

int u, v;

void go() {
	int lhs = -1;
	rep(i, 0, n) if (!chosen[i]) {
		lhs = i; break;
	}

	if (lhs == -1) {
		if (check()) {
			puts("YES");
			exit(0);
		}
		return;
	}

	rep(i, lhs + 1, n) if (!chosen[i]) {
		p[u++] = lhs;
		p[v--] = i;
		chosen[lhs] = chosen[i] = true;
		go();
		--u; ++v;
		chosen[lhs] = chosen[i] = false;
	}

}

void solve() {
	cin >> n >> m;
	rep(i, 0, n) cin >> s[i];
	rep(i, 0, n) p[i] = -1;
	u = 0; v = n - 1;

	if (n & 1) {
		rep(i, 0, n) {
			chosen[i] = true;
			p[n / 2] = i;
			go();
			p[n / 2] = -1;
			chosen[i] = false;
		}
	} else
		go();
	puts("NO");
}



