#include<bits/stdc++.h>
using namespace std;

int H, W;
vector<string> S;

bool check(auto group) {
  vector<string> upper, lower;
  for(auto i=0; i<H; ++i) {
    if((group>>i) & 1) upper.emplace_back(S[i]);
    else               lower.emplace_back(S[i]);
  }
  vector<string> T(begin(upper), end(upper));
  T.insert(end(T), begin(lower), end(lower));
  sort(begin(T), begin(T) + upper.size());
  do {
    vector<string> column(W);
    for(auto j=0; j<W; ++j) for(auto i=0; i<H; ++i) column[j] += T[i][j];
    auto ok = true;
    set<string> uniq;
    map<string, int> m;
    for(auto s: column) ++m[s];
    for(auto s: column) {
      auto t = s;
      reverse(begin(t), end(t));
      if(s == t) {
        if(m[s]&1) uniq.emplace(s);
      } else {
        if(m[s] != m[t]) ok = false;
      }
    }
    if(ok && uniq.size()<=1) return true;
  } while(next_permutation(begin(T), begin(T) + upper.size()));
  return false;
}

bool dfs(auto group, auto i, auto n) {
  if(n == (H+1)/2) return check(group);
  if(i == H)       return false;
  return dfs(group, i+1, n) || dfs(group | (1<<i), i+1, n+1);
}

string solve() {
  return dfs(0, 0, 0) ? "YES" : "NO";
}

int main() {
  cin >> H >> W;
  S.resize(H);
  for(auto& s: S) cin >> s;
  cout << solve() << endl;
}

#include <bits/stdc++.h>
using namespace std;

int H, W;
vector<vector<int> > S;

int main()
{
    cin >> H >> W;

    for (int i = 0; i < H; i++)
    {
        for (int j = 0; j < W; j++)
        {
            unsigned char hoge;
            cin >> hoge;
            S.resize(H);
            S[i].push_back((unsigned int)hoge);
        }
    }


    int rowPattern = 1;
    for (int i = H; i > 0;)
    {
        if (i == 1)
        {
            break;
        }
        else if (i % 2)
        {
            rowPattern *= i;
            i--;
        }
        else
        {
            rowPattern *= (i - 1);
            i = i - 2;
        }
    }

    for (int pp = 0; pp < rowPattern; pp++)
    {
        int p = pp;
        int center = -1;
        vector<vector<int> > Scopy = S;
        vector<vector<int> > Snew(H);

        if (H%2)
        {
            center = p % H;
            p = p / H;
            Snew[(int)(H / 2)] = Scopy[center];
            Scopy.erase(Scopy.begin() + center);
        }

        int pairNum = H / 2;
        for (int i = 0; i < pairNum; i++)
        {
            int tmp = p % (2 * (pairNum - i) - 1);
            p /= (2 * (pairNum - i) - 1);

            Snew[i] = Scopy[0];
            Scopy.erase(Scopy.begin());
            Snew[H - 1 - i] = Scopy[tmp];
            Scopy.erase(Scopy.begin() + tmp);
        }

        vector<vector<int> > columns(W);
        for (int i = 0; i < H; i++)
        {
            for (int j = 0; j < W; j++)
            {
                columns[j].push_back(Snew[i][j]);
            }
        }

        while (!columns.empty())
        {
            int matchedColumn = -1;
            for (int i = 1; i < columns.size(); i++) // 0列目とi列目を比較
            {
                bool matchedFlag = true;
                for (int j = 0; j<H; j++)
                {
                    if (columns[0][j] != columns[i][H-1-j])
                    {
                        matchedFlag = false;
                        break;
                    }
                }

                if (matchedFlag)
                {
                    matchedColumn = i;
                    break;
                }
            }

            if (columns.size() %2 && matchedColumn < 0)
            {
                columns.erase(columns.begin());
                continue;
            }

            if (!(columns.size()%2) && matchedColumn < 0)
                break;

            columns.erase(columns.begin() + matchedColumn);
            columns.erase(columns.begin());
        }
        if (columns.empty())
        {
            cout << "YES\n";
            return 0;
        }
    }

    cout << "NO\n";
    return 0;
}

