bool isequal(int i, int j) {
	for (int k = 1; k <= m; k++) {
		if (c[i][k] != c[j][k]) return false;
	}
	return true;
}

bool iseq(int i, int j) {
	for (int k = 1; k <= n; k++) {
		if (cc[i][k] != cc[j][k]) return false;
	}
	return true;
}

bool check() {
	for (int i = 1; i <= m; i++) {
		if (u[i]) continue;
		for (int j = i + 1; j <= m; j++) {
			if (u[j]) continue;
			if (iseq(i, j)) {
				u[i] = u[j] = 1;
				break;
			}
		}
	}
	int cnt = 0;
	for (int i = 1; i <= m; i++) {
		if (!u[i]) cnt++;
	}
	if (cnt <= 1) {
		if (cnt == 0) return 1;
		for (int i = 1; i <= m; i++) {
			if (!u[i]) cnt = i;
		}
		memset(freq, 0, sizeof freq);
		for (int i = 1; i <= n; i++) {
			freq[(int)cc[cnt][i]]++;
		}
		cnt = 0;
		for (int i = 'a'; i <= 'z'; i++) {
			if (freq[i] & 1) {
				cnt++;
				pos = i;
			}
		}
		if (n & 1) {
			return cnt == 1;
		} else {
			return cnt == 0;
		}
	} 
	return 0;
}

