        if (center_col)
        {
            j=(l+r)/2;
            if (a[i][j]!=a[h-i-1][w-j-1]) return false;
        }
    }
    string t[15];
    int cnt=0;
    for (j=l;j<r;j++)
    {
        if ((!center_col)&&((l+r)/2==j)&&((l+r)%2==1)) continue;
        for (i=0;i<h;i++)
        {
            t[cnt]+=a[i][j];
        }
        cnt++;
    }
    sort(t,t+cnt);
    for (j=0;j<(cnt+1)/2;j++)
    {
        string t1=t[j];
        string t2=t[cnt-1-j];
        reverse(t2.begin(),t2.end());
        if (t1!=t2) return false;
