    for (j=0;j<w;j++)
    {
        for (i=0;i<u;i++)
        {
            if (a[i][j]!=a[h-i-1][w-j-1]) return false;
        }
        for (i=d;i<h;i++)
        {
            if (a[i][j]!=a[h-i-1][w-j-1]) return false;
        }
        if (center_row)
        {
            i=(u+d)/2;
            if (a[i][j]!=a[h-i-1][w-j-1]) return false;
        }
    }
    string t[15];
    int cnt=0;
    for (i=u;i<d;i++)
    {
        if ((!center_row)&&((u+d)/2==i)&&((u+d)%2==1)) continue;
        for (j=0;j<h;j++)
