{
	ios::sync_with_stdio(false);
	cin.tie(0);
	cin>>n>>m;
	for(int i=1;i<=n;i++)cin>>s[i];
	if(m&1)
	{
		for(int i=1;i<=m;i++)
		{
			seq[(m+1)/2]=i;
			match[i]=i;
			solve(1);
			match[i]=0;
		}
	}
	else
	{
		solve(1);
	}
	printf("NO");
	return 0;
}

