	for (short i = 0;i < W;i++) {
		if (V[i])continue;
		for (short j = i + 1;j < W;j++) {
			if (V[j])continue;

			if (stpst(OG[i], OG[j])) {
				V[i] = 1, V[j] = 1;
				st.insert({ i,j });
				if (fsolve(V, st))return 1;
				st.erase(--st.end());
				V[i] = 0;V[j] = 0;
			}
		}
		if (solow < 0)solow = i;
		else return 0;
	}

	if (solow < 0)return 1;
	if (stpst(OG[solow]))return 1;
	return 0;
}

