	}

	for (auto i : st) {
		for (int j = 0;j < H;j++) {
			for (int k = 0;k < W;k++) {
				OG[k][j] = Grid[i.first][k];
				OG[k][H - j - 1] = Grid[i.second][k];
			}
		}
