bool isPalindrome(string &S) {
    memset(chars, 0, sizeof(chars));
    for (int i = 0; i < S.length(); i++) {
        chars[S[i]] += 1;
    }

    int odd = 0, even = 0;
    for (int i = 'a'; i <= 'z'; i++) {
        if (chars[i]%2 == 0) even += 1;
        else odd += 1;
    }
    for (int i = 'A'; i <= 'Z'; i++) {
        if (chars[i]%2 == 0) even += 1;
        else odd += 1;
    }

    if (S.length()%2 == 0) {
        if (odd == 0) return true;
        else return false;
    } else {
        if (odd == 1) return true;
        else return false;
    }
}

