bool check(char T[12][20], int h, int w)
{
	bool pair[12] = {};
	int count = 0;
	for (int i = 0; i < w; i++) {
		for (int j = 0; j < w; j++) {
			if (i == j || pair[i] || pair[j]) continue;
			bool f = true;
			for (int k = 0; k < h; k++) {
				if (T[k][i] != T[h - k - 1][j]) {
					f = false;
					break;
				}
			}
			if (f) {
				pair[i] = true;
				pair[j] = true;
				count += 2;
			}
		}
	}
	if (count == w) return true;
	if (count < w - 1) return false;
	for (int i = 0; i < w; i++) {
		if (pair[i]) continue;
		for (int k = 0; k < h; k++) {
			if (T[k][i] != T[h - k - 1][i]) {
				return false;
			}
		}
		return true;
	}
	return false;
}

bool next_group(int* A, int n)
{
	bool used[12];
	fill(used, used + n, true);
	for (int i = n / 2 - 1; i >= 0; i--) {
		int first = A[i * 2];
		int second = A[i * 2 + 1];
		used[second] = false;
		bool overflow = true;
		for (int j = second + 1; j < n; j++) {
			if (!used[j]) {
				second = j;
				overflow = false;
				break;
			}
		}
		if (!overflow) {
			A[i * 2 + 1] = second;
			used[second] = true;
			int k = (i + 1) * 2;
			for (int j = 0; j < n; j++) {
				if (used[j]) continue;
				A[k] = j;
				used[j] = true;
				k++;
			}
			return true;
		}
		used[first] = false;
	}
	return false;
}

int main(int argc, char* argv[])
{
	scanf("%d%d", &H, &W);
	for (int i = 0; i < H; i++) {
		scanf("%s", S[i]);
	}
	int P[12];
	int K = H + (H & 1);
	for (int i = 0; i < K; i++) {
		P[i] = i;
	}
	char T[12][20];
	do {
		for (int i = 0; i < K; i++) {
			if (P[i] == H) {
				int p = i & 1 ? i - 1 : i + 1;
				for (int j = 0; j < W; j++) {
					T[H / 2][j] = S[p][j];
				}
				break;
			}
		}
		int y = 0;
		for (int i = 0; i < K; i += 2) {
			if (P[i] == H || P[i + 1] == H) continue;
			for (int j = 0; j < W; j++) {
				T[y][j] = S[P[i]][j];
				T[H - y - 1][j] = S[P[i + 1]][j];
			}
			y++;
		}
		if (check(T, H, W)) {
			printf("YES\n");
			return 0;
		}
	} while (next_group(P, K));
	printf("NO\n");

	return 0;
}

