bool isPalindromic(const std::string& s) {
	size_t sn = s.size();
	size_t n = sn / 2;
	for (size_t i = 0; i < n; ++i) {
		if (s[i] != s[sn - i - 1]) return false;
	}
	return true;
}

bool check(int h, int w, std::vector<std::string> s) { // O(H!W!HW)
	return [&] {
		std::vector<int> v(h);
		std::iota(ALL(v), 0);
		do {
			std::vector<int> u(w);
			std::iota(ALL(u), 0);
			do {
				bool conti = [&] {
					REP(i, h) REP(j, w) {
						if (s[v[i]][u[j]] != s[v[h - i - 1]][u[w - j - 1]]) return true;
					}
					return false;
				}();
				if (conti) continue;
				else return true;
			} while (std::next_permutation(ALL(u)));
		} while (std::next_permutation(ALL(v)));
		return false;
	}();
}

bool solve(int h, int w, std::vector<std::string> s) {
	std::vector<int> vc(w); // ペア番号を格納した配列
	std::iota(ALL(vc), 0); // vc = {0,1,2,3,…,w-1}
	REP(j, w) vc[j] /= 2; // vc = {0,0,1,1,…,[(w-1)/2]}
	do { // vcを回していく
		{
			bool ok = true;
			int p = 0; // 今まで出てきた最大のペア番号
			REP(i, w) {
				if (w % 2 == 1 && vc[i] == w / 2) continue; // wが奇数のとき,ペアにならない列は除外
				if (vc[i] < p) continue; // p未満がすでに出てきているのは問題なし
				if (vc[i] == p) { ++p; continue; }
				ok = false; // vc[i]がpより大きいものは除外
				break;
			}
			if (!ok) continue;
		}
		std::vector<int> v(vc); // vcを用いて元の列vを構成する
		{
			std::vector<int> cnt((w + 1) / 2, 0); // ペア番号の出てきた数を格納する
			REP(j, w) {
				if (cnt[v[j]] == 0) ++cnt[v[j]]; // 初めに出てきたものはそのまま(列番号i)
				else v[j] = w - v[j] - 1; // 二回目に出てきたものは弄る(列番号w-i-1)
			}
		}

		std::map<std::string, int> map;
		REP(i, h) {
			std::string ss(w, ' ');
			REP(j, w) ss[v[j]] = s[i][j];
			++map[ss];
		}
		int odd = h % 2;
		bool ok = true;
		for (auto& x : map) {
			if (isPalindromic(x.first)) {
				if (x.second % 2 == 1) --odd;
				continue;
			}
			auto ss(x.first);
			std::reverse(ALL(ss));
			if (x.second != map[ss]) {
				ok = false;
				break;
			}
		}
		if (!ok || odd != 0) continue;
		return true;
	} while (std::next_permutation(ALL(vc)));
	return false;
}

