int n, m, r[N];
string s[N], ss[N], t[N];

void check() {
	map<string, int> M;
	for (int i = 0; i < m; i++) {
		string str;
		for (int j = 0; j < n; j++) {
			str += t[j][i];
		}
		M[str]++;
	}
	bool f = m & 1;
	for (map<string, int>::iterator it = M.begin(); it != M.end(); it++) {
		string str = it->first;
		string str1 = str;
		reverse(str1.begin(), str1.end());
		if (it->second != M[str1]) return;
		if (str == str1) {
			if (!f && it->second & 1) return;
			if (it->second & 1) f = 0;
		}
	}
	printf("YES\n");
	exit(0);
}

void solve(int row, int rownum, bool f) {
	if (row == n && rownum == n) { check(); return; }
	if (row == n || t[rownum] != "") { solve(row, rownum + 1, f); return; }
	if (r[row]) { solve(row + 1, rownum, f); return; }
	r[row] = 1;
	for (int i = row + 1; i < n; i++) {
		if (ss[i] != ss[row] || r[i]) continue;
		r[i] = 1;
		t[rownum] = s[row];
		t[n - 1 - rownum] = s[i];
		solve(row + 1, rownum + 1, f);
		t[n - 1 - rownum] = "";
		t[rownum] = "";
		r[i] = 0;
	}
	if (f) {
		t[n / 2 + 1] = s[row];
		solve(row + 1, rownum, 0);
		t[n / 2 + 1] = "";
	}
	r[row] = 0;
}

