	for (int i = 0; i < n; i++) cin >> s[i];
	for (int i = 0; i < n; i++) {
		ss[i] = s[i];
		sort(ss[i].begin(), ss[i].end());
	}
	solve(0, 0, n & 1);
	printf("NO\n");
	return 0;
}

