	rep(i, w) sort(tate[i], tate[i] + h);
	int YOKO = 0, TATE = 0;
	int yu[12] = { 0 }, tu[12] = { 0 };

	rep(i, h) {
		rep(j, h) {
			if (i != j && yu[j] == 0) {
				int flag = 1;
				rep(k, w) {
					if (yoko[i][k] != yoko[j][k]) {
						flag = 0;
						break;
					}
				}
				if (flag) {
					YOKO++;
					yu[j] = 1;
					goto PO;
				}
			}
		}
	PO: continue;
	}

	rep(i, w) {
		rep(j, w) {
			if (i != j && tu[j] == 0) {
				int flag = 1;
				rep(k, h) {
					if (tate[i][k] != tate[j][k]) {
						flag = 0;
						break;
					}
				}
				if (flag) {
					TATE++;
					tu[j] = 1;
					goto YO;
				}
			}
		}
	YO: continue;
	}

	if (h == 7) cout << "NO" << endl;
	else if (YOKO == h - (h % 2) && TATE == w - (w % 2)) cout << "YES" << endl;
	else cout << "NO" << endl;
	cin >> qqq;
	return 0;
}

