#include <bits/stdc++.h>

using namespace std;

int n, m, c[12];
char g[12][13], h[12][13];
bool e[12][12], used[12];
unsigned long long sign[12], r_sign[12]; 

bool ck(int u, int cnt) {
  if (u == n) { return cnt >= n / 2; }

  if (used[u]) {
    if (ck(u + 1, cnt)) return true;
    else return false;
  }

  if (n & 1) {
    if (e[u][u]) {
      used[u] = true;
      if (ck(u + 1, cnt)) return true;
      used[u] = false;
    }
  }

  for (int v = 0; v < n; ++v) {
    if (v != u && !used[v] && e[u][v]) {
      used[u] = used[v] = true;
      if (ck(u + 1, cnt + 1)) return true;
      used[u] = used[v] = false;
    }
  }

  return false;
}

int main() {

  cin >> n >> m;
  for (int i = 0; i < n; ++i) cin >> g[i];

  for (int x = 0; x < (1 << m); ++x) {

    int cnt = 0;
    for (int i = 0; i < m; ++i) {
      if ((x >> i) & 1) ++cnt;
    }
    if (cnt != m / 2) continue;

    vector<int> a, b;
    for (int i = 0; i < m; ++i) {
      if ((x >> i) & 1) { a.push_back(i); }
      else { b.push_back(i); }
    }

    for (int i = 0; i < (m + 1) / 2; ++i) c[i] = i;    

    do {      

      for (int r = 0; r < n; ++r) {  
        for (int i = 0; i < m / 2; ++i) {
          // a[i], b[c[i]]
          h[r][i] = g[r][a[i]];
          h[r][m - 1 - i] = g[r][b[c[i]]]; 
        }
        if (m & 1) {
          h[r][m / 2] = g[r][b[c[m / 2]]];
        }
        h[r][m] = '\0';
//        cout << h[r] << endl;
      }

//      cout << endl;

      memset(e, 0x00, sizeof(e));

      for (int i = 0; i < n; ++i) {
        sign[i] = r_sign[i] = 0;
        for (int j = 0; j < m; ++j) {
          sign[i] = sign[i] * 31 + h[i][j];
          r_sign[i] = r_sign[i] * 31 + h[i][m - 1 - j];
        }
      }

      for (int i = 0; i < n; ++i) {
        for (int j = i; j < n; ++j) {
          if (sign[i] == r_sign[j]) {
            e[i][j] = e[j][i] = true;
          }
        }
      }

      memset(used, 0x00, sizeof(used));
      if (ck(0, 0)) {
        cout << "YES" << endl;
        return 0;
      }

    } while (next_permutation(c, c + (m + 1) / 2));

  }

  cout << "NO" << endl;

  return 0;
}

