int soroe(vector<string> &s) {

    map<string, ll> m;
    REP(i, s.size()) {
        sort(ALL_OF(s[i]));
        m[s[i]]++;
    }
    ll ones = 0, twos = 0;
    for (const pair<string, ll> &p : m) {
        twos += p.second / 2;
        if (p.second % 2) {
            ones++;
        }
    }
    if (s.size() % 2 != ones) {
        return 0;
    } else {
        return m.size() == 1 ? 2 : 1;
    }

}

