        }
    }
    return ret;
}

bool calc(const V<ll> &nodes) {
    VV<ll> mat(W, V<ll>(W, 0));
    for(ll i = 0; i + 1 < nodes.size(); i += 2) {
        ll f = nodes[i], t = nodes[i + 1];
        if(f == -1 || t == -1) return false;
        for(ll alp = 0; alp < 26; alp++) for(ll fe : alp_list[f][alp]) for(ll te : alp_list[t][alp]) mat[fe][te]++;
    }
    bool ret = false;
    V<bool> used(W, false);
    if(W & 1) {
        for(ll w = 0; w < W; w++) {
            used[w] = true;
            ll tmp = check_col(mat, used, nodes.size() / 2);
            ret |= (tmp == W / 2);
            used[w] = false;
        }
    } else {
        ret = (check_col(mat, used, nodes.size() / 2) == W / 2);
    }
    return ret;
}

bool dfs(V<ll> &nodes, ll depth, ll max_d, V<bool> &used) {
    if((H & 1) && depth + 1 == max_d) {
        nodes[depth] = nodes[depth - 1];
        bool ret = calc(nodes);
        nodes[depth] = -1;
        return ret;
    }
    if(depth == max_d) return calc(nodes);
    bool ret = false;
    for(ll i = 0; i < H; i++) {
        if(used[i]) continue;
        if((depth & 1) && !(same_poss[i][nodes[depth - 1]])) continue;
        nodes[depth] = i;
        used[i] = true;
        ret |= dfs(nodes, depth + 1, max_d, used);
        if(ret) break;
        used[i] = false;
        nodes[depth] = -1;
    }
    return ret;
}

