void solve_col(int i, bool flag) {
	if (i == m) {
		puts("YES\n");
		exit(0);
	}
	if (~match1[i]) {
		solve_col(i + 1, flag);
		return;
	}
	for (int j = 0; j < m; j++) {
		if (j == i) continue;
		if (~match1[j]) continue;
		bool same = 1;
		for (int k = 0; k < n; k++) {
			if (s[k][i] != s[match[k]][j]) {
				same = 0;
				break;
			}
		}
		if (!same) continue;
		match1[i] = j;
		match1[j] = i;
		solve_col(i + 1, flag);
		match1[j] = -1;
	}
	if (flag) {
		bool same = 1;
		for (int j = 0; j < n; j++) {
			if (s[j][i] != s[match[j]][i]) {
				same = 0;
				break;
			}
		}
		if (same) {
			match1[i] = i;
			solve_col(i + 1, 0);
		}
	}
	match1[i] = -1;
}

void solve_row(int i, bool flag) {
	if (i == n) {
		memset(match1, -1, sizeof match1);
		solve_col(0, m & 1);
		return;
	}
	if (~match[i]) {
		solve_row(i + 1, flag);
		return;
	}
	for (int j = 0; j < n; j++) {
		if (j == i) continue;
		if (ss[j] != ss[i]) continue;
		if (~match[j]) continue;
		match[i] = j;
		match[j] = i;
		solve_row(i + 1, flag);
		match[j] = -1;
	}
	if (flag) {
		match[i] = i;
		solve_row(i + 1, 0);
	}
	match[i] = -1;
}

