    srep(i, cstart, w) {
        if (checked[i]) continue;
        srep (j, i+1, w) {
            if (checked[j]) continue;
            if (colums_rearranged[i] == colums_rearranged_reverse[j]) {
                checked[i] = checked[j] = true;
