    if (start >= h / 2) return judge(rows_rearranged, start);

    int idx1 = start;
    srep (i, start, h) {
        if (used[i]) continue;
        idx1 = i;
        break;
    }
    rows_rearranged[start] = rows[idx1];
    used[idx1] = true;

