bool sub(vi& hpat){
    vector<ll> xs, ys;
    map<ll,int> same;
    rep(j,W){
        ll x = 0, y = 0;
        rep(i,H){
            int rx = hpat[i], ry = hpat[H-1-i];
            x = (x << 5LL) | S_[rx][j];
            y = (y << 5LL) | S_[ry][j];
        }
        if (x == y) same[x]++;
        else { xs.pb(x); ys.pb(y); }
    }

    int unpaired = 0;
    for (auto p: same){
        ll x = p.first; int cnt = p.second;
        if (cnt % 2) unpaired++;
    }
    if (unpaired != W%2) return false;


    vector<ii> pairs;
    int m = xs.size();
    assert(m % 2 == 0);
    repC2(i,j,m){
        if (xs[i] == ys[j])
            pairs.pb(ii(i,j));
    }
    int mmc = maximum_match_count(pairs);
    return (mmc == m/2);
}


