bool check(char T[12][20], int h, int w)
{
	int P = 0;
	int count = 0;
	for (int i = 0; i < w; i++) {
		for (int j = i + 1; j < w; j++) {
			if (P >> i & 1 || P >> j & 1) continue;
			bool f = true;
			for (int k = 0; k < h; k++) {
				if (T[k][i] != T[h - k - 1][j]) {
					f = false;
					break;
				}
			}
			if (f) {
				P |= 1 << i;
				P |= 1 << j;
				count += 2;
			}
		}
	}
	if (count == w) return true;
	if (count <= w - 2) return false;
	for (int i = 0; i < w; i++) {
		if (P >> i & 1) continue;
		for (int k = 0; k < h; k++) {
			if (T[k][i] != T[h - k - 1][i]) {
				return false;
			}
		}
		return true;
	}
	return false;
}

bool next_group(int* A, int n)
{
	int used = -1;
	for (int i = n / 2 - 1; i >= 0; i--) {
		int first = A[i * 2];
		int second = A[i * 2 + 1];
		used &= ~(1 << second);
		if (~used >= (1 << (second + 1))) {
			for (int j = second + 1; j < n; j++) {
				if (!(used >> j & 1)) {
					second = j;
					break;
				}
			}
			A[i * 2 + 1] = second;
			used |= 1 << second;
			int k = (i + 1) * 2;
			for (int j = 0; j < n; j++) {
				if (used >> j & 1) continue;
				A[k] = j;
				used |= 1 << j;
				k++;
			}
			return true;
		}
		used &= ~(1 << first);
	}
	return false;
}

