		for (int i = 0; i < K; i += 2) {
			if (P[i] == H) {
				for (int j = 0; j < W; j++) {
					T[H / 2][j] = S[P[i + 1]][j];
				}
			} else if (P[i + 1] == H) {
				for (int j = 0; j < W; j++) {
					T[H / 2][j] = S[P[i]][j];
				}
			} else {
				for (int j = 0; j < W; j++) {
					T[y][j] = S[P[i]][j];
					T[H - y - 1][j] = S[P[i + 1]][j];
				}
				y++;
			}
		}
