        int p1 = part1_map[possible_pairs[i].first];
        int p2 = part2_map[possible_pairs[i].second];
        assert((0 <= p1 && p1 < P1) && (0 <= p2 && p2 < P2));

        capacity[1+p1][1+P1+p2] = 1;
    }
    for (int i=0; i<P2; ++i) {
        capacity[1+P1+i][1+P1+P2] = 1;
    }

    int s = 0, t = w-1;
    vector<vector<int> > resid(w, vector<int>(w, 0));
    for (int j=0; j<w-1; ++j) {
        for (int k=j+1; k<w; ++k) {
            resid[j][k] = capacity[j][k];
            resid[k][j] = 0;
        }
    }
    int total = 0;
    for (total=0; ; ++total) {
        bool another_way = false;
        vector<int> prev(w, infty);
        queue<pair<int, int> > q;
        q.push(pair<int, int>(s, -1));
        while (!q.empty()) {
            pair<int, int> p = q.front();
            int node = p.first, prev_node = p.second;
            q.pop();
            prev[node] = prev_node;
            if (node == t) { another_way = true; break; }
            rep(i, w) {
                if (resid[node][i] == 0) continue;
                if (prev[i] < infty) continue;
                q.push(pair<int, int>(i, node));
            }
        }
        if (!another_way) {
            return total;
        }
        for (int node=t; node!=s; node=prev[node]) {
            int prev_node = prev[node];
            resid[prev_node][node]--;
            resid[node][prev_node]++;
        }
    }
    return 0;
}

int H, W;
vector<string> S;
vvi S_;

bool sub(vi& hpat){

    vector<ll> xs, ys;
    map<ll,int> same;
    rep(j,W){
        ll x = 0, y = 0;
        rep(i,H){
            int rx = hpat[i], ry = hpat[H-1-i];
            x = (x << 5LL) | (ll)S_[rx][j];
            y = (y << 5LL) | (ll)S_[ry][j];
        }
        if (x == y) same[x]++;
        else { xs.pb(x); ys.pb(y); }
    }

    int unpaired = 0;
    for (auto p: same){
        ll x = p.first; int cnt = p.second;
        if (cnt % 2) unpaired++;
    }
    if (unpaired != W%2) return false;


    vector<ii> pairs;
    int m = xs.size();
    assert(m % 2 == 0);
    repC2(i,j,m){
        if (xs[i] == ys[j])
            pairs.pb(ii(i,j));
    }
    int mmc = maximum_match_count(pairs);

    return (mmc == m/2);
}


bool solve(){
    S_.resize(H);
    rep(i,H){
        S_[i].resize(W);
        rep(j,W) S_[i][j] = S[i][j] - 'a';
    }

    int hh = H/2, hl = H-hh;

    vi hhpat(H, 1);
    rep(i,hh) hhpat[i] = 0;

    vi hlpat(hl);
    vi hpat(H, 0);

    if (H % 2) {
        do {
            rep(i,hl) hlpat[i] = hh + i;
            do {
                int a=0, b=0;
                for (int i=0; i<H; ++i){
                    if (!hhpat[i]) hpat[a++] = i;
                    else           hpat[hlpat[b++]] = i;
                }
                if (sub(hpat)) return true;

            } while (next_permutation(ALL(hlpat)));
        } while (next_permutation(hhpat.begin(), hhpat.end()));
    } else {
        do {
            rep(i,hl) hlpat[i] = hh + i;
            do {
                int a=1, b=0;
                for (int i=1; i<H; ++i){
                    if (!hhpat[i]) hpat[a++] = i;
                    else           hpat[hlpat[b++]] = i;
                }
                if (sub(hpat)) return true;

            } while (next_permutation(ALL(hlpat)));
        } while (next_permutation(hhpat.begin()+1, hhpat.end()));
    }
    return false;
}

