using namespace std;
int H, W;
vector<string> S;
vector<long long> SS;
map<int, set<long long>> A;
void f(int n, int visited, long long h) {
	if (n == 0) {
		A[visited].insert(h);
		return;
	}
	for (int i = 0; i < H; ++ i) if (!((visited>>i)&1)) {
		long long hh = 6582952005840035281LL*h + SS[i];
		f(n-1, visited|(1<<i), hh);
	}
}
bool g(int mask) {
	for (const auto& a : A) {
		int v1 = a.first;
		if ((v1&mask) != v1) continue;
		int v2 = mask&~v1;
		for (auto h : a.second) {
			if (A[v2].count(h)) return true;
		}
	}
	return false;
}
bool solve() {
	int mask = (1<<H)-1;
	if (H % 2 == 0) return g(mask);
	for (int i = 0; i < H; ++ i) {
		map<char,int> a;
		for (char c : S[i]) ++ a[c];
		int cnt = 0;
		for (auto p : a) if (p.second % 2 != 0) ++ cnt;
		if (cnt > 1) continue;
		if (g(mask&~(1<<i))) return true;
	}
	return false;
}
int main() {
	cin >> H >> W;
	S = vector<string>(H);
	for (auto& x : S) {
		cin >> x;
		sort(x.begin(), x.end());
	}
	SS = vector<long long>(H, 81);
	for (int i = 0; i < H; ++ i) {
		for (int j = 0; j < W; ++ j) {
			SS[i] *= 37;
			SS[i] += S[i][j];
		}
	}
	f(H/2, 0, 0);
	cout << (solve() ? "YES" : "NO") << endl;
}

