#include <iostream>
#include <vector>
#include <string>

using namespace std;

bool valid(const vector<string>& vs){
	const int w = vs[0].size();
	const int h = vs.size();
	vector<int> used(w, 0);
	bool usePal = false;
	for(int i=0;i<w;i++){
		if(used[i]) continue;
		for(int j=w-1;j>=i;j--){
			if(used[j]) continue;
			if(j==i && (w%2 == 0 || usePal)) continue;
			bool ok = true;
			for(int k=0;k<h;k++){
				if(vs[k][i] != vs[h-1-k][j]) ok = false;
			}
			if(ok){
				used[i] = used[j] = 1;
				if(i == j) usePal = true;
				break;
			}
		}
		if(!used[i]) return false;
	}
	return true;
}

bool search(vector<string>& vs, int idx){
	int n = vs.size();
	if(idx >= n-1-idx) return valid(vs);
	bool ok = false;
	for(int i=idx+1;i<n-idx;i++){
		if(vs.size()%2 == 1 && i == vs.size()/2) continue;
		swap(vs[i], vs[n-1-idx]);
		if(search(vs, idx+1)) ok = true;
		swap(vs[i], vs[n-1-idx]);
	}
	return ok;
}

bool searchRoot(vector<string>& vs){
	if(vs.size()%2 == 0) return search(vs, 0);
	bool ok = false;
	for(int i=0;i<vs.size();i++){
		swap(vs[i], vs[vs.size()/2]);
		if(search(vs, 0)) ok = true;
		swap(vs[i], vs[vs.size()/2]);
	}
	return ok;
}

int main(){
	int H, W;
	while(cin >> H >> W){
		vector<string> vs(H);
		for(auto& s : vs) cin >> s;
		cout << (searchRoot(vs) ? "YES" : "NO") << endl;
	}
}

