int h, w;
string s[12];

string reverse(string s) {
	int l = 0, r = s.length() - 1;
	while (l < r) {
		swap(s[l], s[r]);
		l++; r--;
	}
	return s;
}

void random_col() {
	int i, j;
	srand(101);
	rep(i, 100) rand();

	int tikan[12]; bool used[12] = {false};
	rep(i, w) {
		int t;
		do {
			t = rand() % w;
		} while (used[t]);
		used[t] = true;
		tikan[i] = t;
	}

	string tmp[12]; rep(i, h) rep(j, w) tmp[i] += s[i][tikan[j]];
	rep(i, h) s[i] = tmp[i];
}

void random_row() {
	int i, j;
	srand(151);
	rep(i, 100) rand();

	int tikan[12]; bool used[12] = {false};
	rep(i, h) {
		int t;
		do {
			t = rand() % h;
		} while (used[t]);
		used[t] = true;
		tikan[i] = t;
	}

	string tmp[12]; rep(i, h) tmp[i] = s[tikan[i]];
	rep(i, h) s[i] = tmp[i];
}

signed main() {
	int i, j;

	cin >> h >> w;
	rep(i, h) cin >> s[i];

	//ランダムシャッフルを入れる
	random_row();
	random_col();

	//クロック
	clock_t startT = clock();

	int epoc = 0;
	vector<int> perm;
	for (i = 0; i < w; i++) perm.push_back(i);
	do {
		string t[12];
		rep(i, h) rep(j, w) t[i] += s[i][perm[j]];
		//cout << endl;
		//rep(i, h) cout << t[i] << endl;
		bool used[12] = {false};
		rep(i, h) {
			if (used[i]) continue;
			string tmp = reverse(t[i]);
			rep(j, h) if (j != i && !used[j] && tmp == t[j]) break;
			if (j < h) {
				used[i] = true; used[j] = true;
			}
		}

		int ngCnt = 0;
		rep(i, h) {
			if (used[i]) continue;
			if (h % 2 == 0) break;
			ngCnt++;
			if (ngCnt >= 2) break;
			if (reverse(t[i]) != t[i]) break;
		}
		if (i == h) { cout << "YES" << endl; return 0; }
		epoc++;
		if ((epoc & 1023) == 0) {
			if ((double)(clock() - startT) / CLOCKS_PER_SEC > 1.9) break;
			startT = clock();
		}
	} while (next_permutation(perm.begin(), perm.end()));
	cout << "NO" << endl;
	return 0;
}

