using namespace std;
using pii = pair<int, int>;
static int dp[1 << 12];

int check_palindrome(const string& s){
	const int n = s.size();
	vector<int> h(26);
	for(const int c : s){ ++h[c - 'a']; }
	int odd = -1;
	for(int i = 0; i < 26; ++i){
		if(h[i] % 2 == 1){
			if(odd >= 0){ return -1; }
		}else{
			odd = i;
		}
	}
	int mask = 0;
	for(int i = 0; i < n; ++i){
		if(s[i] == odd + 'a'){ mask |= (1 << i); }
	}
	return mask;
}

int main(){
	ios_base::sync_with_stdio(false);
	int n, m;
	cin >> n >> m;
	vector<string> s(n);
	for(int i = 0; i < n; ++i){ cin >> s[i]; }
	for(int i = 0; i < (1 << n); ++i){ dp[i] = -1; }
	dp[0] = (1 << m) - 1;
	for(int i = 0; i < (1 << n); ++i){
		if(dp[i] < 0){ continue; }
		for(int j = 0; j < n; ++j){
			if(i & (1 << j)){ continue; }
			for(int k = j + 1; k < n; ++k){
				if(i & (1 << k)){ continue; }
				map<pii, int> mp;
				for(int p = 0; p < m; ++p){ ++mp[pii(s[j][p], s[k][p])]; }
				bool valid = true;
				int center = -1;
				for(const auto p : mp){
					const pii key(p.first.second, p.first.first);
					const int x = p.second;
					const int y = (mp.find(key) != mp.end()) ? mp[key] : 0;
					if(x != y){ valid = false; }
					if(key.first == key.second && x % 2 != 0){
						if(m % 2 == 0 || center >= 0){
							valid = false;
						}else{
							center = key.first;
						}
					}
				}
				if(!valid){ continue; }
				int mask = 0;
				for(int p = 0; p < m; ++p){
					if(s[j][p] == center && s[k][p] == center){ mask |= (1 << p); }
				}
				const int key = i | (1 << j) | (1 << k);
				if(dp[key] < 0){ dp[key] = 0; }
				dp[key] |= (mask & dp[i]);
			}
		}
	}
	if(m % 2 == 0 && n % 2 == 0){
		cout << (dp[(1 << n) - 1] == 0 ? "YES" : "NO") << endl;
	}else if(n % 2 == 0){
		cout << (dp[(1 << n) - 1] > 0 ? "YES" : "NO") << endl;
	}else if(m % 2 == 0){
		bool answer = false;
		for(int p = 0; p < n; ++p){
			const int b = ((1 << n) - 1) & ~(1 << p);
			if(dp[b] == 0 && check_palindrome(s[p]) >= 0){
				answer = true;
			}
		}
		cout << (answer ? "YES" : "NO") << endl;
	}else{
		bool answer = false;
		for(int p = 0; p < n; ++p){
			const int b = ((1 << n) - 1) & ~(1 << p);
			const int chk = check_palindrome(s[p]);
			if(chk >= 0 && (dp[b] & chk) != 0){
				answer = true;
			}
		}
		cout << (answer ? "YES" : "NO") << endl;
	}
	return 0;
}

