	char S[12][12];
	set<int> h[12], w[12];

	scanf("%d %d", &H, &W);
	REP(i, H){
		scanf("%s", S[i]);
	}

	REP(i, H){
		REP(j, W){
			w[i].insert(S[i][j]);
			h[j].insert(S[i][j]);
		}
	}

	REP(i, H - 1){
		FOR(j, i + 1, H){
			if (f[i] != 1 && f[j] != 1){
				if (w[i] == w[j]){
					f[i] = 1;
					f[j] = 1;
				}
			}
		}
	}
	REP(i, W - 1){
		FOR(j, i + 1, W){
			if (g[i] != 1 && g[j] != 1){
				if (h[i] == h[j]){
					g[i] = 1;
					g[j] = 1;
				}
			}
		}
	}

	REP(i, H){
		if (f[i] != 1){
			a++;
		}
	}
	REP(i,W){
		if (g[i] != 1){
			b++;
		}
	}

	if (a <= 1 && b <= 1){
		printf("YES\n");
	}
	else{
		printf("NO\n");
	}

	return 0;
}

