void dfsc(int x,bool fl)
{
	if (x==m)
	{
		cout <<"YES";
		exit(0);
	}
	if (visc[x])
	{
		dfsc(x+1,fl);
		return;
	}
	visc[x]=1;
	for (int i=0;i<m;i++)
	{
		if (visc[i]) continue;
		bool jum=0;
		for (int j=0;j<n;j++) if (s[j][x]!=s[r[j]][i]) jum=1;
		if (jum) continue;
		visc[i]=1;
		dfsc(x+1,fl);
		visc[i]=0;
	}
	if (fl)
	{
		bool jum=0;
		for (int j=0;j<n;j++) if (s[j][x]!=s[r[j]][x]) jum=1;
		if (!jum) dfsc(x+1,0);
	}
	visr[x]=0;
}
void dfsr(int x,bool fl)
{
	if (x==n)
	{
		dfsc(0,m%2!=0);
		return;
	}
	if (visr[x])
	{
		dfsr(x+1,fl);
		return;
	}
	visr[x]=1;
	for (int i=0;i<n;i++)
	{
		if (visr[i] || si[x]!=si[i]) continue;
		r[x]=i,r[i]=x;
		visr[i]=1;
		dfsr(x+1,fl);
		visr[i]=0;
	}
	if (fl)
	{
		r[x]=x;
		dfsr(x+1,0);
	}
	visr[x]=0;
}
