const int cmp(const data &A, const data &B)
{ return (A.a<B.a) || (A.a==B.a&&A.b<B.b); }

bool Check(int a, int b)
{
	for(int i = 1; i <= N; ++i)
		if(s[p[i]][a] != s[p[N-i+1]][b])
			return false;
	return true;
}

bool pal(int n)
{
	for(int i = 1; i <= (N>>1); ++i)
		if(s[p[i]][n] != s[p[N-i+1]][n])
			return false;
	return true;
}

bool check()
{
	int mid = 0;
	memset(ok, 0, sizeof(ok));
	for(int i = 1; i <= M; ++i)
	{
		if(ok[i]) continue;
		for(int j = i+1; j <= M; ++j)
			if(!ok[j] && Check(i, j)) { ok[i] = ok[j] = true; break; }
		if(!ok[i])
		{
			if(M & 1)
			{
				if(!mid && pal(i)) mid = i;
				else return false;
			}
			else return false;
		}
	}
	return true;
}

void dfs(int dep)
{
	if(f) return;
	if(dep > (N>>1))
	{
		if(N & 1) for(int i = 1; i <= N; ++i) if(!used[i]) p[dep] = i;
