		if(t1[i].a!=t2[i].a || t2[i].b!=t2[i].b)
			return false;
	return true;
}

void prework()
{
	for(int i = 1; i <= N; ++i)
		if(!mt[i]) for(int j = 1; j <= N; ++j)
				if(i!=j && OK(i, j)) { mt[i] = j, mt[j] = i; break; }
}

