// 列の入れ替えのみで点対象にできるなら true
bool CheckCol(const vector<string>& s) {
    bool isUsedMapped[MAX_W] = {};
    bool isUsedS[MAX_W] = {};
    bool isFind = false;
    ll mapped_ind_head = 0;
    ll mapped_ind_tail = W-1;
    ll dbg_cnt = 0;
    REP(i, W) {
        if(isUsedS[i]) { continue; }
        isFind = false;
        isUsedS[i] = true;
        // i 列を上下反転したような列 j を探す
        REP(j, W) {
            if(isUsedS[j]) { continue; }
            bool isRev = true;
            REP(k, H) {
                if(s[k][i] != s[H-1-k][j]) { isRev = false; break; }
            }
            // 上下反転があった
            if(isRev) {
                DBG("%lld %lld is pair.\n", i, j);
                isUsedS[j] = true;
                isUsedMapped[mapped_ind_head] = true;
                isUsedMapped[mapped_ind_tail] = true;
                mapped_ind_head++;
                mapped_ind_tail--;
                dbg_cnt += 2;
                isFind = true;
                break;
            }
        }
        if(!isFind) {
            DBG("%lld is not pair.\n", i);
            // 上下反転がなかった
            if(W % 2 == 0) {
                return false;
            }
            else {
                // 奇数なら、列が上下対象なら真ん中に置ける
                bool isSym = true;
                REP(j, H / 2) {
                    if(s[j][i] != s[H-1-j][i]) { isSym = false; break; }
                }
                if(isSym && !isUsedMapped[W / 2]) {
                    DBG("  But can mapped %lld\n", W / 2);
                    isUsedMapped[W / 2] = true;
                    dbg_cnt++;
                } else {
                    return false;
                }
            }
        }
    }
    assert(dbg_cnt == W);
    return true;
}

