bool go(vector<vector<int>> v){
    int N = v.size();
    for(int i=0;i<N;i++) sort(v[i].begin(), v[i].end());
    map<vector<int>, int> m;
    for(int i=0;i<N;i++) m[v[i]]++;

    int odds = 0;
    for(auto& kv:m) if(kv.second%2) odds++;
    return odds <= 1;
}

vector<vector<int>> transpose(vector<vector<int>> v){
    int N = v.size(), M = v.front().size();
    vector<vector<int>> ret(M);
    for(int i=0;i<N;i++) for(int j=0;j<M;j++)
        ret[j].push_back(v[i][j]);
    return ret;
}

