void rotate(){
  char tmp[15][15];
  for(int i=0;i<H;i++)
    for(int j=0;j<W;j++)
      tmp[j][H-1-i] = F[i][j];
  swap(H,W);
  for(int i=0;i<H;i++)
    for(int j=0;j<W;j++)
      F[i][j] = tmp[i][j];
}

int hcheck(){
  bool f[15] = {};
  for(int i=0;i<H;i++){    
    for(int j=0;j<H;j++){
      if( i == j ) continue;
      if( f[i] || f[j] ) continue;
      if( eq(i,j) ) f[i] = f[j] = true;
    }
  }
  int cnt = 0;
  for(int i=0;i<H;i++) {
    if( !f[i] ) cnt++;
  }
  if(!(H&1)&&cnt!=0) return false;
  if((H&1)&&cnt!=1) return false;
  return true;
}

bool solve(){
  if(!hcheck()) return false;
  rotate();
  return hcheck();  
}

