                A[T | 1 << a | 1 << b].insert(p);
            }
        }
        A[T].clear();
    }

    vector<string> B = S;

    each(p, A.back()) {
        int q = 0;
        each(r, p) {
            B[q] = S[r.first];
            B[H - 1 - q] = S[r.second];
            q++;
        }

        bool okok = false;
        rep(x, W / 2) { // ここ
            okok = false;
            FOR(xx, x + 1, W - x) {
                bool ok = true;
                rep(y, H / 2) {
                    ok = ok && eq(B[y][x], B[H-1-y][xx]);
                    if (!ok)break;
                }
                if (ok) {
                    rep(y, H) {
                        swap(B[y][W-1-x], B[y][xx]);
                    }
                    okok = true;
                    break;
                }
            }
            if (!okok)break;
        }
        if (okok) {
            cout << "YES" << endl;
            return 0;
        }
    }

    cout << "NO" << endl;
}

