bool dfs(const vector<vc>& s){
	int h = s.size();
	int w = s[0].size();
	//cout << h << ' ' << w << endl; for(auto i : s){ for(auto j : i){ cout << j; } cout << endl; }

	map<vc, vector<pair<vc,int>>> m;
	rep(i,h){
		rep(j,w){
			pair<vc, vc> p = getCrossChar(s, i, j);
			m[p.first].emplace_back(p.second, i);
		}
	}

	if(m.size() == 1){
		map<vc,int> me;
		rep(i,s.size()){
			sort(all(s[i]));
			me[s[i]]++;
		}

		if(h % 2 == 1){
			int odd = 0;
			for(auto i : me){
				if(i.second % 2 == 1) odd++;
			}
			return odd == 1;
		}else{
			for(auto i : me){
				if(i.second % 2 == 1) return false;
			}
			return true;
		}
	}

	if(h % 2 == 1){
		vector<vc> nxt;
		for(auto i : m){
			if(i.second.size() == w){
				rep(j,w){
					nxt.emplace_back(getCrossChar(s, i.second[0].second, j, 1).second);
