  vector <vector<int>> a = gen(n, m, mid, mask0, 0);
  vector <vector<int>> b = gen(n, m, mid, mask0, 1);
  for (int i = 0, j = 0; i < int(a.size()) && j < int(b.size()); ) {
    if (a[i] == b[j]) {
      return true;
    } else if (a[i] < b[j]) {
      ++i;
    } else {
      ++j;
    }
  }
  return false;
}

bool solve(int n, int m, int mid) {
  for (int mask = 0; mask < (1 << n); ++mask) {
    if (mid != -1 && (mask & (1 << mid))) {
      continue;
    }
    if (mid == 0 && n != 1 && (mask & 2) == 0) { continue; }
    if (mid != 0 && (mask & 1) == 0) { continue; }
    if (__builtin_popcount(mask) != n / 2) {
      continue;
    }

    if (solve(n, m, mid, mask)) {
      return true;
    }
  }
  return false;
}

bool solve(int n, int m) {
  if (n % 2 == 1) {
    for (int i = 0; i < n; ++i) {
      if (solve(n, m, i)) {
        return true;
      }
    }
    return false;
  } else {
    return solve(n, m, -1);
  }
}

