			if (d[i - 1].first != d[i - 1].second) continue;
			fill(mark + 1, mark + m + 1, false);
			mark[i] = true;
			if (check2()) {
				puts("YES");
				exit(0);
			}
		}
	} else if (check2()) {
		puts("YES");
		exit(0);
	}
}

void brute(int cnt) {
	int p1 = -1;
	for (int i = all_pairs[cnt - 1].first + 1; i <= n; ++i) {
		if (!used[i]) {
			used[(p1 = i)] = true;
			break;
		}
	}
	if (p1 == -1) {
		check();
		return;
	}
	all_pairs[cnt].first = p1;
	for (int i = p1 + 1; i <= n; ++i) {
		if (used[i]) continue;
		all_pairs[cnt].second = i;
		used[i] = true;
		brute(cnt + 1);
		used[i] = false;
	}
	used[p1] = false;
}

