vvi S_;

bool sub(vi& hpat){

    vector<ll> xs(W), ys(W);
    rep(j,W){
        ll x = 0, y = 0;
        rep(i,H){
            int rx = hpat[i], ry = hpat[H-1-i];
            x = (x << 5LL) | S_[rx][j];
            y = (y << 5LL) | S_[ry][j];
        }
        xs[j] = x; ys[j] = y;
    }

    vector<ii> pairs;
    repC2(i,j,W){
        if (xs[i] == ys[j])
            pairs.pb(ii(i,j));
    }
    if (H%2){
        int h = (H+1)/2;
        if (xs[h] == ys[h])
            pairs.pb(ii(h,h));
    }
    int mmc = maximum_match_count(pairs);
    return (mmc == (H+1)/2);
}


