using namespace std;
class ESymmetricGrid {
 public:
  static void solve(istream &, ostream &) {
    int H, W;
    scan(H, W);
    vector<string> s(H);
    For(row, s) scan(row);
    // permutation of rows
    vector<string> row(H);

    auto check_cols = [&](int i, int j) {
      rng (k, 0, H) {
        if (row[k][i] != row[H - k - 1][j]) return false;
      }
      return true;
    };
    auto is_palindrome = [&](int i) {
      rng (k, 0, H / 2) {
        if (row[k][i] != row[H - k - 1][i]) {
          return false;
        }
      }
      return true;
    };

    auto check = [&]() {
//      debug(row);
      vb used(W);
      bool seen_palindrome = false;
      rng (i, 0, W) {
        if (used[i]) continue;
        bool found = false;
        rng (j, i + 1, W) {
          if (!used[j] && check_cols(i, j)) {
            found = true;
            used[j] = true;
            break;
          }
        }
        if (found) {
          continue;
        }
        if (W & 1 and !seen_palindrome and is_palindrome(i)) {
          seen_palindrome = true;
          continue;
        }
        return false;
      }
      return true;
    };

    vi used(H);
    function<bool(int)> gen_pairing = [&](int cnt) {
      if (cnt == H / 2 + 1) {
        return check();
      }
      rng(i, 0, H) {
        if (!used[i]) {
          row[cnt - 1] = s[i];
          used[i] = true;
          rng(j, i + 1, H) {
            if (!used[j]) {
              used[j] = true;
              row[H - cnt] = s[j];
              if (gen_pairing(cnt + 1)) return true;
              used[j] = false;
            }
          }
          used[i] = false;
          break;
        }
      }
      return false;
    };
    if (H & 1) {
      rng (i, 0, H) {
        used[i] = true;
        row[H / 2] = s[i];
        if (gen_pairing(1)) {
          println("YES");
          return;
        }
        used[i] = false;
      }
      println("NO");
    } else {
      println(gen_pairing(1) ? "YES" : "NO");
    }
  }
};
