    vector<T> d(v, INF);
    d[s] = 0;
    auto edge_cmp = [](const edge& a, const edge& b) { return a.cost > b.cost; };
    priority_queue<edge, vector<edge>, decltype(edge_cmp)> pq(edge_cmp);
    pq.push((edge){s, 0});
    while (!pq.empty()) {
      edge temp = pq.top(); pq.pop();
      if (d[temp.to] < temp.cost) continue;
      for (const edge& next : e[temp.to]) {
        T cost = temp.cost + next.cost;
        if (d[next.to] > cost) {
          d[next.to] = cost;
          pq.push((edge){next.to, cost});
        }
      }
    }
    return d;
  }
  vector<T> bellmanford(ll s) {
    vector<T> d(v, INF);
    d[s] = 0;
    for (ll i = 0; i < v; i++) {
      for (const edge_data& temp : ed) {
        if (d[temp.from] != INF && d[temp.to] > d[temp.from] + temp.cost) d[temp.to] = d[temp.from] + temp.cost;
        if (!isDirected && d[temp.to] != INF && d[temp.from] > d[temp.to] + temp.cost) d[temp.from] = d[temp.to] + temp.cost;
      }
    }
    for (ll i = 0; i < v; i++) {
      for (const edge_data& temp : ed) {
        if (d[temp.from] != INF && d[temp.to] > d[temp.from] + temp.cost) d[temp.to] = -INF;
        if (!isDirected && d[temp.to] != INF && d[temp.from] > d[temp.to] + temp.cost) d[temp.from] = -INF;
      }
    }
    return d;
  }
  vector<T> shortest_path(ll s) {
    if (isMinasEdge) return bellmanford(s);
    else return dijkstra(s);
  }
  T kruskal() {
    // if (isDirected)
    UnionFind uf(v);
    auto edge_data_cmp = [](const edge_data& a, const edge_data& b) { return a.cost < b.cost; };
    sort(ed.begin(), ed.end(), edge_data_cmp);
    T ans = 0;
    for (const edge_data& temp : ed) {
      if (uf.isSame(temp.from, temp.to)) continue;
      uf.merge(temp.from, temp.to);
      ans += temp.cost;
    }
    return ans;
  }
  void scc_dfs(ll s) {
    used[s] = true;
    for (const edge& i : e[s]) if (!used[i.to]) scc_dfs(i.to);
    vs.push_back(s);
  }
  void scc_rdfs(ll s, ll k) {
    used[s] = true;
    cmp[s] = k;
    for (const edge& i : re[s]) if (!used[i.to]) scc_rdfs(i.to, k);
  }
  vector<ll> scc() {
    used.resize(v);
    fill(used.begin(), used.end(), false);
    cmp.resize(v);
    vs.clear();
    for (ll i = 0; i < v; i++) if (!used[i]) scc_dfs(i);
    used.resize(v);
    fill(used.begin(), used.end(), false);
    ll k = 0;
    for (ll i = vs.size() - 1; i >= 0; i--) if (!used[vs[i]]) scc_rdfs(vs[i], k++);
    return cmp;
  }
};

class RollingHash {
  int base;
  vector<__int128> hash;
  vector<__int128> pw;
  const __int128 hashmod = (1ull << 61) - 1;
public:
  RollingHash(string s, int base = 10007) : base(base), hash(s.length()+1, 0), pw(s.length()+1, 1) {
    for (int i = 0; i < (int)s.length(); i++) {
      hash[i+1] = (hash[i] * base + s[i]) % hashmod;
      pw[i+1] = pw[i] * base % hashmod;
    }
  }
  ll get(ll a, ll b) { // [a, b)
    __int128 tmp = hashmod + hash[b] - hash[a] * pw[b-a] % hashmod;
    if (tmp >= hashmod) tmp -= hashmod;
    return (ll)tmp;
  }
};

class BipartiteMatching {
  vector<ll> pre, root;
  vector<vector<ll>> to;
  vector<ll> p, q;
  ll n, m;
public:
  BipartiteMatching(ll n, ll m) : pre(n, -1), root(n, -1), to(n), p(n, -1), q(m, -1), n(n), m(m){}
  void add_edge(ll a, ll b) { to[a].push_back(b);}
  ll solve() {
    ll res = 0;
    bool upd = true;
    while (upd) {
      upd = false;
      queue<ll> s;
      for (ll i = 0; i < n; ++i) {
        if (!~p[i]) {
          root[i] = i;
          s.push(i);
        }
      }
      while (!s.empty()) {
        ll v = s.front(); s.pop();
        if (~p[root[v]]) continue;
        for (ll i = 0; i < (ll)to[v].size(); ++i) {
          ll u = to[v][i];
          if (!~q[u]) {
            while (~u) {
              q[u] = v;
              swap(p[v],u);
              v = pre[v];
            }
            upd = true;
            ++res;
            break;
          }
          u = q[u];
          if (~pre[u]) continue;
          pre[u] = v; root[u] = root[v];
          s.push(u);
        }
      }
      if (upd) fill(pre.begin(),pre.end(),-1), fill(root.begin(),root.end(),-1);
    }
    return res;
  }
};


class Gabow {
  struct edge {
    int to;
    int label;
  };
  vector<vector<int>> _g;
public:
  Gabow(int n) : _g(n) {}
  void add_edge(int from, int to) {
    _g[from].push_back(to);
  }
  vector<P> solve() {
    // E0 - 初期化
    int N = _g.size();
    vector<vector<edge>> g(N + 1);
    vector<P> edges;
    {
      int cnt = N + 1;
      for(int i = 0;i < N;i++){
        for(auto to : _g[i]){
          if(i < to){
            g[to + 1].push_back({i + 1, cnt});
            g[i + 1].push_back({to + 1, cnt++});
            edges.push_back({i + 1, to + 1});
          }
        }
      }
    }
    vector<int> mate(N + 1 , 0);
    vector<int> label(N + 1 , -1);
    vector<int> first(N + 1 , 0);
    queue<int> que;

    // firstの遅延評価
    function<int(int)> eval_first = [&](int x){
      if(label[first[x]] < 0) return first[x];
      first[x] = eval_first(first[x]);
      return first[x];
    };

    // サブルーチンR
    function<void(int, int)> rematch = [&](int v, int w){
      // R1
      int t = mate[v];
      mate[v] = w;
      if(mate[t] != v) return;
      // R2
      if(label[v] <= N){
        mate[t] = label[v];
        rematch(label[v] , t);
      }
      // R3
      else{
        int x = edges[label[v] - N - 1].first;
        int y = edges[label[v] - N - 1].second;
        rematch(x , y);
        rematch(y , x);
      }
    };

    function<void(int, int, int)> assignLabel = [&](int x, int y, int num){
      // L0
      int r = eval_first(x);
      int s = eval_first(y);
      int join = 0;
      if(r == s) return;
      // -numがフラグ
      label[r] = -num;
      label[s] = -num;
      while(true){
        // L1
        if(s != 0) swap(r , s);
        // L2
        r = eval_first(label[mate[r]]);
        if(label[r] == -num){
          join = r;
          break;
        }
        label[r] = -num;
      }
      // L3
      int v = first[x];
      // L4
      while(v != join){
        que.push(v);
        label[v] = num;
        first[v] = join;
        v = first[label[mate[v]]];
      }
      // L3
      v = first[y];
      // L4
      while(v != join){
        que.push(v);
        label[v] = num;
        first[v] = join;
        v = first[label[mate[v]]];
      }
      // L5は遅延評価しているため不要
      // L6
      return;
    };

    function<bool(int)> augment_check = [&](int u){
      // E1 後半
      first[u] = 0;
      label[u] = 0;
      que.push(u);
      while(!que.empty()){
        // E2 
        int x = que.front();
        que.pop();
        for(auto e : g[x]){
          int y = e.to;
          // E3
          if(mate[y] == 0 && y != u){
            mate[y] = x;
            rematch(x , y);
            return true;
          }
          // E4
          else if(label[y] >= 0){
            assignLabel(x , y , e.label);
          }
          // E5
          else if(label[mate[y]] < 0){
            label[mate[y]] = x;
            first[mate[y]] = y;
            que.push(mate[y]);
          }
          // E6
        }
      }
      return false;
    };

    for(int i = 1;i <= N;i++){
      // E1
      que = queue<int>();
      if(mate[i] != 0) continue;
      if(augment_check(i)){
        // E7
        fill(label.begin(), label.end(), -1);
      }
    }

    vector<P> ans;
    for(int i = 1;i <= N;i++){
      if(i < mate[i]){
        ans.push_back({i , mate[i]});
      }
    }
    return ans;
  }
};


ll h, w;
