void dfs(int idx){
	if(found) return;
	if(idx>=H){
		int match_num=0;
		memset(match_c,0,sizeof match_c);
		for(int i=0;i<W;i++){
			if(match_c[i]) continue;
			for(int j=i+1;j<W;j++){
				if(match_c[j]) continue;
				bool succ=true;
				for(int k=0;k<(int)match_row.size() && succ;k++)
					if(grid[match_row[k].first][i]!=grid[match_row[k].second][j])
						succ=false;
				if(succ){
					match_c[i]=match_c[j]=true;
					match_num++;
					break;
				}
			}
		}
		if(match_num==W/2) found=true;
	}else{
		if(match[idx]) dfs(idx+1);
		else{
			for(int i=idx+1;i<H;i++){
				if(!match[i]){
					match[i]=match[idx]=true;
					match_row.push_back(pii(i,idx));
					dfs(idx+1);
					match_row.pop_back();
					match[i]=match[idx]=false;
				}
			}
		}
	}
