using namespace std;

int h, w;
char str[15][15];

int p;
int rp[11000][15];

int trp[15];
void bt(int cnt) {
    int i;
    if (cnt==h) {
        for (i=0;i<h;i++) rp[p][i] = trp[i];
        p++;
        return;
    }
    if (trp[cnt]!=cnt) {
        bt(cnt+1);
        return;
    }
    for (i=cnt+1;i<h;i++) {
        if (trp[i]!=i) continue;
        trp[cnt] = i; trp[i] = cnt;
        bt(cnt+1);
        trp[i] = i;
    }
    trp[cnt] = cnt;
}

int bit[15];
int wp[15];
bool good(int cnt, int rem) {
    int i;
    if (cnt==w) return true;
    if (wp[cnt]!=cnt) {
        return good(cnt+1,rem);
    }
    for (i=cnt;i<w;i++){
        if ((!rem)&&i==cnt) continue;
        if (wp[i]!=i) continue;
        if (bit[cnt]>>i&1) {
            wp[cnt] = i; wp[i] = cnt;
            if (good(cnt+1,rem-(i==cnt))) return true;
            wp[i] = i;
        }
    }
    wp[cnt] = cnt;
    return false;
}

bool rchk() {
    int i, j, k, l;
    for (k=0;k<p;k++) {
        for (j=0;j<w;j++) bit[j] = (1<<w)-1;
        for (i=0;i<h;i++) {
            if (rp[k][i]<i) continue;
            for (j=0;j<w;j++) {
                for (l=0;l<w;l++) {
                    if (str[i][j]!=str[rp[k][i]][l]||
                        str[i][l]!=str[rp[k][i]][j]) bit[j] &= ~(1<<l);
                }
            }
        }
        for (j=0;j<w;j++) wp[j] = j;
        if (good(0,w%2)) return true;
    }
    return false;
}

