bool check() {
	memset(used, false, sizeof(used));
	for(int i = 0; i < m; i ++) {
		if(used[i])
			continue;
		for(int j = 0; j < m; j ++) {
			bool cur = true;
			if(i == j || used[j])
				continue;
			for(int k = 0; k < n; k ++) {
				if(s[swaped[k]][i] != s[k][j]) {
					cur = false;
					break;
				}
			}
			if(cur) {
				used[i] = used[j] = true;
				break;
			}
		}
	}

	int cnt = 0, noused = -1;
	for(int i = 0; i < m; i ++)
		if(!used[i])
			cnt ++, noused = i;
	if((cnt >= 2 ) || (cnt && (m % 2 == 0)))
		return false;
	for(int i = 0; i < n; i ++)
		if(s[swaped[i]][noused] != s[i][noused])
			return false;
