// solve
int h, w;
string s[12];
bool vis[12];
vector<int> v;
string t[12], revt[12];

bool dfs(int i){
  if(i == h){
    rep(j, w){
      t[j] = "";
      for(int k = 0; k < h; k += 2){
        t[j] += s[v[k]][j];
      }
      string tmp = "";
      for(int k = 1; k < h; k += 2){
        tmp += s[v[k]][j];
      }
      reverse(all(tmp));
      t[j] += tmp;
      revt[j] = t[j]; reverse(all(revt[j]));
    }
    vector<bool> ok(w, false);
    int cnt = 0;
    rep(j, w){
      int fal = 0; rep(l, w)if(!ok[l])fal++;
      if(fal < 2)break;
      int k;
      for(k = 0; k < w; k++){
        if(!ok[k])break;
      }
      ok[k] = true;
      bool res = false;
      for(int l = k + 1; l < w; l++){
        if(!ok[l] && t[k] == revt[l]){
          res = true;
          ok[l] = true;
          break;
        }
      }
      if(!res){
        cnt++;
        if(cnt > (w % 2))return false;
      }
    }
    return true;
  }
  if(i % 2 == 0){
    bool res = false;
    int j = 0;
    while(vis[j])j++;
    vis[j] = true;
    v.pb(j);
    res |= dfs(i + 1);
    v.pop_back();
    vis[j] = false;
    if(w % 2 == 1){
      j++;
      while(j < h && vis[j])j++;
      if(j != h){
        vis[j] = true;
        v.pb(j);
        res |= dfs(i + 1);
        v.pop_back();
        vis[j] = false;
      }
    }
    return res;
  }else{
    rep(j, h){
      if(vis[j])continue;
      vis[j] = true;
      v.pb(j);
      bool res = dfs(i + 1);
      if(res)return true;
      v.pop_back();
      vis[j] = false;
    }
    return false;
  }
}

