void try_all(int id, vector<int> a) {
	if(id == n) {
		vector<string> tt(n);
		for (int i = 0; i < n; i++) 
			tt[i] = v[a[i]];
		if(check(tt))
			ok = true;
		return;
	}
	for (int i = 0; i < n / 2; i++) {
		if(a[i] == -1) {
			a[i] = id;
			try_all(id + 1, a);
			a[i] = -1;
			break;
		}
		else {
			if(a[n - i - 1] == -1) {
