bool judge(string rows_rearranged[], int start, const string &center_row)
{
    debug_printf("---- rows_rearranged\n");
    debug_print(rows_rearranged, lh);

    string colums_rearranged[w];
    rep (i, w) {
        string s;
        rep (j, lh) s += rows_rearranged[j][i];
        colums_rearranged[i] = s;
    }
    debug_printf("---- colums_rearranged\n");
    debug_print(colums_rearranged, w);

    string colums_rearranged_reverse[w];
    rep (i, w) {
        string s;
        rep (j, lh) s += colums_rearranged[i][lh-j-1];
        colums_rearranged_reverse[i] = s;
    }
    debug_printf("---- colums_rearranged_reverse\n");
    debug_print(colums_rearranged_reverse, w);

    bool checked[w];
    memset(checked, 0, sizeof(checked));
    ll cstart = 0LL;
    int center = -1;
    srep(i, cstart, w) {
        if (checked[i]) continue;
        srep (j, i+1, w) {
            if (checked[j]) continue;
            if (colums_rearranged[i] == colums_rearranged_reverse[j] &&
                (center_row.size() == 0 || center_row[i] == center_row[j])) {
                checked[i] = checked[j] = true;
                break;
            }
        }
        if (!checked[i]) {
            if (center < 0 && (w%2) &&
                colums_rearranged[i] == colums_rearranged_reverse[i]) {
                checked[i] = true;
                center = i;
            }
            else {
                return false;
            }
        }
        cstart++;
    }

    return true;
}

bool f(string rows_rearranged[], bool used[], int start, const string &center_row)
{
    debug_printf("----- start=%d\n", start);

    if (start >= h / 2) return judge(rows_rearranged, start, center_row);

    int idx1 = start;
    srep (i, start, h) {
        if (used[i]) continue;
        idx1 = i;
        break;
    }
    rows_rearranged[start] = rows[idx1];
    used[idx1] = true;

    srep (idx2, idx1 + 1, h) {
        if (used[idx2]) continue;
        rows_rearranged[lh - start - 1] = rows[idx2];
        used[idx2] = true;
        if (f(rows_rearranged, used, start + 1, center_row)) return true;
        used[idx2] = false;
    }

    used[idx1] = false;

    return false;
}

