bool is_symmetric(int x1, int x2, const vector<int> &perm)
{
    for (int y=0; y<H; y++) {
        if (grid[perm[y]][x1] != grid[perm[H-y-1]][x2]) return false;
    }
    return true;
}

bool match_dfs(int x1, int used, bool allow_alone, const vector<int> &perm)
{
    if (used == (1<<W) - 1) {
        return true;
    }

    if (used>>x1 & 1) {
        return match_dfs(x1+1, used, allow_alone, perm);
    }

    used |= 1<<x1;
    bool res = false;
    for (int x2=x1+1; x2<W; x2++) {
        if (is_symmetric(x1, x2, perm)) {
            used |= 1<<x2; 
            res |= match_dfs(x1+1, used, allow_alone, perm);
            used &= ~(1<<x2);
        }
    }

    if (allow_alone && is_symmetric(x1, x1, perm)) {
        res |= match_dfs(x1+1, used, false, perm);
    }

    used &= ~(1<<x1);
    return res;
}

bool match(const vector<int> &perm)
{
#ifdef DEBUG
    rep(i, H) cerr << perm[i] << " ";
    cerr << endl;
#endif
    return match_dfs(0, 0, W%2, perm);
}

bool dfs(int y1, int used, vector<int> &perm)
{
    if (used == (1<<H) - 1) {
        cnt++;
        return match(perm);
    }

    if (used>>y1 & 1) {
        return dfs(y1+1, used, perm);
    }

    used |= 1<<y1;
    perm[__builtin_popcount(used)/2] = y1;

    bool res = false;
    if (__builtin_popcount(used) == H) {
        res = dfs(y1+1, used, perm);
    } else {
        for (int y2=y1+1; y2<H; y2++) {
            if (used>>y2 & 1) continue; 
            used |= 1<<y2;
            perm[H - __builtin_popcount(used)/2] = y2;
            res  |= dfs(y1+1, used, perm);
            used &= ~(1<<y2);
        }
    }
    used &= ~(1<<y1);

    return res;
}

