        }
        return;
    }
    if ((l+1==r)||(l==r))
    {
        if (checks_2(u,d,center_row))
        {
            puts("YES");
            exit(0);
        }
        return;
    }
    if (center_row)
    {
        int i;
        swap_row(u,(u+d)/2);
        for (i=l+1;i<r;i++)
        {
            if (a[(u+d)/2][i]==a[(u+d)/2][l])
            {
                swap_col(i,r-1);
                dfs(u,d,l-1,r-1,false,center_col);
                swap_col(i,r-1);
            }
        }
        swap_row(u,(u+d)/2);
    }
    if (center_col)
    {
        int i;
        swap_col(l,(l+r)/2);
        for (i=u+1;i<d;i++)
        {
            if (a[i][(l+r)/2]==a[l][(l+r)/2])
            {
                swap_row(i,d-1);
                dfs(u-1,d-1,l,r,center_row,false);
                swap_row(i,d-1);
            }
        }
        swap_col(l,(l+r)/2);
    }
    if (center_col&&center_row)
    {
        swap_col(l,(l+r)/2);
        swap_row(u,(u+d)/2);
        dfs(u,d,l,r,false,false);
        swap_row(u,(u+d)/2);
        swap_col(l,(l+r)/2);
    }
    int i,j;
    for (i=u+1;i<d;i++)
    {
        if ((i==(u+d)/2)&&(!center_row)&&((u+d)%2==1)) continue;
        swap_row(i,d-1);
        for (j=l+1;j<r;j++)
        {
