	rep(j, W) {
		string cur;
		rep(i, H) cur.pb(t[i][j]);
		vec[j] = cur;
	}

	int sol = 0;

	rep(j, W) {
		if (!us_col[j]) {
			bool fd = false;
			int p = -1;
			string rev = vec[j];
			reverse(ALL(rev));

			for (int j2 = j + 1; j2 < W; ++j2) {
				if (vec[j2] == rev) {
					fd = true;
					p = j2;
				}
			}
			if (fd) {
				us_col[j] = us_col[p] = true;
			} else if (W % 2 != 0) {
				return false;
			} else {
				if (rev != vec[j]) {
					return false;
				}
				us_col[j] = true;
				++sol;
			}
		}
	}
	return sol <= 1;
}

bool dfs(int p) {
	if (p == H) {
		int cnt = 0;
		rep(i, H) if (mt[i] == -1) {
			++cnt;
		}
		if (cnt <= 1) {
			return check();
		}
		return false;
	}

	if (mt[p] != -1) {
		return dfs(p + 1);
	}

	int cfree = 0;
	rep(i, p) {
		if (mt[i] == -1) {
			++cfree;
		}
	}
	if (H % 2 == 1 && cfree == 0) {
		if (dfs(p + 1)) {
			return true;
		}
	}

	for (int i = p + 1; i < H; ++i) {
		if (mt[i] == -1) {
			mt[p] = i;
			mt[i] = p;
			if (dfs(p + 1)) {
				return true;
			}
			mt[i] = mt[p] = -1;
		}
	}
	return false;
}

