#define rep(i, n) loop(i, 0, n)
#define lin long long

int h, w;
vector<string> s;
vector<string> t;

bool line_sym(string s)
{
    int c[26];    
    rep(i, 26)
    {
        c[i] = 0;
    }

    rep(i, s.length())
    {
        c[s[i] - 'a']++;
    }

    bool b = false;
    rep(i, 26)
    {
        if(c[i] % 2 != 0)
        {
            if(b)
                return false;
            else
                b = true;
        }
    }

    return true;
}

bool judge(vector<string> r)
{
    int sz = r.size();

    bool b[sz];

    rep(i, sz)
    {
        b[i] = false;

        int len = r[i].length();
        char cc[len + 1];
        r[i].copy(cc, len);
        sort(cc, cc + len);
        cc[len] = '\0'; 
        r[i] = cc;
    }

    if(sz % 2 == 1)
    {
        bool bl = false;

        rep(i, sz)
        {
            if(line_sym(r[i]))
            {
                if(bl)
                    return false;
                else
                {
                    b[i] = true;
                    bl = true;
                }
            }
        }
    }

    rep(i, sz)
    {
        if(b[i])
            continue;

        bool discoverd = false;
        loop(j, i + 1, sz)
        {
            if(b[j])
                continue;

            if(r[i] == r[j])
            {
                discoverd = true;
                b[j] = true;
                b[i] = true;
                break;
            }
        }

        if(!discoverd)
            return false;
    }

    return true;
}

bool solve()
{
    cin >> h >> w;

    rep(i, h)
    {
        string ss;
        cin >> ss;
        s.push_back(ss);
    }

    rep(i, w)
    {
        char c[h + 1];
        rep(j, h)
        {
            c[j] = s[j][i];
        }
        c[h] = '\0';

        t.push_back(c);
    }

    return judge(s) && judge(t);
}

int main(void)
{
    bool result = solve();

    if(result)
        cout << "YES" << endl;
    else
        cout << "NO" << endl;

    return 0;
}

