bool used[14];

int match[14];
bool disable_col[14][14];
bool used2[14];

bool visited[1 << 14];

bool dfs(int bit){
    if(bit == (1 << W) - 1) return true;
    if(visited[bit]) return false;

    int k = 0;
    while((bit>>k)&1) k++;

    bool only = true;
    for(int l=k+1;l<W;l++){
        if((bit>>l)&1) continue;
        only = false;
        if(disable_col[k][l]) continue;
        if(dfs(bit | (1 << l) | (1 << k))) return true;
    }

    if(only) return true;

    visited[bit] = true;
    return false;
}

bool make_able_pair(int i){
    if(i == H){
        memset(used2, 0, sizeof(used2));
        for(int i=0;i<H;i++){
            if(used[i]) continue;
            for(int k=0;k<W;k++){
                for(int l=k+1;l<W;l++){
                    if(!(S[i][k] == S[match[i]][l] && S[i][l] == S[match[i]][k])){
                        disable_col[k][l] = true;
                        disable_col[l][k] = true;
                    }
                }
            }
            used2[i] = true;
            used2[match[i]] = true;
        }
        memset(visited, 0, sizeof(visited));
        return dfs(0);
    }
    if(used[i]) return make_able_pair(i + 1);
    for(int j=i+1;j<H;j++){
        if(used[j] || !able[i][j]) continue;
        used[j] = true;
        match[i] = j;
        match[j] = i;
        if(make_able_pair(i + 1)) return true;
        used[j] = false;
    }
    return false;
}

