			}
		}
		if (!used[last]) flag=false;
	}
	if (flag) return true;
	last=2;
	if (m&1)
	{
		for (int i=1;i<=m/2;i++)
		{
			while (used[last]) last++;
			for (int j=1;j<=m;j++)
			{
				if (used[j] || last==j) continue;
				if (same(last,j))
				{
					used[last]=used[j]=1;
					break;
				}
			}
			if (!used[last]) flag=false;
		}
		if (flag) return true;
	}
	return false;
}
void dfs(int sz)
{
