		}
		return ;
	}
	if ((n&1) && sz==(n+1)/2)
	{
		for (int i=1;i<=n;i++)
			if (!vis[i])
				tmp[sz]=i,dfs(sz+1);
		return ;
	}
	for (int i=1;i<=n;i++)
	{
		if (vis[i]) continue;
		int j;
		for (j=1;j<=n;j++)
		{
			if (vis[j] || i==j) continue;
			if (same(i,j))
				break;
		}
		if (j==n+1) continue;
		tmp[sz]=i,tmp[n-sz+1]=j;
		vis[i]=vis[j]=1;
		dfs(sz+1);
		vis[i]=vis[j]=0;
	}
}
