long long ext_gcd(long long a,long long b,long long& x,long long& y){
	if(b==0){
		x=1;y=0;return a;
	}
	long long q = a/b;
	long long g = ext_gcd(b,a-q*b,x,y);
	x = x - q*y;
	swap(x,y);
	return g;
}
