    for (int i = 0; i < H; i++) {
        cin >> grid[i];
    }

    if (H&1) {
        int m = H / 2;
        for (int i = 0; i < H; i++) {
            swap(grid[i], grid[m]);
            go(grid, 0);
            swap(grid[i], grid[m]);
        }
    } else go(grid, 0);

    cout << "NO\n";
    return 0;
}

