#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using P = pair<int, int>;

int H, W;

bool judge(vector<P>& v, vector<string>& s) {
    vector<string> s2(s);
    for (int i = 0; i < (H + 1) / 2; i++) {
        s2[i] = s[v[i].first];
        s2[H - 1 - i] = s[v[i].second];
    }

    vector<int> used(W, false);
    int ok = W % 2;
    for (int i = 0; i < W; i++) {
        if (used[i]) continue;
        for (int j = i + 1; j < W; j++) {
            if (used[j]) continue;
            bool flag = true;
            for (int k = 0; k < H; k++) {
                if (s2[k][i] != s2[H - 1 - k][j]) {
                    flag = false;
                    break;
                }
            }
            if (flag) {
                used[i] = true;
                used[j] = true;
                break;
            }
        }
        if (!used[i]) {
            if (ok) {
                ok = false;
                used[i] = true;
            } else {
                return false;
            }
        }
    } 
    return true;
}

bool solve(vector<int> used, vector<P> v, vector<string>& s) {
    int cnt = 0;
    for (int x : used) {
        cnt += !x;
    }

    if (cnt == 0) {
        return judge(v, s);
    } else {
        for (int i = 0; i < H; i++) {
            if (used[i]) continue;
            used[i] = true;
            if (cnt == 1) {
                v.emplace_back(i, i);
                if (solve(used, v, s)) return true;
            } else {
                for (int j = i + 1; j < H; j++) {
                    if (used[j]) continue;
                    used[j] = true;
                    v.emplace_back(i, j);
                    if (solve(used, v, s)) return true;
                    used[j] = false;
                    v.pop_back();
                }
            }
            used[i] = false;
        }
    }
    return false;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> H >> W;
    vector<string> s(H);
    for (int i = 0; i < H; i++) {
        cin >> s[i];
    }
    vector<int> used(H, false);
    vector<P> v;
    cout << (solve(used, v, s) ? "YES" : "NO") << endl;
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

const int N = 514;
const int E = (2e5) * 2;

int n, m;
char ip[N][N];

int mat[N];

struct Graph{
  int to[E],bro[E],head[N],e;
  int lnk[N],vis[N],stp,n;
  void init( int _n ){
    stp = 0; e = 1; n = _n;
    for( int i = 1 ; i <= n ; i ++ )
      lnk[i] = vis[i] = 0;
  }
  void add_edge(int u,int v){
    to[e]=v,bro[e]=head[u],head[u]=e++;
    to[e]=u,bro[e]=head[v],head[v]=e++;
  }
  bool dfs(int x){
    vis[x]=stp;
    for(int i=head[x];i;i=bro[i]){
      int v=to[i];
      if(!lnk[v]){
        lnk[x]=v,lnk[v]=x;
        return true;
      }else if(vis[lnk[v]]<stp){
        int w=lnk[v];
        lnk[x]=v,lnk[v]=x,lnk[w]=0;
        if(dfs(w)){
          return true;
        }
        lnk[w]=v,lnk[v]=w,lnk[x]=0;
      }
    }
    return false;
  }
  int solve(){
    int ans = 0;
    for(int i=1;i<=n;i++)
      if(!lnk[i]){
        stp++; ans += dfs(i);
      }
    return ans;
  }
} graph;

bool ans;

void chk() {
  for (int i = 0; i < n; ++i) if (mat[i] == -1) return;
  graph.init(m);
  for (int i = 0; i < m; ++i) {
    for (int j = i + 1; j < m; ++j) {
      bool good = 1;
      for (int k = 0; k < n; ++k) {
        if (ip[k][i] != ip[mat[k]][j] || ip[k][j] != ip[mat[k]][i]) {
          good = 0;
          break;
        }
      }
      if (good) graph.add_edge(i+1, j+1);
    }
  }
  if (graph.solve() >= m/2) {
    ans = 1;
    return;
  }
}

void dfs(int i) {
  if (ans) return;
  if (i == n) {
    chk();
  }
  if (mat[i] != -1) {
    dfs(i + 1);
    return;
  }
  for (int j = i; j < n; ++j) if (mat[j] == -1) {
    if (j == i && n % 2 == 0) continue;
    mat[j] = i;
    mat[i] = j;
    dfs(i + 1);
    if (ans) return;
    mat[j] = -1;
    mat[i] = -1;
  }
  return;
}

int main() {
  cin >> n >> m;
  for (int i = 0; i < n; ++i) cin >> ip[i];
  fill(mat, mat+n, -1);
  dfs(0);
  cout << (ans? "YES": "NO") << endl;
}

