bool dfs2(const vs& grid,const vi& rhash,const vi& chash,vi& rs,vi& cs,int k)
{
	int h=grid.size(),w=grid[0].size();
	if(k>=w-1-k){
		rep(i,h) rep(j,w)
			if(grid[rs[i]][cs[j]]!=grid[rs[h-1-i]][cs[w-1-j]])
				return false;
		return true;
	}
	repi(i,k,w-k){
		swap(cs[k],cs[i]);
		repi(j,k+1,w-k)
			if(chash[cs[k]]==chash[cs[j]]){
				swap(cs[w-1-k],cs[j]);
				if(dfs2(grid,rhash,chash,rs,cs,k+1))
					return true;
				swap(cs[w-1-k],cs[j]);
			}
		swap(cs[k],cs[i]);
	}
	return false;
}

bool dfs1(const vs& grid,const vi& rhash,const vi& chash,vi& rs,vi& cs,int k)
{
	int h=grid.size(),w=grid[0].size();
	if(k>=h-1-k)
		return dfs2(grid,rhash,chash,rs,cs,0);
	repi(i,k,h-k){
		swap(rs[k],rs[i]);
		repi(j,k+1,h-k)
			if(rhash[rs[k]]==rhash[rs[j]]){
				swap(rs[h-1-k],rs[j]);
				if(dfs1(grid,rhash,chash,rs,cs,k+1))
					return true;
				swap(rs[h-1-k],rs[j]);
			}
		swap(rs[k],rs[i]);
	}
	return false;
}

bool solve(vs grid)
{
	int h=grid.size(),w=grid[0].size();

	vi rhash(h),chash(w);
	rep(i,h){
		vi r(w);
		rep(j,w) r[j]=grid[i][j]-'a';
		sort(all(r));
		rep(j,w) ((rhash[i])*=26)+=r[j];
	}
	rep(j,w){
		vi c(h);
		rep(i,h) c[i]=grid[i][j]-'a';
		sort(all(c));
		rep(i,h) ((chash[j])*=26)+=c[i];
	}
	vi rs(h); iota(all(rs),0);
	vi cs(w); iota(all(cs),0);
	random_shuffle(all(rs));
	random_shuffle(all(cs));

	return dfs1(grid,rhash,chash,rs,cs,0);
}

int main()
{
	#ifndef _GLIBCXX_DEBUG
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	constexpr char endl='\n';
	#endif

	for(int h,w;cin>>h>>w&&h|w;){
		vs grid(h);
		rep(i,h) cin>>grid[i];

		cout<<(solve(grid)?"YES":"NO")<<endl;
	}
}

