void foo() {
	int a = -1;
	rep(i,W) {
		if(!f[i]) {
			a = i;
			f[i] = true;
			break;
		}
	}
	if(a < 0) {
		comb.push_back(tempv);
		return;
	}
	FOR(i,a+1,W) {
		if(!f[i]) {
			tempv.push_back(pii(a,i));
			f[i] = true;
			foo();
			tempv.pop_back();
			f[i] = false;
		}
	}
	f[a] = false;
}

bool check(int c, const vector<pii> & p) {
	for(int i = 0; i < (H%2 ? H : 1); i++) {
		vector<int> v;
		rep(k,H) v.push_back(k);
		if(H%2) {
			bool center_f = true;
			swap(v[0], v[i]);
			rep(k,p.size()) {
				if(S[i][p[k].fi] != S[i][p[k].se]) {
					center_f = false;
				}
			}
			if(!center_f) continue;
		}

		bool res = true;
		for(int j = H%2; j < H && res; j += 2) {
			bool found = false;
			for(int j_ = j+1; j_ < H && res; j_++) {
				bool flg = true;
				for(int k = 0; k < p.size(); k++) {
					if(S[v[j]][p[k].fi] != S[v[j_]][p[k].se]
							|| S[v[j]][p[k].se] != S[v[j_]][p[k].fi]) {
						flg = false;
					}
				}
				if(flg && (c < 0 || S[v[j]][c] == S[v[j_]][c])) {
					swap(v[j+1], v[j_]);
					found = true;
					break;
				}
			}
			if(!found) res = false;
		}
		if(res) return true;
	}
	return false;
}

int main() {
	cin >> H >> W;
	S.resize(H);
	rep(i,H) {
		cin >> S[i];
	}
	for(int i = 0; i < (W%2 ? W : 1); i++) {
		comb.clear();
		if(W%2) f[i] = true;
		foo();
		if(W%2) f[i] = false;
		rep(j,comb.size()) {
			if(check(W%2 ? i : -1, comb[j])) {
				cout << "YES" << endl;
				return 0;
			}
		}
	}
	cout << "NO" << endl;
	return 0;
}

