const int maxn = 15;
int N, M, p[maxn], mt[maxn]; char s[maxn][maxn], tmp[maxn];
bool f = false, used[maxn], ok[maxn];
struct data { char a, b; }t1[maxn], t2[maxn];
const int cmp(const data &A, const data &B)
{ return (A.a<B.a) || (A.a==B.a&&A.b<B.b); }

bool Check(int a, int b)
{
	for(int i = 1; i <= N; ++i)
		if(s[p[i]][a] != s[p[N-i+1]][b])
			return false;
	return true;
}

bool pal(int n)
{
	for(int i = 1; i <= (N>>1); ++i)
		if(s[p[i]][n] != s[p[N-i+1]][n])
			return false;
	return true;
}

bool check()
{
	int mid = 0;
	memset(ok, 0, sizeof(ok));
	for(int i = 1; i <= M; ++i)
	{
		if(ok[i]) continue;
		for(int j = i+1; j <= M; ++j)
			if(!ok[j] && Check(i, j)) { ok[i] = ok[j] = true; break; }
		if(!ok[i])
		{
			if(M & 1)
			{
				if(!mid && pal(i)) mid = i;
				else return false;
			}
			else return false;
		}
	}
	return true;
}

void dfs(int dep)
{
	if(f) return;
	if(dep > (N>>1))
	{
		if(N & 1) for(int i = 1; i <= N; ++i) if(!used[i]) p[dep] = i;
		if(check()) f = true; return;
	}
	for(int i = 1; i <= N; ++i)
	{
		if(used[i]) continue;
		p[dep] = i, p[N-dep+1] = mt[i];
		used[i] = used[mt[i]] = true;
		dfs(dep+1);
		used[i] = used[mt[i]] = false;
	}
}

bool OK(int a, int b)
{
	for(int i = 1; i <= M; ++i)
	{
		t1[i].a = s[a][i], t1[i].b = s[b][i];
		t2[i].b = s[a][i], t2[i].a = s[b][i];
	}
	sort(t1+1, t1+M+1, cmp);
	sort(t2+1, t2+M+1, cmp);
	for(int i = 1; i <= M; ++i)
		if(t1[i].a!=t2[i].a || t2[i].b!=t2[i].b)
			return false;
	return true;
}

void prework()
{
	for(int i = 1; i <= N; ++i)
		if(!mt[i]) for(int j = 1; j <= N; ++j)
				if(i!=j && !mt[j] && OK(i, j)) { mt[i] = j, mt[j] = i; break; }
}

void Init()
{
	scanf("%d%d", &N, &M);
	for(int i = 1; i <= N; ++i)
		scanf("%s", s[i]+1);
}

void Solve()
{
	prework(), dfs(1);
	if(f) printf("YES\n");
	else printf("NO\n");
}

int main()
{
	Init(), Solve();
}

