#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef unsigned long long ull;
typedef pair<int, int> ii;

#define SZ(x) ((int)x.size())

int n, m, np;
char a[13][13];
bool used[13], mark[13];
ii all_pairs[13];

struct data {
	ll hs, hp; int id;
	data(ll _hp, ll _hs, int _id) {
		hp = _hp;
		hs = _hs;
		id = _id;
	}
	bool operator<(const data &other) const {
		if (hp == other.hp) {
			if (hs == other.hs)
				return id < other.id;
			return hs < other.hs;
		}
		return hp < other.hp;
	}
};

set<data> d;

pair<ll, ll> calc_hash(int col, const int &residue) {
	ll hs = 0, hp = 0;
	for (int j = 1; j <= np; ++j) {
		hp = hp * 27ll + (ll)(a[all_pairs[j].first][col] - 'a' + 1);
		hs = hs * 27ll + (ll)(a[all_pairs[j].second][col] - 'a');
	}
	if (residue) {
		hp = hp * 27ll + (ll)(a[residue][col] - 'a' + 1);
		hs = hs * 27ll + (ll)(a[residue][col] - 'a' + 1);
	}
	return make_pair(hp, hs);
}

void check() {
	d.clear();
	memset(mark, false, sizeof(mark));
	int residue = 0;
	for (int i = 1; i <= n; ++i) {
		if (!used[i]) {
			residue = i;
			break;
		}
	}
	for (int i = 1; i <= m; ++i) {
		auto tmp = calc_hash(i, residue);
		d.insert(data(tmp.first, tmp.second, i));
	}
	for (int i = 1; i <= m; ++i) {
		if (mark[i]) continue;
		auto tmp = calc_hash(i, residue);
		auto it = d.lower_bound(data(tmp.second, tmp.first, 0));
		if (it != d.end() && it->id == i) ++it;
		if (it == d.end() || it->hs != tmp.first || it->hp != tmp.second) continue;
		mark[i] = mark[it->id] = true;
		d.erase(it);
		d.erase(data(tmp.first, tmp.second, i));
	}
	if (!SZ(d)) {
		puts("YES");
		exit(0);
	}
	if (SZ(d) == 1 && (m & 1)) {
		int i = (*d.begin()).id;
		auto tmp = calc_hash(i, residue);
		if (tmp.first == tmp.second) {
			puts("YES");
			exit(0);
		}
	}
}

void brute(int cnt) {
	if (cnt > np) {
		check();
		return;
	}
	int p1 = -1;
	for (int i = all_pairs[cnt - 1].first + 1; i <= n; ++i) {
		if (!used[i]) {
			used[(p1 = i)] = true;
			break;
		}
	}
	if (p1 == -1) return;
	all_pairs[cnt].first = p1;
	for (int i = p1 + 1; i <= n; ++i) {
		if (used[i]) continue;
		all_pairs[cnt].second = i;
		used[i] = true;
		brute(cnt + 1);
		used[i] = false;
	}
	used[p1] = false;
}

