int dp(int a, int am = 0)
{
	if (done[a] == upto) return poss[a];
	done[a] = upto;
	if (am == c) return poss[a] = 1;
	if (am == c-1)
	{
		for (int i = 0; i < c; i++)
		{
			if (!(a & (1 << i)))
			{
				// check all the same
				for (int j = 1; j <= r; j++)
				{
					if (grid[j][i] != grid[pairs[j]][i])
					{
						return poss[a] = 0;
					}
				}
				return poss[a] = 1;
			}
		}
	}
	for (int i = 0; i < c; i++)
	{
		for (int j = 0; j < i; j++)
		{
		//	printf("hi\n");
			bool cando = 1;
			for (int k = 1; k <= r; k++)
			{
				if (grid[k][i] != grid[pairs[k]][j])
				{
			//		printf(":(\n");
					cando = 0;
					break;
				}
			}
			if (cando)
			{
				int newa = (a | (1 << i));
				newa |= (1 << j);
				if (dp(newa, am+2)) return poss[a] = 1;
			}
		}
	}
	return poss[a] = 0;
}
bool generateall(int paired)
{
	if (paired == r-1)
	{
		for (int i = 1; i <= r; i++)
		{
			if (!pairs[i]) pairs[i] = i;
		}
		paired++;
