		{
			printf("%d ", pairs[i]);
		}
		printf("\n");*/
		upto++;
		if (dp(0)) return 1;
		return 0;
	}
	for (int i = 1; i <= r; i++)
	{
		if (!pairs[i])
		{
			for (int j = i+1; j <= r; j++)
			{
				if (pairs[j]) continue;
				pairs[i] = j;
				pairs[j] = i;
				if (generateall(paired+2)) return 1;
				pairs[i] = 0;
				pairs[j] = 0;
			}
