using namespace std;

int H, W; string S[15], T[15]; bool flag = false;

bool check() {
	vector<string>I;
	for (int i = 0; i < W; i++) {
		string U = "";
		for (int j = 0; j < H; j++) U += T[j][i];
		I.push_back(U);
	}
	set<string>G;
	for (int i = 0; i < I.size(); i++) {
		string V = I[i]; reverse(V.begin(), V.end());

		if (G.find(V) != G.end()) G.erase(V);
		else G.insert(I[i]);
	}
	if (G.size() == 0) return true;
	if (G.size() == 1) {
		auto itr = G.begin();
		string V = *itr;
		string VV = V; reverse(V.begin(), V.end());
		if (V == VV) return true;
	}
	return false;
}

void dfs(vector<pair<int, int>>vec) {
	if (vec.size() == H / 2) {
		bool u[16]; for (int i = 0; i < 16; i++) u[i] = false;
		for (int i = 0; i < vec.size(); i++) {
			T[i] = S[vec[i].first]; u[vec[i].first] = true;
			T[H - 1 - i] = S[vec[i].second]; u[vec[i].second] = true;
		}
		for (int i = 0; i < H; i++) {
			if (u[i] == false) T[H / 2] = S[i];
		}
		if (check() == true) flag = true;
		return;
	}
	bool used[14];
	for (int i = 0; i < 14; i++) used[i] = false;
	for (int i = 0; i < vec.size(); i++) {
		used[vec[i].first] = true;
		used[vec[i].second] = true;
	}
	int s = -1;
	for (int i = 0; i < H; i++) {
		if (used[i] == false) { s = i; break; }
	}
	for (int i = 0; i < H; i++) {
		if (used[i] == true || i == s) continue;
		vector<pair<int, int>>D = vec; D.push_back(make_pair(s, i));
		dfs(D);
	}
}

int main() {
	cin >> H >> W;
	for (int i = 0; i < H; i++) cin >> S[i];
	dfs(vector<pair<int, int>>{});

	if (flag == true) cout << "YES" << endl;
	else cout << "NO" << endl;
	return 0;
}

