#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<string> s(n);
    for(int i = 0; i < n; ++i) {
        cin >> s[i];
    }

    vector<int> p1(n, -1);
    function<bool(int)> dfs1 = [&](int depth) {
        if(depth == n / 2) {
            int rest = -1;
            for(int i = 0; i < n; ++i) {
                if(p1[i] == -1) rest = i;
            }
            if(rest != -1) p1[rest] = rest;

            vector<bool> dp(1 << m);
            dp[0] = true;
            for(int S = 0; S < (1 << m); ++S) {
                if(!dp[S]) continue;
                for(int i = 0; i < m; ++i) {
                    if(S & (1 << i)) continue;
                    for(int j = i + 1; j < m; ++j) {
                        bool ok = true;
                        for(int k = 0; k < n; ++k) {
                            int y1 = k, y2 = p1[k];
                            ok &= s[y1][i] == s[y2][j];
                        }
                        if(ok) {
                            dp[S | (1 << i) | (1 << j)] = true;
                        }
                    }
                }
            }
            const int mask = (1 << m) - 1;
            bool res = dp[mask];
            if(m & 1) {
                for(int i = 0; i < m; ++i) {
                    if(dp[mask ^ (1 << i)]) {
                        bool check = true;
                        for(int j = 0; j < n; ++j) {
                            int y1 = j, y2 = p1[j];
                            check &= s[y1][i] == s[y2][i];
                        }
                        res |= check;
                    }
                }
            }
            if(rest != -1) p1[rest] = -1;
            return res;
        }

        bool res = false;
        for(int i = depth; i < n; ++i) {
            if(p1[i] != -1) continue;
            for(int j = i + 1; j < n; ++j) {
                if(p1[j] != -1) continue;
                p1[i] = j;
                p1[j] = i;
                res |= dfs1(depth + 1);
                p1[i] = p1[j] = -1;
            }
        }
        return res;
    };

    cout << (dfs1(0) ? "YES" : "NO") << endl;
}

