ll mypow(ll x,ll n){
    ll ret = 1;
    while(n > 0){
        if(n&1){
            ret = (ret*x)%MOD;
        }
        x = (x*x)%MOD;
        n >>= 1;
    }
    return ret;
}

ll t;

bool eval(vector<ll> &p,const vector<string> &s){
    ll count = 0;
    vector<bool> used(s[0].size(),false);
    for(int i = 0; i < s[0].size(); i++){
        if(used[i])continue;
        for(int j = i+1; j < s[0].size(); j++){
            if(used[j])continue;
            bool flag = true;
            for(int k = 0; k < s.size(); k++){
                if(s[p[k]][i] != s[p[s.size()-k-1]][j]){
                    flag = false;
                    break;
                }
            }
            if(flag){
                used[i] = true;
                used[j] = true;
                break;
            }
        }
        if(!used[i])count++;
    }
    if(count > 1){
        return false;
    }else if(count == 0){
        return true;
    }else{
        for(int i = 0; i < s[0].size(); i++){
            if(!used[i]){
                for(int j = 0; j < s.size(); j++){
                    if(s[p[j]][i] != s[p[s.size() - j - 1]][i]){
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

bool dfs(vector<ll> &p,vector<bool> selected,const vector<string> &s,int x,int lim,int m){
    if(x == lim){
        return eval(p,s);
    }
    for(int i = m; i < selected.size(); i++){
        if(!selected[i]){
            selected[i] = true;
            for(int j = i+1; j < selected.size(); j++){
                if(!selected[j]){

                    selected[j] = true;
                    p[x] = i;
                    p[p.size() - x - 1] = j;
                    if(dfs(p,selected,s,x+1,lim,i+1)){
                        return true;
                    }
                    selected[j] = false;
                }
            }
            selected[i] = false;
            return false;
        }
    }
    return false;
}

