const int base = 27;
int used[N], b[N], c[N], a[N][N], p[N], n, m;
map < int, int > cnt1, cnt2;
void gen(int x){
    if (x % 2){
        for (int i = 1; i <= m; i++){
            if (!used[i]){
                used[i] = 1;
                p[i] = (i + 1) / 2;
                gen(x - 1);
                used[i] = 0;
            }
        }
    } else{
        if (x == 0){
            for (int i = 1; i <= n; i++){
                for (int j = 1; j <= m; j++){
                    b[i] = b[i] * base + a[i][p[j]];
                }
                for (int j = m; j >= 1; j--){
                    c[i] = c[i] * base + a[i][p[j]];
                }
            }
            if (n % 2){
                for (int i = 1; i <= n; i++){
                    if (c[i] != b[i]) continue;
                    cnt1.clear();
                    cnt2.clear();
                    for (int j = 1; j <= n; j++) if (i != j){
                        cnt1[b[j]]++;
                        cnt2[c[j]]++;
                    }
                    int res = 1;
                    for (int j = 1; j <= n; j++) if (i != j){
                        if (c[j] == b[j]){
                            if (cnt1[c[j]] % 2 != 0){
                                res = 0;
                                break;
                            }
                        } else if (cnt1[c[j]] != cnt2[b[j]]){
                            res = 0;
                            break;
                        }
                    }
                    if (res){
                        cout << "YES";
                        exit(0);
                    }
                }
            } else{
                cnt1.clear();
                cnt2.clear();
                for (int j = 1; j <= n; j++){
                    cnt1[b[j]]++;
                    cnt2[c[j]]++;
                }
                int res = 1;
                for (int i = 1; i <= n; i++){
                    if (c[i] == b[i]){
                        if (cnt1[c[i]] % 2 != 0){
                            res = 0;
                            break;
                        }
                    } else if (cnt1[c[i]] != cnt2[b[i]]){
                        res = 0;
                        break;
                    }
                }
                if (res){
                    cout << "YES";
                    exit(0);
                }
            }
        } else{
            for (int i = 1; i <= m; i++){
                if (used[i]) continue;
                for (int j = 1; j <= m; j++){
                    if (used[j] || i == j) continue;
                    used[i] = 1;
                    used[j] = 1;
                    int q = (m - x) / 2 + 1;
                    p[q] = i;
                    p[m - q + 1] = j;
                    gen(x - 2);
                    used[i] = 0;
                    used[j] = 0;
                }
            }
        }
    }
}
