V<V<int>> ms;

void genMatch(V<int> &match, int m, bool hasCenter) {
    int i=0; while (i<m && match[i] != -1) i++;
    if (i == m) ms.pb(match);
    else {
        FR(j,i,m) if (match[j] == -1 && (i!=j || (!hasCenter && m%2 == 1))) {
            match[i] = j;
            match[j] = i;
            genMatch(match, m, hasCenter || i==j);
            match[i] = match[j] = -1;
        }
    }
}

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);
    int n,m; cin>>n>>m;
    V<string> ss(n);
    F(i,n) cin>>ss[i];
    V<int> curMatch(m,-1);
    genMatch(curMatch, m, false);
    H(S(ms))
    bool ok = false;
    for (V<int> match : ms) {
        H(match)
        V<int> pos(m, -1);
        V<bool> seen(m, false);
        int cnt = 0;
        F(i,m) if (!seen[i]) {
            if (match[i] == i) {
                pos[i] = m/2;
                seen[i] = true;
            } else {
                pos[i] = cnt;
                pos[match[i]] = m-1-cnt;
                seen[i] = seen[match[i]] = true;
                cnt++;
            }
        }
        H(pos)
        assert(cnt == m/2);
        set<string> revs;
        for (string &s : ss) {
            string t(m,' ');
            F(i,m) t[pos[i]] = s[i];
            if (revs.count(t)) {
                revs.erase(revs.find(t));
            } else {
                reverse(ALL(t));
                revs.insert(t);
            }
        }
        if (S(revs) == n%2)
            ok = true;
    }
    if (ok) cout<<"YES\n";
    else cout<<"NO\n";
}

