struct matching { 
  vec<int> g[N];
  int n;
  bool used[N];
  void add_edge (int a, int b) {
    g[a].pb (b); g[b].pb (a);
  }
  bool solve (int p = 0, bool mid = 0) {      
    if (p == n) {
      return 1;
    }   
    if (used[p])  return solve (p + 1, mid);

    if ((n & 1) && !mid) {
      used[p] = 1;
      if (solve (p + 1, 1)) 
        return 1;
      used[p] = 0;
    }   

    for (auto to : g[p]) {
      if (!used[to]) {
        used[to] = used[p] = 1;
        if (solve (p + 1, mid))
          return 1;
        used[to] = used[p] = 0;
      }
    }
    return 0;
  }     
} M[(int)2e5];

