using namespace BasicUnit;
const int maxN = 12;
int n, m, goal;
struct State {
	char s[maxN][maxN];
	int h, hh, val;
	static const int base = 107;
	static const int mod = 12000017;
	static const int bb = 143;
	static const int mm = 13333339;
	void calc() {
		h = hh = 0;
		val = 0;
		for(int i = 0; i < n; ++i)
			for(int j = 0; j < m; ++j) {
				val += (s[i][j] == s[n-1-i][m-1-j]);

				h = (h + s[i][j]) * base % mod;
				hh = (hh + s[i][j]) * bb % mm;
			}
	}
	bool operator < (const State &rhs) const {
		return h != rhs.h ? h < rhs.h : hh < rhs.hh;
	}
}begin;

struct Comp {
	bool operator ()(const State &x, const State &y) const {
		return x.val < y.val;
	}
};

bool SPJ() {
	static int cnt[128];
	int c = 0;
	for(int i = 0; i < n; ++i) for(int j = 0; j < m; ++j) cnt[begin.s[i][j]]++;
	for(int i = 0; i < 128; ++i) c += cnt[i] % 2;
	if(n == m && c > n) { printf("NO\n"); return true; }
	if(n != m && c) { printf("NO\n"); return true; }
	return false;
}

priority_queue<State, std::vector<State>, Comp> q;
set<State> S;
State y;

bool Astar() {
	q.push(begin); S.insert(begin);
	int cnt = 0;
	while(!q.empty()) {
		State x = q.top(); q.pop();
		for(int i = 0; i < n; ++i) for(int j = i + 1; j < n; ++j) {
			y = x; ++cnt;
			for(int k = 0; k < m; ++k) swap(y.s[i][k], y.s[j][k]);
			y.calc();
			if(y.val == goal) return true;
			if(!S.count(y)) S.insert(y), q.push(y);
		}
		for(int i = 0; i < m; ++i) for(int j = i + 1; j < m; ++j) {
			y = x; ++cnt;
			for(int k = 0; k < n; ++k) swap(y.s[k][i], y.s[k][j]);
			y.calc();
			if(y.val == goal) return true;
			if(!S.count(y)) S.insert(y), q.push(y);
		}
		if(cnt >= 3e5) return false;
	}
	return false;
}

int main() {
	n = readint(); m = readint(); goal = n * m;
	for(int i = 0; i < n; ++i) {
		char s[20];
		scanf("%s", s);
		for(int j = 0; j < m; ++j) begin.s[i][j] = s[j];
	}
	begin.calc();
	if(SPJ()) return 0;

	printf("%s\n", Astar() ? "YES" : "NO");

	return 0;
}

