inline int pr(int x, int y){
    return 12*min(x,y) + max(x,y);
}

bool solve(int H, int W, vector<string>& S){

    set<int> hvis;
    map<ii,int> mx;

    repC2(hi,hj, H) { // 66
        if (found(hvis, hi) || found(hvis,hj)) continue;

        vector<ii> pairs;
        repC2(wi,wj, W) { // 66
            if (S[hi][wi] == S[hj][wj] && S[hi][wj] == S[hj][wi]) {
                pairs.pb( ii(wi,wj) );
            }
        }
        if (W%2) {
            if (pairs.size() < (W-1)/2) continue;
        } else {
            if (pairs.size() < W/2) continue;
        }
        set<int> cov;
        vector<int> _pairs;
        for(ii p: pairs) {
            cov.insert(p.first);
            cov.insert(p.second);
            _pairs.pb( pr(p.first, p.second) );
        }
        if (cov.size() < W-1) continue;


        for(auto p: pairs) mx[p]++;
        hvis.insert(hi);
        hvis.insert(hj);
    }
    if (hvis.size() < H-1) return false;
    set<int> vis2;
    for(auto p:mx){
        if (p.second < W/2) continue;
        vis2.insert(p.first.first);
        vis2.insert(p.first.second);
    }

    return vis2.size() >= W-1;
}

