int n, m, X[15], Y[15], v[15];
long long S1[15], S2[15];
char p[15][15];
bool Pos() {
	int i, j;
	for (i = 1; i <= n; i++) {
		S1[i] = S2[i] = 0;
		v[i] = 0;
		long long t = 1;
		for (j = 1; j <= m; j++) {
			S1[i] = S1[i] * 26 + p[i][Y[j]] - 'a';
			S2[i] += (p[i][Y[j]] - 'a')*t;
			t *= 26;
		}
	}
	int ck = n % 2;
	for (i = 1; i <= n; i++) {
		if (v[i])continue;
		for (j = 1; j <= n; j++)if (i!=j && !v[j] && S1[i] == S2[j]) {
			v[i] = v[j] = 1;
			break;
		}
		if (j == n + 1) {
			if (S1[i] == S2[i] && ck) {
				ck--;
				continue;
			}
			return false;
		}
	}
	return true;
}
