    for(int j=i+1;j<h;j++){

      if( S >> j & 1 ) continue;

      vector<P> nA = A;

      nA.push_back(P( i, j ));

      int nS = S | ( 1 << i );

      nS |= ( 1 << j );

      dfs( nA, nS ); 

    }

  }

