void lineset(int start, int rem) {
    if (rem >= 2) {
        int fir;
        for (int i = 0; i < H; i++) {
            if (!usedline[i]) {
                fir = i;
                usedline[i] = true;
                break;
            }
        }
        for (int i = start; i < start + dblfact[rem]; i++) {
            lineperm[i][H - rem] = fir;
        }
        int num = start;
        for (int i = 0; i < H; i++) {
            if (!usedline[i]) {
                usedline[i] = true;
                for (int j = num; j < num + dblfact[rem - 2]; j++) {
                    lineperm[j][rem - 1] = i;
                }
                lineset(num, rem - 2);
                usedline[i] = false;
                num += dblfact[rem - 2];
            }
        }
        usedline[fir] = false;
    } else if (rem == 1) {
        for (int i = 0; i < H; i++) {
            if (!usedline[i]) {
                lineperm[start][H / 2] = i;
            }
        }
    }
}

