void solve (istream &cin = std::cin, ostream &cout = std::cout)
{
    int h, w;

    cin >> h >> w;

    vector<string> grid (h);

    for (auto &it : grid)
        cin >> it;

    vector<vector<vector<pair<int, int>>>> gr (h, vector<vector<pair<int, int>>> (w));

    for (int i = 0; i < grid.size (); i++)
        for (int j = 0; j < grid[i].size (); j++)
            for (int y = 0; y < grid.size (); y++)
                for (int x = 0; x < grid[y].size (); x++)
                    if (grid[y][x] == grid[i][j] && grid[i][x] == grid[y][j])
                        gr[i][j].emplace_back (x, y);

    bool good = false;

    if (h % 2)
    {
        for (int y = 0; y < h; y++)
        {
            if (w % 2)
                for (int x = 0; x < w; x++)
                {
                    bool check = true;

                    for (int i = 0; i < grid.size (); i++)
                        for (int j = 0; j < grid[i].size (); j++)
                        {
                            bool fnd = false;

                            for (auto it : gr[i][j])
                                if (i == y)
                                    if (j == x)
                                        fnd |= true;
                                    else
                                        fnd |= it.second == y && it.first != j;
                                else
                                    if (j == x)
                                        fnd |= it.second != i && it.first == x;
                                    else
                                        fnd |= it.second != y && it.first != x;

                            check &= fnd;
                        }

                    good |= check;
                }
            else
            {
                bool check = true;

                for (int i = 0; i < grid.size (); i++)
                    for (int j = 0; grid[i].size (); j++)
                    {
                        bool fnd = false;

                        for (auto it : gr[i][j])
                            if (i != y)
                                fnd |= it.second != y;
                            else
                                fnd |= it.second == y && it.first != j;

                        check &= fnd;
                    }

                good |= check;
            }
        }
    }
    else if (w % 2)
        for (int x = 0; x < w; x++)
        {
            bool check = true;

            for (int i = 0; i < grid.size (); i++)
                for (int j = 0; grid[i].size (); j++)
                {
                    bool fnd = false;

                    for (auto it : gr[i][j])
                        if (i != x)
                            fnd |= it.first != x;
                        else
                            fnd |= it.first == x && it.second != i;

                    check &= fnd;
                }

            good |= check;
        }
    else
    {
        bool check = true;

        for (int i = 0; i < grid.size (); i++)
            for (int j = 0; grid[i].size (); j++)
            {
                bool fnd = false;

                for (auto it : gr[i][j])
                    fnd |= true;

                check &= fnd;
            }

        good |= check;
    }

    cout << (good ? "YES" : "NO") << endl;
}

