			}
		}
	}
	return sol <= 1;
}

bool dfs(int p) {
	if (p == H) {
		int cnt = 0;
		rep(i, H) if (mt[i] == -1) {
			++cnt;
		}
		if (cnt <= 1) {
			return check();
		}
		return false;
	}

	if (mt[p] != -1) {
		return dfs(p + 1);
	}

	int cfree = 0;
	rep(i, p) {
		if (mt[i] == -1) {
			++cfree;
		}
	}
	if (H % 2 == 1 && cfree == 0) {
		if (dfs(p + 1)) {
			return true;
		}
	}

	for (int i = p + 1; i < H; ++i) {
		if (mt[i] == -1) {
			mt[p] = i;
			mt[i] = p;
			if (dfs(p + 1)) {
				return true;
			}
			mt[i] = mt[p] = -1;
		}
	}
	return false;
}

