void comb(int n)
{
	if (n >= W / 2)
	{
		if (W % 2 == 1 && n == W / 2)
		{
			for (int i = 0; i < W; i++)
			{
				if (!ary_flg[i])
				{
					ary_flg[i] = true;
					ary[n] = i;
					comb(n + 1);
					ary_flg[i] = false;
				}
			}
			return;
