    memset(swaped, -1, sizeof(swaped));
    for(int i = 0; i < n; i ++)
        cin >> s[i];

    if(n & 1)
        dfs(0, true);
    else
        dfs(0, false);
    printf(ans ? "YES" : "NO");
    return 0;
}

