bool solve(const bitset<144> maps[13][13], ll h, ll w,
           bitset<144> &state, set<ll> &to_use)
{
    if (to_use.empty()) {
        if (state.count() < w/2) return false;

        S bool checked[13];
        memset(checked, 0, sizeof(checked));
        ll cnt = 0LL;

        rep (v1, w) srep (v2, v1+1, w) {
            if (checked[v1] || checked[v2]) continue;
            if (state.test(v1*12+v2)) {
                checked[v1] = checked[v2] = true;
                cnt += 2LL;
            }
        }

        assert(cnt <= w);
        if (cnt < w - 1LL) return false;
        if (!(w & 1LL) && cnt < w) return false;
        if (!(w & 1LL) && cnt == w) return true;

        rep (v, w) {
            if (checked[v]) continue;
            if (state.test(v*12+v)) {
                checked[v] = true;
                cnt++;
                break;
            }
        }

        assert(cnt <= w);

        if (cnt == w) return true;
        return false;
    }

    bitset<144> orig_state;
    set<ll> l_to_use = to_use;

    for (auto iter1 = to_use.begin(); iter1 != to_use.end(); iter1++) {
        auto iter2 = iter1; iter2++;
        for ( ; iter2 != to_use.end(); iter2++) {
            ll h1 = *iter1;
            ll h2 = *iter2;
            l_to_use.erase(l_to_use.find(h1));
            l_to_use.erase(l_to_use.find(h2));
            orig_state = state;
            state &= maps[h1][h2];

            if (solve(maps, h, w, state, l_to_use)) return true;

            state = orig_state;
            l_to_use.insert(h1);
            l_to_use.insert(h2);
        }
    }

    return false;
}

void _main();
int main()
{
    cout << setprecision(12);
    _main();
    return 0;
}

void _main()
{
    ll h; llin(h);
    ll w; llin(w);
    V<string> grid;
    rep (i, h) {
        string tmp; CIN(tmp);
        grid.pb(tmp);
    }

    S bitset<144> maps[13][13];
    bitset<144> zero;

    rep (h1, h) rep (h2, h) {
        maps[h1][h2] = zero;
        rep (w1, w) rep (w2, w) {
            if (grid[h1][w1] == grid[h2][w2] && grid[h1][w2] == grid[h2][w1]) {
                maps[h1][h2].set(w1*12LL+w2);
            }
        }
    }

    S set<ll> to_use;
    rep (i, h) to_use.insert(i);

    if (h & 1LL) {
        rep (single, h) {
            to_use.erase(to_use.find(single));
            bitset<144> state = maps[single][single];
            if (solve(maps, h, w, state, to_use)) {
                cout << "YES" << endl;
                return;
            }
            to_use.insert(single);
        }
    }
    else {
        bitset<144> state; state.set();
        if (solve(maps, h, w, state, to_use)) {
            cout << "YES" << endl;
            return;
        }
    }

    cout << "NO" << endl;
