        R.push_back(r);
    }

    vector<bool> used(W,false);    
    int center = (W % 2) ? 0 : 1;

    for (int j = 0; j < W; j++)
    {
        if(used[j]) continue;
        used[j] = true;
        bool pair = false;
        for (int k = 0; k < W; k++)
        {
            if(used[k]) continue;
            if(rev_same(R[j], R[k])){
                used[k] = true;
                pair = true;
                break;
            }
        }
        if(!pair){
            if(rev_same(R[j],R[j]) && center==0){
                center = 1;
            }
            else{
                return false;
            }
        }
    }
    return true;
}

