{
    if(u == (n + 1)/ 2) {
        if(check()){
            printf("YES");
            exit(0);
        }
        return;
    }

    for(int i = u; i < n; i ++) {
        if(!swaped[i]) {
            swaped[i] = true;
            for(int j = i + 1; j < n; j ++) {
                if(swaped[j])
