char s[N][N];bool vis[N];
int mark[N],match[N],n,m,dt;
bool solve()
{
	bool mid = m & 1;
	for(int i = 1;i <= m;i++)match[i] = 0;
	for(int i = 1;i <= m;i++)if(!match[i])
	{
		for(int j = i + 1;j <= m && !match[i];j++)if(!match[j])
		{
			bool f = true;
			for(int k = 1;k <= n && f;k++)if(s[mark[k]][i] != s[mark[n - k + 1]][j])f = false;
			if(f)match[i] = j,match[j] = i;
		}
		if(!match[i] && mid)
		{
		  bool f = true;
		  for(int k = 1;k <= n && f;k++)if(s[mark[k]][i] != s[mark[n - k + 1]][i])f = false;
		  if(f)match[i] = i,mid = false;
		}
		if(!match[i])return false;
	}
	return true;
}
bool dfs(int now,int pos,bool mid)
{
	if(now > n)return solve();
	if(vis[now])return dfs(now + 1,pos,mid);
	for(int i = now + 1;i <= n;i++)if(!vis[i])
	{
		mark[pos] = i;mark[n - pos + 1] = now;
		vis[i] = vis[now] = true;
		if(dfs(now + 1,pos + 1,mid))return true;
		mark[pos] = mark[n - pos +1] = 0;
		vis[i] = vis[now] = false;
	}
	if(mid){mark[n >> 1 | 1] = now;return dfs(now + 1,pos,0);}
	return false;
}
