int h,w;
vector< string > grid;
int rmatch[20];
int ccmatch[20];
bool dfs1(int,int);
bool dfs2(int);

bool dfs1(int n,int r){
  if(n == w){
    rmatch[0] = r;
    rmatch[r] = 0;
    bool res = dfs2(0);
    return res;
  }
  if(ccmatch[n] != -1)
    return dfs1(n+1,r);
  int rest = 0;
  for(int i = 0;i < w;++i){
    if(ccmatch[i] == -1){
      ++rest;
      if(i != n &&
         grid[0][n] == grid[r][i] &&
         grid[0][i] == grid[r][n]){
        ccmatch[i] = n;
        ccmatch[n] = i;
        bool res = dfs1(n+1,r);
        ccmatch[i] = -1;
        ccmatch[n] = -1;
        if(res)
          return true;
      }
    }
  }
  if(rest == 1){
    ccmatch[n] = n;
    rmatch[0] = r;
    rmatch[r] = 0;
    bool res = dfs2(0);
    rmatch[0] = -1;
    rmatch[r] = -1;
    return res;
  }
  return false;
}

bool ok(int r1,int r2){
  for(int i = 0;i < w;++i){
    if(grid[r1][i] != grid[r2][ccmatch[i]] ||
       grid[r1][ccmatch[i]] != grid[r2][i])
      return false;
  }
  return true;   
}

bool pal(int r){
  for(int i = 0;i < w;++i)
    if(grid[r][i] != grid[r][ccmatch[i]])
      return false;
  return true;
}


bool dfs2(int n){
  if(n == h)
    return true;
  if(rmatch[n] != -1)
    return dfs2(n+1);
  int rest = 0;
  for(int i = 0;i < h;++i){
    if(rmatch[i] == -1){
      ++rest;
      if(i != n && ok(n,i)){
        rmatch[i] = n;
        rmatch[n] = i;
        bool res = dfs2(n+1);
        rmatch[i] = -1;
        rmatch[n] = -1;
        if(res)
          return true;
      }
    }
  }
  if(rest == 1 && pal(n)){
    return true;
  }
  return false;
}



