#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef unsigned long long ull;
typedef pair<int, int> ii;
typedef pair<ll, ll> pll;

#define SZ(x) ((int)x.size())

int n, m, np, residue;
char a[13][13];
bool used[13], mark[13];
ii all_pairs[13];

struct data {
	ll hs, hp; int id;
	data(ll _hp, ll _hs, int _id) {
		hp = _hp;
		hs = _hs;
		id = _id;
	}
	bool operator<(const data &other) const {
		if (hp == other.hp) {
			if (hs == other.hs)
				return id < other.id;
			return hs < other.hs;
		}
		return hp < other.hp;
	}
};

set<data> s;
vector<pll> d;

pll calc_hash(int col) {
	ll hs = 0, hp = 0;
	for (int j = 1; j <= np; ++j) {
		hp = hp * 27ll + (ll)(a[all_pairs[j].first][col] - 'a' + 1);
		hs = hs * 27ll + (ll)(a[all_pairs[j].second][col] - 'a' + 1);
	}
	if (residue) {
		hp = hp * 27ll + (ll)(a[residue][col] - 'a' + 1);
		hs = hs * 27ll + (ll)(a[residue][col] - 'a' + 1);
	}
	return pll(hp, hs);
}

void check() {
	d.clear();
	s.clear();
	memset(mark, false, sizeof(mark));
	for (int i = 1; i <= m; ++i) {
		auto tmp = calc_hash(i);
		d.push_back(tmp);
		s.insert(data(tmp.first, tmp.second, i));
	}
	for (int i = 1; i <= m; ++i) {
		if (mark[i]) continue;
		auto tmp = d[i - 1];
		auto it = s.lower_bound(data(tmp.second, tmp.first, 0));
		if (it != s.end() && it->id == i) ++it;
		if (it == s.end() || it->hs != tmp.first || it->hp != tmp.second) continue;
		mark[i] = mark[it->id] = true;
		s.erase(it);
		s.erase(data(tmp.first, tmp.second, i));
	}
	if (!SZ(s)) {
		puts("YES");
		exit(0);
	}
	if (SZ(s) == 1 && (m & 1)) {
		int i = (*s.begin()).id;
		auto tmp = d[i - 1];
		if (tmp.first == tmp.second) {
			puts("YES");
			exit(0);
		}
	}
}

void brute(int cnt) {
	int p1 = -1;
	for (int i = all_pairs[cnt - 1].first + 1; i <= n; ++i) {
		if (!used[i]) {
			used[(p1 = i)] = true;
			break;
		}
	}
	if (p1 == -1) {
		check();
		return;
	}
	all_pairs[cnt].first = p1;
	for (int i = p1 + 1; i <= n; ++i) {
		if (used[i]) continue;
		all_pairs[cnt].second = i;
		used[i] = true;
		brute(cnt + 1);
		used[i] = false;
	}
	used[p1] = false;
}

int main() {
#ifdef debug
	clock_t tStart = clock();
#endif
	scanf("%d%d", &n, &m);
	for (int i = 1; i <= n; ++i) {
		scanf("%s", a[i] + 1);
	}
	np = n / 2;
	for (int residue = n & 1; residue <= (n & 1) * n; ++residue) {
		used[residue] = true;
		brute(1);
	}
	puts("NO");
#ifdef debug
	printf("Total time: %d ms\n", (int)(1000.0 * (double)(clock() - tStart) / CLOCKS_PER_SEC));
#endif
	return 0;
}

