int bitCount(int n){return __builtin_popcount(n);}
vector<string> rot90(const vector<string> &v){
  int h = v.size(), w = v[0].size();
  vector<string> res(w,string(h,'.'));
  for(int i=0;i<h;i++) for(int j=0;j<w;j++) res[j][h-i-1] = v[i][j];
  return res;
}

int h,w;
vector<string> str;
int valid(vector<string> s1,vector<string> s2){
  map<string,int> S;
  for(int i=0;i<h;i++) reverse(s2[i].begin(),s2[i].end());
  for(int i=0;i<h;i++) S[s1[i] + s2[i]]++;

  int cnt = 0;
  for(auto p:S) {
    string s = p.first;
    string tmp = s;
    reverse(s.begin(),s.end());
    if(s == tmp) cnt += S[s] % 2;
  }

  for(auto p:S){
    string s = p.first;
    string tmp = s;
    reverse(s.begin(),s.end());
    if(S[s] == 0) return 0;
    S[s]--;
  }

  if(cnt > 1) return 0;
  if(h%2 == 0 && cnt) return 0;
  return 1;
}

int used[1<<12][1<<12];
int dfs(int bit1,int bit2,vector<string> s1,vector<string> s2,string skip){
  if(!valid(s1,s2)) return 0;
  if(used[bit1][bit2]++) return 0; 
  if(bitCount(bit1) + bitCount(bit2) == w) {
    for(int i=0;i<h;i++) s1[i].push_back(skip[i]);
    for(int i=0;i<h;i++) s2[i].push_back(skip[i]);
    int res = valid(s1,s2);
    for(int i=0;i<h;i++) s1[i].pop_back();
    for(int i=0;i<h;i++) s2[i].pop_back();
    return res;    
  };

  for(int i=0;i<w;i++)
    for(int j=0;j<w;j++){
      if(bit1>>i&1) continue;
      if(bit1>>j&1) continue;
      if(bit2>>i&1) continue;
      if(bit2>>j&1) continue;
      if(i == j) continue;
      int nbit1 = bit1|(1<<i);
      int nbit2 = bit2|(1<<j);
      for(int l=0;l<h;l++) s1[l].push_back(str[l][i]);
      for(int l=0;l<h;l++) s2[l].push_back(str[l][j]);
      if(dfs(nbit1,nbit2,s1,s2,skip)) return 1;
      for(int l=0;l<h;l++) s1[l].pop_back();
      for(int l=0;l<h;l++) s2[l].pop_back();
    }
  return 0;
}

int count(string str){
  int cnt[30]={};
  for(int a:str) cnt[a - 'a']++;
  int sum = 0;
  for(int i=0;i<30;i++) sum += cnt[i]%2;
  if(sum > 1) return -1;
  if(str.size()%2 == 0 && sum) return -1;
  for(int i=0;i<30;i++) if(cnt[i]%2) return i;
  return 1;
}

signed main(){
  cin.tie(0);
  ios_base::sync_with_stdio(0);
  cout << fixed << setprecision(12);

  cin>>h>>w;
  str.resize(h);
  cin>>str;
  if(w%2) str = rot90(str), swap(h,w);

  vector<string> t1(h),t2(h);  
  int ans = 0;
  if(w%2 == 0) ans = dfs(0,0,t1,t2,"");
  else{
    for(int j=0;j<w;j++) {
      memset(used,0,sizeof(used));
      if(ans) break;
      string s2;
      for(int k=0;k<h;k++) s2 += str[k][j];
      ans |= dfs(1<<j,0,t1,t2,s2);
    }
  }

  cout<<(ans? "YES":"NO")<<endl;

  return 0;
}

