using namespace std;

#define MAXN 12

int n, m;
char g[MAXN][MAXN+1];
char t[MAXN+1];

int input() {
	if (scanf("%d %d", &n, &m) < 0) return 0;
	for (int i=0; i<n; i++)
		scanf("%s", g[i]);
	return 1;
}

void init() {
}

string col_str(int j) {
	for (int i=0; i<n; i++) t[i] = g[i][j];
	t[n] = '\0';
	return string(t);
}

int check() {
	multiset<string> ss;
	for (int j=0; j<m; j++) ss.insert(col_str(j));
	int first = 1;
	while (ss.size()>0) {
		auto p = ss.begin();
		string s = *p, r = s;
		reverse(r.begin(), r.end());
		ss.erase(p);
		auto q = ss.find(r);
		if (q==ss.end()) {
			if (m%2==0) return 0;
			if (!first || r != s) return 0;
			first = 0;
		}
		else ss.erase(q);
	}
	return 1;
}

void swap_str(int i, int j) {
	if (i==j) return;
	strcpy(t, g[i]);
	strcpy(g[i], g[j]);
	strcpy(g[j], t);
}

int srch(int p) {
	if (p==n/2) {
		return check();
	}
	int q = n-1-p;
	for (int i=p+1; i<=q; i++) {
		swap_str(i,q);
		if (srch(p+1)) return 1;
		swap_str(i,q);
	}
	return 0;
}

int solve() {
	return srch(0);
}

void output(int ans) {
	printf("%s\n", ans? "YES":"NO");
}

void cleanup() {
}

int main() {
	//int ca; scanf("%d", &ca);
	while (input()) {
		init();
		output(solve());
		cleanup();
	}
}

