bool judge_local(ll i,ll j){
    ll mas[26][26];
    for(int i=0;i<26;i++)for(int j=0;j<26;j++)mas[i][j]=0;
    for(int k=0;k<w;k++){
        ll a=s[i][k]-'a',b=s[j][k]-'a';
        if(mas[b][a]>0){
            mas[b][a]--;
        }
        else{
            mas[a][b]++;
        }
    }
    ll cnt=0;
    for(int i=0;i<26;i++)for(int j=0;j<26;j++){
        if(mas[i][j]==0)continue;
        if(i!=j)return 0;
        cnt++;
    }
    return cnt<=1;
}
bool judge(){
    for(auto pp:p){
        if(judge_local(pp.first,pp.second)==0){
            return 0;
        }
    }
    return 1;
}
bool used[12];
bool dfs(){
    ll cnt=0;
    for(int i=0;i<h;i++)cnt+=used[i];
    if(cnt+1>=h){
        bool res=judge();
        if(cnt+1==h){
            ll alone=-1;
            for(int i=0;i<h;i++)if(used[i]==0)alone=i;
            ll mas[26];
            for(int i=0;i<26;i++)mas[i]=0;
            for(int j=0;j<w;j++){
                mas[s[alone][j]-'a']++;
            }
            ll ocnt=0;
            for(int i=0;i<26;i++)if(mas[i]%2==1)ocnt++;
            res&=(ocnt<=1);
        }
        return res;
    }
    ll fi=-1;
    for(int i=0;i<h;i++)if(used[i]==0){
        fi=i;
        break;
    }
    for(int i=fi+1;i<h;i++)if(used[i]==0){
        p.push_back(make_pair(fi,i));
        used[fi]=used[i]=1;
        if(dfs()==1)return 1;
        used[fi]=used[i]=0;
        p.pop_back();
    }
    return 0;
}
