        if(used[i] == false) {
            string revS = tab[i]; reverse(revS.begin(), revS.end());
            for(int j = 0; j < n; ++j) {
                if((j != i) and (used[j] == false) and (tab[j] == revS)) {
                    used[i] = used[j] = true;
                    ctr += 2;
                    break;
                }
            }
        }
    }
    if(n % 2 == 0) {
        return ctr == n;
    }
    if(ctr < n-1) return false;
    for(int i = 0; i < n; ++i) {
        if(used[i] == false) {
            string revS = tab[i]; reverse(revS.begin(), revS.end());
            return(revS == tab[i]);
        }
    }
    return false;
}

void dfs(int mask) {
    if(test()) {
        cout << "YES\n"; exit(0);
    }
    if(__builtin_popcount(mask) >= (m-1)) return;
    for(int i = 0; i < m; ++i) {
        if((mask >> i) & 1) continue;
        for(int j = i+1; j < m; ++j) {
            if(i != j and (((mask >> j) & 1) == 0)) {
                for(int x = 0; x < n; ++x) swap(tab[x][i], tab[x][j]);
                mask ^= (1 << i) ^ (1 << j);
                dfs(mask);
                for(int x = 0; x < n; ++x) swap(tab[x][i], tab[x][j]);
                mask ^= (1 << i) ^ (1 << j);
            }
        }
        break;
    }

    for(int i = m-1; i >= 0; --i) {
        if((mask >> i) & 1) continue;
        for(int j = i+1; j < m; ++j) {
            if(i != j and (((mask >> j) & 1) == 0)) {
                for(int x = 0; x < n; ++x) swap(tab[x][i], tab[x][j]);
                mask ^= (1 << i) ^ (1 << j);
                dfs(mask);
                for(int x = 0; x < n; ++x) swap(tab[x][i], tab[x][j]);
                mask ^= (1 << i) ^ (1 << j);
            }
        }
        break;
    }
}

