		for( int i = 1; i <= 26; i ++ )	 
			if( sum[i] != rhs.sum[i] ) return false;
		return true;
	}
} row[N], column[N];

bool visited_row[N], visited_column[N];

int mp_row[N], mp_column[N];

bool check()
{
	for( int i = 1; i <= h; i ++ )
		for( int j = 1; j <= w; j ++ )
			b[i][j] = a[mp_row[i]][mp_column[j]];

	for( int i = 1; i <= h; i ++ )
		for( int j = 1; j <= w; j ++ )
			if( b[i][j] != b[h+1-i][w+1-j] ) 
				return false;
	return true;
}

bool dfs_column( int u )
{
//	printf( "column:u:%d\n", u );
	if( u > w ) return check();

	for( int i = 1; i <= w; i ++ )
	{
		if( visited_column[i] ) continue;

		if( u > ( ( w + 1 ) >> 1 ) ) 
			if( !( column[mp_column[w+1-u]] == column[i] ) )
				continue;

//		printf( "u:%d, i:%d\n", u, i );
		visited_column[i] = true;
		mp_column[u] = i;

		b = dfs_column( u+1 ); 
		visited_column[i] = false; 
		if( b ) return b; 
	}
	return false;
}

bool dfs_row( int u )
{
//	printf( "u:%d\n", u );/
	if( u > h ) return dfs_column( 1 );

	for( int i = 1; i <= h; i ++ )
	{
		if( visited_row[i] ) continue;

		if( u > ( h >> 1 ) ) 
			if( !( row[mp_row[h+1-u]] == row[i] ) )
				continue;

		visited_row[i] = true;
		mp_row[u] = i;

		b = dfs_row( u+1 ) 
		visited_row[i] = false; 
		if( b ) return b;
	}
	return false;
}

