int lineperm[30000][12];
int dblfact[13];

void lineset(int start, int rem) {
    if (rem % 2 == 1) {
        int num = start;
        for (int i = 0; i < H; i++) {
            for (int j = num; j < num + dblfact[H - 1]; j++) {
                lineperm[j][H / 2] = i;
            }
            usedline[i] = true;
            lineset(num, rem - 1);
            usedline[i] = false;
            int gap = (rem > 1) ? dblfact[H - 2] : 1;
            num += gap;
        }
    } else if (rem >= 2) {
        int fir;
        for (int i = 0; i < H; i++) {
            if (!usedline[i]) {
                fir = i;
                usedline[i] = true;
                break;
            }
        }
        for (int i = start; i < start + dblfact[rem - 1]; i++) {
            lineperm[i][((H / 2) * 2 - rem) / 2] = fir;
        }
        int num = start;
        for (int i = 0; i < H; i++) {
            if (!usedline[i]) {
                usedline[i] = true;
                int gap = (rem == 2) ? 1 : dblfact[rem - 3];
                for (int j = num; j < num + gap; j++) {
                    lineperm[j][H - 1 - ((H / 2) * 2 - rem) / 2] = i;
                }
                lineset(num, rem - 2);
                usedline[i] = false;
                if (rem != 2) {
                    num += dblfact[rem - 3];
                }
            }
        }
        usedline[fir] = false;
    }
}

