        }
    }
    dblfact[0] = 1;
    dblfact[1] = 1;
    for (int i = 2; i <= 12; i++) {
        dblfact[i] = dblfact[i - 2] * i;
    }
    bool ok = false;
    fill(usedline, usedline + H, false);
    lineset(0, H);
    int permnum = (H % 2 == 0) ? dblfact[H - 1] : dblfact[H];
    for (int i = 0; i < permnum; i++) {
        for (int j = 0; j < H; j++) {
            for (int k = 0; k < W; k++) {
                nowmap[j][k] = s[lineperm[i][j]][k];
            }
        }
        int rem = W;
        bool wid[W];
        bool comp = true;
        fill(wid, wid + W, false);
        bool center = false;
        while (true) {
            if (rem >= 2) {
                int fir;
                for (int j = 0; j < W; j++) {
                    if (!wid[j]) {
                        fir = j;
                        break;
                    }
                }
                wid[fir] = true;
                bool b = false;
                for (int j = 0; j < W; j++) {
                    if (!wid[j]) {
                        bool bb = true;
                        for (int k = 0; k < H; k++) {
                            if (nowmap[k][j] != nowmap[H - 1 - k][fir]) {
                                bb = false;
                            }
                        }
                        if (bb) {
                            b = true;
                            wid[j] = true;
                            break;
                        }
                    }
                }
                if (!b) {
                    bool bb = true;
                    for (int j = 0; j < H; j++) {
                        if (nowmap[j][fir] != nowmap[H - 1 - j][fir]) {
                            bb = false;
                            break;
                        }
                    }
                    if (!bb || center) {
                        comp = false;
                        break;
                    } else {
                        center = true;
                    }
                }
                if (b) {
                    rem -= 2;
                } else {
                    rem--;
                }
            } else if (rem == 1) {
                int fir;
                for (int j = 0; j < W; j++) {
                    if (!wid[j]) {
                        fir = j;
                        break;
                    }
                }
                bool bb = true;
