                    if (nowmap[j][fir] != nowmap[H - 1 - j][fir]) {
                        bb = false;
                        break;
                    }
                }
                if (!bb || center) {
                    comp = false;
                    break;
                } else {
                    center = true;
                    break;
                }
            } else {
                break;
            }
        }
        if (comp) {
            ok = true;
            break;
        }
    }
    if (ok) {
