void dfs(const vi& hash,int i,vi& used,Pairs& ps,vector<Pairs>& cands)
{
	int n=hash.size();
	if(i==n){
		cands.push_back(ps);
		return;
	}
	if(used[i]){
		dfs(hash,i+1,used,ps,cands);
		return;
	}
	used[i]=1;
	repi(j,i+1,n) if(!used[j]&&hash[i]==hash[j]){
		used[j]=1,ps.emplace_back(i,j);
		dfs(hash,i+1,used,ps,cands);
		used[j]=0,ps.pop_back();
	}
	used[i]=0;
}

