    {
        if ((!center_col)&&((l+r)/2==j)&&((l+r)%2==1)) continue;
        for (i=0;i<h;i++)
        {
            t[cnt]+=a[i][j];
        }
        for (i=h-1;i>=0;i--)
        {
            t2[cnt]+=a[i][j];
        }
        cnt++;
    }
    sort(t,t+cnt);
    sort(t2,t2+cnt);
    int sums=0;
    for (j=0;j<cnt;j++)
