bool issame(int r1,int r2,int sign)
{
	for(int i=1;i<=26;i++)
		if(sign==1)
		{
			if(have1[r1][i]!=have1[r2][i]) return false;
		}
		else
		{
			if(have2[r1][i]!=have2[r2][i]) return false;
		}
	return true;	
}
bool tepan(int t,int sign)
{
	vector<vector<int> > v;
	bool used[25];
	for(int i=1;i<=t;i++)
	{
		if(used[i]) continue;
		used[i]=true;
		vector<int> type;
		type.push_back(i);
		for(int j=i+1;j<=t;j++)
			if(issame(i,j,sign))
			{
				used[j]=true;
				type.push_back(j);
			}
		v.push_back(type);
	}
	int cnt=0;
	for(int i=0;i<v.size();i++)
	{
		int Size=v[i].size();
		if(Size%2)
			cnt++;
	}
	if(cnt>=2) return true;
	if(cnt==1&&t%2==0) return true;
	return false;
}

