	swap(h[h1], h[h2]);
}
void SWAPW(int w1, int w2) {
	for (int i = 0; i < H; ++i) {
		swap(S[i][w1], S[i][w2]);
	}
	swap(w[w1], w[w2]);
}

bool slovew(int x) {
	if (x == W / 2) {
		for (int i = 0; i < H; ++i) {
			for (int j = 0; j < W; ++j) {
				if (S[i][j] != S[H - i - 1][W - j - 1])
					return false;
			}
		}
		return true;
	}
	for (int i = x + 1; i < W - x; ++i) {
		if (w[x] == w[i]) {
			SWAPW(i, W - x - 1);
			if (slovew(x + 1))
				return true;
			SWAPW(i, W - x - 1);
		}
	}
	if ((W & 1) && W != 1) {
		SWAPW(x, x + 1);
		for (int i = x + 1; i < W - x; ++i) {
			if (w[x] == w[i]) {
				SWAPW(i, W - x - 1);
				if (slovew(x + 1))
					return true;
				SWAPW(i, W - x - 1);
			}
		}
		SWAPW(x, x + 1);
	}
	return false;
}

bool sloveh(int x) {
	if (x == H / 2) {
		if (slovew(0))
			return true;
		else
			return false;
	}
	for (int i = x + 1; i < H - x; ++i) {
		if (h[x] == h[i]) {
			SWAPH(i, H - x - 1);
			if (sloveh(x + 1))
				return true;
			SWAPH(i, H - x - 1);
		}
	}
	if ((H & 1) && H != 1) {
		SWAPH(x, x + 1);
		for (int i = x + 1; i < H - x; ++i) {
			if (h[x] == h[i]) {
				SWAPH(i, H - x - 1);
				if (sloveh(x + 1))
					return true;
				SWAPH(i, H - x - 1);
			}
		}
		SWAPH(x, x + 1);
	}
	return 0;
}

