bool checks_1(int l,int r,bool center_col)
{
    int i,j;
    for (i=0;i<h;i++)
    {
        for (j=0;j<l;j++)
        {
            if (a[i][j]!=a[h-i-1][w-j-1]) return false;
        }
        for (j=r;j<w;j++)
        {
            if (a[i][j]!=a[h-i-1][w-j-1]) return false;
        }
        if (center_col)
        {
            j=(l+r)/2;
            if (a[i][j]!=a[h-i-1][w-j-1]) return false;
        }
    }
    string t[15];
    int cnt=0;
    for (j=l;j<r;j++)
    {
        if ((!center_col)&&((l+r)/2==j)&&((l+r)%2==1)) continue;
        for (i=0;i<h;i++)
        {
            t[cnt]+=a[i][j];
        }
        cnt++;
    }
    sort(t,t+cnt);
    for (j=1;j<cnt;j+=2)
    {
        if (t[j]!=t[j-1]) return false;
    }
    return true;
}
bool checks_2(int u,int d,bool center_row)
{
    int i,j;
    for (j=0;j<w;j++)
    {
        for (i=0;i<u;i++)
        {
            if (a[i][j]!=a[h-i-1][w-j-1]) return false;
        }
        for (i=d;i<h;i++)
        {
            if (a[i][j]!=a[h-i-1][w-j-1]) return false;
        }
        if (center_row)
        {
            i=(u+d)/2;
            if (a[i][j]!=a[h-i-1][w-j-1]) return false;
        }
    }
    string t[15];
    int cnt=0;
    for (i=u;i<d;i++)
    {
        if ((!center_row)&&((u+d)/2==i)&&((u+d)%2==1)) continue;
        for (j=0;j<h;j++)
        {
            t[cnt]+=a[i][j];
        }
        cnt++;
    }
    sort(t,t+cnt);
    for (j=0;j<cnt;j+=2)
    {
        if (t[j]!=t[j+1]) return false;
    }
    return true;
}
void dfs(int u,int d,int l,int r,bool center_row,bool center_col)
{
    if ((u==d)||(u+1==d))
    {
        if (checks_1(l,r,center_col))
        {
            puts("YES");
            exit(0);
        }
        return;
    }
    if ((l+1==r)||(l==r))
    {
        if (checks_2(u,d,center_row))
        {
            puts("YES");
            exit(0);
        }
        return;
    }
    if (center_row)
    {
        int i;
        swap_row(u,(u+d)/2);
        for (i=l+1;i<r;i++)
        {
            if (a[(u+d)/2][i]==a[(u+d)/2][l])
            {
                swap_col(i,r-1);
                dfs(u,d,l-1,r-1,false,center_col);
                swap_col(i,r-1);
            }
        }
        swap_row(u,(u+d)/2);
    }
    if (center_col)
    {
        int i;
        swap_col(l,(l+r)/2);
        for (i=u+1;i<d;i++)
        {
            if (a[i][(l+r)/2]==a[l][(l+r)/2])
            {
                swap_row(i,d-1);
                dfs(u-1,d-1,l,r,center_row,false);
                swap_row(i,d-1);
            }
        }
        swap_row(u,(u+d)/2);
    }
    if (center_col&&center_row)
    {
        swap_col(l,(l+r)/2);
        swap_row(u,(u+d)/2);
        dfs(u,d,l,r,false,false);
        swap_row(u,(u+d)/2);
        swap_col(l,(l+r)/2);
    }
    int i,j;
    for (i=u+1;i<d;i++)
    {
        if ((i==(u+d)/2)&&(!center_row)&&((u+d)%2==1)) continue;
        swap_row(i,d-1);
        for (j=l+1;j<r;j++)
        {
            if ((j==(l+r)/2)&&(!center_col)&&((l+r)%2==1)) continue;
            if (a[u][l]!=a[d-1][j]) continue;
            swap_col(j,r-1);
            dfs(u+1,d-1,l+1,r-1,center_row,center_col);
            swap_col(j,r-1);
        }
        swap_row(i,d-1);
    }
}
