	fill(was, was + m, false);
	for (int i = 0; i < m; i++)
	{
		if (was[i])
			continue;
		reverse(all(b[i]));
		for (int j = i + 1; j < m; j++)
		{
			if (!was[j] && b[i] == b[j])
			{
				was[i] = was[j] = true;
