		}
	}
	cout << "YES" << endl;
	exit(0);
}

void rec(int id, bool found, vector < pair < int, int > > & v)
{
	if (id == n)
	{
		check(v);
		return;		
	}
	if (used[id])
	{
		rec(id + 1, found, v);	
		return;
	}
	if ((n & 1) && !found)
	{
		used[id] = true;
		v.pb({id, id});
		rec(id + 1, true, v);
		v.pop_back();
		used[id] = false;
	}
	for (int i = id + 1; i <= n; i++)
	{
		if (!used[i])
		{
			used[id] = used[i] = true;
			v.pb({id, i});
			rec(id + 1, found, v);
			used[id] = used[i] = false;
			v.pop_back();
		}
	}
	return;
}	 

