#include <bits/stdc++.h>
using namespace std;

int H, W;
string S[12];
bool U[12];
int K;
int P[12];
bool R;

void check() {
  string buf(W, ' ');
  unordered_multiset<string> ss;
  for(int i = 0; i < H; ++i) {
    for(int j = 0; j < W; ++j) buf[j] = S[i][P[j]];
    ss.insert(buf);
  }
  int fail = 0;
  while(!ss.empty()) {
    auto it = ss.begin(); string s = *it; ss.erase(it);
    reverse(s.begin(), s.end());
    it = ss.find(s);
    if(it == ss.end()) { ++fail; if(fail >= 2) return; }
    else ss.erase(it);
  }
  R = true;
}

void go() {
  if(2 * K == W) { check(); return; }
  int s; for(s = 0; ; ++s) if(!U[s]) break;
  P[K] = s; U[s] = true;
  if(2 * K + 1 == W) { check(); U[s] = false; return; }
  for(int t = 0; t < W; ++t) if(!U[t]) {
    P[W - 1 - K] = t; U[t] = true;
    ++K; go(); --K;
    U[t] = false;
  }
  U[s] = false;
}

int main() {
  cin >> H >> W;
  for(int i = 0; i < H; ++i) cin >> S[i];
  go();
  cout << (R ? "YES" : "NO") << endl;
  return 0;
}

