	fin >> H;
	S.assign(H,string());
	fin >> W;
	for(int i = 0 ; i <= H-1 ; i++){
		fin >> S[i];
	}
	REP(i0,H)REP(i1,H){
		string S0(S[i0]), S1(S[i1]);
		sort(ALL(S0));sort(ALL(S1));
		if(S0==S1)row_pairable[i0][i1] = true;
		else row_pairable[i0][i1] = false;
	}
	row_selected.assign(H,false);
	row_rec();
	if(found){
		fout<<"YES"<<endl;
	}else{
		fout<<"NO"<<endl;
	}
	return 0;
}
