      t[j][w-1-i] = s[j][b];
    }
  }
  bool used[12];
  REP(i,h) used[i] = false;
  int cnt = 0;
  REP(i,h){
    FOR(j,i+1,h){
      if(used[i]) break;
      bool flag = true;
      REP(k,w){
        if(t[i][k] != t[j][w-1-k]){
          flag = false;
          break;
        }
      }
      if(flag){
        used[i] = true;
        used[j] = true;
        cnt += 2;
      }
    }
  }
  if(h-cnt>1) return false;
  REP(i,h){
    if(used[i]) continue;
    REP(j,w){
      if(t[i][j]!=t[i][w-1-j]) return false;
    }
    break;
  }
  return true;
}

bool dfs(vector<bool> used, vector<pii> p){
  if(p.size()*2 == w){
    return ok(p);
  }
  if(p.size()*2+1==w){
    vector<pii> tmp = p;
    REP(i,w){
      if(used[i]) continue;
      tmp.push_back(pii(i,i));
      break;
    }
    return ok(tmp);
  }
  REP(i,w){
    if(used[i]) continue;
    used[i] = true;
    FOR(j,i+1,w){
      if(used[j]) continue;
      vector<pii> tmp = p;
      vector<bool> tmp_u = used;
      tmp_u[j] = true;
      tmp.push_back(pii(i,j));
      if(dfs(tmp_u,tmp)){
        return true;
      }
    }
  }
  return false;
}


