            for (int k = 0; k + 1 < W; k += 2) {
                if (S[i][vec[k]] != S[j][vec[k + 1]] || S[i][vec[k + 1]] != S[j][vec[k]]) goto check1;
            }
            if (W % 2 == 1) {
                if (S[i][vec[W - 1]] != S[j][vec[W - 1]]) goto check1;
            }
            used[i] = true;
            used[j] = true;
            goto check2;
        check1:;
        }
        if (!ikkai) return;
        for (int k = 0; k + 1 < W; k += 2) {
