void dfs(vector<int> saki, bool box[12]) {
    if (saki.size() == 0 && W%2==1) {
        for (int i = 0; i < W; i++) {
            bool newbox[12] = {};
            newbox[i] = true;
            vector<int> a;
            a.push_back(i);
            dfs(a, newbox);
        }
        return;
    }
    if (saki.size() == W && W%2==1) {
        vector<int> a;
        for (int i = 1; i < W; i++)a.push_back(saki[i]);
        a.push_back(saki[0]);
        check(a);
        return;
    }
    if (saki.size() == W) {
        check(saki);
        return;
    }
    if (saki.size() == W - 1) {
        for (int i = 0; i < W; i++) {
            if (!box[i]) {
                saki.push_back(i);
                check(saki);
                return;
            }
        }
    }
    for (int i = 0; i < W; i++) {
        if (!box[i]) {
            saki.push_back(i);
            for (int j = i + 1; j < W; j++) {
                if (!box[j]) {
                    bool newbox[12];
                    for (int k = 0; k < W; k++) {
                        newbox[k] = box[k];
                    }
                    newbox[i] = true;
                    newbox[j] = true;
                    saki.push_back(j);
                    dfs(saki, newbox);
                    saki.pop_back();
                }
            }
            return;
        }
    }

}

