      return false;
    }
    return true;
  };
  function<bool(const vi&)> dfs = [&](const vi& v){
    if(swapvec.size()==H){
      dump(swapvec);
      rep(i,H/2){
        s2[i] = s[swapvec[2*i]];
        s2[H-i-1] = s[swapvec[2*i+1]];
      }
      if(H%2) s2[H/2] = s[swapvec[H-1]];
      // transpose
      rep(i,H) rep(j,W) st[j][i] = s2[i][j];
      return check();
    }
    bool res = false;
    rep(i,v.size()){
      swapvec.pb(v[i]);
      vi nxt = v;
      nxt.erase(nxt.begin()+i);
      bool adnxt = nxt.size();
      if(adnxt){
        swapvec.pb(nxt[0]);
        nxt.erase(nxt.begin());
      }
      res |= dfs(nxt);
      swapvec.pop_back();
      if(adnxt) swapvec.pop_back();
    }
    dump(swapvec.size());
    return res;
  };
  vi vec(H);
  iota(vec.begin(),vec.end(),0);
  swapvec.pb(vec[0]); vec.erase(vec.begin());
  bool ans = dfs(vec);
  vec.resize(H);
  iota(vec.begin(),vec.end(),0);
  reverse(vec.begin(),vec.end());
  swapvec.clear();
  swapvec.pb(vec[0]); vec.erase(vec.begin());
  ans |= dfs(vec);
  cout << (ans ? "YES" : "NO") << endl;
  return 0;
}

