int h, w;
vector<string> a;
vector<pair<int, int>> v;

bool check(int bit, string &s, string &t) {
  if (bit == (1 << h) - 1) return true;

  for (int i = 0; i < h; ++i) {
    if (bit & (1 << i)) continue;
    for (int j = i + 1; j < h; ++j) {
      if (bit & (1 << j)) continue;

      bool f = true;
      for (int k = 0; k < v.size(); ++k) {
        int a = v[k].fs;
        int b = v[k].sc;
        if (s[a] != t[b] || s[b] != t[a]) f = false;
      }

      if (f) {
        if (check(bit | (1 << i) | (1 << j), s, t)) return true;
      }
    }
  }

  return false;
}

bool dfs(string s, string t) {
  if (v.size() == w / 2) {
    if (check(0, s, t)) return true;
  }
  for (int i = 0; i < s.size(); ++i) {
    if (s[i] == '-') continue;
    for (int j = 0; j < t.size(); ++j) {
      if (t[j] == '-') continue;

      if (s[i] == t[j] && t[i] == s[j]) {
        s[i] = t[i] = s[j] = t[j] = '-';
        v.push_back(make_pair(i, j));
        if (dfs(s, t)) return true;
        v.pop_back();
      }
    }
  }
}

