	state.resize(m, 0);

	fori(i, 0, n) {
		cin >> mat[i];
	}

	if(m & 1) {
		fori(i, 0, m) {
			state[m / 2] = i;
			used[i] = true;
			gen(0);
			used[i] = false;
		}
	}
	else {
		gen(0);
	}

	die("NO");

	return 0;
}

