	if(X == (w+1)/2+1) {solve(); return;}
	int I = 1;
	for(;I<=w;I++) {
		if(!vis[I]) break;
	}
	vis[I] = true;
	if(!F && w%2==1) {mat[I] = I; Try(X+1, true);}
	for(int i=1;i<=w;i++) {
		if(!vis[i]) {
			mat[I] = i; mat[i] = I;
			vis[i] = true;
			Try(X+1, F);
			vis[i] = false;
		}
	}
	vis[I] = false;
}

