int rec(int state){
    if(state + 1 == (1 << H)){
        return true;
    }
    if(dp[state] != -1){
        return dp[state];
    }

    if(H % 2 == 1 && __builtin_popcount(state) == H - 1){
        int x = 0;
        while(state >> x & 1){
            ++x;
        }

        return dp[state] = can1(T[x]);
    }

    for(int i=1;i<H-1;++i){
        if(state >> i & 1){continue;}
        for(int j=i+1;j<H-1;++j){
            if(state >> j & 1){continue;}
            if(!G[i][j]){continue;}
            if(rec(state | (1 << i) | (1 << j))){
                return dp[state] = true;
            }
        }
    }

    return dp[state] = false;
}

