                            for(int xx=0;xx<26;++xx){
                                if(cnt2[xx][xx] % 2 == 1){
                                    ++odd_n;
                                }
                            }

                            can22 = can22 && odd_n == 1;

                            if(!can22){
                                continue;
                            }   
                        }

                        // std::cout << "hai" << std::endl;
                        swapColumns(l, W-1-k);
                        break;
                    }
                }

                if(T[0][k] == T[H-1][W-1-k] &&
                   T[0][W-1-k] == T[H-1][k]){

                }else{
                    can = false;
                    break;
                }
            }

            can = can && (W % 2 == 0 || T[0][W/2] == T[H-1][W/2]);

            if(!can){
