			do {
				std::vector<int> u(w);
				std::iota(ALL(u), 0);
				do {
					bool conti = [&] {
						REP(i, h) REP(j, w) {
							if (s[v[i]][u[j]] != s[v[h - i - 1]][u[w - j - 1]]) return true;
						}
						return false;
					}();
					if (conti) continue;
					else return true;
				} while (std::next_permutation(ALL(u)));
			} while (std::next_permutation(ALL(v)));
			return false;
		}();
	}

	{
		std::map<std::vector<int>, int> map;
		REP(i, h) {
			std::vector<int> cnt(26, 0);
			REP(j, w) ++cnt[s[i][j] - 'a'];
			++map[cnt];
		}

		int odd = h & 1;
		for (auto& x : map) {
			if (x.second % 2) {
				if (odd) {
					--odd;
					continue;
				}
				else return false;
			}
		}
		if (h & 1) if (odd) return false;
	}

	{
		std::map<std::vector<int>, int> map;
		REP(j, w) {
			std::vector<int> cnt(26, 0);
			REP(i, h) ++cnt[s[i][j] - 'a'];
			++map[cnt];
		}

		int odd = w & 1;
		for (auto& x : map) {
			if (x.second % 2) {
				if (odd) {
					--odd;
					continue;
				}
				else return false;
			}
		}
		if (w & 1) if (odd) return false;
	}

	if (h % 2 == 1 && w % 2 == 1) return true;
	if (h % 2 == 1 || w % 2 == 1) return true;
	// ここまではAC


