            if(mp.at(a) == mp.at(b) && flag.at(a) && flag.at(b) && a != b){
                flag[a]=false;
                flag[b]=false;
            }
        }
    }
    if(N%2 == 0){
        return count(ALL(flag),true) == 0;
    }else{
        if(count(ALL(flag),true)!=1)return false;
        map<char,int> m;
        for(int a = 0;a < N;a++){
            if(flag.at(a)){
                m = mp.at(a);
            }
        }
        int co = 0;
        int s = 0;
        for(auto a:m){
           // COUT(a.s);
            if(a.s%2==1){
                co++;
            }
            s+=a.s;
        }
        if(co >= 2){
            return false;
        }
        if(s%2 == 0){
            if(co == 0){
                return true;
            }else{
                return false;
            }
        }else{
            if(co == 1){
                return true;
            }else{
                return false;
            }
        }
    }
}
