bool calc(vector<string> const &chars, vector<int> const &hswap, vector<int> const &wswap, mdview const &hgv, mdview const &wgv) {
    // print(hgv), print(wgv);
    for (auto hs: hswap) {
        for (auto ws: wswap) {
            if (hs == -1 || ws == -1) continue;
            int y1 = hgv[hs][0];
            int x1 = wgv[ws][0];
            int y2 = hgv[hs][1];
            int x2 = wgv[ws][1];
            if (chars[y1][x1] != chars[y2][x2] || chars[y2][x1] != chars[y1][x2]) return false;
        }
    }
    return true;
}

pair<vector<int>,int> organize(vector<map<char, int>> const &cnt, int upto) {
    vector<int> gs(upto, -1);
    int g = 0;
    for (int i = 0; i < upto; i++) {
        bool exists = false;
        if (gs[i] != -1) continue;
        for (int j = i+1; j < upto; j++) {
            if (gs[j] != -1) continue;
            if (cnt[i] == cnt[j]) {
                exists = true;
                gs[i] = gs[j] = g;
            }
        }
        if (exists) g++;
    }
    if (count(gs.begin(), gs.end(), -1) > 1) return make_pair(gs, -1);
    return make_pair(gs, g);
}

class groupings_generator {
    private:
        mdview curr;
        vector<int> curr_flat;
        vector<pair<vector<int>::iterator, vector<int>::iterator>> range;

    public:
        groupings_generator(vector<vector<int>> const &orig) : curr(curr_flat) {
            curr_flat.reserve(12);
            for (auto const &r: orig) {
                for (auto x: r) {
                    curr_flat.push_back(x);
                }
            }

            auto it = curr_flat.begin();
            for (size_t i = 0; i < orig.size(); i++) {
                if (orig[i].size() > 2) {
                    range.push_back(make_pair(it, it + orig[i].size()));
                }
                sort(it, it + orig[i].size());
                it += orig[i].size();
            }
        }

        mdview const &get_curr() {
            // cerr << "curr_flat: ";
            // copy(curr_flat.begin(), curr_flat.end(), ostream_iterator<int>(cerr, ", "));
            // cerr << "curr: ";
            // for (int i = 0; i < curr.size(); i++) {
            //     cerr << "(" << curr[i][0] << "," << curr[i][1] << "), ";
            // }
            // cerr << endl;
            return curr;
        }
        bool gen_next() {
            bool flag = false;
            for (int i = range.size()-1; i >= 0; i--) {
                if (next_permutation(range[i].first, range[i].second) && next_permutation(range[i].first, range[i].second)) {
                    flag = true;
                    break;
                }
            }
            curr = mdview(curr_flat);
            return flag;
        }
};

