void dfs(int mask,int last){
    if(__builtin_popcount(mask)>=(H+1)/2){
        int num=0;
        rep(i,H){
            if((mask&(1<<i))==0){
                num++;
                add(i);
            }
        }
        hoge();
        rep(i,num) del();
        return;
    }
    rep(i,H) if((mask&(1<<i))==0){
        add(i);
        dfs(mask^(1<<i),i);
        del();
    }
}

