using namespace std;

void calc_bit(long long H, long long W, vector<string>& S, int i, int j, vector< vector< bitset<12*12> > >& a) {
    for (int x = 0; x < W; x++) {
        for (int y = x; y < W; y++) {
            if ((S[i][x] == S[j][y]) && (S[i][y] == S[j][x])) {
                a[i][j][x*W+y] = 1;
                a[i][j][y*W+x] = 1;
                a[j][i][x*W+y] = 1;
                a[j][i][y*W+x] = 1;
            }
        }
    }
    return;
}

bool dfs(long long H, long long W, vector<string>& S, vector< vector< bitset<12*12> > >& a, vector<bool>& used, int i, bitset<12*12> b) {
    while(used[i]) {
        i++;
        if (i >= H) {
            return true;
        }
    }
    for (int j = i+1; j < H; j++) {
        if ((a[i][j] & b).count() >= W) {
            used[i] = true;
            used[j] = true;
            if(dfs(H, W, S, a, used, i+1, a[i][j] & b)) return true;
            used[i] = false;
            used[j] = false;
        }
    }
    return false;
}

void solve(long long H, long long W, vector<string> S){
    vector< vector< bitset<12*12> > > a(H, vector< bitset<12*12> >(H, bitset<12*12>(0)));
    for (int i = 0; i < H; i++) {
        for (int j = i+1; j < H; j++) {
            calc_bit(H, W, S, i, j, a);
        }
    }
    bitset<12*12> b;
    for (int i = 0; i < 12*12; i++) {
        b[i] = 1;
    }
    vector<bool> used(H, false);
    if(dfs(H, W, S, a, used, 0, b)){
        std::cout << "YES" << std::endl;
    } else {
        std::cout << "NO" << std::endl;
    }
}

int main(){	
    struct timeval start,end;
    long long span;
    gettimeofday(&start,NULL);

    long long W;
    long long H;
    scanf("%lld",&H);
    vector<string> S(H-1+1);
    scanf("%lld",&W);
    for(int i = 0 ; i <= H-1 ; i++){
    	cin >> S[i];
    }
    solve(H, W, S);

    gettimeofday(&end,NULL);
    span = (end.tv_sec -start.tv_sec)*1000000LL + (end.tv_usec - start.tv_usec);
    std::cerr << "--Total Time: " << span/1000 << "ms" << endl;
    return 0;
}

