using namespace std;

bool reveq(string s1, string s2) { reverse(s2.begin(), s2.end()); return s1 == s2; }

vector<int> get_eqvid(vector<string> vs) {
	int n = vs.size();
	int cnt1[26] = { 0 }; for (auto c : vs[0]) cnt1[c - 'a']++;

	vector<int> eqvid; int cnt2[26];

	bool flg;
	for (int i = 1; i < n; ++i) {
		flg = true;
		fill(cnt2, cnt2 + 26, 0); for (auto c : vs[i]) cnt2[c - 'a']++;
		for (int j = 0; j < 26; ++j) if (!(flg &= (cnt1[j] == cnt2[j]))) break;
		if (flg) eqvid.push_back(i);
	}
	return eqvid;
}

bool check(vector<string> vs) {
	int n = vs.size(), len = vs[0].length();

	vector<int> eqvid = get_eqvid(vs);
	if (eqvid.empty() && reveq(vs[0], vs[0])) {
		swap(vs[0], vs[1]);
		eqvid = get_eqvid(vs);
	}

	for (auto id : eqvid) {

		map<pair<int, int>, int > revval;
		vector<pair<int, int>> revpid;
		map<pair<int, int>, int>::iterator tmp;

		for (int i = 0; i < len; ++i) {
			auto c1 = vs[0][i], c2 = vs[id][i];

			if ((tmp = revval.find({ c2, c1 })) != revval.end()) {
				auto val = tmp->second;
				revpid.push_back({ (val == -1) ? 0 : val, i });
				revval.erase({ c2, c1 });
			}
			else revval[{c1, c2}] = (i ? i : -1);
		}

		if (revval.size() != len % 2) continue;

		int revnum = revpid.size();
		vector<int> perm(revnum); for (int j = 0; j < revnum; ++j) perm[j] = j;
		vector<string> nvs(n - 2, "");

		swap(vs[1], vs[id]);

		while (true) {
			for (auto id : perm) for (int k = 0; k < n - 2; ++k) nvs[k] += vs[k + 2][revpid[id].first];
			if (!revval.empty()) for (int k = 0; k < n - 2; ++k) nvs[k] += vs[k + 2][revval.begin()->second];
			for (int l = revnum - 1; l >= 0; --l) for (int k = 0; k < n - 2; ++k) nvs[k] += vs[k + 2][revpid[l].second];

			while (!nvs.empty()) {
				if (nvs.size() == 1 && !reveq(nvs[0], nvs[0])) break;

				bool flg = false;
				for (int k = 1, num = nvs.size(); k < num; ++k) {
					if (reveq(nvs[0], nvs[k])) { nvs.erase(nvs.begin() + k); nvs.erase(nvs.begin()); flg = true; break; }
				}
				if (!flg) break;
			}

			if (nvs.empty())
				return true;

			if (!next_permutation(perm.begin(), perm.end())) break;
		}
	}
	return false;
}

