	if(p == 0) return check();

	for(int y = p+1; y <= h; y++){
		if(used[y]) continue;

		used[p] = used[y] = true;
		vec.push_back(P(p, y));

		if(dfs()) return true;

		used[p] = used[y] = false;
		vec.pop_back();
	}
	return false;
}

