bool chk[15];

void go(int r)
{
	if (r <= 1) {
		int x = -1;
		for (int i = 0; i < N; i++) if (!chk[i]) x = i;
		int v = 0;
		for (int i = 0; i < pick.size(); i++) {
			for (int j = 0; j < M; j++) T[v][j] = S[pick[i].first][j];
			v++;
		}
		if (x >= 0) {
			for (int j = 0; j < M; j++) T[v][j] = S[x][j];
			v++;
		}
		for (int i = (int)pick.size() - 1; i >= 0; i--) {
			for (int j = 0; j < M; j++) T[v][j] = S[pick[i].second][j];
			v++;
		}

		multiset<string> p, q;
		for (int j = 0; j < M; j++) {
			string u,v;
			for (int i = 0; i < N; i++) u += T[i][j];
			for (int i = N-1; i >=0; i--) v += T[i][j];
			p.insert(u);
			q.insert(v);
		}

		auto I = p.begin(), J = q.begin();
		while (I != p.end()) {
			if (*I != *J) return;
			I++; J++;
		}
		puts("YES");
		exit(0);
	}
	else {
		int s;
		for (int i = 0; i < N; i++) if (!chk[i]) { s = i; break; }
		chk[s] = 1;
		for (int i = s + 1; i < N; i++) if (!chk[i]) {
			chk[i] = 1;
			pick.push_back({ s,i });
			go(r - 2);
			pick.pop_back();
			chk[i] = 0;
		}
		chk[s] = 0;
	}
}

