template<typename T> void read(T &a) {
	register int b = 1, c; a = 0;
	for (c=gc(); c > 57 || c < 48; c=gc()) if (c == 45) b = -1;
	for (; c >= 48 && c <= 57; c=gc()) a = a * 10 + c - 48;
	a *= b;
}

int n, m;
int per[N];
map<string, int> M;
char c[N][N], tmp[N][N];

void solve(int line, int dep, bool f) {
    if (line == n) {
		for (int i = 0; i < n; i++) if (!~per[i]) return;
		// for (int i = 0; i < n; i++) printf("%d%c", per[i], " \n"[i+1 == n]);
		M.clear();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                tmp[per[i]][j] = c[i][j];
            }
        }
		for (int i = 0; i < m; i++) {
            string s;
            for (int j = 0; j < n; j++) {
				s += tmp[j][i];
            }
            string t;
            for (int j = 0; j < n; j++) {
				t += tmp[n - 1 - j][i];
            }
			M[s]++;
			M[t]--;
		}
		bool flag = 1;
		for (map<string, int>::iterator it = M.begin(); it != M.end(); it++) {
			// printf("%s %d\n", it->first.c_str(), it->second);
            if (it->second != 0) flag = 0;
		}
		if (flag) {
			puts("YES\n");
			exit(0);
		}
		return;
    }
    if (~per[line]) {
        solve(line + 1, dep, f);
        return;
    }
    per[line] = dep;
    for (int i = line + 1; i < n; i++) {
        if (!~per[i] && i != line) {
            per[i] = n - 1 - dep;
            solve(line + 1, dep + 1, f);
            per[i] = -1;
        }
    }
    if (f) {
		per[line] = (n - 1) >> 1;
		solve(line + 1, dep, 0);
	}
    per[line] = -1;
    solve(line + 1, dep, f);
}

int main() {
    read(n); read(m);
    for (int i = 0; i < n; i++) {
        scanf("%s", c[i]);
    }
    memset(per, -1, sizeof per);
    solve(0, 0, n&1);
    puts("NO\n");
	return 0;
}

