        for (int i = 0; i < W; i++) {
            for (int j = 0; j < H; j++) { cols[i].push_back(S[r[j]][i]); }
        }
        vector<bool> unused(W, true);
        int zuru = 0;
        bool ans = true;
        for (int i = 0; i < W; i++) {
            if (not unused[i]) { continue; }
            for (int j = i + 1; j < W; j++) {
                if (unused[j] and f(cols[i], cols[j])) {
                    unused[i] = false, unused[j] = false;
                    break;
                } else if (j == W - 1) {
                    if (W % 2 == 1 and f(cols[i], cols[i])) {
                        zuru++;
                        unused[i] = false;
                    } else {
                        ans = false;
                    }
                }
            }
        }
        if (ans and zuru <= 1) {
            cout << "YES" << endl;
            return 0;
        }
    }
    cout << "NO" << endl;
}

