int h, w;
string s[12];
vector<vector<int> > cnt(12, vector<int>(26, 0));

bool check(vector<int> ord) {
  string t[w];
  for ( int i = 0; i < h; i++ ) {
    for ( int j = 0; j < w; j++ ) t[j].push_back(s[ord[i]][j]);
  }

  bool flag = false;
  int cnt = 0;
  int bit = 0;
  for ( int i = 0; i < w; i++ ) {
    if ( (1 << i) & i ) continue;
    for ( int j = 0; j < w; j++ ) {
      if ( (1 << j) & j ) continue;
      reverse(t[i].begin(), t[i].end());
      if ( t[i] == t[j] ) {
	cnt += 2, bit |= (1<<i)+(1<<j);
	break;
	reverse(t[i].begin(), t[i].end());
      }
      reverse(t[i].begin(), t[i].end());
      if ( j == w-1 ) {
	if ( flag ) return false;
	string u = t[i];
	reverse(u.begin(), u.end());
	if ( u == t[i] ) flag = true, cnt++, bit |= 1<<i;
	else return false;
      }
    }
  }

  return true;
}

bool select(vector<int> ord, int bit, int num) {
  if ( h - num <= 1 ) {
    if ( h % 2 == 0 ) return check(ord);
    else {
      for ( int i = 0; i < h; i++ ) {
	if ( (1 << i) & i ) continue;
	ord[h/2] = i;
	break;
      }
      return check(ord);
    }
  } else {
    int ret = 0;
    for ( int i = 0; i < h; i++ ) {
      if ( (1 << i) & i ) continue;      
      ord[num/2] = i;
      int nbit = bit | 1<<i;
      for ( int j = 0; j < h; j++ ) {
	if ( !((1 << j) & i && cnt[i] == cnt[j]) ) continue;
	ord[h-num/2-1] = j;
	ret |= select(ord, nbit | 1<<j, num+2);
      }
    }
    return ret;
  }
}

