using namespace std;

const int N = 15;
typedef pair<int,int> ii;

int h, w;
int cnt_h;
ii row[N];
ii col[N];
string a[N];
bool can[N][N];

void yes() {
	printf("YES\n"); exit(0);
}

bool check_col(int i, int j) {
	for (int k = 1; k <= cnt_h; ++k) {
		if (a[row[k].first][i] != a[row[k].second][j]) return false;
	}
	return true;
}

void brute_col(int pos, int mask) {
	if (pos == w) {
		if (w % 2 == 0 && mask == 0) {
			yes();
		}
		if (w % 2 == 1 && __builtin_popcount(mask) == 1) {
			for (int c = 0; c < w; ++c) {
				if (mask >> c & 1) {
					if (check_col(c, c)) yes();
				}
			}
		}
		return;
	}

	brute_col(pos + 1, mask | (1 << pos));

	for (int c = 0; c < w; ++c) {
		if (mask >> c & 1) {
			if (check_col(c, pos)) {
				brute_col(pos + 1, mask ^ (1 << c));
			}
		}
	}
}

void brute_row(int pos, int mask) { 
	// {mask} is the set of currently unmatched rows
	if (pos == h) {
		if (h % 2 == 0 && mask == 0) {
			brute_col(0, 0);
		}
		if (h % 2 == 1 && __builtin_popcount(mask) == 1) {
			for (int r = 0; r < h; ++r) {
				if (mask >> r & 1) {
					row[++cnt_h] = ii(r, r);
					brute_col(0, 0);
					--cnt_h;
					break;
				}
			}
		} 
		return;
	}

	brute_row(pos + 1, mask | (1 << pos));

	for (int r = 0; r < h; ++r) {
		if (mask >> r & 1) {
			if (can[pos][r]) {
				row[++cnt_h] = ii(pos, r);
				brute_row(pos + 1, mask ^ (1 << r));
				--cnt_h;
			}
		}
	}
}

