  }

  if (d == H - d - 1) {
    for (int i = 0; i < H; i++) if (!(used >> i & 1)) {
      if (bin[i] == bin[i]) {
        hist[d] = s[i];
        dfs(hist, s, bin, d+1, used | (1 << i));
      }
    }
  } else {

    for (int i = 0; i < H; i++) if (!(used >> i & 1)) {
      for (int j = 0; j < H; j++) if (i != j && !(used >> i & 1)) {
        if (bin[i] == bin[j]) {
          hist[d] = s[i];
          hist[H - d - 1] = s[j];
          dfs(hist, s, bin, d+1, used | (1 << i) | (1 << j));
        }
      }
    }

  }
}

