int dp(int mask) {
    int &ret = cc[mask];
    if(ret != -1) return ret;
    if(mask == (1 << H) - 1) return ret = 1;

    ret = 0;
    int cnt = 0;
    int p = -1;
    for(int i = 0; i < H; i++) {
        if(mask & (1 << i)) continue;
        if(p == -1) p = i;
        cnt++;
    }
    for(int i = cnt % 2? p : p + 1; i < H; i++) {
        if(mask & (1 << i)) continue;

        bool ok = true;
        for(int j = 0; j < W; j++) {
            if(G[p][j] != G[i][ match[j] ]) {
                ok = false;
                break;
            }
        }
        if(ok) {
            ret |= dp(mask | (1 << p) | (1 << i));
        }
    }
    return ret;
}

void dfs(int mask, int x, int y) {
    if(mask == (1 << W) - 1) {
        memset(cc, -1, sizeof(cc));
        if(dp( (1 << x) ^ (1 << y) )) {
            printf("YES");
            exit(0);
        }
        return;
    }
    int cnt = 0;
    int p = -1;
    for(int i = 0; i < W; i++) {
        if(mask & (1 << i)) continue;
        if(p == -1) p = i;
        cnt++;
    }
    for(int i = cnt % 2? p : p + 1; i < W; i++) {
        if(mask & (1 << i)) continue;

        if(G[x][i] == G[y][p] && G[y][i] == G[x][p]) {
            match[p] = i;
            match[i] = p;
            dfs(mask | (1 << p) | (1 << i), x, y);
        }
    }
}

