const int P = int(1e9) + 7;

vector<ll> gen(int n, int m, int mid, int mask, int num) {
  vector <int> perm;
  for (int i = 0; i < n; ++i) {
    if (i == mid) { continue; }
    if (((mask >> i) & 1) != num) {
      perm.push_back(i);
    }
  }
  int k = int(perm.size());
  if (mid != -1) {
    perm.push_back(mid);
  }

  vector <ll> res;
  do {
    vector <int> cur(m, 0);
    for (int i = 0; i < m; ++i) {
      int curX = 0;
      for (int x : perm) {
        curX <<= 5;
        curX += (s[x][i] - 'a');
      }
      cur[i] = curX;
    }
    /*dbg("mid %d mask %d num %d perm = ", mid, mask, num);
    for (int x : perm) {
      dbg(" %d", x);
    }
    dbg(" res ");
    for (int x : res.back()) {
      dbg(" %d", x);
    }
    dbg("\n");*/
    sort(cur.begin(), cur.end());
    ll hash = 0;
    for (int x : cur) {
      hash = hash * P + x;
    }
    res.push_back(hash);
  } while (next_permutation(perm.begin(), perm.begin() + k));
  sort(res.begin(), res.end());
  return res;
}

bool solve(int n, int m, int mid, int mask0) {
  //dbg("mid %d mask %d\n", mid, mask0);
  vector <ll> a = gen(n, m, mid, mask0, 0);
  vector <ll> b = gen(n, m, mid, mask0, 1);
  for (int i = 0, j = 0; i < int(a.size()) && j < int(b.size()); ) {
    if (a[i] == b[j]) {
      return true;
    } else if (a[i] < b[j]) {
      ++i;
    } else {
      ++j;
    }
  }
  return false;
}

bool solve(int n, int m, int mid) {
  for (int mask = 0; mask < (1 << n); ++mask) {
    if (mid != -1 && (mask & (1 << mid))) {
      continue;
    }
    if (mid == 0 && n != 1 && (mask & 2) == 0) { continue; }
    if (mid != 0 && (mask & 1) == 0) { continue; }
    if (__builtin_popcount(mask) != n / 2) {
      continue;
    }

    if (solve(n, m, mid, mask)) {
      return true;
    }
  }
  return false;
}

bool solve(int n, int m) {
  if (n % 2 == 1) {
    for (int i = 0; i < n; ++i) {
      if (solve(n, m, i)) {
        return true;
      }
    }
    return false;
  } else {
    return solve(n, m, -1);
  }
}

