bool dfs(int rem, int noUse, int depth) {
	int i, j;
	vector<int> perm;

	if (w - depth * 2 == 1) {	//バグがあります
		perm.resize(w);
		for (j = 0; j < depth; j++) {
			perm[j] = kumi[j][0];
			perm[w - 1 - j] = kumi[j][1];
		}
		perm[(w - 1) / 2] = noUse;
		for (j = 0; j < perm.size(); j++) cout << perm[j] << " "; cout << endl;
		if (check(perm)) return true;
		return false;
	}
	if (w == depth * 2) {
		perm.resize(w);
		for (j = 0; j < depth; j++) {
			perm[j] = kumi[j][0];
			perm[w - 1 - j] = kumi[j][1];
		}
		if (check(perm)) return true;
		return false;
	}

	for (i = 0; i < w; i++) if (i != noUse && ((rem >> i) & 1)) break;
	for (j = i + 1; j < w; j++) {
		if (j != noUse && ((rem >> j) & 1)) {
			kumi[depth][0] = i;
			kumi[depth][1] = j;
			bool res = dfs(rem - (1 << i) - (1 << j), noUse, depth + 1);
			if (res) { return true; }
		}
	}
	return false;
}

