#define out std::cout
#define rep(i,N) for(int i=0;i<N;++i)
typedef long long int LL;

int H, W;
std::map<char, int>hcou[20], wcou[20];

int main()
{
	in >> H >> W;
	std::vector<std::string>S(H);
	rep(i, H) in >> S[i];
	int modCouH = 0, modCouW = 0;
	rep(i, H) rep(j, W) ++hcou[i][S[i][j]];
	rep(i, H) rep(j, W) ++wcou[j][S[i][j]];
	rep(i, H)
	{
		if (hcou[i].empty()) continue;
		bool ok = false;
		rep(j, H)
		{
			if (i == j || hcou[j].empty()) continue;
			bool flag = true;
			for (char c = 'a'; c <= 'z'; ++c)
			{
				if (hcou[i][c] != hcou[j][c])
				{
					flag = false;
					break;
				}
			}
			if (flag)
			{
				hcou[i].clear();
				hcou[j].clear();
				ok = true;
				break;
			}
		}
		if (!ok) ++modCouH;
	}
	rep(i, W)
	{
		if (wcou[i].empty()) continue;
		bool ok = false;
		rep(j, W)
		{
			if (i == j || wcou[j].empty()) continue;
			bool flag = true;
			for (char c = 'a'; c <= 'z'; ++c)
			{
				if (wcou[i][c] != wcou[j][c])
				{
					flag = false;
					break;
				}
			}
			if (flag)
			{
				wcou[i].clear();
				wcou[j].clear();
				ok = true;
				break;
			}
		}
		if (!ok) ++modCouW;
	}
	modCouH -= H % 2;
	modCouW -= W % 2;
	out << (modCouH == 0 && modCouW == 0 ? "YES" : "NO") << std::endl;
	return 0;
}

