#include<bits/stdc++.h>
#include <random>
using namespace std;
int h,w;
bool match[15][15];
bool dp[1 << 13];
char s[15][15];
int main()
{
	random_device r;
	mt19937 mt(r());
	scanf("%d %d",&h,&w);
	for(int i = 0; i < h; i++)
	{
		scanf("%s",s[i]);
	}

	for(int t = 0 ; t < 100000; t++)
	{
		memset(match,true,sizeof(match));
		for(int k = 0; k < w; k++)
		{
			for(int j = k ; j < w; j++)
			{
				for(int i = 0; i < h; i++)
				{
					if(s[i][k] != s[h - 1 - i][j])
						match[k][j] = false;
				}
			}
		}
		dp[0] = true;
		for(int mask = 0; mask < (1 << w); mask++)
		{
			if(dp[mask] == false)
				continue;
			for(int i = 0 ; i < w; i++)
			{
				for(int j = i+1 ; j < w; j++)
				{
					if(!(mask & (1 << i)) && !(mask & (1 << j)) && match[i][j])
						dp[mask | (1 << i) | (1 << j)] = true;
				}
			}
		}
		bool can = false;
		if(w & 1)
		{
			for(int i = 0 ; i < w; i++)
			{
				if(dp[((1 << w) -1) - (1 << i)] && match[i][i])
				{
					can = true;
					break;
				}
			}
		}
		else
		{
			can = dp[(1 << w)-1];
		}
		if(can)
		{
			puts("Yes");
			return 0;
		}
		shuffle(s,s+h, mt);
	}

	puts("NO");
	return 0;
}

