#define X 12
int h,w;
string s[X];

string Fcan(int a[]){
    //lol(i,11)cout<<a[i]<<" ";cout<<endl;
    bool uni[X][X];
    lol(i,w)lol(j,w){
	uni[i][j]=1;
	lol(k,h)uni[i][j]&=s[k][i]==s[a[k]][j];
    }
    bool used[X];fill(used,used+X,0);
    bool odduse=w%2==1;
    lol(i,w){
	if(used[i])continue;
	bool done=false;
	for(int j=i+1;j<w;j++){
	    if(uni[i][j]&&!used[j])done=1,used[j]=1;
	}
	if(!done&&odduse){
	    if(uni[i][i])done=1,odduse=0;
	}
	if(!done)return "nya-n";
    }
    return "ok";
}

bool DFS(int a[]){
    bool used[X+1];fill(used,used+X,0);
    lol(i,h)used[a[i]]=true;
    int sum=0;lol(i,h)sum+=used[i];
    //cout<<"&"<<sum<<endl;
    //lol(i,h)cout<<a[i]<<" ";cout<<endl;
    if(sum==h)return Fcan(a)=="ok";
    bool ans=false;
    if(sum<=h-2){
	int first;
	lol(i,h)if(!used[i]){first=i,used[i]=true;break;}
	lol(i,h)if(!used[i]){
	    a[first]=i,a[i]=first;
	    ans|=DFS(a);
	    a[first]=X,a[i]=X;
	}
	used[first]=false;
    }
    if((h-sum)%2==1){
	lol(i,h)if(!used[i]){
	    a[i]=i;
	    ans|=DFS(a);
	    a[i]=X;
	    break;
	}
    }
    return ans;
}

int main(){
    cin>>h>>w;
    lol(i,h)cin>>s[i];
    int a[X];fill(a,a+X,X);
    cout<<(DFS(a)?"YES":"NO")<<endl;
    return 0;
}

