int H, W;
int bitcount(int x) {
  int c = 0;
  while (x) {
    x -= x & (-x);
    c++;
  }
  return c;
}

int log2(int x) {
  int c = 0;
  while (x) {
    x >>= 1;
    c++;
  }
  c--;
  return c;
}
int cc = 0;
bool dfs(int S) {
  cc++;
  // dump(S,s);

  if (bitcount(S) <= 1) {
    vector<string> a(H);
    rep(i, 0, p.size()) {
      a[i] = v[p[i].first];
      a[H - 1 - i] = v[p[i].second];
    }
    if (H & 1) {
      int c = 0;
      while (S) {
        S >>= 1;
        c++;
      }
      c--;

      a[H / 2] = v[c];
    }
    // dump(a);
    string dummy;
    loop(H) { dummy += "#"; }
    vector<string> b(W, dummy);
    // b[i][j]=a[i][j];
    rep(i, 0, W) rep(j, 0, H) { b[i][j] = a[j][i]; }
    // dump(b);
    int U = (1 << W) - 1;
    rep(i, 0, W) {
      rep(j, i + 1, W) {
        string t = b[j];
        reverse(all(t));
        // dump(U,b[i],b[j],t);
        if ((U >> i & 1) & (U >> j & 1) and t == b[i]) {
          U ^= (1 << i);
          U ^= (1 << j);
        }
      }
    }
    // dump(U);

    if (W & 1) {
      int c = 0;
      int X = U;
      while (X) {
        X >>= 1;
        c++;
      }
      c--;
      string t = b[c];
      reverse(all(t));
      if (t == b[c]) {
        U ^= (1 << c);
      }
    }

    return U == 0;
  }

  vector<int> hot;
  int ss = S;
  while (ss) {
    hot.push_back(ss & (-ss));
    ss -= (ss) & (-ss);
  }
  // dump(hot);
  rep(i, 1, hot.size()) {
    p.push_back(pii(log2(hot[0]), log2(hot[i])));
    //    dump(s);
    if (dfs(S ^ hot[0] ^ hot[i]))
      return true;
    p.pop_back();
  }
  return false;
}

