        }
        vector<bool> unused(W, true);
        for (int i = 0; i < W; i++) {
            for (int j = i + 1; j < W; j++) {
                if (unused[j] and f(cols[i], cols[j])) {
                    unused[i] = unused[j] = false;
                    break;
                }
            }
        }
        const int ans = accumulate(unused.begin(), unused.end(), 0);
        if (ans <= 1) {
            bool s = true;
            for (int i = 0; i < W; i++) {
                if (unused[i] and not f(cols[i], cols[i])) {
                    s = false;
                }
            }
            if (s) {
                cout << "YES" << endl;
                return 0;
            }
        }
    }
    cout << "NO" << endl;
    return 0;
}

