			int a, b;
			for(a = 0, b = n - 1; a < n && str[a][i] == str[b][j]; a++, b--);
			if(a == n) {
				ok = 1;
				break;
			}
		}
		if(ok) vis[i] = vis[j] = 1;
		else if(!use) {
			int a, b;
			for(a = 0, b = n - 1; a <= b && str[a][i] == str[b][i]; a++, b--);
			if(a < b) return 0;
			vis[i] = use = 1;
		}
		else return 0;
	}
	rep(i, 0, n) de(str[i]);
	rep(i, 0, n) dd(i), de(match[i]);
