void gao(int id, int msk) {
	if(msk >> id & 1) {
		gao(id + 1, msk);
		return ;
	}
	if(msk == all) {
		if(check())
			throw 1;
		return ;
	}
	msk |= 1 << id;
	for(int j = all ^ msk; j; j -= j & -j) {
		int nxt = LOG[j & -j];
		if(nxt == id) continue;
		match[id] = nxt;
		match[nxt] = id;
		gao(id + 1, msk | 1 << nxt);
	}
}
