bool EqualCol(int x, int y) {
  memset(cnt, 0, sizeof(cnt));
  for(int i = 0; i < n; i++)
    cnt[(int)(s[i][x] - 'a')]++,
      cnt[(int)(s[i][y] - 'a')]--;
  for(int i = 0; i < 26; i++)
    if(cnt[i]) return 0;
  return 1;
}

bool EqualRow(int x, int y) {
  memset(cnt, 0, sizeof(cnt));
  for(int i = 0; i < m; i++)
    cnt[(int)(s[x][i] - 'a')]++,
      cnt[(int)(s[y][i] - 'a')]--;
  for(int i = 0; i < 26; i++)
    if(cnt[i]) return 0;
  return 1;
}

