  //cerr << "!" << endl;
  for(int i = 0; i < n; i++)
    for(int j = 0; j < m; j++)
      if(s[row[i]][col[j]] != s[row[n - i - 1]][col[m - j - 1]]) return 0;
  return 1;
}

bool SolveCol(int x) {
  //cerr << "!" << " " << x << endl;
  if(x == (m + 1) / 2) return Check();
  if((m & 1) && (x == m / 2)) {
    for(int i = 0; i < m; i++)
      if(!visc[i])
	col[x] = i;
    return SolveCol(x + 1);
  }
  for(int i = 0; i < m; i++)
    if(!visc[i])
      for(int j = i + 1; j < m; j++)
	if(!visc[j] && EqualCol(i, j)) {
	  visc[j] = visc[i] = 1;
	  col[x] = i;
	  col[m - x - 1] = j;
	  if(SolveCol(x + 1)) return 1;
	  visc[j] = visc[i] = 0;
	}
  return 0;
}

bool SolveRow(int x) {
  if(x == (n + 1) / 2) return SolveCol(0);
  if((n & 1) && (x == n / 2)) {
    for(int i = 0; i < n; i++)
      if(!visr[i])
	row[x] = i;
    return SolveRow(x + 1);
  }
  for(int i = 0; i < n; i++)
    if(!visr[i]) 
      for(int j = i + 1; j < n; j++)
	if(!visr[j] && EqualRow(i, j)) {
