bool check() {
	set<string> st;
	rep(i, w) {
		if (st.count(t[i])) st.erase(t[i]);
		else {
			string tmp = t[i];
			reverse(all(tmp));
			st.insert(tmp);
		}
	}
	if (st.empty())	return true;
	else if (st.size() == 1) {
		string tmp = *st.begin();
		string rev = tmp;
		reverse(all(rev));
		return rev == tmp;
	}
	return false;
}

bool solve(int x) {
	if (2 * bitcnt(x) >= h) {
		int cnt = 0;
		rep(i, h) {
			if (!((x >> i) & 1)) {
				rep(j, w) {
					t[j][tcnt] = s[i][j];
				}
				cnt++;
				tcnt++;
			}
		}
		if (check())	return true;
		tcnt -= cnt;
		return false;
	}
	rep(i, h) {
		if (!((x >> i) & 1)) {
			rep(j, w)	t[j][tcnt] = s[i][j];
			tcnt++;
			if (solve(x | (1 << i)))	return true;
			tcnt--;
		}
	}
	return false;
}

