bool taken[12];
int with[12];
vi deja;

bool test()
{
  vector<ii > pp;
  REP(i, 0, R-1)
  {
    if(with[i] >= i) pp.push_back(make_pair(i, with[i]));
  }
  deja.assign(C, false);
  bool seul = false;
  REP(i, 0, C-1)
  {
    if(!deja[i])
    {
      REP(j, i+1, C-1)
      {
        bool oui = true;
        LOOP(k, pp)
        {
          if(!ok[pp[k].first][pp[k].second][i][j])
          {
            oui = false;
            break;
          }
        }
        if(oui)
        {
          deja[i] = true;
          deja[j] = true;
          break;
        }
      }
      if(!deja[i])
      {
        if(seul) return false;
        LOOP(k, pp)
        {
          if(!ok[pp[k].first][pp[k].second][i][i]) return false;
        }
        seul = true;
        deja[i] = true;
      }
    }
  }
  return true;
}

bool dp(int x, bool dejaun)
{
  if(x == R)
  {
    return test();
  }

  if(taken[x]) return dp(x+1, dejaun);
  else
  {
    if(!dejaun)
    {
      taken[x] = true;
      with[x] = x;
      if(dp(x+1, true)) return true;
      taken[x] = false;
    }
    REP(y, x+1, R-1)
    {
      if(!taken[y])
      {
        taken[x] = true;
        taken[y] = true;
        with[x] = y;
        with[y] = x;
        if(dp(x+1, dejaun)) return true;
        taken[x] = false;
        taken[y] = false;
      }
    }
    return false;
  }
}

