            ok[i][j][k][l] = true;
            ok[i][j][l][k] = true;
            ok[j][i][k][l] = true;
            ok[j][i][l][k] = true;
          }
        }
      }
    }
  }

  REP(i, 0, R-1) taken[i] = false;
  if(dp(0, false)) printf("YES\n");
  else printf("NO\n");


  return 0;
}

