bool check()
{
	vector<LL> sym;
	rep(i, m) if(fo[n][i] == fr[n][i]) sym.push_back(fo[n][i]);
	sort(sym.begin(), sym.end());
	sym.push_back(LINF);
	sort(fo[n], fo[n] + m);
	sort(fr[n], fr[n] + m);
	rep(i, m) if(fo[n][i] != fr[n][i]) return false;
	int pos = 0, cur = 0, cnt = 0;
	rep(i, m) if(fo[n][i] == sym[pos]) cur ^= 1;
	else {
		cnt += cur;
		cur = 0;
		while(fo[n][i] > sym[pos + 1]) pos ++;
		if(fo[n][i] == sym[pos]) cur ^= 1;
	}
	return cnt == (m & 1);
}

bool solve(int id, int beg, LL t)
{
	if(id == n) return check();
	for(int i = (id >= (n >> 1) ? 0 : beg); i < n; i ++)
	if(!used[i]) {
		used[i] = true;
		rep(j, m) fo[id + 1][j] = fo[id][j] * 26 + d[i][j];
		rep(j, m) fr[id + 1][j] = fr[id][j] + d[i][j] * t;
		if(solve(id + 1, i, t * 26LL)) return true;
		used[i] = false;
	}
	return false;
}

