int h, w, od, B[MAX];
string S[MAX];
bool P[MAX][MAX];
vector <int> A;

int cnt(int mask)
{
	int res = 0;
	REP(i, MAX)
		if (mask & (1 << i))
			++res;
	return res;
}

void rec1(int unused, int r)
{
	if (r == (h >> 1))
	{
		od = -1;
		REP(i, h)
			if (unused & (1 << i))
				od = i;
		if (od > -1)
		{
			A.push_back(od);
			B[r++] = od;
		}
		REP(mask, 1 << w)
		{
			if (cnt(mask) != (w >> 1))
				continue;
			vector <int> C, D;
			REP(j, w)
				if (mask & (1 << j))
					C.push_back(j);
				else
					D.push_back(j);
			do
			{
				bool ok = true;
				if (w & 1)
				{
					REP(i, r)
						if (S[A[i]][D.back()] != S[B[i]][D.back()])
						{
							ok = false;
							break;
						}
				}
				if (!ok)
					continue;
				REP(i, w >> 1)
				{
					REP(j, r)
						if (S[A[j]][C[i]] != S[B[j]][D[i]] || S[A[j]][D[i]] != S[B[j]][C[i]])
						{
							ok = false;
							break;
						}
						if (!ok)
							break;
				}
				if (!ok)
					continue;
				cout << "YES";
				exit(0);
			} while(next_permutation(ALL(D)));
		}
		if (od > -1)
			A.pop_back();
		return;
	}
	REP(i, h)
		if ((unused & (1 << i)) && P[i][A[r]])
		{
			B[r] = i;
			rec1(unused ^ (1 << i), r + 1);
		}
}

