			C2[S[j][k] - 'a'][S[i][k] - 'a']++;
		}
		P[i][j] = T1 == T2;
		REP(k, 26)
			REP(l, 26)
			if (C1[k][l] != C2[k][l])
				P[i][j] = false;
	}
	REP(mask, 1 << h)
	{
