int main() {
  int H, W;
  while (cin >> H >> W) {
    vector<string> A(H);
    for (int i = 0; i < H; i++) {
      cin >> A[i];
    }
    vector<pair<int, int>> cur;
    vector<vector<pair<int, int>>> cands;
    function<void(int)> dfs = [&](int mask) {
      if (mask == 0) {
        cands.push_back(cur);
        return;
      }
      int a;
      for (int i = 0; i < W; i++) {
        if ((mask >> i) & 1) {
          a = i;
          break;
        }
      }
      for (int i = 0; i < W; i++) {
        if (i != a && ((mask >> i) & 1)) {
          cur.push_back(make_pair(a, i));
          dfs(mask ^ (1 << a) ^ (1 << i));
          cur.pop_back();
        }
      }
    };
    if (W % 2 == 0) {
      dfs((1 << W) - 1);
    } else {
      for (int i = 0; i < W; i++) {
        int size = cands.size();
        dfs(((1 << W) - 1) ^ (1 << i));
        for (int j = size; j < cands.size(); j++) {
          cands[j].push_back(make_pair(i, i));
        }
      }
    }
    bool res = false;
    for (auto &cand : cands) {
      map<string, int> mp;
      for (int i = 0; i < H; i++) {
        string s = A[i], t(W, '-');
        for (int j = 0; j < cand.size(); j++) {
          auto p = cand[j];
          t[j] = s[p.first];
          t[W - j - 1] = s[p.second];
        }
        ++mp[t];
      }
      bool ok = true;
      int oddPalindrome = 0;
      for (auto &e : mp) {
        string s = e.first;
        string t = string(s.rbegin(), s.rend());
        if (s != t) {
          ok &= mp[s] == mp[t];
        } else {
          if (mp[s] % 2 != 0) {
            ++oddPalindrome;
          }
        }
      }
      if (ok && oddPalindrome <= 1) {
        res = true;
        break;
      }
    }
    cout << (res ? "YES" : "NO") << endl;
  }
  return 0;
}

