typedef pair<int, int> ip;

bool ok(string& s, string& t) {
	int c[26] = { 0 };
	for (int i = 0; i < s.size(); i++) {
		c[s[i] - 'a']++;
		c[t[i] - 'a']--;
	}
	for (int i = 0; i < 26; i++) if (c[i]) return false;
	return true;
}

bool rev(string& s, string& t) {
	for (int i = 0; i < s.size(); i++) {
		if (s[i] != t[s.size() - 1 - i]) return false;
	}
	return true;
}

string a[12];
int h, w;
bool pick[12];
string t[12];

bool pos(vector<ip>& v) {
	int cur = 0;
	for (int i = 0; i < v.size(); i++) {
		if (v[i].first == v[i].second) {
			t[h / 2] = a[v[i].first];
		}
		else {
			t[cur] = a[v[i].first];
			t[h - 1 - cur] = a[v[i].second];
			cur++;
		}
	}
	vector<string> p;
	for (int j = 0; j < w; j++) {
		string s = "";
		for (int i = 0; i < h; i++)
			s += t[i][j];
		p.push_back(s);
	}
	bool fin[12] = { false };
	if (w % 2) {
		for (int i = 0; i < p.size(); i++) if (rev(p[i], p[i])) {
			memset(fin, 0, sizeof(fin));
			fin[i] = true;
			int rem = p.size() - 1;
			bool ok = true;
			while (rem) {
				bool chg = false;
				for (int i = 0; i < p.size(); i++) if (!fin[i]) {
					bool found = false;
					for (int j = i + 1; j < p.size(); j++) if (!fin[j] && rev(p[i], p[j])) {
						fin[i] = fin[j] = true;
						found = true;
						break;
					}
					if (!found) break;
					else {
						chg = true; rem -= 2;
					}
				}
				if (!chg) break;
			}
			if (!rem) return true;
		}
		return false;
	}
	else {
		int rem = p.size();
		while (rem) {
			for (int i = 0; i < p.size(); i++) if (!fin[i]) {
				bool found = false;
				for (int j = i + 1; j < p.size(); j++) if (!fin[j] && rev(p[i], p[j])) {
					fin[i] = fin[j] = true;
					found = true;
					rem -= 2;
					break;
				}
				if (!found) return false;
			}
		}
		return true;
	}
}

bool dfs(vector<ip>& v) {
	if (v.size() == (h + 1) / 2) {
		return pos(v);
	}
	for (int i = 0; i < h; i++) if (!pick[i]) {
		for (int j = i + 1; j < h; j++) if (!pick[j] && ok(a[i], a[j])) {
			v.push_back(ip(i, j));
			pick[i] = pick[j] = true;
			if (dfs(v)) return true;
			pick[i] = pick[j] = false;
			v.pop_back();
		}
		break;
	}
	return false;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cin >> h >> w;
	for (int i = 0; i < h; i++)
		cin >> a[i];
	vector<ip> v;
	if (h % 2) {
		for (int i = 0; i < h; i++) {
			v.push_back(ip(i, i));
			pick[i] = true;
			if (dfs(v)) {
				cout << "YES\n";
				return 0;
			}
			pick[i] = false;
			v.pop_back();
		}
		cout << "NO\n";
	}
	else {
		if (dfs(v)) cout << "YES\n";
		else cout << "NO\n";
	}
	return 0;
}

