			state[index] = i;

			fori(j, i + 1, m) {
				if(!used[j]) {
					used[j] = true;
					state[m - index - 1] = j;

					gen(index + 1);

					used[j] = false;
				}
			}

			used[i] = false;

			break;
		}
	}
}

