bool calc(vector<string> const &chars, vector<vector<int>> const &hgv, vector<vector<int>> const &wgv) {
    // cerr << "hgv: "; print(hgv);
    // cerr << "wgv: "; print(wgv);
    for (size_t hs = 0; hs < hgv.size(); hs++) {
        for (size_t ws = 0; ws < wgv.size(); ws++) {
            assert(hgv[hs].size() == 2);
            assert(wgv[ws].size() == 2);
            int y1 = hgv[hs][0];
            int x1 = wgv[ws][0];
            int y2 = hgv[hs][1];
            int x2 = wgv[ws][1];
            if (chars[y1][x1] != chars[y2][x2] || chars[y2][x1] != chars[y1][x2]) return false;
        }
    }
    return true;
}

pair<vector<vector<int>>,int> organize(vector<map<char, int>> const &cnt, int upto) {
    vector<int> gs(upto, -1);
    int g = 0;
    for (int i = 0; i < upto; i++) {
        bool exists = false;
        if (gs[i] != -1) continue;
        for (int j = i+1; j < upto; j++) {
            if (gs[j] != -1) continue;
            if (cnt[i] == cnt[j]) {
                exists = true;
                gs[i] = gs[j] = g;
            }
        }
        if (exists) g++;
    }

    vector<vector<int>> gv(g);
    for (int i = 0; i < upto; i++) {
        if (gs[i] != -1) gv[gs[i]].push_back(i);
    }

    auto odd_p = [](auto const &x){ return x.size() & 1; };
    if (count_if(gv.begin(), gv.end(), odd_p) > 1 || count(gs.begin(), gs.end(), -1) > 1)
        return make_pair(gv, -1);

    return make_pair(gv, g);
}

class groupings_generator {
    private:
        vector<vector<int>> base;
        vector<string> lines;
        vector<vector<int>> curr;

        function<bool(int, int)> cmp = [=](int l, int r) {
            return lines[l] < lines[r];
        };

        void calc_curr() {
            curr.clear();
            for (auto const &x: base) {
                if (x.size() == 2) {
                    curr.push_back(x);
                } else {
                    for (size_t i = 0; i < x.size()/2; i++) {
                        curr.emplace_back();
                        curr.back().push_back(x[i*2]);
                        curr.back().push_back(x[i*2+1]);
                    }
                }
            }
        }

    public:
        groupings_generator(vector<string> const &lines, vector<vector<int>> const &orig) : base(orig), lines(lines) {
            for (auto &x: base) sort(x.begin(), x.end(), cmp);
            calc_curr();
        }

        vector<vector<int>> const &get_curr() { return curr; }

        bool gen_next() {
            bool flag = false;
            for (int i = base.size()-1; i >= 0; i--) {
                auto &x = base[i];
                if (next_permutation(x.begin(), x.end(), cmp)) {
                    flag = true;
                    break;
                }
            }
            calc_curr();
            return flag;
        }
};

int main() {
    int h, w;
    cin >> h >> w;
    vector<string> rows(h);
    for (int i = 0; i < h; i++) {
        cin >> rows[i];
    }

    vector<string> cols(w);
    for (int i = 0; i < w; i++) {
        cols[i].reserve(h);
        for (int j = 0; j < h; j++) {
            cols[i].push_back(rows[j][i]);
        }
    }

    vector<map<char,int>> cnth(h);
    vector<map<char,int>> cntw(w);
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            cnth[i][rows[i][j]]++;
            cntw[j][rows[i][j]]++;
        }
    }

    int hgc, wgc;
    vector<vector<int>> hgv, wgv;
    tie(hgv, hgc) = organize(cnth, h);
    tie(wgv, wgc) = organize(cntw, w);
    if (hgc == -1 || wgc == -1) { cout << "NO" << endl; return 0; }
    // cerr << "raw_hgv: "; print(hgv);
    // cerr << "raw_wgv: "; print(wgv);

    groupings_generator hgen(rows, hgv);
    groupings_generator wgen(cols, wgv);
    do {
        do {
            auto const &hgv = hgen.get_curr();
            auto const &wgv = wgen.get_curr();

            if (calc(rows, hgv, wgv)) {
                cout << "YES" << endl;
                return 0;
