bool solve(vector<string>&masu,int mita){
	int H=masu.size();
	if(H==mita){
		int W=masu[0].size();
		int i,j,k;
		vector<bool>used(W);
		int chu=-1;
		if(W%2==0){chu=0;}
		for(j=0;j<W;j++){
			if(used[j]){continue;}
			bool bbb=false;
			for(k=j+1;k<W;k++){
				if(used[k]){continue;}
				bool ok=1;
				for(i=0;i<H;i++){
					if(masu[i][j]!=masu[i^1][k]){ok=0;break;}
				}
				if(ok){bbb=true;used[j]=1;used[k]=1;break;}
			}
			if(!bbb){
				if(chu!=-1){return false;}
				for(i=0;i<H;i++){
					if(masu[i][j]!=masu[i^1][j]){return false;}
				}
				chu=j;
			}
		}
		return true;
	}else{
		if(solve(masu,mita+2)){return true;}
		for(int i=mita+2;i<H;i++){
			swap(masu[mita+1],masu[i]);
			if(solve(masu,mita+2)){return true;}
			swap(masu[mita+1],masu[i]);
		}
	}
	return false;
}
int main(void){
	int H,W,i,j;cin>>H>>W;
	vector<string>masu(H);
	for(i=0;i<H;i++){cin>>masu[i];}
	//ペアを設定全探索
	bool can=false;
	if(H%2==1){
		for(i=0;i<H;i++){
			auto aaa=masu;
			aaa.pub(masu[i]);
			if(solve(aaa,0)){can=true;break;}
		}
	}else{
		can=solve(masu,0);
	}
	cout<<(can?"YES":"NO")<<endl;
	return 0;
}

