void bf(int at)
{
	if (at == r/2)
	{
		if (r&1) for (int i = 0;i < r;i++) if (!done[i])
		{
			perm[at] = i;
			break;
		}
		for (int i = 0;i < c;i++) ya[i] = false;
		for (int i = 0;i < c;i++) if (!ya[i]) for (int j = i+1;j < c;j++) if (!ya[j])
		{
			bool yes = true;
			for (int k = 0;k < r;k++) if (buf[perm[k]][i] != buf[perm[r-k-1]][j])
			{
				yes = false;
				break;
			}
			if (yes)
			{
				ya[i] = ya[j] = true;
				break;
			}
		}
		bool has = false;
		for (int i = 0;i < c;i++) if (!ya[i])
		{
			if (has) return;
			for (int j = 0;j < r;j++) if (buf[perm[j]][i] != buf[perm[r-j-1]][i]) return;
			has = true;
		}
		printf("YES\n");
		exit(0);
	}
	for (int i = at;i < r;i++) if (!done[i])
	{
		done[i] = true;
		perm[at] = i;
		for (int j = i+1;j < r;j++) if (!done[j] && ok[i][j])
		{
			done[j] = true;
			perm[r-at-1] = j;
			bf(at+1);
			done[j] = false;
		}
		done[i] = false;
		break;
	}
}

