void dfs(vector<int> dat, int sz){
  if(sz==(h+1)/2) {
    perm.push_back(dat);
    return;
  }
  if(sz==0&&h%2==1){
    for(int i=0;i<h;i++){
      vector<int> tmp = dat;
      tmp[i] = h/2;
      dfs(tmp, sz+1);
    }
  }else{
    int f = -1;
    for(int i=0;i<h;i++){
      if(dat[i]==-1){
        f = i;
        break;
      }
    }
    for(int i=f+1;i<h;i++){
      if(dat[i]!=-1) continue;
      vector<int> tmp = dat;
      tmp[f] = tmp[i] = (sz - h%2);
      dfs(tmp, sz+1);
    }
  }
}
