    int W = S[0].size();
    vector<vector<int>> T(H, vector<int>(W));
    for(int i=0; i<H; i++)
        for(int j=0; j<W; j++)
            T[i][j] = S[perm[i]][j] - 'a';

    //for(int i=0; i<H; i++){
    //    for(int j=0; j<W; j++){
    //        cerr << char('a'+T[i][j]) << " ";
    //    }
    //    cerr << endl;
    //}

    vector<bool> used(W, false);
    for(int i=0; i<W; i++){
        for(int j=i+1; j<W; j++){
            if(used[j]) continue;
            bool ok = true;
            for(int k=0; k<H; k++){
                if(T[k][i] != T[H-1-k][j]){
                    ok = false;
                    break;
                }
            }
            if(ok){
                used[i] = true;
                used[j] = true;
                break;
            }
        }
    }
    int cnt = 0;
    for(int i=0; i<W; i++)
        if(used[i])
            cnt++;

    cnt = W - cnt;

    if(cnt == 0) return true;
    if(cnt > 1) return false;
    int idx = 0;
    for(int i=0; i<W; i++)
        if(!used[i])
            idx = i;
    for(int i=0; i<H; i++)
        if(T[i][idx] != T[H-1-i][idx])
            return false;
    return true;
}



int main(){
    int H, W;
    cin >> H >> W;
    vector<string> S(H);
    for(int i=0; i<H; i++) cin >> S[i];

    for(int i=0; i<(1<<H); i++){
        if(__builtin_popcount(i) != (H+1)/2) continue;
        vector<string> T;
        for(int j=0; j<H; j++)
            if(i & (1<<j))
                T.push_back(S[j]);
        for(int j=0; j<H; j++)
            if(!(i & (1<<j)))
                T.push_back(S[j]);

        vector<int> perm;
        for(int i=0; i<H; i++)
            perm.push_back(i);
        do{
            if(solve(T, perm)){
                cout << "YES" << endl;
                return 0;
            }
        }while(next_permutation(perm.begin(), perm.begin()+(H+1)/2));
    }
    cout << "NO" << endl;
    return 0;
}

#include <cstdio>
#include <map>
using namespace std;
typedef unsigned long long ULL;
const int N=15;
const ULL B=133333;
int n,m;
char str[N][N];
bool isPld[N];
inline int abs(int x){
	return x>=0?x:-x;
}
void readData(){
	scanf("%d%d",&n,&m);
	for(int i=1;i<=n;i++)
		scanf("%s",str[i]+1);
}
void initPld(){
	for(int i=1;i<=n;i++){
		isPld[i]=true;
		for(int l=1,r=m;l<r;l++,r--)
			if(str[i][l]!=str[i][r]){
				isPld[i]=false;
				break;
			}
	}
}
bool use[N];
int match[N];
bool check(){
	if(n&1){
		for(int i=1;i<=n;i++)
			if(!use[i]){
				if(!isPld[i])
					return false;
				break;
			}
	}
	static char a[N][N];
	int h=n>>1<<1,p=0;
	for(int i=1;i<=n;i++)
		if(use[i]&&i<match[i]){
			p++;
			for(int j=1;j<=m;j++){
				a[p][j]=str[i][j];
				a[h-p+1][j]=str[match[i]][j];
			}
		}
	static map<ULL,int> sum;
	static ULL f[N],b[N];
	sum.clear();
	for(int j=1;j<=m;j++){
		f[j]=b[j]=0;
		for(int i=1;i<=h;i++)
			f[j]=f[j]*B+(a[i][j]-'a'+1);
		for(int i=h;i>=1;i--)
			b[j]=b[j]*B+(a[i][j]-'a'+1);
		sum[f[j]]++;
	}
	bool useChance=(m&1)?false:true;
	for(int j=1;j<=m;j++)
		if(sum[f[j]]){
			if(f[j]==b[j]){
				int x=sum[f[j]];
				if(x&1){
					if(!useChance)
						useChance=true;
					else
						return false;
				}
				continue;
			}
			int delta=abs(sum[f[j]]-sum[b[j]]);
			if(delta==1){
				if(!useChance)
					useChance=true;
				else
					return false;
			}
			else if(delta>1)
				return false;
			sum[f[j]]=sum[b[j]]=0;
		}
	return true;
}
bool solve(int x,bool useIdle){
	if(x==n+1)
		return check();
	if(use[x]){
		if(solve(x+1,useIdle))
			return true;
		return false;
	}
	if(!useIdle){
		use[x]=false;
		if(solve(x+1,true))
			return true;
	}
	for(int i=x+1;i<=n;i++)
		if(!use[i]){
			match[x]=i;
			match[i]=x;
			use[x]=use[i]=true;
			if(solve(x+1,useIdle))
				return true;
			use[x]=use[i]=false;
		}
	return false;
}
int main(){
	readData();
	initPld();
	puts(solve(1,(n&1)?false:true)?"YES":"NO");
	return 0;
}

