int h, w, ar[15];
bool used[15], ev;
char s[12][12];

inline bool isRev(char a[], char b[]) {
	for (int i = 0; i < h; i++)if (a[i] != b[h - 1 - i])return false;
	return true;
}

bool dfs(int p, int n, int e) {
	if (e) {
		for (int i = 0; i < h; i++) {
			used[i] = true; ar[h / 2] = i;
			if (dfs(0, 0, 0))return true;
			used[i] = false;
		}
		return false;
	}
	else if (n != h / 2) {
		while (used[p])p++;
		for (int i = p + 1; i < h; i++)if (!used[i]) {
			used[i] = true;
			ar[n] = p; ar[h - 1 - n] = i;
			if (dfs(p + 1, n + 1, 0))return true;
			used[i] = false;
		}
		return false;
	}
	else {
		char tmp[15][15];
		bool u[15], ev = !(w % 2);
		for (int i = 0; i < w; i++)for (int j = 0; j < h; j++)tmp[i][j] = s[ar[j]][i];
		for (int i = 0; i < w; i++) for (int j = i + 1; j < w && !u[i]; j++) {
			u[i] = u[j] = isRev(tmp[i], tmp[j]);
			if (!u[i] && !ev)u[i] = ev = isRev(tmp[i], tmp[i]);
			if (!u[i])return false;

		}
		return true;
	}
}

