		string t1 = s[i];
		sort(t1.begin(), t1.end());
		bool ok = false;
		for (int j = i+1; j < h; j ++) {
			if (vis[j]) continue; 
			string t2 = s[j];
			sort(t2.begin(), t2.end());
			if (t1 == t2) {
				r_idx[idx++] = i;
				r_pair[i] = j;
				ok = vis[i] = vis[j] = 1; break;
			}
		}
		if (!ok) { flag ++; single = i; }
	}
	if (flag > 1 || flag == 1 && h%2 == 0) {
		cout << "NO\n"; return 0;
	} else r_idx[idx++] = single;

