	idx = flag = 0; single = -1;
	for (int i = 0; i < w; i ++) {
		if (vis[i]) continue;
		string t1 = "";
		for (int j = 0; j < h; j ++) t1 += s[j][i];
		sort(t1.begin(), t1.end());
		bool ok = false;
		for (int j = i+1; j < w; j ++) {
