#define rep2(i,m,n) for(int i=m;i<(n);i++)
#define ALL(c) (c).begin(),(c).end()
#define dump(x) cout << #x << " = " << (x) << endl

const int MN = 12;

int H, W;
string s[MN];

int mt[MN];
string t[MN];

bool check() {
	vi us(H);
	int now = 0;

	rep(i, H) {
		if (!us[i]) {
			if (mt[i] != -1) {
				t[now] = s[i];
				t[H-1-now] = s[mt[i]];
				us[i] = us[mt[i]] = 1;
				now++;
			} else {
				t[H/2] = s[i];
			}
		}
	}

	vi us_col(W);
	vector<string> vec(W);

	rep(j, W) {
		string cur;
		rep(i, H) cur.pb(t[i][j]);
		vec[j] = cur;
	}

	int sol = 0;

	rep(j, W) {
		if (!us_col[j]) {
			bool fd = false;
			int p = -1;
			string rev = vec[j];
			reverse(ALL(rev));

			for (int j2 = j + 1; j2 < W; ++j2) {
				if (!us_col[j2] && vec[j2] == rev) {
					fd = true;
					p = j2;
				}
			}
			if (fd) {
				us_col[j] = us_col[p] = true;
			} else if (W % 2 == 0) {
				return false;
			} else {
				if (rev != vec[j]) {
					return false;
				}
				us_col[j] = true;
				++sol;
			}
		}
	}
	return sol <= 1;
}

bool dfs(int p) {
	if (p == H) {
		int cnt = 0;
		rep(i, H) if (mt[i] == -1) {
			++cnt;
		}
		if (cnt <= 1) {
			return check();
		}
		return false;
	}

	if (mt[p] != -1) {
		return dfs(p + 1);
	}

	int cfree = 0;
	rep(i, p) {
		if (mt[i] == -1) {
			++cfree;
		}
	}
	if (H % 2 == 1 && cfree == 0) {
		if (dfs(p + 1)) {
			return true;
		}
	}

	for (int i = p + 1; i < H; ++i) {
		if (mt[i] == -1) {
			mt[p] = i;
			mt[i] = p;
			if (dfs(p + 1)) {
				return true;
			}
			mt[i] = mt[p] = -1;
		}
	}
	return false;
}

int main() {
	cin >> H >> W;
	rep(i, H) cin >> s[i];
	memset(mt, -1, sizeof(mt));

	bool res = dfs(0);
	puts(res ? "YES" : "NO");

	return 0;
}

