using namespace std;
int match[13];
bool used[13];
int seq[13]; 
int n,m;
string s[13];
void solve(int x)
{
	if(x>m)
	{
		map<string,int>mp;
		for(int i=1;i<=m;i++)used[i]=false;
		int k=1;
		for(int i=1;i<=m/2;i++)
		{
			while(used[k] || match[k]==k)k++;
		    used[k]=used[match[k]]=true;
		    seq[i]=k;
		    seq[m+1-i]=match[k];
		}
		for(int i=1;i<=n;i++)
		{
			string t="";
			for(int j=1;j<=m;j++)t+=s[i][seq[j]-1];
			mp[t]++;
		}
		int mark=0;
		for(int i=1;i<=n;i++)
		{
			string t1="",t2="";
			for(int j=1;j<=m;j++)t1+=s[i][seq[j]-1];
			for(int j=m;j>=1;j--)t2+=s[i][seq[j]-1];
			if(!mp[t2])
			{
				if(m&1)
				{
					if(mark)return;
					if(t1!=t2)return;
					mark=i;
				}
				else return;
			}
			else mp[t2]--;
		}
		printf("YES");
		exit(0);
	}
	if(match[x])
	{
		solve(x+1);
		return;
	}
	for(int i=x+1;i<=m;i++)
	{
		if(!match[i])
		{
			match[i]=x;
			match[x]=i;
			solve(x+1);
			match[i]=0;
			match[x]=0;
		}
	}
} 
int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);
	cin>>n>>m;
	for(int i=1;i<=n;i++)cin>>s[i];
	if(m&1)
	{
		for(int i=1;i<=m;i++)
		{
			seq[(m+1)/2]=i;
			match[i]=i;
			solve(1);
			match[i]=0;
		}
	}
	else
	{
		solve(1);
	}
	printf("NO");
	return 0;
}

