bool f(vs&S,int b,deque<int>&d){
	int H=S.size(),W=S[0].size();
	if(!b){
		int u=(1<<W)-1;
		fr(i,W)if(u>>i&1){
			foor(j,i+1,W-1)if(u>>j&1){
				bool x=true;
				fr(k,d.size()){
					x&=S[d[k]][i]==S[d[H-1-k]][j];
				}
				if(x){
					u^=1<<i^1<<j;
					break;
				}
			}
		}
		if(W%2){
			if(u&u-1){
				return false;
			}else{
				bool z=true;
				fr(i,W)if(u>>i&1){
					fr(j,d.size()){
						z&=S[d[j]][i]==S[d[H-1-j]][i];
					}
				}
				return z;
			}
		}else{
			return!u;
		}
	}
	bool z=false;
	fr(i,H)if(b>>i&1){
		d.push_front(i);
		foor(j,i+1,H-1)if(b>>j&1){
			d.push_back(j);
			z|=f(S,b^1<<i^1<<j,d);
			d.pop_back();
		}
		d.pop_front();
		break;
	}
	return z;
}

