inline bool dfscol(int i,int mask)
{
	if(i==-1) return 1;

	int u=col-1-i;
	if(u==i)
	{
		rep(j,col) if(dfscol(i-1,mask|(1<<j))) return 1;
	}
	else
	{
		int t=0;
		while(mask&(1<<t)) t++;
		mask|=1<<t;

		rep(j,col) if((mask&(1<<j))==0&&g[t][j]) if(dfscol(i-1,mask|(1<<j))) return 1;
	}

	return 0;
}

inline bool dfsrow(int i,int mask)
{
	if(i==-1)
	{
		rep(i,col) rep(j,col)
		{
			bool f=1;
			rep(k,row) if(s[a[k]][i]!=s[a[row-1-k]][j])
			{
				f=0;
				break;
			}

			g[i][j]=f;
		}
		return dfscol((col-1)/2,0);
	}

	int u=row-1-i;
	if(u==i)
	{
		rep(j,row)
		{
			a[i]=j;
			if(dfsrow(i-1,mask|(1<<j))) return 1;
		}
	}
	else
	{
		int t=0;
		while(mask&(1<<t)) t++;
		a[i]=t;
		mask|=1<<t;

		rep(j,row) if((mask&(1<<j))==0&&gr[t][j])
		{
			a[u]=j;
			if(dfsrow(i-1,mask|(1<<j))) return 1;
		}
	}

	return 0;
}

