#include <bits/stdc++.h>
using namespace std;

char s[15][15];
int cntn[15][30],cntm[15][30],cnt[30],row[15],col[15];
int n,m,loc;
bool visr[15],visc[15],f;
bool check_row[15][15],check_col[15][15];

bool AC_check()
{
    for(int i=1;i<=n;i++) for(int j=1;j<=m;j++){
        if(s[i][j]!=s[row[i]][col[j]]) return false;
    }
    return true;
}

bool check_mirror(int c1,int c2)
{
	for(int i=1;i<=n;i++){
		if(s[i][c1]!=s[row[i]][c2]) return false;
	}
	return true;
}

bool dfs_col(int lvl)
{
	if(lvl==m-1&&m%2==1){
	    for(int i=1;i<=m;i++) if(!visc[i]){
	        loc=i;break;
		}
		col[loc]=loc;
		if(!check_mirror(loc,loc)) return false;
	    if(!AC_check()) return false;
	    return true;
	}
	if(lvl==m){if(!AC_check()) return false;return true;}
	for(int i=1;i<=m;i++) if(!visc[i]){
		loc=i;visc[i]=true;break;
	}
	for(int i=1;i<=m;i++) if(!visc[i]&&check_col[i][loc]&&check_mirror(i,loc)){
		col[i]=loc;col[loc]=i;visc[i]=true;
		if(dfs_col(lvl+2)) return true;
		visc[i]=false;
	}
	visc[loc]=false;
	return false;
}

bool dfs_row(int lvl)
{
	if(lvl==n-1&&n%2==1){
		for(int i=1;i<=n;i++) if(!visr[i]){
		    row[i]=i;visr[i]=true;loc=i;break;
	    }
	    if(dfs_col(0)) return true;
	    visr[loc]=false;
	    return false;
	}
	if(lvl==n){if(dfs_col(0)) return true;return false;}
	for(int i=1;i<=n;i++) if(!visr[i]){
		loc=i;visr[i]=true;break;
	} 
	for(int i=1;i<=n;i++) if(!visr[i]&&check_row[i][loc]){
		row[i]=loc;row[loc]=i;visr[i]=true;
		if(dfs_row(lvl+2)) return true;
		visr[i]=false;
	}
	visr[loc]=false;
	return false;
}

bool init()
{
	cin>>n>>m;
	for(int i=1;i<=n;i++){
		for(int j=1;j<=m;j++){
			cin>>s[i][j];
			cnt[s[i][j]-'a'+1]++;
			cntn[i][s[i][j]-'a'+1]++,cntm[j][s[i][j]-'a'+1]++;
		}
	}
	int res=0;
	for(int i=1;i<=26;i++) if(cnt[i]%2!=0) res++;
	if(res>=1&&(n*m)%2==0) return false;
    if(res>=2&&(n*m)%2==1) return false;
	for(int i=1;i<n;i++){
		for(int j=i+1;j<=n;j++){
		    f=false;
			for(int k=1;k<=26;k++){
				if(cntn[i][k]!=cntn[j][k]){
					f=true;break;
				}
			}
			if(!f){
			    check_row[i][j]=true;
			    check_row[j][i]=true;
		    }
		}
	}
	for(int i=1;i<m;i++){
		for(int j=i+1;j<=m;j++){
		    f=false;
			for(int k=1;k<=26;k++){
				if(cntm[i][k]!=cntm[j][k]){
					f=true;break;
				}
			}
			if(!f){
			    check_col[i][j]=true;
			    check_col[j][i]=true;
		    }
		}
	}
    return true;
}

