map<string, int> cnt;

bool isPalindrome(string s) {
	map<char, int> countFreq;
	for (auto c: s) {
		if (countFreq.count(c)) countFreq[c] += 1;
		else countFreq[c] = 1;
	}
	int cntOdd = 0;
	for (auto keyValue: countFreq) {
		if (keyValue.se % 2 != 0) ++cntOdd;
	}
	return cntOdd <= 1;
}

