    for (int i = 0; i < h; i++)
        cin >> a[i];
    map<pair<pair<long long, long long>, char>, int> q;
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            long long vert = 0, hor = 0;
            string z, x;
            for (int k = 0; k < h; k++)
                z += a[k][j];
            for (int k = 0; k < w; k++)
                x += a[i][k];
            sort(z.begin(), z.end());
            sort(x.begin(), x.end());
            for (int k = 0; k < h; k++)
                vert = (vert * p + z[k]) % base;
            for (int k = 0; k < w; k++)
                hor = (hor * p + x[k]) % base;
            q[make_pair(make_pair(vert, hor), a[i][j])]++;
        }
    }
    int ans = 0;
    for (auto x : q) {
        if (x.second % 2) {
            ans++;
        }
    }
    if (h == 1 || w == 1) {
        if (ans <= 1) {
            cout << "YES" << endl;
        } else
            cout << "NO" << endl;
    } else {
        if (h == w) {
            if (ans <= h)
                cout << "YES" << endl;
            else
                cout << "NO" << endl;
        } else {
            if (ans)
