bool check()
{
  memset(used, 0, sizeof(used));
  for(int y = 0; y < H; y++) {
    if(used[y]) {
      continue;
    }
    for(int y2 = y+1; y2 < H; y2++) {
      bool flag = true;
      for(int x = 0; x < W && flag; x++) {
        if(checkS[y][x] != checkS[y2][W-x-1]) {
          flag = false;
        }
      }
      if(flag) {
        used[y] = used[y2] = true;
      }
    }
  }

  int index = -1;
  for(int y = 0; y < H; y++) {
    if(!used[y]) {
      if(index == -1) {
        index = y;
      } else {
        return false;
      }
    }
  }

  if(index == -1) {
    return true;
  } else {
    bool flag = true;
    for(int x = 0; x < W && flag; x++) {
      if(checkS[index][x] != checkS[index][W-x-1]) {
        flag = false;
      }
    }
    return flag;
  }
}

bool pairUsed[MAX_W];
int soloIndex = -1;
using II = pair<int, int>;

vector<II> vec;
bool dfs(int pos = 0)
{
  if(pos == W) {
    for(int x = 0; x < W/2; x++) {
      for(int y = 0; y < H; y++) {
        checkS[y][x] = S[y][vec[x/2].first];
        checkS[y][W-1-x] = S[y][vec[x/2].second];
      }
    }
    if(W%2 == 1) {
      for(int y = 0; y < H; y++) {
        checkS[y][W/2 + 1] = S[y][soloIndex];
      }
    }
    return check();
  }

  if(!pairUsed[pos]) {
    pairUsed[pos] = true;
    for(int x = 0; x < W; x++) {
      if(x != soloIndex && !pairUsed[x]) {
        pairUsed[x] = true;
        vec.push_back(II(pos, x));
        if(dfs(pos+1)){
          return true;
        }
        pairUsed[x] = false;
        vec.pop_back();
      }
    }
    pairUsed[pos] = false;
    return false;
  } else {
    return dfs(pos+1);
  }
}

