                for(int i=0;i<h;i++){
                    if(s[i][j]!=s[h-1-i][k]){
                        isok=false;
                        break;
                    }
                }
                if(isok){
                    flag[j]=flag[k]=true;
                    break;
                }
            }
        }
        int cnt=count(flag.begin(),flag.end(),false);
        if(cnt>=2) return false;
        if(cnt==0) return true;
        for(int j=0;j<w;j++){
            if(!flag[j]){
                for(int i=0;i<h;i++){
                    if(s[i][j]!=s[h-1-i][j]) return false;
