bool is_symmetric(int x1, int x2, const vector<int> &perm)
{
    for (int y=0; y<H; y++) {
        assert(perm[y]>=0);
        if (grid[perm[y]][x1] != grid[perm[H-y-1]][x2]) return false;
    }
    return true;
}

bool match(const vector<int> &perm)
{
#ifdef DEBUG
    rep(i, H) cerr << perm[i] << " ";
    cerr << endl;
#endif

    int used = 0;
    bool allow_alone = W%2;
    for (int x1=0; x1<W; x1++) {
        if ((used>>x1) & 1) continue;
        bool matched = false;
        for (int x2=x1+1; x2<W; x2++) {
            if ((used>>x2) & 1) continue;

            if (is_symmetric(x1, x2, perm)) {
                used |= (1<<x1), used |= (1<<x2);
                matched = true;
                break;
            }
        }

        if (!matched && allow_alone) {
            if (is_symmetric(x1, x1, perm)) {
                used |= (1<<x1);
                allow_alone = false;
                matched = true;
            }
        }

        if (!matched) {
            return false;
        }
    }
    return true;

    // return match_dfs(0, 0, W%2, perm);
}

bool dfs(int y1, int used, vector<int> &perm)
{
    if (used == (1<<H) - 1) {
        cnt++;
        return match(perm);
    }

    if ((used>>y1) & 1) {
        return dfs(y1+1, used, perm);
    }

    used |= (1<<y1);
    perm[__builtin_popcount(used)/2] = y1;

    bool res = false;
    if (H%2 && __builtin_popcount(used) == H) {
        res = dfs(y1+1, used, perm);
    } else {
        for (int y2=y1+1; y2<H; y2++) {
            if ((used>>y2) & 1) continue; 
            used |= (1<<y2);
            perm[H - __builtin_popcount(used)/2] = y2;
            res  |= dfs(y1+1, used, perm);
            perm[H - __builtin_popcount(used)/2] = -1;
            used &= ~(1<<y2);
        }
    }

    perm[__builtin_popcount(used)/2] = -1;
    used &= ~(1<<y1);

    return res;
}

int main()
{
    ios::sync_with_stdio(false);

    cin >> H >> W;
    assert(H%2 == 0 && W%2 == 0);

    rep(i, H) {
        string S; cin >> S;
        grid.push_back(S);
    }

    vector<int> perm(H, -1);
    cout << (dfs(0, 0, perm) ? "YES" : "NO") << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<string> s(n);
    for(int i = 0; i < n; ++i) {
        cin >> s[i];
    }
    vector<vector<int>> cnt(n, vector<int>(26));
    for(int i = 0; i < n; ++i) {
        for(auto c : s[i]) {
            cnt[i][c - 'a'] += 1;
        }
    }

    bool ans = false;
    vector<int> p1(n, -1);
    function<bool(int)> dfs1 = [&](int depth) {
        if(ans) return true;
        if(depth == n / 2) {
            for(int i = 0; i < n; ++i) {
                if(cnt[i] != cnt[p1[i]]) return false;
            }

            int rest = -1;
            for(int i = 0; i < n; ++i) {
                if(p1[i] == -1) rest = i;
            }
            if(rest != -1) p1[rest] = rest;

            static vector<bool> dp(1 << m);
            fill(begin(dp), end(dp), false);
            queue<int> que;
            que.push(0);
            while(!que.empty()) {
                const int S = que.front();
                que.pop();
                for(int i = __builtin_popcount(S) / 2; i < m; ++i) {
                    if(S & (1 << i)) continue;
                    for(int j = i + 1; j < m; ++j) {
                        if(S & (1 << j)) continue;
                        bool ok = true;
                        for(int k = 0; k < n; ++k) {
                            int y1 = k, y2 = p1[k];
                            ok &= s[y1][i] == s[y2][j];
                        }
                        if(ok) {
                            que.push(S | (1 << i) | (1 << j));
                        }
                    }
                }
            }
            const int mask = (1 << m) - 1;
            bool res = dp[mask];
            if(m & 1) {
                for(int i = 0; i < m; ++i) {
                    if(dp[mask ^ (1 << i)]) {
                        bool check = true;
                        for(int j = 0; j < n; ++j) {
                            int y1 = j, y2 = p1[j];
                            check &= s[y1][i] == s[y2][i];
                        }
                        res |= check;
                    }
                }
            }
            if(rest != -1) p1[rest] = -1;
            return ans |= res;
        }

        bool res = false;
        for(int i = depth; i < n; ++i) {
            if(p1[i] != -1) continue;
            for(int j = i + 1; j < n; ++j) {
                if(p1[j] != -1) continue;
                p1[i] = j;
                p1[j] = i;
                res |= dfs1(depth + 1);
                p1[i] = p1[j] = -1;
            }
        }
        return res;
    };

    cout << (dfs1(0) ? "YES" : "NO") << endl;
}

