void solve(){
	vector<ll> rows;
	FOR(i,0,siz(v)-1) rows.eb(v[i].f);
	if(n&1) rows.eb(mid);
	DEC(i,siz(v)-1,0) rows.eb(v[i].s);
	FOR(i,0,m-1) cols[i].clear();
	FOR(i,0,m-1){
		for(auto j:rows) cols[i] += grid[j][i];
	}
	vector<bool> used(m-1, 0);
	bool mid_used = 0;
	FOR(i,0,m-1)if(!used[i]){
		reverse(all(cols[i]));
		ll match=-1;
		FOR(j,i+1,m-1){
			if(cols[i] == cols[j]) match=j;
		}
		if(match==-1 && (m&1) && !mid_used) {
			mid_used = 1;
		}else if(match==-1) return;
		else {
			used[i]=used[match]=1;
		}
	}
	ans=1;
	return;
}
ll zero(ll bm){
	return __builtin_ctz(~bm);
}
void gen_pairs(ll bm){
	if(__builtin_popcount(bm) == n) {
		solve();
		return;
	}
	ll o = bm;
	ll f_zero = zero(bm);
	bm ^= 1<<f_zero;
	for(ll pos=zero(bm); __builtin_popcount(bm) != n; bm ^= 1<<pos, pos = zero(bm)){
		v.eb(f_zero, pos);
		gen_pairs(o^(1<<f_zero)^(1<<pos));
		v.pop_back();	
	}
}
