    //cout << bit << endl;

    for (int i = 0; i < h; ++i) {
        if ((bit >> i) & 1) {
        continue;
        } else {
            for (int j = i + 1; j < h; ++j) {
                if ((bit >> j) & 1) continue;
                ord[depth] = map[i];
                ord[h - depth - 1] = map[j];
                bool ok = all_pair(bit | (1 << i) | (1 << j), depth+1);
                if (ok) return true;
            }
            break;
        }
    }

    return false;
}

int main() {
