    for (int i = 0; i < h; ++i) {
        cin >> map[i];
        ord.push_back("");
    }

    bool ans = false;
    if (h % 2 == 0) {
        ans = all_pair(0);
    } else {
        ans = true;
        for (int i = 0; i < h; ++i) {
            ord[h / 2] = map[i];
            ans &= all_pair(1 << i);
        }
    }
    cout << (ans ? "YES" : "NO") << endl;
}

