using namespace std;
struct HopcroftKarp{
    int n1, n2;
    vector<int> last, pre, head, matching, dist; queue<int> Q;
    vector<bool> used, vis, reachable1, reachable2;
    HopcroftKarp(int _n1, int _n2){
        n1 = _n1;
        n2 = _n2;
        last.assign(n1, -1);
        dist.resize(n1);
        vis.resize(n1);
    }
    void addEdge(int u, int v){
        head.push_back(v);
        pre.push_back(last[u]);
        last[u] = (int) head.size() - 1;
    }
    void bfs(){
        fill(dist.begin(), dist.end(), -1);
        for(int u = 0; u < n1; u++) if(!used[u]){
            Q.push(u); dist[u] = 0;
        }
        while(!Q.empty()){
            int u1 = Q.front(); Q.pop();
            for(int e = last[u1]; e >= 0; e = pre[e]){
                int u2 = matching[head[e]];
                if(u2 >= 0 and dist[u2] < 0){
                    dist[u2] = dist[u1] + 1;
                    Q.push(u2);
                }
            }
        }
    }
    bool dfs(int u1){
        vis[u1] = true;
        for(int e = last[u1]; e >= 0; e = pre[e]){
            int v = head[e], u2 = matching[v];
            if(u2 < 0 or (!vis[u2] and dist[u2] == dist[u1] + 1 and dfs(u2))){
                matching[v] = u1;
                used[u1] = true;
                return true;
            }
        }
        return false;
    }
    int maxMatching(){
        used.assign(n1, false);
        matching.assign(n2, -1);
        for(int res = 0;;){
            bfs();
            fill(vis.begin(), vis.end(), false);
            int f = 0;
            for(int u = 0; u < n1; u++){
                if(!used[u] and dfs(u)) f++;
            }
            if(!f) return res;
            res += f;
        }
    }
};
