  for (int i = 0; i < v.size(); ++i) {
    po[i] = v[i];
    reverse(v[i].begin(), v[i].end());
    po[i + v.size()] = v[i];
  }

  sort(po.begin(), po.end());

  for (int i = 0; i < po.size(); i += 2) {
    if (po[i] != po[i + 1]) return false;
  }

  return true;
}

bool dfs(int bit = 0) {
  if (check()) return true;

  for (int i = 0; i < w; ++i) {
    if (bit & (1 << i)) continue;
    for (int j = i + 1; j < w; ++j) {
      if (bit & (1 << j)) continue;
      idx.push_back(make_pair(i, j));
      if (dfs(bit | (1 << i) | (1 << j))) return true;
      idx.pop_back();
    }
  }

  return false;
}

