  }
  return t;
}

const int N = 19;

char s[N][N];
int p[N];

int main() {
  int n, m;
  scanf("%d %d", &n, &m);
  for (int i = 0; i < n; ++i) {
    scanf("%s", s[i]);
  }
  for (int mask = 0; mask < (1 << n); ++mask) {
    int cnt = 0;
    for (int i = 0; i < n; ++i) {
      if (mask >> i & 1) {
        ++cnt;
      }
    }
    if (cnt != (n + 1) / 2) {
      continue;
    }
    vector<int> a, b;
    for (int i = 0; i < n; ++i) {
      if (mask >> i & 1) {
        a.push_back(i);
      } else {
        b.push_back(i);
      }
    }
    for (int i = 0; i < (n + 1) / 2; ++i) {
      p[i] = i;
    }
    do {
      map<string, int> w;
      for (int j = 0; j < m; ++j) {
        string t = "";
        for (int i = 0; i < n / 2; ++i) {
          t += s[a[p[i]]][j];
          t += s[b[i]][j];
        }
        if (n % 2 == 1) {
          t += s[a[p[n / 2 + 1]]];
        }
        ++w[t];
      }
      bool ok = true;
      int odd = 0;
      for (auto &e : w) {
        string rt = rev(e.first);
        if (rt == e.first) {
          if (e.second % 2 == 1) {
            ++odd;
          }
        } else {
          if (w.count(rt) == 0 || w[rt] != e.second) {
            ok = false;
          }
        }
      }
      if (ok && odd == m % 2) {
        puts("YES");
        return 0;
      }
    } while (next_permutation(p, p + (n + 1) / 2));
  }
  puts("NO");
}

