					break;
				}
			}
			if (is_valid)
			{
				flg[y1] = true;
				flg[y2] = true;
				cnt += 2;
				break;
			}
		}
	}

	if (H % 2 == 1)
	{
		if (H - 1 != cnt)
		{
			return false;
		}

		int c;
		REP(y, H)
		{
