	int index = W - (n - half) - 1;
	int init = ary[n - half];
	for (int i = init; i < W; i++)
	{
		if (ary_flg[i]) continue;
		ary[index] = i;
		ary_flg[i] = true;
		comb2(n + 1);
		ary_flg[i] = false;
	}

}

