bool rev_same(string s, string t){
    if(s.length()!=t.length()) return false;
    for (int i = 0; i < (int)s.length(); i++)
    {
        if(s[i]!=t[s.length()-1-i]) return false;
    }
    return true;
}

bool is_column(vector<string> T){
    vector<string> R;
    for (int j = 0; j < W; j++)
    {
        string r = "";
        for (int i = 0; i < H; i++)
        {
            r += T[i][j];
        }
        R.push_back(r);
    }

    vector<bool> used(W,false);    
    int center = (W % 2) ? 0 : 1;

    for (int j = 0; j < W; j++)
    {
        if(used[j]) continue;
        used[j] = true;
        bool pair = false;
        for (int k = 0; k < W; k++)
        {
            if(used[k]) continue;
            if(rev_same(R[j], R[k])){
                used[k] = true;
                pair = true;
                break;
            }
        }
        if(!pair){
            if(rev_same(R[j],R[j]) && center==0){
                center = 1;
            }
            else{
                return false;
            }
        }
    }
    return true;
}

bool is_pair_row(string s, string t){
    sort(s.begin(),s.end());
    sort(t.begin(),t.end());
    return (s == t);
}

bool is_same_cnt(string s, string t){
    map<char, int> cnt_s, cnt_t;
    for (int i = 0; i < s.length(); i++) cnt_s[s[i]]++;
    for (int i = 0; i < t.length(); i++) cnt_t[t[i]]++;
    return (cnt_s==cnt_t);    
}

bool is_row_center(string s){
    map<char, int> cnt_s;
    int w = W % 2 ? 0 : 1;
    for (int i = 0; i < s.length(); i++) cnt_s[s[i]]++;
    for(auto [ch,cnt]:cnt_s){
        if(cnt % 2 && w) return false; 
        else if(cnt % 2) w = 1;
    }
    return true;
}

bool is_row_ok(vector<string> T){
    vector<bool> used(W,false);    
    int center = (H % 2) ? 0 : 1;

    for (int i = 0; i < H; i++)
    {
        if(used[i]) continue;
        used[i] = true;
        bool pair = false;
        for (int k = 0; k < H; k++)
        {
            if(used[k]) continue;
            if(is_same_cnt(T[i], T[k])){
                used[k] = true;
                pair = true;
                break;
            }
        }
        if(!pair){
            if(is_row_center(T[i]) && center==0){
                center = 1;
            }
            else{
                return false;
            }
        }
    }
    return true;
}

