bool solve(){

    // if(!is_row_ok(S)) return false;
    for (int bit = 1; bit < (1<<H); bit++)
    {
        if(__builtin_popcount(bit) != (H+1)/2) continue;
        vector<int> P,Q;
        for (int i = 0; i < H; i++)
        {
            if((bit>>i)&1) P.push_back(i);
            else Q.push_back(i);
        }
        do
        {
            vector<string> T = S;
            bool ispair = true;
            for (int i = 0; i < H/2; i++)
            {
                T[i] = S[P[i]];
                T[H-1-i] = S[Q[i]];
                if(!is_pair_row(T[i], T[H-1-i])){
                    ispair = false;
                    break;
                }
            }
            if(H % 2) {
                T[H/2] = P[H/2];
                if(!is_row_center(T[H/2])) ispair = false;
            }
            if(!ispair) continue;
            if(is_column(T)) return true;
        } while (next_permutation(P.begin(),P.end()));
    }
    return false;
}   

