void calc() {
	int NG = 0;

	rep(i, HN) rep(j, WN) {
		int a = HP[i].first;
		int b = HP[i].second;
		int c = WP[j].first;
		int d = WP[j].second;
		if (S[a][c] != S[b][d]) NG = 1;
		if (S[a][d] != S[b][c]) NG = 1;
	}

