		}
	}
	if (W % 2) {
		rep(i, HN) {
			int a = HP[i].first;
			int b = HP[i].second;
			if (S[a][areW] != S[b][areW]) NG = 1;
		}
	}
	if (NG == 0) OK = 1;
}

void SWP(int A) {
	if (A == -1) {
		rep(i, W) {
			areW = i;
			usedW[i] = 1;
			SWP(0);
			usedW[i] = 0;
		}
		return;
	}
	if (A == WN) {
		calc();
		return;
	}
	rep(i, W) if (usedW[i] == 0) {
		usedW[i] = 1;
		rep(j, W) {
			if (usedW[j] == 0) {
				usedW[j] = 1;
				WP[A] = mp(i, j);
				SWP(A + 1);
				usedW[j] = 0;
			}
		}
		usedW[i] = 0;
		return;
	}
}

