	if (A == -1) {
		rep(i, H) {
			areH = i;
			usedH[i] = 1;
			SHP(0);
			usedH[i] = 0;
		}
		return;
	}
	if (A == HN) {
		if (W % 2) SWP(-1);
		else SWP(0);
		return;
	}
	rep(i, H) if (usedH[i] == 0) {
		usedH[i] = 1;
