typedef pair<char, char> pcc;
Graph<char> g(12, vector<char>(12));

bool row(int h, int w) {
  Graph<int> det(h, vi(h, 0));

  rep(i,h) {
    map<char, int> self;
    rep(k,w) {
      self[g[i][k]] += 1<<k;
    }
    int idx = 0;
    for (auto &p : self) {
      if (__builtin_parity(p.second)) {
        if (idx) {
          idx = -1;
          break;
        }
        idx = p.second;
      }
    }
    if (idx != -1) det[i][i] = max(1, idx);

    rep(j,i) {
      map<pcc, int> comb;
      rep(k,w) {
        comb[{g[i][k], g[j][k]}] += 1<<k;
      }
      int idx = 0;
      for (auto &p : comb) {
        auto &q = p.first;
        if (q.first == q.second) {
          if (__builtin_parity(p.second)) {
            if (idx) {
              idx = -1;
              break;
            }
            idx = p.second;
          }
        } else {
          pcc r = {q.second, q.first};
          if (!comb.count(r) || __builtin_popcount(comb[r]) != __builtin_popcount(p.second)) {
            idx = -1;
            break;
          }
        }
      }
      if (idx != -1) det[i][j] = det[j][i] = max(1, idx);
    }
  }

  Graph<int> dp(h+1, vi(1<<h, 0));
  dp[0][0] = (1<<w)-1;
  rep(i,h) {
    rep(j,1<<i) {
      if (!dp[i][j]) continue;
      bitset<12> s(j);
      rep(k,i) {
        if (s[k] && det[i][k]) {
          dp[i+1][j-(1<<k)] = dp[i][j] & det[i][k];
        }
      }
      dp[i+1][j+(1<<i)] = dp[i][j];
    }
  }

  if (dp[h][0]) return true;

  rep(i,h) {
    if (dp[h][1<<i] & det[i][i]) return true;
  }

  return false;
}

bool column(int h, int w) {
  rep(i,12) rep(j,i) swap(g[i][j], g[j][i]);

  return row(w, h);
}

void solve() {
  int h, w; cin >> h >> w;
  rep(i,h) rep(j,w) cin >> g[i][j];

  CoutYN(row(h, w) && column(h, w), "YES", "NO");
}


