	REP(k, pa.size()){
		int32 f = pa[k].fs, t = pa[k].sc;
		REP(i, W){
			FOR(j, i, W){
				if (s[f][i] != s[t][j] || s[t][i] != s[f][j]) pack[i][j] = pack[j][i] = 0;
			}
		}
	}
	/*
	REP(i, pa.size()){
