        int num = start;
        for (int i = 0; i < H; i++) {
            if (!usedline[i]) {
                usedline[i] = true;
                for (int j = num; j < num + dblfact[rem - 2]; j++) {
                    lineperm[j][rem - 1] = i;
                }
                lineset(num, rem - 2);
                usedline[i] = false;
                num += dblfact[rem - 2];
            }
        }
        usedline[fir] = false;
    } else if (rem == 1) {
        for (int i = 0; i < H; i++) {
            if (!usedline[i]) {
