bool check(vector<string> s) {
  map<string, int> cnt;
  for (int i = 0; i < s.size(); ++i) {
    cnt[s[i]]++;
    reverse(s[i].begin(), s[i].end());
    cnt[s[i]]--;
  }
  for (auto &p : cnt) {
    if (p.second) return false;
  }

  return true;
}

bool solve(vector<string> &t, int q = 200000) {
  vector<string> s = t;
  vector<int> v(w);
  for (int i = 0; i < w; ++i) v[i] = i;
  while (q--) {
    if (check(s)) return true;
    shuffle(v.begin(), v.end(), ei);
    for (int i = 0; i < h; ++i) {
      for (int j = 0; j < w; ++j) {
        s[i][j] = t[i][v[j]];
      }
    }
  }

  return false;
}

