ll height, width;
string strs[15];


void check(const vector<int>& p_left, vector<int>& p_right) {

    if (int(p_right.size()) * 2 == width / 2 * 2)
        bye("YES");

    repeat(i, width) {
        bool h = false;
        for (auto e : p_left) h |= e == i;
        for (auto e : p_right) h |= e == i;
        if (h) continue;

        int idx = p_right.size();

        map<int, int> q;
        repeat(j, height) {
            q[strs[j][p_left[idx]]]++;
            q[strs[j][i]]--;
        }
        int mid = height % 2;
        bool fail = false;
        for (auto p : q) {
            int s = p.second;
            if (abs(s) > 1) fail = true;
            else if (abs(s) == 1) {
                if (mid) --mid;
                else fail = true;
            }
        }
        if (!fail) {
            p_right.push_back(i);
            check(p_left, p_right);
            p_right.pop_back();
        }
    }
}

void enum_perm(vector<int>& p) {

    if (p.size() == width / 2) {
        vector<int> t;
        check(p, t);
    }
    repeat(i, width) {
        bool h = false;
        for (auto e : p) h |= e == i;
        if (!h) {
            p.push_back(i);
            enum_perm(p);
            p.pop_back();
        }
    }
}

int main() {

