        map<char, int> b;
        for (auto c : strs[0]) b[c]++;
        int mid = (width % 2);
        for (auto p : b) {
            int s = p.second;
            if (s % 2) {
                if (mid) --mid;
                else bye("NO");
            }
        }
        bye("YES");
    }
    if (width == 1) {
        map<char, int> b;
        repeat(i, height) b[strs[i][0]]++;
        int mid = (height % 2);
        for (auto p : b) {
            int s = p.second;
            if (s % 2) {
                if (mid) --mid;
                else bye("NO");
            }
        }
        bye("YES");
    }

    vector<int> t;
    enum_perm(t);

    bye("NO");

    return 0;
}

