bool is_sym(string s) {
    map<char, int> cnt;
    for(auto ch: s) {
        ++cnt[ch];
    }
    int odd_num = 0;
    for (auto e: cnt) {
        if (e.second % 2) ++odd_num;
    }
    return odd_num <= 1;
}

char get_odd_char(string s) {
    map<char, int> cnt;
    for(auto ch: s) {
        ++cnt[ch];
    }
    for (auto e: cnt) {
        if (e.second % 2) return e.first;
    }
    return '0';
}

bool solve(int H, int W, vector<string>& cells) {
    if (H == 1 || W == 1) {
        string s = "";
        REP(h, H) REP(w, W) s += cells[h][w];
        return is_sym(s);
    }

    map<string, int> rows;
    for(auto s: cells) {
        sort(ALL(s));
        ++rows[s];
    }

    map<string, int> cols;
    REP(w, W) {
        string s = "";
        REP(h, H) {
            s += cells[h][w];
        }
        sort(ALL(s));
        ++cols[s];
    }

    int odd_r = 0;
    for(auto r: rows) {
        // cout << r.first << " " << r.second << endl;
        if (r.second % 2) ++odd_r;
    }
    // cout << endl;

    int odd_c = 0;
    for(auto c: cols) {
        // cout << c.first << " " << c.second << endl;
        if (c.second % 2) ++odd_c;
    }

    if (odd_r > 1 || odd_c > 1) {
        return false;
    }
    else {
        bool ok = true;

        char odd_char1 = '0';
        char odd_char2 = '0';

        for(auto r: rows) {
            if (r.second % 2) {
                if (!is_sym(r.first)) ok = false;
                odd_char1 = get_odd_char(r.first);
            }
        }
        for(auto c: cols) {
            if (c.second % 2) {
                if (!is_sym(c.first)) ok = false;
                odd_char2 = get_odd_char(c.first);
            }
        }

        if (H % 2 == 1 && W % 2 == 1) {
            if (odd_char1 != odd_char2) ok = false;
        }

        if (ok) return true;
        else return false;
    }
}

