	for(int x = 1; x <= w; x++){
		string s;
		for(int j = 0; j < vec.size(); j++) s += c[x][vec[j].first];
		for(int j = (int)vec.size()-1; j >= 0; j--) s += c[x][vec[j].second];
		S.insert(s);
	}
	bool flag = false;
	while(S.size()){
		string s = *S.begin();
		reverse(s.begin(), s.end());
		S.erase(S.begin());

		auto it = S.lower_bound(s);
		if(it != S.end() && *it == s) S.erase(it);
		else{
			if(flag) return false;
			if(!pal(s)) return false;
			flag = true;
		}
	}
	return true;
}

bool dfs()
{
	int u = 0;
	for(int y = 1; y <= h; y++){
		if(!used[y]){
			u = y;
			break;
		}
	}
	if(u == 0) return check();

	bool flag = false;
	for(int y = u+1; y <= h; y++){
		if(used[y]) continue;

		flag = true;
		used[u] = used[y] = true;
		vec.push_back(P(u, y));

