bool check(vector<int> perm) {
	int i, j;
	string t[12];
	rep(i, h) rep(j, w) t[i] += s[i][perm[j]];
	bool used[12] = {false};
	rep(i, h) {
		if (used[i]) continue;
		string tmp = reverse(t[i]);
		rep(j, h) if (j != i && !used[j] && tmp == t[j]) break;
		if (j < h) {
			used[i] = true; used[j] = true;
		}
	}

	int ngCnt = 0;
	rep(i, h) {
		if (used[i]) continue;
		if (h % 2 == 0) break;
		ngCnt++;
		if (ngCnt >= 2) break;
		if (reverse(t[i]) != t[i]) break;
	}
	return i == h;
}

//探索 (ICPC2017-Asia-Bと本質は同じ)
int kumi[8][2];	//対称な位置にある元のペア
bool dfs(int rem, int depth = 0) {
	int i, j;
	vector<int> perm;

	if (w - depth * 2 == 1) {	//バグがあります
		i = 0; while ((rem >> i) % 2 == 0) i++;
		perm.resize(w);
		for (j = 0; j < depth; j++) {
			perm[j] = kumi[j][0];
			perm[w - 1 - j] = kumi[j][1];
		}
		perm[(w - 1) / 2] = i;
		if (check(perm)) return true;
		return false;
	}
	if (w == depth * 2) {
		perm.resize(w);
		for (j = 0; j < depth; j++) {
			perm[j] = kumi[j][0];
			perm[w - 1 - j] = kumi[j][1];
		}
		if (check(perm)) return true;
		return false;
	}

	for (i = 0; i < w; i++) if ((rem >> i) & 1) break;
	for (j = i + 1; j < w; j++) {
		if ((rem >> j) & 1) {
			kumi[depth][0] = i;
			kumi[depth][1] = j;
			bool res = dfs(rem - (1 << i) - (1 << j), depth + 1);
			if (res) { return true; }
		}
	}
	return false;
}

