        reverse(all(rev));
        if(mp[rev])mp[rev]--;
        else mp[s[i]]++;
    }
    ll sum=0;
    for(auto &p:mp){
        if(!p.second)continue;
        sum+=p.second;
        string rev=p.first;
        reverse(all(rev));
        if(rev!=p.first)return;
    }
