bool palindrome(string s){
    string t = s;
    reverse(t.begin(), t.end());
    return s == t;
}

bool equal(string s, string t){
    reverse(t.begin(), t.end());
    return s == t;
}

bool match(vector<string> s, int n){
    vector<bool> used(n, 0);
    int odd = 0;
    for(int i = 0;i < n;i++){
        if(used[i])
            continue;
        for(int j = 0;j < n;j++){
            if(used[j] or (j == i))
                continue;
            if(equal(s[i], s[j])){
                used[i] = 1;
                used[j] = 1;
                break;
            }
        }
        if(!used[i]){
           if((n & 1) and odd == 0){
               if(palindrome(s[i])){
                   odd++;
                   used[i] = 1;
               }else{
                    return false;
               }
           }else{
               return false;
           } 
        }
    }
    return true;
}

