vector<int> modify(vector<int> p){
    vector<int> odd, even;
    if(p.size() & 1){
        for(int i = 2;i < p.size();i += 2){
            even.push_back(p[i]);
        }
        even.push_back(p[0]);
    }
    else{
        for(int i = 0;i < p.size();i += 2){
            even.push_back(p[i]);
        }
    }
    for(int i = 1;i < p.size();i += 2){
        odd.push_back(p[i]);
    }
    reverse(odd.begin(), odd.end());
    for(auto v : odd){
        even.push_back(v);
    }
    return even;
}

bool dfs(int id, vector<int> p){
    if(id == (W + 1) / 2 + 1){
        p = modify(p);
        //print(p); 
        vector<string> str = my_shuffle(p);
        return match(str, H);
    }
    if(id == 1 and (W & 1)){
        bool res = false;
        for(int i = 0;i < W;i++){
            res |= dfs(id + 1, {i});
        }
        return res;
    }
    int first;
    for(int i = 0;i < W;i++){
        bool flag = false;
        for(auto v : p){
            if(v == i)
                flag = true;
        }
        if(!flag){
            first = i;
            break;
        }
    }
    vector<int> tmp = p;
    tmp.push_back(first);
    if(tmp.size() == W){
        return dfs(id + 1, tmp);
    }else{
        bool res = false;
        for(int i = 0;i < W;i++){
            bool flag = false;
            for(auto v : tmp){
                if(v == i)
                    flag = true;
            }
            if(!flag){
                vector<int> tmp1 = tmp;
                tmp1.push_back(i);
                res |= dfs(id + 1, tmp1);
            }
        }
        return res;
    }
    return false;
}

