pll calc_hash(int col) {
	ll hs = 0, hp = 0;
	for (int j = 1; j <= np; ++j) {
		hp = hp * 27ll + (ll)(a[all_pairs[j].first][col] - 'a' + 1);
		hs = hs * 27ll + (ll)(a[all_pairs[j].second][col] - 'a' + 1);
	}
	if (residue) {
		hp = hp * 27ll + (ll)(a[residue][col] - 'a' + 1);
		hs = hs * 27ll + (ll)(a[residue][col] - 'a' + 1);
	}
	for (int j = np; j >= 1; --j) {
		hp = hp * 27ll + (ll)(a[all_pairs[j].second][col] - 'a' + 1);
		hs = hs * 27ll + (ll)(a[all_pairs[j].first][col] - 'a' + 1);
	}
	return pll(hp, hs);
}

