bool judge(const vector<string> &a, const vector<string> &b){

  /*
  cout<<"------------"<<endl;
  for(string str:a)cout<<str<<endl;
  cout<<endl;
  for(string str:b)cout<<str<<endl;
    cout<<"------------"<<endl;
  */

  vector<int> total( a[0].size() , (1<<20)-1 );

  for(int i=0;i<(int)a.size();i++){
    if(!countcheck(a[i],b[i]))return false;
  }

  for(int i=0;i<(int)a.size();i++){
    vector<int> X=func(a[i],b[i]);
    vector<int> Y=func(b[i],a[i]);
    for(int j=0;j<(int)X.size();j++){
      int tmp=(X[j]&Y[j]);
      if(tmp == 0 )return false;
    }
  }

  for(int i=0;i<(int)a.size();i++){
    vector<int> X=func(a[i],b[i]);
    vector<int> Y=func(b[i],a[i]);
    for(int j=0;j<(int)X.size();j++){
      int tmp=(X[j]&Y[j]);
      total[j]=(total[j]&tmp);
      if(total[j]==0)return false;
    }
  }

  for(int i=0;i<12;i++){
    G[i].clear();
    visited[i]=false;
  }

  //  cout<<a[0]<<' '<<b[0]<<endl;
  for(int i=0;i<(int)total.size();i++){
    for(int j=0;j<(int)total.size();j++){
      if( total[i] >> j &1 ){
        //        cout<<i<<' '<<j<<endl;
        G[i].push_back(j);
        G[j].push_back(i);
      }
    }
  }

  int cc=0;
  for(int i=0;i<(int)a[0].size();i++){
    if(visited[i])continue;
    int sz=0;
    dfs(i,sz);

    cc += (sz%2);
  }
  return (cc<=1);
}

