using namespace std;
template<typename T> struct Dinitz{
	int n, source, sink;
	vector<vector<T>> adj;
	struct edge {
		int u;
		T flow, cap;
	};
	vector<edge> edges;
	Dinitz(int n, int source, int sink): n(n), source(source), sink(sink), adj(n) {}
	int add_edge(int a, int b, T abcap, T bacap = 0) {
		int result = edges.size();
		adj[a].push_back(edges.size());
		edges.push_back({b, 0, abcap});
		adj[b].push_back(edges.size());
		edges.push_back({a, 0, bacap});
		return result;
	}
	vector<int> mindist, position;
	bool bfs() {
		queue<int> q;
		fill(mindist.begin(), mindist.end(), INT_MAX / 2);
		mindist[source] = 0;
		q.push(source);
		while (!q.empty()) {
			int v = q.front();
			q.pop();
			for (int edid: adj[v]) {
				edge &ed = edges[edid];
				if (ed.flow < ed.cap && mindist[ed.u] > mindist[v] + 1) {
					mindist[ed.u] = mindist[v] + 1;
					q.push(ed.u);
				}
			}
		}
		return mindist[sink] < n;
	}
	T dfs(int v, T maxf) {
		if (v == sink) return maxf;
		for (int &pos = position[v]; pos < (int)adj[v].size(); ++pos) {
			int edid = adj[v][pos];
			edge &ed = edges[edid], &reved = edges[edid ^ 1];
			if (ed.flow < ed.cap && mindist[ed.u] == mindist[v] + 1) {
				T f = dfs(ed.u, min(maxf, ed.cap - ed.flow));
				if (f > 0) {
					ed.flow += f;
					reved.flow -= f;
					return f;
				}
			}
		}
		return 0;
	}
	T maxflow() {
		T result = 0;
		mindist.resize(n);
		position.resize(n);
		while (bfs()) {
			T extra;
			do {
				fill(position.begin(), position.end(), 0);
				extra = dfs(source, numeric_limits<T> :: max());
				result += extra;
			} while (extra > 0);
		}
		return result;
	}
};
string a[12];
int main(){
	int n, m;
	cin >> n >> m;
	for(int i = 0; i < n; i++) cin >> a[i];
	int msk = 1<<n; msk--;
	for(int i = 0; i < (1<<n); i++){
		if(__builtin_popcount(i) != n/2) continue;
		int rev = msk ^ i;
		if(rev < i && __builtin_popcount(rev) == n / 2) continue;
		vector<int> top, bot;
		for(int j = 0; j < n; j++){
			if(i&(1<<j)) top.push_back(j);
			else bot.push_back(j);
		}
		do{
			Dinitz<int> flow(m + m + 2, 0, m + m + 1);
			for(int j = 0; j < m; j++){
				for(int k = j; k < m; k++){
					int ok = 0;
					for(int l = 0; l < n / 2; l++) ok += a[top[l]][j] == a[bot[l]][k] && a[top[l]][k] == a[bot[l]][j];
					if(n&1){
						ok += a[bot.back()][j] == a[bot.back()][k];
					}	
					if(ok == (n + 1) / 2){
						flow.add_edge(1 + j, 1 + k + m, 1);
						if(j != k) flow.add_edge(1 + k, 1 + j + m, 1);
					}
				}
			}
			for(int i = 0; i < m; i++) flow.add_edge(0, i + 1, 1), flow.add_edge(i + 1 + m, m + m + 1, 1);
			int fl = flow.maxflow();
			if(fl == m){
				cout << "YES" << endl;
				return 0;
			}
		} while(next_permutation(bot.begin(), bot.end()));
	}
	cout << "NO" << endl;
	return 0;
}

