bool f(string rows_rearranged[], bool used[], int start)
{
    debug_printf("----- start=%d\n", start);

    if (start >= h / 2) return judge(rows_rearranged, start);

    int idx1 = start;
    srep (i, start, h) {
        if (used[i]) continue;
        idx1 = i;
        break;
    }
    rows_rearranged[start] = rows[idx1];
    used[idx1] = true;

    srep (idx2, idx1 + 1, h) {
        if (used[idx2]) continue;
        rows_rearranged[lh - start - 1] = rows[idx2];
        used[idx2] = true;
        if (f(rows_rearranged, used, start + 1)) return true;
        used[idx2] = false;
    }

    used[idx1] = false;

    return false;
}

