bool check(const vector<vector<char>> &g) { // checks row ok?
  vector<vector<char>> rows;
  map<vector<char>, int> cnt;
  for (int i = 0; i < g.size(); ++i) {
    rows.emplace_back(g[i]);
    sort(rows.back().begin(), rows.back().end());
    ++cnt[rows.back()];
  }
  int bad = 0;
  for (auto it = cnt.begin(); it != cnt.end(); ++it) {
    bad += it->second & 1;
  }
  return bad <= (g.size() & 1);
}

int hh(const vector<string> &g) {
  int p = 1e9 + 7;
  int m = 1e9 + 31;
  int r = 0;
  for (int i = 0; i < g.size(); ++i) {
    for (int j = 0; j < g[0].size(); ++j) {
      (r += 1LL * g[i][j] * p % m) %= m;
    }
  }
  return r < m / 2;
}

signed main() {
  ios::sync_with_stdio(false);
  int N, M;
  cin >> N >> M;
  vector<string> G(N);
  for (int i = 0; i < N; ++i) {
    cin >> G[i];
  }
  vector<vector<char>> g(N, vector<char>(M));
  for (int i = 0; i < N; ++i) {
    for (int j = 0; j < M; ++j) {
      g[i][j] = G[i][j];
    }
  }
  bool ok = true;
  ok &= check(g);
  vector<vector<char>> tg(M, vector<char>(N));
  for (int i = 0; i < N; ++i) {
    for (int j = 0; j < M; ++j) {
      tg[j][i] = g[i][j];
    }
  }
  ok &= check(tg);
  ok ^= hh(G);
  cout << (ok ? "YES" : "NO") << endl;
  return 0;
}

