bool dfs(int x) {
	if (2*bitcnt(x) + 1 >= h) {
		int k = 0;
		rep(i, h) {
			if ((x >> i) % 2 == 0) {
				k++;
				t[tnum++] = s[i];
			}
		}
		// check
		bool ret = check();
		tnum -= k;
		return ret;
	}
	tnum++;
	rep(i, h) {
		if ((x >> i) & 1)	continue;
		t[tnum-1] = s[i];
		if (dfs(x | (1 << i)))	return true;
	}
	tnum--;
	return false;
}

