class FordFulkerson {
    struct Edge {
        ll to, cap, rev_index;
    } ;
private:
    vector<vector<Edge>> v;
    ll n;
    bool *used;
    const ll INF = numeric_limits<ll>::max();

    int dfs(ll now, ll goal, ll f) {
        if(now == goal) return f;
        used[now] = 1;
        for(Edge &e : v[now]) {
            if(used[e.to]) {
                continue;
            }
            if(e.cap <= 0) {
                continue;
            }
            ll d = dfs(e.to, goal, min(f, e.cap));
            if(d > 0) {
                e.cap -= d;
                v[e.to][e.rev_index].cap += d;
                return d;
            }
        }
        return 0;
    }

public:
    FordFulkerson(const vector<vector<pair<ll, ll>>> &v) {
        this->n = v.size();
        for(int i = 0; i < n; i++) {
            this->v.push_back(vector<Edge>(0));
        }
        for(int i = 0; i < n; i++) {
            for(auto e : v[i]) {
                this->v[i].push_back((Edge) {e.first, e.second, (ll)this->v[e.first].size()} );
                this->v[e.first].push_back((Edge) {i, 0, (ll)this->v[i].size() - 1} );
            }
        }
        used = new bool[n];
    }

    ll max_flow(ll start, ll goal) {
        ll ret = 0;
        while(1) {
            memset(used, 0, n);
            ll add = dfs(start, goal, INF);
            if(add == 0) {
                return ret;
            }
            ret += add;
        }
    }
} ;

V<string> S;
VV<bool> same_poss;
V<VV<ll>> alp_list(12, VV<ll>(26)); 
ll H, W;

bool calc(const V<ll> &nodes) {
    ll start = 2 * W, goal = 2 * W + 1;
    VV<ll> mat(W, V<ll>(W, 0));
    for(ll i = 0; i + 1 < nodes.size(); i += 2) {
        ll f = nodes[i], t = nodes[i + 1];
        if(f == -1 || t == -1) return false;
        for(ll alp = 0; alp < 26; alp++) for(ll fe : alp_list[f][alp]) for(ll te : alp_list[t][alp]) mat[fe][te]++;
    }
    VV<PLL> edges(goal + 1);
    for(ll w1 = 0; w1 < W; w1++) {
        edges[start].emplace_back(w1, 1);
        edges[w1 + W].emplace_back(goal, 1);
        for(ll w2 = 0; w2 < W; w2++) {
            if(w1 == w2) continue;
            if(mat[w1][w2] != nodes.size() / 2) continue;
            edges[w1].emplace_back(w2 + W, 1);
        }
    }
    ll matching = FordFulkerson(edges).max_flow(start, goal);
    if(W & 1) {
        matching = 0;
        for(ll w = 0; w < W; w++) {
            if(mat[w][w] != nodes.size() / 2) continue;
            auto wedges = edges;
            for(ll i = 0; i < W; i++) {
                if(i == w) continue;
                for(ll j = 0; j < wedges[i].size(); j++) {
                    if(wedges[i][j].first != w + W) continue;
                    wedges[i].erase(wedges[i].begin() + j);
                    break;
                }
            }
            wedges[w] = { PLL(w + W, 1) };
            chmax(matching, FordFulkerson(wedges).max_flow(start, goal));
        }
    }
    return matching >= W;
}

bool dfs(V<ll> &nodes, ll depth, ll max_d, V<bool> &used) {
    if((H & 1) && depth + 1 == max_d) {
        nodes[depth] = nodes[depth - 1];
        return calc(nodes);
    }
    if(depth == max_d) return calc(nodes);
    bool ret = false;
    for(ll i = 0; i < H; i++) {
        if(used[i]) continue;
        if((depth & 1) && !(same_poss[i][nodes[depth - 1]])) continue;
        nodes[depth] = i;
        used[i] = true;
        ret |= dfs(nodes, depth + 1, max_d, used);
        if(ret) break;
        used[i] = false;
        nodes[depth] = -1;
    }
    return ret;
}

