    for (int k = 0; k < H / 2; ++k) {
      if (ss[k][l] != ss[H - 1 - k][r]) return false;
    }
    return true;
  };
  for (int i = 0; i < W; ++i) {
    for (int j = i + 1; j < W; ++j) {
      if (used[i] || used[j]) continue;
      if (same(i, j)) used[i] = used[j] = true;
    }
  }
