  Solver(int h, int w) : h(h), w(w), s(h){};

  inline int nextCombination(int comb) {
    int x = comb & -comb, y = comb + x;
    return (((comb & ~y) / x) >> 1) | y;
  }
  void yes() {
    cout << "YES" << endl;
    exit(0);
  }
  void no() {
    cout << "NO" << endl;
    exit(0);
  }
