    vector<string> grid(h);
    for (int i = 0; i < h; ++i) {
      for (int j = 0; j < w; ++j) {
        grid[i].push_back(s[i][perm[j]]);
      }
    }
    vector<int> used(h);
    for (int i = 0; i < h; ++i) {
      if (used[i]) continue;
      string tmp = grid[i];
      reverse(tmp.begin(), tmp.end());
      for (int j = i + 1; j < h; ++j) {
        if (tmp == grid[j]) {
          used[i] = used[j] = 1;
          break;
        }
      }
    }
    if (h % 2 == 1) {
      if (accumulate(used.begin(), used.end(), 0) < h - 1) return false;
      int rest = 0;
      for (int i = 0; i < h; ++i) {
        if (used[i] == 0) {
          rest = i;
          break;
        }
      }
      string restRow = grid[rest], rev = restRow;
      reverse(rev.begin(), rev.end());
      return restRow == rev;
    } else {
      return accumulate(used.begin(), used.end(), 0) == h;
    }
  }
  void dfs(int used, int l, int pos, vector<int> perm) {
    DBG(perm)

    if (pos == -1) {
      if (w % 2 == 1) {
        for (int i = 0; i < w; ++i) {
          perm[w / 2] = i;
          dfs(1 << i, 0, 0, perm);
        }
      } else {
        dfs(used, 0, 0, perm);
      }
      return;
    }

    if (pos == w / 2) {
      if (check(perm)) yes();
      return;
    }
    if (((used >> l) & 1)) {
      dfs(used, l + 1, pos, perm);
      return;
    }
    for (int i = l + 1; i < w; ++i) {
      if (((used >> i) & 1) == 0) {
        perm[pos] = l;
        perm[w - pos - 1] = i;
        dfs(used | (1 << l) | (1 << i), l + 1, pos + 1, perm);
      }
    }
  }
  void solve() {
    for (int i = 0; i < h; ++i) {
      cin >> s[i];
    }
    vector<int> perm_col(w);

    dfs(0, 0, -1, perm_col);
    no();
  }
