int n, m, pos, pos1;
char c[N][N];
char cc[N][N];
bool used[N], u[N];
int freq[1234];

bool isequal(int i, int j) {
	for (int k = 1; k <= m; k++) {
		if (c[i][k] != c[j][k]) return false;
	}
	return true;
}

bool iseq(int i, int j) {
	for (int k = 1; k <= n; k++) {
		if (cc[i][k] != cc[j][k]) return false;
	}
	return true;
}

bool check() {
	for (int i = 1; i <= m; i++) {
		if (u[i]) continue;
		for (int j = i + 1; j <= m; j++) {
			if (u[j]) continue;
			if (iseq(i, j)) {
				u[i] = u[j] = 1;
				break;
			}
		}
	}
	int cnt = 0;
	for (int i = 1; i <= m; i++) {
		if (!u[i]) cnt++;
	}
	if (cnt <= 1) {
		if (cnt == 0) return 1;
		for (int i = 1; i <= m; i++) {
			if (!u[i]) cnt = i;
		}
		memset(freq, 0, sizeof freq);
		for (int i = 1; i <= n; i++) {
			freq[(int)cc[cnt][i]]++;
		}
		cnt = 0;
		for (int i = 'a'; i <= 'z'; i++) {
			if (freq[i] & 1) {
				cnt++;
				pos = i;
			}
		}
		if (n & 1) {
			return cnt == 1;
		} else {
			return cnt == 0;
		}
	} 
	return 0;
}

bool check1() {
	for (int i = 1; i <= n; i++) {
		if (used[i]) continue;
		for (int j = i + 1; j <= n; j++) {
			if (used[j]) continue;
			if (isequal(i, j)) {
				used[i] = used[j] = 1;
				break;
			}
		}
	}
	int cnt = 0;
	for (int i = 1; i <= n; i++) {
		if (!used[i]) cnt++;
	}
	if (cnt <= 1) {
		if (cnt == 0) return 1;
		for (int i = 1; i <= n; i++) {
			if (!used[i]) cnt = i;
		}
		memset(freq, 0, sizeof freq);
		for (int i = 1; i <= m; i++) {
			freq[(int)c[cnt][i]]++;
		}
		cnt = 0;
		for (int i = 'a'; i <= 'z'; i++) {
			if (freq[i] & 1) {
				cnt++;
				pos1 = i;
			}
		}
		if (m & 1) {
			return cnt == 1;
		} else {
			return cnt == 0;
		}
	} 
	return 0;
}

int main() {
	scanf("%d %d", &n, &m);
	for (int i = 1; i <= n; i++) {
		scanf("\n");
		for (int j = 1; j <= m; j++) {
			scanf("%c", &c[i][j]);
			cc[j][i] = c[i][j];
		}
	}           
	for (int i = 1; i <= n; i++) 
		sort(c[i] + 1, c[i] + m + 1);		
	for (int i = 1; i <= m; i++) 
		sort(cc[i] + 1, cc[i] + n + 1);
	if (check() && check1()) {
		if ((n & 1) && (m & 1)) {
			if (pos == pos1) {
				puts("YES");
			} else {
				assert(0);
			}
			return 0;
		}
		puts("YES");
	} else {
