void count(){
    fill(count_lines[0], count_lines[12], 0);
    fill(count_columns[0], count_columns[12], 0);
    rep(h){
        repp(j, w){
            count_lines[i][a[i][j]-'a']++;
            count_columns[j][a[i][j]-'a']++;
        }
