bool check_columns(){
    bool center = (w % 2 == 0);
    bool used[w];
    fill(used, used+w, false);

    repp(j, w){
        if(used[j]) continue;
        used[j] = true;
        bool same;

        repp(jj, w){
            if(used[jj]) continue;

            same = true;
            repp(k, 26){
                if(count_columns[j][k] != count_columns[jj][k]){
                    same = false;
                    break;
                }
            }
            if(same){
                used[jj] = true;
                break;
            }
        }

        if(!same){
            if(center) return false;
            else center = true;
        }
    }

    return true;
}

bool check_lines(){
    int pair_first[6];
    fill(pair_first, pair_first+6, -1);
    rep(h){
        if(pair_first[pairs[i]] == -1){
            pair_first[pairs[i]] = i;
        }else{
            repp(k, 26){
                if(count_lines[pair_first[pairs[i]]][k] != count_lines[i][k]) return false;
            }
        }
    }
    return true;
}

bool make_even(){
    h++;
    rep(h-1){
        a[h-1] = a[i];
        pairs[h-1] = -1;
        count();
        if(make_pair_of_lines(0)) return true;
    }
    return false;
}

bool make_pair_of_lines(int paired_line){
    if(h % 2) return make_even();

    if(paired_line == h) return check_lines();

    int pair_line_first = -1;
    rep(h){
        if(pairs[i] == -1){
            if(pair_line_first == -1){
                pair_line_first = i;
                pairs[pair_line_first] = paired_line/2;
                break;
            }
        }
    }

    repp(j, h){
        if(pairs[j] == -1){
            pairs[j] = paired_line/2;
            if(make_pair_of_lines(paired_line+2)) return true;
            pairs[j] = -1;
        }
    }

    pairs[pair_line_first] = -1;

    return false;
}

int main(){
    std::ios::sync_with_stdio(0); cin.tie(0);

    cin >> h >> w;
    rep(h) cin >> a[i];

    count();

    if(!check_columns()){
        cout << "NO" << endl;
        return 0;
    }

    fill(pairs, pairs+h, -1);
    cout << (make_pair_of_lines(0)?"YES":"NO") << endl;
    return 0;
}

