using namespace std;
int n, m, match[15], vis[13], ans = 0;
char s[15][15];

bool check() {
	memset(vis, 0, sizeof(vis));
	for(int i=1; i<=m; i++)
		for(int j=1; j<=m; j++) {
			if(vis[i] || vis[j] || i==j) continue;
			bool flag = 1;
			for(int k=1; k<=n; k++) {
				if(s[match[k]][i] != s[k][j]) {
					flag = 1;
					break;
				}
			}
			if(flag) vis[i] = vis[j] = 1;
		}
	int cnt = 0, flag = 0;
	for(int i=1; i<=m; i++)
		if(!vis[i]) {
			cnt++;
			flag = i;
		}
	if((m % 2 == 0 && cnt) || cnt >= 2) return 0;
	if(!cnt) return 1;
	for(int i=1; i<=n; i++)
		if(s[match[i]][flag] != s[i][flag]) return 0;
	return 1;
}

void dfs(int step, bool flag) {
	if(ans) return;
	if(step == ((n+1) >> 1)) {
		if(check()) ans = 1;
		return;
	}
	for(int i=step; i<=n; i++) {
		for(int j=i+1; j<=n; j++)
			if(match[i] == -1 && match[j] == -1) {
				match[i] = j, match[j] = i;
				dfs(step+1, flag);
				match[i] = -1, match[j] = -1;
			}
		if(flag && match[i] == -1) {
			match[i] = i;
			dfs(step+1, 0);
			match[i] = -1;
		}
	}
}

int main()
{
	memset(match, -1, sizeof(match));
	scanf("%d%d", &n, &m);
	for(int i=1; i<=n; i++) scanf("%s", s[i]+1);
	if(n % 2 == 1) dfs(0, 1);
		else dfs(0, 0);
	if(ans) printf("YES\n");
		else printf("NO\n");
	return 0;
}

#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using P = pair<int, int>;

int H, W;

bool judge(vector<P>& v, vector<string>& s) {
    vector<string> s2(H);
    for (int i = 0; i < (H + 1) / 2; i++) {
        s2[i] = s[v[i].first];
        s2[H - 1 - i] = s[v[i].second];
    }

    vector<int> used(W, false);
    int ok = W % 2;
    for (int i = 0; i < W; i++) {
        if (used[i]) continue;
        for (int j = W - 1; j >= i; j--) {
            if (used[j]) continue;
            bool flag = true;
            for (int k = 0; k < H; k++) {
                if (s2[k][i] != s2[H - 1 - k][j]) {
                    flag = false;
                    break;
                }
            }
            if (flag) {
                if (j == i && ok) {
                    ok = false;
                }
                used[i] = true;
                used[j] = true;
                break;
            }
        }
        if (!used[i]) {
            return false;
        }
    } 
    return true;
}

bool solve(int used, vector<P>& v, vector<string>& s) {
    vector<int> idxs;
    for (int i = 0; i < H; i++) {
        if (used & (1 << i)) continue;
        idxs.push_back(i);
    }

    int m = idxs.size();
    if (m == 0) {
        return judge(v, s);
    } else if (m == 1) {
        used ^= (1 << idxs[0]);
        v.emplace_back(idxs[0], idxs[0]);
        if (solve(used, v, s)) return true;
        used ^= (1 << idxs[0]);
    } else {
        for (int ii = 0; ii < m; ii++) {
            int i = idxs[ii];
            used ^= (1 << i);
            for (int jj = ii + 1; jj < m; jj++) {
                int j = idxs[jj];
                used ^= (1 << j);
                v.emplace_back(i, j);
                if (solve(used, v, s)) return true;
                used ^= (1 << j);
                v.pop_back();
            }
            used ^= (1 << i);
        }
    }
    return false;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> H >> W;
    vector<string> s(H);

    /*
    vector<int> cnt(26, 0);
    for (int i = 0; i < H; i++) {
        cin >> s[i];
        for (int j = 0; j < W; j++) {
            cnt[s[i][j] - 'a']++;
        }
    }

    int hoge = 0;
    for (int i = 0; i < 26; i++) {
        hoge += cnt[i] % 2;
    }
    if (hoge != (H * W) % 2) {
        cout << "NO" << endl;
        return 0;
    }*/

    vector<P> v;
    cout << (solve(0, v, s) ? "YES" : "NO") << endl;
    return 0;
}

