int H, W;
string S[20];
typedef tuple<int, int> P;
vector<vector<P>> pairs;

void dfs(vector<P> temp, vector<bool> used, int R)
{
  if (R == 0)
  {
    pairs.push_back(temp);
    return;
  }
  if (R == 1)
  {
    for (auto i = 0; i < H; i++)
    {
      if (!used[i])
      {
        temp.push_back(P(i, i));
        dfs(temp, used, 0);
        return;
      }
    }
  }
  assert(R >= 2);
  int first = -1;
  for (auto i = 0; i < H; i++)
  {
    if (!used[i])
    {
      first = i;
      used[i] = true;
      break;
    }
  }
  assert(first >= 0);
  for (auto i = 0; i < H; i++)
  {
    if (!used[i])
    {
      vector<bool> n_used = used;
      n_used[i] = true;
      vector<P> n_temp = temp;
      n_temp.push_back(P(first, i));
      dfs(n_temp, n_used, R - 2);
    }
  }
}

vector<string> make_strings(vector<P>& V)
{
  vector<int> X;
  int N = V.size();
  for (auto i = 0; i < N; i++)
  {
    X.push_back(get<0>(V[i]));
  }
  for (auto i = N-1; i >= 0; i--)
  {
    X.push_back(get<1>(V[i]));
  }
  vector<string> res;
  for (auto j = 0; j < W; j++)
  {
    string str = "";
    for (auto i : X)
    {
      string t = {S[i][j]};
      str += t;
    }
    res.push_back(str);
  }
  return res;
}

vector<string> reverse_strings(const vector<string>& V)
{
  vector<string> res;
  for (auto x : V)
  {
    reverse(x.begin(), x.end());
    res.push_back(x);
  }
  return res;
}

int main()
{
  cin >> H >> W;
  for (auto i = 0; i < H; i++)
  {
    cin >> S[i];
  }
  vector<P> emp_P;
  vector<bool> emp_used = vector<bool>(H, false);
  dfs(emp_P, emp_used, H);
  for (auto e : pairs)
  {
    vector<string> V1 = make_strings(e);
    vector<string> V2 = reverse_strings(V1);
    vector<bool> used = vector<bool>(false, W);
    int R = W;
    while (R > 0)
    {
      bool ok = true;
      for (auto i = 0; i < W; i++)
      {
        if (!used[i])
        {
          bool found = false;
          used[i] = true;
          for (auto j = 0; j < W; j++)
          {
            if (!used[j] && V1[i] == V2[j])
            {
              used[j] = true;
              R -= 2;
              found = true;
              break;
            }
          }
          if (!found && V1[i] == V2[i])
          {
            R -= 1;
            found = true;
          }
          if (!found)
          {
            ok = false;
            break;
          }
        }
      }
      if (!ok)
      {
        break;
      }
    }
    if (R == 0)
    {
      cout << "YES" << endl;
      return 0;
    }
  }
  cout << "NO" << endl;
}

