bool rec(int idx1, int cnt){
    if (idx1 == H) {
        return check();
    }
    if (H%2 == 1 && cnt == H/2){
        result[cnt] = grid[idx1];
        used[idx1] = true;
        return check();
    }

    if (used[idx1]){
        return rec(idx1+1, cnt);
    } else {
        for (int idx2 = idx1+1; idx2 < H; idx2++){
            if (!used[idx2] && compare_h(grid[idx1], grid[idx2])){
                used[idx1] = true;
                used[idx2] = true;
                result[cnt] = grid[idx1];
                result[H-1-cnt] = grid[idx2];
                if (rec(idx1+1, cnt+1)){
                    return true;
                } else {
                    used[idx1] = false;
                    used[idx2] = false;
                }
            }
        }
    }
    return false;
}


