int
calc_score(int h, int w, vector<string> grid)
{
    int score = 0;
    for (int i = 0; i < (h + 1) / 2; i++) {
        for (int j = 0; j < w; j++) {
            if (grid[i][j] != grid[h - 1 - i][w - 1 - j])
                score++;
        }
    }
    return score;
}

int
main()
{
    int h, w;
    cin >> h >> w;
    vector<string> s(h);
    for (int i = 0; i < h; i++) {
        cin >> s[i];
    }

    int score = calc_score(h, w, s);
    while (true) {
        bool improved = false;
        for (int i = 0; i < h; i++) {
            for (int i2 = 0; i2 < h; i2++) {
                swap(s[i], s[i2]);
                int score2 = calc_score(h, w, s);
                if (score2 < score) {
                    score = score2;
                    improved = true;
                    goto row;
                }
                swap(s[i], s[i2]);
            }
        }
    row:
        for (int j = 0; j < w; j++) {
            for (int j2 = 0; j2 < w; j2++) {
                for (int i = 0; i < h; i++)
                    swap(s[i][j], s[i][j2]);
                int score2 = calc_score(h, w, s);
                if (score2 < score) {
                    score = score2;
                    improved = true;
                    goto col;
                }
                for (int i = 0; i < h; i++)
                    swap(s[i][j], s[i][j2]);
            }
        }
    col:
        if (!improved)
            break;
    }
    cout << (score == 0 ? "YES" : "NO") << endl;
}

