	}
	np = n / 2;
	for (int residue = n & 1; residue <= (n & 1) * n; ++residue) {
		used[residue] = true;
		brute(1);
	}
	puts("NO");
#ifdef debug
	printf("Total time: %d ms\n", (int)(1000.0 * (double)(clock() - tStart) / CLOCKS_PER_SEC));
#endif
	return 0;
}

