bool check(int j, bool usecenter) {
	if (2 * j >= w)	return true;
	string rev = "";
	rrep(i, h)	rev += s[i][j];
	bool found = false;
	srep(i, j + 1, w - j) {
		string comp = "";
		rep(k, h)	comp += s[k][i];
		if (comp == rev) {
			rep(k, h)	swap(s[k][i], s[k][w - 1 - j]);
			if (check(j + 1, usecenter))	return true;
		}
	}
	if (!usecenter&&w%2==1) {
		map<char, int> dat;
		rep(i, h)	dat[rev[i] - 'a']++;
		int cnt = 0;
		for (auto it : dat)	cnt += it.second % 2;
		if (cnt > 2)	return false;
		if (check(j + 1, true))	return true;
	}
	return false;
}

bool dfs(int x, bool usecenter) {
	if (x * 2 + 1 >= h) {
		return check(0, false);
	}
	map<char, int> base;
	rep(i, w)	base[s[x][i] - 'a']++;
	bool found = false;
	SREP(i, x + 1, h - 1 - x) {
		map<char, int> p;
		rep(j, w)	p[s[i][j] - 'a']++;
		if (base == p) {
			found = true;
			swap(s[i], s[h - 1 - x]);
			if (dfs(x + 1, usecenter))	return true;
		}
	}
	if (h % 2 == 1&&!usecenter) {
		swap(s[x], s[h / 2]);
		if (dfs(x, true))	return true;
	}
	return false;
}

