#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

using tpl = tuple<int, int, int>;
typedef pair<int,int> pii;

void fastStream(){cin.tie(0);std::ios_base::sync_with_stdio(0);}


int H, W;
char S[20][20];
char C[20][20];
int rowperm[20];
bool row_used[20];

bool is_match(const string &s1, const string &s2){
    for(int i = 0; i < (int)s1.size(); i++){
        if(s1[i] != s2[(int)s1.size() - 1 - i]){
            return false;
        }
    }
    return true;
}

bool rec(int depth){
    if(depth == H / 2){
        // rowpermの順番に文字列をセット
        for(int i = 0; i < H; i++){
            for(int j = 0; j < W; j++){
                C[i][j] = S[rowperm[i]][j];
            }
        }
        // colを決定する
        string ss[20];
        for(int j = 0; j < W; j++){
            for(int i = 0; i < H; i++){
                ss[j] += C[i][j];
            }
        }

        // 奇数の場合、どれか一つを除いて判定
        bool used[20] = {};
        for(int i = 0; i < W; i++){
            if(W % 2){
                if(!is_match(ss[i], ss[i])){
                    continue;
                }
                used[i] = true;
            }

            int cnt = 0;
            // ２つのペアを作っていく
            for(int j = 0; j < W; j++){
                if(used[j]) continue;
                used[j] = true;
                bool ok = false;
                for(int k = 0; k < W; k++){
                    if(used[k]) continue;
                    if(j == k) continue;
                    used[k] = true;
                    if(is_match(ss[j], ss[k])){
                        ok = true;
                        break;
                    }
                    used[k] = false;
                }
                if(!ok){
                    break;
                }
                else{
                    cnt++;
                }
            }

            if(cnt == W / 2) return true;

            if(W % 2 == 0) break;

            if(W % 2) used[i] = false;
        }
        return false;
    }
    else{
        int start = -1;
        // 使っていない一番左の要素は確定
        for(int i = 0; i < H; i++){
            if(row_used[i]) continue;
            start = i;
            break;
        }

        row_used[start] = true;
        rowperm[depth] = start;

        for(int i = start + 1; i < H; i++){
            if(row_used[i]) continue;
            rowperm[H - 1 - depth] = i;
            row_used[i] = true;
            if(rec(depth + 1))
                return true;
            row_used[i] = false;
        }
        row_used[start] = false;
    }
    return false;
}

bool solve(){
    // rowを決める
    if(H % 2){
        for(int i = 0; i < H; i++){
            row_used[i] = true;
            rowperm[H / 2] = i;
            if(rec(0)){
                return true;
            }
            row_used[i] = false;
        }
        return false;
    }
    else{
        return rec(0);
    }
}

int main(){
    cin >> H >> W;
    for(int i = 0; i < H; i++) cin >> S[i];
    if(solve()){
        cout << "YES" << endl;
    }
    else{
        cout << "NO" << endl;
    }
    return 0;
}

