bool rev_same(string s, string t){
    if(s.length()!=t.length()) return false;
    for (int i = 0; i < s.length(); i++)
    {
        if(s[i]!=t[s.length()-1-i]) return false;
    }
    return true;
}

bool is_column(vector<string> T){
    vector<string> R;
    for (int j = 0; j < W; j++)
    {
        string r = "";
        for (int i = 0; i < H; i++)
        {
            r += T[i][j];
        }
        R.push_back(r);
    }

    vector<bool> used(W,false);    
    int center = W%2?0:1;

    for (int j = 0; j < W; j++)
    {
        if(used[j]) continue;
        used[j] = true;
        bool pair = false;
        for (int k = 0; k < W; k++)
        {
            if(used[k]) continue;
            if(rev_same(R[j], R[k])){
                used[k] = true;
                pair = true;
                break;
            }
        }
        if(!pair){
            if(rev_same(R[j],R[j]) && center==0){
                center = 1;
            }
            else{
                return false;
            }
        }
    }
    return true;
}

