using Bool = bool;
using Int = long long int;
using String = std::string;
template <class T>
using Vector = std::vector<T>;

// 各関数は上から下に流れるようになっている
// ! で始まるコメントは自分が踏んだバグ
struct {
    Int h, w;
    Vector<Int> col;
    Vector<String> s, t;
    // sは入力 tは行を並び替えた後、転置したもの
    Bool possible;

    void operator()() {
        possible = false;
        std::cin >> h >> w;

        s.resize(h), t.resize(w);
        for (auto& x : s) std::cin >> x;
        for (auto& y : t) y.resize(h);  // ! tのresizeし忘れ

        col.resize(h);
        enumcol();
    }

    // 行の列挙　next_permutationバージョン
    void enumcol() {
        std::iota(col.begin(), col.end(), 0);
        do {
            Bool valid = true;
            for (Int i = 0; i < h - i - 1; ++i) {
                if (col[i] > col[h - i - 1]) valid = false;
            }
            if (valid) align();
        } while (std::next_permutation(col.begin(), col.end()));
    }

    // colに従ってtを埋める
    void align() {
        for (Int y = 0; y < w; ++y) {
            for (Int x = 0; x < h; ++x) {
                t[y][x] = s[col[x]][y];
            }
        }
        check_center();
    }

    // 真ん中の行の列挙　
    // ! enumcol_center()と同じく
    void check_center() {
        if (w % 2 == 0) {
            check(0);
        } else {
            for (Int x = 0; x < w; ++x) {
                // 回文判定
                String z = t[x];
                std::reverse(z.begin(), z.end());
                if (z == t[x]) check(1 << x);
            }
        }
    }

    // 両端から、互いに逆なペアを決めていく
    // bは決定済みの行番号
    void check(Int b) {
        Int x;
        for (x = 0; x < w; ++x) {
            if (!((b >> x) & 1)) break;
        }

        if (x == w) {
            possible = true;
            return;  // ! ここで枝刈りしないと、全文字が同じケースで非常に時間がかかる
                     //   なんならYESを出力してexit()を呼んでもいい
        }

        String z = t[x];
        std::reverse(z.begin(), z.end());

        for (Int y = x + 1; y < w; ++y) {
            if (!((b >> y) & 1)) {
                if (t[y] == z) {
                    check(b | (1 << x) | (1 << y));
                    return;
                }
            }
        }
    }
} solve;

int main() {
    solve();
    std::cout << (solve.possible ? "YES" : "NO") << std::endl;
    return 0;
}

