      if( freq[c-'a'] % 2 == 1 ) {
	oddcount++;
	midchar = c;
      }
    if( oddcount > 1 ) {
      cout << "NO" << nl;
      return 0;
    }
    bool found = false;
    int midx = 0, midy = 0;
    for(int i=1; i<=h and not found; i++)
      for(int j=1; j<=w and not found; j++)
	if(c[i][j] == midchar) {
	  memset(freq, 0, sizeof freq);
	  for(int ii=1; ii<=h; ii++)
	    freq[c[ii][j]-'a']^=1;
	  for(int jj=1; jj<=w; jj++)
	    freq[c[i][jj]-'a']^=1;
	  if( *max_element(freq, freq+26) == 0 ) {
	    midx = i, midy = j;
	    found = true;
	  }
	}

    int p = (h+1)/2, q=(w+1)/2;

    for(int ii=1; ii<=h; ii++)
      swap(c[ii][q], c[ii][midy]);
    for(int jj=1; jj<=w; jj++)
      swap(c[p][jj], c[midx][jj]);

  }

  char mark[1+h][1+w];
  memset(mark, 0, sizeof mark);
  for(int i=1; i<=h; i++)
    for(int j=1; j<=w; j++) {
      int ri = h+1-i, rj = w+1-j;
      if(mark[i][j] or mark[ri][rj]) continue;

      mark[i][j] = 1; // exclude this
      if( ri == i and rj == j ) mark[i][j] = 0; // unless center cell

      bool found = false;
      if( c[i][j] == c[ri][rj] and c[i][rj] == c[ri][j] ) {
	mark[i][j] = mark[ri][rj] =
	  mark[i][rj] = mark[ri][j] = 1;
	found = true;
      }

      for(int x=1; x<=h and not found; x++)
	for(int y=1; y<=w and not found; y++) {
	  if(mark[x][y] or mark[i][y] or mark[x][j])
	    continue;
	  if( c[i][j] == c[x][y] and c[i][y] == c[x][j] ) {

	    if( y != rj )
	      for(int ii=1; ii<=h; ii++)
		swap(c[ii][y], c[ii][rj]);
	    if( x != ri )
	      for(int jj=1; jj<=w; jj++)
		swap(c[x][jj], c[ri][jj]);

	    mark[i][j] = mark[ri][rj] =
	      mark[i][rj] = mark[ri][j] = 1;
	    found = true;
	    break;
	  }
	}

      // cerr << "##" << endl;
      // for(int i=1; i<=h; i++) {for(int j=1; j<=w; j++)
      // 	  cerr << c[i][j] ; cout << nl; }
      // cerr << nl;

      if( not found ) {
	// cerr << "~~" << i << ',' << j << endl;
	cout << "NO" << endl;
	return 0;
      }
    }
  cout << "YES" << endl;
  // for(int i=1; i<=h; i++) {for(int j=1; j<=w; j++)
  //     cerr << c[i][j] ; cout << nl; }
  return 0;
