void make(){
	map<string,int> cnt;
	for(int i=0;i<m;i++){
		string str;
		for(int j=0;j<n;j++){
			if(t[i][j]=='*') str+=t[n-i-1][j];
			else str+=t[i][j];
		}
		string trs=str;
		reverse(trs.begin(),trs.end());
		cnt[min(trs,str)]++;
	}
	bool flag=false;
	for(map<string,int>::iterator it=cnt.begin();it!=cnt.end();it++){
		if(!(it->second%2)) continue;
		string str=it->first;
		string rts=str;
		reverse(rts.begin(),rts.end());
		if(str!=rts){
			if(flag) return;
			flag=true;
		}
	}
	ans=true;
}

void dfs(int b,int k){
	if(!b){
		make();
		return;
	}
	int x;
	while(~b>>x&1) x++;
	t[k]=s[x];
	for(int i=x+1;i<n;i++){
		if(!(b&(1<<i))) continue;
		t[n-k-1]=s[i];
		dfs(b^(1<<x)^(1<<i),k+1);
	}
}

int main(){
	scanf("%d%d",&n,&m);
	for(int i=0;i<n;i++) cin>>s[i];
	if(n&1) s[n]=string(m,'*');
