		if (R % 2 == 1) {
			fixed[R / 2] = order[id++];
		}
		while (i < j) {
			fixed[i] = order[id++];
			fixed[j] = order[id++];
			i++, j--;
		}
		solve(fixed);
	}
	else{
		for (int i : range(R)) {
			if (b[i]) {
				order.push_back(i);
				b[i].flip();
				break;
			}
		}
		for (int i : range(R)) {
			if (b[i]) {
				order.push_back(i);
				b[i].flip();
				dfs(b, order);
				order.pop_back();
				b[i].flip();
			}
		}
	}
}
int main() {
	while (cin >> R >> C) {
		ans = 0;
		in = Vs(R, S(C, '-'));
		cin >> in;
		if (R % 2 == 1) {
			for (int i : range(R)) {
				vector<int> a = { i };
				dfs(bitset<16>((1 << R) - 1 - (1<<i)), a);
			}
		}
		else {
			vector<int> a;
			dfs(bitset<16>((1 << R) - 1), a);
		}
		cout << ret[ans] << endl;
	}

	return 0;
}

