                r[wx] = r[wx] + s[p.second][wx];
            }
        }
        return check(r);
    }


    int l = *st.begin();
    for(auto r : st){
        if(l == r) continue;
        vector<pair<int, int>> v = rem;
        v.push_back({l, r});
        set<int> stt = st;
        stt.erase(l);
        stt.erase(r);
        if(pairs(v, stt)) return true;
    }

    l = *(++st.begin());
    for(auto r : st){
        if(l == r) continue;
        vector<pair<int, int>> v = rem;
        v.push_back({l, r});
        set<int> stt = st;
        stt.erase(l);
        stt.erase(r);
        if(pairs(v, stt)) return true;
    }

    return false;
