int h,w;
string s[15];
vector<int> one,other;

char tmp[15][15];


bool check(){
	//error("Call_Start");
	int idx = other.size();

	for(auto &elem:one){
		rep(j,w) tmp[idx][j] = s[elem][j];
		idx++;
	}

	vector<string> collect;

	rep(j,w){
		string in = "";
		rep(i,h) in += tmp[i][j];
		collect.push_back(in);
	}


	while(collect.size() >= 2){
		bool found = false;

		const int n = collect.size();	

		rep(j,n)rep(i,j){
			bool same = true;
			rep(k,h) if(collect[i][k] != collect[j][h-1-k]) same = false; 

			if(same){
				collect.erase(begin(collect) + j);
				collect.erase(begin(collect) + i);
				found = true;
				j = n;
				break;
			}
		}

		if(found == false) return false;
	}


	if(collect.size() == 0) return true;

	auto str = collect[0];
	rep(i,h) if(str[i] != str[h-1-i]) return false;

	return true;
}

int main(void){
