	rep(i,h) cin >> s[i];

	bool ok = false;

	const int n = h;
	const int k = (n + 1) /2;

	int comb = (1 << k) - 1;

	while(comb < (1 << n)){
		int x = comb & -comb, y = comb + x;
		comb = ((comb & ~y) / x >> 1) | y;

		one.clear(),other.clear();
		rep(i,h){
			if(comb & (1 << i)) 
				one.push_back(i);
			else
				other.push_back(i);
		}

