set<pair<int, int>>p;
int nouse = -1;

int solve(int r){
	vector<string>tate(W);
	for (int i = 0; i < W; i++)tate[i].resize(H);
	for (int i = 0; i < W; i++) {
		int idx = 0;
		fore(x, p) {
			tate[i][idx] = S[x.first][i];
			tate[i][H-1-idx] = S[x.second][i];
			idx++;
		}
		if (H % 2 == 1)tate[i][H/2] = S[r][i];
	}

	int rem = -1;
	set<int>vis;
	for (int i = 0; i < W; i++) {
		if (vis.count(i))continue;
		for (int j = i + 1; j < W; j++) {
			if (vis.count(j) || i == j)continue;
			int ok = 1;
			for (int k = 0; k < H; k++)if (tate[i][k] != tate[j][H-1-k])ok = 0;
			if (ok) { vis.insert(i); vis.insert(j); break; }
		}
	}
	for (int i = 0; i < W; i++)if(!vis.count(i))rem = i;

	if (W % 2 == 0) {
		if (vis.size() != W)return 0;
		else return 1;
	}
	else {
		if (vis.size() != W - 1)return 0;
		for (int i = 0; i < H; i++)if (tate[rem][i] != tate[rem][H - 1 - i])return 0;
		return 1;
	}
}

int dfs(){
	if (st.size() == 0)return solve(nouse);
	int beg = *st.begin();
	set<int>temp = st;
	fore(x,temp) {
		if (x != beg) {
			st.erase(x);
			st.erase(beg);
			p.insert({x,beg});
			if (dfs())return 1;
			st.insert(x);
			st.insert(beg);
			p.erase({x,beg});
		}
	}
	return 0;
}

int b(){
	if (H % 2 == 0)return dfs();
	else {
		for (int i = 0; i < H; i++) {
			st.erase(i);
			nouse = i;
			if (dfs())return 1;
			st.insert(i);
		}
		return 0;
	}
}

