//探索 (ICPC2017-Asia-Bと本質は同じ)
int kumi[8][2];	//対称な位置にある元のペア
bool dfs(int rem, int depth = 0) {
	int i, j;
	vector<int> perm;

	if (w - depth * 2 == 1) {
		i = 0; while ((rem >> i) % 2 == 0) i++;
		perm.resize(w);
		for (j = 0; j < depth; j++) {
			perm[j] = kumi[j][0];
			perm[w - 1 - j] = kumi[j][1];
		}
		perm[(w - 1) / 2] = i;
		if (check(perm)) return true;
		return false;
	}
	if (w == depth * 2) {
		perm.resize(w);
		for (j = 0; j < depth; j++) {
			perm[j] = kumi[j][0];
			perm[w - 1 - j] = kumi[j][1];
		}
		if (check(perm)) return true;
		return false;
	}

	for (i = 0; i < w; i++) if ((rem >> i) & 1) break;
	for (j = i + 1; j < w; j++) {
		if ((rem >> j) & 1) {
			kumi[depth][0] = i;
			kumi[depth][1] = j;
			bool res = dfs(rem - (1 << i) - (1 << j), depth + 1);
			if (res) { return true; }
		}
	}
	return false;
}

