int H, W;
int H2, W2;
char GRID[12][12];
int odd = -1;
void swapGRID(int m, int i, int j) {
	if (m) {
		for (int k = 0; k < H; k++)swap(GRID[k][i], GRID[k][j]);
	}
	else {
		for (int k = 0; k < W; k++)swap(GRID[i][k], GRID[j][k]);
	}
}
bool is_() {
	bool flag = true;

	if (H % 2 && W % 2) {
		if (GRID[H2][W2] != odd)return false;
	}

	for (int i = 0; flag && i < H; i++) {
		for (int j = 0; flag && j < W; j++) {
			if (GRID[i][j] != GRID[H - 1 - i][W - 1 - j])flag = false;
		}
	}
	return flag;
}

int main() {
	cin >> H >> W;
	H2 = H / 2; W2 = W / 2;
	vector<int>cnt(26);
	for (int i = 0; i < H; i++)for (int j = 0; j < W; j++) {
		char c; cin >> c;
		GRID[i][j] = c;
		cnt[c - 'a']++;
	}
	int oddcnt = 0;
	for (int i = 0; i < 26; i++) {
		if (cnt[i] % 2) {
			oddcnt++;
			odd = i;
		}
	}

	if (oddcnt > 1) {
		cout << "NO" << endl;
		return 0;
	}
	else if (oddcnt == 1 && !(H % 2 && W % 2)) {
		cout << "NO" << endl;
		return 0;
	}
	else if (oddcnt == 0 && H % 2 && W % 2) {
		cout << "NO" << endl;
		return 0;
	}

	if (H == 1 && W == 1) {
		cout << "YES" << endl;
		return 0;
	}

	Timer tmr;

	Xor128 rnd;
	int loop = 0;
	while (1) {
		if (loop % 100000 == 0) {
			if (tmr.getTime()>1.9)break;
		}

		int m, i, j;
		m = rnd.rand() % 2;
		if (H == 1)m = 1;
		if (W == 1)m = 0;

		if (m) {
			i = rnd.rand() % W;
			do {
				j = rnd.rand() % W;
			} while (i == j);
		}
		else {
			i = rnd.rand() % H;
			do {
				j = rnd.rand() % H;
			} while (i == j);
		}


		swapGRID(m, i, j);
		if (is_()) {
			cout << "YES" << endl;
			return 0;
		}

		loop++;
	}
	cout << "NO" << endl;

	return 0;
}

