bool synmetry (string s1, string s2) {
  int n = s1.size();
  REP(i, n) {
    if(s1[i] != s2[n - 1 - i]) {
      return false;
    }
  }
  return true;
}

bool check(string s[]) {
  bool used[W];
  REP(j, W) used[j] = false;
  bool center_is_remain = false;
  if(W % 2 == 1) center_is_remain = true;
  REP(j, W) {
    if(used[j]) continue;
    bool flag = false;
    REP(k, W) {
      if(k == j || used[k]) continue;
      if(synmetry(s[j], s[k])) {
        flag = true;
        used[j] = true;
        used[k] = true;
      }
    }
    if(!flag) {
      if(center_is_remain && synmetry(s[j], s[j])) {
        center_is_remain = false;
        flag = true;
        used[j] = true;
      }
    }
    if(!flag) return false;
  }
  return true;
}

