    // cout << endl << "swaps ";
    // REP(i, swaps.size()) cout << swaps[i].first << "-" << swaps[i].second << ", ";
    // cout << endl;
    // REP(j, W) cout << s[j] << endl;
    // cout << "check " << check(s) << endl;
    return check(s);
  }
  if(used[crt]) {
    return dfs(used, swaps, crt + 1);
  }
  used[crt] = true;
  REP(i, H) {
    if(used[i]) continue;
    vpi tmp_swaps = swaps;
