bool dfs2(int32 now){
	if(~dp[now]) return dp[now];
	if(now == 0) return dp[now] = 1;
	if(__builtin_popcount(now) == 1){
		REP(i, W){
			if(now >> i & 1){
				if(pack[i][i]) return dp[now] = 1;
				return dp[now] = 0;
			}
		}
	}
	dp[now] = 0;
	REP(i, W){
		FOR(j, i+1, W){
			if(now >> i & 1 && now >> j & 1){
				if(pack[i][j]) dp[now] |= dfs2(now^(1<<i)^(1<<j));
			}
		}
	}
	return dp[now];
}

