bool match(int n){
  //printG(n);
  int first = -1;
  int c = 0;
  for(int i=0; i<n; i++){
    if(!vis[i]){
      first = i;
      c++;
    }
  }
  if(c <= 1){
    return true;
  }
  if(c%2 == 1){
    bool flag = false;
    for(int i=0; i<n; i++){
      vis[i] = true;
      flag |= match(n);
      vis[i] = false;
    }
    return flag;
  }
  bool flag = false;
  for(int i=0; i<n; i++){
    if(i == first)
      continue;
    if(!vis[i] && G[first][i]){
      vis[first] = true;
      vis[i] = true;
      flag |= match(n);
      vis[first] = false;
      vis[i] = false;
    }
  }
  return flag;
}

