bool odd; bool even;
int h, w;
bool sym() {
	int used[12] = {};
	int rest = 0;
	if (odd)rest = 1;
	rep(j, w) {
		if (!used[j]) {
			used[j] = 1;
			bool exi = false;
			rep(k, w) {
				if (used[k])continue;
				bool ok = true;
				rep(i, h) {
					if (t[i][j] != t[h - 1 - i][k])ok = false;
				}
				if (ok) {
					used[k] = 1; exi = true; break;
				}
			}
			if (!exi) {
				bool ok = true;
				rep(i, h) {
					if (t[i][j] != t[h - 1 - i][j])ok = false;
				}
				if (ok) {
					if (rest)rest--;
					else return false;
				}
				else return false;
			}
		}
	}
	return true;
}
bool dfs(int x) {
	int nex = -1; int cnt = 0;
	rep(i, h) {
		if (!(x&(1 << i)))cnt++;
		if (nex >= 0)continue;
		if (x&(1 << i)) {
			nex = i; x^=(1 << i);
		}
	}
	if (cnt == h) {
		return sym();
	}
	else if (cnt == h-1) {
		rep(j, w) {
			t[h / 2][j] = ori[nex][j];
		}
		return sym();
	}
	else {
		bool g = false;
		rep(j, w) {
			t[cnt / 2][j] = ori[nex][j];
		}
		rep(i, h) {
			if (x&(1 << i)) {
				x ^= (1 << i);
				rep(j, w) {
					t[h - 1 - cnt / 2][j] = ori[i][j];
				}
				if (dfs(x))g = true;
				x ^= (1 << i);
			}
		}
		return g;
	}
}
int main() {
	cin >> h >> w;
	if (w % 2)odd = true;
	else odd = false;
	if (h % 2)even = false;
	else even = true;
	rep(i, h) {
		string s; cin >> s;
		rep(j, w) {
			ori[i][j] = s[j];
		}
	}
	if (dfs((1<<h)-1))cout << "YES" << endl;
	else cout << "NO" << endl;
	return 0;
}

