#include <bits/stdc++.h>
using namespace std;

int h, w;
string s[15];
int pos[15];
int rpos[15];
int cnt;

bool matching(int i, int j) {
  for (int hi = 0; hi < h; hi++) {
    if (s[rpos[hi]][i] != s[rpos[h - 1 - hi]][j]) {
      return false;
    }
  }
  return true;
}

bool check() {
  vector<bool> matched(12, false);
  bool single = w % 2 == 1 ? false : true;
  for (int wi = 0; wi < w; wi++) {
    if (matched[wi]) continue;
    bool m = false;
    for (int wj = wi + 1; wj < w; wj++) {
      if (matching(wi, wj)) {
        m = true;
        matched[wj] = true;
        break;
      }
    }
    if (!m) {
      if (single) return false;
      for (int hi = 0; hi < h / 2; hi++) {
        if (s[rpos[hi]][wi] != s[rpos[h - 1 - hi]][wi]) return false;
      }
      single = true;
    }
  }
  return true;
}

bool traverse(int x) {
  if (x * 2 == h) {
    return check();
  }
  for (int hi = 0; hi < h; hi++) {
    if (pos[hi] == -1) {
      pos[hi] = x;
      rpos[x] = hi;
      if (x * 2 + 1 == h) {
        bool result = check();
        pos[hi] = -1;
        return result;
      } else {
        for (int hj = hi + 1; hj < h; hj++) {
          if (pos[hj] == -1) {
            pos[hj] = h - 1 - x;
            rpos[h - 1 - x] = hj;
            bool result = traverse(x + 1);
            pos[hj] = -1;
            if (result) {
              pos[hi] = -1;
              return true;
            }
          }
        }
        pos[hi] = -1;
        return false;
      }
    }
  }
}

int main() {
  cin >> h >> w;
  for (int hi = 0; hi < h; hi++) {
    cin >> s[hi];
  }
  memset(pos, -1, sizeof(pos));
  bool answer = traverse(0);
  swap(s[0], s[h - 1]);
  answer |= traverse(0);
  cout << (answer ? "YES" : "NO") << endl;
  return 0;
}

#include <bits/stdc++.h>

using namespace std;

typedef pair <int, int> pii;

vector < pii > v;
string S[15];
int n, m;
bool ans = false;

bool check(){
	for(auto f : v){
		S[f.first].swap(S[f.second]);
	}
	map <string, int> mp;
	string a, b;
	for(int i = 0; i < m; ++i){
		a = "";
		for(int j = 0; j < n; ++j){
			a += S[j][i];
		}
		mp[a] += 1;
	}
	int res = true;
	int cnt = 0;
	for(auto u : mp){
		b = u.first;
		reverse(b.begin(), b.end());
		if(b == u.first){
			if(u.second % 2) cnt += 1;
			if(cnt > 1){
				res = false;
				break;
			}
		}
		else{
			if(u.second != mp[b]){
				res = false;
				break;
			}
		}
	}
	res &= (cnt < 2);
	for(auto f : v){
		S[f.first].swap(S[f.second]);
	}
	return res;
}

void fn(int mask){
	if(ans) return;
	int sz = __builtin_popcount(mask);
	if(sz <= 1){
		ans |= check();
		return;
	}
	int k;
	for(int i = n - 1; i >= 0; --i){
		if(mask & (1 << i)){
			mask ^= (1 << i);
			fn(mask);
			for(int j = 0; j < i; ++j){
				if(mask & (1 << j)){
					v.push_back({i, j});
					fn(mask ^ (1 << j));
					v.pop_back();
				}
			}
			break;
		}
	}
}

int main(){
	cin >> n >> m;
	int mask = 0;
	for(int i = 0; i < n; ++i){
		cin >> S[i];
		mask |= (1 << i);
	}
	fn(mask);
	if(ans) cout << "YES\n";
	else cout << "NO\n";
}

