    S=vector<string>(H);
    for(int i = 0; i < H; ++i){
        cin >> S[i];
    }
    solve();
}

void g(){
    vector<string> s(W);
    rep(i,H)rep(j,W){
        s[j]+=S[ord[i]][j];
    }
    map<string,ll> mp;
    rep(i,W){
        string rev=s[i];
        reverse(all(rev));
        if(mp.count(rev))mp[rev]--;
        else mp[s[i]]++;
    }
    ll sum=0;
    for(auto &p:mp){
        if(!p.second)continue;
        sum+=p.second;
        string rev=p.first;
        reverse(all(rev));
        if(rev!=p.first)return;
    }
    ok|=sum<=1;
}
void f(ll b,ll d){
    if(b==(1<<H)-1){
        g();
        return;
    }
    ll l=d;
    while(b>>l&1)++l;
    ord[d]=l;
    b|=1<<l;
    if(b==(1<<H)-1){
        g();
        return;
    }
    rep(r,l,H){
        if((b>>r&1)==0){
            ord[H-1-d]=r;
            f(b|1<<r,d+1);
        }
    }
}
void solve(){
    ord=vl(H);
    f(0,0);
    cout<<(ok?YES:NO)<<endl;
}

