	return equal(s.begin(), s.end(), s.rbegin());
}

bool valid(const vector<int> &perm) {
	fori(i, 0, n) {
		buffer[i] = mat[i];
	}

	multiset<string> S;
	fori(i, 0, n) {
		fori(j, 0, m) {
			buffer[i][j] = mat[i][perm[j]];
		}

		S.insert(buffer[i]);
	}

	while(S.size() > 1) {
		string first = *S.begin(); S.erase(S.begin());

		string revF = first;
		reverse(revF.begin(), revF.end());

		if(S.count(revF)) {
			S.erase(S.find(revF));	
		}
		else {
			return false;
		}
	}

	if(S.size() == 1) {
		string f = *S.begin();

		if(!palindrome(f)) {
			return false;
		}
	}

	return true;
}

void gen(int last, int index) {
	if(2 * index == m || (m - 2 * index == 1 && last != -1)) {
		if(last != -1) {
			fori(i, 0, m) {
				if(!used[i]) {
					state[m / 2] = i;
					break;
				}
			}
		}

		if(valid(state)) {
			die("YES");
		}

		return;
	}

	if(last == -1) {
		fori(i, 0, m) {
			if(!used[i]) {
				used[i] = true;
				state[index] = i;
				gen(i, index);
				used[i] = false;
				break;
			}
		}
	}
	else {
		fori(i, last + 1, m) {
			if(!used[i]) {
				used[i] = true;
				state[m - index - 1] = i;
				gen(-1, index + 1);
				used[i] = false;
			}
		}
	}
}

