		for(int i=0; i<h; i++) {
			if(used[i]) continue;
			used[i]=1;
			order[m]=i;
			if(dfs(m+1,k)) return true;
			used[i]=0;
		}
		return false;
	}
	for(int i=k+1; i<h; i++) {
		if(used[i]) continue;
		used[i]=1;
		order[m]=i;
		if(m%2) {
			if(dfs(m+1,k)) return true;
		} else {
			if(dfs(m+1,i)) return true;
		}
	}
	return false;
}
