void solve()
{
	mp.clear();
	int top = 0;
	for (register int j = 1; j <= px; j++) a[++top] = p[j];
	int qxt = qx;
	if (px != qx) a[++top] = q[qx--];
	for (register int j = qx; j >= 1; j--) a[++top] = q[j];
	qx = qxt;
	for (register int j = 1; j <= m; j++) {
		h[j] = 0;
		for (register int i = 1; i <= n; i++) 
			h[j] = h[j]*bas+str[a[i]][j];
