  if(i == h / 2){
    vector<string> t(h, string(w, '0'));
    rep(j, sz(v)){
      if(j % 2 == 0){
        t[j/2] = s[v[j]];
      }else{
        t[h-1-j/2] = s[v[j]];
      }
    }
    if(h % 2 == 1){
      rep(j, h){
        if(!used[j]){
          t[h/2] = s[j];
          break;
        }
      }
    }
    vector<string> c(w, string(h, '0'));
