bool calc(vector<string> const &chars, vector<int> const &hswap, vector<int> const &wswap, vector<vector<int>> const &hgv, vector<vector<int>> const &wgv) {
    for (auto hs: hswap) {
        for (auto ws: wswap) {
            if (hs == -1 || ws == -1) continue;
            assert(hgv[hs].size() == 2);
            assert(wgv[ws].size() == 2);
            int y1 = hgv[hs][0];
            int x1 = wgv[ws][0];
            int y2 = hgv[hs][1];
            int x2 = wgv[ws][1];
            if (chars[y1][x1] != chars[y2][x2] || chars[y2][x1] != chars[y1][x2]) return false;
        }
    }
    return true;
}

pair<vector<int>,int> organize(vector<map<char, int>> const &cnt, int upto) {
    vector<int> gs(upto, -1);
    int g = 0;
    for (int i = 0; i < upto; i++) {
        bool exists = false;
        if (gs[i] != -1) continue;
        for (int j = i+1; j < upto; j++) {
            if (gs[j] != -1) continue;
            if (cnt[i] == cnt[j]) {
                exists = true;
                gs[i] = gs[j] = g;
            }
        }
        if (exists) g++;
    }
    if (count(gs.begin(), gs.end(), -1) > 1) return make_pair(gs, -1);
    return make_pair(gs, g);
}

class groupings_generator {
    private:
        vector<vector<int>> const &orig;
        vector<int> pos;
        vector<vector<int>> perms;
        vector<vector<int>> curr;

        void calc_curr() {
            curr = orig;
            for (int i = pos.size()-1; i >= 0; i--) {
                curr.erase(curr.begin() + pos[i]);
            }

            for (int i = pos.size()-1; i >= 0; i--) {
                int j = pos[i];
                vector<vector<int>> ins(orig[j].size() / 2);
                for (size_t k = 0; k < orig[j].size(); k++) {
                    ins[perms[i][k]].push_back(orig[j][k]);
                }
                curr.insert(curr.begin() + j, ins.begin(), ins.end());
            }
            // print_current();
        }

        // void print_current() {
        //     cerr << "[";
        //     bool is_first = true;
        //     for (auto const &r: curr) {
        //         if (is_first) is_first = false;
        //         else          cerr << " ";
        //         cerr << "(" << r[0] << "," << r[1] << ")";
        //     }
        //     cerr << "]" << endl;
        // }

    public:
        groupings_generator(vector<vector<int>> const &orig) : orig(orig) {
            for (size_t i = 0; i < orig.size(); i++) {
                if (orig[i].size() > 2) {
                    pos.push_back(i);
                    vector<int> perm(orig[i].size());
                    iota(perm.begin(), perm.end(), 0);
                    for (auto &x: perm) x /= 2;
                    perms.push_back(move(perm));
                }
            }
            calc_curr();
        }

        vector<vector<int>> const &get_curr() { return curr; }
        bool gen_next() {
            bool flag = false;
            for (int i = pos.size()-1; i >= 0; i--) {
                if (next_permutation(perms[i].begin(), perms[i].end())) {
                    flag = true;
                    break;
                }
            }
            calc_curr();
            return flag;
        }
};

int main() {
    int h, w;
    cin >> h >> w;
    vector<string> chars(h);
    for (int i = 0; i < h; i++) {
        cin >> chars[i];
    }

    vector<map<char,int>> cnth(h);
    vector<map<char,int>> cntw(w);
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            cnth[i][chars[i][j]]++;
            cntw[j][chars[i][j]]++;
        }
    }

    vector<int> hg, wg;
    int hgc, wgc;
    tie(hg, hgc) = organize(cnth, h);
    tie(wg, wgc) = organize(cntw, w);
    if (hgc == -1 || wgc == -1) { cout << "NO" << endl; return 0; }

    vector<vector<int>> hgv(hgc), wgv(wgc);
    for (int i = 0; i < h; i++) {
        if (hg[i] != -1) hgv[hg[i]].push_back(i);
    }
    for (int i = 0; i < w; i++) {
        if (wg[i] != -1) wgv[wg[i]].push_back(i);
    }

    groupings_generator hgen(hgv);
    groupings_generator wgen(wgv);
    do {
        do {
            auto const &hgv = hgen.get_curr();
            auto const &wgv = wgen.get_curr();

            vector<int> hswap(hgv.size()), wswap(wgv.size());
            iota(hswap.begin(), hswap.end(), 0);
            iota(wswap.begin(), wswap.end(), 0);
            do {
                do {
                    if (calc(chars, hswap, wswap, hgv, wgv)) {
