                        return 0;
                    }
                } while (next_permutation(wswap.begin(), wswap.end()));
            } while (next_permutation(hswap.begin(), hswap.end()));
        } while (wgen.gen_next());
    } while (hgen.gen_next());

    cout << "NO" << endl;

