                    bool bue = false;
                    reverse(all(t[i]));
                    for(int j = i+1; j < w; j++){
                        if(t[i] == t[j]){
                            used[i] = used[j] = 1;
                            bue = true;
                            break;
                        }
                    }
                    if(!bue){
                        bool ch = false;
                        rep(j,h){
                            if(t[i][j] != t[i][h-1-j]){
