                            used[i] = 1;
                        }
                    }
                }
            }
            return true;
        }else{
            rep(i,w){
                if(!used[i]){
                    bool bue = false;
                    reverse(all(t[i]));
                    for(int j = i+1; j < w; j++){
                        if(t[i] == t[j]){
                            used[i] = used[j] = 1;
                            bue = true;
                            break;
                        }
                    }
                    if(!bue) return false;
                }
            }
            return true;
        }
    }else{
        for(;i < h; i++){
            if(id[i] < 0){
                for(int j = i+1; j < h; j++){
