bool check2(ll x) {
  set<ll> used;
  for (ll i = 0; i < h; i++) if (i != x) {
    for (ll j = 0; j < h; j++) if (j != x) {
      if (i != j && !ng[i][j] && used.count(i) == 0 && used.count(j) == 0) {
        used.insert(i);
        used.insert(j);
      }
    }
  }
  return used.size() == h-1;
}

bool check() {
  if (h % 2 == 1) {
    for (ll i = 0; i < h; i++) if (!ng[i][i] && check2(i)) return true;
    return false;
  }
  set<ll> used;
  for (ll i = 0; i < h; i++) for (ll j = 0; j < h; j++) {
    if (i != j && !ng[i][j] && used.count(i) == 0 && used.count(j) == 0) {
      used.insert(i);
      used.insert(j);
    }
  }
  return used.size() == h;
}

bool dfs() {
  vector<ll> rest;
  for (ll i = 0; i < w; i++) if (!used[i]) rest.push_back(i);
  if (rest.size() == 0) return check();
  bool cp[12][12];
  for (ll i = 0; i < h; i++) for (ll j = 0; j < h; j++) cp[i][j] = ng[i][j];
  if (rest.size() == 1) {
    ll p = rest[0];
    for (ll i = 0; i < h; i++) for (ll j = 0; j < h; j++) {
      if (s[i][p] != s[j][p]) ng[i][j] = true;
    }
    if (check()) return true;
    for (ll i = 0; i < h; i++) for (ll j = 0; j < h; j++) ng[i][j] = cp[i][j];
    return false;
  }
  for (ll a = 0; a < rest.size(); a++) {
    for (ll b = a+1; b < rest.size(); b++) {
      ll x = rest[a], y = rest[b];
      for (ll i = 0; i < h; i++) for (ll j = 0; j < h; j++) {
        if (s[i][x] != s[j][y] || s[i][y] != s[j][x]) ng[i][j] = true;
      }
      if (!check()) {
        for (ll i = 0; i < h; i++) for (ll j = 0; j < h; j++) ng[i][j] = cp[i][j];
        continue;
      }
      used[x] = used[y] = true;
      if (dfs()) return true;
      for (ll i = 0; i < h; i++) for (ll j = 0; j < h; j++) ng[i][j] = cp[i][j];
      used[x] = used[y] = false;
    }
  }
  return false;
}

