int H,W;
bool DFS(vector<string> &S,vector<int> used,vector<pair<int,int>> p){
    int cnt=0;
    for(int i=0;i<W;i++) if(used[i]==0) cnt++;

    if(cnt==0){
        vector<int> used2(H);
        for(int i=0;i<H;i++){
            if(used2[i]) continue;
            vector<int> ok(H,1);
            for(int j=i+1;j<H;j++){
                for(int k=0;k<p.size();k++){
                    int a=p[k].first,b=p[k].second;
                    if(b==-1){
                        if(S[i][a]!=S[j][a]) ok[j]=0;
                    }else{
                        if(S[i][a]!=S[j][b]) ok[j]=0;
                        if(S[i][b]!=S[j][a]) ok[j]=0;
                    }
                }
            }

            for(int j=i+1;j<H;j++){
                if(ok[j]&&used2[j]==0){
                    used2[i]=1;
                    used2[j]=1;
                    break;
                }
            }
        }

        int cnt2=0,wh=-1;

        for(int i=0;i<H;i++){
            if(used2[i]==0){
                cnt2++;
                wh=i;
            }
        }

        if(cnt2==0) return true;
        else if(cnt2==1){
            for(int k=0;k<p.size();k++){
                int a=p[k].first,b=p[k].second;
                if(b!=-1&&S[wh][a]!=S[wh][b]) return false;
            }
            //for(int k=0;k<p.size();k++) cout<<p[k].first<<" "<<p[k].second<<endl;
            return true;
        }else return false;
    }else if(cnt==1){
        for(int i=0;i<W;i++){
            if(used[i]==0){
                used[i]=1;
                p.push_back({i,-1});
            }
        }
        return DFS(S,used,p);
    }else{
        for(int i=0;i<W;i++){
            if(used[i]) continue;
            for(int j=i+1;j<W;j++){
                if(used[j]) continue;

                used[i]=1;
                used[j]=1;
                p.push_back({i,j});

                if(DFS(S,used,p)) return true;

                used[i]=0;
                used[j]=0;
                p.pop_back();
            }
        }

        return false;
    }
}

