template < typename Value >
auto transpose(std::vector< std::vector< Value > > const& grid) {
  int h = grid.size();
  int w = grid.front().size();
  auto ret = std::vector< std::vector< Value > > (w, std::vector< Value >(h));
  for (auto i = 0; i < h; i++) {
    for(auto j = 0; j < w; j++) {
      ret.at(j).at(i) = grid.at(i).at(j);
    }
  }
  return ret;
}

int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  auto make_index_pairs = [&] (int n) {
    int N = 2 * n;
    std::vector<std::vector<std::pair<int,int>>> ans;
    std::vector<std::pair<int,int>> now;
    std::vector<int> ckd(N,false);
    auto dfs = [&] (auto&& dfs) -> void {
      if ((int)now.size() == n) {
        ans.emplace_back(now);
        return;
      }

      int i = std::find(all(ckd), false) - ckd.begin();
      assert(0 <= i && i < N);
      ckd.at(i) = true;

      rep(j,0,N) {
        if (ckd.at(j)) continue;
        ckd.at(j) = true;
        now.emplace_back(i,j);
        dfs(dfs);
        ckd.at(j) = false;
        now.pop_back();
      }
      ckd.at(i) = false;
    };
    dfs(dfs);
    return ans;
  };

  int h, w; std::cin >> h >> w;
  auto grid = make_vector<2,char>(h,w);
  rep(i,0,h) rep(j,0,w) {
    char c; std::cin >> c;
    at(grid,i,j) = c;
  }
  auto index_pairs = make_index_pairs(w/2);
  debug(h,w,grid,index_pairs);

  auto cal = [&] (auto grid, auto&& index_pair) {

    #ifndef STOPIT
      for (auto&& v : grid) {
        debug(v);
      }
      debug("||");
    #endif

    int sz = index_pair.size(), Sz = 2 * sz;
    for (auto&& v : grid) {
      std::vector<char> new_v(Sz);
      rep(k,0,sz) {
        int i,j; std::tie(i,j) = index_pair.at(k);
        new_v.at(k) = v.at(i);
        new_v.at(Sz-1-k) = v.at(j);
      }
      new_v.swap(v);
    }
    #ifndef STOPIT
      for (auto&& v : grid) {
        debug(v);
      }
      debug(index_pair);
      debug("");
    #endif

    while (!grid.empty()) {
      auto v = grid.back(); grid.pop_back();
      std::reverse(all(v));
      auto it = std::find(all(grid), v);
      if (it == grid.end()) return false;
      grid.erase(it);
    }
    return true;
  };

  // skip the middle
  rep(x,0,h) rep(y,0,w) {
    auto now = grid;
    if (h%2==0) {
      if (x!=0) continue;
    } else {
      auto it = now.begin() + x;
      auto v = *it;
      if (v != std::vector<char>(v.rbegin(), v.rend())) continue;
      now.erase(it);
    }
    if (w%2==0) {
      if (y!=0) continue;
    } else {
      now = transpose(now);
      auto it = now.begin() + y;
      auto v = *it;
      if (v != std::vector<char>(v.rbegin(), v.rend())) continue;
      now.erase(it);
      now = transpose(now);
    }

    for (auto&& v : index_pairs) {
      bool res = cal(now,v);
      if (res) {
        std::cout << "YES" << std::endl;
        exit(0);
      }
    }
  }
  std::cout << "NO" << std::endl;
  return 0;
}

