using namespace std;


int H, W;

int perm[12];
string s[12];

bool same(const string &s, string t) {
    reverse(t.begin(), t.end());
    return s == t;
}

string rev(string s) {
    reverse(s.begin(), s.end());
    return s;
}

void check() {
    string ss[H];
    for (int i = 0; i < H; i++) ss[i] = s[i];
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            ss[i][j] = s[i][perm[j]];
        }
    }
    map<string, vector<string>> grp;

    for (int i = 0; i < H; i++) {
        grp[min(ss[i], rev(ss[i]))].push_back(ss[i]);
    }

    bool ok = true;
    int oddCount = 0;
    for (auto gg: grp) {
        auto &g = gg.second;
        sort(g.begin(), g.end());
        oddCount += g.size() % 2;
        for (int i = 0; i <= g.size() / 2; i++) {
            if (!same(g[i], g[g.size() - i - 1])) {
                ok = false;
            }
        }
    }
    if (ok) {
        if (H % 2) {
            if (oddCount == 1) ok = true;
            else ok = false;
        } else {
            if (oddCount == 0) ok = true;
            else ok = false;
        }
    }
    //for (int i = 0; i < W; i++) cout << perm[i] << " ";
    //cout << endl;
    if (ok) {
        cout << "YES" << endl;
        exit(0);
    }

}

void evenDfs(int x, int bit) {

    int mx = -1;
    for (int i = 0; i < W; i++) {
        if (bit >> i & 1) {
            mx = i;
            break;
        }
    }
    if (bit == 0) {
        // even
        check();
        return;
    }
    for (int i = mx + 1; i < W; i++) {
        if (bit >> i & 1) {
            perm[x] = mx;
            perm[W - 1 - x] = i;
            evenDfs(x + 1, bit - (1 << mx) - (1 << i));
        }
    }

}

int main() {
    cin >> H >> W;
    for (int i = 0; i < H; i++) cin >> s[i];
    if (W % 2 == 0) {
        evenDfs(0, (1 << W) - 1);
    } else {
        for (int k = 0; k < W; k++) {
            perm[W / 2] = k;
            evenDfs(0, (1 << W) - 1 - (1 << k));
        }
    }

    cout << "NO" << endl;
}

