string grid[12];
bool match[12],match_c[12],found;
int H,W,cnt=0;
vector<pii> match_row;
void dfs(int idx){
	if(found) return;
	if(idx>=H){
		int match_num=0;
		memset(match_c,0,sizeof match_c);
		for(int i=0;i<W;i++){
			if(match_c[i]) continue;
			for(int j=i+1;j<W;j++){
				if(match_c[j]) continue;
				bool succ=true;
				for(int k=0;k<(int)match_row.size() && succ;k++)
					if(grid[match_row[k].first][i]!=grid[match_row[k].second][j])
						succ=false;
				if(!succ){
					succ=true;
					for(int k=0;k<(int)match_row.size() && succ;k++)
						if(grid[match_row[k].first][j]!=grid[match_row[k].second][i])
						succ=false;
				}
				if(succ){
					match_c[i]=match_c[j]=true;
					match_num++;
					break;
				}
			}
		}
		if(match_num==W/2) found=true;
	}else{
		if(match[idx]) dfs(idx+1);
		else{
