bool valid(const std::vector<Int>& xs) {
   bool checked[16] = {};
   for(Int i = 0; i < h; ++i) {
      for(Int k = i + 1; k < h; ++k) {
         if( checked[k] ) continue;
         bool success = true;
         for(Int j = 0; j < w; ++j) {
            if( ss[i][xs[j]] != ss[k][xs[w-j-1]] ) {
               success = false;
            }
         }
         if( success ) {
            checked[i] = checked[k] = true;
         }
      }
   }
   Int t = 0;
   for(Int i = 0; i < h; ++i) {
      if( checked[i] ) t += 1;
   }
   if( h % 2 == 1 and t == h - 1 ) {
      for(Int i = 0; i < h; ++i) {
         if( not checked[i] ) {
            for(Int k = 0; k < h; ++k) {
               bool ok = true;
               for(Int j = 0; j < w; ++j) {
                  if( ss[k][xs[j]] != ss[k][xs[w-j-1]] ) {
                     ok = false;
                  }
                  if( ss[i][xs[j]] != ss[k][xs[w-j-1]] ) {
                     ok = false;
                  }
               }
               if( ok ) {
                  t += 1;
                  break;
               }
            }
         }
      }
   }
   if( h == t ) {
      return true;
   }
   return false;
}

void stage2(std::vector<Int>& xs, std::vector<bool>& checked) {
   if( (Int)xs.size() == w ) {
      if( valid(xs) ) {
         puts("YES");
         exit(0);
      }
      return;
   }
   for(Int i = 0; i < w; ++i) {
      if( checked[i] ) continue;
      xs.push_back(i);
      checked[i] = true;
      stage2(xs, checked);
      checked[i] = false;
      xs.pop_back();
   }
}

void stage1(std::vector<Int>& xs, std::vector<bool>& checked) {
   if( (Int)xs.size() >= w/2+1 ) {
      stage2(xs, checked);
   }
   Int begin = (Int)xs.size() == 0 ? 0 : xs.back()+1;
   for(Int i = begin; i < w; ++i) {
      if( checked[i] ) continue;
      xs.push_back(i);
      checked[i] = true;
      stage1(xs, checked);
      checked[i] = false;
      xs.pop_back();
   }
}

