		for(int i=0; i<H; i++){
			s.push_back(S[f[i]][j]  );
		}
		u.push_back(s);
	}
	vi used(W);
	int center = 0;
	for(int j=0; j<W; j++){
		if(used[j])continue;
		bool ok = false;
		string s1 = u[j];
		reverse(s1.begin(), s1.end());
		for(int k=j+1; k<W; k++){
			if(used[k])continue;
			string s2 = u[k];

			if(s1==s2){
				ok = true;
				used[k]=1;
			}
		}
		if(!ok){
			if(s1==u[j])center++;
			else return false;
		}
	}
	return center<=1;
}

vector<int> gen(int p){
	int w = H - (H+1)%2;
	//deb(p);deb(w);debl;
	vi used(H);
	vi ret(H);
	if(H%2==1){
		int n = p%w; p/=w; w-=2;
		ret[H/2] = n;
		used[n]=1;
	}
	for(int step=0; step<H/2; step++){
		int k=0;
		while(used[k])k++;
		ret[step]=k;
		used[k]=1;
		k++;		while(used[k])k++;
		//debug(used);
		//debug(ret);
		{
			int n = p%w; p/=w; w-=2;
			//debug(n);
			for(int j=0; j<n; j++){
				k++; while(used[k])k++;
			}
			ret[H-1-step] = k;
			used[k]=1;
		}
	}
	//debug("gen_end");
	return ret;

}

