  rep(i,s.size()){
    if(used[i]) continue;
    char sc = s[i];
    char tc = t[i];
    rep(j,s.size()){
      if(i==j) continue;
      if(used[j]) continue;
      char sb = s[j];
      char tb = t[j];
      if(sc == tb && tc == sb){
        used[i] = true;
        used[j] = true;
        break;
      }
    }
  }
  int cnt = 0;
  rep(i,s.size()){
    if(used[i]){
      cnt++;
    }
  }
  return cnt;
}


