int num(char c1, char c2) {
	return (c1 - 'a') * 100 + (c2 - 'a');
}

int used[max_N][3000], g[max_N][max_N], was[max_N];

void rec(int n) {
	if (n == N / 2) {
		int m = 0, cur = 0, pt = 0;
		while (cur < N) {
			if (pt < n && cur == A[pt]) {
				pt++;
			}	else {
				B[m++] = cur;
			}
			cur++;
		}
		do {
			memset(& g, 0, sizeof(g));
			memset(& was, 0, sizeof(was));
			for (int i = 0; i < n; i++) {
				int a = A[i], b = B[i];
				for (int j = 0; j < M; j++) {
					int need = num(c[b][j], c[a][j]);
					for (int k = 0; k < j; k++) {
						if (used[k][need]) {
							g[k][j]++;
						}
					}
					used[j][num(c[a][j], c[b][j])] = 1;
				}
				for (int j = 0; j < M; j++) {
					used[j][num(c[a][j], c[b][j])] = 0;
				}
			}
			if (m == n + 1) {
				int b = B[m - 1];
				for (int i = 0; i < M; i++) {
					for (int j = 0; j < i; j++) {
						if (c[b][i] == c[b][j]) {
							g[j][i]++;
						}
					}
				}
			}
			int cnt = 0;
			for (int i = 0; i < M; i++) {
				if (was[i]) {
					continue;
				}
				for (int j = i + 1; j < M; j++) {
					if (g[i][j] == m) {
						cnt++;
						was[j] = 1;
					}
				}
			}
			if (cnt == M / 2) {
				cout << "YES";
				exit(0);
			}
		}	while (next_permutation(B, B + m));
		return;
	}
	int last = -1;
	if (n > 0) {
		last = A[n - 1];
	}
	for (int i = last + 1; i < N; i++) {
		A[n] = i;
		rec(n + 1);
		A[n] = 0;
	}
}

