void dfs(int x) {
	if (x>m) {
		for (int i=1;i<=n;i++) {
			h1[i]=0;
			for (int j=1;j<=m;j++)
				h1[i]+=cf[j]*(s[i][d[j]]-'a'+1);
			h2[i]=0;
			for (int j=m;j>=1;j--)
				h2[i]+=cf[m-j+1]*(s[i][d[j]]-'a'+1);
		}
		memset(ok,0,sizeof(ok));
		for (int i=1;i<=n;i++) {
			if (ok[i]) continue;
			for (int j=1;j<=n;j++)
				if (h1[i]==h2[j]&&!ok[j]) {
					ok[i]=ok[j]=1; break;
				}
			if (!ok[i]) return;
		}
		flag=1;
		return;
	}
	T=clock();
	if ((T-S)*1.0/CLOCKS_PER_SEC>=1.99) {
		ans=0; return;
	}
	for (int i=1;i<=m;i++)
		if (!u[i]) {
			u[i]=1;
			d[i]=x;
			dfs(x+1);
			if (!ans||flag) return;
			u[i]=0;
		}
}
