bool found = false;

bool row_pairable[15][15];

bool col_pairable(int j0, int j1){
	if(row_center!=-1){
		if(S[row_center][j0]!=S[row_center][j1])return false;
	}
	for(auto &&p:row_pair){
		if(S[p.first][j0]!=S[p.second][j1])return false;
		if(S[p.first][j1]!=S[p.second][j0])return false;
	}
	return true;
}

bool col_be_center(int j){
	for(auto &&p:row_pair){
		if(S[p.first][j]!=S[p.second][j])return false;
	}
	return true;
}

void col_rec2(){
	for(int j=0;j<W;j++){
		if(col_selected[j])continue;
		col_selected[j] = true;
		bool col_found = false;
		for(int j1=j+1;j1<W;j1++){
			if(col_selected[j1])continue;
			if(!col_pairable(j,j1))continue;
			col_selected[j1] = true;
			col_found = true;
		}
		if(!col_found){
			return;
		}
	}
	found = true;
}

void col_rec(){
	col_selected.assign(W,false);
	if(W%2==1){
		REP(j,W){
			if(!col_be_center(j))continue;
			col_center = j;
			col_selected[j] = true;
			col_rec2();
			col_selected[j] = false;
			col_center = -1;
		}
	}
	col_rec2();
}

void row_rec1(){
	if(found)return;
	int i = 0;
	for(;i<H;i++)if(!row_selected[i])break;
	if(i==H){
		col_rec();
		return;
	}
	row_selected[i] = true;
	for(int i1=i+1;i1<H;i1++){
		if(row_selected[i1] or not row_pairable[i][i1])continue;
		row_selected[i1] = true;
		row_pair.push_back({i,i1});
		row_rec1();
		row_pair.pop_back();
		row_selected[i1] = false;
	}
	row_selected[i] = false;
}

void row_rec(){
	if(H%2==1){
		REP(i,H){
			row_center = i;
			row_selected[i] = true;
			row_rec1();
			row_selected[i] = false;
			row_center = -1;
		}
	}else{
		row_rec1();
	}
}

