    for (int i = 0; i < H; i++)
        if ((b >> i) & 1) rows.push_back(i);
    auto l = rows.begin() + __builtin_popcount(a), r = rows.end();
    do {
        if (check1(H, W, s, rows)) return true;
    } while (next_permutation(l, r));
    return false;
}


