using namespace std;
typedef long long hash_t;
hash_t hashs(const string& s) {
	hash_t r = 81;
	for (char c : s) {
		r *= 37;
		r += c;
	}
	return r;
}
hash_t hasha(hash_t h1, hash_t h2) {
	return 6582952005840035281LL*h1 + h2;
}
void f(map<int, set<hash_t>>& A, int n, int visited, hash_t h, const vector<hash_t>& S) {
	if (n == 0) {
		A[visited].insert(h);
		return;
	}
	for (int i = 0; i < (int)S.size(); ++ i) if (!((visited>>i)&1)) {
		f(A, n-1, visited|(1<<i), hasha(h, S[i]), S);
	}
}
bool solve(const vector<string>& S) {
	int h = S.size();
	int w = S[0].length();
	if (h % 2 == 1) {
		for (int i = 0; i < h; ++ i) {
			map<char, vector<int>> d;
			for (int j = 0; j < w; ++ j) {
				d[S[i][j]].push_back(j);
			}
			vector<int> b(w);
			int p = 0, q = w-1;
			bool odd = w % 2 != 0;
			for (auto& x : d) {
				if (x.second.size() % 2 != 0){
					if (!odd) goto next;
					odd = false;
					b[w/2] = x.second.back();
					x.second.pop_back();
				}
				for (unsigned i = 0; i < x.second.size(); i += 2) {
					b[p++] = x.second[i];
					b[q--] = x.second[i+1];
				}
			}
			{
				vector<string> a;
				for (int ii = 0; ii < h; ++ ii) if (ii != i) {
					string s;
					for (int j = 0; j < w; ++ j) s += S[ii][b[j]];
					a.push_back(s);
				}
				if (solve(a)) return true;
			}
			next:;
		}
		return false;
	} else if (w % 2 == 1) {
		vector<string> a(w);
		for (int i = 0; i < h; ++ i) for (int j = 0; j < w; ++ j) {
			a[j] += S[i][j];
		}
		return solve(a);
	} else {
		vector<hash_t> H1(h);
		for (int i = 0; i < h; ++ i) {
			string s = S[i];
			sort(s.begin(), s.end());
			H1[i] = hashs(s);
		}
		map<int, set<hash_t>> A1;
		f(A1, h/2, 0, 0, H1);
		int mask = (1<<h)-1;
		for (const auto& a : A1) {
			int v1 = a.first;
			if ((v1&mask) != v1) continue;
			int v2 = mask&~v1;
			for (auto h : a.second) {
				if (A1[v2].count(h)) return true;
			}
		}
		return false;
	}
}
