	mid = true;
	for(int i=1;i<=w;i++){
		if(usedcol[i]) continue;
		bool ok = false;
		for(int j=i+1;j<=w;j++){
			if(usedcol[j]) continue;
			if(bw(i,j)){
				usedcol[i] = true;
				usedcol[j] = true;
				ok = true;
				break;
			}
		}
		if(!ok){
			if(w & 1 && mid && pal(i)){
				mid = false;
				used[i] = true;
