			fl = true;
		}
		if(h&1) row[num] = 0;
		return;
	}
	for(int i=cur+1;i<=h;i++){
		if(used[i]) continue;
		row[num] = cur;
		row[h + 1 - num] = i;
		used[cur] = used[i] = true;
		int st;
		for(st = cur+1;st <= h;st++) if(!used[st]) break;
