int64 getCycle() {
  unsigned int low, high;
  __asm__ volatile ("rdtsc" : "=a" (low), "=d" (high));
  return ((unsigned long long int) low) | ((unsigned long long int) high << 32);
}

int64 getTime() {
  return getCycle();
}


int H, W;
string S[12];
int latte[12], malta[12];

int64_t power(int64_t x, int64_t n, int64_t mod) {
  int64_t ret = 1;
  while(n > 0) {
    if(n & 1) (ret *= x) %= mod;
    (x *= x) %= mod;
    n >>= 1;
  }
  return ret;
}

int ismatch() {
  int ret = 0;
  for(int i = 0; i < H; i++) {
    for(int j = 0; j < W; j++) {
      ret += S[latte[i]][malta[j]] == S[latte[H - 1 - i]][malta[W - 1 - j]];
    }
  }
  return ret;
}

void mirrorSequenceSI(int64 msec) {

  int64 all = 0;

  for(int i = 0; i < H; i++) latte[i] = i;
  for(int i = 0; i < W; i++) malta[i] = i;

  int64 bestScore = ismatch();
  int64 currentScore = bestScore;

  {
    const int64 saTimeStart = getTime();
    const int64 saTimeEnd = saTimeStart + msec;
    int64 saTimeCurrent = saTimeStart;

    while((saTimeCurrent = getTime()) < saTimeEnd) {
      int ts = randxor() % 2;
      int ss, tt;

      if(ts == 1) {
        ss = randxor() % H;
        tt = randxor() % H;
        swap(latte[ss], latte[tt]);
      } else {
        ss = randxor() % W;
        tt = randxor() % W;
        swap(malta[ss], malta[tt]);
      }

      const int64 nextScore = ismatch();

      const int64 T = saTimeEnd - saTimeStart;
      const int64 t = saTimeCurrent - saTimeStart;
      const int64 R = 121;
      double startTemp = all;
      double endTemp = 1;
      double temp = startTemp + (endTemp - startTemp) * t / T;
      double probability = exp((nextScore - currentScore) / temp);  // æ��å¤§å��ã�ªã�®ã�§ã��å��å­�ã�¯nextScore - currentScoreã�§è�¯ã��ã��
      bool FORCE_NEXT = probability > (double) (randxor() % R) / R;

      if(nextScore > currentScore || (FORCE_NEXT && currentScore > 0.0f)) {
        currentScore = nextScore;
        // printf("current Score=%lld time=%lld\n", currentScore, t);
        if(currentScore > bestScore) {
          bestScore = currentScore;
          //   printf("New best Score=%lld time=%lld\n", bestScore, t);
          if(ismatch() == H * W) {
            cout << "YES" << endl;
            exit(0);
          }
        }
      } else {
        if(ts % 2 == 0) swap(malta[tt], malta[ss]);
        else swap(latte[tt], latte[ss]);
      }
    }
  }
}

