bool rec(int i, int ct) {
    if (ct == n) {
        multiset<string> st;
        for (int j = 0; j < m; j++) {
            string t;
            for (int k = 0; k < n; k++) {
                t.push_back(s[a[k]][j]);
            }
            st.insert(t);
