        while (st.size() > 1) {
            string t = *st.begin();
            st.erase(st.begin());
            reverse(all(t));

            if (st.count(t)) {
                st.erase(st.find(t));
            }
            else {
                if (m % 2) {
                    if (mid)
                        return false;
                    if (!is_pal(t))
                        return false;
                    mid = true;
                }
                else {
                    return false;
                }
            }
        }
        if (st.size() == 1)
            return is_pal(*st.begin());
        return true;
    }
    else if (used[i]) {
        if (rec(i + 1, ct))
            return true;
        return false;
    }
    else {
        used[i] = true;
        for (int j = i + 1; j < n; j++) {
            if (!used[j]) {
                used[j] = true;
                a[len] = i;
                a[n - len - 1] = j;
                len++;
