			bool ok=true;
			rep(i,h/2){
				int r1,r2; tie(r1,r2)=mat[i];
				if(B[r1][u]!=B[r2][v] || B[r1][v]!=B[r2][u]){ ok=false; break; }
			}
			if(h%2==1){
				int r=mat.back().first;
				if(B[r][u]!=B[r][v]) ok=false;
			}
			if(ok){
				G[u].emplace_back(v);
				if(u<v) G[v].emplace_back(u);
