	for (int i = 0; i < 26; i++) {
		if (cnt[i] % 2) {
			oddcnt++;
			odd = 'a' + i;
		}
	}

	if (oddcnt > 1) {
		cout << "NO" << endl;
		return 0;
	}
	else if (oddcnt == 1 && !mode) {
		cout << "NO" << endl;
		return 0;
	}
	else if (oddcnt == 0 && mode) {
		cout << "NO" << endl;
		return 0;
	}

	if (H == 1 && W == 1) {
		cout << "YES" << endl;
		return 0;
	}

	Timer tmr;

	Xor128 rnd;
	int loop = 0;
	while (1) {
		if (loop % 100000 == 0) {
			if (tmr.getTime()>1.9)break;
		}

		int m, i, j;
		m = rnd.rand() % 2;
		if (H == 1)m = 1;
		if (W == 1)m = 0;

		if (m) {
			i = rnd.rand() % W;
			do {
				j = rnd.rand() % W;
			} while (i == j);
		}
		else {
			i = rnd.rand() % H;
			do {
				j = rnd.rand() % H;
			} while (i == j);
		}


		swapGRID(m, i, j);
		if (is_()) {
			cout << "YES" << endl;
			return 0;
		}

		loop++;
	}
	cout << "NO" << endl;

	return 0;
}

