bool dfs()
{
	int x = -1;
	for(int i = 0; i < h; i++){
		if(!used[i]){
			x = i;
			break;
		}
	}
	if(x != -1){
		for(int i = x+1; i < h; i++){
			if(used[i]) continue;
			used[x] = used[i] = true;
			vec.push_back(make_pair(x, i));
			if(dfs()) return true;
			vec.pop_back();
			used[x] = used[i] = false;
		}
		return false;
	}
	return check();
}

