            int head = 0;
            for (; r[head] != -1 and head < H; head++) {}
            r[head] = num;
            if (H % 2 == 1 and num == (H - 1) / 2) {
                self(self, r, num + 1);
            } else {
                for (int tail = head + 1; tail < H; tail++) {
                    if (r[tail] == -1) {
                        r[tail] = num;
                        self(self, r, num + 1);
                        r[tail] = -1;
                    }
                }
            }
        }
    });
