bool judge() {
    for (int i = 0; i < H; ++i) {
        int r1 = i, r2 = rPair[i];
        for (int j = 0; j < W; ++j) {
            int c1 = j, c2 = cPair[j];
            if (matrix[r1][c1] != matrix[r2][c2]) {
                return false;
            }
        }
    }
    return true;
}
bool rec2(int r1, int r2, int c, int pairCount) {
    while (c < W && cPair[c] != -1) ++c;

    if (c == W) {
        return judge();
    }

    for (int i = c+1; i < W; ++i) {
        if (cPair[i] == -1 && matrix[r1][c] == matrix[r2][i]) {
            cPair[c] = i;
            cPair[i] = c;
            pairCount += 2;
            if (rec2(r1, r2, c+1, pairCount)) return true;
            cPair[c] = -1;
            cPair[i] = -1;
            pairCount -= 2;
        }
    }

    if (W%2 == 1 && pairCount%2 == 0) {
        cPair[c] = c;
        pairCount += 1;
        if (rec2(r1, r2, c+1, pairCount)) return true;
        cPair[c] = -1;
        pairCount -= -1;
    }

    return false;
}

bool rec1(int r, int& pairCount) {
    while (r < H && rPair[r] != -1) ++r;

    if (r == H) {
        int _pc = 0;
        return rec2(0, rPair[0], 0, _pc);
    }

    for (int i = r+1; i < H; ++i) {
        if (isPairable[r][i] && rPair[i] == -1) {
            rPair[i] = r;
            rPair[r] = i;
            pairCount += 2;
            if (rec1(r+1, pairCount)) return true;
            rPair[i] = -1;
            rPair[r] = -1;
            pairCount -= 2;
        }
    }

    if (H%2 == 1 && pairCount%2 == 0) {
        rPair[r] = r;
        pairCount += 1;
        if (rec1(r+1, pairCount)) return true;
        rPair[r] = -1;
        pairCount -= 1;
    }

    return false;
}


