bool checks_1(int l,int r,bool center_col)
{
    int i,j;
    for (i=0;i<h;i++)
    {
        for (j=0;j<l;j++)
        {
            if (a[i][j]!=a[h-i-1][w-j-1]) return false;
        }
        for (j=r;j<w;j++)
        {
            if (a[i][j]!=a[h-i-1][w-j-1]) return false;
        }
        if (center_col)
        {
            j=(l+r)/2;
            if (a[i][j]!=a[h-i-1][w-j-1]) return false;
        }
    }
    string t[15],t2[15];
    int cnt=0;
    for (j=l;j<r;j++)
    {
        if ((!center_col)&&((l+r)/2==j)&&((l+r)%2==1)) continue;
        for (i=0;i<h;i++)
        {
            t[cnt]+=a[i][j];
        }
        for (i=h-1;i>=0;i--)
        {
            t2[cnt]+=a[i][j];
        }
        cnt++;
    }
    sort(t,t+cnt);
    sort(t2,t2+cnt);
    int sums=0;
    for (j=0;j<cnt;j++)
    {
        if (t[j]!=t2[j]) return false;
        int k;
        for (k=0;k<h/2;k++)
        {
            if (t[j][k]!=t[j][h-1-k]) break;
        }
        if (k==w/2)
        {
            if (t[j+1]==t[j])
            {
                j++;
                continue;
            }
            sums++;
        }
    }
    if (sums>=2) return false;
    return true;
}
