bool setted[15];

void getLines(int msk, int cur, int smallest) {
    if (cur == (h >> 1)) return check();
    while (setted[smallest] || (msk >> smallest & 1))
        ++smallest;
    lines[cur] = smallest;
    for (int i = smallest + 1; i < h; ++i)
        if (!setted[i] && (msk >> i & 1)) {
            lines[h - 1 - cur] = i;
            setted[i] = setted[smallest] = true;
            getLines(msk, cur + 1, smallest + 1);
            setted[i] = setted[smallest] = false;
        }
}

void dfs(int cur, int cnt, int msk) {
    if (cnt == (h >> 1)) return getLines(msk, 0, 0);
    if (cur == h) return ;
    if (setted[cur]) return dfs(cur + 1, cnt, msk);
    dfs(cur + 1, cnt + 1, msk | 1 << cur);
    dfs(cur + 1, cnt, msk);
}

