const int nmax = 16;

int curr[nmax];
int mt[nmax];
bool used[nmax];

bool dfs(int v) {
    if (used[v]) {
        return false;
    }
    used[v] = true;
    int val = curr[v];
    for (int i = 0; val; ++i, val >>= 1) {
        if (val & 1) {
            if (mt[i] == -1 || dfs(mt[i])) {
                mt[i] = v;
                return true;
            }
        }
    }
    return false;
}

string s[nmax];
int n, m;
bool ans = false;

void kuhn() {
    for (int i = 0; i < m; ++i) {
        used[i] = false;
    }
    memset(mt, -1, sizeof(mt));
    int sum = 0;
    for (int i = 0; i < m; ++i) {
        if (used[i]) {
            continue;
        }
        if (dfs(i)) {
            ++sum;
            for (int j = 0; j < m; ++j) {
                used[j] = false;
            }
        } else {
            return;
        }
    }
    if (sum == m) {
        ans = true;
    }
}

bool occ[nmax];

const int alpha = 26;
int pos[alpha];

void build(int u, int v) {
    memset(pos, 0, sizeof(pos));
    for (int i = 0; i < m; ++i) {
        pos[s[v][i] - 'a'] |= (1 << i);
    }
    for (int i = 0; i < m; ++i) {
        curr[i] &= pos[s[u][i] - 'a'];
        //cout << curr[i] << "\n";
    }
}

void f(int lib) {
    if (lib == 0) {
        kuhn();
        return;
    }
    int tmp[nmax];
    memcpy(tmp, curr, sizeof(tmp));
    if (lib == 1) {
        for (int i = 0; i < m; ++i) {
            if (!occ[i]) {
                build(i, i);
            }
        }
        kuhn();
        memcpy(curr, tmp, sizeof(tmp));
        return;
    }
    for (int i = 0; i < n; ++i) {
        if (occ[i]) {
            continue;
        }
        for (int j = i + 1; j < n; ++j) {
            if (occ[j]) {
                continue;
            }
            build(i, j);
            occ[i] = occ[j] = true;
            f(lib - 2);
            if (ans) {
                return;
            }
            occ[i] = occ[j] = false;
            memcpy(curr, tmp, sizeof(tmp));
        }
    }
}

