void solve()
{
    int i, j, k;
    memset(used2, 0, sizeof(used2));

    for(i=1; i<=m; ++i)
        if(!used2[i])
        {
            for(j=1; !used2[i] && j<=m; ++j)
                if(i != j && !used2[j])
                {
                    bool match = 1;
                    for(k=0; match && k<p.size(); ++k)
                        match &= (a[p[k].first][i] == a[p[k].second][j]);

                    if(match) used2[i] = used2[j] = 1;
                }
        }

    int id = 0;
    for(i=1; i<=m; ++i)
        if(!used2[i])
        {
            if(id) return;
            id = i;
        }

    if(!id) YES;

    bool match = 1;
    for(k=0; k<p.size(); ++k)
        match &= (a[p[k].first][id] == a[p[k].second][id]);

    if(match) YES;
}

void tracktor(int l)
{
    if(l == n+1)
    {
        solve();
        return;
    }

    if(!used[l])
    {
        int i;
        used[l] = 1;
        for(i=l+1; i<=n; ++i)
            if(!used[i])
            {
                used[i] = 1;
                p.push_back({l, i});
                tracktor(l+1);

                used[i] = 0;
                p.pop_back();
            }
        used[l] = 0;
    }
    else tracktor(l+1);
}

