void go(auto& grid, int dep) {
    if (2 * dep + 1 >= grid.size()) {
        const int H = grid.size();
        const int W = grid[0].size();

        vector<string> unmatched;

        for (int i = 0; i < W; i++) {
            string col(H, 0);
            for (int j = 0; j < H; j++)
                col[j] = grid[j][i];

            string tmp = col;
            reverse(all(tmp));

            bool m = false;
            for (auto it = unmatched.begin(); it != unmatched.end(); it++) {
                if (tmp == *it) {
                    m = true;
                    unmatched.erase(it);
                    break;
                }
            }
            if (!m) unmatched.push_back(col);
        }

        if (!unmatched.size()) {
            cout << "YES\n";
            exit(0);
        } else if (unmatched.size() == 1) {
            string elt = *unmatched.begin();
            string tmp = elt;
            reverse(all(tmp));
            if (elt == tmp) {
                cout << "YES\n";
                exit(0);
            }
        }
    } else {
        const int H = grid.size();
        for (int pr = dep + 1; pr < H - dep; pr++) {
            if ((H&1) && (pr == H/2)) continue;
            swap(grid[pr], grid[H - dep - 1]);
            go(grid, dep + 1);
            swap(grid[pr], grid[H - dep - 1]);
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);

    int H, W;
    cin >> H >> W;

    vector<string> grid(H);
    for (int i = 0; i < H; i++) {
        cin >> grid[i];
    }

    if (H&1) {
        int m = H / 2;
        for (int i = 0; i < H; i++) {
            swap(grid[i], grid[m]);
            go(grid, 0);
            swap(grid[i], grid[m]);
        }
    } else go(grid, 0);

    cout << "NO\n";
    return 0;
}

