using namespace std;
typedef long long ll;

struct UnionFind {
  vector<int> data;
  UnionFind(int size) : data(size, -1) { }
  bool unionSet(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool findSet(int x, int y) {
    return root(x) == root(y);
  }
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) {
    return -data[root(x)];
  }
};

int H, W;
char S[12][12];

bool used[12];
vector<int> buf;

bool verify_pair(int i, int j){
    for(int k = 0; k+1 < H; k += 2){
        int s = buf[k], t = buf[k+1];
        if(S[s][i] != S[t][j]) return false;
        if(S[s][j] != S[t][i]) return false;
    }
    if(H%2 == 1){
        int s = buf[H-1];
        if(S[s][i] != S[s][j]) return false;
    }
    return true;
}

bool has_elm(int n, vector<int> v){
    for(int i = 0; i < v.size(); i++) {
        if(v[i] == n) return true;
    }
    return false;
}

bool verify(){
    // for(int i = 0; i < H; i++) cout << buf[i];
    // cout << endl;
    UnionFind uf(W);
    for(int i = 0; i < W; i++){
        for(int j = i+1; j < W; j++){
            if(verify_pair(i, j)) {
                // cout << "unite " << i << ' ' << j << endl;
                uf.unionSet(i, j);
            }
        }
    }
    vector<int> odd;
    for(int i = 0; i < W; i++){
        int s = uf.size(i);
        int r = uf.root(i);
        if(s%2 == 1){
            // cout << i << endl;
            if(W%2 == 0) return false;
            else{
                if(odd.size() > 0 && !has_elm(r, odd)) return false;
                if(!verify_pair(i, i)) return false;
            }
            odd.push_back(r);
        }
    }
    return true;
}

bool ans = false;

void search_pairs(int t, int cnt){
    if(buf.size()+2 > H){
        if(H%2 == 1){
            for(int i = 0; i < H; i++){
                if(!used[i]) {
                    buf.push_back(i);
                    break;
                }
            }
        }
        ans |= verify();
        if(H%2 == 1){
            buf.pop_back();
        }
    }else{
        for(int i = t; i < H; i++){
            if(used[i]) continue;
            for(int j = i+1; j < H; j++){
                if(used[j]) continue;
                used[i] = true; used[j] = true;
                buf.push_back(i); buf.push_back(j);
                search_pairs(t, cnt);
                used[i] = false; used[j] = false;
                buf.pop_back(); buf.pop_back();
            }
            if(!used[i]) cnt++;
            if(cnt >= 2) break;
        }
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << setprecision(10) << fixed;
    cin >> H >> W;
    for(int i = 0; i < H; i++){
        for(int j = 0; j < W; j++){
            cin >> S[i][j];
        }
    }
    search_pairs(0, 0);
    cout << (ans?"YES":"NO") << endl;
}

