int ngay(string a,string b){
	map<pii,int>mp;
	FOR(i,0,a.size()){
		mp[{a[i],b[i]}]++;
	}
	int pos=(n%2?-1:1);
	for(map<pii,int>::iterator itr=mp.begin();itr!=mp.end();itr++){
		pii p=itr->first;
		int x=itr->second;
		pii q={p.second,p.first};
		int y=mp[q];
		if(x!=y)return -1;
		if(p==q&&pos==-1){
			pos=q.first;
		}
	}
	int ret=0;
	FOR(i,0,a.size()){
		if(a[i]==pos&&b[i]==pos){
			ret|=(1<<i);
		}
	}
	return ret;

