int H, W, *is_used, *is_chosen;
char **S, **T;

int sym(int j, int k){
	int i;
	for(i = 0; i < H; i++){
		if(T[i][j] != T[H - 1 - i][k]){
			return 0;
		}
	}
	return 1;
}

int solve(int set_num){
	int i, j, k;
	if(set_num == H){
		int alone_num = 0;
		for(j = 0; j < W; j++){
			is_chosen[j] = 0;
		}
		for(j = 0; j < W; j++){
			if(is_chosen[j] == 0){
				for(k = j + 1; k < W; k++){
					if(is_chosen[k] == 0){
						if(sym(j, k) == 1){
							is_chosen[j] = 1;
							is_chosen[k] = 1;
							break;
						}
					}
				}
				if(is_chosen[j] == 0){
					if(sym(j, j) == 0 || alone_num > 0){
						return 0;
					}
					else{
						is_chosen[j] = 1;
						alone_num++;
					}
				}
			}
			return 1;
		}
	}
	else{
		for(i = 0; is_used[i] == 1; i++){}
		T[set_num / 2] = S[i];
		if(set_num == H - 1){
			return solve(set_num + 1);
		}
		for(k = i + 1; k < H; k++){
			if(is_used[k] == 0){
				T[H - 1 - set_num / 2] = S[k];
				if(solve(set_num + 2) == 1){
					return 1;
				}
			}
		}
		return 0;
	}
}

