void rep(int pod,int sk){
  //printf("[%d %d]\n",pod,sk);
  int i;
  if(pod==m){
    int j,c=0,sz[16],ssk=-1;
    char sm[16][16]={0};
    bool usf[16]={0};
    if(m%2==0){
      if(sk!=-1){return;}
      for(i=0;i<m;i++){
        if(pair[i]<i){continue;}
        sz[c]=i;
        sz[m-c-1]=pair[i];
        c++;
      }
    }
    else{
      if(sk==-1){return;}
      for(i=0;i<m;i++){
        if(pair[i]<i){continue;}
        sz[c]=i;
        sz[m-c-1]=pair[i];
        c++;
      }
      sz[c]=sk;
    }
    //for(i=0;i<m;i++){printf("[%d]",sz[i]);}printf("\n");
    for(i=0;i<n;i++){
      for(j=0;j<m;j++){
        sm[i][j]=s[i][sz[j]];
      }
      //printf("<%s>\n",sm[i]);
    }//printf("\n");
    for(i=0;i<n;i++){
      for(j=i+1;j<n;j++){
        if(usf[j]==1){continue;}
        if(isrev(sm[i],sm[j],m)==1){
          usf[i]=1;
          usf[j]=1;
          break;
        }
      }
      if(usf[i]==0){
        if(ssk!=-1 || n%2==0){
          return;
        }
        ssk=i;
      }
    }
    if(n%2==0){res=1;}
    else if(isrev(sm[ssk],sm[ssk],m)==1){res=1;}
    return;
  }
  else{
    if(pair[pod]!=-1){
      rep(pod+1,sk);
      return;
    }
    for(i=pod+1;i<m;i++){
      if(strcmp(map[pod],map[i])==0){
        pair[pod]=i;
        pair[i]=pod;
        //printf("Pairing %d %d\n",pod,i);
        rep(pod+1,sk);
        //printf("Break %d %d\n",pod,i);
        pair[pod]=0;
        pair[i]=0;
      }
    }
    if(sk==-1){
      rep(pod+1,pod);
    }
  }
}

