void g(int s,int flag){
	if(s+1==(1<<w)){
		puts("YES");
		exit(0);
	}
	int i=0;
	while(bit(s,i))i++;
	if(flag){
		int b=1;
		rep(k,0,h)if(ss[k][i]!=ss[a[k]][i]){
			b=0;
			break;
		}
		if(b)g(s^(1<<i),0);
	}
	rep(j,i+1,w)if(!bit(s,j)){
		int b=1;
		rep(k,0,h)if(ss[k][i]!=ss[a[k]][j]){
			b=0;
			break;
		}
		if(b)g(s^(1<<i)^(1<<j),flag);
	}	
}

void f(int s,int flag){
	if(s+1==(1<<h))g(0,w%2);
	int i=0;
	while(bit(s,i))i++;
	if(flag){
		a[i]=i;
		f(s^(1<<i),0);
	}
	rep(j,i+1,h)if(!bit(s,j)){
		a[i]=j;
		a[j]=i;
		f(s^(1<<i)^(1<<j),flag);
	}
}

