/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        MyInput in = new MyInput(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        public void solve(int testNumber, MyInput in, PrintWriter out) {
            int h = in.nextInt();
            int w = in.nextInt();
            char[][] cs = new char[h][];
            int[][] cnt = new int[h][26];
            for (int y = 0; y < h; y++) {
                cs[y] = in.nextChars();
                for (int x = 0; x < w; x++) {
                    cnt[y][cs[y][x] - 'a']++;
                }
            }

            TreeMap<int[], Integer> map = new TreeMap<>((a, b) -> {
                for (int i = 0; i < a.length; i++) {
                    if (a[i] != b[i]) return a[i] - b[i];
                }
                return 0;
            });

            for (int[] c : cnt) {
                map.put(c, map.getOrDefault(c, 0) + 1);
            }

            if (h % 2 == 0) {
                boolean ok = map.entrySet().stream().allMatch(e -> e.getValue() % 2 == 0);
                out.println(ok ? "YES" : "NO");
            } else {
                boolean ok = true;
                int odd = 0;
                for (Map.Entry<int[], Integer> e : map.entrySet()) {
                    if (e.getValue() % 2 == 0) {
                        odd++;
                        int o = 0;
                        for (int c : e.getKey()) {
                            if (c % 2 == 1) o++;
                        }
                        if (o != w % 2) {
                            ok = false;
                        }
                    }
                }
                ok &= odd == 1;
                out.println(ok ? "YES" : "NO");
            }
        }

    }

    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        public char[] nextChars() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            return Arrays.copyOf(str, len);
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }

    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

class Main{

    static long[] hash;

    static int[] used;
    static int[][] tmp;
    static int[][] mat;
    static int H,W;
    static boolean ans=false;
    static long mod = (long)1e9+7;
    static long base = 26;



    static void check(){
        if(ans)return;
        for(int i=0;i<H;++i){
            if(used[i]%2==0){
                tmp[used[i]/2]=mat[i];
            }else{
                tmp[H-1 -used[i]/2]=mat[i];
            }
        }
        Set<Long> usedHash = new HashSet<>();
        for(int i=0;i<W;++i){
            long hsh = 0;
            for(int j=0;j<H;++j)hsh = (hsh*base + tmp[j][i])%mod;
            if(!usedHash.remove(hsh)){
                hsh = 0;
                for(int j=H-1;j>=0;--j)hsh = (hsh*base + tmp[j][i])%mod;
                usedHash.add(hsh);
            }
        }
        if(usedHash.size()==0)ans = true;
        if(usedHash.size()==1){
            for(int i=0;i<W;++i){
                long hsh = 0;
                for(int j=H-1;j>=0;--j)hsh = (hsh*base + tmp[j][i])%mod;
                if(usedHash.contains(hsh)){
                    for(int k=0; k<(H-1-k);++k)if(tmp[k][i]!=tmp[H-1-k][i])return;
                    ans = true;
                    return;
                }
            }
        }
    }

    static void dfs(int v, int depth){
        if(v==-1){
            boolean full=true;
            for(int i=0;i<H;++i)if(used[i]<0){
                full=false;
                used[i]=depth;
                dfs(i,depth+1);
                used[i]=-1;
            }
            if(full)check();
        }else{
            for(int i=0;i<H;++i){
                if(i==v)continue;
                if(hash[i]==hash[v]){
                    used[i]=depth;
                    dfs(-1,depth+1);
                    used[i]=-1;
                }
            }
        }
    }

    public static void main(String[] args){
        Scanner scan = new Scanner(System.in);
        H = scan.nextInt();
        W = scan.nextInt();
        mat = new int[H][W];
        tmp = new int[H][W];
        hash = new long[H];
        used = new int[H];
        Arrays.fill(used,-1);
        for(int i=0;i<H;++i){
            String s = scan.next();
            int cnt[] = new int[26];
            for(int j=0;j<W;++j){
                mat[i][j]=s.charAt(j)-'a';
                cnt[mat[i][j]]++;
            }
            for(int j=0;j<26;++j)hash[i] = (hash[i]*base + cnt[j])%mod;
        }
        dfs(-1,0);
        if(ans)System.out.println("YES");
        else System.out.println("NO");
    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Iterator;
import java.util.Set;
import java.io.IOException;
import java.util.HashMap;
import java.io.InputStreamReader;
import java.util.StringTokenizer;
import java.util.BitSet;
import java.io.BufferedReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author anand.oza
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        ESymmetricGrid solver = new ESymmetricGrid();
        solver.solve(1, in, out);
        out.close();
    }

    static class ESymmetricGrid {
        char[][] s;
        char[][] t;
        char[][] tR;
        int h;
        int w;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            h = in.nextInt();
            w = in.nextInt();

            s = new char[h][];
            for (int i = 0; i < h; i++) {
                s[i] = in.next().toCharArray();
            }
            t = new char[h][w];
            tR = new char[h][w];

            BitSet avail = new BitSet();
            for (int i = 0; i < w; i++) {
                avail.set(i);
            }

            int[] perm = new int[w];
            boolean answer = false;
            if (w % 2 == 1) {
                for (int i = 0; i < w; i++) {
                    perm[w / 2] = i;
                    avail.clear(i);
                    answer |= go(perm, avail, 0);
                    avail.set(i);
                }
            } else {
                answer |= go(perm, avail, 0);
            }

            out.println(answer ? "YES" : "NO");
        }

        boolean go(int[] perm, BitSet avail, int index) {
            if (avail.cardinality() <= 1) {
                if (avail.cardinality() == 1) perm[index] = avail.nextSetBit(0);
                return eval(perm);
            } else {
                int first = avail.nextSetBit(0);
                avail.clear(first);
                for (int second = avail.nextSetBit(first + 1); second != -1; second = avail.nextSetBit(second + 1)) {
                    perm[index] = first;
                    perm[perm.length - 1 - index] = second;
                    avail.clear(second);
                    if (go(perm, avail, index + 1)) return true;
                    avail.set(second);
                }
                avail.set(first);
            }

            return false;
        }

        private boolean eval(int[] perm) {
            HashMap<String, Integer> columns = new HashMap<>();
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    t[i][j] = s[i][perm[j]];
                }
            }
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    tR[i][w - 1 - j] = s[i][perm[j]];
                }
            }

            for (int i = 0; i < h; i++) {
                String cur = String.valueOf(t[i]);
                String curReverse = String.valueOf(tR[i]);
                int count = columns.getOrDefault(curReverse, 0);
                if (count > 0) {
                    columns.put(curReverse, count - 1);
                    if (count == 1) {
                        columns.remove(curReverse);
                    }
                } else {
                    columns.put(cur, columns.getOrDefault(cur, 0) + 1);
                }
            }

            if (h % 2 == 0) {
                return columns.isEmpty();
            } else {
                if (columns.size() > 1) return false;
                String cur = columns.keySet().iterator().next();
                if (columns.get(cur) > 1) return false;
                return isPalindrome(cur);
            }
        }

        private static boolean isPalindrome(String cur) {
            for (int i = 0; i < cur.length(); i++) {
                if (cur.charAt(i) != cur.charAt(cur.length() - 1 - i)) return false;
            }
            return true;
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

class Main {
  public static void main(String[] args) {
    final Scanner scanner = new Scanner(System.in);
    final int h = scanner.nextInt();
    final int w = scanner.nextInt();
    final char[][] table = new char[h][w];
    for (int i = 0; i < h; i++) table[i] = scanner.next().toCharArray();
    if (possible(table, h, w)) {
      System.out.println("YES");
    } else {
      System.out.println("NO");
    }
  }

  private static boolean possible(char[][] table, int h, int w) {
    int[] cindicies = new int[w];
    for (int i = 0; i < w; i++) cindicies[i] = i;
    do {
      boolean valid = true;
      for (int i = 0; i < w / 2; i++) {
        if (cindicies[i] > cindicies[w - i - 1]) {
          valid = false;
          break;
        }
      }
      if (!valid) continue;

      if (check(table, h, w, cindicies)) return true;
    } while (nextPerm(cindicies));

    return false;
  }

  private static boolean check(char[][] table, int h, int w, int[] c) {
    List<char[]> rows = new ArrayList<>();
    for (int i = 0; i < h; i++) rows.add(table[i]);
    char[] rem = null;
    while (rows.size() > 1) {
      char[] row = rows.remove(0);
      boolean found = false;
      for (int i = 0; i < rows.size(); i++) {
        char[] other = rows.get(i);
        boolean symmetry = true;
        for (int j = 0; j < w / 2; j++) {
          if (row[c[j]] != other[c[w - j - 1]]) {
            symmetry = false;
            break;
          }
        }
        if (symmetry) {
          rows.remove(i);
          found = true;
          break;
        }
      }
      if (!found) {
        if (rem == null) rem = row;
        else return false;
      }
    }
    if (rem == null) return true;
    for (int i = 0; i < w / 2; i++) {
      if (rem[c[i]] != rem[c[w - i - 1]]) return false;
    }
    return true;
  }

  private static boolean nextPerm(int[] a) {
    int i = a.length - 1;
    while (i > 0 && a[i - 1] >= a[i]) i--;
    if (i == 0) return false;

    int j = a.length - 1;
    while (j >= i && a[j] <= a[i - 1]) j--;

    swap(a, i - 1, j);

    j = a.length - 1;
    while (i < j) swap(a, i++, j--);
    return true;
  }

  private static void swap(int[] a, int i, int j) {
    int tmp = a[j];
    a[j] = a[i];
    a[i] = tmp;
  }
}

