public class Main{
	static int n,m;
	static boolean allMatchings(int idx,int[]match) {
		//match holds that column i should be matched with column match[i]
		if(idx==m) {
			return check(match);
		}
		if(match[idx]!=-1) {
			return allMatchings(idx+1, match);
		}
		boolean ans=false;
		boolean odd=true;
		for(int j=idx+1;j<m && !ans;j++) {
			if(match[j]==-1) {
				odd=false;
				int[]tmp=match.clone();
				tmp[idx]=j;
				tmp[j]=idx;
				ans|=allMatchings(idx+1, tmp);
			}
		}
		if(odd) {
			int[]tmp=match.clone();
			tmp[idx]=idx;
			ans|=allMatchings(idx+1, tmp);
		}
		return ans;
	}
	static boolean check(int[]match) {
		boolean[]done=new boolean[n];
		boolean odd=(n%2==1);
		for(int i=0;i<n;i++) {
			if(done[i])continue;
			int matchRow=-1;
			for(int j=n-1;j>=i+(odd?0:1);j--) {
				if(done[j])continue;
				boolean matched=true;
				for(int idx=0;idx<m;idx++) {
					if(in[i][idx]!=in[j][match[idx]]) {
						matched=false;
						break;
					}
				}
				if(matched) {
					if(j==i) {
						odd=false;
					}
					matchRow=j;
					break;
				}
			}
			if(matchRow==-1) {
				return false;
			}
			done[i]=true;
			done[matchRow]=true;
		}
		return true;
	}
