	void solve(){
		int h=gInt(),w=gInt();
		int[][]a=new int[h][w],b=new int[w][h];

		int[]c=new int[26];
		for(int i:rep(h)) {
			String v=s.next();
			for(int j:rep(w)) {
				c[a[i][j]=b[j][i]=v.charAt(j)-'a']++;
