/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        char[][] a;
        int h;
        int w;
        int[] p;
        boolean[] used;
        boolean[] dp;
        boolean ans = false;

        void check() {
            if (ans) {
                return;
            }
            Arrays.fill(dp, false);
            dp[0] = true;
            boolean[][] good = new boolean[w][w];
            for (int i = 0; i < w; i++) {
                for (int j = 0; j < w; j++) {
                    good[i][j] = true;
                    for (int r1 = 0; r1 < h; r1 += 2) {
                        int r2 = r1 + 1;
                        if (r2 >= h) {
                            r2 = r1;
                        }
                        good[i][j] &= a[p[r1]][i] == a[p[r2]][j] && a[p[r1]][j] == a[p[r2]][i];
                    }
                }
            }

            for (int mask = 0; mask < 1 << w; mask++) {
                if (dp[mask]) {
                    if (Integer.bitCount(mask) + 1 == w) {
                        int missing = 0;
                        for (int i = 0; i < w; i++) {
                            if ((mask & (1 << i)) == 0) {
                                missing = i;
                            }
                        }
                        if (good[missing][missing]) {
                            dp[mask | (1 << missing)] = true;
                        }
                    } else {

                        for (int bit1 = 0; bit1 < w; bit1++) {
                            if ((mask & (1 << bit1)) != 0) {
                                continue;
                            }
                            for (int bit2 = bit1 + 1; bit2 < w; bit2++) {
                                if ((mask & (1 << bit2)) != 0) {
                                    continue;
                                }
                                dp[mask | (1 << bit1) | (1 << bit2)] |= good[bit1][bit2];
                            }
                        }
                    }
                }
            }
            if (dp[dp.length - 1]) {
                ans = true;
            }
        }

        void go(int pos) {
            int min = 0;
            while (min < used.length && used[min]) {
                min++;
            }
            if (min == used.length) {
                check();
                return;
            }

            used[min] = true;
            p[pos] = min;
            if (pos + 1 == h) {
                check();
            } else {
                for (int i = 0; i < h; i++) {
                    if (!used[i]) {
                        used[i] = true;
                        p[pos + 1] = i;
                        go(pos + 2);
                        used[i] = false;
                    }
                }
            }
            used[min] = false;
        }

        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            h = in.nextInt();
            w = in.nextInt();
            a = new char[h][];
            for (int i = 0; i < h; i++) {
                a[i] = in.next().toCharArray();
            }
            used = new boolean[h];
            p = new int[h];
            dp = new boolean[1 << w];
            go(0);
            out.println(ans ? "YES" : "NO");
        }

    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                String line = null;
                try {
                    line = br.readLine();
                } catch (IOException e) {
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

    }
}

public class Main {
  static char[][] map;
  static int h, w;
  private static void solve() {
    h = ni();
    w = ni();

    map = new char[h][w];
    for (int i = 0; i < h; i ++) {
      map[i] = ns();
    }

    int n = h;
    if (!dfs(n, 0, 0, new int[n / 2][2])) {
      System.out.println("NO");
      return;
    }

    char[][] tr = new char[w][h];
    for (int i = 0; i < h; i ++) {
      for (int j = 0; j < w; j ++) {
        tr[j][i] = map[i][j];
      }
    }
    map = tr;
    int tmp = w;
    w = h;
    h = tmp;
    n = h;
    if (!dfs(n, 0, 0, new int[n / 2][2])) {
      System.out.println("NO");
      return;
    }
    System.out.println("YES");

  }

  private static boolean check(int[][] pair) {
    boolean[] usedRow = new boolean[h];
    for (int[] v : pair) {
      int[][] cnt = new int[2][26];
      usedRow[v[0]] = usedRow[v[1]] = true;
      for (int i = 0; i < w; i ++) {
        cnt[0][map[v[0]][i] - 'a'] ++;
        cnt[1][map[v[1]][i] - 'a'] ++;
      }

      for (int i = 0; i < 26; i ++) {
        if (cnt[0][i] != cnt[1][i]) {
          return false;
        }
      }
    }
    return true;
  }

  private static boolean dfs(int n, int map, int k, int[][] pair) {
    if (k == n / 2) {
      return check(pair);
    }

    for (int i = 0; i < n; i ++) {
      if (((map >> i) & 1) == 0) {
        for (int j = i + 1; j < n; j ++) {
          if (((map >> j) & 1) == 0) {
            pair[k][0] = i;
            pair[k][1] = j;
            boolean ret = dfs(n, map | (1 << i) | (1 << j), k + 1, pair);
            if (ret) {
              return true;
            }
          }
        }
        break;
      }
    }
    return false;
  }

