public class Main {
  static char[][] map;
  static int h, w;
  private static void solve() {
    h = ni();
    w = ni();

    map = new char[h][w];
    for (int i = 0; i < h; i ++) {
      map[i] = ns();
    }

    int n = h;
    if (!dfs(n, 0, 0, new int[n / 2][2])) {
      System.out.println("NO");
      return;
    }

    char[][] tr = new char[w][h];
    for (int i = 0; i < h; i ++) {
      for (int j = 0; j < w; j ++) {
        tr[j][i] = map[i][j];
      }
    }
    map = tr;
    int tmp = w;
    w = h;
    h = tmp;

    if (!dfs(n, 0, 0, new int[n / 2][2])) {
      System.out.println("NO");
      return;
    }
    System.out.println("YES");

  }

  private static boolean check(int[][] pair) {
    boolean[] usedRow = new boolean[h];
    for (int[] v : pair) {
      int[][] cnt = new int[2][26];
      usedRow[v[0]] = usedRow[v[1]] = true;
      for (int i = 0; i < w; i ++) {
        cnt[0][map[v[0]][i] - 'a'] ++;
        cnt[1][map[v[1]][i] - 'a'] ++;
      }

      for (int i = 0; i < 26; i ++) {
        if (cnt[0][i] != cnt[1][i]) {
          return false;
        }
      }
    }
    return true;
  }

  private static boolean dfs(int n, int map, int k, int[][] pair) {
    if (k == n / 2) {
      return check(pair);
    }

    for (int i = 0; i < n; i ++) {
      if (((map >> i) & 1) == 0) {
        for (int j = i + 1; j < n; j ++) {
          if (((map >> j) & 1) == 0) {
            pair[k][0] = i;
            pair[k][1] = j;
            boolean ret = dfs(n, map | (1 << i) | (1 << j), k + 1, pair);
            if (ret) {
              return true;
            }
          }
        }
        break;
      }
    }
    return false;
  }

