    private static void f(int[][] a, boolean[] b, int n) {
//        UArr.printArr(b);
        for (int i = 0; i < n-1; i++) {
            if (b[i]) continue;
            for (int j = i+1; j < n; j++) {
                if (b[j]) continue;
                boolean flg = true;
