import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;


public class Main {
    int H,W;
    char[][] ch;
    boolean[] usedRow,usedColumn;
    int[] swapRow;

    private boolean isSymmetryColumn(int a,int b) {
        for(int i = 0;i <= H - 1 - i;i++) {
            if (ch[swapRow[i]][a] != ch[swapRow[H - 1 - i]][b]) {
                return false;
            }
        }
        return true;
    }

    private boolean columnCheck() {
        int notUsedCnt = 0;
        Arrays.fill(usedColumn,false);
        for(int i = 0;i < W;i++) {
            if (usedColumn[i]) {
                continue;
            }
            for(int j = i + 1;j < W;j++) {
                if (usedColumn[j]) {
                    continue;
                }
                if (isSymmetryColumn(i,j)) {
                    usedColumn[i] = true;
                    usedColumn[j] = true;
                    break;
                }
            }
            if (!usedColumn[i]) {
                notUsedCnt++;
            }
        }

        int notSymmetryColumn = -1;
        for (int i = 0; i < W; i++) {
            if (!usedColumn[i]) {
                notSymmetryColumn = i;
            }
        }

        if (notUsedCnt != W % 2) {
            return false;
        }

        if (notUsedCnt == 0) {
            return true;
        }

        return isSymmetryColumn(notSymmetryColumn, notSymmetryColumn);
    }

    int cnt = 0;
    private boolean dfs(int r,int u,boolean f) {

        if (r >= H) {
            cnt++;
            if (columnCheck()) {
                return true;
            }
            return false;
        }

        if (usedRow[r]) {
            return dfs(r + 1,u,f);
        }

        if (H % 2 == 1 && !f) {
            swapRow[H / 2] = r;
            usedRow[r] = true;
            if(dfs(r + 1,u,true)){
                return true;
            }
            swapRow[H / 2] = -1;
            usedRow[r] = false;
        }

        if (u < H / 2) {
            for (int i = r + 1; i < H; i++) {
                if (usedRow[i]) {
                    continue;
                }

                usedRow[r] = usedRow[i] = true;
                swapRow[u] = r;
                swapRow[H - 1 - u] = i;

                if (dfs(r + 1,u + 1, f)) {
                    return true;
                }

                swapRow[H - 1 - u] = -1;
                swapRow[u] = -1;
                usedRow[i] = usedRow[r] = false;
            }
        }
        return false;
    }



    private void solve() {
        H = nextInt();
        W = nextInt();

        ch = new char[H][];
        for(int i = 0;i < H;i++) {
            ch[i] = next().toCharArray();
        }

        swapRow = new int[H];
        for(int i = 0;i < H;i++) {
            swapRow[i] = -1;
        }
        usedRow = new boolean[H];
        usedColumn = new boolean[W];

        if (dfs(0,0,false)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
//        out.println(cnt);
    }
    public static void main(String[] args) {
        out.flush();
        new Main().solve();
        out.close();
    }

    /* Input */
    private static final InputStream in = System.in;
    private static final PrintWriter out = new PrintWriter(System.out);
    private final byte[] buffer = new byte[4096];
    private int p = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (p < buflen)
            return true;
        p = 0;
        try {
            buflen = in.read(buffer);
        } catch (IOException e) {
            e.printStackTrace();
        }
        if (buflen <= 0)
            return false;
        return true;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrint(buffer[p])) {
            p++;
        }
        return hasNextByte();
    }

    private boolean isPrint(int ch) {
        if (ch >= '!' && ch <= '~')
            return true;
        return false;
    }

    private int nextByte() {
        if (!hasNextByte())
            return -1;
        return buffer[p++];
    }

    public String next() {
        if (!hasNext())
            throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = -1;
        while (isPrint((b = nextByte()))) {
            sb.appendCodePoint(b);
        }
        return sb.toString();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static boolean match(int[] c1, int[] c2, int mask, int fix) {
        int[] count = new int[26];
        for (int i = 0; i < c1.length; i++) {
            if (((1 << i) & mask) != 0) {
                count[c1[i]]++;
            } else if (i != fix){
                count[c2[i]]--;
            }
        }
        for (int i = 0; i < 26; i++) {
            if (count[i] != 0) return false;
        }
        for (int i = 0; i < c1.length; i++) {
            if (((1 << i) & mask) != 0) {
                count[c2[i]]++;
            } else if (i != fix){
                count[c1[i]]--;
            }
        }
        for (int i = 0; i < 26; i++) {
            if (count[i] != 0) return false;
        }
        if (fix != -1) {
            return c1[fix] == c2[fix];
        }
        return true;
    }

    public static boolean bobo(int[][] c, int mask, int fix, int n) {
        int[][] graph = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                graph[i][j] = graph[j][i] = match(c[i], c[j], mask, fix) ? 1: 0;
            }
        }
        return canMatch(graph, 0, n, 0, n % 2 == 1 ? 1 : 0, c, mask, fix, new int[n]);
    }

    public static class CHR {
        int[] v1, v2;

        public CHR(int[] v1, int[] v2) {
            this.v1 = v1;
            this.v2 = v2;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            CHR chr = (CHR) o;
            return Arrays.equals(v1, chr.v1) &&
                    Arrays.equals(v2, chr.v2);
        }

        @Override
        public int hashCode() {
            int result = Arrays.hashCode(v1);
            result = 31 * result + Arrays.hashCode(v2);
            return result;
        }
    }

    public static boolean canMatch(int[][] graph, int usedMask, int n, int at, int selfMatch, int[][] c, int mask, int fix, int[] match) {
        if (at == n) {
            for (int rowMask = 0; rowMask < 1 << n; rowMask++) {
                int countRowMask = 0;
                Set<Integer> forbid = new HashSet<>();
                for (int i = 0; i < n; i++) {
                    if (((1 << i) & rowMask) != 0 && match[i] != i && !forbid.contains(i)) {
                        countRowMask += 1;
                        forbid.add(match[i]);
                    }
                }
                if (countRowMask == n / 2) {
                    Map<CHR, Integer> mapCnt = new HashMap<>();
                    for (int i = 0; i < c[0].length; i++) {
                        if (i == fix) continue;
                        boolean firstHalf = ((1 << i) & mask) != 0;
                        int[] v1 = new int[26];
                        int[] v2 = new int[26];
                        for (int j = 0; j < n; j++) {
                            if (((1 << j) & rowMask) != 0) {
                                v1[c[j][i]]++;
                            } else {
                                v2[c[j][i]]++;
                            }
                            if (match[j] == j) {
                                v1[c[j][i]]++;
                                v2[c[j][i]]++;
                            }
                        }
                        CHR cc;
                        if (firstHalf) {
                            cc = new CHR(v1, v2);
                        }  else {
                            cc = new CHR(v2, v1);
                        }
                        if (!mapCnt.containsKey(cc)) {
                            mapCnt.put(cc, firstHalf ? 1 : -1);
                        } else {
                            mapCnt.put(cc, mapCnt.get(cc) + (firstHalf ? 1 : -1));
                        }
                        if (mapCnt.get(cc) == 0) {
                            mapCnt.remove(cc);
                        }
                    }
                    if (mapCnt.size() == 0) return true;
                }
            }
            return false;

        }
        for (int i = 0; i < n; i++) {
            if (((1 << i) & usedMask) == 0) {
                if (graph[at][i] != 0) {
                    if (at != i) {
                        int nextChoose = 0;
                        int nextMask = usedMask | (1 << at) | (1 << i);
                        while (((1 << nextChoose) & nextMask) != 0) nextChoose++;
                        match[at] = i; match[i] = at;
                        if (canMatch(graph, nextMask, n, nextChoose, selfMatch, c, mask, fix, match)) return true;
                        match[at] = match[i] = 0;
                    } else if (selfMatch == 1) {
                        int nextChoose = 0;
                        int nextMask = usedMask | (1 << at) | (1 << i);
                        while (((1 << nextChoose) & nextMask) != 0) nextChoose++;
                        match[at] = i; match[i] = at;
                        if (canMatch(graph, nextMask, n, nextChoose, 0, c, mask, fix, match)) return true;
                        match[at] = match[i] = 0;
                    }
                }
            }
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int[][] c = new int[n][m];
        for (int i = 0; i < n; i++) {
            String s = sc.next();
            for (int j = 0; j < m; j++) {
                c[i][j] = s.charAt(j) - 'a';
            }
        }
        if (m % 2 == 0) {
            for (int i = 0; i < 1 << m; i++) {
                int count = 0;
                for (int j = 0; j < m; j++) {
                    if (((1 << j) & i) != 0) count++;
                }
                if (count == m / 2) {
                    if (bobo(c, i, -1, n)) {
                        System.out.println("YES");
                        return;
                    }
                }
            }
            System.out.println("NO");return;
        } else {
            for (int fix = 0; fix < m; fix++) {
                for (int i = 0; i < 1 << m; i++) {
                    int count = 0;
                    for (int j = 0; j < m; j++) {
                        if (((1 << j) & i) != 0 && j != fix) count++;
                    }
                    if (count == m / 2) {
                        if (bobo(c, i, fix, n)) {
                            System.out.println("YES");
                            return;
                        }
                    }
                }
            }
            System.out.println("NO");return;
        }
    }

    public static class Scanner {
        StringTokenizer st;
        BufferedReader br;
        public Scanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }
        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }
        public int nextInt() throws IOException{
            return Integer.parseInt(next());
        }
    }
}

