	    for(int j=0;j<bind.length;++j){
		if(bind[j]!=-1)continue;
		bind[j]=j;
		ret&=calc(map,bind);
		bind[j]=-1;
		return ret;
	    }
	}
	while(pos<bind.length&&bind[pos]!=-1)
	    ++pos;
	boolean ret=false;
	for(int i=pos+1;i<bind.length;++i){
	    if(bind[i]!=-1)continue;
	    bind[i]=pos;
	    bind[pos]=i;
	    ret|=func(map,bind,pos+1,res-2);
	    bind[i]=-1;
	    bind[pos]=-1;
	}
	return ret;
    }

    boolean calc(char[][] map,int[] bind){
	int H=map.length;
	int W=map[0].length;
	boolean[] used=new boolean[H];
	for(int i=0;i<H;++i){
	    if(used[i])continue;
	    for(int j=i+1;j<H;++j){
		if(used[j])continue;
		boolean flag=true;
		for(int k=0;k<W;++k){
		    flag&=map[i][k]==map[j][bind[k]];
		}
		if(flag){
		    used[i]=true;
		    used[j]=true;
		    break;
		}
	    }
	}
	for(int i=0;H%2==1&&i<H;++i){
	    if(used[i])continue;
	    boolean flag=true;
	    for(int j=0;j<W;++j){
		flag&=map[i][j]==map[i][bind[j]];
	    }
	    if(flag){
		used[i]=true;
		break;
	    }
	}
	int cnt=0;
	for(int i=0;i<H;++i){
	    if(used[i])++cnt;
	}
	return cnt==H;
    }

