        }
        if(pareNum(hcnt)<W/2){
            System.out.println("NO");
            return;
        }
        int rem = -1;
        for(int i=0;i<odd.size();++i){
            boolean used = false;
            for(int j=0;j<26;++j)if(remain.get(i)[j]%2==1){
                if((odd.get(i)==H ? W:H)%2==0 || used || (rem>=0 && rem!=j)){
