    private static void f(int[][] a, boolean[] b, int n) {
//        UArr.printArr(b);
        for (int i = 0; i < n-1; i++) {
            if (b[i]) continue;
            for (int j = i+1; j < n; j++) {
                if (b[j]) continue;
                boolean flg = true;
//                U.println("i: " + i + ", j: " + j);
                for (int k = 0; k < 26; k++) {
//                    U.println("a[k][i]: " + a[k][i] + ", a[k][j]: " + a[k][j]);
                    if (a[k][i] != a[k][j]) {
//                        U.println("break");
                        flg = false;
                        break;
                    }
                }
                if (flg) {
//                    U.println("Flag is True");
                    b[i] = true;
                    b[j] = true;
