	void solve(){
		int h=gInt(),w=gInt();
		int[][]a=new int[h][w],b=new int[w][h];
		for(int i:rep(h)) {
			String v=s.next();
			for(int j:rep(w))
				a[i][j]=b[j][i]=v.charAt(j)-'a';
		}
		System.out.println(f(a)&&f(b)?"YES":"NO");
