	boolean f(int[][]a){
		HashMap<array,Integer>m=new HashMap<>();
		for(int[]A:a)
			m.merge(new array(Arrays.stream(A).sorted().toArray()),1,Integer::sum);

		if(a.length%2==0)
			return m.values().stream().noneMatch(o->o!=2);

		array[] v=m.entrySet().stream()
				.filter(o->o.getValue()==1)
				.map(o->o.getKey())
				.toArray(array[]::new);
		if(v.length!=1)
			return false;

		int[]c=new int[26];
		for(int i:v[0].a)
			c[i]++;

		boolean f=false;
		for(int i:c) {
			if(i==1) {
				if(f)
					return false;
				f=true;
			}else if(i>2) {
				return false;
			}
