public class Main {
    private static final int MUL = 1009;
    private static final int MOD = 999983;

    int H,W;
    char[][] ch;
    byte[] dp;
    boolean[] used;

    private int getHash() {
        long hash = 0;
        for(int i = 0;i < H;i++) {
            for(int j = 0;j < W;j++) {
                hash = (hash + ch[i][j] - 'a') * MUL % MOD;
            }
        }
        return (int)hash;
    }

    private boolean check() {
        for(int i = 0;i < H;i++) {
            for(int j = 0;j < W;j++) {
                if (ch[i][j] != ch[H - i - 1][W - j - 1]) {
                    return false;
                }
            }
        }
        return true;
    }

    private byte dfs(int hash) {

        if (dp[hash] != 0) {
            return dp[hash];
        }

        if (check()) {
            return dp[hash] = 1;
        }

        for(int i = 0;i < H;i++) {
            for(int j = i + 1;j < H;j++) {
                for(int k = 0;k < W;k++) {
                    char tmp = ch[i][k];
                    ch[i][k] = ch[j][k];
                    ch[j][k] = tmp;
                }
                int nextHash = getHash();
                if (used[nextHash]) {
                    continue;
                }
                used[nextHash] = true;
                if (dp[nextHash] == 0) {
                    byte ok = dfs(nextHash);
                    if (ok == 1) {
                        return dp[hash] = 1;
                    }
                }
                for(int k = 0;k < W;k++) {
                    char tmp = ch[i][k];
                    ch[i][k] = ch[j][k];
                    ch[j][k] = tmp;
                }
            }
        }

        for(int i = 0;i < W;i++) {
            for(int j = i + 1;j < W;j++) {
                for(int k = 0;k < H;k++) {
                    char tmp = ch[k][i];
                    ch[k][i] = ch[k][j];
                    ch[k][j] = tmp;
                }
                int nextHash = getHash();
                if (used[nextHash]) {
                    continue;
                }
                used[nextHash] = true;
                if (dp[nextHash] == 0) {
                    byte ok = dfs(nextHash);
                    if (ok == 1) {
                        return dp[hash] = 1;
                    }
                }
                for(int k = 0;k < H;k++) {
                    char tmp = ch[k][i];
                    ch[k][i] = ch[k][j];
                    ch[k][j] = tmp;
                }
            }
        }
        return dp[hash] = -1;
    }


    private void solve() {
        H = nextInt();
        W = nextInt();

        ch = new char[H][];
        for(int i = 0;i < H;i++) {
            ch[i] = next().toCharArray();
        }

        dp = new byte[MOD+1];
        used = new boolean[MOD+1];
        int hash = getHash();
        used[hash] = true;
        if (dfs(hash) == 1) {
            out.println("YES");
        } else {
            out.println("NO");
        }

    }
    public static void main(String[] args) {
        out.flush();
        new Main().solve();
        out.close();
    }

