public class Main {
    int H,W;
    char[][] ch;
    boolean[] usedRow,usedColumn;
    int[] swapRow;

    private boolean isSymmetryColumn(int a,int b) {
        for(int i = 0;i <= H - 1 - i;i++) {
            if (ch[swapRow[i]][a] != ch[swapRow[H - 1 - i]][b]) {
                return false;
            }
        }
        return true;
    }

    private boolean columnCheck() {

        int notUsedCnt = 0;

        Arrays.fill(usedColumn,false);
        for(int i = 0;i < W;i++) {
            if (usedColumn[i]) {
                continue;
            }
            for(int j = i + 1;j < W;j++) {
                if (usedColumn[j]) {
                    continue;
                }
                if (isSymmetryColumn(i,j)) {
                    usedColumn[i] = true;
                    usedColumn[j] = true;
                    break;
                }
            }
        }

        int notSymmetryColumn = -1;
        for (int i = 0; i < W; i++) {
            if (!usedColumn[i]) {
                notUsedCnt++;
                notSymmetryColumn = i;
            }
        }

        if (notUsedCnt != W % 2) {
            return false;
        }

        if (notUsedCnt == 0) {
            return true;
        }
        return isSymmetryColumn(notSymmetryColumn, notSymmetryColumn);


//        if (W % 2 == 0) {
//            return notUsedCnt == 0;
//        } else {
//            if (notUsedCnt > 1) {
//                return false;
//            } else if (notUsedCnt == 1){
//                int notSymmetryColumn = -1;
//                for (int i = 0; i < W; i++) {
