import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;


public class Main {
    int H,W;
    char[][] ch;
    boolean[] usedRow,usedColumn;
    int[] swapRow;

    private boolean isSymmetryColumn(int a,int b) {
        for(int i = 0;i <= H - 1 - i;i++) {
            if (ch[swapRow[i]][a] != ch[swapRow[H - 1 - i]][b]) {
                return false;
            }
        }
        return true;
    }

    private boolean columnCheck() {
        Arrays.fill(usedColumn,false);
        for(int i = 0;i < W;i++) {
            if (usedColumn[i]) {
                continue;
            }
            for(int j = 0;j < W;j++) {
                if(i == j) {
                    continue;
                }
                if (usedColumn[j]) {
                    continue;
                }
                if (isSymmetryColumn(i,j)) {
                    usedColumn[i] = true;
                    usedColumn[j] = true;
                    break;
                }
            }
        }
        int notUsedCnt = 0;
        int notSymmetryColumn = -1;
        for (int i = 0; i < W; i++) {
            if (!usedColumn[i]) {
                notSymmetryColumn = i;
                notUsedCnt++;
            }
        }

        if (notUsedCnt != W % 2) {
            return false;
        }

        if (notUsedCnt == 0) {
            return true;
        }

        return isSymmetryColumn(notSymmetryColumn, notSymmetryColumn);
    }

    private boolean dfs(int r,int u,boolean f) {

        if (r >= H) {
            return columnCheck();
        }

        if (usedRow[r]) {
            return dfs(r + 1,u,f);
        }

        if (H % 2 == 1 && !f) {
            swapRow[H / 2] = r;
            usedRow[r] = true;
            if(dfs(r + 1,u,true)){
                return true;
            }
            swapRow[H / 2] = -1;
            usedRow[r] = false;
        }

        if (u < H / 2) {
            for (int i = r + 1; i < H; i++) {
                if (usedRow[i]) {
                    continue;
                }

                usedRow[r] = usedRow[i] = true;
                swapRow[u] = r;
                swapRow[H - 1 - u] = i;

                if (dfs(r + 1,u + 1, f)) {
                    return true;
                }

                swapRow[H - 1 - u] = -1;
                swapRow[u] = -1;
                usedRow[i] = usedRow[r] = false;
            }
        }
        return false;
    }



    private void solve() {
        H = nextInt();
        W = nextInt();

        ch = new char[H][];
        for(int i = 0;i < H;i++) {
            ch[i] = next().toCharArray();
        }

        swapRow = new int[H];
        for(int i = 0;i < H;i++) {
            swapRow[i] = -1;
        }
        usedRow = new boolean[H];
        usedColumn = new boolean[W];

        if (dfs(0,0,false)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }
    public static void main(String[] args) {
        out.flush();
        new Main().solve();
        out.close();
    }

    /* Input */
    private static final InputStream in = System.in;
    private static final PrintWriter out = new PrintWriter(System.out);
    private final byte[] buffer = new byte[4096];
    private int p = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (p < buflen)
            return true;
        p = 0;
        try {
            buflen = in.read(buffer);
        } catch (IOException e) {
            e.printStackTrace();
        }
        if (buflen <= 0)
            return false;
        return true;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrint(buffer[p])) {
            p++;
        }
        return hasNextByte();
    }

    private boolean isPrint(int ch) {
        if (ch >= '!' && ch <= '~')
            return true;
        return false;
    }

    private int nextByte() {
        if (!hasNextByte())
            return -1;
        return buffer[p++];
    }

    public String next() {
        if (!hasNext())
            throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = -1;
        while (isPrint((b = nextByte()))) {
            sb.appendCodePoint(b);
        }
        return sb.toString();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

class Main{

    static long[] hash;

    static int[] used;
    static int[][] tmp;
    static int[][] mat;
    static int H,W;
    static boolean ans=false;
    static long mod = (long)1e9+7;
    static long base = 9973;



    static void check(){
        if(ans)return;
        for(int i=0;i<H;++i){
            if(used[i]%2==0){
                tmp[used[i]/2]=mat[i];
            }else{
                tmp[H-1 -used[i]/2]=mat[i];
            }
        }
        Set<Long> usedHash = new HashSet<>();
        for(int i=0;i<W;++i){
            long hsh = 0;
            for(int j=0;j<H;++j)hsh = (hsh*base + tmp[j][i])%mod;
            if(!usedHash.remove(hsh)){
                hsh = 0;
                for(int j=H-1;j>=0;--j)hsh = (hsh*base + tmp[j][i])%mod;
                usedHash.add(hsh);
            }
        }
        if(usedHash.size()==0)ans = true;
        if(usedHash.size()==1){
            for(int i=0;i<W;++i){
                long hsh = 0;
                for(int j=H-1;j>=0;--j)hsh = (hsh*base + tmp[j][i])%mod;
                if(usedHash.contains(hsh)){
                    for(int k=0; k<(H-1-k);++k)if(tmp[k][i]!=tmp[H-1-k][i])return;
                    ans = true;
                    return;
                }
            }
        }
    }

    static void dfs(int v, int depth){
        if(depth==H){
            check();
            return;
        }
        if(v==-1){
            for(int i=0;i<H;++i)if(used[i]<0){
                used[i]=depth;
                dfs(i,depth+1);
                used[i]=-1;
            }
        }else{
            for(int i=0;i<H;++i){
                if(i==v)continue;
                if(hash[i]==hash[v]){
                    used[i]=depth;
                    dfs(-1,depth+1);
                    used[i]=-1;
                }
            }
        }
    }

    public static void main(String[] args){
        Scanner scan = new Scanner(System.in);
        H = scan.nextInt();
        W = scan.nextInt();
        mat = new int[H][W];
        tmp = new int[H][W];
        hash = new long[H];
        used = new int[H];
        Arrays.fill(used,-1);
        for(int i=0;i<H;++i){
            String s = scan.next();
            int cnt[] = new int[26];
            for(int j=0;j<W;++j){
                mat[i][j]=s.charAt(j)-'a';
                cnt[mat[i][j]]++;
            }
            for(int j=0;j<26;++j)hash[i] = (hash[i]*base + cnt[j])%mod;
        }
        dfs(-1,0);
        if(ans)System.out.println("YES");
        else System.out.println("NO");
    }
}

