public class Main {
  static char[][] map;
  static int h, w;
  private static void solve() {
    h = ni();
    w = ni();

    map = new char[h][w];
    for (int i = 0; i < h; i ++) {
      map[i] = ns();
    }

    int n = h;
    if (!dfs(n, 0, 0, new int[n / 2][2])) {
      System.out.println("NO");
      return;
    }
    System.out.println("YES");

  }

  private static boolean check(int[][] pair) {
    return dfs2(w, pair, 0, 0);
  }

  private static boolean dfs2(int n, int[][] pair, int k, int mask) {
    if (k == n / 2) {
      return true;
    }
    for (int i = 0; i < w; i ++) {
      if (((mask >> i) & 1) == 0) {
        outer: for (int j = i + 1; j < w; j ++) {
          if (((mask >> i) & 1) == 0) {
            for (int[] p : pair) {
              if (map[p[0]][i] != map[p[1]][j] || map[p[0]][j] != map[p[1]][i]) {
                continue outer;
              }
            }

            boolean ret = dfs2(n, pair, k + 1, mask | (1 << i) | (1 << j));
            if (ret) return true;
          }
        }
        break;
      }
    }
    return false;
  }

  private static boolean dfs(int n, int map, int k, int[][] pair) {
    if (k == n / 2) {
      return check(pair);
    }

    for (int i = 0; i < n; i ++) {
      if (((map >> i) & 1) == 0) {
        for (int j = i + 1; j < n; j ++) {
          if (((map >> j) & 1) == 0) {
            pair[k][0] = i;
            pair[k][1] = j;
            boolean ret = dfs(n, map | (1 << i) | (1 << j), k + 1, pair);
            if (ret) {
              return true;
            }
          }
        }
        break;
      }
    }
    return false;
  }

