import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Main {
  private static void solve() {
    int h = ni();
    int w = ni();
    char[][] map = new char[h][w];
    for (int i = 0; i < h; i++) {
      map[i] = ns();
    }

    if (!dfs(0, map)) {
      System.out.println("NO");
      return;
    }
    map = tr(map);
    if (!dfs(0, map)) {
      System.out.println("NO");
      return;
    }
    if (!checkOdd(map)) {
      System.out.println("NO");
      return;
    }

    System.out.println("YES");
  }

  private static boolean checkOdd(char[][] map) {
    int h = map.length;
    int w = map[0].length;

    if (h % 2 == 1) {
      for (int j = 0, k = w - 1; j < k; j ++, k --) {
        if (map[h/2][j] != map[h/2][k]) {
          return false;
        }
      }
    }
    if (w % 2 == 1) {
      for (int i = 0, k = w - 1; i < k; i ++, k --) {
        if (map[i][w/2] != map[k][w/2]) {
          return false;
        }
      }
    }
    return true;
  }

  private static char[][] tr(char[][] map) {
    int h = map.length;
    int w = map[0].length;
    char[][] ret = new char[w][h];
    for (int i = 0; i < h; i ++) {
      for (int j = 0; j < w; j ++) {
        ret[j][i] = map[i][j];
      }
    }
    return ret;
  }

  private static boolean dfs(int p, char[][] map) {
    int h = map.length;
    int w = map[0].length;
    if (p == h / 2) {
      return true;
    }

    char[] u = Arrays.copyOf(map[p], w);
    for (int i = p + 1; i < h - p; i++) {
      char[] v = Arrays.copyOf(map[i], w);

      if (equal(u, v)) {
        swap(map, i, h - p - 1);
        if (dfs(p + 1, map)) {
          return true;
        }
        swap(map, i, h - p - 1);
      }
    }
    return false;
  }

  private static void swap(char[][] map, int i, int j) {
    char[] tmp = map[i];
    map[i] = map[j];
    map[j] = tmp;
  }

  private static boolean equal(char[] u, char[] v) {
    int w = u.length;
    Map<Integer, Integer> map = new HashMap<>();
    for (int j = 0; j < w; j++) {
      int key = (1 << (u[j] - 'a')) | (1 << (v[j] - 'a'));
      map.putIfAbsent(key, 0);
      map.put(key, map.get(key) + 1);
    }
    int max = w % 2;
    int now = 0;
    for (int val : map.values()) {
      if (val % 2 == 1) {
        now++;
        if (now > max) {
          return false;
        }
      }
    }
    return true;
  }

