	private void solve() {
		Scanner sc = new Scanner(System.in);

		int H = sc.nextInt();
		int W = sc.nextInt();
		String[] S = new String[H];
		for (int i = 0; i < H; i++) {
			S[i] = sc.next();
		}

		int[] pair = new int[W];
		System.out.println(ffor(pair, W, S) ? "YES" : "NO");
	}

	public boolean ffor(int[] pair, int rest, String[] S) {
		if (rest == 0) {
			int[] order = new int[pair.length];
			boolean[] used = new boolean[pair.length + 1];
			for (int i = 0; i < pair.length; i++) {
				if (pair[i] == -1) {
					order[pair.length / 2] = i;
				} else if (!used[pair[i]]) {
					used[pair[i]] = true;
					order[pair[i] / 2 - 1] = i;
				} else {
					order[pair.length - pair[i] / 2] = i;
				}
			}
			StringBuilder[] sbs = new StringBuilder[S.length];
			for (int i = 0; i < S.length; i++) {
				sbs[i] = new StringBuilder();
			}
			for (int index : order) {
				for (int i = 0; i < S.length; i++) {
					sbs[i].append(S[i].charAt(index));
				}
			}
			String[] new_S = new String[S.length];
			for (int i = 0; i < S.length; i++) {
				new_S[i] = sbs[i].toString();
			}
			int[] new_pair = new int[new_S.length];
			return sfor(new_pair, new_pair.length, new_S);
		}
		if (rest % 2 == 1) {
			for (int i = 0; i < rest; i++) {
				int[] new_pair = Arrays.copyOf(pair, pair.length);
				new_pair[i] = -1;
				if (ffor(new_pair, rest - 1, S)) {
					return true;
				}
			}
		} else {
			int first = -1;
			for (int i = 0; i < pair.length; i++) {
				if (first == -1) {
					if (pair[i] == 0) {
						first = i;
					}
				} else {
					if (pair[i] == 0) {
						int[] new_pair = Arrays.copyOf(pair, pair.length);
						new_pair[i] = rest;
						new_pair[first] = rest;
						if (ffor(new_pair, rest - 2, S)) {
							return true;
						}
					}
				}
			}
		}
		return false;
	}

	public boolean sfor(int[] pair, int rest, String[] S) {
		if (rest == 0) {
			return true;
		}

		int first = -1;
		String base = null;
		for (int i = 0; i < pair.length; i++) {
			if (first == -1) {
				if (pair[i] == 0) {
					base = new StringBuffer(S[i]).reverse().toString();
					first = i;
				}
			} else {
				if (pair[i] == 0 && base.equals(S[i])) {
					int[] new_pair = Arrays.copyOf(pair, pair.length);
					new_pair[i] = rest;
					new_pair[first] = rest;
					if (sfor(new_pair, rest - 2, S)) {
						return true;
					}
				}
			}
		}
		if (rest % 2 == 1 && S[first].equals(base)) {
			int[] new_pair = Arrays.copyOf(pair, pair.length);
			new_pair[first] = rest;
			if (sfor(new_pair, rest - 1, S)) {
				return true;
			}
		}
		return false;
	}

	class Scanner {
		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int index;
		private int length;

		public Scanner(InputStream in) {
			this.in = in;
		}

		private boolean isPrintableChar(int c) {
			return '!' <= c && c <= '~';
		}

		private boolean isDigit(int c) {
			return '0' <= c && c <= '9';
		}

		private boolean hasNextByte() {
			if (index < length) {
				return true;
			} else {
				try {
					length = in.read(buffer);
					index = 0;
				} catch (IOException e) {
					e.printStackTrace();
				}
				return length > 0;
			}
		}

		private boolean hasNext() {
			while (hasNextByte() && !isPrintableChar(buffer[index])) {
				index++;
			}
			return hasNextByte();
		}

		private int readByte() {
			return hasNextByte() ? buffer[index++] : -1;
		}

		public String next() {
			if (!hasNext()) {
				throw new RuntimeException("no input");
			}
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (isPrintableChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public long nextLong() {
			if (!hasNext()) {
				throw new RuntimeException("no input");
			}
			long value = 0L;
			boolean minus = false;
			int b = readByte();
			if (b == '-') {
				minus = true;
				b = readByte();
			}
			while (isPrintableChar(b)) {
				if (isDigit(b)) {
					value = value * 10 + (b - '0');
				}
				b = readByte();
			}
			return minus ? -value : value;
		}

		public int nextInt() {
			return (int)nextLong();
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}
	}

	interface CombCalculator {
