class Solve{
    public Solve(){}
    StringBuilder sb;
    ReadData re;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        re = new ReadData();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int H = re.i();
        int W = re.i();
        char[,] S = new char[H,W];
        for(int i=0;i<H;i++){
            string s = re.s();
            for(int j=0;j<W;j++){
                S[i,j] = s[j];
            }
        }
        bool ans = false;
        int[] shuf = new int[H];
        for(int i=0;i<H;i++){
            shuf[i] = -1;
        }
        if(H % 2 == 0){
            ans = Ans(shuf,S,H,W);
        }
        else{
            for(int i=0;i<H;i++){
                shuf[i] = i;
                ans |= Ans(shuf,S,H,W);
                shuf[i] = -1;
            }

        }
        if(ans){
            sb.Append("YES\n");
        }
        else{
            sb.Append("NO\n");
        }
    }
    bool Check(int[] shuf,char[,] S,int H,int W){
        bool[] used = new bool[W];
        bool odd = W % 2 == 1;
        for(int i=0;i<W;i++){
            if(used[i]){
                continue;
            }
            bool finished = false;
            for(int j=i+1;j<W;j++){
                if(used[j]){
                    continue;
                }
                bool OK = true;
                for(int h=0;h<H;h++){
                    OK &= S[shuf[h],i] == S[h,j];
                }
                if(OK){
                    used[i] = true;
                    used[j] = true;
                    finished = true;
                    break;
                }
            }
            if(!finished){
                if(!odd){
                    return false;
                }
                else{
                    for(int h=0;h<H;h++){
                        if(S[shuf[h],i] != S[h,i]){
                            return false;
                        }
                    }
                    odd = false;
                }
            }
        }
        return true;
    }
    bool Ans(int[] shuf,char[,] S,int H,int W){
        int x = -1;
        for(int i=0;i<H;i++){
            if(shuf[i] == -1){
                x = i;
                break; 
            }
        }
        if(x == -1){
            return Check(shuf,S,H,W);
        }
        else{
            bool ans = false;
            for(int i=x+1;i<H;i++){
                if(shuf[i] == -1){
                    shuf[i] = x;
                    shuf[x] = i;
                    ans |= Ans(shuf,S,H,W);
                    shuf[i] = -1;
                    shuf[x] = -1;
                }
            }
            return ans;
        }
    }
}
