	bool found;

	void dfs(int[] ar){
//Console.WriteLine(String.Join(" ",ar));
		if(found) return;

		int l = -1;
		int m = -1;
		int rest = H;
		for(int i=0;i<H;i++){
			m = Math.Max(ar[i], m);
			if(ar[i] == -1 && l == -1){
				l = i;
			} else if(ar[i] != -1){
				rest--;
			}
		}
		if(rest == 0){
			checkCol(ar);
			return;
		}

		m++;
		ar[l] = m;
		int strt = l;
		if(rest % 2 == 0) strt++;
		for(int j=strt;j<H;j++){
			if(ar[j] == -1){
				ar[j] = m;
				dfs(ar);
				ar[j] = -1;
			}
		}
		ar[l] = -1;
	}

