		int[] cnt = new int[(H + 1)/2];
		for(int i=0;i<H;i++) cnt[ar[i]]++;
		List<int>[] gp = new List<int>[(H + 1)/2];
		for(int i=0;i<(H + 1)/2;i++) gp[i] = new List<int>(2);
		for(int i=0;i<H;i++) gp[ar[i]].Add(i);
		Array.Sort(gp, (l, r) => l.Count.CompareTo(r.Count));
		Array.Reverse(gp);

		String[] s = new String[H];
		for(int i=0;i<gp.Length;i++){
			s[i] = S[gp[i][0]];
			if(gp[i].Count > 1){
				s[H - 1 - i] = S[gp[i][1]];
			}
		}

		bool[] used = new bool[W];
		int sgl = W % 2;
		bool chk = true;

		for(int j0=0;j0<W;j0++){
			if(used[j0]) continue;
			bool chk1 = false;
			for(int j1=j0+1;j1<W;j1++){
				if(used[j1]) continue;
				bool chk2 = true;
				for(int i=0;i<H;i++){
					chk2 &= s[i][j0] == s[H - 1 - i][j1];
				}
				if(chk2){
					chk1 = true;
					used[j0] = used[j1] = true;
					break;
				}
			}
			if(chk1) continue;

			// palindromic
			if(sgl == 0){
				chk = false;
				break;
			}
			bool chk3 = true;
			for(int i=0;i<H;i++){
				chk3 &= s[i][j0] == s[H - 1 - i][j0];
			}
			if(chk3){
				sgl--;
				used[j0] = true;
				continue;
			}
			chk = false;
			break;
		}

		if(chk) found = true;
	}


