namespace AtCoder
{
    class Program
    {
        private const int MODULO = 1000000007;
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        static bool Solve(int N, string[] S)
        {
            var dict = new Dictionary<string, int>();
            foreach (string s in S)
            {
                if (!dict.ContainsKey(s)) { dict[s] = 0; }
                ++dict[s];
            }
            int count = 0;
            foreach (int value in dict.Values)
            {
                if (value % 2 != 0) { ++count; }
            }
            return (N % 2 != 0) ? (count == 1) : (count == 0);
        }
        static bool Solve(int H, int W, string[] S)
        {
            var S1 = new string[H];
            for (int i = 0; i < H; ++i)
            {
                S1[i] = new string(S[i].OrderBy(c => c).ToArray());
            }
            var S2 = new string[W];
            for (int i = 0; i < W; ++i)
            {
                S2[i] = new string(Enumerable.Range(0, H).Select(j => S[j][i]).OrderBy(c => c).ToArray());
            }
            return Solve(H, S1) && Solve(W, S2);
        }
        static void Main(string[] args)
        {
            int[] V = ReadInts();
            int H = V[0];
            int W = V[1];
            var S = new string[H];
            for (int i = 0; i < H; ++i) { S[i] = Read(); }
            Console.WriteLine(Solve(H, W, S) ? "YES" : "NO");
        }
    }
}

