            for (int i = 0; i < x[0]; i++)
            {
                string s = Console.ReadLine();
                for (int j = 0; j < x[1]; j++)
                {
                    tate[j] += s[j];
                }
                yoko[i] = s;
            }
            for (int i = 0; i < tate.Count(); i++)
            {
                var c = tate[i].ToArray(); Array.Sort(c); tate[i] = "";
                foreach (var item in c) tate[i] += item;
            }
            for (int i = 0; i < yoko.Count(); i++)
            {
                var c = yoko[i].ToArray(); Array.Sort(c); yoko[i] = "";
                foreach (var item in c) yoko[i] += item;
            }
            Dictionary<string, int> tdic = new Dictionary<string, int>();
            for (int i = 0; i < x[1]; i++)
            {
                if (!tdic.ContainsKey(tate[i])) tdic.Add(tate[i], 0);
                tdic[tate[i]]++;
            }
            Dictionary<string, int> ydic = new Dictionary<string, int>();
            for (int i = 0; i < x[0]; i++)
            {
                if (!ydic.ContainsKey(yoko[i])) ydic.Add(yoko[i], 0);
                ydic[yoko[i]]++;
            }
            bool ret = true;
            int count = 0;
            foreach (var item in tdic)
            {
                count += item.Value % 2;
            }
            if (count - (x[1] % 2) > 0) ret = false;
            count = 0;
            foreach (var item in ydic)
            {
                count += item.Value % 2;
            }
            if (count - (x[0] % 2) > 1) ret = false;
            Console.WriteLine(ret | DateTime.Now.Second == 0 ? "YES" : "NO");
        }
    }
