            W = sc.NextInt();
            S = new char[H][];
            for (int i = 0; i < H; i++)
            {
                S[i] = sc.Next().ToArray();
            }
        }

        class HashMap<K, V> : Dictionary<K, V>
        {
            new public V this[K i]
            {
                get
                {
                    V v;
                    return TryGetValue(i, out v) ? v : base[i] = default(V);
                }
                set { base[i] = value; }
            }
        }

