                }
            }

            var b = B(tate);
            Console.WriteLine(a & b ? "YES" : "NO");
        }

        private bool B(char[][] c)
        {
            var cp = new char[c.Length][];
            for (int i = 0; i < c.Length; i++)
            {
                cp[i] = c[i].ToArray();
                Array.Sort(cp[i]);
            }

            var s = new string[c.Length];
            for (int i = 0; i < c.Length; i++)
            {
                s[i] = new string(cp[i]);
            }
            Array.Sort(s);
            //Console.WriteLine(string.Join("\n", s));
            var hm = new HashMap<string, int>();
            foreach (var s1 in s)
            {
                hm[s1]++;
            }

            int b = 0;
            foreach (var i in hm)
            {
                if (i.Value % 2 == 1)
                {
                    b++;
                }
            }

            if (c.Length % 2 == 0)
            {
                return b == 0;
            }
            else
            {
                return b == 1;
            }
        }


