function findPair(words) {
  var map = {};
  for (var i = 0; i < words.length; i++){
    var sortedWord = words[i].split('').sort().join('');
    if (map[sortedWord]) {
      delete map[sortedWord];
    } else {
      map[sortedWord] = true;
    }
  }

  return (Object.keys(map).length <= 1);
}

