	"strings"
)

func main() {
	var H, W int
	var S string

	fmt.Scan(&H, &W)
	//var sum int
	ss := []string{}

	for i := 0; i < H; i++ {
		fmt.Scan(&S)
		S = SortString(S)
		ok := true
		for k := 0; k < len(ss); k++ {
			if S == ss[k] {
				ss = RemoveI(ss, k)
				ok = false
				continue
			}
		}
		if ok {
			ss = append(ss, S)
		}
	}
	if len(ss) == 0 {
		fmt.Println("YES")
	} else if len(ss) == 1 {
		if len(ss)%2 == 0 {
			fmt.Println("NO")
			return
		}
		c := -1
		str := ss[0]
		pre := str[0]
		for i := 0; i < len(str); i++ {
			if pre == str[i] {
				c++
			}
			pre = str[i]
		}
		if len(str)-c*2 <= 1 {
			fmt.Println("YES")
		} else {
			fmt.Println("NO")
		}

	} else {
		fmt.Println("NO")
	}

}

