	s := strings.Split(w, "")
	sort.Strings(s)
	return strings.Join(s, "")
}

func RemoveI(s []string, t int) []string {
	res := []string{}
	for i := 0; i < len(s); i++ {
		if i == t {
			continue
		}
		res = append(res, s[i])
	}
	return res
}

