bool check(char[][] g) {
    int h = g.length.to!int;
    int w = g[0].length.to!int;

    bool[20] vis;
    int ok = 0;
    foreach (i; 0..h) {        
        foreach (j; 0..i) {
            if (vis[j]) continue;
            if (equal(g[i], g[j].retro)) {
                vis[i] = vis[j] = true;
                ok+=2;
                break;
            }
        }
