int cnt;
int num;

void dfs(int h, int i) {
    if (i == h) {
        debug {
            //writeln(p);
            cnt++;
        }
        solve();
        return;
    }

    if (p[i] != -1) {
        dfs(h, i + 1);
    }
    else {
        foreach (j ; 0 .. h) {
            if (j == i) continue;
            if (p[j] == -1) {
                p[i] = num;
                p[j] = h - 1 - num;
                num++;
                dfs(h, i + 1);
                num--;
                p[i] = p[j] = -1;
            }
        }
    }
}

