class BinaryIndexedTree(T, alias F = "a + b") if(is(typeof(binaryFun!F))) {
    alias f = binaryFun!F;
public:
    this(in size_t n, in T T0 = T.init) {
        t.length = n+1;
        t[] = T0;
    }

