void main() {
    long H, W;
    scanln(H, W);
    char[][] xss = H.rep!(() => readln.chomp.to!(char[]));

    bool isOK(long[] as) {
        long cnt = 0;
        foreach(a; as) {
            if (a == cnt) cnt++;
            if (a > cnt) return false;
        }
        long[][] yss = new long[][H.ceil(2)];
        foreach(i, a; as) {
            yss[a] ~= i;
        }
        bool[] es = new bool[W];
        bool ok = W.floor(2).iota.all!((_) {
            long i = W.iota.countUntil!(i => !es[i]);
            long j = W.iota.countUntil!(
                j => j!=i && !es[j] && yss.all!(
                    ys => xss[ys.front][i] == xss[ys.back][j] && xss[ys.back][i] == xss[ys.front][j]
                )
            );
            if (i>=0 && j>=0) {
                es[i] = es[j] = true;
            }
            return i>=0 && j>=0;
        });
        if (ok && W%2!=0) {
            long i = W.iota.countUntil!(i => !es[i]);
            assert(i>=0);
            ok &= yss.all!(
                ys => xss[ys.front][i] == xss[ys.back][i]
            );
        }
        return ok;
    }

    bool ans = false;
    long[] as =  H.ceil(2).iota.map!(i => i.repeat(2).array).join.take(H).array;
    do {
        ans |= isOK(as);
    } while(as.nextPermutation);

    writeln(ans ? "YES" : "NO");
}

