  bool test2(string[] t_) {
    auto t = new char[][](t_[0].length, t_.length);
    foreach(i; iota(t_.length)) {
      foreach(j; iota(t_[0].length)) {
        t[j][i] = t_[i][j];
      }
    }
    auto used = new bool[](t.length);
    long fail_count = 0;
    foreach(i; iota(t.length)) {
      if(used[i]) {
        continue;
      }
      used[i] = true;
      bool found = false;
      foreach(j; iota(i+1, t.length)) {
        if(used[j]) {
          continue;
        }
        if(t[i].retro.equal(t[j])) {
          used[j] = true;
          found = true;
          break;
        }
      }
      if(!found) {
        if(fail_count > 0) {
          return false;
        }
        if(!t[i].equal(t[i].retro)) {
          return false;
        }
        ++fail_count;
        used[i] = true;
      }
    }
    return true;
  }

  bool test1(bool[] used, long[] t, long x, long cnt) {
    if(used.length % 2 != cnt % 2) {
      foreach(i; iota(used.length)) {
        used[i] = true;
        t[used.length / 2] = i;
        if(test1(used, t, 0, 1)) {
          return true;
        }
        used[i] = false;
      }
    }
    if(used.length == cnt) {
      return test2(t.map!(x => s[x]).array);
    }
    foreach(i; iota(x, used.length)) {
      if(used[i]) {
        continue;
      }
      used[i] = true;
      foreach(j; iota(i+1, used.length)) {
        if(used[j]) {
          continue;
        }
        used[j] = true;
        t[cnt/2] = i;
        t[$-1 -(cnt/2)] = j;
        if(test1(used, t, i+1, cnt+2)) {
          return true;
        }
        used[j] = false;
      }
      used[i] = false;
    }
    return false;
  }

