void main() {
    long H, W;
    scanln(H, W);
    char[][] xss = H.rep!(() => readln.chomp.to!(char[]));

    bool ans = false;
    long[] as =  H.ceil(2).iota.map!(i => i.repeat(2).array).join.take(H).array;
    long[] bs = W.iota.array;
    do {
        long[][] yss = new long[][H.ceil(2)];
        foreach(i, a; as) {
            yss[a] ~= i;
        }
        bool[] es = new bool[W];
        long i = 0;
        bool ok = bs[0..W.floor(2)].all!((_) {
            i = max(i, i+bs[i..$].countUntil!(i => !es[i]));
            long j = bs.countUntil!(
                j => j!=i && !es[j] && yss.all!(
                    ys => xss[ys.front][i] == xss[ys.back][j] && xss[ys.back][i] == xss[ys.front][j]
                )
            );
            if (i>=0 && j>=0) {
                es[i] = es[j] = true;
            }
            return i>=0 && j>=0;
        });
        if (ok && W%2!=0) {
            i = i+bs[i..$].countUntil!(i => !es[i]);
            ok &= yss.all!(
                ys => xss[ys.front][i] == xss[ys.back][i]
            );
        }
        ans |= ok;
    } while(as.nextPermutation && !ans);

    writeln(ans ? "YES" : "NO");
