    auto can_pair = new bool[][](H, H);

    foreach (i; 0..H) {
        foreach (j; 0..H) {
            auto cnt1 = new int[](26);
            auto cnt2 = new int[](26);
            foreach (k; 0..W) {
                cnt1[A[i][k]] += 1;
                cnt2[A[j][k]] += 1;
            }
            if (26.iota.map!(a => cnt1[a] == cnt2[a]).all) {
                can_pair[i][j] = true;
                can_pair[j][i] = true;
            }
        }
    }

    auto used = new bool[](H);
    int[] stack;
    int center = -1;

    bool dfs(int n) {
        if (n >= H) {
            auto B = new int[][](H, W);
            foreach (i; 0..H/2) {
                B[i] = A[stack[i*2]].dup;
                B[H-i-1] = A[stack[i*2+1]].dup;
            }
            if (center != -1) {
                B[H/2] = A[center].dup;
            }

            auto col_used = new bool[](W);
            bool center = false;

            foreach (j; 0..W) {
                if (col_used[j]) continue;
