void main() {
    long H, W;
    scanln(H, W);
    char[][] xss = H.rep!(() => readln.chomp.to!(char[]));

    bool isOK(long[] as) {
        long cnt = 0;
        foreach(a; as) {
            if (H%2!=0 && a==H.floor(2)) continue;
            if (a == cnt) cnt++;
            if (a > cnt) return false;
        }
        long[][] yss = new long[][H.ceil(2)];
        foreach(i, a; as) {
            yss[a] ~= i;
        }
        bool[] es = new bool[W];
        cnt = 0;
        return W.ceil(2).iota.all!((_) {
            long i = W.iota.countUntil!(i => !es[i]);
            assert(i >= 0);
            es[i] = true;
            long j = W.iota.countUntil!(
                j => !es[j] && yss.all!(
                    ys => xss[ys.front][i] == xss[ys.back][j] && xss[ys.back][i] == xss[ys.front][j]
                )
            );
            if (j<0 && W%2!=0 && cnt==0) {
                cnt++;
                return yss.all!(
                    ys => xss[ys.front][i] == xss[ys.back][i]
                );
            } else if (j>=0) {
                return es[j] = true;
            }
            return false;
        });
    }

    bool ans = false;
    long[] as =  H.ceil(2).iota.map!(i => i.repeat(2).array).join.take(H).array;
    do {
        ans |= isOK(as);
    } while(as.nextPermutation);

    writeln(ans ? "YES" : "NO");
}

