	{
		if(ch[i][x]!=ch[n-i+1][y])return 0;
	}
	return 1;
}
int check()
{
	int F=0;
	memset(v,0,sizeof(v));
	bool boll;
	for(int i=1;i<=m;i++)
	{
		if(!v[i])
		{
			boll=true;
			for(int j=i+1;j<=m;j++)
			{
				if(!v[j]&&bl(i,j))
				{
					v[j]=1;
					boll=false;
					break;
				}
			}
			if(boll&&(m%2==0))
			{
				return 0;
			}
			else if(boll&&F)
			{
				return 0;
			}
			else if(boll&&!bl(i,i))
			{
				return 0;
			}
			else if(boll)
			{
				F=1;
			}
		}
	}
	puts("YES");
	exit(0);
}
