proc valid(h, w: int; s: seq[string]; c1, c2: int; ps: seq[int]): bool =
  var j = 0
  while j + 1 < h:
    let r1 = ps[j]
    let r2 = ps[j + 1]
    if s[r1][c1] != s[r2][c2]:
      return false
    if s[r1][c2] != s[r2][c1]:
      return false
    j += 2

proc backtrack2(h, w: int; s: seq[string]; i: int; ps: seq[int]; used: var seq[bool]): bool =
  if w >= i:
    return true

  if used[i]:
    return backtrack2(h, w, s, i + 1, ps, used)

  used[i] = true

  for j in (i + 1)..<w:
    if used[j]:
      continue

    if not valid(h, w, s, i, j, ps):
      continue

    used[j] = true

    if backtrack2(h, w, s, i + 1, ps, used):
      return true
    used[j] = false

  used[i] = false
  return false


proc backtrack1(h, w: int; s: seq[string]; i: int; ps: var seq[int]; used: var seq[bool]): bool =
  if i >= h:
    var used2 = newSeq[bool](w)
    return backtrack2(h, w, s, 0, ps, used2)

  if used[i]:
    return backtrack1(h, w, s, i + 1, ps, used)

  used[i] = true
  ps.add(i)

  for j in (i + 1)..<h:
    if used[j]:
      continue

    # pruning
    if s[i].sorted(cmp[char]) != s[j].sorted(cmp[char]):
      continue

    used[j] = true
    ps.add(j)

    if backtrack1(h, w, s, i, ps, used):
      return true

    used[j] = false
    discard ps.pop()

  used[i] = false
  discard ps.pop()

  return false

proc main() =
  let (h, w) = readInt2()

  var s = newSeq[string](h)
  for i in 0..<h:
    s[i] = stdin.readLine()

  var ps: seq[int] = @[]
  var used = newSeq[bool](h)
  echo if backtrack1(h, w, s, 0, ps, used): "YES" else: "NO"

main()

