import numpy as np
from collections import Counter

def main():
    H, W = map(int, input().split())
    area = np.array([list(input()) for _ in range(H)])

    hcounts = [Counter(area[i, :]) for i in range(H)]
    vcounts = [Counter(area[:, i]) for i in range(W)]

    h_paired, v_paired = set(), set()
    for i in range(H):
        if i in h_paired:
            continue
        for j in range(i+1, H):
            if j in h_paired:
                continue
            if hcounts[i]==hcounts[j]:
                h_paired |= {i, j}

    for i in range(W):
        if i in v_paired:
            continue
        for j in range(i+1, W):
            if j in v_paired:
                continue
            if vcounts[i]==vcounts[j]:
                v_paired |= {i, j}

    if H-len(h_paired) in (0, 1) and W-len(v_paired) in (0, 1):
        print('YES')
    else:
        print('NO')


