def check(field):
    if len(field) == 1:
        center = field[0]
    else:
        center = None
        prev = None
        for i, row in enumerate(field):
            if prev is None:
                prev = row
                continue
            if prev == row:
                prev = None
                continue
            if center is not None:
                return False
            center = prev
            prev = row

    if center is not None:
        cnt = Counter(center)
        cntcnt = Counter(c % 2 for c in cnt.values())
        if cntcnt[1] > 1:
            return False

    return True


