from collections import defaultdict


def can_palindrome(s):
    l = []
    for c in s:
        if c in l:
            l.remove(c)
        else:
            l.append(c)

    if len(s) % 2 == 0:
        return len(l) == 0
    else:
        return len(l) == 1


def can_pair(s1, s2):
    l = []
    for c1, c2 in zip(s1, s2):
        c = sorted([c1, c2])
        if c in l:
            l.remove(c)
        else:
            l.append(c)

    if len(s1) % 2 == 0:
        return len(l) == 0
    else:
        return len(l) == 1


def pair_graph(s1, s2):
    N = len(s1)
    G = np.zeros([N, N])
    for i in range(N):
        for j in range(i+1, N):
            if s1[i] == s2[j] and s1[j] == s2[i]:
                G[i, j] = 1
                G[j, i] = 1
    return G

