import array

orda = ord('a')
p12 = 2 ** 12

a = None
ta = None
h = None
w = None

row_keys = None
col_keys = None


def calc_row_keys(sel = 0, count = 0, last = -1):
    if count == w // 2:
        arr = array.array('l')
        row_keys[sel] = arr
        for i in range(h):
            ai = a[i]
            ss = []
            for j in range(w):
                if sel & (2 ** j):
                    ss.append(ai[j])
            ss.sort()
            v = 0
            for ch in ss:
                v *= 26
                v += ch
            arr.append(v)
    else:
        for j in range(last + 1, w):
            calc_row_keys(sel | (2 ** j), count + 1, j)


def calc_col_keys(sel = 0, count = 0, last = -1):
    if count == h // 2:
        arr = array.array('l')
        col_keys[sel] = arr
        for j in range(w):
            aj = ta[j]
            ss = []
            for i in range(h):
                if sel & (2 ** i):
                    ss.append(aj[i])
            ss.sort()
            v = 0
            for ch in ss:
                v *= 26
                v += ch
            arr.append(v)
    else:
        for i in range(last + 1, h):
            calc_col_keys(sel | (2 ** i), count + 1, i)


def check_sym1(t):
    c = 0
    for ch in t:
        c ^= 2 ** ch
    odd = 0
    for code in range(26):
        if c & (2 ** code):
            odd += 1
    return odd <= 1


def check_sym(sel_rows, sel_rows2, center_row = None, sel_cols = None, sel_cols2 = None, center_col = None):
    if sel_cols is None:
        t0 = 2 ** w - 1
        if w % 2:
            for j in range(w):
                p2j = 2 ** j
                t = t0 - p2j
                for sel_cols in row_keys.keys():
                    if sel_cols & p2j:
                        continue
                    sel_cols2 = t - sel_cols
                    if sel_cols2 < sel_cols:
                        continue
                    if check_sym(sel_rows, sel_rows2, center_row, sel_cols, sel_cols2, j):
                        return True
            return False
        else:
            for sel_cols in row_keys.keys():
                sel_cols2 = t0 - sel_cols
                if sel_cols2 < sel_cols:
                    continue
                if check_sym(sel_rows, sel_rows2, center_row, sel_cols, sel_cols2):
                    return True
            return False
    else:
        rows = []
        rows2 = []
        keys = row_keys[sel_cols]
        keys2 = row_keys[sel_cols2]
        sc = None
        if center_col is not None:
            sc = ta[center_col]
        for i in range(h):
            p2i = 2 ** i
            k = 0 if sc is None else sc[i]
            if p2i & sel_rows:
                k += (keys[i] * p12 + keys2[i]) * 32
                rows.append((k, i))
            elif p2i & sel_rows2:
                k += (keys2[i] * p12 + keys[i]) * 32
                rows2.append((k, i))
        rows.sort()
        rows2.sort()
        for i in range(len(rows)):
            if rows[i][0] != rows2[i][0]:
                return False
        if center_col is not None:
            sc = ta[center_col]
            for i in range(len(rows)):
                if sc[rows[i][1]] != sc[rows2[i][1]]:
                    return False
        cols = []
        cols2 = []
        keys = col_keys[sel_rows]
        keys2 = col_keys[sel_rows2]
        sc = None
        if center_row is not None:
            sc = a[center_row]
        for j in range(w):
            p2j = 2 ** j
            k = 0 if sc is None else sc[j]
            if p2j & sel_cols:
                k += (keys[j] * p12 + keys2[j]) * 32
                cols.append((k, j))
            elif p2j & sel_cols2:
                k += (keys2[j] * p12 + keys[j]) * 32
                cols2.append((k, j))
        cols.sort()
        cols2.sort()
        for j in range(len(cols)):
            if cols[j][0] != cols2[j][0]:
                return False
        if center_row is not None:
            sc = a[center_row]
            for j in range(len(cols)):
                if sc[cols[j][1]] != sc[cols2[j][1]]:
                    return False
        for i in range(len(rows)):
            ai = a[rows[i][1]]
            ai2 = a[rows2[i][1]]
            for j in range(len(cols)):
                if ai[cols[j][1]] != ai2[cols2[j][1]]:
                    return False
                if ai[cols2[j][1]] != ai2[cols[j][1]]:
                    return False

    return True


def solve():
    global row_keys, col_keys
    global ta

    if h == 1 or w == 1:
        if h == 1:
            a0 = a[0]
        else:
            a0 = ''.join(s)
        return check_sym1(a0)

    ta = [array.array('b') for _ in range(w)]
    for i in range(h):
