#!/usr/bin/env python3

orda = ord('a')
p12 = 2 ** 12

s = None
ts = None
h = None
w = None

row_keys = None
col_keys = None


def calc_row_keys(sel = 0, count = 0, last = -1):
    if count == w // 2:
        arr = []
        row_keys[sel] = arr
        for i in range(h):
            si = s[i]
            ss = []
            for j in range(w):
                if sel & (2 ** j):
                    ss.append(si[j])
            ss.sort()
            v = 0
            for ch in ss:
                v *= 26
                v += ord(ch) - orda
            arr.append(v)
    else:
        for j in range(last + 1, w):
            calc_row_keys(sel | (2 ** j), count + 1, j)


def calc_col_keys(sel = 0, count = 0, last = -1):
    if count == h // 2:
        arr = []
        col_keys[sel] = arr
        for j in range(w):
            sj = ts[j]
            ss = []
            for i in range(h):
                if sel & (2 ** i):
                    ss.append(sj[i])
            ss.sort()
            v = 0
            for ch in ss:
                v *= 26
                v += ord(ch) - orda
            arr.append(v)
    else:
        for i in range(last + 1, h):
            calc_col_keys(sel | (2 ** i), count + 1, i)


def check_sym1(t):
    c = 0
    for ch in t:
        c ^= 2 ** (ord(ch) - orda)
    odd = 0
    for code in range(26):
        if c & (2 ** code):
            odd += 1
    return odd <= 1


def check_sym(sel_rows, sel_rows2, center_row = None, sel_cols = None, sel_cols2 = None, center_col = None):
    if sel_cols is None:
        t0 = 2 ** w - 1
        if w % 2:
            for j in range(w):
                p2j = 2 ** j
                t = t0 - p2j
                for sel_cols in row_keys.keys():
                    if sel_cols & p2j:
                        continue
                    sel_cols2 = t - sel_cols
                    if sel_cols2 < sel_cols:
                        continue
                    if check_sym(sel_rows, sel_rows2, center_row, sel_cols, sel_cols2, j):
                        return True
            return False
        else:
            for sel_cols in row_keys.keys():
                sel_cols2 = t0 - sel_cols
                if sel_cols2 < sel_cols:
                    continue
                if check_sym(sel_rows, sel_rows2, center_row, sel_cols, sel_cols2):
                    return True
            return False
    else:
        rows = []
        rows2 = []
        keys = row_keys[sel_cols]
        keys2 = row_keys[sel_cols2]
        for i in range(h):
            p2i = 2 ** i
            if p2i & sel_rows:
                rows.append((keys[i], keys2[i], i))
            elif p2i & sel_rows2:
                rows2.append((keys2[i], keys[i], i))
        rows.sort()
        rows2.sort()
        for i in range(len(rows)):
            if rows[i][0] != rows2[i][0]:
                return False
            if rows[i][1] != rows2[i][1]:
                return False
        if center_col is not None:
            sc = ts[center_col]
            for i in range(len(rows)):
                if sc[rows[i][2]] != sc[rows2[i][2]]:
                    return False
        cols = []
        cols2 = []
        keys = col_keys[sel_rows]
        keys2 = col_keys[sel_rows2]
        for j in range(w):
            p2j = 2 ** j
            if p2j & sel_cols:
                cols.append((keys[j], keys2[j], j))
            elif p2j & sel_cols2:
                cols2.append((keys2[j], keys[j], j))
        cols.sort()
        cols2.sort()
        for j in range(len(cols)):
            if cols[j][0] != cols2[j][0]:
                return False
            if cols[j][1] != cols2[j][1]:
                return False
        if center_row is not None:
            sc = s[center_row]
            for j in range(len(cols)):
                if sc[cols[j][2]] != sc[cols2[j][2]]:
                    return False
        for i in range(len(rows)):
            si = s[rows[i][2]]
            si2 = s[rows2[i][2]]
            for j in range(len(cols)):
                if si[cols[j][2]] != si2[cols2[j][2]]:
                    return False

    return True


def solve():
    global row_keys, col_keys
    global ts

    if h == 1 or w == 1:
        if h == 1:
            s0 = s[0]
        else:
            s0 = ''.join(s)
        return check_sym1(s0)

    ts = ['' for _ in range(w)]
    for i in range(h):
        si = s[i]
        for j in range(w):
            ts[j] += si[j]

    row_keys = {}
    col_keys = {}
    calc_row_keys()
    calc_col_keys()

    t0 = 2 ** h - 1
    if h % 2:
        for i in range(h):
            p2i = 2 ** i
            t = t0 - p2i
            for sel_rows in col_keys.keys():
                if sel_rows & p2i:
                    continue
                sel_rows2 = t - sel_rows
                if sel_rows2 < sel_rows:
                    continue
                if check_sym(sel_rows, sel_rows2, i):
                    return True
    else:
        for sel_rows in col_keys.keys():
            sel_rows2 = t0 - sel_rows
            if sel_rows2 < sel_rows:
                continue
            if check_sym(sel_rows, sel_rows2):
                return True

    return False


def main():
    global s, h, w

    h, w = input().split()
    h = int(h)
    w = int(w)
    s = [input() for _ in range(h)]


    print('YES' if solve() else 'NO')


if __name__ == '__main__':
    main()

