def solve(f):
    h, w = f.read_int_list()
    s = [list(f.read_str()) for i in xrange(h)]

    sh = sorted(["".join(sorted(si)) for si in s])
    sw = sorted(["".join(sorted([s[hi][wi] for hi in xrange(h)])) for wi in xrange(w)])

    odd_h = []
    dh = collections.Counter(sh)
    for k, v in dh.items():
        if v % 2 == 1: odd_h.append(k)

    odd_w = []
    dw = collections.Counter(sw)
    for k, v in dw.items():
        if v % 2 == 1: odd_w.append(k)

    if len(odd_h) > h % 2 or len(odd_w) > w % 2: return "NO"

    if len(odd_h) == 1 and len(odd_w) == 1:
        if odd_h[(w+1)/2] != odd_w[(h+1)/2]:
            return "NO"
    if len(odd_h) == 1:
        if odd_h[0][:w/2] != odd_h[0][(w+1)/2:]:
            return "NO"
    if len(odd_w) == 1:
        if odd_w[0][:h/2] != odd_w[0][(h+1)/2:]:
            return "NO"

    return "YES"


class Reader(object):
    def __init__(self, filename=None):
        self.file = open(filename) if filename is not None else None
        self.case = 1

    def __readline(self):
        return self.file.next().strip() if self.file else raw_input()

    def next_case(self):
        self.file.next()
        self.case += 1

    def read_int(self): return int(self.__readline())
    def read_float(self): return float(self.__readline())
    def read_long(self): return long(self.__readline())
    def read_decimal(self): return decimal.Decimal(self.__readline())
    def read_str(self): return self.__readline()

    def read_int_list(self): return map(int, self.__readline().split())
    def read_float_list(self): return map(float, self.__readline().split())
    def read_long_list(self): return map(long, self.__readline().split())
    def read_decimal_list(self): return map(decimal.Decimal, self.__readline().split())
    def read_str_list(self): return self.__readline().split()

if __name__ == '__main__':
    filename = sys.argv[1] if len(sys.argv) > 1 else None
    f = Reader(filename)
    if f.file:
        while True:
            print "Case #%d\n"%f.case, solve(f)
            try:
                f.next_case()
            except StopIteration:
                break
    else:
        print solve(f)

