def solve(f):
    h, w = f.read_int_list()
    s = [list(f.read_str()) for i in xrange(h)]
    s2 = [[s[hi][wi] for hi in xrange(h)] for wi in xrange(w)]

    sh = ["".join(sorted(si)) for si in s]
    sw = ["".join(sorted([s[hi][wi] for hi in xrange(h)])) for wi in xrange(w)]
    odd_h = []
    dh = collections.Counter(sh)
    for k, v in dh.items():
        if v % 2 == 1: odd_h.append(sh.index(k))

    odd_w = []
    dw = collections.Counter(sw)
    for k, v in dw.items():
        if v % 2 == 1: odd_w.append(sw.index(k))


    if len(odd_h) != h % 2 or len(odd_w) != w % 2: return "NO"

    def checkh(oh):
        d = collections.defaultdict(list)
        res = None
        for i, si in enumerate(s[oh]):
            d[si].append(i)
        for k, v in d.items():
            if len(v) % 2 == 0:
                dd = collections.Counter(["".join(sorted(s2[vi])) for vi in v])
                od = 0
                for vv in dd.values():
                    if vv % 2 == 1: od += 1
                if od > 1: return False
            else:
                res = k
        return res

    def checkw(ow):
        d = collections.defaultdict(list)
        res = None
        for i, si in enumerate(s2[ow]):
            d[si].append(i)
        for k, v in d.items():
            if len(v) % 2 == 0:
                dd = collections.Counter(["".join(sorted(s[vi])) for vi in v])
                od = 0
                for vv in dd.values():
                    if vv % 2 == 1: od += 1
                if od > 1: return False
            else:
                res = k
        return res

    resh = resw = None
    if len(odd_h) == 1:
        resh = checkh(odd_h[0])
        if resh == False: return "NO"
    if len(odd_w) == 1:
        resw = checkw(odd_w[0])
        if resw == False: return "NO"
    if resh is not None and resw is not None and resh != resw: return "NO"

    return "YES"


class Reader(object):
    def __init__(self, filename=None):
        self.file = open(filename) if filename is not None else None
        self.case = 1

    def __readline(self):
        return self.file.next().strip() if self.file else raw_input()

    def next_case(self):
        self.file.next()
        self.case += 1

    def read_int(self): return int(self.__readline())
    def read_float(self): return float(self.__readline())
    def read_long(self): return long(self.__readline())
    def read_decimal(self): return decimal.Decimal(self.__readline())
    def read_str(self): return self.__readline()

    def read_int_list(self): return map(int, self.__readline().split())
    def read_float_list(self): return map(float, self.__readline().split())
    def read_long_list(self): return map(long, self.__readline().split())
    def read_decimal_list(self): return map(decimal.Decimal, self.__readline().split())
    def read_str_list(self): return self.__readline().split()

if __name__ == '__main__':
    filename = sys.argv[1] if len(sys.argv) > 1 else None
    f = Reader(filename)
    if f.file:
        while True:
            print "Case #%d\n"%f.case, solve(f)
            try:
                f.next_case()
            except StopIteration:
                break
    else:
        print solve(f)

