def apply_switch(S_arr, row_matching, col_matching):
    S_arr_row = S_arr.copy()
    i = 0
    for mat in row_matching:
        if len(mat) == 2:
            S_arr_row[i, :] = S_arr[mat[0], :]
            S_arr_row[H-1-i, :] = S_arr[mat[1], :]
            i += 1
        else:
            S_arr_row[(H-1)//2, :] = S_arr[mat[0], :]
    S_arr_rowcol = S_arr_row.copy()
    j = 0
    for mat in row_matching:
        if len(mat) == 2:
            S_arr_rowcol[:, j] = S_arr_row[:, mat[0]]
            S_arr_rowcol[:, W-1-j] = S_arr_row[:, mat[1]]
            j += 1
        else:
            S_arr_rowcol[:, (W-1)//2] = S_arr_row[:, mat[0]]

