fn search2(
    hist_y: &[usize],
    h:usize,
    w:usize, 
    map: &Vec<Vec<char>>, 
    used: usize
) -> bool {
    let mut used = used;
    for tar in 0..w {
        if used&(1 << tar) > 0 {
            continue;
        }
        used |= 1 << tar;
        let mut found = false;
        for tar2 in tar+1..w {
            if used&(1 << tar2) > 0 {
                continue;
            }
            let mut flag = true;
            for i in 0..h {
                let y1 = hist_y[i];
                let y2 = hist_y[h -1 - i];
                if map[y1][tar]!=map[y2][tar2] {
                    flag = false;
                    break;
                }
            }
            if flag {
                used |= 1 << tar2;
                found = true;
                break;                
            }
        }
        if !found {
            return false;
        }
    }
    return true;
}

fn search1(
    current: usize,
    hist_y: &mut [usize],
    h: usize,
    w: usize,
    map: &Vec<Vec<char>>,
    used: usize
) -> bool {
    if current >= h/2 {
        if h%2 > 0 {
            for tar in 0..h {
                if used&(1 << tar) == 0 {
                    hist_y[h/2] = tar;
                    break;
                }
            }
        }
        if w%2 > 0 {
            for tar in 0..w {
                let mut flag = true;
                for i in 0..h/2 {
                    let y1 = hist_y[i];
                    let y2 = hist_y[h - 1 - i];
                    if map[y1][tar] != map[y2][tar] {
                        flag = false;
                        break;
                    }
                }
                if flag && search2(hist_y, h ,w, map, 1 << tar) {
                    return true;
                }
            }
            return false;
        }
        return search2(hist_y, h ,w, &map, 0)
    }

    for tar in 0..h {
        if used&(1 << tar) > 0 {
            continue;
        }
        for tar2 in tar+1..h {
            if used&(1 << tar2) == 0 {
                hist_y[current] = tar;
                hist_y[h -1 - current] = tar2;
                let nused = used | (1 << tar) | (1 << tar2);
                if search1(current + 1, hist_y, h, w, &map, nused) {
                    return true;
                }
            }
        }
    }
    return false;
}


