fn compare_sets(ss: &Vec<String>) -> bool {
    let mut list: Vec<usize> = Vec::new();

    for (i1, s1) in ss.iter().enumerate() {
        if list.contains(&i1) {
            continue;
        }
        for (i2, s2) in ss.iter().enumerate() {
            if i1 == i2 {
                continue;
            } else if list.contains(&i2) {
                continue;
            } else if set_compare_eq(s1, s2) {
                list.push(i1);
                list.push(i2);
                break;
            }
        }
    }
    ss.len() - list.len() == 0 || ss.len() - list.len() == 1
}

fn set_compare_eq(s1: &String, s2: &String) -> bool {
    for c in s1.chars() {
        if !s2.contains(c) {
            return false;
        }
    }
    for c in s2.chars() {
        if !s1.contains(c) {
            return false;
        }
    }
    true
}

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().split_whitespace()
        .map(|e| e.parse().ok().unwrap()).collect()
}

fn read_lines<T: std::str::FromStr>(n: u32) -> Vec<T> {
    (0..n).map(|_| read()).collect()
}

fn read_vec2<T: std::str::FromStr>(n: u32) -> Vec<Vec<T>> {
    (0..n).map(|_| read_vec()).collect()
}

