fn check_palindrome(s: &Vec<char>) -> bool {
    let mut s = s.clone();
    s.sort();
    let mut count = vec![0; 26];
    for &c in &s {
        count[c as usize - 'a' as usize] += 1;
    }

    if s.len() % 2 == 1 {
        let mut used = false;
        for &c in &count {
            if c % 2 == 1 {
                if used {
                    return false;
                } else {
                    used = true;
                }
            }
        }
    } else {
        for &c in &count {
            if c % 2 == 1 {
                return false;
            }
        }
    }

    return false;
}

