fn rec(s: &Vec<Vec<char>>, used: &mut Vec<bool>, rows: &mut Vec<usize>) -> bool {
    if rows.len() == s.len() {
        let h = s.len();
        let w = s[0].len();
        let mut t = vec![vec![' '; w]; h];
        for i in 0..h {
            for j in 0..w {
                t[i][j] = s[rows[i]][j];
            }
        }
        let mut used = vec![false; w];
        for i in 0..w {
            if used[i] { continue; }
            for j in (i + 1)..w {
                if used[j] { continue; }

                let mut ok = true;
                for k in 0..h {
                    if t[k][i] != t[h - 1 - k][j] {
                        ok = false;
                        break;
                    }
                }

                if ok {
                    used[i] = true;
                    used[j] = true;
                }
            }
        }

        let mut count = 0;
        for i in 0..w {
            if !used[i] {
                count += 1;
                if w % 2 == 1 {
                    let mut s = vec![' '; h];
                    for j in 0..h {
                        s[j] = t[j][i];
                    }
                    if !check_palindrome(&s) {
                        return false;
                    }
                }
            }
            if w % 2 == 1 && count > 1 { return false; }
            if w % 2 == 0 && count > 0 { return false; }
        }
        return true;
    }
    let h = s.len();
    for i in 0..h {
        if used[i] { continue; }
        rows.push(i);
        used[i] = true;

        let check = if rows.len() > (h + 1) / 2 {
            let w = s[0].len();
            let mut up = Vec::new();
            let mut down = Vec::new();
            for col in 0..w {
                let mut u = Vec::new();
                let mut d = Vec::new();
                if h % 2 == 0 {
                    let center = h / 2;
                    for i in 0..h {
                        if center + i >= rows.len() { break; }
                        u.push(s[rows[center - 1 - i]][col]);
                        d.push(s[rows[center + i]][col]);
                    }
                } else {
                    let center = h / 2;
                    for i in 1..h {
                        if center + i >= rows.len() { break; }
                        u.push(s[rows[center - i]][col]);
                        d.push(s[rows[center + i]][col]);
                    }
                }
                up.push(u);
                down.push(d);
            }
            up.sort();
            down.sort();

            let mut ok = true;
            for col in 0..w {
                if up[col] != down[col] {
                    ok = false;
                    break;
                }
            }

            ok
        } else { true };

        if check { if rec(s, used, rows) { return true; } }
        used[i] = false;
        rows.pop();
    }
    return false;
}

struct Scanner {
    ptr: usize,
    length: usize,
    buf: Vec<u8>,
    small_cache: Vec<u8>,
}

impl Scanner {
    fn new() -> Scanner {
        Scanner { ptr: 0, length: 0, buf: vec![0; 1024], small_cache: vec![0; 1024] }
    }

    fn load(&mut self) {
        use std::io::Read;
        let mut s = std::io::stdin();
        self.length = s.read(&mut self.buf).unwrap();
    }

    fn byte(&mut self) -> u8 {
        if self.ptr >= self.length {
            self.ptr = 0;
            self.load();
            if self.length == 0 {
                self.buf[0] = b'\n';
                self.length = 1;
            }
        }

        self.ptr += 1;
        return self.buf[self.ptr - 1];
    }

    fn is_space(b: u8) -> bool { b == b'\n' || b == b'\r' || b == b'\t' || b == b' ' }

    fn read<T>(&mut self) -> T where T: std::str::FromStr, T::Err: std::fmt::Debug, {
        let mut b = self.byte();
        while Scanner::is_space(b) {
            b = self.byte();
        }

        for pos in 0..self.small_cache.len() {
            self.small_cache[pos] = b;
            b = self.byte();
            if Scanner::is_space(b) {
                return String::from_utf8_lossy(&self.small_cache[0..(pos + 1)]).parse().unwrap();
            }
        }

        let mut v = self.small_cache.clone();
        while !Scanner::is_space(b) {
            v.push(b);
            b = self.byte();
        }
        return String::from_utf8_lossy(&v).parse().unwrap();
    }
}

use proconio::input;

fn generate_even_pairings(n: usize) -> Vec<Vec<(usize, usize)>> {
    assert!(n % 2 == 0);

    fn dfs(ckd: &mut [bool], now: &mut Vec<(usize, usize)>, ans: &mut Vec<Vec<(usize, usize)>>) {
        if 2 * now.len() == ckd.len() {
            ans.push(now.clone());
            return;
        }
        let i = ckd
            .iter()
            .copied()
            .enumerate()
            .filter(|&(_, b)| !b)
            .next()
            .unwrap()
            .0;
        ckd[i] = true;
        for j in 0..ckd.len() {
            if ckd[j] {
                continue;
            }
            ckd[j] = true;
            now.push((i, j));
            dfs(ckd, now, ans);
            now.pop();
            ckd[j] = false;
        }
        ckd[i] = false;
    }

    let mut ckd = vec![false; n];
    let mut now = vec![];
    let mut ans = vec![];

    dfs(&mut ckd, &mut now, &mut ans);

    ans
}

fn convert_to_permutation(pairs: Vec<(usize, usize)>) -> Vec<usize> {
    let n = pairs.len() * 2;
    let mut seq = vec![0; n];
    for (i, (x, y)) in pairs.into_iter().enumerate() {
        seq[i] = x;
        seq[n - 1 - i] = y;
    }
    seq
}

fn generate_representitve_parmutations(n: usize) -> Vec<Vec<usize>> {
    if n % 2 == 0 {
        generate_even_pairings(n)
            .into_iter()
            .map(convert_to_permutation)
            .collect()
    } else {
        (0..n)
            .map(|center| {
                generate_even_pairings(n - 1)
                    .into_iter()
                    .map(convert_to_permutation)
                    .map(move |mut seq| {
                        for x in &mut seq {
                            if center <= *x {
                                *x += 1;
                            }
                        }
                        seq.insert(n / 2, center);
                        seq
                    })
            })
            .flatten()
            .collect()
    }
}

fn main() {
    input!(h: usize, w: usize, v: [proconio::marker::Chars; h]);
    println!(
        "{}",
        if generate_representitve_parmutations(w).iter().any(|seq| {
            // eprintln!("{:?}", seq);
            let mut v: Vec<Vec<char>> = v
                .iter()
                .map(|s| {
                    let mut ret = vec!['$'; w];
                    for (i, &x) in seq.iter().enumerate() {
                        ret[i] = s[x];
                    }
                    ret
                })
                .collect();
            // eprintln!("v = {:?}", &v);

            while !v.is_empty() {
                let s = &v[0];
                let t: &Vec<_> = &s.iter().copied().rev().collect();
                // eprintln!("s = {:?} t = {:?}", s, t);
                if let Some(i) = v
                    .iter()
                    .enumerate()
                    .find(|&(i, u)| 0 != i && t == u)
                    .map(|p| p.0)
                {
                    v.remove(i);
                    v.remove(0);
                } else {
                    return v.len() == 1
                        && v[0] == v[0].iter().copied().rev().collect::<Vec<char>>();
                }
            }
            true
        }) {
            "YES"
        } else {
            "NO"
        }
    );
}

