                        {
                            assert!(i < j);
                            Some((i, j))
                        } else {
                            None
                        }
                    })
                    .filter_map(std::convert::identity)
                    .next()
                {
                    v.remove(j);
                    v.remove(i);
                } else {
                    return false;
                }
            }
        }) {
            "YES"
        } else {
            "NO"
        }
    );
}

