fn rec(used: &mut Vec<bool>,
       rows: &mut Vec<usize>,
       skip: &mut Vec<Vec<bool>>,
       s: &Vec<Vec<char>>) -> bool {
    let h = s.len();
    let w = s[0].len();

    if rows.len() == h {
        let mut t = vec![vec![' '; w]; h];
        for i in 0..h {
            for j in 0..w {
                t[i][j] = s[rows[i]][j];
            }
        }

        let mut u = vec![vec![' '; w]; h];
        let mut pos = 0;
        let mut used = vec![false; w];
        for i in 0..w {
            if used[i] { continue; }
            for j in (i + 1)..w {
                if used[i] { continue; }

                let mut ok = true;
                for k in 0..h {
                    if t[k][i] != t[h - 1 - k][j] {
                        ok = false;
                        break;
                    }
                }

                if ok {
                    for k in 0..h {
                        u[k][pos] = t[k][i];
                        u[k][w - 1 - pos] = t[k][j];
                    }
                    pos += 1;
                    used[i] = true;
                    used[j] = true;
                    break;
                }
            }
            if !used[i] {
                if w % 2 == 0 { return false; }
                if u[0][w / 2] != ' ' { return false; }
                for k in 0..h {
                    u[k][w / 2] = t[k][i];
                    if t[k][i] != t[h - 1 - k][i] { return false; }
                }
            }
        }

        return true;
    }

    let turn = rows.len();
    for i in 0..h {
        if used[i] || skip[turn][i] { continue; }
        used[i] = true;
        skip[h - 1 - turn][i] = true;
        rows.push(i);
        if rec(used, rows, skip, s) { return true; };
        rows.pop();
        used[i] = false;
    }
    for i in 0..h {
        skip[h - 1 - turn][i] = false;
    }

    return false;
}

struct Scanner {
    ptr: usize,
    length: usize,
    buf: Vec<u8>,
    small_cache: Vec<u8>,
}

impl Scanner {
    fn new() -> Scanner {
        Scanner { ptr: 0, length: 0, buf: vec![0; 1024], small_cache: vec![0; 1024] }
    }

    fn load(&mut self) {
        use std::io::Read;
        let mut s = std::io::stdin();
        self.length = s.read(&mut self.buf).unwrap();
    }

    fn byte(&mut self) -> u8 {
        if self.ptr >= self.length {
            self.ptr = 0;
            self.load();
            if self.length == 0 {
                self.buf[0] = b'\n';
                self.length = 1;
            }
        }

        self.ptr += 1;
        return self.buf[self.ptr - 1];
    }

    fn is_space(b: u8) -> bool { b == b'\n' || b == b'\r' || b == b'\t' || b == b' ' }

    fn read<T>(&mut self) -> T where T: std::str::FromStr, T::Err: std::fmt::Debug, {
        let mut b = self.byte();
        while Scanner::is_space(b) {
            b = self.byte();
        }

        for pos in 0..self.small_cache.len() {
            self.small_cache[pos] = b;
            b = self.byte();
            if Scanner::is_space(b) {
                return String::from_utf8_lossy(&self.small_cache[0..(pos + 1)]).parse().unwrap();
            }
        }

        let mut v = self.small_cache.clone();
        while !Scanner::is_space(b) {
            v.push(b);
            b = self.byte();
        }
        return String::from_utf8_lossy(&v).parse().unwrap();
    }
}

