fn detect(s: &Vec<Vec<char>>) -> bool {
    let h = s.len();
    let w = s[0].len();
    let mut used = vec![false; w];
    let mut center = w % 2 == 0;
    for i in 0..w {
        if used[i] {
            continue;
        }
        for j in (i + 1)..w {
            if used[j] {
                continue;
            }
            let mut ok = true;
            for k in 0..h {
                if s[k][i] != s[h - 1 - k][j] {
                    ok = false;
                }
            }
            if ok {
                used[i] = true;
                used[j] = true;
                break;
            }
        }
        if !used[i] {
            if center {
                return false;
            }
            for k in 0..h {
                if s[k][i] != s[h - 1 - k][i] {
                    return false;
                }
            }
            center = true;
            used[i] = true;
        }
        if !used[i] {
            return false;
        }
    }
    true
}

fn can(s: &mut Vec<Vec<char>>, k: usize, used: bool) -> bool {
    let h = s.len();
    if 2 * k + 2 >= h {
        return detect(s);
    }
    for i in (k + 1)..(h - k) {
        if used && 2 * i + 1 == h {
            continue;
        }
        s.swap(i, h - 1 - k);
        if can(s, k + 1, used) {
            return true;
        }
        s.swap(i, h - 1 - k);
    }
    if !used {
        s.swap(k, h / 2);
        if can(s, k, true) {
            return true;
        }
        s.swap(k, h / 2);
    }
    false
}

fn run() {
    input! {
        h: usize,
        _w: usize,
        s: [chars; h],
    }
    let mut s = s;
    if can(&mut s, 0, h % 2 == 0) {
        println!("YES");
    } else {
        println!("NO");
    }
}

fn main() {
    run();
}

use std::collections::HashMap;
use std::io;
use std::io::{BufRead, Write};

fn count(val: &[u8]) -> [usize; 26] {
    let mut ret = [0usize; 26];
    for &i in val {
        assert!(i >= b'a' && i <= b'z');
        ret[(i - b'a') as usize] += 1;
    }
    ret
}

fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut buf = String::new();
    input.read_line(&mut buf).unwrap();
    let (h, w): (usize, usize) = {
        let mut split = buf.split_whitespace();
        (
            split.next().unwrap().parse().unwrap(),
            split.next().unwrap().parse().unwrap(),
        )
    };
    let grid: Vec<_> = (0..h)
        .map(|_| {
            buf.clear();
            input.read_line(&mut buf).unwrap();
            buf.trim_right().as_bytes().to_owned()
        })
        .collect();
    let inverse: Vec<Vec<u8>> = (0..w)
        .map(|y| (0..h).map(|x| grid[x][y]).collect())
        .collect();
    let mut horizontal = HashMap::new();
    for i in &grid {
        let count = horizontal.entry(count(i)).or_insert(0usize);
        *count += 1;
    }
    let mut vertical = HashMap::new();
    for i in &inverse {
        let count = vertical.entry(count(i)).or_insert(0usize);
        *count += 1;
    }
    let horizontal = horizontal.values().filter(|&i| i % 2 == 1).count() <= 1;
    let vertical = vertical.values().filter(|&i| i % 2 == 1).count() <= 1;
    writeln!(
        output,
        "{}",
        if horizontal && vertical { "YES" } else { "NO" }
    ).unwrap();
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    solve(stdin.lock(), stdout.lock());
}

