fn detect(s: &Vec<Vec<char>>) -> bool {
    let h = s.len();
    let w = s[0].len();
    let mut used = vec![false; w];
    let mut centor = false;
    let mut i = 0;
    while i < w {
        if used[i] {
            i += 1;
            continue;
        }
        let mut j = i + 1;
        while j < w {
            if used[j] {
                j += 1;
                continue;
            }
            let mut ok = true;
            for k in 0..h {
                if s[k][i] != s[h - 1 - k][j] {
                    ok = false;
                }
            }
            if ok {
                used[i] = true;
                used[j] = true;
                break;
            }
            j += 1;
        }
        if !used[i] {
            if centor {
                return false;
            }
            for k in 0..h {
                if s[k][i] != s[h - 1 - k][i] {
                    return false;
                }
            }
            centor = true;
            used[i] = true;
        }
    }
    used.iter().all(|p| *p)
}

fn calc(s: &mut Vec<Vec<char>>, k: usize, used: bool) -> bool {
    let h = s.len();
    if k >= h / 2 {
        return detect(&s);
    }
    for i in (k + 1)..(h - k) {
        if h % 2 == 1 && used && i == h / 2 {
            continue;
        }
        s.swap(h - 1 - k, i);
        if calc(s, k + 1, used) {
            return true;
        }
        s.swap(h - 1 - k, i);
    }
    let w = s[k].len();
    for i in 0..w {
        if s[k][i] != s[k][w - 1 - i] {
            return false;
        }
    }
    if !used && h % 2 == 1 {
        s.swap(h / 2, k);
        if calc(s, k + 1, true) {
            return true;
        }
        s.swap(h / 2, k);
    }
    false
}

fn run() {
    input! {
        h: usize,
        _w: usize,
        s: [chars; h],
    }
    let mut s = s;
    if calc(&mut s, 0, false) {
        println!("YES");
    } else {
        println!("NO");
    }
}

fn main() {
    run();
}

use proconio::input;

fn generate_even_pairings(n: usize) -> Vec<Vec<(usize, usize)>> {
    assert!(n % 2 == 0);

    fn dfs(ckd: &mut [bool], now: &mut Vec<(usize, usize)>, ans: &mut Vec<Vec<(usize, usize)>>) {
        if 2 * now.len() == ckd.len() {
            ans.push(now.clone());
            return;
        }
        let i = ckd
            .iter()
            .copied()
            .enumerate()
            .filter(|&(_, b)| !b)
            .next()
            .unwrap()
            .0;
        ckd[i] = true;
        for j in 0..ckd.len() {
            if ckd[j] {
                continue;
            }
            ckd[j] = true;
            now.push((i, j));
            dfs(ckd, now, ans);
            now.pop();
            ckd[j] = false;
        }
        ckd[i] = false;
    }

    let mut ckd = vec![false; n];
    let mut now = vec![];
    let mut ans = vec![];

    dfs(&mut ckd, &mut now, &mut ans);

    ans
}

fn convert_to_permutation(pairs: Vec<(usize, usize)>) -> Vec<usize> {
    let n = pairs.len() * 2;
    let mut seq = vec![0; n];
    for (i, (x, y)) in pairs.into_iter().enumerate() {
        seq[i] = x;
        seq[n - 1 - i] = y;
    }
    seq
}

fn generate_representitve_parmutations(n: usize) -> Vec<Vec<usize>> {
    if n % 2 == 0 {
        generate_even_pairings(n)
            .into_iter()
            .map(convert_to_permutation)
            .collect()
    } else {
        (0..n)
            .map(|center| {
                generate_even_pairings(n - 1)
                    .into_iter()
                    .map(convert_to_permutation)
                    .map(move |mut seq| {
                        for x in &mut seq {
                            if center <= *x {
                                *x += 1;
                            }
                        }
                        seq.insert(n / 2, center);
                        seq
                    })
            })
            .flatten()
            .collect()
    }
}

fn main() {
    input!(h: usize, w: usize, v: [proconio::marker::Chars; h]);
    println!(
        "{}",
        if generate_representitve_parmutations(w).iter().any(|seq| {
            // eprintln!("{:?}", seq);
            let mut v: Vec<Vec<char>> = v
                .iter()
                .map(|s| {
                    let mut ret = vec!['$'; w];
                    for (i, &x) in seq.iter().enumerate() {
                        ret[i] = s[x];
                    }
                    ret
                })
                .collect();
            // eprintln!("v = {:?}", &v);

            while !v.is_empty() {
                if v.len() == 1 {
                    return v.len() == 1
                        && v[0] == v[0].iter().copied().rev().collect::<Vec<char>>();
                }
                for i in 0..v.len() {
                    let s = &v[i];
                    let t: &Vec<_> = &s.iter().copied().rev().collect();
                    // eprintln!("s = {:?} t = {:?}", s, t);
                    if let Some(j) = v
                        .iter()
                        .enumerate()
                        .find(|&(j, u)| i != j && t == u)
                        .map(|p| p.0)
                    {
                        assert_ne!(0, j);
                        v.remove(j);
                        v.remove(0);
                        break;
                    } else {
                        return false;
                    }
                }
            }
            true
        }) {
            "YES"
        } else {
            "NO"
        }
    );
}

