    let h: usize = sc.read();
    let w: usize = sc.read();
    let s: Vec<Vec<char>> = (0..h).map(|_| sc.read::<String>().chars().collect()).collect();

    let mut used = vec![false; h];
    let mut rows = Vec::new();
    let mut skip = vec![vec![false; h]; h];
    if rec(&mut used, &mut rows, &mut skip, &s) {
        println!("YES");
    } else {
