            }
            ckd[j] = true;
            now.push((i, j));
            dfs(ckd, now, ans);
            now.pop();
            ckd[j] = false;
        }
        ckd[i] = false;
    }

    let mut ckd = vec![false; n];
    let mut now = vec![];
    let mut ans = vec![];

