type Pairs = Vec<(usize,usize)>;

fn make_pairs(n: usize, left: usize, taken: usize, pairs: Pairs) -> Vec<Pairs> {
    if left <= 1 {
        return vec![pairs];
    }

    let mut w = vec![];
    for i in 0..n {
        if (taken>>i)&1 == 1 {
            continue;
        }
        for j in i+1..n {
            if (taken>>j)&1 == 0 {
                let mut tp = pairs.clone();
                tp.push((i, j));
                let tt = taken|(1<<i)|(1<<j);
                w.append(&mut make_pairs(n, left-2, tt, tp));
            }
        }
        break;
    }
    w
}


fn make_table(s: &Vec<Vec<char>>, pairs: Pairs) -> Vec<Vec<char>> {
    let n = s.len();
    let m = s[0].len();

    let pn = pairs.len();
    let mut col_perm = vec![0; m];
    let mut total = 0;
    for i in 0..pn {
        let (l, r) = pairs[i];
        col_perm[i] = l;
        col_perm[m-1-i] = r;
        total += l+r;
    }
    if m % 2 == 1 {
        col_perm[m/2] = m*(m-1)/2-total;
    }

    let mut ret = dvec!(' '; n, m);
    for i in 0..n {
        for j in 0..m {
            ret[i][j] = s[i][col_perm[j]];
        }
    }
    ret
}

fn is_reverse(a: &Vec<char>, b: &Vec<char>) -> bool {
    let m = a.len();
    for j in 0..m {
        if a[j] != b[m-1-j] {
            return false;
        }
    }
    true
}

fn is_ok(table: Vec<Vec<char>>) -> bool {
    // debug!(table);

    let n = table.len();
    let m = table[0].len();
    let mut used = vec![false; n];

    let mut no_counterpart = 0;
    for i in 0..n {
        if used[i] {
            continue;
        }
        let mut found = n;
        for ti in i+1..n {
            if is_reverse(&table[i], &table[ti]) {
                found = ti;
                break;
            }
        }
        if found == n {
            if is_reverse(&table[i], &table[i]) {
                no_counterpart += 1;
            } else {
                no_counterpart += 10000;
            }
        } else {
            used[i] = true;
            used[found] = true;
        }
    }
    ifv!(n % 2 == 1, no_counterpart == 1, no_counterpart == 0)
}

