fn detect(s: &Vec<Vec<char>>) -> bool {
    let h = s.len();
    let w = s[0].len();
    let mut used = vec![false; w];
    let mut center = w % 2 == 0;
    for i in 0..w {
        if used[i] {
            continue;
        }
        for j in (i + 1)..w {
            if used[j] {
                continue;
            }
            let mut ok = true;
            for k in 0..h {
                if s[k][i] != s[h - 1 - k][j] {
                    ok = false;
                }
            }
            if ok {
                used[i] = true;
                used[j] = true;
                break;
            }
        }
        if !used[i] {
            if center {
                return false;
            }
            for k in 0..h {
                if s[k][i] != s[h - 1 - k][i] {
                    return false;
                }
            }
            center = true;
            used[i] = true;
        }
        if !used[i] {
            return false;
        }
    }
    true
}

fn can(s: &mut Vec<Vec<char>>, k: usize, used: bool) -> bool {
    let h = s.len();
    if 2 * k + 2 >= h {
        return detect(s);
    }
    for i in (k + 1)..(h - k) {
        if used && 2 * i + 1 == h {
            continue;
        }
        s.swap(i, h - 1 - k);
        if can(s, k + 1, used) {
            return true;
        }
        s.swap(i, h - 1 - k);
    }
    if !used {
        let mut ok = true;
        let w = s[0].len();
        for i in 0..w {
            if s[k][i] != s[k][w - 1 - i] {
                ok = false;
            }
        }
        if ok {
            s.swap(k, h / 2);
            if can(s, k, true) {
                return true;
            }
            s.swap(k, h / 2);
        }
    }
    false
}

