fn rec(used: &mut Vec<bool>,
       rows: &mut Vec<usize>,
       skip: &mut Vec<Vec<bool>>,
       s: &Vec<Vec<char>>) -> bool {
    let h = s.len();

    if rows.len() == h {
        return check(rows, s);
    }

    let turn = rows.len();
    for i in 0..h {
        if used[i] || skip[turn][i] { continue; }
        used[i] = true;
        skip[h - 1 - turn][i] = true;
        rows.push(i);
        if rec(used, rows, skip, s) { return true; };
        rows.pop();
        used[i] = false;
    }
    for i in 0..h {
        skip[h - 1 - turn][i] = false;
    }

    return false;
}

