fn f(
    l: usize,
    cnt: usize,
    odd: bool,
    h: usize,
    w: usize,
    used: &mut Vec<bool>,
    p: &mut Vec<usize>,
    s: &Vec<Vec<usize>>,
) -> bool {
    if l == w {
        let mut us = vec![false; h];
        let mut hodd = h % 2 != 0;
        for i in 0..h - 1 {
            if !us[i] {
                for j in i + 1..h {
                    if !us[j] {
                        if (0..w).all(|k| s[i][p[k]] == s[j][p[w - k - 1]]) {
                            us[i] = true;
                            us[j] = true;
                            break;
                        }
                    }
                }
                if !us[i] {
                    if hodd {
                        if (0..w).any(|k| s[i][p[k]] != s[i][p[w - k - 1]]) {
                            return false;
                        }
                        hodd = false;
                    } else {
                        return false;
                    }
                }
            }
        }
        return true;
    } else if used[l] {
        return f(l + 1, cnt, odd, h, w, used, p, s);
    } else {
        if odd {
            p[w / 2] = l;
            used[l] = true;
            if f(l + 1, cnt, false, h, w, used, p, s) {
                return true;
            }
            used[l] = false;
        }
        for i in l + 1..w {
            if !used[i] {
                p[cnt] = l;
                p[w - cnt - 1] = i;
                used[l] = true;
                used[i] = true;
                if f(l + 1, cnt + 1, odd, h, w, used, p, s) {
                    return true;
                }
                used[l] = false;
                used[i] = false;
            }
        }
    }
    false
}

use std::collections::HashMap;
use std::io;
use std::io::{BufRead, Write};

fn count(val: &[u8]) -> [usize; 26] {
    let mut ret = [0usize; 26];
    for &i in val {
        assert!(i >= b'a' && i <= b'z');
        ret[(i - b'a') as usize] += 1;
    }
    ret
}

fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut buf = String::new();
    input.read_line(&mut buf).unwrap();
    let (h, w): (usize, usize) = {
        let mut split = buf.split_whitespace();
        (
            split.next().unwrap().parse().unwrap(),
            split.next().unwrap().parse().unwrap(),
        )
    };
    let grid: Vec<_> = (0..h)
        .map(|_| {
            buf.clear();
            input.read_line(&mut buf).unwrap();
            buf.trim_right().as_bytes().to_owned()
        })
        .collect();
    let inverse: Vec<Vec<u8>> = (0..w)
        .map(|y| (0..h).map(|x| grid[x][y]).collect())
        .collect();
    let mut horizontal = HashMap::new();
    for i in &grid {
        let count = horizontal.entry(count(i)).or_insert(0usize);
        *count += 1;
    }
    let mut vertical = HashMap::new();
    for i in &inverse {
        let count = vertical.entry(count(i)).or_insert(0usize);
        *count += 1;
    }
    let horizontal = horizontal.values().filter(|&i| i % 2 == 1).count() == h % 2;
    let vertical = vertical.values().filter(|&i| i % 2 == 1).count() == w % 2;
    writeln!(
        output,
        "{}",
        if horizontal && vertical { "YES" } else { "NO" }
    ).unwrap();
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    solve(stdin.lock(), stdout.lock());
}

