fn shuffle<T>(v: &mut Vec<T>, rnd: &mut Random) {
    for i in (1..v.len()).rev() {
        let j = rnd.next()%i as i32;
        let j = j as usize;
        v.swap(i, j);
    }
}

fn transpose<T>(v: &Vec<Vec<T>>) -> Vec<Vec<T>> 
where
    T: Default + Clone
{
    let n = v.len();
    let m = v[0].len();
    let mut ret = vec![vec![T::default(); n]; m];
    for i in 0..n {
        for j in 0..m {
            ret[j][i] = v[i][j].clone();
        }
    }
    ret
}

