fn check(s: Vec<Vec<u8>>) -> bool {
    let h = s.len();
    let w = s[0].len();

    let mut used = vec![false; h];
    let mut cnt = 0;
    for i in 0..h {
        if used[i] {
            continue;
        }
        for j in i+1..h {
            if used[j] {
                continue;
            }
            let mut a = s[j].clone();
            a.reverse();
            if s[i] == a {
                used[i] = true;
                used[j] = true;
                cnt += 2;
            }
        }
    }
    if h%2 == 0 {
        if cnt != h {
            return false;
        }
    } else {
        if cnt+1 != h {
            return false;
        }
        for i in 0..h {
            if !used[i] {
                let mut t = s[i].clone();
                t.reverse();
                if t != s[i] {
                    return false;
                }
            }
        }
    }

    true
}


