fn rec(used: &mut Vec<bool>,
       rows: &mut Vec<usize>,
       skip: &mut Vec<Vec<bool>>,
       s: &Vec<Vec<char>>) -> bool {
    let h = s.len();
    let w = s[0].len();

    if rows.len() == h {
        let mut t = vec![vec![' '; w]; h];
        for i in 0..h {
            for j in 0..w {
                t[i][j] = s[rows[i]][j];
            }
        }

        let mut u = vec![vec![' '; w]; h];
        let mut pos = 0;
        let mut used = vec![false; w];
        for i in 0..w {
            if used[i] { continue; }
            for j in (i + 1)..w {
                if used[i] { continue; }

                let mut ok = true;
                for k in 0..h {
                    if t[k][i] != t[h - 1 - k][j] {
                        ok = false;
                        break;
                    }
                }

                if ok {
                    for k in 0..h {
                        u[k][pos] = t[k][i];
                        u[k][w - 1 - pos] = t[k][j];
                    }
                    pos += 1;
                    used[i] = true;
                    used[j] = true;
                    break;
                }
            }
            if !used[i] {
                if w % 2 == 0 { return false; }
                if u[0][w / 2] != ' ' { return false; }
                for k in 0..h {
                    u[k][w / 2] = t[k][i];
                    if t[k][i] != t[h - 1 - k][i] { return false; }
                }
            }
        }

        return true;
    }

    let turn = rows.len();
    for i in 0..h {
        if used[i] || skip[turn][i] { continue; }
        used[i] = true;
        skip[h - 1 - turn][i] = true;
        rows.push(i);
        if rec(used, rows, skip, s) { return true; };
        rows.pop();
        used[i] = false;
    }

    return false;
}

struct Scanner {
    ptr: usize,
    length: usize,
    buf: Vec<u8>,
    small_cache: Vec<u8>,
}

impl Scanner {
    fn new() -> Scanner {
        Scanner { ptr: 0, length: 0, buf: vec![0; 1024], small_cache: vec![0; 1024] }
    }

    fn load(&mut self) {
        use std::io::Read;
        let mut s = std::io::stdin();
        self.length = s.read(&mut self.buf).unwrap();
    }

    fn byte(&mut self) -> u8 {
        if self.ptr >= self.length {
            self.ptr = 0;
            self.load();
            if self.length == 0 {
                self.buf[0] = b'\n';
                self.length = 1;
            }
        }

        self.ptr += 1;
        return self.buf[self.ptr - 1];
    }

    fn is_space(b: u8) -> bool { b == b'\n' || b == b'\r' || b == b'\t' || b == b' ' }

    fn read<T>(&mut self) -> T where T: std::str::FromStr, T::Err: std::fmt::Debug, {
        let mut b = self.byte();
        while Scanner::is_space(b) {
            b = self.byte();
        }

        for pos in 0..self.small_cache.len() {
            self.small_cache[pos] = b;
            b = self.byte();
            if Scanner::is_space(b) {
                return String::from_utf8_lossy(&self.small_cache[0..(pos + 1)]).parse().unwrap();
            }
        }

        let mut v = self.small_cache.clone();
        while !Scanner::is_space(b) {
            v.push(b);
            b = self.byte();
        }
        return String::from_utf8_lossy(&v).parse().unwrap();
    }
}

use proconio::input;

fn generate_even_pairings(n: usize) -> Vec<Vec<(usize, usize)>> {
    assert!(n % 2 == 0);

    fn dfs(ckd: &mut [bool], now: &mut Vec<(usize, usize)>, ans: &mut Vec<Vec<(usize, usize)>>) {
        if 2 * now.len() == ckd.len() {
            ans.push(now.clone());
            return;
        }
        let i = ckd
            .iter()
            .copied()
            .enumerate()
            .find(|&(_, b)| !b)
            .unwrap()
            .0;
        ckd[i] = true;
        for j in 0..ckd.len() {
            if ckd[j] {
                continue;
            }
            ckd[j] = true;
            now.push((i, j));
            dfs(ckd, now, ans);
            now.pop();
            ckd[j] = false;
        }
        ckd[i] = false;
    }

    let mut ckd = vec![false; n];
    let mut now = vec![];
    let mut ans = vec![];

    dfs(&mut ckd, &mut now, &mut ans);

    ans
}

fn convert_to_permutation(pairs: Vec<(usize, usize)>) -> Vec<usize> {
    let n = pairs.len() * 2;
    let mut seq = vec![0; n];
    for (i, (x, y)) in pairs.into_iter().enumerate() {
        seq[i] = x;
        seq[n - 1 - i] = y;
    }
    seq
}

fn generate_representitve_parmutations(n: usize) -> Vec<Vec<usize>> {
    if n % 2 == 0 {
        generate_even_pairings(n)
            .into_iter()
            .map(convert_to_permutation)
            .collect()
    } else {
        (0..n)
            .map(|center| {
                generate_even_pairings(n - 1)
                    .into_iter()
                    .map(convert_to_permutation)
                    .map(move |mut seq| {
                        for x in &mut seq {
                            if center <= *x {
                                *x += 1;
                            }
                        }
                        seq.insert(n / 2, center);
                        seq
                    })
            })
            .flatten()
            .collect()
    }
}

fn main() {
    input!(h: usize, w: usize, v: [proconio::marker::Chars; h]);
    let ans = generate_representitve_parmutations(w).iter().any(|seq| {
        let mut v: Vec<Vec<char>> = v
            .iter()
            .map(|s| {
                let mut ret = vec!['$'; w];
                for (i, &x) in seq.iter().enumerate() {
                    ret[i] = s[x];
                }
                ret
            })
            .collect();

        loop {
            if v.len() <= 1 {
                return v.is_empty() || v[0] == v[0].iter().copied().rev().collect::<Vec<char>>();
            }
            if let Some((i, j)) = (0..v.len())
                .map(|i| {
                    let s = &v[i];
                    let t: &Vec<_> = &s.iter().copied().rev().collect();
                    if let Some(j) = v
                        .iter()
                        .enumerate()
                        .skip(i + 1)
                        .find(|&(_, u)| t == u)
                        .map(|p| p.0)
                    {
                        Some((i, j))
                    } else {
                        None
                    }
                })
                .filter_map(std::convert::identity)
                .next()
            {
                assert!(i < j);
                v.remove(j);
                v.remove(i);
            } else {
                return false;
            }
        }
    });
    println!("{}", if ans { "YES" } else { "NO" });
}

