fn detect(s: &Vec<Vec<char>>) -> bool {
    let h = s.len();
    let w = s[0].len();
    let mut used = vec![false; w];
    let mut centor = false;
    for i in 0..w {
        if used[i] {
            continue;
        }
        for j in (i + 1)..w {
            if used[j] {
                continue;
            }
            let mut ok = true;
            for k in 0..h {
                if s[k][i] != s[h - 1 - k][j] {
                    ok = false;
                }
            }
            if ok {
                used[i] = true;
                used[j] = true;
                break;
            }
        }
        if !used[i] {
            if centor {
                return false;
            }
            for k in 0..h {
                if s[k][i] != s[h - 1 - k][i] {
                    return false;
                }
            }
            centor = true;
            used[i] = true;
        }
        if !used[i] {
            return false;
        }
    }
    true
}

fn calc(s: &mut Vec<Vec<char>>, k: usize, used: bool) -> bool {
    let h = s.len();
    if k >= h / 2 {
        return detect(&s);
    }
    for i in (k + 1)..(h - k) {
        if h % 2 == 1 && used && i == h / 2 {
            continue;
        }
        s.swap(h - 1 - k, i);
        if calc(s, k + 1, used) {
            return true;
        }
        s.swap(h - 1 - k, i);
    }
    let w = s[k].len();
    for i in 0..w {
        if s[k][i] != s[k][w - 1 - i] {
            return false;
        }
    }
    if !used && h % 2 == 1 {
        s.swap(h / 2, k);
        if calc(s, k + 1, true) {
            return true;
        }
        s.swap(h / 2, k);
    }
    false
}

fn run() {
    input! {
        h: usize,
        _w: usize,
        s: [chars; h],
    }
    let mut s = s;
    if calc(&mut s, 0, false) {
        println!("YES");
    } else {
        println!("NO");
    }
}

