fn rec(used: &mut Vec<bool>,
       rows: &mut Vec<usize>,
       s: &Vec<Vec<char>>,
       count: usize) -> bool {
    let h = s.len();

    if count == h {
        return check(rows, s);
    }

    for i in 0..h {
        if used[i] { continue; }
        used[i] = true;
        rows[count] = i;
        if rec(used, rows, s, count + 1) { return true; };
        used[i] = false;
    }

    return false;
}

fn check(rows: &Vec<usize>, s: &Vec<Vec<char>>) -> bool {
    let h = s.len();
    let w = s[0].len();
    let mut centered = false;
    let mut used = vec![false; w];
    for i in 0..w {
        if used[i] { continue; }
        for j in (i + 1)..w {
            if used[i] { continue; }

            let mut ok = true;
            for k in 0..h {
                if s[rows[k]][i] != s[rows[h - 1 - k]][j] {
                    ok = false;
                    break;
                }
            }

            if ok {
                used[i] = true;
                used[j] = true;
                break;
            }
        }
        if !used[i] {
            if w % 2 == 0 { return false; }
            if centered { return false; }
            centered = true;
            for k in 0..h {
                if s[rows[k]][i] != s[rows[h - 1 - k]][i] { return false; }
            }
        }
    }

    return true;
}

