fn solve(s: &Vec<Vec<char>>, rows: &mut Vec<usize>, used: &mut Vec<bool>, pos: usize) -> bool {
    let h = rows.len();
    if pos == h / 2 {
        if h % 2 == 0 {
            return check(s, rows);
        } else {
            for i in 0..h {
                if !used[i] {
                    rows[pos] = i;
                    break;
                }
            }
            return check(s, rows);
        }
    }

    for i in 0..h {
        if used[i] {
            continue;
        }
        used[i] = true;
        for j in (i + 1)..h {
            if used[j] {
                continue;
            }
            used[j] = true;

            rows[pos] = i;
            rows[h - 1 - pos] = j;
            if solve(s, rows, used, pos + 1) {
                return true;
            }

            used[j] = false;
        }
        used[i] = false;
    }

    return false;
}

fn check(s: &Vec<Vec<char>>, rows: &Vec<usize>) -> bool {
    let h = rows.len();
    let w = s[0].len();
    let mut used = vec![false; w];
    for c1 in 0..w {
        if used[c1] {
            continue;
        }
        for c2 in (c1 + 1)..w {
            if used[c2] {
                continue;
            }
            let mut ok = true;
            for i in 0..h {
                let cl = s[rows[i]][c1];
                let cr = s[rows[h - 1 - i]][c2];
                if cl != cr {
                    ok = false;
                    break;
                }
            }
            if ok {
                used[c1] = true;
                used[c2] = true;
                break;
            }
        }
    }

    let mut already_checked = false;
    for c in 0..w {
        if used[c] {
            continue;
        }
        if already_checked {
            return false;
        }
        already_checked = true;
        for i in 0..h {
            if s[rows[i]][c] != s[rows[h - 1 - i]][c] {
                return false;
            }
        }
    }

    return true;
}

