fn rec(s: &Vec<Vec<char>>, used: &mut Vec<bool>, rows: &mut Vec<usize>) -> bool {
    if rows.len() == s.len() {
        return true;
    }
    let h = s.len();
    for i in 0..h {
        if used[i] { continue; }
        rows.push(i);
        used[i] = true;

        let check = if rows.len() > (h + 1) / 2 {
            let w = s[0].len();
            let mut up = Vec::new();
            let mut down = Vec::new();
            for col in 0..w {
                let mut u = Vec::new();
                let mut d = Vec::new();
                if h % 2 == 0 {
                    let center = h / 2;
                    for i in 0..h {
                        if center + i >= rows.len() { break; }
                        u.push(s[rows[center - 1 - i]][col]);
                        d.push(s[rows[center + i]][col]);
                    }
                } else {
                    let center = h / 2;
                    for i in 1..h {
                        if center + i >= rows.len() { break; }
                        u.push(s[rows[center - i]][col]);
                        d.push(s[rows[center + i]][col]);
                    }
                }
                up.push(u);
                down.push(d);
            }
            up.sort();
            down.sort();

            let mut ok = true;
            for col in 0..w {
