use proconio::input;

fn generate_even_pairings(n: usize) -> Vec<Vec<(usize, usize)>> {
    assert!(n % 2 == 0);

    fn dfs(ckd: &mut [bool], now: &mut Vec<(usize, usize)>, ans: &mut Vec<Vec<(usize, usize)>>) {
        if 2 * now.len() == ckd.len() {
            ans.push(now.clone());
            return;
        }
        let i = ckd
            .iter()
            .copied()
            .enumerate()
            .filter(|&(_, b)| !b)
            .next()
            .unwrap()
            .0;
        ckd[i] = true;
        for j in 0..ckd.len() {
            if ckd[j] {
                continue;
            }
            ckd[j] = true;
            now.push((i, j));
            dfs(ckd, now, ans);
            now.pop();
            ckd[j] = false;
        }
        ckd[i] = false;
    }

    let mut ckd = vec![false; n];
    let mut now = vec![];
    let mut ans = vec![];

    dfs(&mut ckd, &mut now, &mut ans);

    ans
}

fn convert_to_permutation(pairs: Vec<(usize, usize)>) -> Vec<usize> {
    let n = pairs.len() * 2;
    let mut seq = vec![0; n];
    for (i, (x, y)) in pairs.into_iter().enumerate() {
        seq[i] = x;
        seq[n - 1 - i] = y;
    }
    seq
}

fn generate_representitve_parmutations(n: usize) -> Vec<Vec<usize>> {
    if n % 2 == 0 {
        generate_even_pairings(n)
            .into_iter()
            .map(convert_to_permutation)
            .collect()
    } else {
        (0..n)
            .map(|center| {
                generate_even_pairings(n - 1)
                    .into_iter()
                    .map(convert_to_permutation)
                    .map(move |mut seq| {
                        for x in &mut seq {
                            if center <= *x {
                                *x += 1;
                            }
                        }
                        seq.insert(n / 2, center);
                        seq
                    })
            })
            .flatten()
            .collect()
    }
}

fn main() {
    input!(h: usize, w: usize, v: [proconio::marker::Chars; h]);
    println!(
        "{}",
        if generate_representitve_parmutations(w).iter().any(|seq| {
            // eprintln!("{:?}", seq);
            let mut v: Vec<_> = v
                .iter()
                .map(|s| {
                    let mut ret = vec!['$'; w];
                    for (i, &x) in seq.iter().enumerate() {
                        ret[i] = s[x];
                    }
                    ret
                })
                .filter(|s| *s != s.iter().copied().rev().collect::<Vec<_>>())
                .collect();
            // eprintln!("{:?}", &v);

            while !v.is_empty() {
                let s = &v[0];
                let t: &Vec<_> = &s.iter().copied().rev().collect();
                if let Some(i) = v.iter().enumerate().find(|&(_, u)| t == u).map(|p| p.0) {
                    assert_ne!(0, i);
                    v.remove(i);
                    v.remove(0);
                } else {
                    return false;
                }
            }
            true
        }) {
            "YES "
        } else {
            "NO "
        }
    );
}

