fn compare_sets(ss: &Vec<String>) -> bool {
    let mut list: Vec<usize> = Vec::new();

    for (i1, s1) in ss.iter().enumerate() {
        if list.contains(&i1) {
            continue;
        }
        for (i2, s2) in ss.iter().enumerate() {
            if i1 == i2 {
                continue;
            } else if list.contains(&i2) {
                continue;
            } else if set_compare_eq(s1, s2) {
                list.push(i1);
                list.push(i2);
                break;
            }
        }
    }
    ss.len() - list.len() == 0 || ss.len() - list.len() == 1
}

fn set_compare_eq(s1: &String, s2: &String) -> bool {
    for c in s1.chars() {
        if !s2.contains(c) {
            return false;
        }
    }
    true
}

fn read<T: std::str::FromStr>() -> T {
